P.entries["quest:2160"] = {n="塔诺克的补给品",s="“交给塔诺克的补给品”是一项委托给初出茅庐的冒险者的任务，他们将离开寒脊山谷，穿过危险的山间小径，进入更为广阔的丹莫罗。侏儒修补匠汉兹·跳链需要将一箱必需的补给品送给卡拉诺斯雷酒酿制厂旅店的塔诺克·霜锤，以此绕过那些阻断了常规贸易、到处都是穴居人的小径。",h="“交给塔诺克的补给品”是一项委托给初出茅庐的冒险者的任务，他们将离开寒脊山谷，穿过危险的山间小径，进入更为广阔的丹莫罗。侏儒修补匠汉兹·跳链需要将一箱必需的补给品送给卡拉诺斯雷酒酿制厂旅店的塔诺克·霜锤，以此绕过那些阻断...",kw={"安威玛尔","寒脊山小径","汉兹·跳链","卡拉诺斯","交给塔诺克的补给品","塔诺克·霜锤","雷酒","穴居人"},ang={["faction:Alliance"]="尽管有凶猛的穴居人入侵，恢复孤立前哨站之间的贸易依然能让铁炉堡的内陆补给线保持畅通。",["race:Dwarf"]="将补给品从安威玛尔运送到卡拉诺斯，标志着你完成了走出庇护山谷的成年礼，开始为更广阔的铁炉堡王国效力。",["race:Gnome"]="帮助汉兹·跳链展现了诺莫瑞根流亡者与他们在丹莫罗的矮人东道主之间可靠的合作关系。"},sec={{t="被封锁的山谷",b="寒脊山谷一直是年轻的铁炉堡矮人和诺莫瑞根流亡者幸存者的试炼场与避难所，但最近发生的事件导致其与丹莫罗其他地区的联系变得紧张。穴居人的入侵淹没了寒脊山小径，使得这条山路变得危机四伏。山地巡逻队员们为了守卫定居点和防御周界已经分身乏术，导致原本计划好的补给护送任务一再延误。"},{t="汉兹与旅店老板的助手",b="汉兹·跳链，一位在寒脊山小径入口处等待的侏儒，发现自己手中有一箱运往卡拉诺斯的重要旅店补给品，却苦于没有安全的方式亲自运送。他意识到勇敢的冒险者们正准备闯过这条危险的小径，便征募了这些外出的旅行者，将货物带给在繁忙的雷酒旅店工作的助手塔诺克·霜锤。"},{t="卡拉诺斯温馨的炉火",b="到达卡拉诺斯标志着冒险者正式进入了更为广阔的丹莫罗世界。塔诺克·霜锤急切地收下了这批货物，并提到自从穴居人阻断了这条山路后，安威玛尔的消息就变得非常匮乏。运送这些物资恢复了这两个孤立的矮人社区之间脆弱的通讯和贸易往来。"}},faq={{q="汉兹·跳链是谁？",a="汉兹·跳链是一位驻扎在寒脊山谷寒脊山小径入口处的进取心十足的侏儒。由于无法独自穿过危险的山间小径，他依靠有能力的旅行者将货物运往卡拉诺斯。",al={"汉兹·跳链","任务发布者","谁把补给品交给塔诺克"}},{q="塔诺克·霜锤是谁？",a="塔诺克·霜锤是卡拉诺斯雷酒酿制厂的一位旅店助理。他协助管理当地酒馆的物流，并负责接收来自安威玛尔等前哨站运送来的补给品。",al={"塔诺克","塔诺克·霜锤","卡拉诺斯旅店助理"}},{q="为什么汉兹不能亲自运送补给品？",a="连接寒脊山谷和卡拉诺斯的小径已被敌对的穴居人占领。汉兹没有装备来独自杀出一条血路，而官方的山地巡逻队护送任务也严重延误了。",al={"为什么汉兹不能运送补给品","为什么需要冒险者","为什么小径危险"}},{q="卡拉诺斯的旅店在哪里？",a="塔诺克·霜锤位于雷酒酿制厂内，这是一家大型旅店，位于卡拉诺斯的中心，紧邻通往东面铁炉堡的主干道。",al={"塔诺克在哪里","雷酒酿制厂位置","卡拉诺斯旅店位置"}},{q="一箱旅店补给品里有什么？",a="这个箱子里装满了在安威玛尔收集的必要酒馆杂货和补给品，用于补充卡拉诺斯雷酒旅店的库存。",al={"箱子里装了什么","一箱旅店补给品"}},{q="为什么安威玛尔和卡拉诺斯之间的通讯中断了？",a="从地下隧道涌出的穴居人淹没了寒脊山小径。它们咄咄逼人的存在切断了寒脊山谷与丹莫罗其他地区之间便捷的步行路线和定期的派遣往来。",al={"为什么安威玛尔消息匮乏","小径的穴居人问题"}}},fp="18,195,18.238.0,35.206.0,30.232.0,28.192.0,26.136.0,45.193.0,37.129.0,41.104.0,59.178.0"}
P.entries["quest:2161"] = {n="苦工的重担",s="“苦工的重担”是一项入门级的递送任务，由乌克尔发布，他是一位焦虑的兽人劳工，被困在试炼谷外的道路上。在试图向并不需要补给的新兵运送物资后，乌克尔委托路过的旅者将这沉重的货物安全送回剃刀岭。",h="“苦工的重担”是一项入门级的递送任务，由乌克尔发布，他是一位焦虑的兽人劳工，被困在试炼谷外的道路上。在试图向并不需要补给的新兵运送物资后，乌克尔委托路过的旅者将这沉重的货物安全送回剃刀岭。",kw={"杜隆塔尔","食物","旅店老板格罗斯克","苦工","剃刀岭","补给","乌克尔","试炼谷"},ang={["faction:Horde"]="这段路程是走出试炼场的过渡，引导旅者前往剃刀岭，那里是杜隆塔尔南部部落防御和后勤的中心枢纽。",["race:Orc"]="兽人文化崇尚体能与勇气，这使得像乌克尔这样的苦工处于社会等级的最底层；承担他的差事向人们展示了即使是卑微的劳作，也能让杜隆塔尔这个新兴国家正常运转。"},sec={{t="误送的货物",b="乌克尔是一位诚恳的苦工，他怀着好意从剃刀岭出发，拖着沉重的补给包前往试炼谷。他认为在红色峡谷中训练的新兵急需口粮，于是冒险上路，结果却被拒之门外。负责监督试炼的训练师故意让补给保持在匮乏水平——正如旅店老板格罗斯克后来指出的那样，靠微薄的口粮生存被视为磨练年轻部落勇士纪律和耐力的一种方式。"},{t="红色荒原的危险",b="虽然他设法到达了山口，但乌克尔却被要在杜隆塔尔那被烈日炙烤的土地上原路返回的恐惧所笼罩。沿途的岩壁上挤满了具有攻击性的蝎子、毒蜘蛛和徘徊的野猪。这位受惊的劳工既没有武器、盔甲，也不具备兽人步兵应有的战斗精神，他只能守在路边，恳求任何离开试炼场、路过的冒险者帮他扛起重担，送回旅店。"}},faq={{q="乌克尔是谁？",a="乌克尔是一位驻扎在通往试炼谷道路上的兽人苦工。他心地善良但性格胆怯，从剃刀岭出发去运送补给，后来意识到自己太害怕当地的野生生物，无法独自踏上归途。",al={"乌克尔","路上的苦工是谁","试炼谷附近的苦工"}},{q="为什么试炼谷的训练师不要这些食物？",a="试炼谷的监督者们相信对新兵进行严格的纪律训练。正如旅店老板格罗斯克幽默地指出的那样，教官们更愿意让受训者保持饥饿以考验他们的勇气并磨练意志，这使得乌克尔的一片好心成了多余。",al={"为何拒收食物","乌克尔为何搬运食物","旅店老板格罗斯克与饥饿训练"}},{q="这份货物需要送到哪里？",a="这份货物必须沿着杜隆塔尔的主干道向北运送至剃刀岭，并交给位于营地旅店内的旅店老板格罗斯克。",al={"剃刀岭在哪里","我该把食物交给谁","乌克尔的货物送到哪里"}},{q="是什么让苦工的旅程变得危险？",a="杜隆塔尔的岩石荒原上到处都是领地意识极强的蝎子、毒爬蛛和野猪。虽然经验丰富的新兵可以对付这些害虫，但像乌克尔这样没有盔甲、未经训练的劳工一旦被袭击，几乎毫无生还希望。",al={"乌克尔为何害怕","杜隆塔尔路上的危险"}},{q="苦工在部落中的角色是什么？",a="苦工处于兽人社会的底层，负责搬运补给、砍伐木材和建造防御工事等琐碎劳作。虽然步兵和勇士们能获得赞美与荣耀，但苦工们尽管让营地得以维持和运转，却常常被人们所忽视。",al={"兽人苦工背景资料","苦工的地位","什么是苦工"}},{q="旅店老板格罗斯克是谁？",a="旅店老板格罗斯克经营着剃刀岭的旅店。他管理着城镇的住宿和补给，为路过的勇士提供食物、饮料和温暖的壁炉，并提醒新兵在面对更广阔的世界之前，休息至关重要。",al={"旅店老板格罗斯克","格罗斯克与剃刀岭","剃刀岭旅店老板"}}},fp="15,197,20.356.0,23.352.0,12.235.0,62.210.0,36.141.0,44.180.0,39.273.0,23.207.0"}
P.entries["quest:217"] = {n="保卫国王的领土",s="“保卫国王领地”的任务最终将演变成对洛克莫丹穴居人入侵者首领的直接打击。矮人侦察兵追踪到了这起暴力入侵事件的源头，发现碎石怪之谷深处盘踞着格拉姆格酋长及其残暴的保镖。拉格弗斯上尉委派勇敢的联盟冒险者去击杀这位酋长，以粉碎穴居人的士气并收复王国的南部边境。",h="“保卫国王领地”的任务最终将演变成对洛克莫丹穴居人入侵者首领的直接打击。矮人侦察兵追踪到了这起暴力入侵事件的源头，发现碎石怪之谷深处盘踞着格拉姆格酋长及其残暴的保镖。拉格弗斯上尉委派勇敢的联盟冒险者去击杀这位酋长，以粉碎...",kw={"布劳勒","格纳舍","格拉姆格","国王领地","洛克莫丹","拉格弗斯","碎石怪","穴居人"},ang={["faction:Alliance"]="保卫洛克莫丹可以维护铁炉堡与东部边境之间至关重要的陆路连接，确保所有联盟部队的补给线安全。",["race:Dwarf"]="对于矮人而言，将穴居人从卡兹莫丹古老的土地上赶走是保卫家园与荣誉的问题，确保山堡不被地下灾祸所玷污。"},sec={{t="斩首虫群",b="在洛克莫丹南部肆虐的穴居人威胁已经不仅仅是随机的地下爬行生物骚扰了。拉格弗斯上尉的侦察兵发现，碎石怪穴居人在一个名叫格拉姆格的酋长的粗暴指挥下行动。与通常四散的掠夺者不同，这群穴居人展现出了协同一致的侵略性，如果不加以遏制，它们可能会践踏国王的领地。通过深入它们的巢穴，将格拉姆格及其私人打手一并处决，矮人守卫希望能够瓦解这群怪物的凝聚力并扭转局势。"},{t="深入碎石怪巢穴",b="格拉姆格盘踞在碎石怪之谷东南部悬崖内的一个阴暗洞穴中。在它最信任的打手——格纳舍和布劳勒——的簇拥下，这位酋长对孤身冒险者构成了巨大的挑战。击杀这个核心集团将迫使剩余的穴居人陷入混乱，从而为处境艰难的登山者们争取到宝贵的机会，以便他们能够加固道路并将这些野兽赶回黑暗的深渊。"}},faq={{q="谁是格拉姆格？",a="格拉姆格是那名邪恶的穴居人酋长，他正集结洛克莫丹南部的碎石怪穴居人发动攻击。矮人侦察兵确认他就是骚扰山谷的组织化袭击背后的主谋，他的身边时刻带着两名强大的保镖：格纳舍和布劳勒。",al={"格拉姆格背景故事","穴居人首领是谁","格拉姆格酋长"}},{q="格拉姆格和他的守卫在哪里？",a="格拉姆格、格纳舍和布劳勒都在洛克莫丹碎石怪之谷东南边缘的一个洞穴中安营扎寨。他们共同居住在洞穴深处。",al={"格拉姆格位置","格拉姆格在哪里","格拉姆格怎么找"}},{q="谁是拉格弗斯上尉？",a="拉格弗斯上尉是驻扎在洛克莫丹南部岗哨的矮人军官。他负责监督针对穴居人入侵的防御行动，并发布保护国王领地领土完整的命令。",al={"拉格弗斯","拉格弗斯上尉职责","谁发布保卫国王领地的任务"}},{q="为什么格拉姆格的保镖也必须被击杀？",a="格纳舍和布劳勒是格拉姆格的私人打手，从不离他左右。要消灭这位酋长并彻底粉碎穴居人攻势的领导核心，必须将这两名强大的守卫与他们的头领一起击败。",al={"为什么击杀格纳舍和布劳勒","格纳舍和布劳勒","格拉姆格保镖"}},{q="格拉姆格被消灭后会发生什么？",a="击杀格拉姆格将为洛克莫丹带来至关重要的缓解。失去了指挥突袭的酋长，碎石怪穴居人将失去组织性，这将使当地的矮人民兵有机会守住边境，并将这些野兽赶回地下。",al={"击杀格拉姆格的结果","格拉姆格死后穴居人会怎样","洛克莫丹安全了吗"}},{q="为什么穴居人会入侵洛克莫丹？",a="穴居人长期以来一直在卡兹莫丹地下的地穴中滋生。挖掘工作和未封闭的洞穴让它们能够涌上地表，肆意驱逐定居点并攻击国王道路上的旅客。",al={"为什么这里有穴居人","洛克莫丹穴居人入侵","碎石怪穴居人起源"}}},fp="30,250,22.286.0,23.351.0,15.197.0,41.112.0,25.194.0,43.148.0,41.255.1,35.209.0"}
P.entries["quest:2178"] = {n="炖陆行鸟",s="“简单的陆行鸟生活”是奥伯丁的奥兰达利亚·夜歌提供的一项当地烹饪任务。如果冒险者愿意在黑海岸狩猎那些凶猛的森林陆行鸟并取回它们的肉，她很乐意分享她那珍贵的炖陆行鸟食谱。",h="“简单的陆行鸟生活”是奥伯丁的奥兰达利亚·夜歌提供的一项当地烹饪任务。如果冒险者愿意在黑海岸狩猎那些凶猛的森林陆行鸟并取回它们的肉，她很乐意分享她那珍贵的炖陆行鸟食谱。",kw={"奥兰达利亚·夜歌","奥伯丁","烹饪","黑海岸","简单的陆行鸟生活","森林陆行鸟","陆行鸟肉","炖陆行鸟"},ang={["class:Hunter"]="森林陆行鸟既是敏捷的猎物，也可能是潜在的动物伙伴，在黑海岸雾气弥漫的小径上提供了追踪和狩猎的练习。",["profession:Cooking"]="对于在黑海岸旅行的烹饪者来说，这项任务至关重要，它奖励使用当地野生生物制作营养丰富的炖陆行鸟的食谱。",["race:NightElf"]="在卡利姆多和谐地生活通常意味着靠山吃山，而丰盛的炖陆行鸟已经成为奥伯丁暗夜精灵的一种沿海主食。"},sec={{t="荒野之味",b="奥伯丁或许是一个安静的港口村庄，但在海岸边生存需要善用当地的野生生物。奥兰达利亚·夜歌研制出了一种丰盛的炖陆行鸟秘制食谱，这道美味佳肴的原料来自于那些在黑海岸阴暗树林中潜行的身材高大、行动敏捷的森林陆行鸟。她并没有直接传授烹饪秘诀，而是让有志于成为厨师和猎人的冒险者亲自前往狩猎这些鸟类。"},{t="狩猎森林陆行鸟",b="森林陆行鸟是敏捷、长着锋利喙的禽类掠食者，它们漫游在奥伯丁南北两侧那雾气笼罩的林地和海滩上。虽然它们在受到挑衅时会变得暴躁且具有攻击性，但它们多汁的肉是制作浓郁炖菜的绝佳基础。带回新鲜的肉不仅能填满奥兰达利亚那饥渴的炖锅，还能为猎人赢得她珍视的食谱。"}},faq={{q="奥兰达利亚·夜歌是谁？",a="奥兰达利亚·夜歌是一位居住在黑海岸奥伯丁的暗夜精灵。她以那锅咕嘟作响的炖陆行鸟而闻名，并主动提出向展现出狩猎实力的旅行者传授她的烹饪技艺。",al={"奥兰达利亚","奥兰达利亚·夜歌是谁","炖菜 厨师 奥伯丁"}},{q="我在哪里可以找到陆行鸟肉？",a="陆行鸟肉是通过在整个黑海岸狩猎森林陆行鸟获得的。这些不会飞的大型鸟类在奥伯丁之外的沙滩海岸线和森林树丛中漫游。",al={"陆行鸟肉位置","森林陆行鸟在哪里","如何获得陆行鸟肉"}},{q="这个任务的目的是什么？",a="该任务要求你狩猎森林陆行鸟，为奥兰达利亚·夜歌带回五块肉，以换取学习烹饪炖陆行鸟的方法。",al={"为什么要完成简单的陆行鸟生活","任务目的","简单的陆行鸟生活目标"}},{q="森林陆行鸟狩猎起来危险吗？",a="森林陆行鸟是具有领地意识的鸟类，长着锋利的喙且双腿敏捷，这使得它们在被接近时具有攻击性。然而，一个装备合理的冒险者可以在没有太大危险的情况下猎杀它们。",al={"陆行鸟难杀吗","森林陆行鸟危险"}},{q="这个任务会解锁烹饪食谱吗？",a="是的。在给奥兰达利亚带回她要求的肉后，她会分享她的烹饪秘诀，教冒险者制作炖陆行鸟的食谱。",al={"我能得到食谱吗","炖陆行鸟食谱","烹饪奖励"}},{q="这个任务在哪里进行？",a="任务在奥伯丁定居点开始和结束，狩猎活动则在黑海岸的荒野中进行。",al={"任务区域","简单的陆行鸟生活在哪里"}}},fp="19,122,19.279.0,26.253.0,29.143.0,33.137.0,34.129.0,41.105.0,40.94.0,33.72.0"}
P.entries["quest:218"] = {n="被窃取的日记",s="“被窃的日记”是丹莫罗的一项早期联盟任务，格瑞林·白须委托冒险者进入寒脊山谷的巨魔洞穴，找回他被窃的笔记。为了找回它，你必须击败强大的巨魔首领格里克尼尔。找回日记后，格瑞林就能完成他对寒脊山谷内巨魔威胁的评估了。",h="“被窃的日记”是丹莫罗的一项早期联盟任务，格瑞林·白须委托冒险者进入寒脊山谷的巨魔洞穴，找回他被窃的笔记。为了找回它，你必须击败强大的巨魔首领格里克尼尔。找回日记后，格瑞林就能完成他对寒脊山谷内巨魔威胁的评估了。",kw={"寒脊山谷","丹莫罗","霜鬃巨魔要塞","霜鬃巨魔","格瑞林·白须","格里克尼尔","森内尔·白须","被窃的日记"},ang={["faction:Alliance"]="压制具有侵略性的霜鬃部族，确保了丹莫罗的初始山谷免受内部破坏的影响。",["race:Dwarf"]="扫除寒脊山谷中霜鬃部族的领导层，保护了走出安威玛尔、踏出第一步的年轻矮人新兵。",["race:Gnome"]="在安威玛尔避难的侏儒难民依赖寒脊山谷通道的安全性，以便在矮人领地内重新集结。"},sec={{t="学者遗失的笔记",b="格瑞林·白须一直在观察侵扰寒脊山谷的霜鬃巨魔，并详细记录下它们的习性和突发的侵略行为。在动乱期间，一个极其强壮的巨魔偷走了他的私人日记，并退回了它们巢穴的深处。对于格瑞林来说，这次丢失不仅仅是情感上的损失；笔记本中包含了他大部分的侦察记录，导致他的正式评估工作在找回日记前不得不停滞不前。"},{t="直面格里克尼尔",b="偷走日记的那个野蛮家伙是格里克尼尔，一个强大的霜鬃巨魔。他的身体和脸上涂着独特的纹饰，盘踞在山谷巨魔洞穴的中心。击杀格里克尼尔可以粉碎该洞穴巨魔在当地的直接领导层，并夺回格瑞林的日记。除掉这个首领后，格瑞林感到很有把握报告说山谷的巨魔局势已经得到控制，并将他完成的调查结果寄给了他的兄弟森内尔。"}},faq={{q="是谁偷走了格瑞林·白须的日记？",a="日记是被格里克尼尔偷走的，这是一个巨大的霜鬃巨魔，他的皮肤和脸上有着奇怪的斑纹，潜伏在巨魔洞穴的深处。",al={"谁偷了日记","谁拿着格瑞林的日记","日记窃贼"}},{q="在哪里可以找到格里克尼尔？",a="格里克尼尔位于寒脊山谷南部的巨魔洞穴内。",al={"格里克尼尔在哪里","格里克尼尔的位置","如何找到格里克尼尔"}},{q="为什么这本日记对格瑞林很重要？",a="日记里记载了格瑞林·白须关于寒脊山谷巨魔活动的笔记和发现。他需要取回日记，以便为他的兄弟森内尔汇总一份完整的报告。",al={"格瑞林为什么要找回日记","格瑞林的日记里有什么"}},{q="归还日记后会发生什么？",a="一旦日记被找回，格瑞林就会完成他那份关于寒脊山谷巨魔局势的评估报告，并要求你将他的观察结果送到卡拉诺斯，转交给他的兄弟森内尔·白须。",al={"完成“被窃的日记”后接下来做什么","被窃的日记后续任务"}},{q="霜鬃巨魔在任务后被赶出寒脊山谷了吗？",a="格瑞林认为在击败格里克尼尔后，寒脊山谷的巨魔局势已得到控制，尽管霜鬃部族在丹莫罗更广阔的山路上依然是一个长期的威胁。",al={"寒脊山谷的巨魔被击败了吗","寒脊山谷是否没有巨魔威胁了"}},{q="森内尔·白须是谁？",a="森内尔·白须是格瑞林的兄弟，驻扎在寒脊山谷外靠近卡拉诺斯的一名联盟侦察兵，负责收集王国所面临的威胁情报。",al={"森内尔是谁","格瑞林的兄弟森内尔"}}},fp="18,225,22.369.0,29.364.0,37.154.0,37.87.0,39.145.0,42.180.1,67.172.0,24.160.0"}
P.entries["quest:219"] = {n="失踪人员",s="“失踪的士兵”是一个联盟护送任务，地点在赤脊山，目的是将基沙恩下士从黑石兽人的俘虏中解救出来。他的部队在山里被全歼后，基沙恩被打晕并拖进了一座洞穴要塞。将这位受伤的士兵安全带回湖畔镇，可以帮助当地驻军确认他们失踪士兵的悲惨命运。",h="“失踪的士兵”是一个联盟护送任务，地点在赤脊山，目的是将基沙恩下士从黑石兽人的俘虏中解救出来。他的部队在山里被全歼后，基沙恩被打晕并拖进了一座洞穴要塞。将这位受伤的士兵安全带回湖畔镇，可以帮助当地驻军确认他们失踪士兵的悲...",kw={"黑石兽人","基沙恩下士","护送任务","基沙恩","湖畔镇","治安官马瑞斯","失踪的士兵","赤脊山"},ang={["class:Warrior"]="将基沙恩从武装的兽人营地中救出，需要抵御一波又一波冷酷的黑石攻击者，同时还要保护脑部受创的战友。",["faction:Alliance"]="湖畔镇的驻军已紧绷到崩溃的边缘，这使得每一位获救的士兵对于王国抵御黑石氏族的防御战来说都至关重要。"},sec={{t="全军覆没",b="随着黑石兽人从北方的山峰蜂拥而下，赤脊山变得越来越危险。镇卫兵派出的巡逻队经常遭到伏击，而基沙恩下士的部队遭受了最惨重的损失。由于寡不敌众，他部队中的大多数士兵当场被杀。基沙恩之所以能活下来，只是因为在被处决前的一记重击让他昏了过去，兽人便把他拖回洞穴作为俘虏。"},{t="逃离洞穴",b="基沙恩遍体鳞伤、脑部受创，且被关在敌方领地的深处，他无法独自走下山。护送他前往湖畔镇的安全地带，需要穿过盘踞在山脊上蜂拥的兽人战团。活着回到湖畔镇让治安官马瑞斯感到一丝慰藉，他一直在设法拼凑失踪部队的遭遇，同时还要让湖畔镇做好抵御进一步袭击的准备。"}},faq={{q="谁是基沙恩下士？",a="基沙恩下士是一名驻扎在赤脊山的联盟步兵。在多岩石的山丘进行巡逻时，他的部队被黑石兽人压制，在被拖走关押之前，他是已知唯一的幸存者。",al={"基沙恩下士","基沙恩是谁","基沙恩背景故事"}},{q="基沙恩下士在哪里被俘的？",a="他被关押在赤脊山北部丘陵中一个兽人出没的洞穴深处，周围是敌对的黑石战士。",al={"基沙恩在哪里","基沙恩位置","基沙恩的洞穴"}},{q="基沙恩部队的其他成员遭遇了什么？",a="据基沙恩说，黑石兽人伏击并压制了他的部队，在最初的冲突中杀死了几乎所有人。",al={"基沙恩的小队","部队的遭遇","基沙恩的部下"}},{q="谁派玩家去营救基沙恩？",a="该任务直接由关押在洞穴里的基沙恩下士本人发布，联盟的冒险者发现并解救他时即可接到。",al={"谁发布失踪的士兵任务","任务发布者","如何接取失踪的士兵"}},{q="基沙恩被释放后去了哪里？",a="他必须被护送下山前往湖畔镇，在那里他会向镇子桥附近的治安官马瑞斯报告。",al={"失踪的士兵任务交付","基沙恩逃往何处","基沙恩的目的地"}},{q="为什么黑石兽人会在赤脊山？",a="黑石氏族从他们位于燃烧平原的据点向南推进到赤脊山，威胁着防御薄弱的湖畔镇聚居点，并伏击王国的巡逻队。",al={"赤脊山的黑石兽人","为什么湖畔镇有兽人","黑石入侵"}}},fp="17,266,18.422.0,21.374.0,24.210.0,36.129.0,44.106.0,36.101.0,40.132.0,39.178.0"}
P.entries["quest:22"] = {n="猪肝馅饼",s="血牙野猪的肝馅饼是为西部荒野萨丁农场的萨尔玛·萨丁完成的一项烹饪差事。随着王国的粮仓被强盗洗劫一空，当地农户只能依靠捕猎凶猛的本地野猪来为餐桌增添一道丰盛的佳肴。帮助萨尔玛能在这片凄凉的边境之地，带来一丝难得的舒适和家常般的款待。",h="血牙野猪的肝馅饼是为西部荒野萨丁农场的萨尔玛·萨丁完成的一项烹饪差事。随着王国的粮仓被强盗洗劫一空，当地农户只能依靠捕猎凶猛的本地野猪来为餐桌增添一道丰盛的佳肴。帮助萨尔玛能在这片凄凉的边境之地，带来一丝难得的舒适和家常...",kw={"野猪","烹饪","血牙野猪","肝馅饼","萨丁农场","萨尔玛·萨丁","西部荒野"},ang={["faction:Alliance"]="帮助像萨丁一家这样的农村农户，能直接支持那些在暴风城军队缺席的情况下，仍努力守护王国边境的忠诚人类家庭。",["profession:Cooking"]="萨尔玛的这道菜展现了传统的人类乡村烹饪技艺，使用大蒜、迷迭香和莳萝等园艺香料，将野味内脏提升为一道主食。"},sec={{t="边境的款待",b="西部荒野曾是暴风城肥沃的粮仓，但近年来境况不佳。由于基础设施缺乏维护、强盗横行以及农田荒废，仅存的定居者们生活日益艰难。在萨丁农场，萨尔玛·萨丁不辞辛劳，努力在日益逼近的威胁中守护着家的温馨。制作一份传统的肉馅饼，是那些试图保全生活方式的农户们所能享受到的为数不多的简单奢侈之一。"},{t="西部荒野的野兽",b="西部荒野的平原上到处都是血牙野猪，这种凶猛的野猪以皮糙肉厚和獠牙锋利而闻名。虽然它们对落单的农场工人来说很危险，但对那些与正常贸易隔绝的家庭来说，它们也是重要的肉食来源。萨尔玛的食谱需要仔细处理——加入碎迷迭香、蒜末、莳萝碎和炖肉汁——才能将这些强壮野兽的浓腥内脏变成一道香气四溢的盛宴。"}},faq={{q="谁是萨尔玛·萨丁？",a="萨尔玛·萨丁是一位坚韧的农妇，她和丈夫农夫萨丁住在位于西部荒野中部的农场里。她以擅长家常料理而闻名，尽管面临强盗和野兽的威胁，她依然竭尽全力保持乐观的精神。",al={"萨尔玛·萨丁","谁是萨尔玛","萨丁的妻子"}},{q="萨尔玛为什么需要血牙野猪的肝？",a="萨尔玛正在准备她那著名的鲜美肉馅饼，准备和丈夫一起享用。馅饼皮已经烤好了，调料也准备就绪，只需要当地血牙野猪的肝脏来完成馅料的炖煮。",al={"为什么需要血牙野猪的肝","馅饼的原料","肝馅饼的用途"}},{q="血牙野猪在西部荒野通常出现在哪里？",a="血牙野猪在西部荒野的金色平原和休耕的农田上四处游荡，它们在荒废的田地里翻找食物，并在土路上漫步。",al={"血牙野猪的位置","哪里能找到野猪","血牙野猪肝狩猎"}},{q="血牙野猪对当地农民有危险吗？",a="是的。血牙野猪是一种凶猛的领地型野猪，长有尖锐的獠牙。它们对平原上的牲畜和毫无防备的旅行者构成了重大威胁。",al={"血牙野猪是否具有敌意","西部荒野的野猪危险"}},{q="为什么西部荒野现在的食物如此短缺？",a="由于暴风城缺乏王室支持，加上有组织的强盗频繁劫掠，许多农民被迫背井离乡，使曾经的王国粮仓变成了贫困挣扎的边境之地。",al={"西部荒野饥荒","为什么西部荒野缺乏食物","西部荒野的艰难时期"}},{q="完成这项任务能帮助萨丁农场生存下去吗？",a="虽然这不能解决西部荒野面临的更广泛的危机，但收集新鲜肉类可以直接维持萨丁一家的生计，并为旅行者提供旅途所需的丰盛口粮。",al={"馅饼是否重要","萨丁农场的食物供应"}}},fp="18,193,20.355.0,23.358.0,21.204.0,36.226.0,48.136.0,45.169.0,44.207.0,56.147.0"}
P.entries["quest:220"] = {n="水之召唤",s="这段萨满祭司试炼的任务是让初学者将净化后的水带回贫瘠之地，交给水之先知伊斯伦。这瓶水由隐士Brine准备并祝福过，其中含有调制精神sapta所需的催化剂。一旦酿成，这种药剂将揭示居住在遥远银松森林水域中的元素之灵。",h="这段萨满祭司试炼的任务是让初学者将净化后的水带回贫瘠之地，交给水之先知伊斯伦。这瓶水由隐士Brine准备并祝福过，其中含有调制精神sapta所需的催化剂。一旦酿成，这种药剂将揭示居住在遥远银松森林水域中的元素之灵。",kw={"brine","call of water","水之先知伊斯伦","sapta","银松森林","贫瘠之地","一瓶最纯净的水","water sapta","水之图腾"},ang={["class:Shaman"]="每一位部落萨满祭司都必须完成Call of Water仪式，以与灵魂沟通并获得携带水之图腾的权利，该图腾掌管着治疗和补给。",["faction:Horde"]="这项试炼横跨卡利姆多和洛丹伦，展示了部落广阔的地理版图，年轻的初学者从贫瘠之地一路前往被遗忘者控制的银松森林。"},sec={{t="返回岸边",b="在穿越了南贫瘠之地并完成了Brine设下的试炼后，萨满祭司学徒将获得一瓶最纯净的水。这个容器中装满了来自纯净泉水的水，并经由Brine的隐居仪式所祝圣，代表了元素纯粹的潜力。将其安全地带回水之先知伊斯伦守望的东海岸，是连接Brine质朴智慧与正式图腾仪式的关键纽带。"},{t="sapta的用途",b="收到纯净的水后，水之先知伊斯伦解释说，凡人的眼睛无法轻易看到难以捉摸的水之灵。为了与它们沟通，初学者必须饮用一种被称为sapta的特制药水。从Brine那里带来的液体将成为这种药水强有力的基础，开启萨满祭司的感官，去察觉那些隐藏在凡人视线之外的力量。然而，正如水之先知伊斯伦所警告的那样，沟通仅仅是旅程的一半；灵魂本身还需要考验。"},{t="前往洛丹伦",b="水之先知伊斯伦透露，试炼的高潮不会在卡利姆多干燥的广袤土地上进行。相反，萨满祭司必须横跨大海，前往位于幽暗城以南、古老且迷雾笼罩的银松森林海岸。在那里，在这一座与世隔绝的神龛旁，必须喝下sapta，这样初学者才能直面元素生物，并获得显现水之图腾的权利。"}},faq={{q="一瓶最纯净的水里装着什么？",a="这瓶子里装着由初学者从纯净泉水中收集，并经由隐士Brine的仪式祝圣过的水。它代表了未受污染的元素之水，这是酿制与水之灵沟通所需的炼金sapta的关键。",al={"一瓶最纯净的水","brine的水","brine给了我什么"}},{q="谁是水之先知伊斯伦？",a="水之先知伊斯伦是一位居住在贫瘠之地东南偏远海岸线上（棘齿城以南）的年长萨满祭司。她是部落萨满祭司寻求与水元素沟通并获得水之图腾的主要导师。",al={"伊斯伦","谁是水之先知伊斯伦","水之先知伊斯伦的背景故事"}},{q="什么是sapta？",a="sapta是一种由萨满导师制作的仪式药剂。饮用后，它会改变饮用者的感知，使萨满祭司能够清晰地看到并与凡人视线中不可见的元素之灵互动。",al={"sapta的含义","water sapta","sapta有什么用"}},{q="为什么我接下来必须去银松森林？",a="与此次沟通有关的元素神龛位于东部王国幽暗城以南的银松森林沿海水域。居住在那里的灵魂在授予对其元素的掌控权之前，需要进行沟通和最终的考验。",al={"为什么去银松森林","银松森林的水之图腾","银松森林的神龛"}},{q="Brine住在哪里？",a="Brine住在南贫瘠之地山丘高处的一间僻静小屋里，位于通往升降梯和千针石林的道路以西。",al={"brine的位置","brine在哪里","寻找brine"}},{q="有萨满祭司可以跳过制作sapta的步骤吗？",a="不可以。沟通仪式要求萨满祭司的精神与不可见的世界保持协调。如果没有sapta所提供的感官桥梁，神龛处的水之灵就无法被呼唤或挑战。",al={"跳过sapta","需要sapta吗","萨满幻象任务"}}},fp="13,249,19.323.0,24.318.0,23.264.1,40.195.0,23.183.0,16.167.0,46.227.0,22.133.0,39.179.0"}
P.entries["quest:2205"] = {n="军情七处",s="“寻找军情七处”是科瑞恩·塞尔留斯在艾尔文森林为潜行者新手提供的入门任务。新手特工需要带着一个小包裹从闪金镇前往暴风城，并以此为契机拜见军情七处首领、国王秘密情报网络的核心人物马迪亚斯·肖尔大师。",h="“寻找军情七处”是科瑞恩·塞尔留斯在艾尔文森林为潜行者新手提供的入门任务。新手特工需要带着一个小包裹从闪金镇前往暴风城，并以此为契机拜见军情七处首领、国王秘密情报网络的核心人物马迪亚斯·肖尔大师。",kw={"闪金镇","科瑞恩·塞尔留斯","mathias shaw","old town","潜行者","寻找军情七处","军情七处","暴风城"},ang={["class:Rogue"]="这项任务标志着一名潜行者正式进入暴风城最高间谍机构服役，从街头小巷的伎俩转变为效力于王室的侦察工作。",["faction:Alliance"]="军情七处充当着王国的耳目，以应对内外威胁，在瓦里安·乌瑞恩国王失踪期间默默守护着王国。"},sec={{t="信使的考验",b="在闪金镇的Lion's Pride Inn里，潜行者训练师科瑞恩·塞尔留斯从不浪费时间去恭维新人。虽然她觉得这些新招募的菜鸟看起来更像是送奶酪的伙计，而不是能干的秘密特工，但她还是下达了一个跑腿任务：将一件密封的货物送往都城。这项任务既是一次可靠的信使工作，也是对那些希望效力于王国、更广阔的情报工作的斥候们进行的一场低调的审查。"},{t="旧城区的紧闭之门",b="目的地位于Old Town深处，这是暴风城中繁忙而古老的一个区域。在Old Town的东南角坐落着军情七处（SI:7）的Command Center——暴风城情报局第七分部。马迪亚斯·肖尔大师就在这里统筹王国的秘密行动。当他以其标志性的冷淡和怀疑态度接过包裹时，他也在评估这位旅行者是否具备进行真实间谍活动所需的胆识。"}},faq={{q="什么是军情七处？",a="军情七处（SI:7）即“暴风城情报局第七分部”。它是暴风城王国的秘密情报和隐秘行动部门，由马迪亚斯·肖尔大师从他们位于Old Town的总部进行领导。",al={"军情七处的意思","什么是军情七处","军情七处背景故事"}},{q="科瑞恩·塞尔留斯是谁？",a="科瑞恩·塞尔留斯是一位驻扎在闪金镇Lion's Pride Inn的潜行者训练师。她与军情七处保持联络，负责评估当地的招募人员，并将有潜力的斥候引荐给暴风城的马迪亚斯·肖尔大师。",al={"科瑞恩·塞尔留斯","闪金镇潜行者训练师"}},{q="马迪亚斯·肖尔在暴风城什么位置？",a="马迪亚斯·肖尔大师位于暴风城Old Town东南角的军情七处总部楼上，穿过该城的潜行者训练师区域即可到达。",al={"肖尔在哪","找到马迪亚斯·肖尔","马迪亚斯·肖尔位置"}},{q="把包裹交给肖尔之后会发生什么？",a="一旦你向马迪亚斯·肖尔报到，他会立即通过一项秘密行动来测试你的潜行者实战技能，让你前往杰罗德码头从一名迪菲亚码头管理员手中窃取一份Shipping Schedule。",al={"寻找军情七处之后的任务","肖尔想要什么"}},{q="为什么科瑞恩在交出货物前要嘲讽玩家？",a="军情七处特工以高超的能力和敏锐的直觉自豪。塞尔留斯对新兵表现严厉，旨在测试他们的脾性，确保只有那些脸皮够厚、意志坚定的人才能去打扰肖尔大师。",al={"为什么科瑞恩要侮辱我","奶酪递送侮辱"}}},fp="14,191,16.247.0,31.284.0,13.180.0,21.181.0,43.140.0,50.148.1,64.186.0"}
P.entries["quest:2206"] = {n="连偷带抢",s="“抓捕与夺取”是军情七处首领马迪亚斯·肖尔派给有潜力的潜行者的卧底任务。任务要求特工潜入杰罗德码头，从迪菲亚潜行者手中窃取船运情报。",h="“抓捕与夺取”是军情七处首领马迪亚斯·肖尔派给有潜力的潜行者的卧底任务。任务要求特工潜入杰罗德码头，从迪菲亚潜行者手中窃取船运情报。",kw={"水晶湖","迪菲亚","码头管理员","闪金镇","杰罗德码头","mathias shaw","shipping schedule","军情七处","抓捕与夺取"},ang={["class:Rogue"]="这项任务标志着潜行者正式加入军情七处，通过考验潜行和扒窃本能来赢得认可，并从马迪亚斯·肖尔那里获得一把标志性的匕首。",["faction:Alliance"]="在杰罗德码头拦截迪菲亚的补给链不仅保护了艾尔文森林，还削弱了威胁暴风城周边领土的犯罪集团。"},sec={{t="技艺的考验",b="对于暴风城中一位胸怀大志的特工来说，站在马迪亚斯·肖尔面前便是进入王国秘密情报机构的真正考验。肖尔要求的不是单纯的蛮力，而是精妙的技巧和潜行能力。在不引起王国公开丑闻的情况下悄无声息地解决关键人物并取回重要文件，这是军情七处的核心准则，而这项任务就是新人的试炼场。"},{t="河上的走私者",b="杰罗德码头坐落在艾尔文森林南部的河边，位于闪金镇以南，马科伦农场正东方。这里曾是一个安静的地方码头，但迪菲亚潜行者夺取了该地的控制权，并将其建立为一条非法的运输走廊。通过在水中转运走私的武器、补给品和违禁品，将它们从赤脊山运往西部荒野，这些盗贼完全绕过了王国的道路巡逻队。"},{t="合理的推诿",b="在派遣特工进入现场之前，肖尔明确传达了军情七处不成文的准则：如果特工被捕、身份暴露或被杀，王国及其情报首脑将否认对此人的任何知情权。找回迪菲亚码头管理员的时间表，既能获取迪菲亚潜行者补给线的关键证据，又能让暴风城的官方介入保持在阴影之中。"}},faq={{q="是谁发布了“抓捕与夺取”任务？",a="暴风城情报机构军情七处的首领马迪亚斯·肖尔在旧城区的军情七处总部内发布该任务。",al={"谁发布抓捕与夺取任务","抓捕与夺取任务发布者"}},{q="杰罗德码头在哪里？",a="杰罗德码头是位于艾尔文森林南部河流上的一个码头，在闪金镇以南，马科伦农场正东方。迪菲亚潜行者已经征用了那里的码头和码头房屋。",al={"杰罗德码头位置","杰罗德码头在哪里","码头管理员位置"}},{q="迪菲亚潜行者通过杰罗德码头走私什么？",a="迪菲亚潜行者利用杰罗德码头在赤脊山和西部荒野之间的水域运送大量的违禁品和补给品，从而绕过王国的岗哨和道路检查站。",al={"他们走私什么","迪菲亚违禁品"}},{q="谁携带着迪菲亚船运时间表？",a="船运时间表由迪菲亚码头管理员携带，他就在杰罗德码头的码头房屋旁守卫。",al={"船运时间表在哪里","谁掉落时间表","迪菲亚码头管理员"}},{q="如果特工在任务中被俘会发生什么？",a="正如马迪亚斯·肖尔所警告的那样，军情七处奉行严格的“合理推诿”原则。如果特工身份暴露或被捕，军情七处将否认与他们有任何联系。",al={"如果我失败了会怎样","被军情七处否认"}},{q="为什么军情七处需要这份船运时间表？",a="这份文件详细说明了迪菲亚潜行者如何在赤脊山和西部荒野之间运输违禁品。获取它能让暴风城的情报网络在不惊动该组织的情况下绘制出敌人的后勤地图。",al={"为什么需要时间表","军情七处船运时间表"}}},fp="15,158,20.313.0,22.321.0,21.312.0,38.121.0,25.175.0,54.135.0,41.97.0,61.104.0,48.197.0"}
P.entries["quest:221"] = {n="森林里的狼人",s="随着夜祸狼人族群进一步向夜色镇逼近，卡洛尔派遣冒险者去击杀该族群的主要基层潜行者。这些凶猛的暗影奔行者已经占领了附近的烂果园，威胁着要将这座被围困的城镇完全包围。",h="随着夜祸狼人族群进一步向夜色镇逼近，卡洛尔派遣冒险者去击杀该族群的主要基层潜行者。这些凶猛的暗影奔行者已经占领了附近的烂果园，威胁着要将这座被围困的城镇完全包围。",kw={"卡洛尔","卡尔文","暗影奔行者","夜色镇","暮色森林","守夜人","夜祸","烂果园","狼人"},ang={["class:Hunter"]="在烂果园迅速蔓延的非自然双足狼怪，给猎人们上了一堂严峻的课，教导他们如何应对那些违背艾泽拉斯自然生态、来自异界的野兽。",["faction:Alliance"]="暮色森林几乎没有得到来自暴风城王国的任何增援，这迫使守夜人等当地志愿民兵组织不得不完全依赖路过的联盟英雄来削减这些入侵的掠食者族群。"},sec={{t="收紧的防线",b="起初，侦察兵在森林边缘发现了独自编织暗影魔法的狼人，但卡洛尔的巡逻揭示了一个更为紧迫的战术威胁。更大型、更迅捷的野兽——被称为夜祸暗影奔行者——已经在夜色镇西南方的烂果园集结。这些掠食者并没有仅仅潜伏在树冠之下，它们构成了狼人族群的主力，并在距离镇门仅一步之遥的地方建立了前哨阵地。"},{t="无穷无尽的潮水",b="虽然消灭暗影奔行者可以暂时削弱狼人的攻势，但这并不能让守夜人感到安心。卡洛尔怀着日益增长的恐惧注意到，每一只被击倒的野兽仿佛都会被迷雾中徘徊的另一只立刻取代。夜祸狼人超自然的韧性和极高的补充速度让城镇的守卫者们感到困惑，迫使他们求助于像乔纳森·卡尔文大师这样的资深怪物猎人，去查明究竟是什么邪恶的媒介将这些异界的恐怖之物召唤到了暮色森林。"}},faq={{q="什么是夜祸暗影奔行者？",a="夜祸暗影奔行者是体型更大、更具威慑力的狼人，构成了徘徊在暮色森林的狼人族群的主要前线部队。与神秘的暗影织法者不同，暗影奔行者依靠纯粹的速度、利爪和捕食者的凶猛。",al={"暗影奔行者","什么是暗影奔行者","夜祸暗影奔行者"}},{q="烂果园在哪里？",a="烂果园位于夜色镇的西南方。它曾是一片肥沃的农田，如今已经沦为一片被腐化和侵蚀的空地，并被夜祸狼人族群当作靠近城镇的前进落脚点占据。",al={"烂果园位置","烂果园在哪里"}},{q="卡洛尔是谁？",a="卡洛尔是夜色镇的一名游侠，服务于乔纳森·卡尔文大师。他负责侦察定居点的边缘地带，追踪威胁着城镇生存的狼人族群的侵略性动向。",al={"卡洛尔是谁","卡洛尔暮色森林","卡洛尔任务发布者"}},{q="为什么守卫者觉得狼人的数量无穷无尽？",a="守卫者们还不了解狼人存在的超自然本质。他们认为有一股邪恶的力量正在积极地召唤或将这些野兽吸引到暮色森林，导致新的浪潮在旧的被杀死的瞬间就会出现。",al={"为什么狼人这么多","无穷无尽的狼人","狼人从哪里来"}},{q="卡尔文大师是谁？",a="乔纳森·卡尔文大师在夜色镇领导着卡尔文家族对抗亡灵和暮色森林其他邪恶势力的斗争。卡洛尔非常信任他的专业知识，希望他能查出困扰该地区的怪物滋生的根本原因。",al={"卡尔文大师","乔纳森·卡尔文","谁是卡尔文"}},{q="这项任务如何融入夜色镇的防御之中？",a="夜色镇是一个孤立的定居点，补给匮乏，且得不到暴风城的援助。清理烂果园可以防止夜祸狼人族群对城镇的西南防线发起直接且势不可挡的伏击。",al={"为什么要杀暗影奔行者","夜色镇防御"}}},fp="19,162,22.358.0,21.338.1,32.206.0,37.184.0,13.164.0,56.210.0,22.208.0,53.204.0"}
P.entries["quest:222"] = {n="森林里的狼人",s="随着夜行狼人部族不断收紧对暮色森林的控制，卡洛尔指引冒险者去打击他们最致命的军团。通过直接前往他们南方的巢穴和矿洞展开战斗，守卫者们击退了对夜色镇步步紧逼的野蛮威胁。",h="随着夜行狼人部族不断收紧对暮色森林的控制，卡洛尔指引冒险者去打击他们最致命的军团。通过直接前往他们南方的巢穴和矿洞展开战斗，守卫者们击退了对夜色镇步步紧逼的野蛮威胁。",kw={"卡洛尔","卡尔文","夜色镇","暮色森林","夜行狼人","污浊者","邪恶之牙","狼人"},ang={["class:Hunter"]="夜行狼人表现出的狡诈使它们成为了不同寻常的猎物，这要求在它们昏暗巢穴附近活动的追踪者必须时刻保持警惕。",["faction:Alliance"]="夜色镇孤零零地坐落在王国的阴郁南方；清理南方的洞穴有助于保护暮色森林脆弱的补给线和仅存的家园。"},sec={{t="野兽的立足点",b="困扰暮色森林的狼人瘟疫远非无脑的混乱。这些被称为“夜行”的野兽在夜色镇南部的黑暗旷野中开辟了领地，并开始建立坚固的营地。卡洛尔怀着日益增长的恐惧，注视着远方闪烁的篝火，他注意到这些生物已经占据了深处的洞穴和废弃的矿井。在它们之中，邪恶之牙和污浊者代表了最凶残的品种，它们展现出的野蛮残暴和顽强令人担忧，甚至可能威胁到小镇的周边防线。"},{t="卡洛尔的推荐",b="卡洛尔担任着夜色镇防御的前线征兵官，时刻保持警惕，尽管他对这些狼人入侵者可怕的本性并无幻想。击溃邪恶之牙和污浊者的主力是对任何英雄勇气的考验。那些成功铲除这些顽固狼群的人获得的不仅仅是金钱，还能赢得卡洛尔的尊重，并获得他写给卡尔文大师的亲笔推荐信。卡尔文大师是一位深居简出的重要人物，负责协调针对狼人天灾的更大规模攻势。"}},faq={{q="邪恶之牙和污浊者位于何处？",a="这些危险的夜行狼人品种聚集在暮色森林南部的洞穴和矿井周围，通常会聚集在显眼的篝火旁。",al={"污浊者位置","邪恶之牙位置","暮色森林狼人位置"}},{q="卡洛尔是谁？",a="卡洛尔是夜色镇的一名忠诚居民，他密切关注着森林中的狼人威胁，并招募有能力的冒险者来阻止这些生物的推进。",al={"卡洛尔 夜色镇","谁发布了“森林中的狼人”3"}},{q="卡尔文大师是谁？",a="卡尔文大师就是夜色镇的乔纳森·卡尔文，他的家族致力于对抗该地区的邪恶势力，并负责协调从周边地区根除狼人威胁的行动。",al={"卡尔文大师","卡尔文 暮色森林"}},{q="为什么狼人会生篝火？",a="尽管拥有可怕的狼人外表，但夜行狼人表现出了令人不安的智慧，它们聚集在有组织的营地中，使用火种，并占据着像矿井这样坚固的阵地。",al={"为什么狼人生火","夜行狼人篝火"}},{q="完成这次狩猎后会发生什么？",a="让卡洛尔刮目相看就能为你赢得一封推荐信，你可以直接去找卡尔文大师，协助他进行下一阶段的狩猎。",al={"“森林中的狼人”3后的后续任务","“森林中的狼人”后续"}},{q="为什么夜色镇如此担心这些特定的狼人？",a="邪恶之牙和污浊者是该部族中最致命、最具攻击性的成员。如果不加限制地任由它们在南方矿井附近活动，这些野兽可能会彻底淹没周边道路。",al={"为什么会有夜行狼人邪恶之牙","邪恶之牙的危险"}}},fp="19,129,16.324.0,19.288.1,50.107.0,13.120.0,22.147.0,32.183.0,40.123.0,58.175.0"}
P.entries["quest:223"] = {n="森林里的狼人",s="这一任务需要将卡洛尔的推荐信送交给夜色镇的乔纳森·卡尔文，从而结束你对那些在暮色森林游荡的野蛮狼人的追猎。卡洛尔对你在对抗这些野兽般的入侵者时展现出的英勇深感钦佩，并将你引荐给一位在阴影中与更深层威胁抗争的人。",h="这一任务需要将卡洛尔的推荐信送交给夜色镇的乔纳森·卡尔文，从而结束你对那些在暮色森林游荡的野蛮狼人的追猎。卡洛尔对你在对抗这些野兽般的入侵者时展现出的英勇深感钦佩，并将你引荐给一位在阴影中与更深层威胁抗争的人。",kw={"卡洛尔","卡洛尔的便笺","夜色镇","暮色森林","乔纳森·卡尔文","守夜人","森林中的狼人"},ang={["class:Paladin"]="卡尔文用圣光的祈祷词迎接被证明可靠的盟友，寻找愿意坚定地对抗暮色森林猖獗邪恶的圣光勇士。",["class:Priest"]="卡尔文临别时的祝福“愿圣光照耀你”回荡着夜色镇剩余的守卫者在面对永无止境的黑暗腐化时所怀有的那份绝望的信仰。",["faction:Alliance"]="由于暴风王国无法抽出兵力来支援暮色森林的边境，像卡尔文这样的联盟独立冒险者和守夜人成为了该镇唯一的防线。"},sec={{t="一份罕见的推荐",b="你已经铲除了盘踞在罗兰之墓和阴影空地中的夜祸狼群，赢得了卡洛尔那来之不易的尊重。卡洛尔驻守在暮色森林黑暗的边境，平时很少称赞别人，更不用说写正式的推荐信了。他递给你一张褪色的羊皮纸，让你直接把他的话传达给夜色镇的乔纳森·卡尔文，并提到如果他们能有更多像你这样实力的战士，他们这一小队人马或许终于能胜过城镇里那支疲于奔命的守夜人部队了。"},{t="卡尔文的警觉",b="乔纳森·卡尔文在夜色镇承受着巨大的压力，他警惕着外来者，且总是忙得不可开交。这座城镇不仅面临着嗜血狼人的猛攻，还受到徘徊不去的亡灵、阴险的恶魔势力以及从内部协助腐化的叛徒邪教徒的威胁。收到卡洛尔的强力推荐打破了卡尔文冰冷的外表，他确认你是一位值得信赖的、致力于在暮色森林令人窒息的恐怖中捍卫圣光的战士。"}},faq={{q="谁指派我执行这项任务？",a="这项任务由卡洛尔指派。在见证了你在整个暮色森林对抗贪婪狼群的英勇表现后，他给了你一张褪色的推荐便笺，让你带给他的伙伴乔纳森·卡尔文。",al={"任务发布者","谁开启了这个任务","卡洛尔"}},{q="乔纳森·卡尔文是谁？",a="乔纳森·卡尔文是夜色镇的一名行事严谨、高度专注的居民，负责协调对抗威胁该镇的超自然邪恶势力。虽然他对外来者保持警惕，但他与卡洛尔等值得信赖的人物合作，共同铲除亡灵、恶魔以及协助它们的同谋者。",al={"卡尔文","卡尔文是谁","卡尔文大师"}},{q="为什么卡洛尔如此轻视守夜人？",a="卡洛尔暗示镇上官方的守夜人部队陷入了困境，人手严重不足，难以应对入侵暮色森林的各种恐怖威胁。他认为，在正式的官僚体系之外，几名有能力的专职战士在对抗不断蔓延的阴影时能发挥更大的作用。",al={"卡洛尔 守夜人","胜过守夜人","为什么要与守夜人竞争"}},{q="送达时卡尔文警告了哪些威胁？",a="在读完推荐信后，卡尔文警告说夜色镇正面临多方威胁：贪婪的狼人、游荡的亡灵、入侵的恶魔，以及提供援助的阴险邪教徒或同谋者。他告诫你要保持警惕，只信任那些经过考验的盟友。",al={"卡尔文的敌人","卡尔文说了什么","我们在对抗什么"}},{q="这个任务需要战斗吗？",a="不需要。这是最后的一步，完全是一个跑腿任务。在完成了之前任务链中那些在暮色森林猎杀夜祸狼人的危险战斗后，这项任务只需要你安全地将卡洛尔的便笺送到夜色镇的卡尔文手中即可。",al={"需要战斗吗","我需要杀什么吗","仅限运送"}},{q="我在哪里可以找到乔纳森·卡尔文？",a="乔纳森·卡尔文位于暮色森林的夜色镇内，正在处理有关城镇危急防御的紧急事务。",al={"卡尔文的位置","卡尔文在哪里","去哪里交任务"}}},fp="19,196,21.434.0,15.337.0,29.162.0,24.233.0,46.182.0,51.159.0,35.136.0,34.73.0"}
P.entries["quest:224"] = {n="保卫国王的领土",s="巡山人库伯弗林特守卫着国王谷的南塔，急需援助以抵御入侵的碎石怪穴居人。随着铁炉堡的军队在遥远的前线上捉襟见肘，洛克莫丹南部山口的防御落到了过往的联盟志愿者身上。",h="巡山人库伯弗林特守卫着国王谷的南塔，急需援助以抵御入侵的碎石怪穴居人。随着铁炉堡的军队在遥远的前线上捉襟见肘，洛克莫丹南部山口的防御落到了过往的联盟志愿者身上。",kw={"库伯弗林特","格拉维戈","铁炉堡","洛克莫丹","巡山人","碎石怪","穴居人","国王谷"},ang={["class:Hunter"]="碎石怪之谷的悬崖和岩层提供了理想的地形，可以从高处狙击好斗的穴居人哨兵和侦察队。",["faction:Alliance"]="协助保卫国王谷体现了联盟纽带的力量，在矮人军队被部署到遥远的盟友战线时，回应铁炉堡的恳求。",["race:Dwarf"]="对于矮人冒险者来说，响应库伯弗林特的号召是保卫家园的重中之重，这能确保在军队远征他方时，麦格尼国王的祖居峡谷不会沦陷于这些地下害虫之手。"},sec={{t="国王谷的薄弱防线",b="国王谷山脉中雕刻出的巨大矮人纪念碑笼罩着一支压力重重的驻军。巡山人库伯弗林特和他的同僚守卫在南岗哨，面对着从岩石中涌出、规模不断扩大的穴居人入侵。由于国王麦格尼·铜须的大部分正规军已被派往国外以履行联盟的承诺，本土防线严重依赖当地巡逻队和雇佣兵来防止该省被占领。"},{t="碎石怪入侵",b="地下威胁源于碎石怪之谷，这是一条切入洛克莫丹南峰的崎岖深谷。穴居人及其斥候大量钻出地面，在谷底开辟了防御营地。如果不加遏制，他们的侦察队将威胁到连接洛克莫丹与南部山口的关键道路，迫使巡山人进行持续的消耗战。"}},faq={{q="为什么洛克莫丹的驻军人手如此不足？",a="国王麦格尼·铜须已将铁炉堡的大部分军队派往艾泽拉斯各地的遥远联盟战场和前哨站。这种对外承诺使得像洛克莫丹这样的本土领地主要由轻型巡山人巡逻队来保护，他们必须求助于过往的冒险者来阻止区域性的入侵。",al={"为什么守卫这么少","铁炉堡士兵在哪里","为什么人手不足"}},{q="巡山人库伯弗林特是谁？",a="巡山人库伯弗林特是一名驻守在国王谷南岗哨的矮人哨兵。他负责协调洛克莫丹南界的周边安全，并指挥针对筑巢穴居人部落的反击。",al={"库伯弗林特","谁提供任务","任务发布者"}},{q="碎石怪之谷在哪里？",a="碎石怪之谷位于塞尔萨玛以南，在到达国王谷巨大的矮人雕像之前，通过主路附近的一个入口即可进入。穴居人在其多岩石的谷底维持着几个营地。",al={"碎石怪位置","穴居人在哪里","寻找碎石怪之谷"}},{q="为什么穴居人对矮人构成如此严重的威胁？",a="穴居人是具有攻击性的地下野兽，它们能穿凿坚硬的岩石，绕过传统的地面城墙和防御工事。由于它们可以在道路、定居点和矿井下毫无预兆地突然出现，矮人当局认为它们肆无忌惮的繁殖是对铁炉堡安全的一种生存威胁。",al={"穴居人威胁","为什么要对抗穴居人","穴居人危险吗"}},{q="帮助库伯弗林特后我该和谁交谈？",a="在削弱了碎石怪穴居人和斥候的力量后，库伯弗林特会指引你去找驻扎在隔壁岗哨内的巡山人格拉维戈，他负责管理谷地前线巡逻的下一阶段任务。",al={"下一个任务","之后去哪里","格拉维戈"}},{q="碎石怪穴居人有组织吗？",a="虽然原始，但碎石怪氏族表现出基本的组织能力，它们部署专门的斥候去侦察道路，并配合那些在整个深谷中维持防御营地的野蛮步兵。",al={"穴居人斥候","穴居人聪明吗","碎石怪组织结构"}}},fp="30,170,34.307.0,27.321.0,49.266.0,31.204.0,38.197.0,54.178.0,44.193.0,39.136.0"}
P.entries["quest:2242"] = {n="命运的召唤",s="“命运的召唤”是一项由塞尤娜委托的秘密调查，旨在揭开泰达希尔枝叶中蔓延的腐蚀源头。任务要求特工潜行通过或对抗神谕林地附近一名名为“远古的塞希尔”的敌对萨特，以取回他的日记。",h="“命运的召唤”是一项由塞尤娜委托的秘密调查，旨在揭开泰达希尔枝叶中蔓延的腐蚀源头。任务要求特工潜行通过或对抗神谕林地附近一名名为“远古的塞希尔”的敌对萨特，以取回他的日记。",kw={"黑海岸","达纳苏斯","命运的召唤","日记","神谕林地","萨特","远古的塞希尔","塞尤娜","泰达希尔"},ang={["class:Rogue"]="这项任务由达纳苏斯自己的潜行训练师发布，旨在考验潜行者从危险的萨特眼皮底下窃取机密情报的能力。",["faction:Alliance"]="这一发现将泰达希尔当地的林地动荡与更广泛的大陆腐蚀联系起来，为联盟军队前往卡利姆多北部奠定了基础。",["race:NightElf"]="对于卡多雷的保卫者来说，得知黑海岸的古老诅咒已经跨越海洋来到泰达希尔，这预示着他们的神圣避难所正面临着令人担忧的威胁。"},sec={{t="静默侦察",b="达纳苏斯的暗夜精灵领导层一直在不安地关注着泰达希尔日益严重的病态。盗贼训练师塞尤娜没有派出那些最终只会送命的武装巡逻队，而是寻找能够执行潜行任务的人选。远古的塞希尔，一只栖息在神谕林地附近偏远枝干上的萨特，已经击退了所有武力和外交尝试。要揭开他所掌握的情报，就必须潜入他的巢穴并夺取他的个人物品。"},{t="黑海岸的阴影笼罩",b="取回的塞希尔的日记页揭示了残酷的真相。威胁着新生的世界之树的邪恶污秽，与吞噬了黑海岸对岸迷雾海域森林和水道的古老腐烂与堕落直接相关。这种病害并非土壤的孤立疾病，而是指向了威胁着卡多雷心脏地带的一场更广泛、更蓄意的恶意。"}},faq={{q="远古的塞希尔是谁？",a="远古的塞希尔是一只行踪诡秘的萨特，躲藏在泰达希尔神谕林地北郊的一根树枝上。他生性敌对且狡猾，挫败了所有为了探查他所掌握的关于岛屿腐蚀情报而发起的武力突袭和和平询问。",al={"塞希尔","塞希尔是谁","神谕林地的萨特"}},{q="为什么塞尤娜想要塞希尔的日记？",a="塞尤娜认为塞希尔掌握着关于泰达希尔蔓延的不明疾病的关键见解。他的个人日记中记录了关于这名萨特的活动以及黑暗污秽本质的笔记。",al={"为什么需要塞希尔的日记","塞尤娜的目标","日记里有什么"}},{q="任务完成后日记揭示了什么？",a="日记证实，侵蚀泰达希尔枝干的疾病与海峡对岸黑海岸古老森林和海岸线上肆虐的更深层的恶魔枯萎病有关。",al={"日记背景故事","塞希尔发现了什么","黑海岸联系"}},{q="这个任务在哪里领取？",a="这项任务由位于达纳苏斯阴影之中的盗贼训练师塞尤娜发布，需要在对你的能力进行初步评估后领取。",al={"哪里领取命运的召唤","命运的召唤任务发布者","谁发布命运的召唤"}},{q="冒险者完成这项任务后该去哪里？",a="塞尤娜指出，在这件事上你已无能为力，并奖励你一把利刃，以表彰你为泰达希尔所做的贡献。",al={"what comes next","命运的召唤之后做什么","处理塞希尔之后"}},{q="为什么是盗贼训练师而不是德鲁伊在处理森林腐蚀问题？",a="常规方法——无论是武装力量还是德鲁伊外交——在塞希尔面前都以失败告终，并导致了致命的后果。当公开的努力陷入血腥的死胡同时，塞尤娜转而寻求秘密侦察和渗透。",al={"为什么是盗贼任务","为什么是塞尤娜","为什么不是塞纳里奥议会"}}},fp="13,178,23.373.0,31.286.1,26.231.0,38.154.0,45.152.1,29.106.0,58.120.1,68.159.0"}
P.entries["quest:2258"] = {n="荒芜之地的试剂",s="在卡加斯前哨站，颇有名气的炼金师加卡尔需要荒芜之地的试剂来补充库存。他承诺提供金币作为报酬，但前提是必须有人把货物带回来。",h="在卡加斯前哨站，颇有名气的炼金师加卡尔需要荒芜之地的试剂来补充库存。他承诺提供金币作为报酬，但前提是必须有人把货物带回来。",kw={"炼金术","荒芜之地","秃鹫胃囊","峭壁土狼獠牙","加卡尔","卡加斯","岩石元素碎块","奥达曼"},sec={{t="补充库存",b="加卡尔缺乏配料：五个秃鹫的胃囊、十个峭壁土狼的獠牙，以及五个岩石元素碎块。这三种材料都能从对应的生物身上获得。如果不擅长战斗，建议找擅长战斗的朋友帮忙。加卡尔会支付金币，但必须在拿到试剂之后才会给。"},{t="收获之后",b="加卡尔对这次的收获感到很满意，他说这些材料应该能维持一段时间。这位炼金师还需要更多试剂，但那些试剂只能在奥达曼发掘场深处才能找到，而且很难获得。加卡尔暗示，报酬可能不仅仅是闪亮的金币。"}},faq={{q="是谁在索要这些试剂？",a="加卡尔，一位在荒芜之地卡加斯前哨站颇有名气的炼金师，他想要补充库存。",al={"谁发布了荒芜之地的试剂任务","加卡尔","加卡尔是谁"}},{q="加卡尔需要什么配料？",a="五个秃鹫的胃囊、十个峭壁土狼的獠牙和五个岩石元素碎块。它们都是从生物本身掉落的。",al={"需要什么物品","荒芜之地试剂列表","所需的试剂"}},{q="加卡尔在哪里？",a="加卡尔位于荒芜之地的卡加斯前哨站。",al={"加卡尔的位置","卡加斯的炼金师在哪里","在哪里交荒芜之地的试剂任务"}},{q="加卡尔用什么来交换这些配料？",a="金币，在将试剂带给卡加斯的加卡尔之后支付。在此之前不会支付任何报酬。",al={"荒芜之地的试剂任务奖励","我能得到什么"}}},fp="20,192,20.320.0,14.266.1,33.120.0,34.142.0,33.53.0,55.91.0"}
P.entries["quest:2259"] = {n="艾瑞安·影语",s="Erion Shadewhisper是一个简单的召唤任务，旨在引导初出茅庐的联盟潜行者前往达纳苏斯。该信息由詹诺克·柔歌传达，指引旅行者前往塞纳里奥区，Erion Shadewhisper正等在那里，准备将他们的行动范围扩展到当地以外的区域。",h="Erion Shadewhisper是一个简单的召唤任务，旨在引导初出茅庐的联盟潜行者前往达纳苏斯。该信息由詹诺克·柔歌传达，指引旅行者前往塞纳里奥区，Erion...",kw={"塞纳里奥区","达纳苏斯","erion shadewhisper","erion's behest","詹诺克·柔歌","潜行者引导任务","塞尤娜"},ang={["class:Rogue"]="这个引导任务标志着你从泰达希尔的新手工作中毕业，直接将你引向Erion Shadewhisper，去执行那些需要超越起始森林范畴的精湛技巧的任务。",["faction:Alliance"]="该任务引导卡利姆多北部的联盟特工在进入争夺领土之前，先与达纳苏斯的联络人进行协调。",["race:NightElf"]="对于暗夜精灵影行者来说，向达纳苏斯的Erion Shadewhisper报到是必经的成人礼，标志着他们从本地守卫工作转向更广泛的大陆职责。"},sec={{t="塞纳里奥区的召唤",b="当一名潜行者在泰达希尔周边地区小有名气时，詹诺克·柔歌会介入，确保他们的才华不被浪费。为了缓解他们被派去接受严厉的训练师塞尤娜教导的焦虑，詹诺克转而指引这些特工直接前往达纳苏斯的中心。在那里，在塞纳里奥区葱郁的枝叶深处，Erion Shadewhisper负责处理那些需要更安静、更微妙手段的事务。"},{t="展望地平线",b="对于任何在暗夜精灵领地活动的潜行者来说，找到Erion Shadewhisper是一个重要的转折点。他的问候清楚地表明，泰达希尔的庇护森林已不再能束缚一名特工的职责。Erion Shadewhisper的角色是引导有能力的潜行者走向更广阔、更危险的世界，并作为通往跨海任务的跳板。"}},faq={{q="是谁让你去找Erion Shadewhisper的？",a="詹诺克·柔歌发布了召唤，让你立即前往达纳苏斯，在塞纳里奥区与Erion Shadewhisper交谈。",al={"任务发布者","谁开启了erion shadewhisper任务","詹诺克·柔歌任务"}},{q="Erion Shadewhisper在哪里？",a="Erion Shadewhisper位于达纳苏斯的塞纳里奥区，就在该区域上层的树木掩映之中。",al={"erion shadewhisper位置","erion shadewhisper在哪里","如何找到erion shadewhisper"}},{q="为什么詹诺克提到了塞尤娜？",a="塞尤娜是达纳苏斯一位著名的潜行者训练师，以严厉和高要求著称。詹诺克开了一个轻松的玩笑，让你放心，你并没有惹上麻烦，也不会被拖去接受她那严苛的课程。",al={"谁是塞尤娜","为什么不是塞尤娜","詹诺克关于塞尤娜的台词"}},{q="向Erion Shadewhisper报到后会发生什么？",a="在你完成汇报后，Erion Shadewhisper会交给你他的下一个任务“Erion's Behest”，指引你离开泰达希尔，以扩大你在卡利姆多的行动范围。",al={"接下来做什么","erion shadewhisper后续","erion shadewhisper之后的任务"}},{q="Erion Shadewhisper负责什么样的工作？",a="Erion Shadewhisper负责协调达纳苏斯内部的行动并指导初出茅庐的潜行者，作为一名联络人，将当地特工与联盟网络中更广泛的任务连接起来。",al={"erion shadewhisper是潜行者训练师吗","erion shadewhisper的角色","erion shadewhisper做什么"}},{q="为什么一个潜行者联络人会驻扎在塞纳里奥区？",a="虽然塞纳里奥区主要以德鲁伊和自然崇拜而闻名，但其蔓延、阴影笼罩的树木为潜行特工提供了充足的隐蔽场所，使他们能够避开Temple of the Moon，聚集并开展业务。",al={"塞纳里奥区潜行者","为什么德鲁伊区域会有潜行者"}}},fp="18,158,24.243.0,19.210.0,41.98.0,36.105.0,31.197.0,38.132.0,37.95.0,57.175.0"}
P.entries["quest:226"] = {n="恶狼成群",s="“狼群逼近”是一项联盟任务，由位于暮色森林西部斯温营地的拉尔斯提供。任务要求狩猎潜伏在周围树林中、患有狂犬病且饥饿的恐狼。旅行者们将清除这些迫在眉睫的荒野威胁，让斯温和拉尔斯能够专注于他们针对死灵法师摩本特·费尔的复仇行动。",h="“狼群逼近”是一项联盟任务，由位于暮色森林西部斯温营地的拉尔斯提供。任务要求狩猎潜伏在周围树林中、患有狂犬病且饥饿的恐狼。旅行者们将清除这些迫在眉睫的荒野威胁，让斯温和拉尔斯能够专注于他们针对死灵法师摩本特·费尔的复仇行...",kw={"恐狼","暮色森林","闪光束","拉尔斯","摩本特·费尔","患狂犬病的恐狼","饥饿的恐狼","斯温","斯温营地"},ang={["class:Hunter"]="驯服或扑杀暮色森林中扭曲的野生动物需要极高的警惕；这些恐狼远比普通的森林野兽更加绝望和凶残。",["faction:Alliance"]="帮助拉尔斯可以稳定斯温偏远的营地，从而稳固一个对抗困扰暮色森林西部亡灵势力的盟军补给据点。"},sec={{t="岌岌可危的营地",b="斯温·约根和他的同伴拉尔斯在暮色森林西部、靠近西部荒野边界的群山中维护着一个与世隔绝的前哨站。远离夜色镇的生活使他们完全依赖自己的采集和狩猎来维持生存。然而，在这些黑暗的树林中携带新鲜猎物，使拉尔斯成为了潜伏在阴影河岸和灌木丛中的饥饿掠食者们无法抗拒的目标。"},{t="清理树林",b="当地的饥饿且患有狂犬病的恐狼群主要在营地的北部和东部，向河流方向游荡。通过猎杀这些疯狂的野兽，旅行者们解除了拉尔斯狩猎工作所面临的紧迫困境。减少狼群的数量使两人不必再为每日的面包而不断战斗，让他们能够将全部注意力转向潜伏在更东面的死灵法师摩本特·费尔身上。"}},faq={{q="拉尔斯是谁？",a="拉尔斯是一位坚韧的生存专家，在暮色森林西部山丘中的一个小营地里协助斯温·约根。他负责营地日常的狩猎和采集，而斯温则执着于向威胁该地区的黑暗势力复仇。",al={"拉尔斯","狼群逼近任务发布者","任务发布者拉尔斯"}},{q="狼群在何处游荡？",a="恐狼游荡在斯温营地正北和正东的森林中，特别是在将暮色森林与北部地区隔开的河岸沿线。",al={"恐狼位置","患狂犬病的恐狼在哪里","饥饿的恐狼在哪里"}},{q="为什么恐狼如此具有攻击性？",a="在阴影的侵蚀下，暮色森林的荒野环境日益恶化。猎物稀缺，导致恐狼濒临饿死；疾病或黑暗腐蚀也使得它们中的许多患上了狂犬病，并对任何携带新鲜肉类的人表现出鲁莽的暴力倾向。",al={"狼群为何攻击","暮色森林的疯狼"}},{q="摩本特·费尔是谁？",a="摩本特·费尔是一位强大的死灵法师，在东部的墓地和土丘中研习黑暗艺术。斯温和拉尔斯对他怀有深仇大恨，并准备在满足了基本生存需求后就去打倒他。",al={"摩本特·费尔","死灵法师","东面的死灵法师是谁"}},{q="拉尔斯作为奖励给予的闪光束是什么？",a="闪光束是由夜色镇居民制造的致盲闪光装置。同情的居民们将它们捐赠给了斯温的营地，以帮助他对抗在这片树林中出没的亡灵和野兽。",al={"闪光束","拉尔斯的奖励","什么是闪光束"}},{q="为什么斯温和拉尔斯不住在夜色镇？",a="斯温的家庭遭遇了一场悲剧，使他变成了一个痛苦、执着的义务警员。斯温和拉尔斯没有躲在夜色镇的守夜人背后，而是驻扎在荒野中，亲身追踪困扰这片树林的邪恶力量。",al={"为什么要住在营地","斯温营地位置","为什么不住在镇里"}}},fp="19,200,17.296.0,18.261.0,12.199.0,30.140.0,38.231.0,19.203.0,50.188.0,42.230.0"}
P.entries["quest:2260"] = {n="艾瑞安的命令",s="“埃里奥的嘱托”是一份发给在达纳苏斯行动、前途无量的暗夜精灵潜行者的传唤。潜行者导师埃里奥·影语（Erion Shadewhisper）认可了他们初露锋芒的潜行技巧，于是派遣他们跨越海洋前往暴风城，直接向暴风城军情七处报到。",h="“埃里奥的嘱托”是一份发给在达纳苏斯行动、前途无量的暗夜精灵潜行者的传唤。潜行者导师埃里奥·影语（Erion...",kw={"达纳苏斯","埃里奥·影语","埃里奥的嘱托","old town","“剃刀”雷吉克","潜行者","军情七处","暴风城"},ang={["class:Rogue"]="这份传唤标志着你已从卡利姆多的地方小打小闹，毕业并进入了更广阔的洲际间谍活动领域，并将在军情七处接受致命的训练。",["faction:Alliance"]="军情七处负责统筹联盟的秘密行动，确保来自各个成员种族的优秀侦察兵能够被部署到王权最需要他们的地方。",["race:NightElf"]="离开达纳苏斯和泰达希尔的庇护，去暴风城的石板巷弄里为人类情报网络效力，对于卡多雷潜行者来说，往往是一种强烈的文化冲击。"},sec={{t="跨海的传唤",b="在泰达希尔阴影下行动的暗夜精灵潜行者通常会在埃里奥·影语这样的导师静默的注视下磨练自己的技能。然而，当一名特工展现出非凡的天赋时，消息便会传遍世界之树的枝桠。通过埃里奥，暴风城军情七处（即大名鼎鼎的军情七处）向其发出直接邀请，要求其跨越无尽之海前往人类首都。"},{t="加入军情七处",b="旅途十分艰辛，特工需要从卡利姆多的北部边境出发，穿过黑海岸的码头或湿地，进入暴风城熙熙攘攘的街道。一旦到达首都，特工必须潜入Old Town，并向军情七处总部报到。在那里，“剃刀”雷吉克正等着考核新人，为他们开启通往高级间谍活动、毒药精通以及代表联盟执行隐秘行动的大门。"}},faq={{q="是谁派遣我执行这个任务的？",a="埃里奥·影语，达纳苏斯的潜行者训练师。在你早期的事迹引起了海对岸情报网络的注意后，他便指派了这项任务给你。",al={"任务发布者","埃里奥·影语","谁给了我这个任务"}},{q="为什么军情七处会联系一名暗夜精灵？",a="虽然暗夜精灵有自己传统的潜行方式，但联盟非常依赖军情七处来协调秘密情报和破坏活动。军情七处会定期发掘任何联盟种族中的优秀潜行者，以充实他们的作战队伍。",al={"为什么是军情七处","为什么是暴风城","人类为何关注我"}},{q="我在哪里可以找到“剃刀”雷吉克？",a="“剃刀”雷吉克驻扎在军情七处总部内，该总部位于暴风城的Old Town区一隅。",al={"雷吉克的位置","剃刀在哪里","寻找雷吉克"}},{q="这个任务只有潜行者能接吗？",a="是的。这是一个联盟潜行者职业任务，旨在引导位于卡利姆多的特工前往暴风城的联盟情报训练中心。",al={"仅限潜行者","其他职业能做这个吗","这是潜行者任务吗"}},{q="见到雷吉克之后会发生什么？",a="向雷吉克报到后，你将加入军情七处在东部王国的训练行动，从而为接受专门训练和在人类领地执行隐秘任务做好准备。",al={"后续任务","我能得到什么","雷吉克之后"}},{q="现阶段暗夜精灵该如何前往暴风城？",a="旅客可以从黑海岸的奥伯丁乘坐船只，直航跨越海洋抵达暴风城港口。",al={"如何前往暴风城","前往暴风城","前往暴风城的路径"}}},fp="14,223,24.273.0,28.325.0,29.144.0,53.208.0,34.75.0,30.127.0,34.171.0,57.85.0"}
P.entries["quest:2281"] = {n="赤脊山的联络员",s="“赤脊山会面”是暴风城情报指挥部派发的一项联盟潜行者任务。由于SI:7意识到未经雕琢的新兵缺乏执行危险实地行动所需的技巧，他们会将有潜力的特工送往湖畔镇，以便在经验丰富的特工指导下磨练他们的职业技能。",h="“赤脊山会面”是暴风城情报指挥部派发的一项联盟潜行者任务。由于SI:7意识到未经雕琢的新兵缺乏执行危险实地行动所需的技巧，他们会将有潜力的特工送往湖畔镇，以便在经验丰富的特工指导下磨练他们的职业技能。",kw={"湖畔镇","卢修斯","赤脊山会面","伦兹克·“快刀”","潜行者任务","si:7","暴风城"},ang={["class:Rogue"]="这项任务标志着潜行者正式开始SI:7的实地工作，将其训练内容从街头小偷小摸转变为经过计算的国家间谍活动。",["faction:Alliance"]="这项指派揭示了暴风城秘密部门的影响力，他们在像湖畔镇这样的外部定居点中也驻扎有隐秘的特工。"},sec={{t="生存的考量",b="在暴风城SI:7的秘密大厅内，副指挥官伦兹克·“快刀”对新兵的预期寿命直言不讳。将未经磨练的特工直接投入敌对行动只会造成人员伤亡，而非搜集情报。为了防止不必要的损失，SI:7会将展现出潜力的招募人员派往东方，进入赤脊山，并在驻扎于湖畔镇码头的特工卢修斯手下接受训练。"},{t="湖畔镇的监视者",b="湖畔镇是进行秘密训练的理想中转站。这座边境城镇四周环绕着豺狼人和黑石兽人，提供了充足的现实威胁；而繁忙的码头又为卢修斯这样的特工提供了绝佳的掩护，使他能在不引起当地镇民或城镇守卫注意的情况下，评估潜行者的潜行、反应和开锁能力。"}},faq={{q="谁发布了“赤脊山会面”任务？",a="伦兹克·“快刀”，这位在暴风城Old Town的SI:7总部内活动的哥布林情报主管，会将该任务发布给向情报指挥部报到的潜行者。",al={"谁发布赤脊山会面","赤脊山会面任务发布人","谁发布任务"}},{q="卢修斯在哪里？",a="卢修斯位于赤脊山的湖畔镇木质码头上，混在水边的当地闲人和渔民中。",al={"卢修斯在哪里","卢修斯位置","寻找卢修斯"}},{q="SI:7为什么要派潜行者去赤脊山？",a="伦兹克认为新手潜行者不适合执行高风险的情报实地任务。卢修斯的职责是打磨他们的生疏技巧，在边境环境下测试他们的扒窃和开锁等实际能力。",al={"为什么选择湖畔镇","赤脊山会面的目的","为什么去赤脊山"}},{q="完成“赤脊山会面”后有什么后续任务？",a="向卢修斯报到后会直接进入训练练习，首先是“奥瑟尔伐木场”，特工将在那里被要求测试自己的潜行能力和手工灵巧度。",al={"下一个任务","赤脊山会面后续","赤脊山会面之后"}},{q="除了潜行者以外的职业可以接取此任务吗？",a="不可以。“赤脊山会面”是专门针对SI:7实地训练的联盟潜行者职业任务。",al={"战士可以做赤脊山会面吗","是潜行者专属吗","职业要求"}},{q="为什么伦兹克会为暴风城情报部门工作？",a="尽管伦兹克·“快刀”是个哥布林，但他却是情报主管Mathias Shaw高度信任的副手，负责在SI:7要塞深处进行特工招募和培训。",al={"为什么si:7里有哥布林","伦兹克背景故事","暴风城的哥布林"}}},fp="19,183,21.327.0,17.237.0,40.154.0,24.120.0,38.206.0,48.117.0,53.85.0,48.160.0"}
P.entries["quest:2282"] = {n="奥瑟尔伐木场",s="奥瑟尔伐木场是联盟潜行者在湖畔镇接受卢修斯指导的一项关键训练任务。学员们被派往附近的伐木场，带着一套盗贼工具，潜入黑石兽人监视的区域，打开一个锁着的箱子并取回偷窃技能证明物。",h="奥瑟尔伐木场是联盟潜行者在湖畔镇接受卢修斯指导的一项关键训练任务。学员们被派往附近的伐木场，带着一套盗贼工具，潜入黑石兽人监视的区域，打开一个锁着的箱子并取回偷窃技能证明物。",kw={"奥瑟尔伐木场","黑石兽人","湖畔镇","开锁","卢修斯","赤脊山","军情七处","盗贼工具","偷窃技能证明物"},ang={["class:Rogue"]="这项成年礼为你提供了必备的开锁工具和实地认证，在黑石兽人巡逻的间隙考验你的耐心和隐身能力。",["faction:Alliance"]="在湖畔镇边缘训练专业的盗贼和渗透者，既加强了联盟的情报工作，又能密切监视黑石兽人的动向。"},sec={{t="优雅与技巧的考验",b="在湖畔镇，如果能通过打开锁住的箱子快速学会课程，潜行者教官们是不会费心进行抽象说教的。卢修斯派遣有前途的特工沿路向东北前往奥瑟尔伐木场，并为他们配备了第一套盗贼工具。为了获得正式的偷窃技能认证书，新手们必须溜进废弃的伐木场，撬开卢修斯的私人锁箱，并带回藏在里面的证明物。"},{t="锯木厂周围的阴影",b="虽然奥瑟尔伐木场曾经是一个普通的木材前哨站，但最近它引起了入侵赤脊山的黑石兽人们危险的关注。卢修斯很高兴地将这些入侵的战争贩子视为一种额外的实战考核。在敌占区潜行并不被发现地开锁，正是军情七处期望其特工所能生存的试炼。"}},faq={{q="前往奥瑟尔伐木场的任务目的是什么？",a="这是联盟潜行者学习开锁艺术的实战考核。卢修斯会提供给你盗贼工具，并要求你从锁着的步兵箱中取回特定的证明物，以此来证明你的技巧。",al={"为什么要前往奥瑟尔伐木场","任务目的","这个任务做什么"}},{q="卢修斯是谁？",a="卢修斯是一位经验丰富的潜行者训练师，在赤脊山的湖畔镇工作。他多年来一直在教导联盟各处联系人送来的潜行者新兵，测试他们的隐身能力和手动灵活性。",al={"谁是卢修斯","卢修斯湖畔镇","谁发布这个任务"}},{q="奥瑟尔伐木场在哪里？",a="奥瑟尔伐木场位于湖畔镇东北偏东方向的路边，坐落在通往更高山隘之前的山脚下。",al={"伐木场在哪里","奥瑟尔伐木场位置","如何找到奥瑟尔伐木场"}},{q="为什么奥瑟尔伐木场周围有兽人？",a="黑石氏族的兽人已经从石堡和上方燃烧的山脊高处降临，他们正在袭击人类定居点，并在整个赤脊山建立前沿据点，包括那个废弃伐木场周围的区域。",al={"为什么这里有兽人","黑石兽人赤脊山","谁控制了奥瑟尔伐木场"}},{q="完成任务后卢修斯会给予什么奖励？",a="卢修斯会授予你偷窃技能认证书，认可你已经掌握了弹子锁和开锁工具的基础知识，现在可以作为一名完全合格的战地潜行者行动了。",al={"奖励是什么","偷窃技能认证书","任务完成奖励"}},{q="这个任务在联盟的潜行者训练中占什么地位？",a="全联盟的潜行者都会在暴风城的Mathias Shaw所属军情七处联络人的指引下，前往湖畔镇与卢修斯会合。奥瑟尔伐木场的任务构成了他们基础实地训练的实战高潮。",al={"潜行者任务线","军情七处关联","赤脊山会合后续"}}},fp="13,177,27.266.0,23.251.0,52.148.0,14.163.0,31.126.0,40.198.0,55.151.0,64.218.0"}
P.entries["quest:23"] = {n="乌萨苟斯的爪子",s="这个任务证明了你已经击杀了乌萨诺斯，它是灰谷中最凶猛、最富传奇色彩的掠食者之一。将这头野兽的断爪带给碎木岗哨的塞娜尼·雷心，将为你赢得部落追踪者们的荣耀。",h="这个任务证明了你已经击杀了乌萨诺斯，它是灰谷中最凶猛、最富传奇色彩的掠食者之一。将这头野兽的断爪带给碎木岗哨的塞娜尼·雷心，将为你赢得部落追踪者们的荣耀。",kw={"灰谷","灰谷狩猎","熊","新月纹章","爪子","塞娜尼·雷心","碎木岗哨","乌萨诺斯"},ang={["class:Hunter"]="追踪并击败灰谷最古老、最致命的掠食者之一，是对野外生存能力、求生技巧和战斗技能的终极考验。",["faction:Horde"]="部落猎手视乌萨诺斯为危险的猎物，击败它能在碎木岗哨赢得荣耀。",["race:Tauren"]="对于牛头人猎手来说，夺取乌萨诺斯的爪子是一件神圣的事情，既是为了向野兽表示敬意，也是为了展示战斗的决心以及对狩猎之灵的尊重。"},sec={{t="伟大狩猎的战利品",b="作为灰谷狩猎的一部分，驻扎在碎木岗哨的追踪者们负责追捕那些盘踞在茂密森林树冠下的远古野兽。乌萨诺斯是这些顶级掠食者中最凶猛的一员，因为它杀死了无数过往的旅人和战士。击败这样的野兽绝非易事，取回它的爪子是这头强大生物最终落败的铁证。"},{t="暗夜精灵的联系",b="仔细检查乌萨诺斯的爪子时，可以看到上面刻有一个小的四分之一新月纹章。当你把它交给塞娜尼·雷心时，她会指出这个标志是暗夜精灵介入的明确迹象。暗夜精灵经常驯养和结盟森林中强大的野兽来保卫他们神圣的边境，这意味着乌萨诺斯不仅仅是一头野生掠食者——它还是联盟不自知的守护者或武器。"}},faq={{q="什么是乌萨诺斯？",a="乌萨诺斯是一头漫游在灰谷森林中，体型巨大且致命的熊。它让猎人和路人闻风丧胆，在倒在部落的猎杀之下前，它已经夺去了无数的生命。",al={"乌萨诺斯是谁","乌萨诺斯之熊","乌萨诺斯背景故事"}},{q="爪子上的新月纹章意味着什么？",a="当你检查战利品时，这个四分之一新月纹章是一个谜。当你送交这只爪子时，塞娜尼·雷心可以帮你鉴定它。",al={"爪子上的新月印记","爪子纹章","为什么会有新月标志"}},{q="我该把乌萨诺斯的爪子交给谁？",a="这只爪子必须交给位于灰谷东部碎木岗哨的牛头人女猎手塞娜尼·雷心。",al={"在哪里上交爪子","谁想要乌萨诺斯的爪子","塞娜尼·雷心位置"}},{q="这与灰谷狩猎有什么关系？",a="乌萨诺斯是灰谷狩猎中被标记的三头巨兽之一，另外两头是沙德拉和尖爪。击败这三头巨兽并上交它们的战利品是完成整个试炼的必要条件。",al={"灰谷狩猎系列任务","什么是狩猎","狩猎任务线"}},{q="部落为什么要猎杀灰谷的巨兽？",a="部落的猎手，尤其是碎木岗哨的牛头人和兽人，猎杀这些顶级生物既是为了测试他们的战斗能力，也是为了遏制潜伏在他们脆弱补给线和营地附近的致命威胁。",al={"为什么要猎熊","碎木岗哨狩猎背景"}},{q="上交爪子后会发生什么？",a="一旦你收集了乌萨诺斯和其他指定猎物的战利品，塞娜尼·雷心就会在最终试炼“狩猎的终结”中认可你的功绩。",al={"爪子之后的下一个任务","乌萨诺斯之后是什么"}}},fp="15,188,26.275.0,24.336.1,18.177.0,46.141.0,34.108.0,42.161.0,55.191.0,38.173.0"}
P.entries["quest:230"] = {n="斯温的营地",s="斯温的营地是暮色森林中的一个联盟任务，揭露了关于约根家园惨剧的关键线索。通过从废弃农场的一堆松土中挖掘出一本无名日记，冒险者们拼凑出了是谁目睹了斯温·约根家人的惨死。",h="斯温的营地是暮色森林中的一个联盟任务，揭露了关于约根家园惨剧的关键线索。通过从废弃农场的一堆松土中挖掘出一本无名日记，冒险者们拼凑出了是谁目睹了斯温·约根家人的惨死。",kw={"黑暗骑士","暮色森林","一堆松土","暗影身影","斯温·约根","约根农场"},ang={["faction:Alliance"]="调查约根惨案是联盟更广泛的努力的一部分，旨在理解正在侵蚀暮色森林的黑暗力量。"},sec={{t="泥土中的线索",b="当黑暗骑士袭击斯温·约根的农场时，他恰好不在家。当他回来时，只看到家人惨死，农场化为废墟。悲痛与复仇的火焰吞噬了他，他派遣盟友去搜寻家园的残骸。在一堆翻出的新土下，埋藏着一本沾满污泥的小书，那是某个暗影身影匆忙藏下的。"},{t="无声的目击者",b="当把这本书带到位于西部丘陵的斯温营地后，书中的细节令人不寒而栗。它证明了一个暗影身影目睹了他家人惨遭屠杀的恐怖过程。这本日记并没有给斯温带来安宁，反而让他将悲痛转变为对寻找这个神秘旁观者并索要答案的执着。"}},faq={{q="从土堆中找到的书是什么？",a="那是一本埋在约根农场的无名且沾满污泥的日记。其中的记录证明，一个身份不明的旁观者目睹了斯温·约根家人的惨死。",al={"这是什么书","斯温农场的书","我挖到了什么"}},{q="这个任务接下来会引导去哪里？",a="将书交给斯温·约根会直接开启任务“暗影身影”，开始寻找那个神秘的目击者。",al={"what comes next","斯温的营地后续任务","谁是暗影身影"}},{q="斯温·约根在哪里？",a="斯温在暮色森林西北部的丘陵中建立了一处避难营地，在那里沉思家人的命运并策划复仇。",al={"斯温在哪里","斯温·约根的位置","在哪里交任务"}},{q="为什么书会被埋在农场里？",a="这本书被藏在废弃家园的一堆松土中，很可能是袭击现场的观察者匆忙丢弃或藏匿的。",al={"为什么要埋起来","谁藏了这本书","一堆松土"}},{q="是谁杀了斯温的家人？",a="来自逆风小径的黑暗骑士在斯温外出时突袭了农场，屠杀了他的家人。",al={"谁袭击了农场","谁杀了斯温的家人","杀害斯温家人的凶手"}},{q="哪个阵营可以完成这个任务？",a="该任务为联盟玩家专属，因为斯温·约根只寻求暮色森林的保卫者和联盟的援助。",al={"这是联盟专属吗","部落能做斯温的营地吗"}}},fp="11,160,18.304.0,16.246.1,44.167.0,32.114.0,29.118.0,36.165.0,25.89.0,37.109.0"}
P.entries["quest:2300"] = {n="军情七处",s="这项指令旨在将艾尔文森林中前途无量的年轻潜行者直接召集到暴风城秘密情报网络的核心。在闪金镇的科瑞恩·塞尔留斯指导下，特工们被命令立即向Old Town的“剃刀”雷吉克报到。响应此召唤将使一名特工直接进入马迪亚斯·肖尔大师麾下效力。",h="这项指令旨在将艾尔文森林中前途无量的年轻潜行者直接召集到暴风城秘密情报网络的核心。在闪金镇的科瑞恩·塞尔留斯指导下，特工们被命令立即向Old...",kw={"科瑞恩·塞尔留斯","mathias shaw","old town","“剃刀”雷吉克","潜行者","哨兵岭","si:7","暴风城"},ang={["class:Rogue"]="这次召唤标志着你从一名从事当地杂活的流氓，转变为暴风城官方情报部门认可的特工。",["faction:Alliance"]="SI:7作为联盟的秘密盾牌，负责处理那些常规元帅和步兵无法公开执行的危险间谍行动。"},sec={{t="前往Old Town的召唤",b="潜行者训练师科瑞恩·塞尔留斯在闪金镇的Lion's Pride Inn开展工作，密切关注当地的新兵。当一名潜行者在应对聚集的Defias威胁时展现出足够的狡黠和能力，塞尔留斯就会传达来自总部的消息。召唤简短而不拘礼节：立即向“剃刀”雷吉克报到。特工将离开艾尔文森林的田野，直接被指派前往首都的秘密核心。"},{t="暴风城的隐形之眼",b="在Old Town一座毫不起眼的军营外表下，隐藏着暴风城首席情报机构——SI:7的总部。在马迪亚斯·肖尔大师的指挥下，SI:7负责管理整个王国及其周边的秘密行动、侦察和暗杀任务。“剃刀”雷吉克是肖尔言辞犀利的副官，他会亲自审核有前途的外勤特工，然后再将他们派遣去执行那些王国正规军无法触及的高风险行动。"}},faq={{q="是谁派我向SI:7报到的？",a="闪金镇Lion's Pride Inn的潜行者训练师科瑞恩·塞尔留斯会给你这项指令。一旦你在外勤中证明了自己的能力，塞尔留斯就会传达命令，指示你前往暴风城的总部报到。",al={"谁发布任务","任务发布者","科瑞恩·塞尔留斯"}},{q="“剃刀”雷吉克是谁？",a="“剃刀”雷吉克是一位地精特工，担任SI:7的副官，直接在马迪亚斯·肖尔大师手下工作。他负责评估外勤特工，并从位于Old Town的SI:7总部协调秘密情报任务。",al={"“剃刀”雷吉克","谁是雷吉克","雷吉克"}},{q="什么是SI:7？",a="SI:7——即暴风城情报局——是暴风城王国的秘密间谍、侦察和暗杀部门。在Mathias Shaw的领导下，其特工负责收集针对王权威胁的情报，这些威胁是常规卫兵和士兵无法处理的。",al={"什么是si:7","si:7是做什么的","暴风城情报局"}},{q="SI:7总部位于哪里？",a="SI:7总部位于暴风城的Old Town东部。它在一座隐藏于主干道之外的坚固行会大厅和训练营中运作。",al={"si:7在哪里","si:7位置","雷吉克在哪里"}},{q="向雷吉克报到后会发生什么？",a="一旦你向雷吉克报到，他会测试你的准备情况，然后才会分配给你一项城墙之外的外勤任务，派遣你去见一位驻扎在Redridge的特工。",al={"下一个任务","接下来要做什么","redridge会合"}},{q="为什么科瑞恩·塞尔留斯叫我“菜鸟”？",a="这是指未受考验的新手或新兵的俚语。该机构内部的特工会使用生动且刺耳的昵称，以让新兵在通过真实任务证明自己之前保持谦逊。",al={"为什么叫我菜鸟","菜鸟的含义"}}},fp="4,166,21.292.0,23.413.0,31.202.0,25.204.0,13.239.0,39.159.0,39.136.1,38.183.0"}
P.entries["quest:233"] = {n="寒脊山谷的送信任务",s="寒脊山谷的信件投递是一项简单的快递任务，由安威玛尔的斯登·粗臂委托给新兵。由于山口常被积雪封堵，且附近有穴居人出没，将新鲜的信件送到冰封湖畔的营地，能让山谷中孤立的守卫者们保持联络。",h="寒脊山谷的信件投递是一项简单的快递任务，由安威玛尔的斯登·粗臂委托给新兵。由于山口常被积雪封堵，且附近有穴居人出没，将新鲜的信件送到冰封湖畔的营地，能让山谷中孤立的守卫者们保持联络。",kw={"安威玛尔","寒脊山谷","丹莫罗","格瑞林·白须","信件投递","斯登·粗臂","塔林·锐眼"},ang={["faction:Alliance"]="寒脊山谷的每一个哨所都在保障丹莫罗安全方面发挥着作用，因此可靠的通信对于早期的军事协调至关重要。",["race:Dwarf"]="在哨所之间传递消息凸显了铁炉堡矮人团结的精神，确保了即使是偏远山谷的侦察兵也能与他们的部族保持联系。",["race:Gnome"]="作为诺莫瑞根陷落后在丹莫罗的客人们和盟友，协助维持通讯线路加强了与当地矮人守卫者的信任。"},sec={{t="雪中信使",b="即使在最平静的季节，寒脊山谷的生活依然与世隔绝。当冬季的信使成功穿过山口，将丹莫罗其他地区的信件送达时，信件会在安威玛尔迅速堆积。斯登·粗臂忙于处理当地的补给问题和安保工作，他更倾向于让四处游荡的新兵沿着西面的道路把这些包裹送走，而不是让重要的消息在厅堂里发霉。"},{t="边境哨所",b="预定的收件人塔林·锐眼在西面的冰封湖旁守望，观察穴居人的动向和危险的野生生物。即使在寒冷的地带，来自铁炉堡和周边哨所的消息依然弥足珍贵。然而，在严酷的山地条件下分拣信件很难做到尽善尽美，寄给不同侦察兵的信件往往会被放在同一个包裹里。"}},faq={{q="是谁发布了信件投递任务？",a="斯登·粗臂在安威玛尔外给你发布了投递任务。他收到了一摞刚穿过山口送达的信件，但无法腾出时间亲自离开岗位去分发它们。",al={"任务发布者","谁发布了寒脊山谷的信件投递任务","斯登·粗臂的任务"}},{q="塔林·锐眼在哪里？",a="塔林·锐眼驻扎在安威玛尔的西面，就在寒脊山谷冰封湖旁的路边。",al={"塔林·锐眼在哪里","塔林·锐眼的位置","寻找塔林·锐眼"}},{q="那一摞信件都是给塔林的吗？",a="不是。当塔林仔细检查包裹时，他发现其中有一封信是寄给格瑞林·白须的，他此时正驻扎在山谷附近。",al={"信件全是给塔林的吗","格瑞林·白须的信","寄错的信件"}},{q="为什么斯登需要冒险者来送信？",a="由于安威玛尔正积极应对穴居人的入侵和当地的威胁，像斯登这样的矮人守卫被繁重的后勤和防御职责束缚住了。过往的旅人和年轻的新兵是向偏远哨所发送信件最快捷的方式。",al={"为什么要送信","为什么斯登不亲自去送信","信件投递职责"}},{q="这个任务会引出其他任务吗？",a="是的。在完成投递后，塔林会让你把那封寄错的信带给格瑞林·白须，这是信件投递任务链的第二部分。",al={"后续任务","信件任务链","信件投递的后续"}},{q="这些信件最初来自哪里？",a="这些信件穿过了通往寒脊山谷的山口，从丹莫罗更广阔的土地和铁炉堡被送进了这个隐蔽的盆地。",al={"信件来自哪里","信件来源"}}},fp="30,181,21.258.0,17.299.0,29.159.0,31.99.0,52.86.1,49.173.0,36.124.1,43.108.0"}
P.entries["quest:234"] = {n="寒脊山谷的送信任务",s="这项差事完成了一次横穿寒脊山谷积雪漂流的信使任务。将信件从登山者塔林·锐眼手中通过东南方向的道路送达，能确保格瑞林·白须与矮人主城保持联系。",h="这项差事完成了一次横穿寒脊山谷积雪漂流的信使任务。将信件从登山者塔林·锐眼手中通过东南方向的道路送达，能确保格瑞林·白须与矮人主城保持联系。",kw={"寒脊山谷","信使","丹莫罗","格瑞林·白须","铁炉堡","信件投递","塔林·锐眼"},ang={["faction:Alliance"]="通过险峻雪路的可靠信使路线，让偏远的联盟侦察兵能够获得命令和重要的情报。",["race:Dwarf"]="丹莫罗的每一个前哨站都依赖铁炉堡麦格尼国王的驻地发来的指令，以保持王国防御的协调一致。"},sec={{t="通往山脉的纽带",b="即使在寒脊山谷这样与世隔绝的盆地中，新闻和正式信函也必须能够传达。虽然安威玛尔是山谷的行政中心，但驻扎在小径沿线的野外侦察兵和哨兵仍然依靠徒步信使在山口与铁炉堡之间传递消息。"},{t="给白须的口信",b="格瑞林·白须在塔林·锐眼岗哨东南方的道路下驻守着一个小营地。为了抵御严寒和穴居人不断的骚扰，驻扎在这些偏远岗哨的资深登山者们依赖定期的信函来了解丹莫罗以及王国各地的最新局势。"}},faq={{q="格瑞林·白须是谁？",a="格瑞林·白须是一位矮人老兵，驻扎在寒脊山谷东南道路旁的一个前哨站。他负责监视山谷道路，并防范穴居人和野兽等当地威胁。",al={"格瑞林","格瑞林·白须信息","格瑞林是谁"}},{q="这封信是从哪里发出的？",a="这封信是从矮人主城铁炉堡发出的。它被带入寒脊山谷，由当地的信使和哨兵沿着山口步行送达，最后到达收件人手中。",al={"信件来源","铁炉堡信件","信件寄送者"}},{q="为什么这里要靠步行投递信件？",a="寒脊山谷被陡峭、冰封的山峰环绕，与丹莫罗的主要道路隔绝。由于没有直达偏远野外营地的狮鹫航线，值得信赖的旅行者和登山者便以徒步方式在各前哨站之间传递信件。",al={"为何步行投递","为何送信","寒脊山谷没有信箱"}},{q="格瑞林·白须的营地在哪里？",a="他的营地位于穿过寒脊山谷的东南道路更远方，越过了上山口的狩猎和侦察区。",al={"格瑞林营地位置","格瑞林·白须位置","寻找格瑞林"}},{q="是谁把要送给格瑞林的信交出来的？",a="塔林·锐眼，一位驻扎在山口的资深猎人和侦察兵，在信件从安威玛尔附近的初级集结地送出后，将其转交给了信使。",al={"谁给了信","塔林·锐眼职责","谁开始任务"}},{q="格瑞林收到信后会做什么？",a="一旦格瑞林收到来自铁炉堡的消息，他就会将注意力转向威胁山谷的紧迫危险，通常会指引新兵协助处理当地霜鬃巨魔和穴居人的入侵。",al={"送信后下一步","格瑞林后续任务","投递邮件后"}}},fp="30,185,22.157.0,19.257.0,25.155.0,32.162.0,35.200.0,42.147.0,47.130.0,44.144.0"}
P.entries["quest:235"] = {n="灰谷狩猎",s="这份由奥格瑞玛的公告员高拉克发布的指令，召集了刚刚起步的部落冒险者前往贫瘠之地以北，深入灰谷的古老森林。玩家需前往碎木岗哨向塞娜尼·雷心报到，参与正在进行的狩猎，并加强部落不断扩张的前沿阵地。",h="这份由奥格瑞玛的公告员高拉克发布的指令，召集了刚刚起步的部落冒险者前往贫瘠之地以北，深入灰谷的古老森林。玩家需前往碎木岗哨向塞娜尼·雷心报到，参与正在进行的狩猎，并加强部落不断扩张的前沿阵地。",kw={"灰谷","贫瘠之地","高拉克","狩猎","奥格瑞玛","塞娜尼","碎木岗哨","雷心"},ang={["class:Hunter"]="灰谷茂密的林冠和危险的野兽，为响应塞娜尼·雷心号召的志向远大的追踪者提供了终极的荒野磨练场。",["faction:Horde"]="深入灰谷的行军考验着新统一的部落，能否从杜隆塔尔干旱的岩石地带，向资源丰富却充满敌意的异国土地扩张。",["race:Tauren"]="在塞娜尼·雷心麾下服役，使牛头人冒险者能将他们对伟大狩猎的崇敬带入这片未被驯服的北方森林。"},sec={{t="荒野的呼唤",b="奥格瑞玛充满了尚武的狂热，但这座年轻的城市需要大量的木材、肉类和安全的贸易路线来维持其发展。公告员高拉克作为部落最高指挥部的传声筒，引导经验丰富的流浪者和新兵参与各种活跃的战役。对于在杜隆塔尔和贫瘠之地初出茅庐的勇士来说，灰谷的古老林地是考验荣耀与生存的下一处磨练场。"},{t="充满危险的边境",b="跨过贫瘠之地的北部边界，旅行者便直接进入了灰谷。部落在此设有两处主要据点：位于东部森林的碎木岗哨，以及西海岸的佐拉姆加前哨站。塞娜尼·雷心在碎木岗哨协调作战，组织追踪者和猎人去驯服这片野兽横行的林冠，并抵御那些阻挠部落主张的敌对暗夜精灵哨兵。"}},faq={{q="谁发布了这个任务？我在哪里可以找到他？",a="公告员高拉克在部落主城奥格瑞玛内提供该任务。他作为一名军官，号召有能力的冒险者去承担杜隆塔尔边境之外的作战任务。",al={"任务发放者","高拉克在哪里","谁发布灰谷狩猎任务"}},{q="碎木岗哨在哪里？",a="碎木岗哨位于贫瘠之地正北方的灰谷东部，坐落在通往艾萨拉的森林主干道沿线。",al={"碎木岗哨位置","碎木岗哨在哪里","如何前往碎木岗哨"}},{q="塞娜尼·雷心是谁？",a="塞娜尼·雷心是一位驻扎在碎木岗哨的经验丰富的牛头人追踪者。她负责指挥灰谷全境的狩猎工作，并评估想要参加当地试炼的冒险者。",al={"塞娜尼是谁","塞娜尼·雷心位置","任务完成npc"}},{q="灰谷狩猎的目的是什么？",a="这项狩猎使部落能够获得野味、收集珍贵的毛皮，并消灭那些危及碎木岗哨周边巡逻队和附近伐木作业的顶级掠食者。",al={"为何在灰谷狩猎","灰谷狩猎剧情","部落在灰谷的目标"}},{q="部落在灰谷还有哪些前哨站？",a="除了碎木岗哨外，部落在森林最西端的佐拉姆海岸也设有一处营地。",al={"部落在灰谷的基地","佐拉姆海岸据点","灰谷前哨站"}},{q="这个任务需要战斗吗？",a="不需要。这个任务纯粹是一个指引任务，引导你安全地从奥格瑞玛穿过贫瘠之地，去向塞娜尼·雷心报到。",al={"这个任务有战斗吗","需要战斗吗","简单交接任务"}}},fp="18,189,17.306.0,22.356.0,48.124.0,27.113.0,27.165.0,42.149.0,53.100.0,35.123.0"}
P.entries["quest:2359"] = {n="克拉文之塔",s="Klaven's Tower是联盟潜行者在西部荒野的一项秘密SI:7渗透任务。特工们需根据密探吉尔妮提供的情报，扒窃一把钥匙，潜入戒备森严的迪菲亚潜行者前哨站，并取回与某种非自然实验有关的险恶文件。",h="Klaven's Tower是联盟潜行者在西部荒野的一项秘密SI:7渗透任务。特工们需根据密探吉尔妮提供的情报，扒窃一把钥匙，潜入戒备森严的迪菲亚潜行者前哨站，并取回与某种非自然实验有关的险恶文件。",kw={"密探吉尔妮","迪菲亚潜行者","暮色森林宝箱","klaven mortwake","klaven's tower","mathias shaw","毒药","si:7","西部荒野","赞吉尔"},ang={["class:Rogue"]="这次秘密渗透是联盟潜行者成长的必经之路，要求他们精通潜行、扒窃、开锁，并能利用敌人的身体弱点。",["faction:Alliance"]="揭开塔楼中迪菲亚潜行者的阴谋表明，这些叛军不仅仅是不满的石匠，更是一群危险的阴谋家，他们愿意与丛林巨魔和黑暗炼金术勾结来威胁王国。",["race:Human"]="暴风城的人类保卫者看到他们曾经的同胞在西部荒野被扭曲成无脑的亡灵傀儡，感到无比惊恐。"},sec={{t="西部荒野的秘密监视",b="在西部荒野的东南边缘，靠近河流且位于匕首岭的北面，矗立着一座孤零零的石塔，这里被迪菲亚潜行者所占据。尽管迪菲亚潜行者的那些人类盗贼和暴徒在平原上随处可见，但密探吉尔妮在独自监视数周后，还是发现了异样。最近，一批奇怪的货物直接从暮色森林的阴影丛林中运抵此地，随行护送的还有一些不同于普通强盗的畸形怪物守卫。"},{t="高塔与尖刺守卫",b="这座塔由Klaven Mortwake指挥，并由呼吸沉重而粗糙的诡异变异守卫把守。在这些蹒跚而行的守卫中，有一个被铁刺穿透的巨大僵尸，它的身上带着迪菲亚塔楼钥匙。窃取钥匙需要安静和技巧，这使特工能够绕过地面防御，溜进据点的上层，并撬开加锁的暮色森林宝箱。"},{t="赞吉尔的药剂",b="从宝箱中找回的Klaven Mortwake的个人日记，详细记录了一个将迪菲亚潜行者、荆棘谷地精和荆棘谷丛林巨魔联系在一起的险恶合作。文件揭示，巫医赞吉尔发现了一种足以制造出毫无思想、唯命是从的亡灵傀儡的炼金毒药。对于马迪亚斯·肖尔和SI:7来说，这一发现揭露了迪菲亚潜行者不断膨胀的野心，也让潜行者必须深入了解各种毒药。"}},faq={{q="Klaven's Tower位于哪里？",a="Klaven's Tower位于西部荒野的东南边缘，靠近河流，就在匕首岭的北面。它作为迪菲亚潜行者的一处安全加固堡垒。",al={"klavens tower位置","klavens tower在哪里","西部荒野的迪菲亚塔楼位置"}},{q="谁是密探吉尔妮？",a="密探吉尔妮是暴风城情报机构SI:7的一名特工。她在附近的营地秘密监视Klaven's Tower长达数周，追踪奇怪的货物并策划潜入行动。",al={"密探吉尔妮","谁提供klaven's tower任务","西部荒野的潜行者是谁"}},{q="Klaven's Tower的守卫有什么特别之处？",a="与迪菲亚潜行者常见的强盗不同，把守塔楼的守卫是变异的亡灵傀儡。他们是通过运送到西部荒野的异域炼金药剂制造出来的无脑劳工。",al={"为什么守卫是僵尸","klaven塔楼守卫","塔楼守卫是什么"}},{q="迪菲亚潜行者是如何获得亡灵仆从的？",a="迪菲亚潜行者获得了一种由荆棘谷的丛林巨魔巫医赞吉尔调制的特种毒药。通过与荆棘谷地精的交易，这种毒药被进口到此，用于将活人转化为唯命是从的傀儡。",al={"迪菲亚潜行者如何得到僵尸","为什么迪菲亚潜行者有亡灵","赞吉尔与迪菲亚潜行者的联系"}},{q="Klaven Mortwake是谁？",a="Klaven Mortwake是驻扎在塔楼的一名迪菲亚潜行者高级监工。他负责接收来自暮色森林的黑暗货物，并留有一本详细记录其险恶炼金术的私人日记。",al={"klaven mortwake背景故事","klaven mortwake是谁","klaven"}},{q="为什么马迪亚斯·肖尔关心找回的日记？",a="马迪亚斯·肖尔需要关于迪菲亚潜行者联盟和危险外国代理人的实时情报。得知赞吉尔的巨魔能够通过毒药制造亡灵，这让SI:7意识到暴风城正面临一个严重的威胁，迫使该机构对其特工进行全面的毒药技能训练。",al={"为什么马迪亚斯·肖尔想要日记","si:7赞吉尔毒药","马迪亚斯·肖尔与klaven"}}},fp="14,146,22.434.0,30.342.1,19.366.2,32.145.0,21.189.0,48.164.1,41.214.1,23.160.0,55.252.1"}
P.entries["quest:2360"] = {n="Mathias and the Defias",s="军情七处报告称，西部荒野的迪菲亚活动异常猖獗。你奉命前往一座废弃的联盟瞭望塔附近，接受密探吉尔妮的汇报。",h="军情七处报告称，西部荒野的迪菲亚活动异常猖獗。你奉命前往一座废弃的联盟瞭望塔附近，接受密探吉尔妮的汇报。",kw={"密探吉尔妮","迪菲亚","马西亚斯","赤脊山","哨兵岭","军情七处","瞭望塔","西部荒野"},ang={["faction:Alliance"]="迪菲亚占据了西部荒野一座废弃的联盟瞭望塔，并将其用作走私据点。"},sec={{t="瞭望塔",b="迪菲亚占据了哨兵岭东南方一座废弃的联盟瞭望塔。军情七处报告称，他们正以此为据点，走私来自赤脊山补给线的货物。你奉命前往西部荒野，找到藏身在塔附近的密探吉尔妮，听取她的汇报。"}},faq={{q="西部荒野发生了什么？",a="军情七处报告称，西部荒野的迪菲亚活动异常猖獗。迪菲亚占据了一座废弃的联盟瞭望塔，并利用它走私来自赤脊山补给线的货物。",al={"西部荒野的迪菲亚","西部荒野迪菲亚活动"}},{q="迪菲亚的据点在哪里？",a="迪菲亚占据了哨兵岭东南方一座废弃的联盟瞭望塔。",al={"迪菲亚瞭望塔","他们的据点在哪里"}},{q="密探吉尔妮是谁？",a="密探吉尔妮是军情七处派驻此地的密探，你奉命前往塔附近找到她，听取汇报。",al={"吉尔妮","吉尔妮是谁"}},{q="军情七处要我做什么？",a="军情七处派你前往西部荒野，找到藏身在塔附近的密探吉尔妮，听取汇报。",al={"军情七处任务","寻找吉尔妮"}},{q="迪菲亚在走私什么？",a="迪菲亚正在走私来自赤脊山补给线的货物。",al={"迪菲亚货物","赤脊山补给"}}},fp="22,143,15.264.0,30.173.0,25.80.0,21.85.0,29.98.0,30.62.0"}
P.entries["quest:237"] = {n="保卫国王的领土",s="这项军事任务委派联盟冒险者代表巡山人格拉维戈，去削弱洛克莫丹南部的穴居人攻势。由于矮人正规军被困在遥远的联盟战线上，当地前哨站必须依靠志愿者来清除危险的碎石怪头骨重锤和先知，以免国王谷被攻陷。",h="这项军事任务委派联盟冒险者代表巡山人格拉维戈，去削弱洛克莫丹南部的穴居人攻势。由于矮人正规军被困在遥远的联盟战线上，当地前哨站必须依靠志愿者来清除危险的碎石怪头骨重锤和先知，以免国王谷被攻陷。",kw={"格拉维戈","铁炉堡","洛克莫丹","巡山人","先知","头骨重锤","碎石怪","穴居人","国王谷"},ang={["faction:Alliance"]="这项任务揭示了更广泛的联盟战争所带来的沉重代价，表明保卫遥远的领土是如何让核心成员的家园变得易受当地威胁的。",["race:Dwarf"]="对于矮人来说，保卫国王谷是个人的使命：这片土地纪念着铁炉堡最伟大的统治者，而当你的族人在遥远的战场上流血时，让穴居人的脚践踏这里是极其苦涩的屈辱。"},sec={{t="薄弱的防线",b="驻扎在通往丹莫罗的南部山口沿线的巡山人兵力严重不足。由于国王麦格尼·铜须将大量矮人军事力量投入到了更广阔的联盟前线，像国王谷守望塔这样的前哨站缺乏正规步兵。巡山人格拉维戈依靠外来的志愿者对碎石怪之谷进行积极的破坏性突袭，在当地驻军等待永远不会到来的增援时，将这些地底入侵者阻挡在外。"},{t="碎石怪萨满与拳手",b="碎石怪穴居人并非漫无目的游荡的野兽；他们的战团通过野蛮武力和原始的元素魔法进行协调。格拉维戈将目标对准了该部落的精英战士——头骨重锤，以及他们的神秘领袖——先知。消灭这些前线指挥官可以破坏部落的势头，使他们南部的营地陷入混乱，并阻止其对铁炉堡道路的大规模推进。"},{t="来自前线的噩耗",b="在你报告成功后，格拉维戈带来了一个令人清醒的消息：承诺的矮人增援部队不会来了。遥远联盟前线的重大伤亡耗尽了铁炉堡的预备队，使得洛克莫丹完全只能依靠当地的巡山人和路过的雇佣兵来保护王国的腹地。"}},faq={{q="巡山人格拉维戈在哪里？",a="巡山人格拉维戈驻扎在穿越国王谷的道路南侧的守望塔内，守卫着连接洛克莫丹和丹莫罗的山口。",al={"格拉维戈位置","格拉维戈在哪里","格拉维戈任务提交"}},{q="为什么矮人巡山人兵力如此不足？",a="国王麦格尼·铜须已经将铁炉堡的大部分常备军投入到了海外更广阔的联盟前线。随着其他地方伤亡人数的增加，像洛克莫丹这样的边境哨所只剩下少量的留守人员，被迫依靠四处旅行的志愿者。",al={"为什么没有矮人卫兵","增援部队在哪里","铁炉堡军队洛克莫丹"}},{q="在哪里可以找到碎石怪头骨重锤和先知？",a="他们主要聚集在国王谷以东的碎石怪之谷的南部营地。在洛克湖内的最北端岛屿上，也能发现少量他们活动的踪迹。",al={"碎石怪头骨重锤位置","碎石怪先知位置","穴居人在哪里"}},{q="为什么要特别针对头骨重锤和先知？",a="头骨重锤是碎石怪部落的主要先锋突击部队，而先知则使用原始魔法并指挥低级穴居人。消灭这两者将剥夺入侵部队的武力和神秘协调能力。",al={"为什么杀先知","为什么要杀头骨重锤","穴居人目标"}},{q="格拉维戈接下来会派你去哪里？",a="格拉维戈指示你去找驻扎在国王谷南侧守望塔的巡山人沃尔班，协助进行下一阶段的山谷防御工作。",al={"格拉维戈后续任务","沃尔班是谁","保卫国王谷之后"}}},fx={c78d8208={q="巡山人格拉维戈为什么希望你做这件事？",a="巡山人格拉维戈正试图为洛克莫丹的守军争取宝贵时间。碎石穴居人不断向南部山谷推进，而矮人士兵在联盟远方的战场上也同样急缺。通过削弱入侵者的兵力，他希望守住南部隘道，直到铁炉堡的援军赶到。",al={"为什么要杀穴居人","格拉维戈的动机","保卫国王领地的动机"}}},fp="30,199,14.366.0,34.347.0,27.248.1,39.150.0,48.213.0,61.184.0,48.179.0,35.130.1"}
P.entries["quest:2378"] = {n="寻找碎手氏族",s="“寻找碎手氏族”是一个旅程任务，旨在指引被遗忘者盗贼从提瑞斯法林地跨越海洋前往杜隆塔尔。在死亡猎手的指示下，这些初出茅庐的盗贼前往奥格瑞玛阴暗的底层，向碎手氏族学习专业的技巧。",h="“寻找碎手氏族”是一个旅程任务，旨在指引被遗忘者盗贼从提瑞斯法林地跨越海洋前往杜隆塔尔。在死亡猎手的指示下，这些初出茅庐的盗贼前往奥格瑞玛阴暗的底层，向碎手氏族学习专业的技巧。",kw={"cleft of shadow","死亡猎手","梅内特·卡卡德","奥格瑞玛","盗贼任务","碎手氏族","申苏尔"},ang={["class:Rogue"]="这个任务将本地训练与部落更广泛的犯罪和秘密网络联系起来，向盗贼介绍了卡利姆多的主要地下训练师。",["faction:Horde"]="这项任务说明了部落的合作不仅限于前线的步兵和萨满，还展示了奥格瑞玛和幽暗城特务机构之间深度的协调。",["race:Undead"]="对于年轻的被遗忘者盗贼来说，这标志着从在洛丹伦对抗当地天灾余孽，正式过渡到融入杜隆塔尔的部落核心区域。"},sec={{t="暗影联盟",b="虽然被遗忘者在死亡猎手内部培养了自己的秘密组织，但他们与部落的结盟也开启了在更黑暗的领域进行合作的途径。梅内特·卡卡德（Mennet Carkad）在提瑞斯法林地见证了一名盗贼证明了自己的价值，意识到他们需要更广阔的教导。他指引这些前途无量的暗影去寻找奥格瑞玛的碎手氏族，依靠洛丹伦亡灵特工与卡利姆多兽人刺客公会之间静默的伙伴关系。"},{t="进入暗影裂口",b="这段旅程终结于暗影裂口深处，这是隐藏在奥格瑞玛地下的洞穴，术士、盗贼和恶魔使者在此进行着那些地表居民不愿直视的交易。申苏尔（Shenthul），一名碎手氏族的训练师，正等在那里。这位粗鲁的巨魔并没有因名声而感到震撼，他以严苛的怀疑态度评估着刚抵达的亡灵特工，急于测试这位特使是拥有真正的狡诈，还是仅仅浪费了跨越无尽之海的航程。"}},faq={{q="谁发布了“寻找碎手氏族”任务？",a="梅内特·卡卡德，幽暗城Rogues' Quarter的一名死亡猎手训练师，会在盗贼在提瑞斯法林地证明了他们的基础技能后发布此任务。",al={"谁开启寻找碎手氏族","梅内特·卡卡德任务","谁派我去奥格瑞玛"}},{q="申苏尔在哪里？",a="申苏尔位于暗影裂口，那是奥格瑞玛中央道路下方昏暗的深渊。",al={"寻找申苏尔","申苏尔位置","申苏尔在奥格瑞玛哪里"}},{q="死亡猎手和碎手氏族之间是什么关系？",a="死亡猎手充当被遗忘者的情报网络和刺客公会，而碎手氏族则在奥格瑞玛为部落担任类似的秘密角色。他们作为正式盟友进行合作，在部落各阵营之间共享高级训练和秘密契约。",al={"死亡猎手和碎手氏族","被遗忘者盗贼兽人盗贼","为什么要派往奥格瑞玛"}},{q="为什么申苏尔说我平庸无奇？",a="碎手氏族将身体韧性和冷酷的狡诈视为最重要的品质。申苏尔经常侮辱和贬低新人，以粉碎他们的自尊，从而测试他们是否有毅力去承受严格的刺客训练。",al={"申苏尔对话","为什么申苏尔很刻薄","申苏尔完成文本"}},{q="找到申苏尔之后会发生什么？",a="申苏尔会直接让特工投入工作，提供任务“赞多赞”，并最终将其派往南部的棘齿城，在贫瘠之地执行实地作战任务。",al={"寻找碎手氏族之后是什么","申苏尔之后的下一个任务","碎手氏族任务线"}},{q="非被遗忘者盗贼可以接到这个任务吗？",a="不能。“寻找碎手氏族”是被遗忘者的特殊版本，由死亡猎手发布。在杜隆塔尔活动的兽人和巨魔盗贼会接到一个类似的过渡任务，名为“前往奥格瑞玛！”。",al={"兽人盗贼寻找碎手氏族","巨魔版本","前往奥格瑞玛替代"}}},fp="23,191,19.344.0,24.383.0,44.141.0,26.88.0,74.251.0,38.209.0,37.114.0,39.148.0"}
P.entries["quest:2379"] = {n="赞杜沙",s="这项任务指引有前途的部落潜行者前往奥格瑞玛的暗影裂口深处，向赞多赞报到。受训练师申苏尔派遣，初学者由此迈出加入破碎之手潜行组织并学习其隐秘技巧的第一步。",h="这项任务指引有前途的部落潜行者前往奥格瑞玛的暗影裂口深处，向赞多赞报到。受训练师申苏尔派遣，初学者由此迈出加入破碎之手潜行组织并学习其隐秘技巧的第一步。",kw={"cleft of shadow","开锁","奥格瑞玛","潜行者","破碎之手","申苏尔","潜行","维尼克斯","赞多赞"},ang={["class:Rogue"]="这项任务标志着你正式被引入破碎之手的秘密机构，使你从一个未经训练的持刀斗士转变为一名受认可的部落特工。",["faction:Horde"]="虽然大酋长经常谈论荣誉和正面突击，但破碎之手提供了必不可少的间谍活动和秘密脏活，保护着年轻的部落免受隐蔽威胁的侵害。"},sec={{t="走进暗影",b="奥格瑞玛看起来是一座崇尚蛮力和军事纪律的堡垒，但统治者们深知仅靠蛮力无法赢得每一场战争。在暗影裂口那昏暗的地下深处，活跃着破碎之手，这是一个为部落处理间谍、破坏和窃取活动的秘密公会。当潜行者训练师申苏尔认为某个初学者展现出足够的潜力时，他会派遣其直接向赞多赞报到，接受专业的特工训练。"},{t="证明自己的价值",b="赞多赞不会随随便便就对每个溜进洞穴的潜行者新手表示尊重。接近他意味着正式开始学习更高级的隐秘艺术，从潜行、掩护和盗窃等细腻的技巧开始。与赞多赞会面是连接街头鲁莽小偷与有组织情报特工的桥梁，让潜行者为首都红岩墙壁之外充满风险的实地工作做好准备。"}},faq={{q="赞多赞是谁？",a="赞多赞是暗影裂口的一名潜行者训练师，也是破碎之手在奥格瑞玛的联络人。他负责评估新兵，并指导他们进行实用的潜行、盗窃和特工技能训练。",al={"赞多赞","赞多赞是谁","赞多赞 暗影裂口"}},{q="为什么申苏尔要派潜行者去见赞多赞？",a="申苏尔能看出一个初出茅庐的潜行者何时已经不再满足于基本的斗殴，需要作为破碎之手特工接受专业训练。赞多赞负责监督那些进行秘密外勤任务所必需的盗窃和开锁教学。",al={"为什么要找赞多赞谈话","申苏尔 赞多赞","任务目的"}},{q="奥格瑞玛的破碎之手是什么组织？",a="破碎之手最初是一个来自德拉诺、以仪式性自残而闻名的残酷兽人氏族，在杜隆塔尔，他们已经演变成部落负责情报和暗杀的秘密机构。他们在奥格瑞玛的暗影中运作，从事间谍、投毒和侦察工作。",al={"什么是破碎之手","破碎之手 奥格瑞玛","部落潜行者 破碎之手"}},{q="这个训练链下一步通往哪里？",a="向赞多赞报到后，他会指引你前往贫瘠之地海岸的棘齿城，去咨询一位名叫维尼克斯的地精联络人，从而开始实际的开锁外勤工作。",al={"后续任务","赞多赞之后做什么","棘齿城的维尼克斯"}},{q="我在哪里可以找到赞多赞？",a="他潜伏在暗影裂口之中，那是奥格瑞玛中心下方挖掘出的深邃洞穴网络，术士、暗影牧师和潜行者特工们都躲开白昼在此聚集。",al={"赞多赞位置","赞多赞在哪里","如何找到赞多赞"}},{q="为什么赞多赞见到我时会道歉？",a="赞多赞在你到来之前很可能心存疑虑，怀疑你的胆识。看到你站在他面前准备接受训练，这迫使他承认你的决心，并收回他最初的质疑。",al={"为什么赞多赞道歉","赞多赞完成对话"}}},fp="9,185,23.327.0,19.393.0,17.180.0,47.198.0,40.256.0,41.165.1,27.172.0,45.155.0"}
P.entries["quest:2380"] = {n="向奥格瑞玛进发！",s="《前往奥格瑞玛！》是一个入门级的召唤任务，旨在将一名正在成长的部落潜行者从剃刀岭派遣到主城。在执行卡普拉克的命令时，这位新兵被派遣到地表之下的Cleft of Shadow，去向申苏尔报道，并深入Shattered Hand的网络之中。",h="《前往奥格瑞玛！》是一个入门级的召唤任务，旨在将一名正在成长的部落潜行者从剃刀岭派遣到主城。在执行卡普拉克的命令时，这位新兵被派遣到地表之下的Cleft of Shadow，去向申苏尔报道，并深入Shattered...",kw={"cleft of shadow","卡普拉克","剃刀岭","潜行者","shattered hand","申苏尔","前往奥格瑞玛"},ang={["class:Rogue"]="这项任务标志着你正式加入了主城的隐秘网络，使你超越了粗糙的边境冲突，开始接触由申苏尔监督的毒药、盗窃和欺诈技艺。",["faction:Horde"]="申苏尔表达的安静不满凸显了萨尔荣耀的新道路与奥格瑞玛地下幸存的旧氏族组织阴暗残余之间的摩擦。"},sec={{t="暗影的召唤",b="在杜隆塔尔磨练了一番之后，潜行者新手们终会引起更高级别接头人的注意。在剃刀岭，卡普拉克直言不讳地承认，一名特工虽然稚嫩，但其初露锋芒的才华已经引起了注意。特工不再留在这片红色的山岩之间，而是被指引向北，前往奥格瑞玛那洞穴般的巷道。"},{t="在萨尔的注视下",b="在地下的Cleft of Shadow与申苏尔见面，揭示了部落建国理念之下更深层的紧张关系。申苏尔毫不掩饰他对大酋长萨尔政治改革的警惕。对于Shattered Hand来说，蛮力和公然对抗永远不足以保障他们的利益；生存和影响力需要耐心、隐秘行动和精巧的欺诈。"}},faq={{q="谁派我执行这个任务？",a="卡普拉克，驻扎在剃刀岭的一名潜行者训练师，在认定你的技能已经引起了奥格瑞玛上级的注意后，发出了这份召唤。",al={"任务发布者","谁发布前往奥格瑞玛任务","卡普拉克任务"}},{q="我在哪里可以找到申苏尔？",a="申苏尔位于Cleft of Shadow，那是奥格瑞玛深处开凿出的阴暗地下区域，潜行者、术士和其他流亡者们聚集于此。",al={"申苏尔位置","申苏尔在哪里","cleft of shadow申苏尔"}},{q="Shattered Hand在奥格瑞玛的议程是什么？",a="Shattered Hand在部落内部充当着情报和暗杀公会的角色。虽然名义上是新都的一部分，但像申苏尔这样的领导人仍然对萨尔的荣耀改革保持警惕，并强调通过隐秘行动来维持影响力和生存。",al={"shattered hand动机","为什么shattered hand在奥格瑞玛","shattered hand与萨尔"}},{q="为什么我偏偏在这个阶段被派去？",a="在基础侦察和前哨战中证明自己能力的新手特工，会被引入更正式的公会职责，首先从主城分配的开锁和隐秘外勤任务开始。",al={"16级潜行者任务","为什么现在去奥格瑞玛","潜行者训练召唤"}},{q="这个任务和“寻找破碎之手”有什么不同吗？",a="两者都是将潜行者引向奥格瑞玛的申苏尔的入门引导任务；根据你受训或接受命令的地点不同，你会收到其中之一来推进相同的训练链。",al={"寻找破碎之手与前往奥格瑞玛对比","备选引导任务"}},{q="向申苏尔报道后会发生什么？",a="申苏尔会测试你的能力并引导你继续完成后续任务链，介绍像Zando'zan这样的联络人，并最终涉及在棘齿城与地精联络人的隐秘工作。",al={"前往奥格瑞玛后的下一个任务","申苏尔提供什么"}}},fp="13,151,24.223.0,27.304.1,27.113.0,25.134.0,49.198.0,47.188.0,54.150.0,41.169.0"}
P.entries["quest:2381"] = {n="抢劫海盗",s="这项由棘齿城的卑鄙的维尼克斯委派的任务，是考验部落潜行者新人的成人礼，目标是南海海盗。潜行者需要潜入海盗船潮汐剃刀号，避开这些亡命之徒，撬开货舱的锁，并利用地精科技压制一只可怕的禽类守卫，从而夺取南海宝藏。",h="这项由棘齿城的卑鄙的维尼克斯委派的任务，是考验部落潜行者新人的成人礼，目标是南海海盗。潜行者需要潜入海盗船潮汐剃刀号，避开这些亡命之徒，撬开货舱的锁，并利用地精科技压制一只可怕的禽类守卫，从而夺取南海宝藏。",kw={"大饼干","开锁","掠夺海盗","波莉","棘齿城","南海海盗","南海宝藏","蓟叶茶","潮汐剃刀号","卑鄙的维尼克斯"},ang={["class:Rogue"]="这项成人礼教授了在压力下开锁的必要技巧，并奖励了一批珍贵的蓟叶茶，这使它成为任何为部落效力的特工不可或缺的里程碑。",["faction:Horde"]="破碎之手利用在棘齿城的中立地精关系，来测试那些针对威胁贫瘠之地海岸的南海海盗的准战地特工。",["profession:Cooking"]="该任务的报酬是蓟叶茶，一种烹饪天赋出众的潜行者比任何普通饮料都更珍视的草药能量补剂。"},sec={{t="潜行与利刃的考验",b="对于破碎之手的一名潜行者新人来说，单纯的蛮力毫无意义，必须还要有精湛的技巧。卑鄙的维尼克斯是一位在棘齿城活动的当地地精联络人，他提供了这项实地测试。他指引潜行者前往南边贫瘠之地那被烈日炙烤的海岸，那里停泊着一艘由南海海盗把守的船只——潮汐剃刀号。任务看似简单：在不被察觉的情况下潜入船只，闯入海盗教导他们自己的窃贼的巢穴，撬开深层货舱里的保险箱，然后带回他们珍贵的战利品。"},{t="波莉与小玩意",b="想要拿到战利品，光有灵活的手指是不够的。维尼克斯警告说，之前的盗贼都是残肢断臂地被送回来的，这主要是因为负责守卫船只最底层货舱的守卫：一只极其凶残的鹦鹉，名叫波莉。为了对抗这只带翅膀的恐怖生物，维尼克斯提供了一种实验性装置，称为大饼干。当撬开海盗保险箱后将此物掷向那只凶恶的鸟时，这个小玩意会让野兽晕头转向并削弱其力量，将一场必死的绝境转化为一场可赢的对决。"}},faq={{q="卑鄙的维尼克斯是谁？",a="卑鄙的维尼克斯是一位常驻中立港口棘齿城的地精潜行者联络人。他与奥格瑞玛破碎之手的特工合作，通过派遣这些新晋窃贼潜入海盗领地练习开锁并收回被盗的财物，来对他们进行测试。",al={"维尼克斯","维尼克斯是谁","棘齿城地精潜行者任务"}},{q="潮汐剃刀号在哪里？",a="潮汐剃刀号停泊在棘齿城南面的贫瘠之地东海岸，隐匿在南海海盗的据点内。这艘船是海盗恶棍的基地和训练窝点。",al={"潮汐剃刀号位置","海盗船在哪里","南海海盗在哪里"}},{q="什么是大饼干，我该如何使用它？",a="大饼干是一种实验性的地精装置，由维尼克斯的奇思妙想装置分发。它被用来对付波莉，那只守卫在潮汐剃刀号腹部南海宝藏处的致命巨型鹦鹉，使用后会极大地削弱该野兽的力量，使其可以被击败。",al={"大饼干","什么是大饼干","如何打败波莉"}},{q="为什么船上的开锁区域很重要？",a="潮汐剃刀号的第二层甲板是南海海盗的训练室。那里存放着一系列会刷新的锁箱，潜行者可以在尝试下面主保险箱之前，在实地条件下练习他们的开锁技术。",al={"开锁练习","杂兵训练船","贫瘠之地开锁"}},{q="为什么这项任务对潜行者至关重要？",a="完成这次劫掠任务向破碎之手情报网证明了潜行者的价值。作为你那一份战利品，维尼克斯会奖励你一些蓟叶茶，这是一种极为珍贵的草药茶，可以迅速恢复潜行者的战斗能量。",al={"潜行者任务蓟叶茶","为什么要完成掠夺海盗","潜行者任务奖励"}},{q="波莉是谁？",a="波莉是南海海盗那只凶猛的看门鹦鹉，被安置在潮汐剃刀号的下层货舱里。如果不对其进行限制，除非使用地精科技将其削弱，否则这只鸟对缺乏经验的潜入者来说是致命的。",al={"波莉","巨型鹦鹉","潮汐剃刀号首领"}}},fp="25,224,27.362.0,19.325.1,27.216.0,32.163.0,40.232.0,52.168.0,40.176.0,13.187.0"}
P.entries["quest:2382"] = {n="棘齿城的维尼克斯",s="“棘齿城的维尼克斯”是一个部落潜行者任务，指引怀揣梦想的代理人离开奥格瑞玛，前往地精港口棘齿城。狂躁的巨魔赞多赞派遣特工南下，去协助一位名声不佳的地精，也就是卑鄙的维尼克斯。",h="“棘齿城的维尼克斯”是一个部落潜行者任务，指引怀揣梦想的代理人离开奥格瑞玛，前往地精港口棘齿城。狂躁的巨魔赞多赞派遣特工南下，去协助一位名声不佳的地精，也就是卑鄙的维尼克斯。",kw={"棘齿城","潜行者","碎手氏族","贫瘠之地","萨尔","维尼克斯","赞多赞"},ang={["class:Rogue"]="这趟旅程是部落潜行者训练中的关键一步，指引年轻的特工离开奥格瑞玛的安全区，进入中立的海盗领地。",["faction:Horde"]="碎手氏族在杜隆塔尔边境之外也维持着耳目，经常依靠像棘齿城这样的中立港口来处理敏感的合同。"},sec={{t="暗影中的先知",b="在奥格瑞玛大断崖那蜿蜒的裂隙中，潜行者行会正在暗中开展他们的行动。拜访赞多赞的特工们会听到他语无伦次的疯言乱语和不祥的预兆，包括大酋长萨尔被毒药和利刃暗杀的黑暗幻象。这位古怪的巨魔并没有解释他的预言，而是迅速将代理人们打发到贫瘠之地的港口城镇棘齿城。"},{t="棘齿城的麻烦解决者",b="中立港口棘齿城坐落在十字路口以东的海岸上，这里聚集了各种各样的恶棍、雇佣兵和技工。卑鄙的维尼克斯就在这个繁忙的避风港中运作，不过他对赞多赞的古怪行径并没有什么耐心。据维尼克斯所说，巨魔之前的招募人选都在海湾里那些掠食者出没的水域中落得个悲惨的下场。"}},faq={{q="是谁派你来棘齿城的？",a="赞多赞，一位与奥格瑞玛大断崖的碎手氏族有关联的巨魔，在脱口而出一些奇怪的幻象后，派你来执行这项差事。",al={"谁发布任务","任务发布者","赞多赞"}},{q="卑鄙的维尼克斯是谁？",a="卑鄙的维尼克斯是一位在地精港口城镇棘齿城活动的地精联络人。他负责处理贫瘠之地各地潜行者行动所需的秘密任务和机械补给。",al={"维尼克斯是谁","棘齿城维尼克斯","维尼克斯身份"}},{q="在我之前派去的特工发生了什么事？",a="根据维尼克斯的说法，赞多赞派出的前五名特工都失败了，最终在棘齿城外的海域成了鲨鱼的食物。",al={"之前的潜行者","鲨鱼饲料","其他招募人选"}},{q="赞多赞提到的关于萨尔的事是什么？",a="赞多赞声称他看到了一个幻象，萨尔被人从背后用毒匕首刺杀，但他很快就打住并转移了话题。",al={"萨尔预言","萨尔中毒","赞多赞萨尔幻象"}},{q="棘齿城在哪里？",a="棘齿城位于贫瘠之地的东海岸，就在十字路口的直接东面。它通过从怒水河向南延伸的道路与杜隆塔尔相连。",al={"棘齿城在哪里","寻找棘齿城","棘齿城位置"}},{q="见到维尼克斯之后接下来要做什么？",a="在见到维尼克斯后，他会指派你执行“掠夺劫掠者”任务，这需要潜入棘齿城南面海岸的南海海盗。",al={"下一个任务","维尼克斯之后","棘齿城后续"}}},fp="17,172,24.370.0,24.317.0,25.124.0,27.129.0,47.121.0,50.121.0,25.150.0,37.136.1"}
P.entries["quest:2383"] = {n="简易羊皮纸",s="你不在时，一封信送到了，寄信人可能是你的职业训练师弗朗恩。他正在试炼谷的大兽穴外等你。",h="你不在时，一封信送到了，寄信人可能是你的职业训练师弗朗恩。他正在试炼谷的大兽穴外等你。",kw={"职业训练师","大兽穴","弗朗恩","羊皮纸","简易羊皮纸","试炼谷"},sec={{t="弗朗恩的来信",b="羊皮纸上请你读完后去找弗朗恩交谈，他正在试炼谷的大兽穴外等你。"}},faq={{q="谁寄来了这封羊皮纸信？",a="看起来这封信是你的职业训练师弗朗恩寄来的。",al={"羊皮纸寄件人","谁写的"}},{q="我在哪里能找到弗朗恩？",a="弗朗恩在试炼谷的大兽穴外。",al={"弗朗恩在哪里","弗朗恩的位置"}},{q="弗朗恩想做什么？",a="羊皮纸上说，等你准备好后，弗朗恩有话要对你说。",al={"弗朗恩为什么找我","羊皮纸内容"}},{q="我该怎么处理这封羊皮纸信？",a="读完羊皮纸信后，去试炼谷找弗朗恩交谈。",al={"读羊皮纸","简易羊皮纸"}}},fp="16,121,20.128.0,23.66.0,23.52.0,21.43.0,36.66.0"}
P.entries["quest:239"] = {n="西泉要塞",s="治安官杜汉下令让可用的冒险者前往西方的西泉要塞，这座哨站守卫着艾尔文森林与西部荒野的边界。由于暴风城军队在王国各地兵力吃紧，瑞尼尔副队长和他的卫兵在没有正规增援的情况下，面临着来自好战的河爪豺狼人和流浪盗贼日益增长的压力。",h="治安官杜汉下令让可用的冒险者前往西方的西泉要塞，这座哨站守卫着艾尔文森林与西部荒野的边界。由于暴风城军队在王国各地兵力吃紧，瑞尼尔副队长和他的卫兵在没有正规增援的情况下，面临着来自好战的河爪豺狼人和流浪盗贼日益增长的压力...",kw={"瑞尼尔副队长","艾尔文森林","豺狼人","闪金镇","治安官杜汉","河爪","西泉要塞"},ang={["faction:Alliance"]="联盟的志愿者在此承担起正规士兵的职责，进行必要的基础工作，以防止核心领土陷入彻底的混乱。",["race:Human"]="对于暴风城的人类来说，这次派遣是王国被忽视的一个令人不安的迹象，直观地展示了在国王失踪后，王室的防御力量已经变得多么薄弱。"},sec={{t="捉襟见肘的边境",b="西泉要塞标志着艾尔文森林的西缘，坐落于定居的林地逐渐过渡到动荡的西部荒野平原之处。随着豺狼人战团和强盗沿着水道和西部道路变得愈发猖獗，这座哨站的小型驻军一直请求增派人手。然而，治安官杜汉和闪金镇的管理层已经没有多余的暴风城职业士兵可供调遣，使得当地指挥官别无选择，只能雇佣过往的佣兵和冒险者。"},{t="小溪对岸的威胁",b="瑞尼尔副队长及其部下所面临的主要威胁是河爪豺狼人氏族，他们的劫掠小队不断袭扰旅客和附近的农舍。这些豺狼人在艾尔文森林与西部荒野之间的边境地带活动，趁着暴风城在政治和军事上的分心，进一步深入有人居住的领土。西泉要塞是最后一道防线，阻止他们肆无忌惮地进入森林腹地。"}},faq={{q="为什么暴风城不能派遣正规士兵前往西泉要塞？",a="暴风城的常备军在多个前线兵力严重不足。由于瓦里安·乌瑞恩国王失踪，王国正处于内部纷争之中，最高指挥部拒绝或无力向乡村哨站部署正规士兵，迫使像杜汉这样的城镇治安官只能依靠自由志愿者的帮助。",al={"为什么没有暴风城军队","为什么要派遣冒险者","暴风城军队在哪里"}},{q="西泉要塞位于哪里？",a="这座要塞位于艾尔文森林的西缘。沿着闪金镇外的主路向西走，经过那条小溪；在进入西部荒野的边界前，你会看到右侧有一座防御塔。",al={"西泉要塞位置","如何前往西泉要塞","瑞尼尔副队长在哪里"}},{q="哪些威胁正在困扰着要塞？",a="瑞尼尔副队长正在应对河爪豺狼人的持续劫掠，以及在西部荒野和艾尔文森林边境地区日益猖獗的盗贼和强盗活动。",al={"什么在攻击西泉要塞","为什么瑞尼尔需要帮助","谁在攻击西泉要塞"}},{q="谁是瑞尼尔副队长？",a="瑞尼尔副队长是驻守西泉要塞的暴风城军官。他肩负着守卫西界线的重任，由于缺乏官方军事增援，他被迫向平民志愿者和佣兵寻求帮助。",al={"瑞尼尔背景故事","瑞尼尔副队长","瑞尼尔是谁"}},{q="向瑞尼尔副队长报到后会发生什么？",a="瑞尼尔副队长会立即征求你的帮助来对付当地的河爪豺狼人，并悬赏它们的项圈以减少其数量并保护边境道路。",al={"what comes next","西泉要塞任务线","瑞尼尔任务"}},{q="为什么豺狼人会向艾尔文森林推进？",a="河爪豺狼人在分隔艾尔文森林和西部荒野的河流沿岸建立了营地。它们利用边境军事存在减少的机会，变得胆大妄为，开始劫掠贸易路线并向艾尔文森林内部的农场推进。",al={"艾尔文森林的河爪豺狼人","为什么豺狼人会在这里","豺狼人问题"}}},fp="30,367,25.395.0,27.357.0,64.289.0,36.195.0,40.157.0,21.205.0,46.153.0,46.211.0"}
P.entries["quest:2399"] = {n="发芽的树叶",s="随着德纳兰在奥拉密斯湖进行的植物学实验，种下的树叶开始生根发芽。这一宁静的时刻标志着他在理解泰达希尔奇异而充满生命力的植物群方面，获得了一次成功的收成。参观花园苗圃的旅行者可以亲眼见证它们迅速的生长。",h="随着德纳兰在奥拉密斯湖进行的植物学实验，种下的树叶开始生根发芽。这一宁静的时刻标志着他在理解泰达希尔奇异而充满生命力的植物群方面，获得了一次成功的收成。参观花园苗圃的旅行者可以亲眼见证它们迅速的生长。",kw={"德纳兰","草药学","苗圃","种子","发光的树叶","发芽的叶片","泰达希尔","涌泉湖"},ang={["class:Druid"]="观察德纳兰苗圃的德鲁伊们可以领略到自然的宁静平衡，看到生命在细心照料下，即使在泰达希尔日益增长的危险中也能繁荣生长。",["profession:Herbalism"]="德纳兰的研究反映了采集和学习泰达希尔独特植被的实用艺术，展示了本地种子如何迅速适应经过培育的土壤。",["race:NightElf"]="照料新发芽的植物反映了卡多雷有责任去监测和培育在他们年轻的世界之树上扎根的生命。"},sec={{t="奥拉密斯湖畔的花园",b="植物学家德纳兰隐居在奥拉密斯湖附近，致力于将泰达希尔特有的植物生命编入目录。在种下一片神秘的“发光的树叶”后，这片土壤很快就有了产出。在他打理的苗圃里，奇异且颤抖的叶片从肥沃的壤土中破土而出，等待着被采集和研究。"},{t="世界之树的奇异植物",b="泰达希尔还很年轻，广袤无垠，且充满着快速的自然演化，这既令暗夜精灵草药师们着迷，也让他们感到困扰。这些“发光的树叶”及其发芽的分株，象征着生命在巨树枝桠上扎根的速度有多快，暗示着这座岛屿的土壤中蕴含着强大且难以预测的生命力。"}},faq={{q="什么是发芽的叶片？",a="它们是德纳兰在他的湖畔营地种下一片“发光的树叶”后发芽长成的植物。这些奇异的植物生长自泰达希尔其他地方找到的叶片，当准备好收获时，它们会因为能量而颤抖。",al={"发芽的叶片","这些植物是什么","德纳兰的叶片"}},{q="德纳兰的花园在哪里？",a="德纳兰将他的花园和研究营地设在奥拉密斯湖的东岸，位于泰达希尔多兰纳尔的东南方。",al={"德纳兰位置","德纳兰在哪里","涌泉湖花园"}},{q="德纳兰为什么要种植这些叶片？",a="德纳兰正在研究泰达希尔植物生命奇异且快速的生长模式。通过在受控的土壤中播种，他调查这些植物的本质，并测试它们是否具备有用的恢复性或草药学特性。",al={"为什么要种植叶片","德纳兰的实验","叶片的用途"}},{q="发芽的叶片危险吗？",a="不。与泰达希尔枝桠上其他一些受到腐蚀或充满敌意的植物不同，这些发芽的叶片是无害的植物样本，正等着被采摘。",al={"叶片危险吗","叶片会攻击吗","这种植物有害吗"}},{q="这个任务之前有什么？",a="冒险者首先要在泰达希尔的野外发现一片“发光的树叶”，并将其带给德纳兰，由他将其种入苗圃中，希望能让它生根。",al={"发芽的叶片前置任务","什么任务是先决条件"}},{q="为什么叶片会颤抖？",a="叶片在等待被采摘时会颤抖。来源资料并未解释导致这种动作的原因。",al={"颤抖的叶片","它们为什么会摇动"}}},fp="19,140,25.220.0,35.275.0,29.185.0,34.120.0,36.172.0,34.141.0,29.150.0,26.78.0"}
P.entries["quest:24"] = {n="萨杜布拉的头颅",s="这个任务证明了你已经击败了影爪，这只臭名昭著且凶猛的夜刃豹一直在灰谷的西部小径上徘徊。将这头野兽的断头带回给碎木岗哨的塞娜尼·雷心，不仅完成了灰谷狩猎的关键考验，还保障了通往佐拉姆海岸的旅行路线安全。",h="这个任务证明了你已经击败了影爪，这只臭名昭著且凶猛的夜刃豹一直在灰谷的西部小径上徘徊。将这头野兽的断头带回给碎木岗哨的塞娜尼·雷心，不仅完成了灰谷狩猎的关键考验，还保障了通往佐拉姆海岸的旅行路线安全。",kw={"灰谷狩猎","夜刃豹","塞娜尼·雷心","影爪","碎木岗哨","战利品","佐拉姆海岸"},ang={["class:Hunter"]="追踪并征服像影爪这样难以捉摸的夜刃豹，是对在茂密林地中进行射击、耐心和生存能力的终极考验。",["faction:Horde"]="碎木岗哨仍然是一个孤立的部落据点；消除像影爪这样的当地威胁，对于保持通往佐拉姆海岸的重要补给线畅通至关重要。",["race:Tauren"]="对于牛头人来说，猎杀影爪这种级别的野兽，既是通过挑战顶级掠食者来磨练技巧，又是在保护路上的族人，这符合大地母亲的自然法则。"},sec={{t="西部大道的威胁",b="影爪在灰谷的参天巨树间绝非普通的掠食者。这只强大的夜刃豹一直徘徊在碎木岗哨以西的荒野中，猎杀那些试图前往佐拉姆海岸的部落斥候和信使。它的速度、隐蔽性和纯粹的凶残使得步行旅行变得危机四伏，导致碎木岗哨的守军在巡逻队向西移动时总是提心吊胆。"},{t="狩猎的证明",b="作为灰谷狩猎的一部分，牛头人女猎手塞娜尼·雷心向部落的勇士们发起挑战，要求他们追踪并猎杀森林中的顶级野兽。上交影爪的头颅不仅仅是一种炫耀实力的冷酷展示，更证明了道路已经变得更加安全，且猎人已经征服了卡利姆多最致命的土生掠食者之一。"}},faq={{q="影爪是谁？",a="影爪是一只极其凶残的夜刃豹，它在那片碎木岗哨以西的森林中出没。由于它经常伏击那些前往海岸长途跋涉的旅人，它被认为是灰谷当地最危险的野兽之一。",al={"影爪是什么","影爪背景故事","那只猫是谁"}},{q="为什么塞娜尼·雷心想要这个头颅？",a="塞娜尼·雷心在碎木岗哨负责监管灰谷狩猎。要求得到这个头颅，既是将其作为一场出色狩猎的传统战利品，也是确认对前往西部旅人的威胁已被消除。",al={"为什么要带回头颅","塞娜尼·雷心战利品","灰谷狩猎证明"}},{q="这在灰谷狩猎中处于什么位置？",a="这是接受灰谷狩猎后启动的首要考验之一。击杀影爪，连同森林中的其他巨兽如乌萨诺斯和尖爪，将最终获得认可，并开启任务“狩猎完成”。",al={"什么是灰谷狩猎","狩猎任务线","下一个狩猎任务"}},{q="清除这头野兽对部落为什么很重要？",a="碎木岗哨依赖斥候和信使向西前往位于佐拉姆海岸的部落营地——佐拉姆加前哨站。影爪的掠食本性对通过这片荒野的部落步行交通构成了持续的威胁。",al={"部落为什么关心","佐拉姆海岸道路危险","碎木岗哨安全"}},{q="在哪里可以找到影爪？",a="影爪徘徊在碎木岗哨以西的林地中，在道路和散布于灰谷中西部地区的暗夜精灵古代遗迹之间的树林里游荡。",al={"影爪位置","影爪在哪里","寻找影爪"}},{q="影爪与暗夜精灵结盟了吗？",a="没有。虽然夜刃豹经常被暗夜精灵驯化和崇拜，但影爪是一头野性难驯、只凭原始掠食本能行事的恐怖森林野兽，威胁着任何进入它领地的生物。",al={"影爪是宠物吗","哨兵宠物","影爪暗夜精灵"}}},fp="16,217,28.225.0,17.292.0,18.196.0,43.178.0,44.200.0,50.189.0,29.171.0,41.171.0"}
P.entries["quest:240"] = {n="基特斯的美餐",s="“回到基特斯身边”为厨师格鲁奥在暮色森林的烹饪差事画上了句号。格鲁奥用当地毒蛛的粘腿肉制作了他那臭名昭著的“蟹”肉饼，并让你把食物送回到乌鸦岭那个饥肠辘辘、惊恐万分的隐士那里。送去这顿餐点终于满足了基特斯那绝望的饥饿感。",h="“回到基特斯身边”为厨师格鲁奥在暮色森林的烹饪差事画上了句号。格鲁奥用当地毒蛛的粘腿肉制作了他那臭名昭著的“蟹”肉饼，并让你把食物送回到乌鸦岭那个饥肠辘辘、惊恐万分的隐士那里。送去这顿餐点终于满足了基特斯那绝望的饥饿感。",kw={"厨师格鲁奥","夜色镇","暮色森林","黑蟹蛋糕","基特斯的馋虫","基特斯","scarlet raven tavern"},ang={["faction:Alliance"]="夜色镇贫乏且不同寻常的饮食状况反映了该镇与暴风城更广泛的补给线是如何隔绝的，迫使当地人只能依赖潜伏在阴影中的生物为食。",["profession:Cooking"]="厨师格鲁奥能将粘糊糊的毒蛛腿变成美味的蛋糕，这证明了边境地区的厨师必须具备坚韧不拔的应变能力。"},sec={{t="可疑的美味",b="暮色森林缺乏常规的牲畜和海产，这让Scarlet Raven Tavern的厨师格鲁奥只能因陋就简，利用这片被诅咒的森林所提供的任何食材。他著名的“黑蟹蛋糕”里根本没有真正的蟹肉，而是依靠从森林中爬行的毒蛛身上采集来的粘腿肉制作而成。格鲁奥认为这是足智多谋的烹饪方式；但任何肠胃敏感的人可能会对此感到毛骨悚然。"},{t="安抚基特斯的神经",b="基特斯终日蜷缩在乌鸦岭，被恐惧完全吞噬，无论是什么恐怖经历将他从森林中驱赶出来，都让他变得瘫痪。因恐惧而虚弱，且无法鼓起勇气为自己狩猎或寻找食物，空虚的胃只会加剧他的痛苦。收到热腾腾的蛋糕，让这位颤抖的流浪汉获得了片刻难得的慰藉，他实在太饿了，根本不会去深究厨师格鲁奥用的是哪种“蟹”。"}},faq={{q="黑蟹蛋糕里有什么？",a="暮色森林里没有螃蟹。厨师格鲁奥使用当地毒蛛的粘腿肉制作他的特色蛋糕，并用调味料模仿传统海鲜饼的味道。",al={"黑蟹蛋糕配料","黑蟹蛋糕的成分","是真正的蟹肉吗"}},{q="基特斯知道这些蛋糕是用蜘蛛的粘腿肉做的吗？",a="厨师格鲁奥对他的烹饪秘方守口如瓶，而基特斯由于极度饥饿和恐惧，根本无暇过问配方。他狼吞虎咽地吃下蛋糕，完全没怀疑过它们的真正来源。",al={"基特斯知道吗","基特斯知道蜘蛛的事吗"}},{q="为什么基特斯不能自己找食物？",a="在暮色森林的荒野中遭遇险境后，基特斯彻底被恐惧所压垮。由于惊恐万分，他拒绝远离在乌鸦岭的藏身处，只能依靠好心的路人为他带来食物。",al={"基特斯为什么挨饿","基特斯为什么不狩猎"}},{q="谁是厨师格鲁奥？",a="厨师格鲁奥是夜色镇Scarlet Raven Tavern的厨师。面对这个被阴影和野兽所隔绝的城镇，他利用拾荒者带来的任何非常规食材来维持当地酒馆的供应。",al={"厨师格鲁奥的作用","夜色镇的厨师"}},{q="这个任务链从哪里开始？",a="这项差事始于乌鸦岭的基特斯，他会在“基特斯的馋虫”任务中请求帮助解决他的饥饿问题。这会引向为厨师格鲁奥猎杀毒蛛的任务，最后再将做好的餐点送回这里。",al={"如何开启基特斯的食物任务","基特斯任务链的起始"}},{q="基特斯吃完后会康复吗？",a="这顿饭满足了他的生理饥饿，并为你赢得了他衷心的感激，但食物无法治愈他根深蒂固的心理恐惧。他依然焦虑不安，并被森林中黑暗的秘密所困扰。",al={"基特斯治愈了吗","食物能帮助基特斯吗"}}},fp="17,113,18.349.0,24.317.0,32.141.0,51.125.0,38.171.0,18.189.0,34.182.0,34.172.0"}
P.entries["quest:243"] = {n="进入沙漠",s="药剂师金格派遣你前往塔纳利斯沙漠，携带一套实地测试工具去测试蛇怪、蝎子和土狼的组织样本。改装后的工具还需要一种加基森地精拥有的动力源，所以金格指引你去找那里的首席工程师沙克斯·比格维兹。",h="药剂师金格派遣你前往塔纳利斯沙漠，携带一套实地测试工具去测试蛇怪、蝎子和土狼的组织样本。改装后的工具还需要一种加基森地精拥有的动力源，所以金格指引你去找那里的首席工程师沙克斯·比格维兹。",kw={"药剂师","蛇怪","沙克斯·比格维兹","加基森","土狼","动力源","蝎子","塔纳利斯","测试工具","金格"},sec={{t="沙漠中的组织",b="药剂师金格想要测试沙漠中蛇怪、蝎子和土狼的组织结构。你需要收集样本并用你携带的测试工具进行分析，不过相当大一部分样本将会失败。你需要每种生物各收集八份合格的样本，金格要求你只有在成功后才能回来找他。"},{t="加基森的动力源",b="改装后的工具必须使用加基森地精所拥有的那种动力源。金格派你去找加基森的首席工程师沙克斯·比格维兹，从他那里搞到一个。"},{t="没有免费午餐",b="沙克斯·比格维兹对比格维兹4711-FTZ型动力源非常了解；它们通常用于水井运转，而且多亏了那些邪恶的游牧民，现在这种东西多得是。沙克斯·比格维兹愿意为你那试图掩盖的邪恶实验安排一个，但这绝不是免费的，因为在加基森，没有什么东西是免费的。"}},faq={{q="是谁派你到塔纳利斯进行这项研究的？",a="药剂师金格，他给了你一套实地测试工具，想要测试沙漠生物的组织样本。",al={"谁开始进入实地","谁发放进入实地任务","进入实地任务发布者"}},{q="为什么你需要去见首席工程师沙克斯·比格维兹？",a="改装后的测试工具需要一种加基森地精所拥有的动力源，而沙克斯·比格维兹就是负责处理这件事的人。",al={"沙克斯·比格维兹的角色","为什么要拜访沙克斯·比格维兹","测试工具动力源"}},{q="哪些野兽是测试的目标？",a="塔纳利斯沙漠中的蛇怪、蝎子和土狼，每种需要八份合格的样本。",al={"需要测试的野兽","进入实地生物类型","塔纳利斯组织样本"}}},fp="14,266,20.341.0,27.164.0,15.304.1,43.102.0,51.147.0,38.99.0"}
P.entries["quest:2438"] = {n="翡翠摄梦符",s="多兰纳尔的塔隆凯·捷根请求冒险者从他在星风村的废弃住所里取回一件珍贵的传家宝。翡翠摄梦符是他从德鲁伊守望者盖洛拉斯·塔文斯伦那里获得的礼物，当受到腐蚀的棘齿熊怪占领了这座宁静的定居点时，他被迫将其遗落。取回这件护身符可以防止它那温和的自然魔法落入邪恶之手。",h="多兰纳尔的塔隆凯·捷根请求冒险者从他在星风村的废弃住所里取回一件珍贵的传家宝。翡翠摄梦符是他从德鲁伊守望者盖洛拉斯·塔文斯伦那里获得的礼物，当受到腐蚀的棘齿熊怪占领了这座宁静的定居点时，他被迫将其遗落。取回这件护身符可以...",kw={"班奈希尔兽穴","多兰纳尔","翡翠梦境","翡翠摄梦符","熊怪","盖洛拉斯·塔文斯伦","棘齿熊怪","星风村","塔隆凯·捷根","泰达希尔"},ang={["class:Druid"]="这件护身符是盖洛拉斯·塔文斯伦的直接作品，他是照料你在班奈希尔兽穴中沉睡族人的守望者，因此找回此物关乎德鲁伊的荣誉。",["faction:Alliance"]="帮助多兰纳尔的流离失所的卡多雷能巩固当地局势，因为泰达希尔正饱受熊怪部落日益严重的腐蚀之苦。",["race:NightElf"]="星风村曾是你族人宁静的避风港。帮助塔隆凯找回他的遗产，是对席卷泰达希尔野生生物的疯狂行径的一次小小的反击。"},sec={{t="德鲁伊的护身符",b="翡翠摄梦符绝不仅仅是一件装饰性的饰品。它是盖洛拉斯·塔文斯伦赠予的礼物，此人是班奈希尔兽穴内沉睡德鲁伊的尊贵守望者。这件护身符旨在引导翡翠梦境中平静的流光。通过汲取这种纯净的精神能量，摄梦符能为佩戴者带来安宁与好运。这类信物极为罕见，只授予少数几位与森林守护事业息息相关的受托者。"},{t="逃离星风村",b="不久之前，星风村还是一座坐落在泰达希尔枝干间的宁静定居点。随着当地的棘齿熊怪陷入疯狂，暗夜精灵被迫逃离他们的家园，那种平静的生活便戛然而止。在撤离时的恐惧与混乱中，塔隆凯被迫将他最珍贵的财产留在了村庄东南角的梳妆台里，无力独自取回。"},{t="腐蚀的威胁",b="将一个翡翠梦境魔法的聚焦点留在一座被占领的村庄中心，有着极大的风险。棘齿熊怪已被证明容易受到黑暗力量的影响，而一件脉动着梦境能量的文物很容易被玷污或武器化。在熊怪或其他邪恶生物玷污其残留的魔法之前，将其安全取回，能把星风村的一部分遗产带回给塔隆凯。"}},faq={{q="什么是翡翠摄梦符？",a="这是一款罕见的护身符，由班奈希尔兽穴的德鲁伊守望者盖洛拉斯·塔文斯伦赠予塔隆凯。摄梦符能从翡翠梦境汲取能量，为佩戴者带来好运与精神上的和谐。",al={"什么是翡翠摄梦符","摄梦符背景故事","翡翠摄梦符"}},{q="为什么摄梦符会被留在星风村？",a="当当地的棘齿熊怪陷入疯狂且受到腐蚀的狂乱状态时，星风村迅速失陷。塔隆凯·捷根被迫逃亡多兰纳尔以求生，只能将那件珍贵的传家宝遗落在他的卧室梳妆台里。",al={"为什么把它留在那","星风村梳妆台","塔隆凯的梳妆台"}},{q="塔隆凯·捷根是谁？",a="塔隆凯是一位目前居住在多兰纳尔的暗夜精灵难民。在星风村沦陷后逃脱的他，正寻求勇敢的旅人前往被占领的废墟，找回他的传家宝并守护德鲁伊圣物。",al={"谁是塔隆凯","塔隆凯·捷根"}},{q="是谁制作了摄梦符？",a="塔隆凯只提到这是盖洛拉斯·塔文斯伦赠予的礼物，他是班奈希尔兽穴内监护沉睡德鲁伊的守望者；至于此物究竟由谁所制，从未提及。",al={"谁制造的","盖洛拉斯·塔文斯伦 摄梦符","盖洛拉斯"}},{q="摄梦符在星风村的什么位置？",a="它位于星风村最东南侧房屋内塔隆凯的私人梳妆台里，该区域现在正有大批敌对的棘齿熊怪游荡。",al={"梳妆台在哪里","星风村梳妆台位置","寻找摄梦符"}},{q="归还摄梦符后会发生什么？",a="当塔隆凯检查找回的护身符时，他发现上面的翡翠不见了，那是被棘齿熊怪首领“梦境吞噬者”费罗塞塔斯窃走的，这也直接引发了对他的追捕。",al={"任务后续","摄梦符之后的下一个任务"}}},fp="24,347,18.362.0,26.316.0,24.371.1,33.254.0,59.190.0,27.212.0,26.167.0,56.159.0,48.181.1"}
P.entries["quest:244"] = {n="豺狼人的入侵",s="“逼近的豺狼人”是一项联盟任务，旨在向湖畔镇的城镇卫兵发出警报，告知他们有豺狼人正在艾尔文森林边境附近危险地徘徊。卫兵帕克在边境通道沿线发现了聚集的营地，于是派遣路人前往提醒菲尔顿副队长。这个消息证实了湖畔镇日益增长的担忧：这些兽人正威胁着要将赤脊山彻底与外界隔绝。",h="“逼近的豺狼人”是一项联盟任务，旨在向湖畔镇的城镇卫兵发出警报，告知他们有豺狼人正在艾尔文森林边境附近危险地徘徊。卫兵帕克在边境通道沿线发现了聚集的营地，于是派遣路人前往提醒菲尔顿副队长。这个消息证实了湖畔镇日益增长的担...",kw={"评估威胁","菲尔顿副队长","艾尔文森林边境","逼近的豺狼人","卫兵帕克","湖畔镇","赤脊山"},ang={["faction:Alliance"]="湖畔镇的孤立威胁到了联盟的东部前线，这使得边境情报对于旅行者和补给车队至关重要。",["race:Human"]="兽人在艾尔文森林视线范围内的蚕食，突显了在国王缺席的情况下，王国核心领土变得多么脆弱。"},sec={{t="边境视线",b="连接艾尔文森林和赤脊山的道路本应是王国中最安全的交通路线之一，但暴风城稀薄的兵力使其几乎处于无人防守的状态。卫兵帕克驻扎在西部边境小径上负责监视动向。虽然他勉强维持了碎石路供补给车队通行，但他向北和向东的侦察却显示，豺狼人战团已经从山崖中推进，并在离道路惊人近的地方建立了营地。"},{t="受困的城镇",b="在湖畔镇大桥附近收到警报后，菲尔顿副队长意识到情况比预想的还要糟糕。赤脊山的豺狼人不仅仅是在袭击城镇周边；他们在艾尔文森林边境附近的靠前部署意味着他们可以包围湖畔镇并向王国的腹地推进。由于暴风城无视增援的请求，湖畔镇的守卫根本无法应对两线作战的威胁。"}},faq={{q="谁发放这个任务？",a="卫兵帕克在赤脊山西部、靠近艾尔文森林边境路口处的道路旁发放该任务。",al={"任务发放者","从哪里开始","卫兵帕克位置"}},{q="我在哪里能找到菲尔顿副队长？",a="菲尔顿副队长驻扎在湖畔镇，在城镇大石桥以南的地面巡逻。",al={"菲尔顿位置","菲尔顿副队长是谁","交付地点"}},{q="为什么道路上的豺狼人是个问题？",a="通往艾尔文森林的道路是湖畔镇与王国其他地区联系的唯一陆路生命线。如果豺狼人占领了西侧山坡，该镇将实际上被切断补给和逃生路径。",al={"豺狼人的重要性","赤脊山豺狼人问题","道路危险"}},{q="为什么暴风城不向湖畔镇派遣援助？",a="由于瓦里安·乌瑞恩国王失踪，王国局势紧张，伯瓦尔公爵和王庭拒绝向赤脊山派遣皇家部队，导致湖畔镇的防务完全留给了当地的副官和志愿者。",al={"暴风城卫兵在哪里","没有增援","湖畔镇防务"}},{q="报告豺狼人后的后续内容是什么？",a="菲尔顿副队长会让你在后续任务“评估威胁”中更近距离地侦察豺狼人营地，以确定它们数量的真实实力。",al={"下一个任务","任务链后续"}},{q="哪些豺狼人部族正在侵入这里？",a="赤脊山的豺狼人正聚集在山丘中形成赤脊山豺狼人部族，随着人类对该地区控制力的减弱，它们变得越来越大胆且协作紧密。",al={"哪些豺狼人","赤脊山豺狼人部族"}}},fp="18,239,18.365.0,18.371.0,22.120.0,31.100.0,40.176.0,45.209.0,40.125.0,39.148.0"}
P.entries["quest:245"] = {n="蜘蛛的威胁",s="“八足威胁”是暮色森林的守夜人道茨发布的一份民兵契约。由于西部边界被极具攻击性的毒蛛侵袭，人手不足的守夜人只能依靠过往的冒险者在更多的守卫被困入蛛网之前清理这些巢穴。",h="“八足威胁”是暮色森林的守夜人道茨发布的一份民兵契约。由于西部边界被极具攻击性的毒蛛侵袭，人手不足的守夜人只能依靠过往的冒险者在更多的守卫被困入蛛网之前清理这些巢穴。",kw={"夜色镇","暮色森林","八足威胁","守夜人","侏儒毒蛛","蜘蛛","守夜人道茨"},ang={["class:Hunter"]="暮色森林的毒蛛是凶残的野兽，需要谨慎的走位和抗毒剂准备才能有效地进行狩猎。",["faction:Alliance"]="守夜人在没有暴风城贵族议会援助的情况下孤军奋战，因此联盟旅行者提供的任何支持对于保持道路畅通都至关重要。"},sec={{t="被围困的边界",b="沿着连接西部荒野与暮色森林的西侧道路，茂密的树冠渐渐让位于被蛛网缠绕的灌木丛。侏儒毒蛛现在成群结队地盘踞在灌木丛中，威胁着旅行者的安全，并不断蚕食守夜人苦苦维持的脆弱防线。"},{t="守夜人的重担",b="守夜人道茨驻扎在远离夜色镇安全区的地方，正面临严重的兵力短缺。当亡灵和狼人不断冲击城镇本身时，指挥官阿尔泰娅·埃伯洛克根本抽不出援军来保卫边远的哨所。道茨孤立无援，他已经眼睁睁地看着战友成为毒蛛的猎物，发现他们倒挂在树冠上，被麻痹毒素缓慢地溶解以便吞食。"}},faq={{q="谁发布了这个任务？",a="守夜人道茨，一名驻扎在暮色森林某个小营地的守夜人成员，为有能力清理毒蛛的旅行者提供了这项任务。",al={"任务发布者","谁发布八足威胁","守夜人道茨"}},{q="为什么守夜人不能亲自处理这些毒蛛？",a="指挥官阿尔泰娅·埃伯洛克必须将她那为数不多的驻军集中在夜色镇附近，以抵御亡灵的持续进攻。道茨没有足够的人手在不放弃岗位的情况下清理边境的 infested 蛛巢。",al={"为何需要帮助","为何呼叫冒险者","夜色镇民兵短缺"}},{q="这些毒蛛位于何处？",a="侏儒毒蛛大量聚集在暮色森林的西部树林中，潜伏在从西部荒野进入的主路旁的灌木丛里。",al={"蜘蛛位置","侏儒毒蛛在哪里","蜘蛛树林"}},{q="是什么让这些毒蛛对守卫如此危险？",a="除了数量庞大之外，它们还拥有能麻痹并溶解血肉的强效毒素，这让被困住的守夜人束手无策，只能被挂在树枝上沦为待宰的羔羊。",al={"蜘蛛毒液","蜘蛛毒素","蜘蛛受害者"}},{q="暮色森林里只有这些毒蛛吗？",a="不。侏儒毒蛛仅仅是较小的幼蛛。在树林深处还栖息着体型更大、更致命的个体，对旅行者构成了更为严重的威胁。",al={"暮色森林的其他蜘蛛","蜘蛛种类","毒蛛"}},{q="为什么昆虫和蜘蛛的数量增长得如此疯狂？",a="笼罩在暮色森林上空的弥漫魔法腐蚀扭曲了这里的原生生物，加速了这片枯萎森林中生物的攻击性、体型和致命程度。",al={"为何有这么多蜘蛛","暮色森林腐蚀的本质","蜘蛛起源"}}},fp="20,168,20.213.0,29.344.0,22.105.0,56.180.0,32.105.0,51.148.0,39.137.0,63.133.0"}
P.entries["quest:2458"] = {n="卧底密探",s="深层掩护是奥格瑞玛的申苏尔交给有前途的部落潜行者的一项卧底任务。该任务将执行者派往淤泥沼泽的荆棘谷地精钻探点，与碎手氏族的一名卧底特工建立秘密联系。",h="深层掩护是奥格瑞玛的申苏尔交给有前途的部落潜行者的一项卧底任务。该任务将执行者派往淤泥沼泽的荆棘谷地精钻探点，与碎手氏族的一名卧底特工建立秘密联系。",kw={"贫瘠之地潜行者","深层掩护","信号枪","碎手氏族","申苏尔","淤泥沼泽","工头费苏勒","荆棘谷地精"},ang={["class:Rogue"]="这项任务是部落潜行者成长过程中的一个重要里程碑，标志着他们从普通的街头侦察兵转变为能够进行秘密现场协调的可信特工。",["faction:Horde"]="荆棘谷地精在贫瘠之地无休止的砍伐和钻探威胁着部落的领土控制权和自然资源，因此必须进行积极的间谍活动。"},sec={{t="牟利者中的间谍",b="碎手氏族是部落的秘密情报和刺客公会，通过冷酷务实的手段默默捍卫着奥格瑞玛的利益。整整一年以来，该公会一直致力于将一名特工安插进贪婪的荆棘谷地精的层级之中。那名资产，即工头费苏勒，成功打入了他们位于淤泥沼泽以北的工业钻探哨站。"},{t="信号与暗号",b="在雇佣兵防线深处行动，容不得半点差错。由于费苏勒必须维持冷酷的形象来应付他的公司上司，任何未经通报的访客都有被立即攻击的风险。为了验证身份，到来的潜行者必须在他的塔楼视线内使用指定的信号枪发射两发信号弹，悄悄靠近，并做出碎手氏族的秘密敬礼，然后才能听取他对荆棘谷地精日益升级的阴谋的汇报。"}},faq={{q="工头费苏勒是谁？",a="工头费苏勒是碎手氏族安插在淤泥沼泽以北、荆棘谷地精层级中的深层卧底特工。他花了一整年的时间在雇佣兵中晋升至领导地位，监视他们的行动并将情报传回奥格瑞玛。",al={"费苏勒","费苏勒是谁","工头费苏勒的身份"}},{q="如果你不发出正确的信号，费苏勒为什么要攻击你？",a="费苏勒正在维持他那粗暴、强硬的荆棘谷地精工头的伪装。如果有人在没有提供准确的双信号弹信号和碎手氏族的敬礼的情况下接近他的哨位，他必须假定对方是敌对的入侵者或竞争对手的代理人，从而当场攻击他们以掩盖自己的真实身份。",al={"为什么费苏勒会攻击","费苏勒是敌对的","费苏勒杀了我"}},{q="荆棘谷地精的塔楼在哪里？",a="这座塔楼矗立在淤泥沼泽以北的工业区上方，位于贫瘠之地中北部广阔的区域内。",al={"费苏勒的位置","塔楼位置","淤泥沼泽塔楼在哪里"}},{q="部落为什么要监视荆棘谷地精？",a="荆棘谷地精因在卡利姆多各地肆无忌惮地掠夺资源、剥削和实施残酷暴力而臭名昭著。碎手氏族最近收集的情报显示，该集团正在贫瘠之地策划一项重大阴谋，这促使申苏尔激活了他的联系人。",al={"为什么要监视荆棘谷地精","荆棘谷地精的威胁"}},{q="与费苏勒建立联系后会发生什么？",a="一旦成功建立联系，费苏勒会指示潜行者潜入附近的荆棘谷地精塔楼，击杀包括大工头普兹克·加里维克斯在内的守卫，并窃取赞吉尔的改良药剂，以向公会证明他们的价值。",al={"深层掩护之后做什么","费苏勒之后"}},{q="什么是碎手氏族？",a="碎手氏族是一个在奥格瑞玛的暗影裂口运作的、由潜行者、间谍和刺客组成的阴影网络。虽然他们曾经是德拉诺的一个臭名昭著的氏族，但在新部落中，他们是部落的秘密情报机构。",al={"碎手氏族","碎手氏族是什么"}}},fp="10,240,22.297.0,17.366.0,26.220.0,58.239.0,43.102.0,47.223.0,47.214.1,27.190.0"}
P.entries["quest:2459"] = {n="噬梦者菲罗斯塔",s="“食梦者”费罗塞塔斯是一项由多兰纳尔的塔隆凯·捷根提供的联盟任务。在找回他受损的传家宝翡翠摄梦符后，塔隆凯发现其强力的翡翠核心被星风村北部的蓟皮熊怪撬走了。冒险者们受命去杀死那些腐化的秘法师，并从它们的首领，费罗塞塔斯那里取回被盗的宝石。",h="“食梦者”费罗塞塔斯是一项由多兰纳尔的塔隆凯·捷根提供的联盟任务。在找回他受损的传家宝翡翠摄梦符后，塔隆凯发现其强力的翡翠核心被星风村北部的蓟皮熊怪撬走了。冒险者们受命去杀死那些腐化的秘法师，并从它们的首领，费罗塞塔斯那...",kw={"多兰纳尔","食梦者","翡翠摄梦符","费罗塞塔斯","蓟皮秘法师","星风村","塔隆凯·捷根","塔隆凯的珠宝","泰达希尔"},ang={["class:Druid"]="翡翠摄梦符是与翡翠梦境相连的强力法器；看到它被腐化的熊怪玷污，需要迅速进行自然的惩戒。",["race:NightElf"]="蓟皮熊怪曾经是卡多雷的盟友，这使得它们的秘法师被腐化以及它们窃取神圣护身符的行为，对于任何保卫泰达希尔的暗夜精灵来说，都是一出令人心酸的悲剧。"},sec={{t="污秽的传家宝",b="当塔隆凯·捷根检查从腐化的荒野中找回的翡翠摄梦符时，他的欣慰很快变成了沮丧。这件神圣的文物遭到了破坏，其充满活力的翡翠中心被从编织的框架中撬了出来。暗夜精灵中流传着一个消息，星风村北部的一群蓟皮秘法师受到了一位被称为“食梦者”费罗塞塔斯的熊怪首领的影响，他肆无忌惮地将那颗闪亮的绿色宝石挂在脖子上。深知这颗神圣的宝石在那个生物手中毫无用处且显得亵渎，塔隆凯派遣防御者去夺回它。"},{t="清除秘法师",b="居住在泰达希尔北部的蓟皮熊怪曾经是和平的邻居，但渗透进世界之树的日益严重的腐化驱使它们陷入了狂乱和疯狂。曾经实行和谐自然仪式的秘法师们，开始利用扭曲的魔法能量。通过追踪费罗塞塔斯并杀出重围，击败守卫其林地领地的秘法师随从，旅行者们恢复了林地的平衡，并找回了塔隆凯的珠宝，使翡翠摄梦符终于得以复原。"}},faq={{q="我在哪里可以找到“食梦者”费罗塞塔斯？",a="“食梦者”费罗塞塔斯位于泰达希尔星风村北部的森林中，周围环绕着腐化的蓟皮秘法师和其他林地危险。",al={"费罗塞塔斯位置","费罗塞塔斯在哪里","找到食梦者"}},{q="费罗塞塔斯是谁？",a="费罗塞塔斯是一位蓟皮熊怪首领，他指挥着星风村北部的一群腐化的蓟皮秘法师。他从塔隆凯·捷根的翡翠摄梦符上取下了那块翡翠，并将它做成了一条简陋的项链。",al={"费罗塞塔斯是谁","费罗塞塔斯背景故事","什么是食梦者"}},{q="为什么塔隆凯·捷根想要回这颗珠宝？",a="失踪的翡翠是塔隆凯的翡翠摄梦符的核心动力源。没有它，这件护身符就无法修复，也无法引导翡翠梦境的保护能量。",al={"为什么塔隆凯想要珠宝","塔隆凯珠宝的作用"}},{q="蓟皮熊怪真的能使用翡翠的魔法吗？",a="不能。根据塔隆凯·捷根的说法，翡翠的魔法属性对于费罗塞塔斯和蓟皮秘法师这类生物来说毫无用处，他们仅仅把它当作一个发光的装饰品来觊觎。",al={"蓟皮熊怪能用翡翠摄梦符吗","费罗塞塔斯会使用翡翠吗"}},{q="这个任务之后会发生什么？",a="这个任务是始于“翡翠摄梦符”这一两部分任务链的最终章。一旦你将珠宝交给多兰纳尔的塔隆凯，他终于可以修复他的传家宝了。",al={"费罗塞塔斯任务后续","翡翠摄梦符后续任务"}},{q="为什么蓟皮秘法师会充满敌意？",a="和泰达希尔各地的许多野生动物和熊怪部落一样，蓟皮熊怪屈服于一种奇怪的腐化，这种腐化扭曲了新种植的世界之树的枝干，使它们心智扭曲，变得具有攻击性。",al={"为什么熊怪会发狂","蓟皮熊怪腐化"}}},fp="25,258,18.540.0,19.478.0,42.147.0,17.194.0,49.161.0,51.140.0,30.170.0,38.197.0"}
P.entries["quest:246"] = {n="审时度势",s="“评估威胁”是一项由湖畔镇的菲尔顿副队长发起的防御性侦察行动。由于当地驻军兵力吃紧，且无法从暴风城获得增援，冒险者受雇清除沿南路侵扰的豺狼人部族，并以此来衡量这场日益严峻的威胁的规模。",h="“评估威胁”是一项由湖畔镇的菲尔顿副队长发起的防御性侦察行动。由于当地驻军兵力吃紧，且无法从暴风城获得增援，冒险者受雇清除沿南路侵扰的豺狼人部族，并以此来衡量这场日益严峻的威胁的规模。",kw={"评估","菲尔顿","豺狼人","湖畔镇","杂种犬","偷猎者","侦察","赤脊山","威胁"},ang={["class:Warrior"]="菲尔顿副队长要求进行激进的战斗侦察，以测试武装战斗人员深入加固的敌方营地并击溃其先锋部队的能力。",["faction:Alliance"]="赤脊山展现了联盟腹地的裂痕，当首都对边境地区置之不理时，被忽视的边境定居点必须雇佣自由勇士才能求生。",["race:Human"]="对于人类守军来说，保卫湖畔镇是个人的使命；这些边境家庭正在承受着Stormwind Keep政治瘫痪所带来的后果。"},sec={{t="紧绷的边境",b="湖畔镇正多面受敌，为生存而战。来自高地的黑石兽人战帮和侵扰河谷的凶猛豺狼人部族，让当地守军无法抽调人手进行常规的侦察巡逻。当最初的报告证实有豺狼人侵入边境时，菲尔顿副队长只能寻求外部援助。与其将正规卫兵投入荒野，镇上选择花钱雇佣路过的勇士，去实地测试敌人的实力。"},{t="武力侦察",b="这项任务要求侦察兵沿着赤脊山的南路行进，深入赤脊杂种犬和偷猎者的营地。这是一种以消耗战形式进行的军事情报搜集：清理前锋侦察兵，切断补给线，并判断这些部族到底是游荡的食腐动物，还是威胁着定居点的有组织军事力量。这些血腥的冲突为菲尔顿提供了他制定湖畔镇防御计划所必需的具体数据。"}},faq={{q="为什么菲尔顿副队长雇佣冒险者而不是派遣城镇卫兵？",a="湖畔镇的驻军严重缺乏人手。由于暴风城没有提供任何增援，且敌对势力四面来袭，城镇卫兵无法抽出士兵来进行南路的长期巡逻。",al={"为何雇佣冒险者","卫兵在哪里","湖畔镇守军短缺"}},{q="这项任务中豺狼人的位置在哪里？",a="赤脊杂种犬和偷猎者在赤脊山南部、湖畔镇南侧以及边境山口附近的南路和山脚低地形成了松散的战争营地。",al={"赤脊杂种犬在哪里","赤脊山豺狼人位置","南路豺狼人"}},{q="清除这些豺狼人的战略目的是什么？",a="该行动有两个目的：一是击退侵入道路的前锋侦察兵，二是带回有关赤脊山豺狼人的规模、武器和纪律的第一手军事情报。",al={"为何要消灭豺狼人","威胁评估目标","湖畔镇防御"}},{q="暴风城会协助应对豺狼人的威胁吗？",a="不会。暴风城的贵族议会和摄政委员会拒绝向赤脊山等边远地区提供常规军事支持，迫使所罗门镇长和菲尔顿副队长等地方官员只能依赖雇佣兵。",al={"暴风城增援","为何暴风城不提供协助","暴风城军队湖畔镇"}},{q="菲尔顿副队长会如何处理你的报告？",a="菲尔顿副队长会对部族的实力和顽固程度进行评估，确认南方的豺狼人不仅是孤立的野兽，而是严重的军事威胁，并指引你协助其他镇领导加强防御。",al={"菲尔顿的反应","评估威胁后会发生什么","提交报告"}},{q="这项任务与之前的任务有什么关联？",a="这是“侵扰的豺狼人”的直接后续任务。在你首次向驻军发出豺狼人活动的警报后，菲尔顿委派了这次战斗巡逻，以评估入侵的严重程度。",al={"任务线关联","侵扰的豺狼人后续","前置任务"}}},fp="20,203,19.351.0,23.356.0,63.218.0,46.162.0,54.174.0,47.219.0,44.223.0,46.160.0"}
P.entries["quest:2460"] = {n="碎手军礼",s="碎手礼是一种由申苏尔在奥格瑞玛的暗影裂口监督的入门仪式。通过学习这种独特的识别标志，初出茅庐的潜行者们可以学会如何在野外安全地识别碎手氏族的同僚。",h="碎手礼是一种由申苏尔在奥格瑞玛的暗影裂口监督的入门仪式。通过学习这种独特的识别标志，初出茅庐的潜行者们可以学会如何在野外安全地识别碎手氏族的同僚。",kw={"cleft of shadow","隐蔽","深度潜伏","奥格瑞玛","潜行者","碎手氏族","碎手礼","申苏尔"},ang={["class:Rogue"]="对于一名部落潜行者来说，掌握碎手氏族的秘密信号代表着从一名普通的小偷向奥格瑞玛情报网络值得信赖的特工的转变。",["faction:Horde"]="尽管大酋长萨尔以荣誉领导部落，但部落在很大程度上依赖碎手氏族的秘密手段来在威胁浮出水面之前将其化解。"},sec={{t="标志与阴影",b="在暗影裂口的黑暗隧道中，碎手氏族作为萨尔领导的部落的秘密情报和暗杀机构开展行动。考虑到他们任务的危险性和隐秘性，特工们不能依赖显眼的横幅或标准的军事纹章。申苏尔指导新入行的潜行者学习碎手礼，这是一种旨在作为盟友之间明确无误的无声信号的特定手势。"},{t="野外准备",b="掌握这种礼节不仅是一种仪式性的练习，更是至关重要的贸易技巧。潜行者特工被派往危险地区或负责渗透敌对派系时，必须在不惊动旁观者或目标的情况下验证联络人。申苏尔坚持要求特工在将秘密的野外任务托付给他们之前，必须能够熟练地识别并模仿这一手势。"}},faq={{q="碎手礼的目的是什么？",a="碎手礼是碎手氏族成员之间的一种秘密识别信号。它允许特工在深入潜伏或处于敌对领土时识别彼此，而不会向外人暴露他们的真实身份。",al={"为什么需要学习碎手礼","碎手礼的目的","碎手礼的作用"}},{q="谁传授碎手礼？",a="这种礼节由申苏尔传授，他是一位驻扎在奥格瑞玛下方暗影裂口深处的潜行者训练师。",al={"谁发布任务","谁是申苏尔","在哪里学习碎手礼"}},{q="什么组织使用这种手势？",a="它由碎手氏族使用，这是一个由兽人潜行者、间谍和刺客组成的组织，在奥格瑞玛的阴影中为现代部落服务。",al={"碎手氏族","碎手氏族是谁","哪个组织使用这种手势"}},{q="为什么在进入野外之前必须学习这种礼节？",a="被派去执行渗透任务（例如与卧底特工联络）的特工依靠这种礼节来避免暴露身份或将敌人误认为盟友。",al={"为什么要练习碎手礼","碎手礼是必须的吗"}},{q="这项训练在哪里进行？",a="训练在暗影裂口进行，这是奥格瑞玛下方的地下区域，潜行者、术士和其他禁忌之术的修行者聚集在这里，远离公众的视线。",al={"碎手礼位置","申苏尔在哪里"}},{q="掌握这种礼节后会进行什么任务？",a="一旦申苏尔对特工掌握礼节的情况感到满意，他就会指派他们执行深度潜伏任务，测试他们使用该信号联系野外特工的能力。",al={"what comes next","碎手礼之后的下一个任务","深度潜伏任务"}}},fp="20,149,17.321.0,25.325.0,44.154.0,33.96.0,36.132.0,65.138.0,36.186.0,51.179.0"}
P.entries["quest:247"] = {n="完成狩猎",s="“狩猎完成”是塞娜尼·雷心在灰谷进行的伟大野兽试炼的最高潮。通过击败Ursangous、Shadumbra和Sharptalon，部落勇士证明了他们在争议森林中的力量、坚韧和原始本领。",h="“狩猎完成”是塞娜尼·雷心在灰谷进行的伟大野兽试炼的最高潮。通过击败Ursangous、Shadumbra和Sharptalon，部落勇士证明了他们在争议森林中的力量、坚韧和原始本领。",kw={"灰谷","野兽","狩猎","掠食者","塞娜尼","shadumbra","sharptalon","雷心","战利品","ursangous"},ang={["class:Hunter"]="战胜灰谷的三只顶级掠食者是追踪术和射击术的终极仪式，证明了你的本能与这些野生猛兽不相上下。",["faction:Horde"]="驯服灰谷的野兽有助于巩固部落在这个充满掠食者和联盟哨兵的危险敌对林地中的立足点。",["race:Tauren"]="对于舒哈鲁来说，猎杀Ursangous、Shadumbra和Sharptalon是一种历史悠久的考验，象征着尊重、平衡和先祖的荣耀。"},sec={{t="猎人的证明",b="塞娜尼·雷心驻扎在灰谷的部落部队中，她考验旅者不仅在于他们对大酋长的忠诚，更在于他们对荒野生存的理解。灰谷狩猎的目标是徘徊在古老枝叶下的三只传奇掠食者：熊Ursangous、猫科动物Shadumbra以及凶猛的角鹰兽Sharptalon。击败这三只野兽并获得它们的战利品，证明了挑战者的血管中流淌着真正的猎人血统。"},{t="祭奠先祖",b="对于牛头人来说，狩猎是一种神圣的平衡与尊重的行为，即使是在激烈的战争前线也是如此。通过战胜灰谷的顶级恐怖生物，猎人可以荣耀大地之灵，并获得雷心的先祖祝福。狩猎最终以正式的嘉奖和恩惠信物告终，这巩固了勇士在整个森林中的声望。"}},faq={{q="谁提供了这个任务？他们位于何处？",a="该任务由塞娜尼·雷心结案，她是一位驻扎在灰谷古老森林中与部落并肩作战的牛头人猎人。",al={"任务发布者","任务交还地点","塞娜尼·雷心位置"}},{q="完成狩猎有什么要求？",a="你必须杀死徘徊在灰谷的三只顶级掠食者，并提交它们被击杀的证明：熊Ursangous的爪子、夜刃豹Shadumbra的头颅，以及角鹰兽Sharptalon的爪子。",al={"要杀死的野兽","先决条件","哪些动物"}},{q="塞娜尼·雷心为什么要猎杀这些野兽？",a="狩猎是对力量和坚韧的考验。击败如此强大的野兽证明了旅者拥有真正的猎食者之心和本能，能够在这片灰谷险恶的荒野中生存下来。",al={"为什么要狩猎它们","塞娜尼的动机","狩猎目的"}},{q="对于部落来说，狩猎的文化意义是什么？",a="对于像塞娜尼·雷心这样的牛头人来说，在强大的野兽面前考验自己的勇气是一种光荣的传统，可以告慰灵魂和先祖。这展示了对荒野的掌控力，且没有鲁莽的不荣誉行为。",al={"牛头人狩猎传说","文化意义","牛头人为什么要狩猎野兽"}},{q="整个部落都认可这项试炼吗？",a="是的。完成狩猎意味着你在灰谷的部落成员眼中成为了一名合格的猎人，并赢得了先祖的祝福和同志们的尊重。",al={"部落的认可","是否正式","部落嘉奖"}},{q="灰谷狩猎的目标是哪三只野兽？",a="目标是巨熊Ursangous、潜行者夜刃豹Shadumbra和致命的角鹰兽Sharptalon。",al={"三只野兽","狩猎目标","命名动物"}}},fp="18,194,16.381.0,22.347.0,49.90.0,47.126.0,53.178.0,59.205.0,45.150.0,54.104.0"}
P.entries["quest:2478"] = {n="基本不可能的任务",s="这项关键任务旨在考验部落潜行者的潜行、偷窃和战斗技巧，地点位于贫瘠之地北部的荆棘谷地精哨站。特工需要潜入一座石油塔，暗杀总工头普兹克·加里维克斯，并为破碎之手窃取一种强效化学混合剂。",h="这项关键任务旨在考验部落潜行者的潜行、偷窃和战斗技巧，地点位于贫瘠之地北部的荆棘谷地精哨站。特工需要潜入一座石油塔，暗杀总工头普兹克·加里维克斯，并为破碎之手窃取一种强效化学混合剂。",kw={"贫瘠之地","费苏勒","开锁","毒药","普兹克·加里维克斯","破碎之手","申苏尔","斯利希兹","淤泥沼泽","赞吉尔"},ang={["class:Rogue"]="这一入会仪式教授了开锁、偷窃和利用弱点的实际外勤经验，是通往破碎之手致命贸易和毒药技术的入门途径。",["faction:Horde"]="破碎之手在奥格瑞玛的阴影中运作，密切监视着像荆棘谷地精这样利用贫瘠之地的危险企业入侵者。"},sec={{t="潜入荆棘谷地精",b="在淤泥沼泽石油钻井的北面，荆棘谷地精维护着一座与世隔绝的钻井塔。在工头费苏勒——一名潜伏在荆棘谷地精内部并伪装成主管的破碎之手特工——的命令下，潜行者被要求使用经典的地下手段，而不是直接发动突袭。费苏勒要求潜行者从工头斯利希兹身上直接扒窃一把钥匙，并为他保管好，然后一路攀升，穿过那些受到严重影响的工人和哨兵。"},{t="化学灾难",b="塔内的居住者受到了某种实验性物质的深远影响：赞吉尔的变异混合剂。虽然这种毒素削弱了卫兵——使他们异常容易受到快速打击、流血攻击和突然伏击——但也使得该设施极其不稳定。在塔顶潜伏着总工头普兹克·加里维克斯，他守护着装有这种不稳定药剂的锁箱。"},{t="职责的代价",b="撬开加里维克斯的锁箱必然会让潜行者暴露在变异混合剂的毒性蒸汽中，从而遭受一种会破坏潜行并消耗活力的、持久且虚弱的折磨。任务最终回到奥格瑞玛，与破碎之手的导师申苏尔汇合。他会收下加里维克斯的头颅和化学样本，同时默默哀悼费苏勒陷入危险的处境，并派遣这名垂死的特工去寻找解药。"}},faq={{q="荆棘谷地精的塔在哪里？",a="这座塔位于贫瘠之地的北部，就在淤泥沼泽钻井作业点的北面。它的周围环绕着敌对的荆棘谷地精工人，工头费苏勒就躲在东边附近的一棵树旁。",al={"荆棘谷地精塔位置","加里维克斯塔在哪里","淤泥沼泽塔"}},{q="如何获得通往塔楼的钥匙？",a="塔楼钥匙属于工头斯利希兹，他在塔基外的场地游荡。你必须使用潜行并对他进行偷窃来获得钥匙；杀掉他是无法获得该物品的。",al={"斯利希兹塔钥匙","如何获得塔钥匙","钥匙在哪里"}},{q="什么是赞吉尔的变异混合剂？",a="这是一种源自臭名昭著的巨魔巫医赞吉尔配方的炼金混合物。荆棘谷地精获得了这种物质，但其不稳定的烟雾毒害了塔内的工人，使他们变得病恹恹、发生变异，并且在潜行者的战斗艺术面前显得十分脆弱。",al={"赞吉尔混合剂","毒药是什么","变异混合剂"}},{q="为什么我在打开锁箱后无法潜行？",a="打开加里维克斯的锁箱会释放出浓缩的变异混合剂烟雾。由此产生的毒性减益效果会持续数天，消耗你的属性，并使你在被经验丰富的药剂师治愈之前无法保持隐身状态。",al={"赞吉尔之触","宝箱后的中毒","潜行者任务无法潜行","7天毒药"}},{q="谁是工头费苏勒？",a="费苏勒是部落潜行者组织——破碎之手的深层潜伏特工。他是一名伪装成贫瘠之地无情荆棘谷地精工头的黑铁矮人，他指导新兵破坏荆棘谷地精的资产，同时不暴露自己的身份。",al={"费苏勒","谁发布了这个任务","费苏勒背景故事"}},{q="谁是总工头普兹克·加里维克斯？",a="总工头普兹克·加里维克斯是负责指挥淤泥沼泽附近荆棘谷地精塔楼的地精主管。他一直守护着被窃取的赞吉尔混合剂储备，直到被破碎之手的特工杀死。",al={"普兹克·加里维克斯","加里维克斯在贫瘠之地吗","工头加里维克斯"}}},fp="34,228,31.395.0,22.320.1,17.367.2,39.210.0,39.156.0,33.271.0,53.210.1,26.259.0,36.199.0"}
P.entries["quest:2479"] = {n="希诺特的帮助",s="“希诺特的帮助”是一次迫切的旅程，旨在拯救身中致命热带毒素的部落潜行者。在贫瘠之地的渗透任务中，这些潜行者中了毒，需要塔伦米尔的瑟尔格·希诺特提供专业诊疗。寻找他的帮助不仅能带来救命的解药，还能习得调制致命毒药的艺术。",h="“希诺特的帮助”是一次迫切的旅程，旨在拯救身中致命热带毒素的部落潜行者。在贫瘠之地的渗透任务中，这些潜行者中了毒，需要塔伦米尔的瑟尔格·希诺特提供专业诊疗。寻找他的帮助不仅能带来救命的解药，还能习得调制致命毒药的艺术。",kw={"希尔斯布莱德丘陵","希诺特的帮助","潜行者毒药任务","瑟尔格·希诺特","申苏尔","塔伦米尔","幽暗城飞艇","赞吉尔","赞吉尔的药剂"},ang={["class:Rogue"]="这个成人仪式架起了潜行技能与炼金艺术之间的桥梁，在考验潜行者耐力的同时，也为你开启了自制毒药的大门。",["faction:Horde"]="这次任务展示了卡利姆多的兽人和巨魔潜行者与洛丹伦被遗忘者的邪恶炼金知识之间紧密的实践合作。"},sec={{t="中毒危机",b="在大胆潜入淤泥沼泽北部的荆棘谷地精塔楼之后，潜行者们中了赞吉尔调制的混合毒剂。这种毒药对身体造成了极大的破坏，迟钝了反应能力，甚至危及生命。奥格瑞玛的潜行者训练师申苏尔认识到这种毒素的严重性，承认当地的治疗手段无法应对，于是指引这名中毒的特工跨海前往东部王国。"},{t="前往塔伦米尔",b="寻找解药的旅程将引导你穿过洛丹伦大陆南部，前往希尔斯布莱德丘陵的塔伦米尔村。那里住着药剂师瑟尔格·希诺特，他对剧毒药剂的痴迷使他成为分析这些异域样本的最佳人选。当普通的治疗者对赞吉尔的毒液退避三舍时，希诺特却怀着专业的兴奋感对待这种致命化合物，渴望剖析这种邪恶的混合剂，并指导有前途的潜行者调配他们自己的毒药。"}},faq={{q="为什么我需要去见瑟尔格·希诺特？",a="瑟尔格·希诺特是一位居住在塔伦米尔的专家级药剂师，专门研究稀有毒素及其解毒剂。普通的治疗者无法清除赞吉尔的混合毒剂，因此希诺特是唯一有能力分析这种化合物、拯救你的生命并教授毒药学艺术的联络人。",al={"为什么找希诺特","谁能解毒","瑟尔格·希诺特的作用"}},{q="塔伦米尔在哪里？",a="塔伦米尔是希尔斯布莱德丘陵北部的一处被遗忘者定居点。从奥格瑞玛出发，乘坐飞艇前往提瑞斯法林地的幽暗城，然后穿过银松森林向南行进，沿路向东转入希尔斯布莱德。",al={"塔伦米尔的位置","如何前往塔伦米尔","希诺特在哪里"}},{q="我最初是怎么中毒的？",a="你是在贫瘠之地淤泥沼泽北部的荆棘谷地精塔楼执行隐秘任务“任务：可能的，但不现实的”时感染的。打开高安全级别的箱子使你接触到了赞吉尔的混合毒剂，留下了挥之不去的衰弱性毒素。",al={"我怎么中的赞吉尔毒药","任务：可能的，但不现实的毒药","我为什么中毒"}},{q="瑟尔格·希诺特收到样本后会发生什么？",a="一旦希诺特收到样本，他会检查其属性并准备解药来净化你的系统。在治愈毒素后，他会分享他的专业知识，使潜行者能够掌握毒药的调配和使用方法。",al={"希诺特任务后续","我会被治愈吗","希诺特的帮助之后"}},{q="申苏尔是谁？他为什么要让我离开？",a="申苏尔是位于奥格瑞玛大断崖的碎手氏族潜行者训练师。他监督了你在贫瘠之地的技能测试，并认识到赞吉尔的药剂已经远远超出了奥格瑞玛的医疗知识水平，需要希尔斯布莱德的专家来处理。",al={"申苏尔是谁","申苏尔 奥格瑞玛","训练师为什么让我离开"}},{q="其他职业能完成这个任务吗？",a="不能。这个任务是潜行者专属训练任务链的一部分，旨在解锁调配毒药和解药的基础学科。",al={"潜行者专属任务","战士能做希诺特的帮助吗"}}},fp="19,233,19.332.0,22.383.0,34.240.0,29.226.0,42.279.0,52.221.1,44.250.0,40.108.0"}
P.entries["quest:248"] = {n="监视",s="“深入调查”是一项由法师塞欧克瑞图斯通过魔法通道指派的联盟间谍任务。为了调查背叛的法师摩根斯与黑石兽人之间的紧张局势，你必须潜入石堡要塞旁边的瞭望塔，并将一个附魔雕文放置在一个不起眼的容器中。",h="“深入调查”是一项由法师塞欧克瑞图斯通过魔法通道指派的联盟间谍任务。为了调查背叛的法师摩根斯与黑石兽人之间的紧张局势，你必须潜入石堡要塞旁边的瞭望塔，并将一个附魔雕文放置在一个不起眼的容器中。",kw={"空罐子","阿祖拉的铭文饰品","深入调查","摩根斯","老狮子雕像","石堡","石堡要塞","塞欧克瑞图斯","伊尔加拉之塔"},ang={["class:Mage"]="塞欧克瑞图斯依赖通过阿祖拉的铭文饰品进行的精密远程占卜魔法，展示了阿祖拉的法师是如何在敌对领土上建立魔法监视网络的。",["faction:Alliance"]="石堡要塞仍然是黑石氏族在赤脊山的主要据点。收集他们与摩根斯内斗的情报对于保卫湖畔镇至关重要。"},sec={{t="赤脊山的裂痕",b="塞欧克瑞图斯在艾尔文森林的圣所中，通过占卜魔法时刻监视着赤脊山东部的情况。在监视伊尔加拉之塔时，他察觉到背叛的人类术士摩根斯与盘踞在石堡要塞的黑石兽人之间突然爆发了争执。这两个敌对派系并没有联手对抗暴风城，反而为了某种未知的战利品陷入了冲突，这促使塞欧克瑞图斯在局势失控前介入其中。"},{t="石堡之眼",b="为了突破石堡要塞的防御，塞欧克瑞图斯需要第二个魔法锚点。他命令冒险者爬上那座矗立在废弃堡垒旁、保存完好的瞭望塔。在那里，在一堆守卫留下的杂物中，兽人哨兵丢弃的一个空罐子是个完美的隐藏点。一旦阿祖拉的铭文饰品被放入罐中，塞欧克瑞图斯就能通过心灵感应筛选石堡内的思想，揭开摩根斯和黑石兽人决裂的真相。"}},faq={{q="谁指派我执行这项任务？",a="在你完成他之前的任务后，这个任务由阿祖拉的法师塞欧克瑞图斯通过赤脊山的老狮子雕像传达给你。",al={"任务发放者","老狮子雕像"}},{q="塞欧克瑞图斯为什么要监视石堡要塞？",a="塞欧克瑞图斯发现伊尔加拉之塔的背叛黑魔法师摩根斯与盘踞在石堡要塞的黑石兽人之间正在酝酿敌意。他希望能查明引发他们冲突的原因。",al={"为什么要监视兽人","塞欧克瑞图斯的目的","为什么是石堡"}},{q="容器在哪里？",a="这个容器是一个空罐子，放在石堡要塞主入口旁边那座保存完好的瞭望塔顶部的木桶上。",al={"空罐子的位置","放置铭文的地方","瞭望塔在哪里"}},{q="阿祖拉的铭文饰品有什么作用？",a="它作为一种魔法占卜和预言的焦点，使塞欧克瑞图斯能够远程监视周边地区，并探查要塞内黑石兽人的思想。",al={"阿祖拉的铭文饰品的作用","铭文饰品的作用"}},{q="放置铭文后会发生什么？",a="一旦塞欧克瑞图斯占卜出冲突的根源，他会指派你去伊尔加拉之塔亲自追捕摩根斯，并带回他的暗影坠饰。",al={"下一个任务","接下来发生什么","深入调查后续"}},{q="为什么要用一个空罐子？",a="魔法间谍符文需要一个不起眼的容器，这样守卫才不会发现或摧毁它。那个被遗忘在木桶上、散发着恶臭的酒罐是一个理想的藏身之处。",al={"为什么用罐子","空罐子的背景信息"}}},fx={["3912e7be"]={q="我在石堡要塞监视谁？",a="你要监视占据石堡要塞的黑石兽人。法师塞欧克瑞图斯从观察点发现，这些敌对兽人与伊尔加拉之塔的黑暗法师摩根斯之间正酝酿着冲突。放置雕文能让法师探查石堡要塞内众人的思想，找出这场摩擦的真正原因。",al={"石堡要塞里有什么人","石堡要塞目标","深入探查任务目标"}},["6347ef38"]={q="为什么塞欧克瑞图斯需要冒险者去放置雕文？",a="塞欧克瑞图斯驻守在阿祖拉之塔，借助古老的狮子雕像等附魔遗物施展法术，监视赤脊山各处的威胁。石堡要塞里到处都是危险的黑石兽人，要潜入这座据点，就需要有人能一路战斗而不被发现地进入塔中；独自一人的脆弱法师不能轻易离开岗位。",al={"为什么派我深入探查","塞欧克瑞图斯为什么不自己做","为什么派我去石堡"}}},fp="15,241,18.418.0,21.425.1,29.129.0,44.201.0,31.114.0,32.182.0,38.141.1,21.170.0"}
P.entries["quest:2480"] = {n="希诺特的帮助",s="“希诺特的帮助”是部落潜行者历经艰险，克服赞吉尔致命剧毒之旅的终章。深受毒害的潜行者来到塔伦米尔，求助于药剂师瑟尔格·希诺特，不仅得到了解毒剂，还学到了炼金毒药学的入门知识。",h="“希诺特的帮助”是部落潜行者历经艰险，克服赞吉尔致命剧毒之旅的终章。深受毒害的潜行者来到塔伦米尔，求助于药剂师瑟尔格·希诺特，不仅得到了解毒剂，还学到了炼金毒药学的入门知识。",kw={"解毒剂","治愈","希尔斯布莱德","希诺特","毒药","潜行者任务","瑟尔格·希诺特","塔伦米尔","赞吉尔"},ang={["class:Rogue"]="这场成年礼治愈了你在入门阶段所遭受的削弱性病痛，并解锁了调制战术毒药所需的知识。",["faction:Horde"]="被遗忘者炼金术对部落的潜行特工来说至关重要，它将奇异的丛林巨魔毒素转化为了标准的战场知识。",["race:Undead"]="药剂师希诺特体现了皇家药剂师学会那种超然的科学态度：无论来源如何，只要是展现出真正工艺的毒药，都能赢得他们的赞赏。"},sec={{t="剧毒杰作",b="在贫瘠之地执行任务时感染了一种致命的致幻毒素后，部落潜行者被指引前往北方的塔伦米尔咨询瑟尔格·希诺特。作为一名专注的被遗忘者化学家，希诺特对丛林巨魔流亡者赞吉尔配制的毒药表现出职业般的敬畏。虽然并不关心这名巨魔的身份或血统，但希诺特公开称赞了这种药剂的致命效力，并迫切想要在研制解毒剂之前研究其作用机理。"},{t="解毒剂与毒药学",b="研制解毒剂只需等待希诺特分离出活性成分。成品药剂能阻止那逐渐蔓延的疯狂，尽管这位化学家承认他无法洗去那种挥之不去的恶臭。在清除了这种削弱能力的剧毒后，潜行者完成了从受害者到实践者的转变，利用希诺特对赞吉尔手笔的见解，开始掌握制作属于自己的战术毒药的方法。"}},faq={{q="“希诺特的帮助”任务过程中会发生什么？",a="你只需在塔伦米尔等待片刻，让瑟尔格·希诺特准备解毒剂。一旦他完成配制，与他交谈即可服用治愈药物，清除赞吉尔的毒素。",al={"我该做什么","希诺特的帮助流程","如何完成任务"}},{q="谁是瑟尔格·希诺特？",a="瑟尔格·希诺特是一位被遗忘者炼金术士和毒药专家，驻扎在希尔斯布莱德丘陵的塔伦米尔。他将自己的专业技艺传授给部落潜行者，帮助他们治愈奇异的病痛，并学习毒药制作的复杂知识。",al={"瑟尔格·希诺特背景","希诺特是谁","塔伦米尔药剂师"}},{q="为什么瑟尔格·希诺特会对这种毒药印象深刻？",a="希诺特认为赞吉尔的配方是炼金设计上的杰作，因为它将逐渐蔓延的疯狂与身体虚弱完美地结合在了一起。即使在努力中和它时，他也公开称赞了这种破坏性药剂背后的工艺。",al={"赞吉尔毒药反应","为什么希诺特喜欢它"}},{q="希诺特提到的挥之不去的恶臭是什么？",a="赞吉尔的药剂带有一种刺鼻的、令人作呕的气味，会渗入受害者的毛孔。虽然希诺特的解毒剂成功阻止了毒素的蔓延并清除了意识的混乱，但它无法立即中和残留的恶臭。",al={"为什么我身上有味道","疯狂的气味","任务气味"}},{q="完成这个任务有什么奖励？",a="完成这项任务可以清除潜行者职业任务线中染上的持续性减益效果，并开启学习“潜行者毒药”技能的途径，让玩家能够调制自己的致残药剂。",al={"潜行者获得什么","希诺特的帮助奖励"}},{q="这个任务在哪里交？",a="该任务直接在位于希尔斯布莱德丘陵北部的塔伦米尔找瑟尔格·希诺特开始和完成。",al={"希诺特在哪里","交任务地点"}}},fp="19,140,19.364.0,26.305.1,40.152.0,20.172.0,44.188.0,44.173.0,45.147.0,30.113.0"}
P.entries["quest:249"] = {n="莫甘斯",s="“摩根斯”是塞欧克瑞图斯这位法师在一系列针对赤脊山险恶敌手的漫长调查后，所发布的最终任务。探险者们受命去阻止一名觊觎恐怖远古圣物的黑暗术士，必须攻破伊尔加拉之塔，终结他的阴谋。",h="“摩根斯”是塞欧克瑞图斯这位法师在一系列针对赤脊山险恶敌手的漫长调查后，所发布的最终任务。探险者们受命去阻止一名觊觎恐怖远古圣物的黑暗术士，必须攻破伊尔加拉之塔，终结他的阴谋。",kw={"艾尔文","摩根斯","暗影坠饰","赤脊山","艾露恩之镰","塞欧克瑞图斯","阿祖拉之塔","伊尔加拉之塔"},ang={["class:Mage"]="塞欧克瑞图斯代表了人类法师勤奋、学术的传统，他们在高塔之上守望，保护王国免受邪恶施法者的侵害。",["class:Warlock"]="摩根斯代表了不受约束的邪能和暗影野心的危险，证明了觊觎艾露恩之镰这样的圣物只会招致毁灭。",["faction:Alliance"]="击败摩根斯保护了暴风城暴露的东部边界，确保赤脊山地区不会陷入黑暗魔法的侵蚀。",["race:NightElf"]="艾露恩之镰在人类手中低语，这应该会让卡多雷深感惊恐，因为圣物的名字触及了神圣且不稳定的奥秘。"},sec={{t="边界的守望者",b="法师塞欧克瑞图斯在艾尔文森林东部的阿祖拉之塔中建立了自己的避难所，并一直保持警惕，用奥术视界监视着赤脊山的峭壁。他所观察到的景象证实了他内心深处的恐惧：那个盘踞在伊尔加拉之塔的术士摩根斯，正在积极搜寻传说中的艾露恩之镰。塞欧克瑞图斯意识到这名术士即将掌握这股黑暗力量，于是召唤勇敢的联盟勇士进行干预，以免摩根斯的阴影笼罩整个暴风城王国。"},{t="突袭高塔",b="伊尔加拉之塔高耸在赤脊山盆地上方，到处都是豺狼人和扭曲的奥术能量。摩根斯在塔顶等待着，挥舞着暗影魔法并守护着他的研究成果。要对付这名术士，就需要穿过充满敌意的地带登上塔顶，直接将他斩杀，并夺取他的暗影坠饰作为铁证，证明高塔已被攻陷，威胁已被消除。"},{t="艾露恩之镰挥之不去的阴影",b="虽然摩根斯的失败消除了暴风城眼下的毁灭性威胁，但他对艾露恩之镰的追寻却揭示了这件圣物的黑暗传说影响深远。当塞欧克瑞图斯收到暗影坠饰并松了一口气时，这把远古镰刀的真正下落以及它可能带来的浩劫，对于周边省份来说依然是一个令人不安的谜团。"}},faq={{q="谁是摩根斯？",a="摩根斯是一位强大的邪恶术士，居住在赤脊山的伊尔加拉之塔顶端。他花费时间研究黑暗艺术并追寻艾露恩之镰，这是一件能够施展灾难性魔法的圣物。",al={"摩根斯身份","谁是摩根斯","摩根斯背景故事"}},{q="伊尔加拉之塔在哪里？",a="伊尔加拉之塔位于赤脊山东部，石堡要塞之外，影皮豺狼人就在塔基周围扎营。",al={"伊尔加拉之塔位置","摩根斯之塔在哪里","赤脊山高塔"}},{q="为什么塞欧克瑞图斯想要摩根斯死？",a="通过他的占卜法术，塞欧克瑞图斯得知摩根斯正在搜寻艾露恩之镰，并担心这名术士即将得手。这种黑暗力量将对赤脊山和邻近的暴风城王国构成灾难性的威胁。",al={"塞欧克瑞图斯的动机","为什么要杀摩根斯","塞欧克瑞图斯任务原因"}},{q="什么是艾露恩之镰？",a="艾露恩之镰是一件笼罩在谜团中的圣物。塞欧克瑞图斯没有解释它的力量，但他担心如果摩根斯找到了它，赤脊山和暴风城王国很快就会感受到这位术士的黑暗力量。",al={"艾露恩之镰背景传说","什么是艾露恩之镰","为什么艾露恩之镰很危险"}},{q="什么是暗影坠饰？",a="暗影坠饰是摩根斯的魔法护身符，既作为他黑暗艺术的焦点，也是当带回阿祖拉之塔交给塞欧克瑞图斯时，证明他已被击败的确凿证据。",al={"暗影坠饰","摩根斯的坠饰","摩根斯死亡的证明"}},{q="什么任务线引出了这个任务？",a="这是四部分任务链的终章，始于艾尔文森林的“塞欧克瑞图斯的收回”，随后是“警惕之眼”和“进一步调查”，内容涉及取回工具并布置占卜仪式以监视摩根斯之塔。",al={"摩根斯任务线","摩根斯前提条件","如何解锁摩根斯"}}},fp="8,67,27.327.0,18.369.0,29.322.1,16.217.0,30.133.0,39.215.0,28.191.0,30.168.0,34.219.0"}
P.entries["quest:2498"] = {n="向德纳兰回报",s="“回到德纳兰身边”是一个联盟任务，连接了正在调查泰达希尔内部腐蚀现象的植物学家们。在研究了折磨当地树苗怪的苔藓肿瘤后，Rellian Greenspyre把你派回南边的奥拉密斯湖，去协助德纳兰处理一项令人震惊的新发现。",h="“回到德纳兰身边”是一个联盟任务，连接了正在调查泰达希尔内部腐蚀现象的植物学家们。在研究了折磨当地树苗怪的苔藓肿瘤后，Rellian Greenspyre把你派回南边的奥拉密斯湖，去协助德纳兰处理一项令人震惊的新发现。",kw={"德纳兰","多兰纳尔","奥拉密斯湖","oakenscowl","rellian greenspyre","泰达希尔","树苗怪","肿瘤"},ang={["class:Druid"]="调查林地灵体身上不自然的肿瘤，触及了塞纳里奥议会维护自然平衡和净化阴险枯萎病这一使命的核心。",["race:NightElf"]="树苗怪是泰达希尔生命力的活体体现；协助德纳兰是治愈威胁到你族人新家园的日益严重的腐蚀这一神圣职责的一部分。"},sec={{t="枝叶间的讯息",b="在检查泰达希尔树苗怪身上奇异的苔藓肿瘤时，Rellian Greenspyre收到了同事德纳兰的紧急消息。德纳兰驻扎在平静的奥拉密斯湖畔，他认为自己终于查明了是什么导致了这些森林自然之灵身上出现的不自然生长。意识到局势的严重性，Rellian立即把你派回南边去伸出援手。"},{t="湖畔的威胁",b="德纳兰在奥拉密斯湖的研究对于了解蔓延在这棵年轻世界之树上的病症至关重要。最初对受腐蚀植物和患病树苗怪的调查，很快升级为与毒害树枝的枯萎实体之间的直接对抗，而这一切始于那只受到腐蚀的树苗怪Oakenscowl。"}},faq={{q="德纳兰是谁？",a="德纳兰是一位暗夜精灵研究员兼博物学家，驻扎在泰达希尔南部的奥拉密斯湖。他致力于研究岛上的植物群、奇异的幼苗变异，以及在当地树苗怪中蔓延的不自然病症。",al={"德纳兰背景故事","德纳兰是谁","德纳兰 奥拉密斯湖"}},{q="为什么Rellian Greenspyre要让你回到奥拉密斯湖？",a="Rellian收到消息称，德纳兰已经发现了导致树苗怪身上肿瘤的可能根源。由于局势发展迅速，且对森林构成了日益严重的威胁，Rellian派你前去提供及时的实地援助。",al={"为什么要去德纳兰那里","rellian greenspyre的任务"}},{q="困扰树苗怪的肿瘤是什么？",a="树苗怪是诞生于岛上植物群的宁静自然之灵，但泰达希尔内部滋生的一种弥漫性腐蚀导致它们长出了奇异的苔藓状赘生物。这些肿瘤使这些生物变得充满敌意且疯狂。",al={"树苗怪肿瘤","为什么树苗怪会长肿瘤","苔藓肿瘤"}},{q="我在哪里可以找到德纳兰？",a="德纳兰在奥拉密斯湖岸边扎营，就在泰达希尔南部林地多兰纳尔的南边。",al={"德纳兰位置","德纳兰在哪里"}},{q="到达德纳兰那里后会发生什么？",a="德纳兰欢迎你的帮助，并说他发现了一些令人不安的事情。当你到达他的营地时，他会向你解释接下来的任务。",al={"what comes next","oakenscowl后续任务"}},{q="这个差事是如何联系起Rellian和德纳兰的？",a="这项差事将Rellian Greenspyre在达纳苏斯的树苗怪研究与德纳兰在奥拉密斯湖的营地联系了起来，将Rellian对肿瘤的研究带到了德纳兰关于其病因的新发现之中。",al={"为什么rellian要派我去找德纳兰","回到德纳兰的目的"}}},fp="17,218,27.357.0,22.221.1,15.214.0,59.238.0,47.214.0,25.109.0,37.128.1,49.198.0"}
P.entries["quest:2499"] = {n="奥肯斯古尔",s="德纳兰请求冒险者去终结橡木之怒（Oakenscowl），一个被巨大的瘤所腐蚀的强大树妖。这只疯狂的生物栖息在奥拉密斯湖南岸的一个洞穴中，它正在向当地的野生生物散播枯萎病。",h="德纳兰请求冒险者去终结橡木之怒（Oakenscowl），一个被巨大的瘤所腐蚀的强大树妖。这只疯狂的生物栖息在奥拉密斯湖南岸的一个洞穴中，它正在向当地的野生生物散播枯萎病。",kw={"腐蚀","德纳兰","巨大的瘤","奥拉密斯湖","苔藓状的瘤","橡木之怒","泰达希尔","树妖"},ang={["class:Druid"]="看到一个守护者树妖被奇怪的瘤所腐蚀，这对于德鲁伊们来说是一个痛苦的提醒，即泰达希尔正在萌芽的生态系统已经病得很重了。",["profession:Herbalism"]="协助德纳兰的草药师们亲眼目睹了植物生命如何在无形腐烂的影响下，扭曲成恶性的苔藓状枯萎物。",["race:NightElf"]="橡木之怒的悲剧下场冲击着暗夜精灵社会的核心，威胁到了多兰纳尔以南的奥拉密斯湖。"},sec={{t="堕落的守护者",b="橡木之怒曾是树妖中的一位伟大领袖，这些树妖是照料泰达希尔茂密枝叶的森林之灵。可悲的是，在世界之树蔓延的腐蚀并不区分卑微的野生生物和古老的保护者。由于树皮上隆起的巨大的瘤，橡木之怒变得狂乱，它不再是生长的管家，而成为了枯萎病的载体。"},{t="净化奥拉密斯湖",b="橡木之怒潜伏在奥拉密斯湖南岸的一个洞穴里，它那有毒的存在正在主动毒害周围的水域和林地野兽。德纳兰无法独自面对这只野兽，他寻求消灭该生物并非出于恶意，而是为了仁慈地切断腐蚀的源头，并研究那种困扰着湖中之灵的怪异而巨大的瘤。"}},faq={{q="什么是橡木之怒？",a="橡木之怒是一个巨大的树妖——一种与泰达希尔植物生命相连的森林之灵。在遭受恶性增生之前，他曾被视为同类中高贵的领袖。",al={"谁是橡木之怒","橡木之怒背景故事","橡木之怒是什么生物"}},{q="为什么必须消灭橡木之怒？",a="橡木之怒被一个巨大的瘤所折磨，这扭曲了他的心智并使他变得极具攻击性。他潜伏在奥拉密斯湖边的洞穴中，正在向邻近的树妖和野兽主动散播这种奇怪的枯萎病。",al={"为什么要杀橡木之怒","橡木之怒敌对"}},{q="橡木之怒住在哪里？",a="橡木之怒居住在泰达希尔南部，奥拉密斯湖南岸深处的一个洞穴里。",al={"橡木之怒位置","橡木之怒洞穴在哪里"}},{q="谁是德纳兰，他为什么要研究那个瘤？",a="德纳兰是一位住在奥拉密斯湖东岸的草药师和博物学家。他研究世界之树的动植物，致力于了解并治愈感染当地树妖种群的那种奇怪的腐烂病。",al={"谁发布橡木之怒任务","德纳兰 橡木之怒"}},{q="是什么导致了橡木之怒身上的瘤？",a="这个瘤是一种更深层、更阴险的疾病的症状，这种疾病正在泰达希尔的土壤和根系中蔓延，从内部腐蚀着自然之灵。",al={"为什么树妖会长瘤","腐蚀源头"}},{q="橡木之怒是否已经无法拯救了？",a="当冒险者遇到他时，病情已经发展得太严重了。那个瘤已经彻底扭曲了这个生物，让德纳兰别无选择，只能要求给予他仁慈的终结。",al={"橡木之怒能被治愈吗","治疗橡木之怒"}}},fp="10,186,17.306.0,21.276.0,19.154.0,33.168.0,29.92.0,48.206.0,36.123.0,28.164.0"}
P.entries["quest:25"] = {n="石爪山的困境",s="“石爪山脉的停滞”是碎木岗哨的马斯托克·维尔西斯发布的一项部落任务，旨在确保通往石爪山脉的重要通道安全。密斯特拉湖中受污染的水元素阻断了补给运输，促使部落必须清除敌对的灵魂，并侦察一座可以俯瞰附近联盟动向的精灵凉亭。",h="“石爪山脉的停滞”是碎木岗哨的马斯托克·维尔西斯发布的一项部落任务，旨在确保通往石爪山脉的重要通道安全。密斯特拉湖中受污染的水元素阻断了补给运输，促使部落必须清除敌对的灵魂，并侦察一座可以俯瞰附近联盟动向的精灵凉亭。",kw={"受污染的水元素","凉亭","马斯托克·维尔西斯","密斯特拉湖","碎木岗哨","石爪山脉的停滞","石爪小径","海潮恩"},ang={["class:Shaman"]="密斯特拉湖水元素的扭曲状态，揭示了灰谷古老森林中正在滋生的严重的元素失调。",["faction:Horde"]="如果没有畅通的后勤通道，碎木岗哨就无法生存；确保石爪小径的安全对于维持与石爪山脉的通讯和贸易至关重要。",["race:Orc"]="部落的勇士们依赖灰谷的木材和道路来维持定居点的运转，因此山脉补给线的受阻是不可接受的。"},sec={{t="阻塞的补给路线",b="要维持部落在灰谷的立足点，就需要木材、补给和信使在森林与石爪山脉的群峰之间源源不断地往来。石爪小径是这条关键的命脉，沿着密斯特拉湖的西岸延伸。当湖水因敌对的水元素而剧烈翻腾时，交通便完全中断了。运输车队遭到愤怒的水之灵的袭击，促使马斯托克·维尔西斯要求立即采取行动，以免后勤补给线彻底崩溃。"},{t="腐化的水域",b="密斯特拉湖不再是一处宁静的林间避难所。游荡在湖底深处的水元素已经变得肮脏、具有攻击性且难以预料，它们会无差别地袭击任何试图穿越周边小径的人。清除这些水之恶魔，并终结高等灵魂海潮恩的统治，对于恢复当地的安全至关重要。然而，在灰谷圣林笼罩于大范围动荡之中的背景下，它们受污染的根源仍然是一个不祥的谜团。"},{t="水面之眼",b="除了平定湖中愤怒的灵魂外，部落还发现了密斯特拉湖中央岛屿上的一个战略机遇。岛上坐落着一座古老的暗夜精灵凉亭，这里是一个绝佳的视点，可以隔水俯瞰附近的暗夜精灵定居点银风避难所。通过侦察这座建筑，部落斥候可以评估这些废墟是否能作为前哨观察点，确保碎木岗哨的指挥官们能够密切监视他们在卡利姆多的对手，而不被对方发现。"}},faq={{q="是什么导致了石爪山脉附近的停滞？",a="栖息在密斯特拉湖的受污染水元素变得狂暴，攻击沿邻近的石爪小径行进的旅人。这种攻击行为阻断了灰谷与石爪山脉之间往来的补给运输。",al={"为什么补给运输停止了","石爪小径被封锁","是什么阻断了补给路线"}},{q="是谁下令清除这些水元素？",a="驻扎在灰谷东部碎木岗哨的兽人马斯托克·维尔西斯，下达了这项旨在恢复部落贸易路线并探察联盟阵地的任务。",al={"谁发布了“石爪山脉的停滞”任务","马斯托克·维尔西斯任务","马斯托克是谁"}},{q="为什么要侦察密斯特拉湖中的凉亭？",a="这座凉亭提供了一个俯瞰湖面的高处视点，且正对着附近的联盟营地。马斯托克希望将其评估为隐蔽的观察点，以监控敌人的动向。",al={"为什么要侦察凉亭","密斯特拉湖凉亭的目的","凉亭观察哨"}},{q="石爪小径是什么？",a="石爪小径是连接灰谷西南部与石爪山脉的主要山道，从密斯特拉湖的西岸经过。",al={"石爪小径位置","通往石爪山脉的道路","石爪山脉道路"}},{q="为什么密斯特拉湖的水元素会受到污染？",a="灰谷中的黑暗能量和广泛的动荡破坏了自然平衡，导致密斯特拉湖的灵魂陷入疯狂，并将它们本应宁静的水域变成了对外来者的敌对之地。",al={"为什么元素会腐化","密斯特拉湖水被腐化","受污染元素的起源"}},{q="从凉亭监视的是哪座联盟据点？",a="这座凉亭可以俯瞰银风避难所，那是位于湖泊北岸的一个暗夜精灵定居点，由保卫灰谷、抵御部落伐木行动的哨兵守卫。",al={"密斯特拉湖附近有什么联盟基地","灰谷联盟据点"}}},fp="21,241,21.352.0,20.329.0,21.306.0,47.204.0,34.135.0,51.221.0,27.148.0,54.146.0,56.171.0"}
P.entries["quest:250"] = {n="水坝危机",s="主工程师辛德维尔七世担心，继在湿地发生袭击事件后，巨石水坝会成为黑铁矮人侵略的下一个目标。由于大坝的大部分防御守军已被调往别处，冒险者们被派去调查潜伏在东侧坡道附近的黑铁工兵。",h="主工程师辛德维尔七世担心，继在湿地发生袭击事件后，巨石水坝会成为黑铁矮人侵略的下一个目标。由于大坝的大部分防御守军已被调往别处，冒险者们被派去调查潜伏在东侧坡道附近的黑铁工兵。",kw={"黑铁矮人","丹莫德","辛德维尔","洛克莫丹","工兵","巨石水坝","可疑木桶","萨多尔大桥"},ang={["faction:Alliance"]="随着大陆各处前线军队兵力吃紧，联盟新兵必须挺身而出，保护重要的后方补给中心和区域基础设施。",["profession:Engineering"]="工程师们既能领略大坝那令人叹为观止的规模，也能意识到工兵在承重地基上部署挥发性化学炸药所带来的阴险威胁。",["race:Dwarf"]="巨石水坝是矮人工艺与荣耀的杰作；眼见它受到阴险的黑铁同族的威胁，使得这项调查成了关乎国家防御的大事。"},sec={{t="脆弱的奇迹",b="巨石水坝是铁炉堡最伟大的工程杰作之一，它拦截了洛克莫丹的浩瀚水域。然而，随着卡兹莫丹及其他地区冲突的持续，大坝的大部分安全守卫已被调往联盟前线。由于兵力短缺，当敌人活动逐渐逼近这座庞大的建筑时，主工程师辛德维尔七世和他留守的精简人手在面对协同攻击时几乎毫无防备。"},{t="来自北方的回响",b="辛德维尔的焦虑源于最近北部边境遭受的破坏。黑铁矮人在湿地发动了致命的协同攻击，破坏了具有战略意义的萨多尔大桥，并洗劫了要塞城镇丹莫德。观察到臭名昭著的黑铁工兵潜伏在大坝东侧坡道附近，辛德维尔意识到其中的规律：这个邪恶氏族已经将目标转向了摧毁洛克湖的生命线。"},{t="可疑的木桶",b="对下层城墙的侦察证实了这位工程师最担心的事。在工兵聚集处的岩石中，藏着一个无人看管、装满了不稳定且散发着奇怪气味的火药的可疑木桶。这充分证明黑铁矮人正在积极筹划爆破，意图摧毁巨石水坝的地基。"}},faq={{q="为什么主工程师辛德维尔会担心大坝的安全？",a="黑铁部队最近破坏了萨多尔大桥并洗劫了丹莫德，摧毁了北方的防线。看到黑铁工兵潜伏在巨石水坝的东侧坡道上，这让辛德维尔确信大坝就是他们的下一个目标。",al={"辛德维尔为何担忧","对巨石水坝的威胁","为什么要攻击水坝"}},{q="大坝的守军去哪了？",a="驻扎在巨石水坝的大部分安全部队，包括辛德维尔手下的高级督察，都被调往支援更广阔的联盟前线，导致这座关键设施防守薄弱。",al={"为什么水坝没有守卫","大坝安保","士兵去哪了"}},{q="你在东侧坡道发现了什么？",a="在发现黑铁工兵踪迹的东侧坡道附近，调查人员发现了一个装有散发奇怪气味火药的可疑木桶，证实黑铁矮人正在安放炸药企图破坏该建筑。",al={"线索是什么","可疑木桶线索","工兵在做什么"}},{q="巨石水坝有什么战略意义？",a="巨石水坝控制着洛克莫丹的水库。如果水坝决堤，洪水将对下游的湿地造成巨大的破坏，同时会排干矮人领地的核心区域。",al={"为什么要摧毁水坝","水坝决堤会发生什么","水坝背景资料"}},{q="辛德维尔提到的针对丹莫德的袭击是什么？",a="丹莫德是位于北部湿地、靠近萨多尔大桥的一座坚固矮人前哨站。黑铁渗透者攻陷了该城镇并袭击了附近的萨多尔大桥，切断了关键的陆路补给线。",al={"丹莫德袭击","丹莫德发生了什么","萨多尔大桥被毁"}},{q="针对洛克莫丹的黑铁矮人是什么人？",a="自三锤之战以来，黑铁氏族长期以来一直是铜须矮人的死敌。他们以黑石山和灼热峡谷为据点，经常破坏铜须矮人的基础设施和边境防御。",al={"黑铁矮人是谁","黑铁工兵的动机","黑铁矮人为何仇恨铁炉堡"}}},fp="19,188,19.259.0,21.221.0,19.194.1,55.196.0,32.161.0,37.160.1,59.148.0,56.196.0,51.230.0"}
P.entries["quest:251"] = {n="翻译亚伯克隆比的信",s="“翻译亚伯克隆比的笔记”是夜色镇的一项联盟任务，任务要求一名The Adventurer带着一封无法解读的信件去找镇上的学者。艾尔罗·埃伯洛克公爵无法理解这位隐居者写下的信件，只能寄希望于希拉·沃宁迪对晦涩文字的了解。这标志着夜色镇的领导层开始密切关注这位隐居者写下的古怪信件。",h="“翻译亚伯克隆比的笔记”是夜色镇的一项联盟任务，任务要求一名The...",kw={"亚伯克隆比","密码","夜色镇","暮色森林","艾尔罗·埃伯洛克公爵","隐居者","希拉·沃宁迪","翻译"},ang={["class:Mage"]="熟悉晦涩方言和奥术转录的法师们会欣赏希拉·沃宁迪作为夜色镇当地深奥文字专家的角色。",["faction:Alliance"]="对于援助暮色森林的联盟勇士来说，这件差事凸显了夜色镇的民政领导层在周围黑暗笼罩下所感受到的脆弱和孤立。"},sec={{t="一封无法解读的讯息",b="当亚伯克隆比寄出一封密封的信件给艾尔罗·埃伯洛克公爵时，这位镇长本以为会是这位墓地隐居者写来的一些古怪的请求或苦涩的胡言乱语。然而，羊皮纸上写着的却是奇怪、晦涩的文字，完全不属于通用的通用语书写系统。由于缺乏解读古代或深奥语言的学术训练，艾尔罗·埃伯洛克公爵没有直接扔掉这封信，因为他知道，即便是疯癫的隐居者在暮色森林中也可能构成威胁。"},{t="夜色镇的学者",b="为了破解密码，艾尔罗·埃伯洛克公爵指引旅行者穿过广场去寻找希拉·沃宁迪。希拉是夜色镇研究深奥知识的学者，精通古代艺术和失传的语言。虽然希拉对亚伯克隆比的理智嗤之以鼻——调侃说任何居住在闹鬼墓地旁边的人肯定脑子烂掉了——但他还是足够严肃地对待那张羊皮纸，开始进行费力的转录工作。"},{t="一窥隐居者的内心",b="将信件交出去，便为小镇拉开了一场严峻揭示的序幕。虽然亚伯克隆比此前看起来是一个虚弱、避世的老人，乞求物资和保护以抵御食尸鬼，但他写给公爵的加密信件却显示出一种远为阴险的智慧，以及一场夜色镇尚未准备好面对的即将来临的清算。"}},faq={{q="为什么艾尔罗·埃伯洛克公爵自己无法阅读这封笔记？",a="亚伯克隆比送来的信是用一种不寻常的文字或古代密码书写的。艾尔罗·埃伯洛克公爵是一位行政官和贵族，而非语言学家，所以他将其转交给夜色镇当地精通古代艺术和奥术语言的专家希拉·沃宁迪。",al={"为什么艾尔罗·埃伯洛克公爵看不懂笔记","艾尔罗·埃伯洛克公爵信件翻译","为什么需要翻译"}},{q="希拉·沃宁迪是谁？",a="希拉·沃宁迪是一位居住在夜色镇的博学之士。他以精通晦涩语言、历史和古代艺术而闻名，每当有神秘的文献或遗物从黑暗的森林中出现时，他便是镇上求助的首选学者。",al={"希拉·沃宁迪是谁","翻译者是谁","夜色镇学者"}},{q="亚伯克隆比住在哪里？",a="亚伯克隆比住在暮色森林西部、乌鸦岭墓地东北方向的一间破旧小屋里，周围环绕着不安分的亡灵和掠食性野兽。",al={"亚伯克隆比在哪里","隐居者位置","暮色森林的亚伯克隆比"}},{q="希拉对亚伯克隆比的笔记有什么反应？",a="希拉公开质疑亚伯克隆比的理智，说任何愿意住在墓地旁边的人肯定脑子烂掉了。尽管如此，他还是同意检查这封信，并开始翻译其中深奥的文字。",al={"希拉如何看待亚伯克隆比","希拉·沃宁迪对话"}},{q="把笔记交给希拉之后会发生什么？",a="希拉·沃宁迪要求The Adventurer等待，以便他进行转录工作。完成后，翻译好的信件必须带回给艾尔罗·埃伯洛克公爵。",al={"翻译笔记后的下一个任务","翻译亚伯克隆比的笔记之后是什么"}},{q="亚伯克隆比为什么要写信给艾尔罗·埃伯洛克公爵？",a="亚伯克隆比写给公爵的笔记是用艾尔罗·埃伯洛克公爵无法阅读的文字书写的。这位隐居者到底写了什么，只有在希拉·沃宁迪翻译之后才会水落石出。",al={"亚伯克隆比为什么要寄信","隐居者笔记的目的"}}},fp="28,178,25.367.0,24.337.0,32.207.1,48.143.0,22.179.0,28.142.0,47.176.0,44.137.1,45.119.1"}
P.entries["quest:2518"] = {n="月神的泪水",s="“月之泪”是女祭司艾茉拉在Temple of the Moon指派的一项庄严任务。伟大的蜘蛛萨丝拉女士曾深受艾露恩女神的眷顾，如今却陷入了疯狂，这迫使The Sisterhood of Elune不得不痛下杀手，以求终结她的苦难，并取回她神圣的丝囊。",h="“月之泪”是女祭司艾茉拉在Temple of the Moon指派的一项庄严任务。伟大的蜘蛛萨丝拉女士曾深受艾露恩女神的眷顾，如今却陷入了疯狂，这迫使The Sisterhood of...",kw={"达纳苏斯","艾露恩","萨丝拉女士","女祭司艾茉拉","银色丝囊","月之泪","泰达希尔","temple of the moon","涌泉湖"},ang={["class:Druid"]="德鲁伊们将萨丝拉突如其来的凶猛和折磨视为泰达希尔失衡的又一个令人不安的症状，这使得恢复她灵魂的纯净成为了一种生态上的必要。",["class:Priest"]="侍奉The Sisterhood of Elune的牧师们明白，慈悲有时需要通过痛苦的打击来达成，最终通过一场仪式性的祭献，将一个被腐化的灵魂归还给女神的怀抱。",["race:NightElf"]="对于卡多雷而言，除掉萨丝拉是一个痛苦的提醒，即侵蚀泰达希尔荒野的腐化既不放过卑微的野兽，也不放过艾露恩的神圣伙伴。"},sec={{t="挚爱生物的陨落",b="在达纳苏斯的Temple of the Moon宁静的殿堂中，女祭司艾茉拉为萨丝拉女士的悲惨命运感到哀痛。过去，萨丝拉曾被视为艾露恩的眷属。她在夜空下编织出精致的银色蛛网，捕捉泰达希尔枝叶间凝聚的夜雾。她的蛛网所收集的闪烁露水具有神奇的治疗功效，The Sisterhood of Elune会精心收集并保存这些露水，用于她们神圣的祭祀活动。"},{t="对萨丝拉的慈悲",b="正如年轻的世界之树上的许多野生生物一样，萨丝拉女士最近也沦为了某种压倒性疯狂的牺牲品。她的腐化不仅威胁到了路人，也威胁到了她位于涌泉湖附近北部区域尚未孵化的后代。由于她此刻狂暴且躁动不安，已无法将其净化，The Sisterhood of Elune认定终结她的苦难是唯一剩下的慈悲之举。通过取回她的银色丝囊，女祭司们打算将她的遗骸奉献在艾露恩的祭坛上，祈祷月亮女神能赐予她安宁，使她获得纯净的重生。"}},faq={{q="萨丝拉女士是谁？",a="萨丝拉女士是一只泰达希尔本土的雄伟古老蜘蛛。传统上，她被尊为艾露恩的眷属，以编织能捕捉蕴含自然治疗力量的夜雾的银色蛛网而闻名。",al={"萨丝拉女士背景故事","萨丝拉女士是谁","萨丝拉背景","萨丝拉蜘蛛"}},{q="为什么必须杀死萨丝拉女士？",a="她屈服于一种已经感染了泰达希尔野生生物的蔓延疯狂。因为她变得极具攻击性，且对她的后代和其他生物构成了威胁，女祭司们决定将其击杀是一种慈悲的行为。",al={"为什么杀死萨丝拉","萨丝拉可以被拯救吗","为什么萨丝拉会攻击人"}},{q="萨丝拉女士在哪里？",a="萨丝拉女士在泰达希尔的北部荒野，涌泉湖的岸边筑巢。",al={"萨丝拉女士位置","萨丝拉在哪里","寻找萨丝拉"}},{q="萨丝拉女士的蛛网有什么用途？",a="她的蛛网捕捉夜雾，形成了被称为具有深厚治疗力量的强效银色露水，The Sisterhood of Elune将这些露水保存在Temple of the Moon中。",al={"月之泪含义","萨丝拉蛛网用途","银色露水背景"}},{q="谁给予了“月之泪”这个任务？",a="达纳苏斯Temple of the Moon内的一位侍从，女祭司艾茉拉，将此任务给予了值得信赖的联盟冒险者。",al={"谁发布月之泪任务","月之泪任务发布者","女祭司艾茉拉"}},{q="女祭司们将如何处理萨丝拉的丝囊？",a="它们会被作为一种祝圣祭品奉献给神殿祭坛上的艾露恩，祈求女神接纳萨丝拉的灵魂，祝福她，并让她在宁静祥和中重生。",al={"丝囊怎么处理","丝囊用途","献祭给艾露恩"}}},fp="17,220,25.355.0,17.507.1,20.161.0,40.175.0,28.81.0,39.144.0,38.115.0,55.174.0"}
P.entries["quest:2519"] = {n="月神殿",s="Temple of the Moon 是达纳苏斯的一个入门任务，艾奎恩妮会在任务中指引冒险者寻找女祭司艾茉拉。The Sisterhood of Elune 需要有人协助泰达希尔枝叶中遭受痛苦的古老生物。这是通往庄严慈悲仪式的开端。",h="Temple of the Moon 是达纳苏斯的一个入门任务，艾奎恩妮会在任务中指引冒险者寻找女祭司艾茉拉。The Sisterhood of Elune...",kw={"达纳苏斯","艾露恩","女祭司艾茉拉","sathrah","艾奎恩妮","the sisterhood of elune","神殿花园","temple of the moon"},ang={["class:Druid"]="德鲁伊非常关心任何处于困境中的大型野生生物，这使得来自神殿花园的呼唤成为了事关自然和谐的紧急事项。",["class:Priest"]="在达纳苏斯行走的祭司们会被姐妹会的工作自然而然地吸引，协助神职同僚进行治疗和慈悲的仪式。",["race:NightElf"]="对于暗夜精灵来说，响应艾奎恩妮的号召是他们保护泰达希尔神圣生态系统、维护艾露恩祭司教导这一职责的延伸。"},sec={{t="花园的恳求",b="当旅行者漫步在神殿花园的水域和林荫间时，会遇到艾奎恩妮，一位艾露恩的虔诚仆人。她感受到冒险者是有能力的人，便代表她的组织寻求帮助。一只古老的森林生物正在受苦，而姐妹会无法独自处理此事。"},{t="进入 Temple of the Moon",b="艾奎恩妮指引候选者前往东南方宏伟的 Temple of the Moon。在那里，女祭司艾茉拉负责协调仪式和实际工作，以处理泰达希尔受困的野生生物，并让富有同情心的盟友准备好执行一项令人悲伤的慈悲任务。"}},faq={{q="谁发布了 Temple of the Moon 任务？",a="艾奎恩妮发布该任务。她站在达纳苏斯神殿花园区域外。",al={"temple of the moon 任务发布者","在哪里接取 temple of the moon 任务","谁发布 temple of the moon"}},{q="女祭司艾茉拉在哪里？",a="女祭司艾茉拉位于宏伟的 Temple of the Moon 内，就在达纳苏斯神殿花园的东南方。",al={"女祭司艾茉拉在哪里","寻找艾茉拉","女祭司艾茉拉位置"}},{q="需要帮助的生物是什么？",a="该生物是 Sathrah，一只泰达希尔受人尊敬的蜘蛛，她的困境引发了一场由祭司主持的慈悲仪式。",al={"什么生物需要帮助","森林生物是谁","任务链的内容是什么"}},{q="这个任务是继续任务链所必需的吗？",a="不是。Temple of the Moon 只是一个可选的指引任务。你可以直接与神殿内的女祭司艾茉拉交谈，无需先拜访艾奎恩妮即可进行仪式任务。",al={"temple of the moon 是必须的吗","我可以跳过 temple of the moon 吗","temple of the moon 指引任务"}},{q="这个任务之后接什么任务？",a="女祭司艾茉拉会提供 Tears of the Moon 任务，指引你结束 Lady Sathrah 的痛苦并带回她的银色丝囊。",al={"temple of the moon 之后的任务","temple of the moon 后续任务","what comes next"}},{q="为什么 The Sisterhood of Elune 要向外人寻求帮助？",a="泰达希尔动植物体内挥之不去的腐蚀让姐妹会人手紧缺，迫使女祭司们招募那些尊重自然和女神的有能力的旅行者。",al={"为什么寻求外人帮助","为什么祭司需要帮助","艾奎恩妮的动机"}}},fp="22,183,21.193.0,20.230.0,44.99.0,35.102.0,37.122.0,46.184.0,34.127.0,57.158.0"}
P.entries["quest:252"] = {n="翻译好的信件",s="“翻译好的信件”是暮色森林中亚伯克隆比任务线的关键任务。在请求希拉·沃宁迪破译了这位隐居者晦涩难懂的文字后，The Adventurer被指派将翻译好的信件直接交给夜色镇的艾尔罗·埃伯洛克公爵。",h="“翻译好的信件”是暮色森林中亚伯克隆比任务线的关键任务。在请求希拉·沃宁迪破译了这位隐居者晦涩难懂的文字后，The Adventurer被指派将翻译好的信件直接交给夜色镇的艾尔罗·埃伯洛克公爵。",kw={"亚伯克隆比","夜色镇","艾尔罗·埃伯洛克公爵","乌鸦岭","希拉·沃宁迪","翻译好的信件"},ang={["faction:Alliance"]="对于联盟的勇士来说，这一时刻是暮色森林背叛行径所带来的痛苦教训：在森林中错信他人，可能会让整个定居点的无辜居民陷入险境。"},sec={{t="迟来的觉悟",b="几天来，年迈的隐居者亚伯克隆比以自己身体虚弱、需要生存为借口，让过往的旅人在整个暮色森林奔波办事。他索要线绳、防腐试剂和个人物品。直到希拉·沃宁迪最终破译了他私藏的羊皮纸，真相才大白：这位好心的老人其实是一个精神失常的防腐师，而收集来的材料都被用来制造一种旨在直接对付夜色镇的恐怖复仇武器。"},{t="通往夜色镇的道路",b="将翻译好的信件交给艾尔罗·埃伯洛克公爵，让这位镇长的脸色瞬间变得惨白。无论The Adventurer最初出于什么高尚的动机提供帮助，交付这些最后的补给品都让亚伯克隆比完成了他那可怕的造物——缝合怪。将这封信交出后，这个庞然大物便沿着乌鸦岭墓地出发，一路向东行进，屠杀了路上所有阻挡它的夜色镇守夜人巡逻队。"}},faq={{q="翻译好的信件里写了什么？",a="希拉担心亚伯克隆比做了什么不可言说的事情。翻译好的信件必须紧急送交艾尔罗·埃伯洛克公爵，由他来评估对夜色镇构成的威胁。",al={"信里写了什么","亚伯克隆比的信件内容","翻译了什么"}},{q="希拉·沃宁迪是谁？",a="希拉·沃宁迪是一位居住在夜色镇的学者。他精通语言学和分析，当别人无法解读亚伯克隆比的笔迹时，他的专业能力可以破译其留下的晦涩笔记和信件。",al={"希拉是谁","希拉·沃宁迪背景故事"}},{q="为什么艾尔罗公爵要责怪玩家？",a="艾尔罗公爵在阅读了翻译好的信件后，其反应便显而易见了。这项调查要求你尽快将警报带给他。",al={"为什么艾尔罗很生气","是我导致了缝合怪出现吗","艾尔罗的反应"}},{q="完成此任务后会立即发生什么？",a="将翻译好的信件交给夜色镇的艾尔罗·埃伯洛克公爵。当他阅读信件时，他的反应以及信中所警告的危险将会显露出来。",al={"什么触发了缝合怪","缝合怪会刷新吗","缝合怪事件"}},{q="缝合怪之后去了哪里？",a="缝合怪与乌鸦岭墓地和夜色镇之间的道路有关。它在亚伯克隆比阴谋中的角色将通过调查揭晓。",al={"缝合怪的行进路线","缝合怪要去哪里"}},{q="下一个任务是什么？",a="在交付信件后，艾尔罗公爵会派遣探险者们继续执行“防腐师的新娘”这一任务。",al={"下一个任务","翻译好的信件之后"}}},fx={["203575b3"]={q="为什么希拉·沃宁迪要把信送给艾尔罗？",a="解读信件后，希拉意识到亚伯克隆比犯下了不可饶恕的罪行，释放出一场可怕的灾祸，而灾祸正蹒跚着逼近夜色镇。他派你立刻警告艾尔罗·埃伯洛克公爵，好让镇上的领袖在灾难袭击城门前做好准备。",al={"为什么要把信送给艾尔罗","希拉·沃宁迪的动机","为什么要送翻译后的信"}},["4e225af8"]={q="为什么希拉派你去警告艾尔罗公爵，而不是亲自前往？",a="最初奉艾尔罗公爵之命解读亚伯克隆比可疑文字的人是你，后来也是你把那封奇怪的信带给了希拉。怪物已经出动，每一秒都至关重要；把警告交给眼前这位能干的冒险者，是最快让镇长收到消息的办法。",al={"为什么让我去找艾尔罗","希拉为什么不自己去找艾尔罗","为什么派玩家去找艾尔罗"}}},fp="19,177,21.388.1,21.368.1,41.154.0,22.179.0,36.109.0,53.137.1,34.137.2,22.90.1"}
P.entries["quest:2520"] = {n="萨丝拉的祭品",s="“萨丝拉的祭品”是达纳苏斯月神殿内举行的一场肃穆仪式的终结。玩家受托带着萨丝拉女士的遗骸，将这只已故生物的丝囊献入艾露恩的神圣之水中，以洗净她灵魂所受的腐化，并让她安息。",h="“萨丝拉的祭品”是达纳苏斯月神殿内举行的一场肃穆仪式的终结。玩家受托带着萨丝拉女士的遗骸，将这只已故生物的丝囊献入艾露恩的神圣之水中，以洗净她灵魂所受的腐化，并让她安息。",kw={"女祭司艾茉拉","达纳苏斯","艾露恩","喷泉","萨丝拉女士","净化","萨丝拉","丝囊","泰达希尔","temple of the moon"},ang={["class:Druid"]="哀悼泰达希尔瘟疫的德鲁伊们在得知堕落的野兽可以通过净化回归自然循环时，感到了一丝慰藉。",["class:Priest"]="走在月神殿的祭司们亲眼目睹了艾露恩的神圣之光和圣水如何治愈那些因疯狂和腐化而破碎的灵魂。",["race:NightElf"]="对于暗夜精灵来说，这种仪式反映了他们对卡利姆多动植物群所负有的庄严职责：即便生物必须被击杀，它们的灵魂也能通过艾露恩的恩典得到尊崇与净化。"},sec={{t="神圣之水中的净化",b="在萨丝拉女士被悲剧性地击杀后，女祭司艾茉拉交给初学者们一项最终的精神使命。这只巨型蜘蛛沦为了蔓延在泰达希尔的黑暗疯狂的牺牲品，这种疯狂扭曲了她曾经温顺的天性，使她陷入了盲目的攻击性。与其将她的死亡视为简单的捕杀，艾露恩的祭司们寻求救赎她堕落的本质。通过将她的银色丝囊放入月神殿中央的喷泉中，圣水洗去了玷污她的腐化，使她得到了解脱。"},{t="萨丝拉的重生",b="将祭品献给艾露恩会带来即时的精神共鸣。当丝囊触碰到月光下的水池时，萨丝拉女士虚灵的形态从深处升起，平静且洗净了那折磨她陷入疯狂的病痛。The Sisterhood of Elune视此仪式为必要的救赎；尽管痛失这只巨型生物令人悲伤，但暗夜精灵的神学教导说，通过这种神圣的净化，她终有一天能带着纯洁的灵魂重生。"}},faq={{q="萨丝拉女士是谁？",a="萨丝拉女士是一只居住在泰达希尔的巨型蜘蛛，她屈服于折磨世界之树野生动物的蔓延腐化。她因受腐化而陷入疯狂，必须被击杀以使她的遗骸能够得到净化。",al={"萨丝拉女士","萨丝拉是谁","萨丝拉是什么"}},{q="祭品是在哪里献出的？",a="祭品被放入位于月神殿中央的神圣喷泉中，该神殿是达纳苏斯The Sisterhood of Elune的中心圣殿。",al={"我该把祭品放在哪里","喷泉位置","神殿喷泉"}},{q="当你把丝囊放入喷泉时会发生什么？",a="在将银色丝囊放入祝福之水中后，萨丝拉那净化的灵魂会短暂地显现在水池中，自由且平静地漫步，象征着艾露恩的接纳。",al={"喷泉处发生了什么","萨丝拉之魂喷泉"}},{q="为什么萨丝拉女士必须死？",a="毒害她心智的腐化太过深重，以至于她在活着的时候无法治愈。女祭司艾茉拉和The Sisterhood of Elune认为，拯救她灵魂的唯一方法就是结束她的痛苦，并在艾露恩的神圣之水中洗净她的遗骸。",al={"为什么要杀死萨丝拉","萨丝拉能被拯救吗","萨丝拉的疯狂"}},{q="是谁发布了“萨丝拉的祭品”任务？",a="该任务由在达纳苏斯月神殿内、俯瞰中央大厅的女祭司艾茉拉发布并终结。",al={"任务发布者","在哪里交任务","艾茉拉的位置"}},{q="暗夜精灵的这种仪式背后蕴含着什么信仰？",a="暗夜精灵相信，经由月之母净化的灵魂可以重生于自然世界，他们的精神得到洗涤与更新，不再带有残留的腐化污点。",al={"暗夜精灵转世","艾露恩的净化","重生传说"}}},fp="19,217,28.471.0,22.346.1,21.217.0,31.143.0,59.177.1,33.225.0,40.132.0,54.137.0"}
P.entries["quest:253"] = {n="藏尸者的妻子",s="“藏尸者的新娘”是一项由夜色镇的艾尔罗·埃伯洛克公爵发布的危险任务。在拼凑出关于传说中藏尸者背后令人不安的真相后，镇领导层派你前往暮色森林那些闹鬼的墓地，找到他复活的妻子的安息之处。通过从伊莉莎被诅咒的遗骸中挖出这位炼金术士鲜活的心脏，你的目标是剥夺他那邪恶的力量。",h="“藏尸者的新娘”是一项由夜色镇的艾尔罗·埃伯洛克公爵发布的危险任务。在拼凑出关于传说中藏尸者背后令人不安的真相后，镇领导层派你前往暮色森林那些闹鬼的墓地，找到他复活的妻子的安息之处。通过从伊莉莎被诅咒的遗骸中挖出这位炼金...",kw={"炼金术士","藏尸者的新娘","夜色镇","暮色森林","伊莉莎","艾尔罗·埃伯洛克","藏尸者的心脏","坟墓","藏尸者"},ang={["class:Paladin"]="圣骑士视伊莉莎那邪恶的复活为对圣光和自然法则的亵渎，他们乐于净化这个吃人的怪物，切断通灵师那亵渎的生命线。",["class:Priest"]="牧师们能够理解这位因丧妻而坠入黑暗的鳏夫背后的悲剧，但也知道伊莉莎这种对生命进行亵渎和嘲弄的嗜血怪物必须被神圣的终结所安息。",["faction:Alliance"]="随着守夜人因对抗暮色森林的野兽威胁而兵力吃紧，一位联盟勇士必须挺身而出，保卫夜色镇免受这种古老而蔓延的疯狂侵害。"},sec={{t="活生生的睡前故事",b="多年来，暮色森林的父母们总是向受惊的孩子讲述藏尸者的故事。根据民间传说，他曾是一位仁慈的炼金术士，但在爱妻伊莉莎不幸离世后，他的精神崩溃了。为了逃避死亡，他不惜动用邪恶的法术，付出了终极代价：挖出了自己跳动的心脏，放进了妻子的胸膛。艾尔罗·埃伯洛克公爵长期以来都认为这不过是村野传闻，但最近的发现证明，藏尸者确实生活在他们中间，他那邪恶的杰作正在墓地泥土下腐烂滋生。"},{t="复活的新娘",b="仪式成功让伊莉莎恢复了生机，但黑暗通灵术总是索要可怕的代价。被偷来的生命火花复活后，伊莉莎变成了一个贪婪的憎恶，被诅咒永远渴望着活人的血肉。由于感到恐惧且不愿摧毁自己的杰作，藏尸者被迫将他的新娘藏在一座孤坟之中，秘密地探望她，同时密谋着更多堕落的行径。为了解除这位通灵师的武装，埃伯洛克公爵指挥勇敢的灵魂去掘开伊莉莎的坟墓，击败这个嗜血的怪物，并取回那颗维持他黑暗技艺的、仍在跳动的心脏。"},{t="夜色镇的庇护",b="当你从伊莉莎腐烂的胸腔中挖出那颗跳动的心脏并带回夜色镇时，埃伯洛克公爵长舒了一口气。镇长并没有简单地销毁它，而是打算用这位炼金术士的邪恶造物来对付他自己。他相信心脏中残留的诡异魔法将作为守护夜色镇的护身符和屏障，保护这个饱受折磨的小镇免受虚弱的藏尸者可能发动的任何复仇之怒。"}},faq={{q="谁是藏尸者？",a="藏尸者原本是暮色森林的一名炼金术士，在妻子伊莉莎去世后陷入了疯狂。他转向通灵术，挖出了自己鲜活的心脏并放入伊莉莎的尸体中以复活她，从而将自己变成了一个难以捉摸的怪物。",al={"藏尸者背景","谁是藏尸者","藏尸者起源"}},{q="既然伊莉莎复活了，为什么还要把她埋起来？",a="虽然这位炼金术士成功用自己的心脏复活了伊莉莎，但黑魔法诅咒了她，让她对活人血肉产生了永不满足的渴望。由于无法让她安全地生活在社会中，也无法平息她那野兽般的食欲，他被迫将她一直埋在墓地里。",al={"为什么伊莉莎被埋","伊莉莎的坟墓","为什么把伊莉莎关在坟墓里"}},{q="为什么埃伯洛克公爵想要藏尸者的心脏？",a="根据艾尔罗讲述的故事，心脏是藏尸者力量的源泉。他让你在心脏还在跳动时从伊莉莎的坟墓中取回它，相信这会瓦解那种力量。",al={"为什么要去拿心脏","藏尸者的心脏的作用"}},{q="这个任务链从哪里开始？",a="该任务紧随“致艾尔罗的译文”之后，在任务中，旧信件和研究报告被递交给艾尔罗·埃伯洛克公爵，证明了当地儿歌中提到的藏尸者是一个真实存在且危险的威胁。",al={"任务前置条件","如何接到藏尸者的新娘","藏尸者前置任务"}},{q="取回心脏能彻底击败藏尸者吗？",a="艾尔罗相信取回心脏将瓦解藏尸者的力量。任务的结果将在你回到夜色镇时揭晓。",al={"藏尸者死了吗","这能杀死藏尸者吗"}},{q="谁发布了这个任务？",a="艾尔罗·埃伯洛克公爵，夜色镇的镇长和领袖，在得知该镇民间传说背后的惊人真相后，在Darkshire Town Hall发布了该任务。",al={"任务发布者","谁开启藏尸者的新娘任务"}}},fp="21,202,26.438.0,21.471.1,17.386.2,20.206.0,53.202.0,50.175.0,34.190.0,58.120.1,21.152.0"}
P.entries["quest:254"] = {n="掘墓",s="“掘地三尺”标志着在暮色森林寻找藏尸者丢失的心脏这一任务的严酷高潮。在乌鸦岭墓地那令人毛骨悚然的寂静深处，一堆被翻动的泥土掩盖着一个拒绝安息的恐怖存在。",h="“掘地三尺”标志着在暮色森林寻找藏尸者丢失的心脏这一任务的严酷高潮。在乌鸦岭墓地那令人毛骨悚然的寂静深处，一堆被翻动的泥土掩盖着一个拒绝安息的恐怖存在。",kw={"亚伯克隆比","藏尸者的新娘","棺材","掘地三尺","暮色森林","伊莱莎","伊莱莎的坟墓泥土","藏尸者的心脏","乌鸦岭墓地"},ang={["class:Paladin"]="打扰新坟违背了圣光的每一条丧葬礼仪，但释放并消灭困在其中的邪恶怪物是一项必要的净化行为。",["class:Priest"]="圣土之下传来的利爪抓挠声和磨牙声，是对圣光许诺给暮色森林逝者的宁静安息的公然冒犯。",["faction:Alliance"]="守夜人一直在与从乌鸦岭溢出的恐怖势力抗争；根除藏尸者隐藏的那些地下恐怖存在，对夜色镇的安全至关重要。"},sec={{t="被打扰的坟墓",b="在乌鸦岭墓地那数不清的风化墓碑之间，有一块近期被翻动过、土壤尚显松散的坟墓，上面刻着“伊莱莎”的名字。虽然暮色森林中许多坟墓都曾被食腐动物或野性的食尸鬼亵渎，但这堆土却是被刻意堆放的。挖开表层土壤后，会露出一个埋在底下的棺材的破损木板，里面封印着藏尸者试图隐瞒于天光之外的某种残骸。"},{t="棺内的抓挠声",b="破碎的木板下并非安息的尸体。按压棺盖，可以感觉到剧烈的震动——那是长着利爪的手指疯狂抓挠的声音，还有腐烂的下颌骨发出的空洞咔哒声。亚伯克隆比那个病态实验的产物，伊莱莎，正在她的松木囚牢中剧烈挣扎，藏尸者的心脏在她的胸腔内跳动，等待着粗心的双手撬开这道坟墓。"}},faq={{q="伊莱莎的坟墓里埋着什么？",a="泥土下埋着一具棺材，里面装的是伊莱莎，一个由藏尸者创造的亡灵怪物。她被封印在地下，而藏尸者自己的心脏就放在她的胸腔内。",al={"坟墓里有什么","伊莱莎是谁","伊莱莎坟墓的内容"}},{q="这座坟墓在哪里？",a="伊莱莎的坟墓位于暮色森林西部的乌鸦岭墓地，周围是一片被诅咒的墓穴和游荡的亡灵。",al={"伊莱莎的坟墓在哪里","伊莱莎坟墓位置","坟墓泥土位置"}},{q="为什么要挖开棺材？",a="你必须挖开坟墓来面对伊莱莎并取回藏尸者的心脏，从而终结围绕着藏尸者扭曲阴谋的调查。",al={"为什么要挖坟墓","挖掘的目的","为什么要打开棺材"}},{q="打开棺材后会发生什么？",a="打开棺材会将伊莱莎从她浅浅的囚牢中释放出来，你必须消灭这个贪婪的抓挠着的食尸鬼，才能取回被锁在里面的心脏。",al={"接下来会发生什么","棺材已打开","打开伊莱莎的棺材"}},{q="是谁把伊莱莎埋在那里的？",a="是藏尸者把她放在那里的，他将自己这具可怕的造物连同他珍视的心脏一起，隐藏在了广阔的乌鸦岭墓地中。",al={"谁埋葬了伊莱莎","谁把她放在那里"}},{q="伊莱莎是普通的食尸鬼吗？",a="伊莱莎是藏尸者已故的妻子，被他的黑暗魔法复活，胸腔内还装着他的心脏，她远比那些在暮色森林道路上漫无目的游荡的食尸鬼更加强壮，也更有目的性。",al={"伊莱莎是什么怪物","伊莱莎是食尸鬼吗"}}},fp="24,149,17.335.0,21.319.1,32.118.1,28.105.0,39.112.1,39.124.1,28.104.1,27.175.1"}
P.entries["quest:2541"] = {n="沉睡的德鲁伊",s="在班奈希尔兽穴的深处，沉睡的暗夜精灵奥本·怒爪正面临着可怕的魔法困境。敌对的枯木熊怪萨满祭司将他的梦境灵魂从肉体中剥离，并利用邪恶的咒法驱使他的躯体成为一个狂暴的守护者。",h="在班奈希尔兽穴的深处，沉睡的暗夜精灵奥本·怒爪正面临着可怕的魔法困境。敌对的枯木熊怪萨满祭司将他的梦境灵魂从肉体中剥离，并利用邪恶的咒法驱使他的躯体成为一个狂暴的守护者。",kw={"班奈希尔兽穴","兽穴","翡翠梦境","枯木部族","奥本·怒爪","萨满巫毒符咒","泰达希尔","沉睡的德鲁伊"},ang={["class:Druid"]="对于德鲁伊来说，奥本的处境无异于一场清醒的噩梦：在翡翠梦境中冥想时身体被劫持，这违背了德鲁伊沉睡的根本原则。",["race:NightElf"]="班奈希尔兽穴遭受的亵渎证明了枯木熊怪与卡多雷的古老血缘关系已经沦丧到了何种地步。"},sec={{t="被打断的沉睡",b="暗夜精灵德鲁伊会进入卡利姆多各地的兽穴，通过数百年的沉睡与自然交流，在翡翠梦境中漫游，而他们的凡身则安稳地在石龛中休憩。然而，泰达希尔遭受的腐蚀使当地的枯木部族熊怪陷入了绝望的野蛮行径。在班奈希尔兽穴，枯木萨满祭司找到了一种突破奥本·怒爪圣洁沉睡的方法，强行将他的灵魂从沉睡的躯壳中驱离。"},{t="巫毒与腐蚀",b="枯木萨满祭司并没有杀死奥本，而是使用了一种邪恶的护身符——萨满巫毒符咒——强行操控他空虚的躯壳。奥本离体的灵魂被困在翡翠梦境中，无助地看着自己的肉身在走廊中游荡，盲目地攻击任何进入兽穴的人。为了破除这道咒法并找到恢复身体的方法，他那以太形态的投影委托冒险者取回一个枯木咒符以供研究。"}},faq={{q="奥本·怒爪是谁？",a="奥本·怒爪是一位暗夜精灵德鲁伊，他进入班奈希尔兽穴进行神圣的沉睡，以便与翡翠梦境沟通。敌对的枯木熊怪劫持了他的肉身，导致他的灵魂离体。",al={"奥本·怒爪","沉睡的德鲁伊是谁","兽穴中沉睡的暗夜精灵"}},{q="奥本的身体为什么会攻击人？",a="枯木萨满祭司举行了一场仪式，将奥本的意识与他的肉体分离开来。他们用黑暗魔法驱使他空虚的肉身，作为守护兽穴深处的强力卫兵。",al={"奥本为何具有敌意","奥本为何发起攻击","奥本·怒爪躯体攻击"}},{q="什么是萨满巫毒符咒？",a="这是一种由班奈希尔兽穴内的枯木萨满祭司携带的附魔媒介。他们利用其黑暗力量将沉睡德鲁伊的灵魂从身体中强行拽出，并操纵他们的肉身。",al={"萨满咒符","泰达希尔巫毒符咒","什么是萨满巫毒符咒"}},{q="任务期间奥本真正的灵魂在哪里？",a="奥本的意识被困在翡翠梦境中游荡，无法回到他的凡身。他只能以闪烁灵魂的形态，在自己安息处附近与清醒的世界交流。",al={"奥本在哪里","奥本灵魂位置","翡翠梦境奥本"}},{q="为什么班奈希尔兽穴里的熊怪具有敌意？",a="枯木部族已经沦为腐蚀泰达希尔野生动物和森林的污染与疯狂的受害者，这导致他们背弃了曾经的暗夜精灵盟友，并亵渎了神圣的德鲁伊圣地。",al={"枯木部族为何疯狂","泰达希尔熊怪腐蚀","熊怪为何具有攻击性"}},{q="奥本的身体能在不被杀死的情况下获救吗？",a="研究萨满巫毒符咒是奥本打破仪式的首要希望。通过审视束缚他肉体的邪恶咒法，他希望能理解这种魔法并找到解决这场危机的方法。",al={"拯救奥本·怒爪","奥本能被拯救吗","治愈奥本"}}},fp="18,185,19.395.0,21.363.1,21.205.0,36.151.0,32.208.0,45.162.0,53.169.0,44.197.0"}
P.entries["quest:255"] = {n="雇佣兵",s="“雇佣兵”是塞尔萨玛的镇长埃罗恩·钝鼻发布的一项悬赏契约，旨在清理洛克莫丹东北部不断入侵的莫格罗什食人魔。由于来自铁炉堡的军事增援深陷数月的官僚主义泥潭，镇长被迫雇佣路过的冒险者来保护山谷中脆弱的定居点、挖掘场以及至关重要的巨石水坝。",h="“雇佣兵”是塞尔萨玛的镇长埃罗恩·钝鼻发布的一项悬赏契约，旨在清理洛克莫丹东北部不断入侵的莫格罗什食人魔。由于来自铁炉堡的军事增援深陷数月的官僚主义泥潭，镇长被迫雇佣路过的冒险者来保护山谷中脆弱的定居点、挖掘场以及至关重...",kw={"洛克莫丹","镇长埃罗恩·钝鼻","雇佣兵","莫格罗什","食人魔","巨石水坝","塞尔萨玛"},ang={["faction:Alliance"]="洛克莫丹是卡兹莫丹与北方王国之间至关重要的走廊；任由其在食人魔的劫掠中陷入混乱，将威胁到联盟在整个东部王国的补给线。",["race:Dwarf"]="看到矮人工程学的皇冠明珠——巨石水坝——因为铁炉堡的官僚主义而无人守卫，这使得埃罗恩·钝鼻的征兵号召对于任何来自首都的山地巡逻队员或旅行者来说，都成了一件私事。"},sec={{t="铁炉堡迟缓的运作",b="塞尔萨玛正深受矮人官僚主义之苦。铁炉堡足足花了两个月才承诺派遣一小队士兵来加强洛克莫丹的本地防御，而这些部队预计还要再过两个月才能抵达。由于城镇卫兵已捉襟见肘，镇长埃罗恩·钝鼻无法在敌对势力于山谷边界外集结时干等四个月。"},{t="山中的威胁",b="莫格罗什食人魔在洛克湖东北部的山丘中加固了一个营地。它们日益增长的势力不仅威胁着塞尔萨玛镇，还威胁着Ironband挖掘场以及巨石水坝本身。如果水坝遭到攻击或破坏，下游的灾难将是毁灭性的。由于缺乏正式的山地巡逻队，埃罗恩·钝鼻只能转向自由雇佣兵，以削减食人魔的数量，并为山谷争取时间来对抗食人魔和石腭怪。"}},faq={{q="镇长埃罗恩·钝鼻为什么要雇佣雇佣兵而不是使用卫兵？",a="对于洛克莫丹的求援，铁炉堡的反应慢得令人痛苦。议会花了两个月才批准派遣哪怕一小队士兵，而这些士兵真正抵达还需要再等两个月。面对塞尔萨玛、水坝以及当地挖掘场迫在眉睫的威胁，埃罗恩·钝鼻别无选择，只能花钱雇佣独立的冒险者。",al={"为什么要雇佣雇佣兵","塞尔萨玛卫兵","铁炉堡援助"}},{q="莫格罗什食人魔位于何处？",a="莫格罗什食人魔居住在莫格罗什要塞，该要塞位于洛克莫丹大湖东北部崎岖的断崖和山丘之中。",al={"食人魔位置","莫格罗什在哪里","莫格罗什营地"}},{q="为什么巨石水坝被认为处于危险之中？",a="巨石水坝调节着整个湖泊的水位，是矮人建筑的瑰宝。由于几乎没有军事防御，且莫格罗什食人魔在附近建立了营地，埃罗恩·钝鼻担心有组织的突袭可能会损坏或破坏这座巨大的建筑，从而引发灾难性的洪水。",al={"为什么要保护水坝","食人魔与水坝"}},{q="除了食人魔，塞尔萨玛还面临哪些其他威胁？",a="石腭怪从地下的废墟和挖掘场中涌出，遍布洛克湖各地。埃罗恩·钝鼻认为它们是一个巨大的威胁，但附近食人魔要塞的蛮力迫使他雇佣战士来击退莫格罗什食人魔，这样当地卫兵才能集中精力对付石腭怪的入侵。",al={"洛克莫丹的其他威胁","石腭怪威胁"}}},fp="11,262,23.274.0,23.420.0,71.330.0,37.118.0,49.268.0,59.258.0"}
P.entries["quest:256"] = {n="通缉令：卓克苏尔",s="塞尔萨玛的镇长埃罗恩·钝鼻发布了一项悬赏，要求诛杀卓克苏尔。这名食人魔督军正在威胁着洛克莫丹的东北部。据信他正在组织对当地定居点和关键基础设施的袭击，带回他的头颅，就能从镇上的领导层那里获得丰厚的奖励。",h="塞尔萨玛的镇长埃罗恩·钝鼻发布了一项悬赏，要求诛杀卓克苏尔。这名食人魔督军正在威胁着洛克莫丹的东北部。据信他正在组织对当地定居点和关键基础设施的袭击，带回他的头颅，就能从镇上的领导层那里获得丰厚的奖励。",kw={"镇长埃罗恩·钝鼻","悬赏","卓克苏尔","洛克莫丹","食人魔","巨石水坝","塞尔萨玛"},ang={["faction:Alliance"]="洛克莫丹是通往丹莫罗的主要农业和补给走廊，因此维持塞尔萨玛周边的稳定对于联盟的军事行动至关重要。",["profession:Engineering"]="巨石水坝是矮人土木工程史上最伟大的成就之一；对于任何有声望的工匠来说，容忍粗鲁的食人魔破坏它都是不可想象的。",["race:Dwarf"]="保卫巨石水坝和周边的考古挖掘场，直接关系到矮人的骄傲、遗产以及铁炉堡主权领地的安全。"},sec={{t="洛克湖的威胁",b="虽然石腭怪和野生动物不断侵扰洛克莫丹的边界，但有组织的食人魔的出现标志着事态升级，当地的矮人山地猎人们已无法坐视不管。这些野蛮人已经在山谷崎岖的东北部安营扎寨，他们的行径已不再仅仅是简单的搜寻物资。据当地侦察兵和镇当局称，他们的突袭目标明确，行动持续不断，且极具危险性。"},{t="卓克苏尔的项上人头",b="塞尔萨玛的镇长埃罗恩·钝鼻认定卓克苏尔是策划针对该镇、附近的矮人挖掘场以及巨石水坝本身所发生暴力事件的幕后黑手。由于担心会对山谷引以为傲的工程杰作造成灾难性的破坏并危及平民生命，镇长对这名食人魔首领发出了悬赏：不惜一切代价将其击毙，并必须带回他的断头作为凭证。"}},faq={{q="是谁悬赏缉拿卓克苏尔？",a="塞尔萨玛的最高行政官员镇长埃罗恩·钝鼻，代表该镇正式发布了这项命令，以保护该地区免受有组织的袭击。",al={"谁想要卓克苏尔死","谁发布了卓克苏尔的悬赏","塞尔萨玛通缉令"}},{q="为什么卓克苏尔被视为高度优先的目标？",a="卓克苏尔被认为是策划针对塞尔萨玛、铁炉堡考古挖掘场以及巨石水坝的食人魔突袭的协调者——这些目标不仅关乎矮人的生命，也是王国关键的基础设施。",al={"为什么要杀卓克苏尔","卓克苏尔干了什么","卓克苏尔的威胁"}},{q="在哪里可以找到卓克苏尔？",a="他在位于洛克莫丹东北角崎岖丘陵中的食人魔营地里。",al={"卓克苏尔的位置","卓克苏尔在哪里","洛克莫丹的食人魔营地"}},{q="镇长埃罗恩·钝鼻需要什么证明？",a="你必须将卓克苏尔的断头直接带到塞尔萨玛交给镇长埃罗恩·钝鼻，以领取赏金并获得铁炉堡的感激。",al={"卓克苏尔的头颅","悬赏凭证","交付卓克苏尔的任务"}},{q="为什么食人魔要攻击巨石水坝？",a="巨石水坝拦截了巨大的洛克湖，是矮人工程学的一项巅峰杰作。破坏它会淹没湿地并摧毁矮人的补给线，这使它成为敌对势力首要的战术打击目标。",al={"为什么要攻击水坝","巨石水坝遭到袭击"}},{q="有其他食人魔与卓克苏尔共事吗？",a="是的，卓克苏尔指挥着一个在洛克湖东北部丘陵建立起来的食人魔营地，并指挥他们在周围地区发动突袭。",al={"卓克苏尔部族","洛克莫丹的食人魔","卓克苏尔的追随者"}}},fp="16,180,20.280.0,28.306.0,34.138.0,55.180.0,28.103.0,45.143.0,44.216.0,44.123.0"}
P.entries["quest:2561"] = {n="利爪德鲁伊",s="在泰达希尔的巢穴深处，奥本·怒爪的灵魂形态请求你给他一个悲剧性的解脱。受到腐蚀的熊怪对他沉睡的躯体施加了黑暗的咒语，强迫你必须摧毁他那失去灵魂的躯壳，并打破束缚，让他的灵魂能够重返翡翠梦境。",h="在泰达希尔的巢穴深处，奥本·怒爪的灵魂形态请求你给他一个悲剧性的解脱。受到腐蚀的熊怪对他沉睡的躯体施加了黑暗的咒语，强迫你必须摧毁他那失去灵魂的躯壳，并打破束缚，让他的灵魂能够重返翡翠梦境。",kw={"ban'ethil","利爪德鲁伊","翡翠梦境","木喉熊怪","奥本·怒爪","泰达希尔","沉睡的德鲁伊","巫毒咒符"},ang={["class:Druid"]="看到一名沉睡的利爪德鲁伊被腐蚀的熊怪亵渎，让人不寒而栗，这提醒了人们在与翡翠梦境沟通时，将肉体留在无人看管的地方有多么危险。",["race:NightElf"]="泰达希尔本应是暗夜精灵的避难所，但像木喉熊怪这样的本地物种迅速堕落，即使在他们神圣的巢穴中也构成了直接的威胁。"},sec={{t="被切断的灵魂",b="当奥本·怒爪在泰达希尔下方的巢穴中安睡时，他遭遇了可怕的命运。受到腐蚀的木喉熊怪对他沉睡的身体施加了邪恶的巫毒咒语，将他的灵魂从凡人的肉体中切断。奥本的灵魂被困在翡翠梦境附近，无法安息，也无法夺回自己的身体。"},{t="肉体的慈悲",b="检查木喉熊怪的巫毒咒符揭示了一个残酷的真相：奥本的肉身完全处于熊怪的控制之下。为了打破这个咒语，冒险者必须进入附近的房间，击倒奥本·怒爪那毫无意识且充满敌意的躯壳，并在他的遗骸上使用熊怪的咒符，彻底粉碎束缚他灵魂的魔法。"}},faq={{q="为什么我必须杀死奥本·怒爪？",a="木喉熊怪在奥本沉睡时对他施加了强大的巫毒咒语，将他的肉身变成了没有灵魂的傀儡。由于他的肉体完全受到它们的奴役，摧毁这具躯壳是切断咒语并释放他徘徊灵魂的唯一方法。",al={"为什么要杀死奥本","杀死沉睡的德鲁伊","奥本·怒爪的身体"}},{q="巫毒咒符是用来做什么的？",a="这枚咒符是控制奥本的咒语的关键。一旦你杀死了他那受到腐蚀、失去灵魂的躯体，在他的尸骸上激活这枚咒符就能解开束缚他灵魂的黑暗魔法。",al={"巫毒咒符的用途","如何使用巫毒咒符","木喉熊怪对奥本的咒符"}},{q="完成这个任务后奥本会去哪里？",a="一旦他的肉身被摧毁，咒语被解除，奥本·怒爪的灵魂就从凡世中解脱了。他终于能够前往翡翠梦境安息了。",al={"奥本的命运","奥本·怒爪会发生什么","奥本能活下来吗"}},{q="为什么木喉熊怪要使用巫毒魔法？",a="木喉熊怪已经堕入腐蚀与疯狂的深渊，它们背弃了祖先的和谐，沉迷于邪恶的巫术和粗糙的黑暗魔法，以此来奴役周围的生物和沉睡的德鲁伊。",al={"熊怪巫毒","木喉熊怪的巫毒魔法","为什么熊怪有咒符"}},{q="奥本·怒爪是谁？",a="奥本是一名暗夜精灵利爪德鲁伊，他在泰达希尔的巢穴中进行神圣的沉睡，与翡翠梦境沟通，直到木喉熊怪打断了他的休息并奴役了他的凡人躯壳。",al={"奥本是谁","奥本的背景故事","奥本·怒爪背景"}},{q="当他的身体还活着的时候，奥本的灵魂还能和我交流吗？",a="是的。黑暗的咒语将奥本的灵魂与肉体切断了。他的灵魂在房间入口附近显现为幽灵，完全无法控制或重新进入里面那个被施了咒的空壳。",al={"奥本的灵魂与身体","两个奥本","为什么奥本在两个地方"}}},fp="17,211,16.299.0,19.214.1,36.212.0,34.159.0,36.153.1,41.195.0,22.193.0,61.168.0"}
P.entries["quest:257"] = {n="自豪的猎人",s="“猎人的夸耀”是由洛克莫丹旅行者营地的年轻的达瑞尔发布的一项限时狩猎挑战。这名傲慢的年轻人类急于炫耀他所谓的精湛技艺，竟敢向冒险者挑衅，要求他们在十五分钟的限时内追踪并击杀六只山地秃鹫。",h="“猎人的夸耀”是由洛克莫丹旅行者营地的年轻的达瑞尔发布的一项限时狩猎挑战。这名傲慢的年轻人类急于炫耀他所谓的精湛技艺，竟敢向冒险者挑衅，要求他们在十五分钟的限时内追踪并击杀六只山地秃鹫。",kw={"猎人的夸耀","大胆的达瑞尔","年轻的达瑞尔","旅行者营地","狩猎挑战","洛克莫丹","山地秃鹫","限时任务"},ang={["class:Hunter"]="对于射手和追踪者来说，达瑞尔的比赛是一个有趣的契机，可以在他的主场胜过这个夸夸其谈的新手，并获得一把可靠的弓或枪。",["faction:Alliance"]="旅行者营地是洛克莫丹东南部道路上一个重要的联盟哨所，为崎岖山谷中的狩猎活动提供庇护和补给。",["race:Dwarf"]="习惯了营地老练猎人的矮人们会看出这个人类年轻人的姿态不过是空洞的虚张声势，最好的回应便是默默展现实力。"},sec={{t="年轻射手的傲慢",b="旅行者营地是卡兹莫丹一些最优秀的追踪者和射手的聚集地，但并非屋檐下的每一个人都拥有老兵的谦逊。年轻的达瑞尔——自诩为“大胆的达瑞尔”——总是喜欢轻视路过的冒险者。他坚信这些初出茅庐的外乡人根本无法与他的狩猎本领相提并论，于是他下了一个鲁莽的赌注：在十五分钟内猎杀六只当地的山地秃鹫，否则就承认失败。"},{t="清理食腐动物",b="山地秃鹫在洛克莫丹的悬崖和山坡上盘旋，它们以残羹剩饭为食，并捕食较小的野生动物。虽然成群结队时十分危险，但它们主要被当作测试猎人速度、耐心和准头的基准目标。那些在严格时限内完成任务的人会迅速挫败达瑞尔那膨胀的自尊心，迫使他极不情愿地交出一件远程武器，也为后续的狩猎挑战奠定了基础。"}},faq={{q="这项狩猎挑战是在哪里进行的？",a="该任务起始于位于洛克莫丹东南部荒野的旅行者营地。你需要狩猎的山地秃鹫在附近区域的岩架和开阔的山脊上游荡。",al={"任务地点","达瑞尔在哪里","秃鹫在哪里"}},{q="年轻的达瑞尔是谁？",a="年轻的达瑞尔是一名雄心勃勃、喜欢吹嘘的年轻人类，目前待在旅行者营地。他自称“大胆的达瑞尔”，喜欢挑衅旅行者进行限时狩猎试验，以证明他那自以为是的优越感。",al={"达瑞尔是谁","大胆的达瑞尔背景故事","达瑞尔与旅行者营地"}},{q="为什么狩猎有时间限制？",a="十五分钟的限制是达瑞尔赌注的一部分。他认为在压力下猎杀野生秃鹫是一项远超普通冒险者能力的壮举。",al={"为什么是15分钟","任务计时器","限时挑战"}},{q="完成达瑞尔的挑战后会发生什么？",a="虽然对你的成功感到震惊，但达瑞尔拒绝承认真正的失败。他信守诺言提供了一件武器，然后立即提出了另一个狩猎任务——“猎人的挑战”，目标是体型更大的猎物。",al={"what comes next","夸耀后续任务","猎人任务链"}},{q="为什么专门狩猎山地秃鹫？",a="成群的山地秃鹫在洛克莫丹的岩石斜坡上筑巢。它们是一种敏捷的飞行目标，非常适合测试弓箭手或火枪手是否具备真正的实战纪律。",al={"为什么要狩猎秃鹫","秃鹫的作用","洛克莫丹的秃鹫"}},{q="这个任务与旅行者营地的其他任务有关联吗？",a="是的。达瑞尔的测试直接引出了营地的一系列更广泛的狩猎任务，最终目标是追踪那头曾在达瑞尔身上留下伤疤的“老烟鬼”，这也是维琳·迅风为了教训这个狂妄的年轻人而制定的计划的一部分。",al={"与维琳的关系","营地故事","旅行者营地剧情"}}},fp="16,134,28.214.0,23.220.0,45.141.0,27.179.0,38.131.0,45.163.1,40.127.0,62.171.1"}
P.entries["quest:258"] = {n="猎人的挑战",s="“猎人的挑战”是由狂妄的人类年轻的达瑞尔在洛克莫丹东南部的旅行者营地所发布的一项限时狩猎试炼。因为无法贬低你之前的成就而感到恼火，年轻的达瑞尔和你打赌，如果你不能在十二分钟内追踪并猎杀五头年长的山猪，他就要输掉他身上的衬衫。这项任务旨在考验冒险者在崎岖地形和高地危险野生动物面前的敏捷身手。",h="“猎人的挑战”是由狂妄的人类年轻的达瑞尔在洛克莫丹东南部的旅行者营地所发布的一项限时狩猎试炼。因为无法贬低你之前的成就而感到恼火，年轻的达瑞尔和你打赌，如果你不能在十二分钟内追踪并猎杀五头年长的山猪，他就要输掉他身上的衬...",kw={"山猪","寒脊山谷","达瑞尔","年长的山猪","旅行者营地","狩猎","洛克莫丹","年轻的"},ang={["class:Hunter"]="对于追踪专家来说，在严格的时间窗口内穿过高地灌木丛追踪五头年长的山猪，是对猎物管理和快速猎杀能力的经典测试。",["faction:Alliance"]="旅行者营地是联盟护林人为保护洛克莫丹东部边界免受野兽和高地威胁侵扰而设立的重要据点。",["race:Dwarf"]="任何从寒脊山谷走出来的矮人都会立刻认出年轻的达瑞尔的比较，尽管容忍他那居高临下的态度更加令人难以接受。"},sec={{t="年轻人的吹嘘",b="年轻的达瑞尔居住在旅行者营地经验丰富的猎人之中，但他却没有半点他们的沉稳与耐心。相反，年轻的达瑞尔用吹牛和夸大的狩猎故事来掩饰自己年龄的不足，其中包括讲述他如何获得“著名”伤疤的冗长故事。他不愿承认任何人的能力，不断搞错其他猎人的名字，并设计出严苛的试炼，意图让新人出丑，从而恢复他在营地居民中那虚高的地位。"},{t="高地狩猎",b="与寒脊山谷中矮人新兵初次学习狩猎技艺时捕猎的简单野猪不同，漫步在洛克莫丹山脊和山坡上的年长的山猪体型庞大、皮糙肉厚，且在被激怒时十分危险。年轻的达瑞尔只给了猎人十二分钟的时间来定位、击杀并确认五头这类野兽。只要能足够迅速地完成狩猎，这个夸夸其谈的年轻人就会尴尬地退缩，装作不记得他曾随口夸下那样离谱的赌约。"}},faq={{q="年轻的达瑞尔是谁？",a="年轻的达瑞尔是一位年轻、爱吹嘘的人类猎人，住在洛克莫丹东南部的旅行者营地。他极度渴望看起来像周围的老兵一样强大，因此不断吹嘘自己的本事，编造宏大的故事，并向路过的冒险者发起高难度的狩猎挑战。",al={"达瑞尔是谁","年轻的达瑞尔背景故事","旅行者营地的达瑞尔"}},{q="年长的山猪在哪里？",a="年长的山猪游荡在旅行者营地周围的山脚、草地和山脊，以及洛克莫丹的南部和东部广阔区域。它们在营地和中部湖泊之间的连绵高地上觅食。",al={"年长的山猪位置","去哪里找野猪","狩猎野猪区域"}},{q="为什么这次狩猎有时间限制？",a="年轻的达瑞尔将狩猎限制在十二分钟内，是因为他笃定你会失败。通过设定严格的期限，他希望让你出丑，并证明你之前的狩猎成就不过是新手的运气。",al={"为什么是十二分钟","为什么有时限","猎人挑战计时器"}},{q="年轻的达瑞尔打了什么赌？",a="在解释试炼时，年轻的达瑞尔大言不惭地宣称，如果你能及时猎杀五头年长的山猪，他就会把你脱下他身上的衬衫送给你。当然，当你凯旋而归时，他很快就假装不记得有这回事了。",al={"达瑞尔的赌注","输掉身上的衬衫","达瑞尔打了什么赌"}},{q="这与寒脊山谷的野猪相比如何？",a="年轻的达瑞尔特别指出，这些年长的山猪比新手矮人在寒脊山谷捕猎的较小野猪要强硬和凶猛得多。洛克莫丹的成年山猪拥有更厚的皮毛，以及在高地花岗岩上磨砺出的危险獠牙。",al={"寒脊山谷野猪对比山猪","寒脊山谷比较"}},{q="这个狩猎系列任务接下来会引向何处？",a="一旦你通过完成他的挑战让年轻的达瑞尔闭嘴，营地的关注点就会转向更严肃的事务，引出在任务“维林复仇”中与危险的年长熊怪老烟枪的对决。",al={"下一个任务是什么","猎人的挑战之后","狩猎任务线"}}},fp="20,188,15.446.0,17.327.0,27.255.0,43.198.0,23.188.0,24.165.0,48.217.0,40.191.1"}
P.entries["quest:26"] = {n="必修的课程",s="“必修课”是达纳苏斯训练的联盟德鲁伊早期的一项成人礼。该任务由玛斯雷·驭熊者提供，指示初学者前往月光林地的圣所，开始掌握他们的水栖形态。",h="“必修课”是达纳苏斯训练的联盟德鲁伊早期的一项成人礼。该任务由玛斯雷·驭熊者提供，指示初学者前往月光林地的圣所，开始掌握他们的水栖形态。",kw={"必修课","水栖形态","达纳苏斯","德迪利特·星焰","德鲁伊任务","玛斯雷·驭熊者","月光林地","永夜港"},ang={["class:Druid"]="此任务是德鲁伊训练中的一个重要里程碑，开启了与波浪之下塞纳留斯赐予的礼物进行交流的道路。",["race:NightElf"]="对于达纳苏斯的卡多雷来说，响应月光林地塞纳里奥议会的召唤是一项神圣的传统，将他们与古老的导师联系在一起。"},sec={{t="野性召唤",b="玛斯雷·驭熊者照看着在达纳苏斯枝叶间修行的年轻暗夜精灵德鲁伊。一旦初学者展现出与自然坚定的联系以及承担更大责任的意愿，玛斯雷便会让他们为下一个主要学科做准备：掌握水下之道。塞纳留斯赐予的礼物需要严格的专注，而要在不溺水的情况下穿越深渊，则需要与塞纳里奥议会的长者们进行直接沟通。"},{t="前往永夜港",b="若要继续，初学者必须离开达纳苏斯，前往位于海加尔山下方的古老圣地月光林地。在永夜港宁静的定居点内，德迪利特·星焰正在等待。作为议会的一名长者导师，星焰负责评估年轻的变形者是否已准备好接受解锁水栖形态所需的试炼，并警告他们：掌控水域既需要身体的强韧，也需要精神的坚定。"}},faq={{q="谁指派我进行这项任务？",a="玛斯雷·驭熊者，即居住在达纳苏斯塞纳里奥区的德鲁伊训练师，会在你的早期德鲁伊技艺成长到足够水平时提供此任务。",al={"任务发布者","谁提供必修课","谁开启此任务"}},{q="这项任务的目的是什么？",a="这是德鲁伊寻求获得水栖形态的第一步。它召唤初学者前往月光林地，接受长者德迪利特·星焰的指导和试炼。",al={"为什么要做这个任务","水栖形态入门","我能得到什么"}},{q="德迪利特·星焰在哪里？",a="德迪利特·星焰居住在月光林地的永夜港村，坐落在月神湖北岸。",al={"德迪利特的位置","德迪利特·星焰在哪里","寻找德迪利特"}},{q="德鲁伊如何为该任务前往月光林地？",a="德鲁伊拥有一种精神协调能力，可以使用“传送：月光林地”法术直接传送到月光林地的圣林，从而绕过传统的陆路。",al={"如何前往月光林地","前往永夜港"}},{q="与德迪利特·星焰交谈后会发生什么？",a="在结束与德迪利特·星焰的会面后，他会立即指派你进行“湖泊试炼”，以测试你在水下的耐力和清醒程度。",al={"下一个任务","接下来做什么","完成必修课之后"}}},fp="17,189,20.376.0,21.333.0,27.137.0,34.135.0,36.94.0,45.112.0,48.146.0"}
P.entries["quest:2605"] = {n="口渴的地精",s="身在加基森的马林·诺格弗格正饱受干渴的折磨。有传言说，位于西南方仙人掌花园的露水收集者会将水储存在特殊的腺体中，马林希望其中一个腺体能制成一种终于能解渴的饮料。",h="身在加基森的马林·诺格弗格正饱受干渴的折磨。有传言说，位于西南方仙人掌花园的露水收集者会将水储存在特殊的腺体中，马林希望其中一个腺体能制成一种终于能解渴的饮料。",kw={"仙人掌花园","露水收集者","露水腺体","加基森","马林·诺格弗格","塔纳利斯","灌木谷"},sec={{t="值得一喝的腺体",b="马林听说在加基森的西南方生活着一种被称为露水收集者的奇怪生物，它们会将水储存在特殊的腺体中。马林认为，如果能弄到一个饱满的腺体，或许就能调制出一种彻底消除干渴的饮料。你需要找到它们栖息的仙人掌花园，并带回一个腺体。"}},faq={{q="谁让你去寻找露水腺体？",a="位于加基森镇的马林·诺格弗格让你去找一个饱满的露水腺体来治愈他那可怕的干渴。",al={"干渴的地精任务发布者","谁开启干渴的地精任务","马林·诺格弗格"}},{q="露水收集者在哪里？",a="它们生活在塔纳利斯加基森西南方的灌木谷仙人掌花园中。",al={"露水收集者位置","在哪里寻找露水腺体","仙人掌花园位置"}},{q="什么生物携带饱满的露水腺体？",a="这种腺体来自灌木露水收集者，据说这些生物会将水储存在特殊的腺体中。",al={"什么掉落饱满的露水腺体","露水收集者怪物"}},{q="这个任务链接下来是什么？",a="该任务链后续是“品味不错”。",al={"干渴的地精后续任务","干渴的地精之后接什么任务"}}},fp="18,235,22.289.0,40.107.0,37.89.0,42.102.0,29.40.0"}
P.entries["quest:2606"] = {n="好味道",s="马林·诺格弗格觉得灌木露水的味道糟透了，但他决定不放弃。你带着灌木露水被派去找加基森的斯普林克，她是马林的一位朋友。",h="马林·诺格弗格觉得灌木露水的味道糟透了，但他决定不放弃。你带着灌木露水被派去找加基森的斯普林克，她是马林的一位朋友。",kw={"加基森","好品味","马林·诺格弗格","斯普林克","塔纳利斯","灌木露水"},sec={{t="糟糕的饮料，蹩脚的厨师",b="马林尝了尝灌木露水，觉得味道很可怕，但他最终决定不放弃这个想法。相反，他把灌木露水交给你，让你去找加基森的一位朋友斯普林克，马林称赞她是一位出色的厨师。你要告诉她发生了什么事，并说明这种饮料需要更容易入口。马林还希望它能有点劲儿。"}},faq={{q="这一步在任务链中处于什么位置？",a="它紧接在“口渴的地精”之后，之后是“斯普林克的秘密配料”。",al={"前置任务","任务链后续","任务进度"}},{q="为什么马林·诺格弗格想把灌木露水带给斯普林克？",a="马林觉得灌木露水很难喝。他称赞斯普林克是一位出色的厨师，希望她能让饮料更容易入口，并且更有劲儿。",al={"为什么找斯普林克","马林对斯普林克的要求","斯普林克是谁"}},{q="在哪里可以找到斯普林克？",a="斯普林克在加基森，和马林·诺格弗格在同一个城镇。",al={"斯普林克位置","斯普林克在哪","寻找斯普林克"}}},fp="13,180,21.326.0,38.79.0,59.138.0,28.62.0"}
P.entries["quest:261"] = {n="血色之路",s="位于尼耶尔前哨站的血色十字军安东兄弟说，他的组织正在与天灾军团作战，这是一种腐蚀人民并感染大地的邪恶力量。他要求你消灭白骨之谷中的三十个亡灵劫掠者来证明你的忠诚。",h="位于尼耶尔前哨站的血色十字军安东兄弟说，他的组织正在与天灾军团作战，这是一种腐蚀人民并感染大地的邪恶力量。他要求你消灭白骨之谷中的三十个亡灵劫掠者来证明你的忠诚。",kw={"安东兄弟","凄凉之地","血色之路","尼耶尔前哨站","血色十字军","天灾军团","亡灵劫掠者","白骨之谷"},sec={{t="证明忠诚",b="安东兄弟说话很直接。他说必须在天灾军团吞噬这片土地并将世界拖入黑暗之前阻止它们，而血色十字军已经发誓要进行这场战斗。如果你与他们站在一边，他希望你能通过消灭三十个亡灵劫掠者来展示你的勇气和忠诚。它们就在安东南部的白骨之谷。成功的话，十字军会欢迎你。"}},faq={{q="谁要求你消灭亡灵劫掠者？",a="位于尼耶尔前哨站的血色十字军安东兄弟。",al={"谁给予血色之路任务","安东兄弟任务","凄凉之地血色十字军npc"}},{q="在哪里可以找到亡灵劫掠者？",a="在凄凉之地的白骨之谷，位于尼耶尔前哨站的南面。",al={"亡灵劫掠者位置","白骨之谷在哪里","凄凉之地的劫掠者"}},{q="安东兄弟为什么要消灭这些劫掠者？",a="他说十字军正在与天灾军团作战，这是一种腐蚀人民并感染大地的邪恶力量，他希望以此让你证明你的忠诚。",al={"为什么要杀死亡灵劫掠者","安东兄弟动机","血色十字军原因"}},{q="需要消灭多少个劫掠者？",a="三十个。",al={"需要多少个劫掠者","劫掠者数量"}},{q="在此之前需要做什么？",a="首先是与安东兄弟会面。",al={"前置任务","血色之路的前置条件"}}},fp="21,251,19.386.0,44.55.0,36.56.0,51.145.0,36.7.0,23.44.0"}
P.entries["quest:262"] = {n="模糊的人影",s="被家人的惨死所困扰，隐士斯温·约根委托你查明那个在事发当晚徘徊在他农场附近的神秘陌生人的身份。你仅拿着从废墟中寻获的一本神秘书籍，必须去询问夜色镇的居民，以此追寻那个陌生人的踪迹。",h="被家人的惨死所困扰，隐士斯温·约根委托你查明那个在事发当晚徘徊在他农场附近的神秘陌生人的身份。你仅拿着从废墟中寻获的一本神秘书籍，必须去询问夜色镇的居民，以此追寻那个陌生人的踪迹。",kw={"书籍","夜色镇","暮色森林","伊瓦夫人","阴影中的身影","斯温·约根","斯温的营地"},ang={["class:Priest"]="调查伊瓦夫人的占卜突显了精神通灵、暗影魔法，以及依附在日常物品上看不见的灵能印记之间那层薄薄的帷幕。",["faction:Alliance"]="夜色镇缺乏来自暴风城的支援，这迫使那些饱受创伤的边疆民兵和当地先知只能完全依靠四处游历的联盟勇士来调查暮色森林中发生的致命暴行。"},sec={{t="屠杀的回响",b="斯温·约根因家人的惨遭屠戮而心力交瘁，躲藏在暮色森林荒凉的丘陵中。虽然他最初将矛头指向了那些在森林中横行霸道的神秘黑骑士，但他的记忆却被另一个细节所折磨：在屠杀发生当晚，有一个安静的、阴暗的身影在附近徘徊。由于急于寻找答案，斯温将从废墟中找到的唯一线索交给了你——一本被遗弃在被洗劫的农场里的奇怪书籍。"},{t="在镇上寻求占卜",b="在危险的荒野中没有直接线索可寻，线索指向了东边的夜色镇。斯温希望那些迷信的当地人中有人能认出这本奇怪的书。夜色镇藏着不少怪事和灵媒，其中最出名的是伊瓦夫人，她那神秘的感官和占卜术让她能看穿凡人的目光，读出依附在神秘遗物上的灵魂印记。"},{t="外来的线索",b="把这本书交给伊瓦夫人，显现出了微弱但清晰可辨的灵能印记。虽然斯温强烈的复仇欲望近期留在了书页上，但底层的气息却完全属于另一个人。伊瓦夫人占卜出，这本书的原主根本不是夜色镇或暮色森林的居民，这证实了在流血事件发生前，有一个外来者曾到过农场。"}},faq={{q="斯温·约根是谁？",a="斯温·约根是一位饱受摧残的农夫，被迫流亡到暮色森林西部的丘陵中。在黑骑士袭击了他的家园并屠杀了他全家之后，他带着悲痛和对凶手强烈的复仇渴望，追逐着他们进入了荒野。",al={"sven是谁","sven的背景故事","斯温·约根"}},{q="在斯温的农场里发现的那本书是什么？",a="这本书是从斯温被毁的家园的泥土和瓦砾中寻获的实物遗物。它属于一个难以捉摸的旁观者，在袭击发生时，有人看到他在阴影中潜伏。",al={"这是什么书","来自sven农场的书","神秘书籍"}},{q="为什么要带着书去找伊瓦夫人？",a="伊瓦夫人是夜色镇常驻的先知和占卜师。普通的镇民从一本无名的书里看不出什么，但伊瓦夫人利用她的通灵力量，可以解读之前拥有或携带该物品的人所留下的残留灵能印记。",al={"为什么要找伊瓦夫人","谁来阅读这本书","夜色镇的神秘主义者"}},{q="伊瓦夫人从书中了解到了什么？",a="伊瓦夫人感应到了斯温最近接触它时留下的强烈的复仇情绪印记。然而，在这之下，她检测到了微弱的痕迹，表明原主是一个并非来自夜色镇的外来者。",al={"伊瓦夫人说了什么","书的主人身份","占卜结果"}},{q="接下来调查的方向是什么？",a="得知书的主人是个外来者，伊瓦夫人让你去搜寻夜色镇的其他记录和地点，寻找是否有人还记得符合那个身影特征的陌生旅客。",al={"接下来做什么","书之后的任务","阴影中的人是谁"}}},fp="18,175,21.344.0,26.310.0,15.276.1,19.232.0,38.201.0,32.230.0,41.186.1,40.199.1"}
P.entries["quest:2622"] = {n="丢失的命令",s="当你问起丢失的命令时，分队指挥官鲁尔格显得有些恼火，坚持说命令已经传达下去了。鲁尔格说运送命令的士兵遭到了鱼人的伏击，只有一人幸存，并让你去找本戈尔谈谈。",h="当你问起丢失的命令时，分队指挥官鲁尔格显得有些恼火，坚持说命令已经传达下去了。鲁尔格说运送命令的士兵遭到了鱼人的伏击，只有一人幸存，并让你去找本戈尔谈谈。",kw={"伏击","本戈尔","分队指挥官鲁尔格","丢失的命令","鱼人","悲伤沼泽"},sec={{t="鲁尔格的陈述",b="鲁尔格对这个问题感到冒犯，坚持声称命令已经传达。据鲁尔格所说，那些负责运送命令的士兵遭到了鱼人的伏击并被残忍地殴打，最后只有一个人活了下来，如果那也能叫活着的话。幸存者几乎无法说话，不能行走，只能靠插管进食。鲁尔格说，想知道命令的下落就去找本戈尔，他就在这附近，并警告你少管闲事，以免惹火上身。"},{t="本戈尔支离破碎的话语",b="当你找到本戈尔时，他只能说出一些支离破碎的词句，你在其中捕捉到了“沼泽语者”这个词。"}},faq={{q="是谁发出了丢失的命令？",a="分队指挥官鲁尔格声称命令已经随派出的士兵一并传达，当被问及命令的下落时，他变得充满防备。",al={"谁发出了丢失的命令","谁弄丢了命令"}},{q="运送命令的士兵发生了什么事？",a="据分队指挥官鲁尔格所说，他们遭到了鱼人的伏击并被残忍地殴打，只有一人幸存。",al={"信使发生了什么","命令是怎么丢失的"}},{q="本戈尔是谁？",a="本戈尔是那场伏击中唯一的幸存者。他几乎无法说话，不能行走，只能靠插管进食。",al={"幸存者是谁","本戈尔背景故事"}},{q="本戈尔在哪里？",a="分队指挥官鲁尔格只说本戈尔就在这附近。",al={"本戈尔位置","本戈尔在哪里"}}},fp="18,216,14.454.0,22.109.1,38.132.0,50.98.0,14.101.0,26.71.0"}
P.entries["quest:2623"] = {n="沼泽空谈者",s="本戈尔几乎无法说话，但他还是设法说明了命令的下落。派遣指挥官发布了命令，在前往诅咒之地的途中，这支队伍遭到了许多鱼人的伏击。其中一个名叫Swamp Talker的鱼人从他手中夺走了命令。必须取回这些命令并交给部落英雄的灵魂。",h="本戈尔几乎无法说话，但他还是设法说明了命令的下落。派遣指挥官发布了命令，在前往诅咒之地的途中，这支队伍遭到了许多鱼人的伏击。其中一个名叫Swamp...",kw={"本戈尔","诅咒之地","部落英雄的灵魂","鱼人","悲伤沼泽","swamp talker","酋长的命令"},sec={{t="本戈尔支离破碎的叙述",b="本戈尔说，派遣指挥官发布了命令，他的队伍在前往诅咒之地的路上遭到了许多鱼人的伏击。当一支长矛刺入他的头骨时，一个名叫Swamp Talker的鱼人从他手中夺走了命令。本戈尔在昏迷前，费力地说出了东边有个洞穴。必须取回这些命令并交给部落英雄的灵魂。"},{t="部落英雄的清算",b="部落英雄的灵魂发现情况比想象中更糟。如果他当时没有做出如此不理智的行动，他手下的十九个人本可以免受折磨。他现在无力采取行动，恳求你去帮助那些人。"}},faq={{q="是谁偷走了酋长的命令？",a="在伏击期间，一个名叫Swamp Talker的鱼人从本戈尔手中抢走了命令。",al={"谁拿走了命令","swamp talker是谁","谁偷了命令"}},{q="Swamp Talker去了哪里？",a="本戈尔那微弱的话语提到了东边的一个洞穴。",al={"swamp talker在哪里","swamp talker的位置","鱼人洞穴在哪里"}},{q="本戈尔和他的部队要去哪里？",a="他们在前往诅咒之地的途中遭到了鱼人的伏击，当时正带着派遣指挥官下达的命令。",al={"本戈尔的目的地","本戈尔要去哪里","本戈尔部队的目标"}},{q="应该把命令交给谁？",a="必须把命令带给部落英雄的灵魂。",al={"谁接收酋长的命令","我在哪里上交命令","上交swamp talker任务"}}},fp="16,317,23.392.0,27.213.1,32.82.0,30.49.0,39.121.0,38.53.0"}
P.entries["quest:263"] = {n="保卫国王的领土",s="此任务代表了铁炉堡的巡山人为了对抗洛克莫丹南部的穴居人入侵而进行的不断升级的斗争。巡山人沃尔班在南部哨塔指挥着经验丰富的招募兵进入碎石怪之谷，以清除危险的穴居人萨满和前线碎骨者。完成此试炼将赢得沃尔班的充分信任，并获得与该哨所指挥官拉格弗斯上尉面谈的机会。",h="此任务代表了铁炉堡的巡山人为了对抗洛克莫丹南部的穴居人入侵而进行的不断升级的斗争。巡山人沃尔班在南部哨塔指挥着经验丰富的招募兵进入碎石怪之谷，以清除危险的穴居人萨满和前线碎骨者。完成此试炼将赢得沃尔班的充分信任，并获得与...",kw={"碎骨者","铁炉堡","洛克莫丹","麦格尼","巡山人","萨满","碎石怪","穴居人","沃尔班"},ang={["class:Shaman"]="直面碎石怪穴居人粗陋的施法者，可以让你以一种原始、野蛮的角度审视被野性本能扭曲的大地魔法。",["faction:Alliance"]="援助南部哨塔能够巩固连接丹莫罗、东部湿地以及暴风城王国的重要贸易和旅行路线。",["race:Dwarf"]="响应沃尔班的号召对于任何矮人来说都是保家卫国之事，在同族正规军被调往海外时，站出来保护洛克莫丹的家园。"},sec={{t="单薄的矮人防线",b="洛克莫丹的防御已捉襟见肘。随着矮人正规预备役被征调至艾泽拉斯各地的遥远前线，像南部哨塔这样的地方哨所人手严重不足。巡山人沃尔班和他的几位同袍面临着碎石怪部族的持续压力，这迫使他们不得不极度依赖到访的联盟旅者来守住南部的关口。"},{t="目标：碎石怪先锋",b="与其猎杀零星的斥候，此项行动将更深入地打击碎石怪的层级结构。穴居人碎骨者为部族提供了残酷的蛮力，而他们原始的萨满则编织大地魔法来集结同族。消灭二十个此类高价值目标将削弱他们对低地的入侵，直接服务于国王麦格尼·铜须对王国的保卫工作。"}},faq={{q="巡山人沃尔班是谁？",a="巡山人沃尔班是一位驻扎在洛克莫丹南部哨塔的铁炉堡矮人。他的任务是监控从山脉中蔓延出来的穴居人活动，并协调民兵力量以确保南部主干道的安全。",al={"沃尔班","沃尔班是谁","巡山人沃尔班背景故事"}},{q="为什么巡山人要向旅者寻求帮助？",a="铁炉堡的军事预备役已被征调至王国境内及海外更优先的战线。这种重新部署使得像洛克莫丹南部岗哨这样的边境哨所面对当地威胁时，人手严重短缺。",al={"为什么矮人需要帮助","铁炉堡卫兵在哪里","为什么没有预备役"}},{q="这些穴居人位于何处？",a="它们主要聚集在碎石怪之谷，隐藏在洛克湖西南方崎岖的丘陵中。这些萨满和碎骨者的小股部队也会出没于湖面上北部的岛屿。",al={"碎石怪穴居人在哪里","碎石怪萨满位置","碎石怪之谷在哪里"}},{q="碎石怪部族为何构成威胁？",a="穴居人繁殖迅速，并通过纯粹的地下虫群淹没定居区域。碎石怪部族通过其萨满施展粗糙的元素魔法，并依靠凶猛的碎骨者撕裂矮人斥候，威胁着附近的定居点和贸易路线。",al={"为什么穴居人很危险","碎石怪威胁"}},{q="在这项任务之后巡山人沃尔班会做什么？",a="在确认你是效忠于麦格尼国王的可靠战士后，沃尔班会指引你去向拉格弗斯上尉报到，以获取更多关于保卫洛克莫丹的战略指令。",al={"沃尔班任务之后做什么","上尉是谁"}},{q="在这场危机中，谁统治着铁炉堡？",a="国王麦格尼·铜须在铁炉堡的High Seat统治着矮人王国。为保卫洛克莫丹所做的每一份努力都是以他的名义进行的，旨在捍卫他的主权领土。",al={"矮人国王是谁","铁炉堡国王"}}},fp="30,305,19.346.0,36.308.0,28.214.0,51.201.0,31.186.0,43.218.0,50.174.0,39.159.0"}
P.entries["quest:264"] = {n="至死方休",s="“直到死亡将我们分离”是一个充满苦涩的个人任务，它将玩家引向银松森林的瑟伯切尔。克拉莉斯·弗斯特，一位居住在雷霆崖下方预见之池的被遗忘者，派遣冒险者将她的坠饰丢弃在她已故丈夫尤里夫的墓碑上。这项任务揭示了当瘟疫席卷洛丹伦时，狂热与战争所造成的人性破碎。",h="“直到死亡将我们分离”是一个充满苦涩的个人任务，它将玩家引向银松森林的瑟伯切尔。克拉莉斯·弗斯特，一位居住在雷霆崖下方预见之池的被遗忘者，派遣冒险者将她的坠饰丢弃在她已故丈夫尤里夫的墓碑上。这项任务揭示了当瘟疫席卷洛丹伦...",kw={"克拉莉斯·弗斯特","十字军东征","被遗忘者","坠饰","瑟伯切尔","银松森林","坟墓","尤里夫"},ang={["class:Priest"]="这个任务描绘了一幅关于信仰的残酷画面，突显了对圣光的狂热是如何拆散家庭，并给幸存者心中留下持久的苦涩。",["faction:Horde"]="帮助克拉莉斯可以让部落的勇士们深入了解将银松森林的被遗忘者们凝聚在一起的个人悲剧与持久怨恨。",["race:Undead"]="对于被遗忘者来说，克拉莉斯的困境体现了生者的虚伪：圣战战士们为了狂热的信仰离开了家人，任由他们毁灭，留下的只有那些被转化后的幸存者来承受记忆的重负。"},sec={{t="苦涩的纪念品",b="克拉莉斯·弗斯特对她凡人婚姻的回忆毫无留恋。当洛丹伦分崩离析时，她的丈夫尤里夫抛弃了她和孩子们，去参加一场针对日益壮大的亡灵威胁的十字军东征，并声称侍奉圣光高于一切。最终，他的虔诚既没能拯救他的家庭，也没能拯救他自己。如今，克拉莉斯已复生成为亡灵，而尤里夫则在破损的墓碑下腐烂，她只想抛弃这最后一件关于他那破碎诺言的有形信物。"},{t="被遗弃的坟墓",b="尤里夫的墓位于瑟伯切尔周围的墓地中，墓碑上伤痕累累，散落着垃圾，并长满了杂草。将克拉莉斯的坠饰放在他双手雕像的浮雕上，并没有引发什么伟大的魔法或精神上的解脱，只是让宝石变得暗淡，并有一阵冰冷、静默的风吹过坟墓。这无声地见证了洛丹伦亡者心中挥之不去的怨恨。"}},faq={{q="尤里夫是谁？",a="尤里夫是克拉莉斯·弗斯特身为凡人时的丈夫。生前，他为了以圣光之名对抗天灾军团，抛下了她和孩子们，将十字军东征置于家庭之上。",al={"尤里夫是谁","尤里夫背景故事","克拉莉斯的丈夫"}},{q="为什么克拉莉斯如此痛恨她已故的丈夫？",a="克拉莉斯曾无数次在夜晚等待尤里夫归来，而他却将宗教职责放在首位。最终，他的十字军东征没能保护她们，他死在了一座荒废的坟墓里，而她却被诅咒复生，变成了他生前极力对抗的那种亡灵怪物。",al={"克拉莉斯为何愤怒","克拉莉斯·弗斯特背景"}},{q="归还坠饰后会发生什么？",a="当坠饰被放置在尤里夫雕像的双手上时，宝石明显变暗了。一阵寒冷、僵硬的微风吹过瑟伯切尔，留下了那座被损毁的坟墓，在寒冷与寂静中被遗弃。",al={"坟墓上的坠饰","直到死亡将我们分离结局"}},{q="尤里夫的墓在哪里？",a="尤里夫的墓碑位于瑟伯切尔的墓地区域，那是被遗忘者在银松森林北部设立的据点。",al={"尤里夫的墓在哪里","尤里夫墓地位置"}},{q="为什么尤里夫的坟墓损毁得如此严重？",a="坟墓被利刃划破，堆满了垃圾，并长满了杂草。生活在瑟伯切尔的被遗忘者对一个死于对抗他们同类的十字军战士毫无同情或敬意。",al={"为什么坟墓被损毁","坟墓遭破坏"}},{q="克拉莉斯的孩子们幸存了吗？",a="克拉莉斯提到尤里夫在抛弃她的同时，也抛弃了他们的孩子，但他们的最终命运并未提及。考虑到洛丹伦所遭受的彻底毁灭，他们很可能遭遇了悲惨的结局。",al={"孩子们发生了什么","克拉莉斯的孩子"}}},fp="22,265,17.408.0,19.333.0,14.166.0,47.191.0,41.178.1,30.104.0,32.174.0,31.149.0"}
P.entries["quest:2641"] = {n="斯普琳科的秘密佐料",s="在马林·诺格弗格的饮料味道变得糟糕透顶后，加基森的斯普林克提议用她的秘密配料——一种名为紫色水生菇的蘑菇——来让它变得可口。这种蘑菇生长在辛特兰的一个小湖泊的水底。",h="在马林·诺格弗格的饮料味道变得糟糕透顶后，加基森的斯普林克提议用她的秘密配料——一种名为紫色水生菇的蘑菇——来让它变得可口。这种蘑菇生长在辛特兰的一个小湖泊的水底。",kw={"加基森","辛特兰","蘑菇","诺格弗格","斯普林克","塔纳利斯","紫色水生菇"},sec={{t="厨师的秘密",b="斯普林克讲述了她的童年往事，那时都是她姐姐在做饭，做出来的东西难以下咽。后来她发现了一种蘑菇，也就是紫色水生菇，这是她的“秘密”配料，能让每一道菜都变得美味无比。她会用它来帮助将马林的糟糕饮料变成可口的饮品。"},{t="水下",b="这种蘑菇生长在辛特兰的一个小湖里。瓦罗温湖位于横穿该区域的道路正南方。紫色水生菇只生长在水下，所以你必须潜入水面之下进行采集，然后回到加基森找斯普林克。"}},faq={{q="斯普林克是谁？",a="斯普林克是加基森的一位厨师，也是马林·诺格弗格的朋友。马林把你派到她那里，因为他配制的饮料味道很糟糕。",al={"斯普林克是谁","加基森的斯普林克","斯普林克的秘密配料任务发布者"}},{q="什么是紫色水生菇？",a="那是斯普林克小时候发现的一种蘑菇，她称之为自己的秘密配料。她说这种蘑菇能让任何东西尝起来都很棒。",al={"紫色水生菇","什么是紫色水生菇","秘密配料蘑菇"}},{q="哪里可以找到紫色水生菇？",a="只能在水下找到，位于辛特兰的一个小湖里。瓦罗温湖位于横穿该区域的道路正南方。",al={"哪里有紫色水生菇","哪里可以找到秘密配料","紫色水生菇位置"}},{q="这和马林·诺格弗格有什么关系？",a="马林的饮料味道太差了，所以斯普林克想要紫色水生菇来把它变成可口的饮品。",al={"斯普林克为什么需要这个","马林·诺格弗格的关联","诺格弗格任务线"}}},fp="28,215,15.292.0,15.272.0,16.112.0,26.115.0,37.112.0,44.99.0"}
P.entries["quest:265"] = {n="继续搜寻",s="随着伊瓦夫人的占卜，调查从她的客厅一路延伸到夜色镇的书记员达尔塔处。调查重点是追溯在那本从斯温·约根被洗劫的农场废墟中寻获的日记的来源。",h="随着伊瓦夫人的占卜，调查从她的客厅一路延伸到夜色镇的书记员达尔塔处。调查重点是追溯在那本从斯温·约根被洗劫的农场废墟中寻获的日记的来源。",kw={"书","书记员达尔塔","夜色镇","暮色森林","日记","伊瓦夫人","暗影身影","斯温·约根"},ang={["class:Rogue"]="通过购买记录和商人的印象在镇上追踪一个紧张的目标是经典的调查手段。",["faction:Alliance"]="查明是谁在暮色森林中资助和帮助死灵法师，对于保卫夜色镇并将正义带给那些惨遭屠戮的边境家园定居者至关重要。"},sec={{t="追踪装订来源",b="在检查了从斯温的农场惨剧中抢救出来的沾满污垢的日记后，伊瓦夫人断定，虽然日记的作者是一个外来者，但这本书本身却来自夜色镇。书记员达尔塔经常向旅行的学者、施法者和记录员出售空白账簿和书籍。通过追寻当地贸易的线索，调查者们试图找到一条普通的书面记录，以查明那个潜伏在暮色森林阴郁树林中、难以捉摸且险恶的闯入者。"},{t="一个神经质的买家",b="在查看了这本书后，书记员达尔塔清晰地回忆起了这笔交易，尽管夜色镇市政厅处理的记录数量庞大。大约一个月前，一位紧张而鬼鬼祟祟的旅行者买走了这本空白书，却从未透露姓名。顾客神经质的表现和不断回头张望的样子给书记员留下了深刻的印象，证实了斯温瞥见的那个暗影身影确实曾在夜色镇的居民中大摇大摆地走过。"}},faq={{q="这本神秘的书是从哪里来的？",a="伊瓦夫人说作者对夜色镇来说是个陌生人，但这本书是在镇上买的。书记员达尔塔出售空白书籍，可能记得购买者。",al={"书的来源","谁卖了这本书","书籍出处"}},{q="为什么伊瓦夫人让你去找书记员达尔塔？",a="伊瓦夫人认出这本书的装订和材料是当地购买的。书记员达尔塔负责向当地人和旅行学者出售空白账簿和日记。",al={"为什么要找达尔塔","伊瓦夫人和达尔塔的联系","谁制作了这本书"}},{q="书记员达尔塔对买家有什么印象？",a="达尔塔记得近几个月从他那里买书的人。向他出示这册书可以让他查明是谁购买的。",al={"谁买了书","买家描述","暗影身影的外貌"}},{q="这与斯温的农场有什么联系？",a="这本书是从位于暮色森林南部的斯温·约根被毁的农场中抢救出来的，是在那场摧毁了他家庭的谋杀性袭击中遗留下来的。",al={"与斯温的联系","我们为什么要搜寻","斯温·约根"}},{q="调查下一步指向哪里？",a="由于这位紧张的陌生人在镇上待过，搜寻工作将在夜色镇的旅店，即Scarlet Raven Tavern继续进行，看看是否有人目击了他住在哪里或与谁交谈过。",al={"下一步做什么","找过达尔塔之后","下一个线索"}},{q="书记员达尔塔有危险吗？",a="达尔塔正在协助确认他普通书刊销售的买家。这次交流没有任何迹象表明他个人受到了威胁。",al={"书记员达尔塔的危险","达尔塔是否安全"}}},fp="28,175,19.314.0,15.355.1,40.150.0,45.168.0,48.90.0,37.143.0,39.144.1,26.126.0"}
P.entries["quest:266"] = {n="调查旅店",s="“打听旅店的消息”是夜色镇的一项联盟任务，旨在继续调查与斯温·约根废弃农场有关的神秘陌生人。在书记员达尔塔的指引下，冒险者将一本找回的日记带到Scarlet Raven Tavern，向旅店老板斯密茨询问入住者的信息。",h="“打听旅店的消息”是夜色镇的一项联盟任务，旨在继续调查与斯温·约根废弃农场有关的神秘陌生人。在书记员达尔塔的指引下，冒险者将一本找回的日记带到Scarlet Raven Tavern，向旅店老板斯密茨询问入住者的信息。",kw={"书记员达尔塔","夜色镇","暮色森林","打听旅店的消息","乌鸦岭","scarlet raven","神秘的身影","斯温·约根","旅店老板斯密茨"},ang={["class:Rogue"]="从旅店传闻到凄凉废墟，追踪多疑的逃亡者完全符合一名特工的调查手段。",["faction:Alliance"]="调查夜色镇内的威胁，有助于保护东部王国南部地区最脆弱、最偏远的联盟定居点之一。"},sec={{t="Scarlet Raven的线索",b="当书记员达尔塔检查完从斯温·约根农场找回的破旧书籍后，他认为任何造访夜色镇的陌生人几乎肯定会经过当地的旅店。Scarlet Raven Tavern是镇上唯一的聚会场所和旅馆，因此它是追踪过往旅客最合适的地方。"},{t="多疑的房客",b="将书交给旅店老板斯密茨证实了达尔塔的猜测。斯密茨立刻认出了这本册子，回想起曾有一位客人在那里住过几天，每天晚上都在吧台边疯狂地写个不停。据这位旅店老板所说，那名客人惊恐万状地逃离了夜色镇，确信自己正被看不见的追捕者无情地猎杀。他的足迹一路向西，朝着乌鸦岭阴森的道路走去。"}},faq={{q="是谁让你去旅店打听的？",a="书记员达尔塔，这位位于夜色镇市政厅的镇档案管理员，将日记交还给你，并建议去当地旅店询问是否有人认得它的主人。",al={"谁发布此任务","任务发布者","打听旅店的消息在哪里开始"}},{q="你带着的那本书是什么？",a="那是从暮色森林南部的斯温·约根废弃农场找回的破旧日记，据信属于那个在这一带出没的阴影般的身影。",al={"书是什么","斯温农场发现的书","日记"}},{q="谁经营着Scarlet Raven Tavern？",a="旅店老板斯密茨负责经营Scarlet Raven Tavern，为那些仍敢于冒险进入暮色森林的旅客提供酒水和住宿。",al={"谁是旅店老板","夜色镇旅店老板","斯密茨是谁"}},{q="旅店老板斯密茨透露了关于那位客人的什么信息？",a="斯密茨回忆说，日记的主人租了一间房住了几天，晚上一直在喝酒和写作。后来那名旅客在恐慌中向西逃跑了，嘴里还念叨着被某种可怕的东西追杀。",al={"斯密茨说了什么","神秘身影发生了什么","旅店老板知道什么"}},{q="那个神秘的身影逃往了何处？",a="他急匆匆地向西逃离了夜色镇寻找藏身之处，引导追寻者前往乌鸦岭那片荒废的定居点和广阔的墓地。",al={"他去了哪里","神秘的身影在哪里","接下来去哪"}},{q="“打听旅店的消息”之后是什么任务？",a="旅店老板斯密茨指引你去完成“寻找神秘的身影”任务，沿着那个陌生人留下的踪迹向西追寻。",al={"后续任务","打听旅店的消息之后做什么"}}},fp="18,161,27.319.0,18.286.1,25.161.0,34.148.0,34.127.0,51.172.0,34.71.0,38.95.0"}
P.entries["quest:2661"] = {n="给马林的粉末",s="加基森的斯普林克交给你一包紫色粉末，让你带给马林·诺格弗格，并提醒你转告马林，他欠她一个人情。",h="加基森的斯普林克交给你一包紫色粉末，让你带给马林·诺格弗格，并提醒你转告马林，他欠她一个人情。",kw={"加基森","马林·诺格弗格","诺格弗格药剂","斯普林克","塔纳利斯","紫色粉末"},sec={{t="城镇快递",b="在拿到紫色水生菇后，斯普林克把紫色粉末交给你，让你送到同样位于加基森的马林·诺格弗格那里。你要告诉马林，他欠她一个人情。"}},faq={{q="谁派你去找马林·诺格弗格的？",a="在你把紫色水生菇交给加基森的斯普林克之后，她会给你紫色粉末。",al={"谁给马林的快递任务","马林的快递任务发布者","斯普林克的快递"}},{q="你要递送什么物品？",a="紫色粉末，斯普林克让你带给马林·诺格弗格的东西。",al={"带给马林什么","马林的快递物品","什么粉末"}},{q="马林·诺格弗格在哪里？",a="在加基森，和斯普林克在同一个城镇。",al={"马林·诺格弗格位置","马林在哪里","寻找马林·诺格弗格"}},{q="斯普林克想要传达给马林什么消息？",a="她想让马林知道，他欠她一个人情。",al={"斯普林克的消息","斯普林克对马林说了什么","斯普林克的人情"}}},fp="18,132,15.176.0,36.90.0,29.71.0,36.40.0,48.46.0"}
P.entries["quest:2662"] = {n="诺格弗格药剂",s="马林·诺格弗格在加基森将紫色粉末混合进露水中，并让你稍后再回来找他，届时他的神奇药剂就完成了。",h="马林·诺格弗格在加基森将紫色粉末混合进露水中，并让你稍后再回来找他，届时他的神奇药剂就完成了。",kw={"露水","加基森","哥布林","马林·诺格弗格","诺格弗格药剂","粉末","斯普琳科","塔纳利斯"},sec={{t="混合药剂",b="马林拿到了露水和粉末，开始将两者混合在一起。你需要稍等片刻，然后再次与马林交谈，此时诺格弗格药剂应该已经准备好了。"},{t="马林的结论",b="当马林完成后，他会递给你一杯饮料，并声称其效果绝妙。马林吹嘘说这瓶药剂将为他带来数百万的收入，他让你站到一边以免妨碍生意，并对斯普琳科声称的人情嗤之以鼻，认为那只是个玩笑。"}},faq={{q="谁提供这个任务？",a="马林·诺格弗格，位于加基森。",al={"诺格弗格任务给予者","谁提供诺格弗格药剂","马林·诺格弗格任务"}},{q="在这一步之前发生了什么？",a="此任务紧接“给马林的货物”。在此之前是“口渴的哥布林”、“好的口味”和“斯普琳科的秘密配料”。",al={"诺格弗格药剂前置任务","马林的上一个任务","诺格弗格药剂的前置任务是什么"}},{q="马林在这里混合了什么原料？",a="马林将从斯普琳科那里得到的紫色粉末混合进了露水中。",al={"诺格弗格配方原料","马林正在混合什么","药剂里有什么"}}},fp="19,161,17.191.0,15.233.1,22.33.0,27.115.0,41.57.0"}
P.entries["quest:267"] = {n="穴居人的威胁",s="“穴居人威胁”是一项联盟任务，由洛克莫丹南门岗哨的拉格弗斯上尉发布。由于当地的铁炉堡预备队已被调往支援联盟的其他战线，剩余的守军在对抗山丘中充满敌意的穴居人部落时显得捉襟见肘。冒险者们受命去消灭这些穴居人，并带回它们的石牙，以减轻山口所面临的防守压力。",h="“穴居人威胁”是一项联盟任务，由洛克莫丹南门岗哨的拉格弗斯上尉发布。由于当地的铁炉堡预备队已被调往支援联盟的其他战线，剩余的守军在对抗山丘中充满敌意的穴居人部落时显得捉襟见肘。冒险者们受命去消灭这些穴居人，并带回它们的石...",kw={"拉格弗斯上尉","铁炉堡预备队","卡兹莫丹","洛克莫丹","magni bronzebeard","南门","穴居人","穴居人的石牙"},ang={["faction:Alliance"]="该任务凸显了联盟在遥远地区的作战承诺如何掏空了像洛克莫丹这类地区的防卫储备。",["race:Dwarf"]="对于矮人来说，清除南门附近的穴居人是履行对卡兹莫丹的直接职责，并将获得国王麦格尼·铜须本人的赞许。"},sec={{t="日渐空虚的边境",b="守卫洛克莫丹南入口的防线如今岌岌可危。常规的矮人山地巡逻队和铁炉堡预备役军团已被派遣去增援更广阔的联盟战争前线，只留下拉格弗斯上尉和一支残缺的卫戍部队驻扎在南岗哨。由于受到不得擅离职守的严格军令限制，拉格弗斯无法对高地发动主动进攻，这使得附近的定居者和旅人极易遭受伏击。"},{t="遏制浪潮",b="盘踞在周边峭壁上的穴居人对卡兹莫丹构成了日益严重的威胁。若不加以遏制，它们的数量会迅速膨胀，进而威胁到矮人的前哨站。为了争取时间并削弱这一威胁，拉格弗斯号召流浪的冒险者直接突袭穴居人在山坡上的巢穴，并上交割下的石牙作为完成任务的实质证据。"}},faq={{q="拉格弗斯上尉是谁？",a="拉格弗斯上尉是驻扎在洛克莫丹南门岗哨的一名矮人军官。他的职责是守卫山口，防止入侵，同时还要应对驻军严重不足的窘境。",al={"拉格弗斯上尉","谁发布了穴居人威胁","拉格弗斯"}},{q="为什么南门的驻军不足？",a="铁炉堡预备队已被征召并重新部署，前往国外的更大型联盟前线作战。仅有一小支军团留守岗哨，他们受限于防守职责，无法发起反击。",al={"为什么没有卫兵","铁炉堡预备队缺席","矮人士兵在哪里"}},{q="什么是穴居人石牙？",a="穴居人有着天生石化、状如岩石的牙齿特征，这反映了它们源自地底的土灵血统。拉格弗斯上尉要求冒险者带回这些牙齿，作为它们已被击杀的无可辩驳的实质证据。",al={"穴居人的石牙","石牙","为什么需要穴居人牙齿"}},{q="穴居人在哪里？",a="这些穴居人栖息在洛克莫丹南门附近的岩石山丘、峡谷以及道路两旁的挖掘场中。",al={"哪里可以找到穴居人","洛克莫丹的穴居人位置","这个任务的穴居人在哪里"}},{q="为什么穴居人现在构成了如此大的威胁？",a="穴居人繁殖迅速，具有极强的领地侵略性，一旦军方撤离，它们就会涌入定居区。若不主动进行清理，它们将会堵塞连接洛克莫丹与周边地区的通道。",al={"为什么穴居人很危险","穴居人问题","穴居人想要什么"}},{q="完成这个任务对国王麦格尼·铜须有什么帮助？",a="国王麦格尼·铜须肩负着保卫整个卡兹莫丹安全的重任。在铁炉堡的军队远征在外时，冒险者们通过减少穴居人的数量，保护了王国内部的补给线和脆弱的边境定居点。",al={"与麦格尼·铜须的联系","麦格尼会在意吗","为什么要帮助铁炉堡"}}},fp="16,241,19.279.0,17.283.0,25.170.0,38.173.0,27.184.0,29.111.0,43.196.0,58.204.0"}
P.entries["quest:268"] = {n="回复斯温",s="这个任务标志着斯温·约根终于得知了导致他的家人在约根农场惨遭屠杀的真相。在追踪到逃跑的基特斯之后，你带着那个流浪汉的日记回到了斯温位于西部荒野边缘的孤立营地。这本日记有望解答自袭击发生以来一直困扰着斯温的疑问。",h="这个任务标志着斯温·约根终于得知了导致他的家人在约根农场惨遭屠杀的真相。在追踪到逃跑的基特斯之后，你带着那个流浪汉的日记回到了斯温位于西部荒野边缘的孤立营地。这本日记有望解答自袭击发生以来一直困扰着斯温的疑问。",kw={"黑暗骑士","暮色森林","荒弃鬼屋","基特斯","基特斯的日记","morbent fel","斯温·约根","约根农场"},ang={["class:Paladin"]="帮助斯温揭开杀害他家人的凶手背后的势力，履行了保护无辜者并寻求正义的神圣职责。",["faction:Alliance"]="约根农场的悲惨毁灭有力地提醒了人们，暴风城在保护暮色森林边境定居点免受阴影侵蚀方面是彻底失败的。"},sec={{t="懦夫的供词",b="当约根农场遭到袭击时，基特斯惊恐地逃进了森林，只在屠杀现场留下了一本未写完的日记。由于害怕斯温的愤怒并被他所目睹的一切所折磨，基特斯躲进了暮色森林深处。当你找到他时，他主动交出了完整的日记，迫切地希望通过提供袭击的完整内幕，能让他免于亲自面对这位复仇心切的农夫。"},{t="揭开黑暗骑士的真面目",b="阅读了基特斯的完整叙述后，斯温终于将这些可怕的碎片拼凑在了一起。他农场里的屠杀并非偶然的亡灵暴动或野兽袭击，而是由神秘的黑暗骑士为了寻找一件神器所为。此外，斯温回想起曾亲眼目睹这些戴着兜帽的身影在荒弃鬼屋附近与死灵法师Morbent Fel秘密会面。基特斯的日记将斯温盲目的悲伤转化为针对这位黑暗巫师的复仇狩猎。"}},faq={{q="为什么基特斯如此惧怕斯温·约根？",a="基特斯逃离了斯温的农场，害怕面对这位悲痛的农夫的怒火。他请求你把他的日记交给斯温，以便斯温能读到他的叙述。",al={"基特斯为什么害怕","基特斯惧怕斯温","基特斯做了什么"}},{q="基特斯的日记里写了些什么？",a="这是基特斯关于斯温农场事件的完整陈述。斯温需要阅读它来了解他的家人遭遇了什么。",al={"日记里写了什么","基特斯的日记背景"}},{q="斯温提到的黑暗骑士是谁？",a="黑暗骑士是徘徊在暮色森林中神秘的披风兜帽人。他们冷酷无情，极其危险，进入森林是为了无休止地搜寻强大的魔法圣物，所到之处只留下死亡与毁灭。",al={"黑暗骑士是谁","暮色森林的骑士","黑暗骑士"}},{q="Morbent Fel与斯温农场的袭击有什么关联？",a="Morbent Fel是暮色森林西部的一位强大死灵法师。他与这次袭击的关联是通过斯温的调查和基特斯的日记揭露出来的。",al={"morbent fel的关联","为什么是morbent fel","morbent fel是谁"}},{q="在哪里可以找到斯温·约根？",a="斯温已经放弃了他被毁的农场，现在居住在暮色森林西北山丘附近的一个小型、戒备森严的营地里，靠近通往西部荒野的边境关口。",al={"斯温在哪里","斯温·约根位置","斯温的营地"}},{q="把日记交给斯温之后会发生什么？",a="斯温读完基特斯的完整叙述后，会要求你在接下来的任务“证明你的价值”中证明你的战斗能力。",al={"斯温回归后的后续任务","斯温任务线后续"}}},fp="14,161,21.336.0,25.409.1,43.138.0,38.144.1,42.144.0,58.137.1,31.140.0,43.96.1"}
P.entries["quest:269"] = {n="寻求指引",s="“寻求智慧”是一个联盟任务，要求将“基特斯的日记”从战火纷飞的暮色森林送往安全的暴风城。斯温·约根派遣冒险者去圣光大教堂咨询主教法席恩，希望能得到神圣的建议，从而揭示如何摧毁被护盾保护的死灵法师摩尔本·奈。 ",h="“寻求智慧”是一个联盟任务，要求将“基特斯的日记”从战火纷飞的暮色森林送往安全的暴风城。斯温·约根派遣冒险者去圣光大教堂咨询主教法席恩，希望能得到神圣的建议，从而揭示如何摧毁被护盾保护的死灵法师摩尔本·奈。",kw={"主教法席恩","cathedral of light","夜色镇","暮色森林","基特斯","摩尔本·奈","寻求智慧","暴风城","斯温·约根"},ang={["class:Paladin"]="将来自被遗弃边境的圣光介入请求带到圣光大教堂的核心，这直接考验了白银之手保护被遗忘者并净化死灵法术的职责。",["class:Priest"]="主教法席恩提供了关于黑暗结界如何腐蚀灵魂与肉体的教义指导，表明阴影魔法不能仅靠刀剑对抗，而是需要专注的神圣净化。",["faction:Alliance"]="这段旅程凸显了受到守卫的暴风城大理石殿堂与得不到驻军支援的暮色森林荒凉城镇之间，那种苦涩的政治隔阂。"},sec={{t="来自阴影的恳求",b="暮色森林饱受挥之不去的诅咒、贪婪的亡灵以及暴风城皇室日益冷漠的态度所苦。斯温·约根是一名在边境露营、心碎的幸存者，他深知普通的力量无法穿透死灵法师摩尔本·奈的黑暗结界。手持流浪汉基特斯的日记，斯温敦促过往的英雄向教会而非王室请愿，并指引他们沿着道路向北前往圣光大教堂。"},{t="大教堂的指引",b="在暴风城宏伟的大教堂里，主教法席恩是为数不多仍愿意倾听暮色森林求援呼声的权威之一。在审阅了基特斯那令人不寒而栗的记录后，主教证实了摩尔本·奈那可怕的力量。这位死灵法师用邪恶的法术保护自己，足以弹开普通的攻击，这意味着仅凭盲目的勇气只会导致屠杀。为了战胜这个恶魔，必须找到一件被附魔的神圣器具。"}},faq={{q="为什么斯温不让你去找安度因国王，而是去找主教法席恩？",a="暴风城的贵族和军队基本上已经放弃了夜色镇及周边地区，任由他们在这场政治瘫痪中自生自灭。斯温知道官方渠道不会提供任何士兵，但他信任主教法席恩——一位富有同情心、学识渊博的圣光信徒，能够理解邪恶的魔法。",al={"为什么要找法席恩","为什么不找暴风城贵族","暴风城无视暮色森林"}},{q="基特斯的日记是什么，为什么主教需要它？",a="基特斯记录了袭击斯温农场前后的事件。斯温将整理好的记录送给主教法席恩，以便主教能为准备面对摩尔本·奈的冒险者提供建议。",al={"什么是基特斯的日记","为什么需要基特斯的日记","基特斯的日记"}},{q="摩尔本·奈是谁？",a="摩尔本·奈是一位强大的死灵法师，曾出没于暮色森林的荒弃鬼屋。他指挥着大批骷髅爪牙，并用强大的结界保护着自己的肉身，使其对普通武器免疫。",al={"摩尔本·奈是谁","摩尔本·奈背景故事"}},{q="主教法席恩在哪里？",a="主教法席恩位于圣光大教堂内，那是矗立在暴风城Cathedral Square区域内的一座宏伟的人类大教堂。",al={"法席恩在哪里","法席恩位置","主教法席恩地图"}},{q="主教法席恩读完日记后会发生什么？",a="主教法席恩解释说，摩尔本·奈无法被常规打击伤害。他指引冒险者去寻找一件能够驱散死灵法师魔法结界的圣物，这引出了寻找“被诅咒的舰队”的任务线。",al={"寻求智慧后续","寻求智慧任务后续","完成寻求智慧后"}},{q="斯温·约根在暮色森林的什么位置？",a="斯温·约根躲在暮色森林西北部的一个小营地里，靠近艾尔文森林南部的河流边界，位于闹鬼的乌鸦岭墓地以西。",al={"斯温在哪里","斯温·约根位置","斯温的营地"}}},fp="14,177,23.345.0,24.281.1,65.291.0,57.173.0,19.184.0,33.123.0,53.193.1,40.161.0"}
P.entries["quest:27"] = {n="必修的课程",s="“需习之课”是年轻牛头人德鲁伊准备获得驾驭水流之力时的成年礼。该任务由图拉克·符文图腾在雷霆崖的长者高地颁布，指引学员前往莫高雷的永夜港，在塞纳里奥议会的教导下开始他们的试炼。",h="“需习之课”是年轻牛头人德鲁伊准备获得驾驭水流之力时的成年礼。该任务由图拉克·符文图腾在雷霆崖的长者高地颁布，指引学员前往莫高雷的永夜港，在塞纳里奥议会的教导下开始他们的试炼。",kw={"水栖形态","塞纳里奥议会","德迪利特·星焰","长者高地","需习之课","月光林地","永夜港","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="这一仪式标志着从陆地生存向真正的元素多面性的转变，为掌握水下呼吸与移动铺平了道路。",["faction:Horde"]="尽管忠于部落，但牛头人德鲁伊必须尊重月光林地的神圣中立，在塞纳留斯的共同庇护下与暗夜精灵并肩而行。",["race:Tauren"]="该任务代表了雷霆崖的牛头人德鲁伊与坐镇于月光林地的广阔塞纳里奥兄弟会之间深厚的纽带。"},sec={{t="深渊的掌控",b="在通过熊形态掌握了原始的肉体力量后，德鲁伊的修习将转向适应性。艾泽拉斯的水道对陆行旅行者而言充满危险，这就需要一种适合深寒水域与强大水流的形态。图拉克·符文图腾会密切观察他的学生，只挑选那些已证明自己对自然怀有献身精神的人，才会将他们送往北方学习水栖形态。"},{t="前往永夜港之路",b="因为水栖变形需要深刻的灵性洞察，初学者必须在莫高雷的峭壁之外寻求指引。图拉克嘱咐他的学生前往海加尔山下受庇护的神圣避难所——月光林地。在那里，在宁静的永夜港中，塞纳里奥议会的远古暗夜精灵导师会欢迎牛头人兄弟姐妹，超越阵营纷争，以传承塞纳留斯共同的教诲。"},{t="双重试炼",b="在永夜港找到德迪利特·星焰仅仅是个开始。这位暗夜精灵长者告诫说，对水域的掌控无法轻易获得，必须通过试炼来赢得。他警告候选人，两项艰巨的考验正等待着他们：一项是测试在水下压力下工作时的耐力与镇定，另一项则是要求对水栖形态本身有着深刻的灵性理解。"}},faq={{q="谁发布了“需习之课”任务？",a="该任务由雷霆崖长者高地的德鲁伊训练师图拉克·符文图腾发布。一旦初学者达到足够的经验，他便会派他们去寻求进阶训练。",al={"谁发布需习之课","在哪里接需习之课","图拉克·符文图腾任务"}},{q="我必须去哪里完成这个任务？",a="你必须前往坐落在月光林地神圣森林中的永夜港村庄，并与塞纳里奥议会的德迪利特·星焰交谈。",al={"在哪里交需习之课","德迪利特·星焰位置","永夜港在哪里"}},{q="这个任务链会带来什么能力？",a="这是奖励德鲁伊水栖形态任务线的开端，该形态可提供快速的水下游泳速度，并能在水下无限呼吸。",al={"这会给什么形态","水栖形态任务","为什么要做这个任务"}},{q="为什么牛头人德鲁伊要向暗夜精灵寻求训练？",a="塞纳里奥议会是一个致力于塞纳留斯与保护自然的绝对中立兄弟会。在月光林地内，部落与联盟之间的政治紧张局势会被搁置，以便暗夜精灵和牛头人能够共同学习神圣的技艺。",al={"为什么是月光林地","为什么是德迪利特·星焰","塞纳里奥议会牛头人"}},{q="德迪利特·星焰所说的试炼是什么？",a="德迪利特解释说你必须面对两项具体的挑战：一项测试你在水下压力下工作时的身体镇定力，另一项测试你理解该形态本身的精神决心。",al={"两项试炼是什么","德迪利特试炼","水栖试炼"}},{q="现阶段德鲁伊如何前往月光林地？",a="德鲁伊拥有与生俱来的灵性纽带，可获得法术“传送：月光林地”，这允许他们直接从艾泽拉斯的任何地方移动到宁静的永夜港村庄。",al={"如何前往月光林地","传送至月光林地","前往永夜港"}}},fp="17,180,21.270.0,22.322.0,15.286.0,38.155.0,39.95.0,43.116.0,52.206.0,45.172.0,47.132.0"}
P.entries["quest:270"] = {n="被诅咒的舰队",s="“注定的舰队”是一段向北的旅程，由暴风城Cathedral of Light的主教法席恩派遣。为了寻找击败强大的死灵法师摩尔本·菲尔的方法，英雄们被派往卡兹莫丹，前往湿地海岸边那些沉没的残骸。",h="“注定的舰队”是一段向北的旅程，由暴风城Cathedral of Light的主教法席恩派遣。为了寻找击败强大的死灵法师摩尔本·菲尔的方法，英雄们被派往卡兹莫丹，前往湿地海岸边那些沉没的残骸。",kw={"主教法席恩","注定的舰队","戈罗林·钢眉","库尔提拉斯","圣光锻铁","米奈希尔港","摩尔本·菲尔","第三舰队","湿地"},ang={["class:Paladin"]="寻找圣洁金属来打击邪恶的死灵法师，体现了圣骑士使用圣光祝圣武器净化黑暗的使命。",["class:Priest"]="在主教法席恩的指引下行动，将牧师们直接与教会关于受祝福遗物和祝圣矿石的古老知识联系了起来。",["faction:Alliance"]="这个任务突显了联盟的后勤跨度，将南方孤立的人类城镇与矮人港口和古老的航海路线连接起来。",["profession:Blacksmithing"]="铁匠们会欣赏圣光锻铁这种罕见的传说，这是一种注入了信仰的金属，需要大师级的工艺才能塑造。"},sec={{t="神圣真理之武器",b="事实证明，普通钢铁无法对摩尔本·菲尔在Forlorn Rowe隐居处所施加的黑暗结界产生效果。为了穿透这种死灵防御，主教法席恩指示冒险者们必须打造一把与圣光相连的武器。关键材料是圣光锻铁，这是一种稀有且神圣的金属，它的打击蕴含神圣真理，能够切开那些弹开普通刀剑的魔法防护。"},{t="第三舰队的残骸",b="不幸的是，圣光锻铁在被围困的暮色森林中并没有现成的储备。法席恩回忆起多年前，库尔提拉斯岛国的第三舰队在铁炉堡以北湿地那险恶的海岸线上遭遇了灾难。在那些沉没的帆船中，有一艘载着珍贵的矿石。冒险者们必须一路前往米奈希尔港，咨询戈罗林·钢眉，他是一位熟知沼泽及其沉船的矮人联络人。"}},faq={{q="为什么我必须一路前往湿地？",a="摩尔本·菲尔的黑暗魔法保护他免受普通攻击。主教法席恩知道，只有用神圣的圣光锻铁打造的武器才能剥离那些结界，而唯一已知的矿藏就位于米奈希尔港外库尔提拉斯第三舰队的失事船只中。",al={"为什么要去湿地","为什么去米奈希尔港","湿地之行"}},{q="摩尔本·菲尔是谁？",a="摩尔本·菲尔是一位居住在暮色森林Forlorn Rowe的邪恶死灵法师。他的法术助长了困扰该地区的亡灵起义，因此击败他对于夜色镇的生存至关重要。",al={"摩尔本·菲尔身份","死灵法师是谁","暮色森林死灵法师"}},{q="戈罗林·钢眉是谁？",a="戈罗林·钢眉是一位驻扎在湿地米奈希尔港的矮人。他是圣光教会的盟友，对沼泽的海岸线、沉船和打捞行动有着深刻的了解。",al={"钢眉是谁","钢眉的作用"}},{q="什么是圣光锻铁？",a="圣光锻铁是一种被牧师们珍视的、经过特殊祝圣的金属。用它打造的武器在打击时带有神圣的力量，能够驱散或穿透普通钢铁无法撼动的黑暗护盾和死灵诅咒。",al={"圣光锻铁的作用","圣光金属","圣化钢铁"}},{q="库尔提拉斯第三舰队发生了什么事？",a="多年前，库尔提拉斯的第三舰队在湿地崎岖沼泽的海岸线上遇难并沉没。它们的船体残骸至今仍淹没在岸边，里面留有遗失的货物，并由溺毙的水手和水生掠食者守护着。",al={"第三舰队的命运","湿地的库尔提拉斯船只","船只如何沉没"}},{q="这个任务一开始就需要战斗吗？",a="这一阶段完全是一个跑腿任务。它需要从暮色森林出发，经过暴风城王国和卡兹莫丹，长途跋涉前往米奈希尔港与戈罗林·钢眉接头。",al={"有战斗吗","只是跑腿任务"}}},fp="16,181,22.267.0,28.354.0,52.244.0,19.198.0,24.176.0,24.197.0,46.194.0,48.159.0"}
P.entries["quest:272"] = {n="海狮试炼",s="海狮试炼是德鲁伊在月光林地进行的一项神圣仪式，旨在踏上掌握水栖形态的旅程。受训者需要找回两块散落的坠饰碎片，它们分别象征着海狮的敏捷与耐力，然后将它们在雷姆洛斯神殿合而为一。通过锻造出完整的海狮坠饰，德鲁伊证明了自己与水元素的和谐统一，并为引导该生物的灵魂做好了准备。",h="海狮试炼是德鲁伊在月光林地进行的一项神圣仪式，旨在踏上掌握水栖形态的旅程。受训者需要找回两块散落的坠饰碎片，它们分别象征着海狮的敏捷与耐力，然后将它们在雷姆洛斯神殿合而为一。通过锻造出完整的海狮坠饰，德鲁伊证明了自己与水...",kw={"水栖形态","德迪利特·星焰","水兽敏捷坠饰","水兽耐力坠饰","月光林地","永夜港","海狮坠饰","雷姆洛斯神殿","海狮试炼"},ang={["class:Druid"]="这项试炼是德鲁伊独有的成年仪式，在他们被允许与水元素灵魂交流并采用海狮形态之前，考验他们的精神成熟度和平衡性。",["race:NightElf"]="作为月光林地和塞纳里奥议会的长期守护者，暗夜精灵德鲁伊崇敬德迪利特·星焰的教诲以及雷姆洛斯神殿周围的神圣土地。",["race:Tauren"]="对于新加入塞纳里奥议会的牛头人德鲁伊来说，在月光林地进行试炼可以加强他们与自然灵魂的交流，并加深他们与暗夜精灵导师之间的联系。"},sec={{t="水栖形态之路",b="为了获得在艾泽拉斯深水中航行的能力，德鲁伊受训者必须在月光林地的神圣林地中进行协调测试。海狮试炼是这些重要仪式中的第二项，此前他们已经进行了精神训练方面的准备。在永夜港的德迪利特·星焰的指导下，这项试炼挑战德鲁伊去理解两种截然不同的特质——优雅的速度与坚韧的耐力——是如何达到平衡的。如果不掌握海狮天性的这两个维度，受训者就无法驾驭其形态，也无法抵御深海的危险。"},{t="敏捷与耐力",b="试炼的物质与精神核心在于从两块断裂的碎片中重新组装海狮坠饰。其中一块坠饰引导着海狮形态的敏捷，反映了其在湍急水流中优雅穿梭的能力。另一块坠饰则汲取了该生物无穷的耐力，代表了在冰冷的水中长时间潜行而不动摇所需的坚韧。受训者必须向月光林地的居民寻求线索，以发现这些散落在世界各地的圣物，这既展示了他们的足智多谋，也体现了他们在神圣庇护所内寻求指导的意愿。"},{t="雷姆洛斯神殿",b="一旦两件圣物都到手，受训者必须将碎片带到雷姆洛斯神殿附近，将它们重新结合成一枚单一的护身符。守护者的圣所提供了将敏捷与耐力的不同力量和谐融合所需的宁静而强大的能量。将修复后的海狮坠饰呈现给永夜港的德迪利特·星焰，即可完成试炼。手持这一信物，德鲁伊表明了他们已准备好拥抱海狮形态，并最终唤醒他们的水栖形态。"}},faq={{q="什么是海狮试炼？",a="海狮试炼是月光林地一项关键的德鲁伊任务，考验受训者对水生生物的理解。它要求德鲁伊找回代表敏捷和耐力的两块坠饰碎片，在雷姆洛斯神殿将它们组装起来，并将完成的护身符交给德迪利特·星焰。通过这项试炼是解锁德鲁伊水栖形态的必要里程碑。",al={"海狮试炼任务","什么是海狮试炼","海狮试炼"}},{q="谁发布海狮试炼任务？",a="月光林地雷姆洛斯神殿的守望者塔加里会发布这项试炼。受训者向当地居民寻求指导，在神殿附近将两块碎片结合，然后将制成的海狮坠饰带给位于永夜港的暗夜精灵德鲁伊德迪利特·星焰。",al={"谁给予海狮试炼","如何开始海狮试炼","海狮试炼任务发布者"}},{q="这两块坠饰碎片分别代表什么？",a="这两块坠饰碎片代表了界定海狮形态的双重特质：敏捷和耐力。一块体现了在深水中平稳滑行所需的优雅与迅捷，另一块则体现了在漫长的水下旅程中生存所需的耐力与韧性。德鲁伊必须同等尊重并体现这两种特质，才能掌握他们的变形艺术。",al={"什么是坠饰碎片","坠饰碎片的含义","敏捷与耐力碎片"}},{q="坠饰碎片位于何处？",a="要发现水兽敏捷坠饰和水兽耐力坠饰隐藏在哪里，受训者必须与月光林地的居民交谈。当地的德鲁伊和村民会提供关于每块碎片遗失或隐藏的遥远水域的关键线索。",al={"如何找到坠饰碎片","去哪里找坠饰碎片","海狮坠饰碎片位置"}},{q="在哪里组装海狮坠饰？",a="这两块碎片不能随处组合；它们必须在月光林地雷姆洛斯神殿的附近结合。雷姆洛斯守护者神殿的神圣光环提供了将敏捷与耐力的力量结合成单一功能性护身符所需的精神共鸣。",al={"如何组合坠饰碎片","在哪里融合坠饰碎片","雷姆洛斯神殿坠饰在哪里"}},{q="为什么德鲁伊必须平衡敏捷和耐力？",a="根据德迪利特·星焰的说法，在水下，敏捷和耐力单凭任何一种都无法有效发挥作用。没有耐力的快速移动会导致迅速精疲力竭，而没有迅捷的耐力则会使游泳者在强大的水流面前束手无策。对于任何试图完全体现海狮灵魂的德鲁伊来说，调和这两种特质至关重要。",al={"为什么需要敏捷与耐力","德鲁伊海狮特质","海狮试炼的意义"}},{q="完成试炼能获得什么？",a="完成海狮试炼可获得修复后的海狮坠饰，并完成获得水栖形态所需的主要试炼。通过证明对敏捷与耐力课程的掌握，受训者建立了变形为能够在水下呼吸和快速游动的生物所需的精神基础。",al={"完成海狮试炼能得到什么","海狮试炼奖励","这能给予水栖形态吗"}}},fp="21,210,24.398.0,21.373.0,21.372.0,34.228.0,42.224.0,41.281.0,37.254.0,50.144.0,46.274.0,39.259.0"}
P.entries["quest:273"] = {n="挖掘场的补给品",s="“补给挖掘场”是洛克莫丹的一个联盟任务，玩家需要在任务中追赶一车原本应运往铁环挖掘场的火药。玩家受吉恩·角盔之托去追赶这支运送小队，并沿着洛克湖的岸边道路前行。",h="“补给挖掘场”是洛克莫丹的一个联盟任务，玩家需要在任务中追赶一车原本应运往铁环挖掘场的火药。玩家受吉恩·角盔之托去追赶这支运送小队，并沿着洛克湖的岸边道路前行。",kw={"爆破火药","胡达尔","铁环","吉恩·角盔","洛克莫丹","米兰","补给挖掘场","saean","塞尔萨玛"},ang={["profession:Mining"]="在崎岖的地形上运送挥发性爆破火药本身就够危险了，再加上背叛，使得这批货物对南方的挖掘者来说至关重要。",["race:Dwarf"]="对于铜须矮人来说，保护这批爆破火药有助于在洛克莫丹道路充满危险的情况下，确保铁环挖掘场的工作能够持续进行。"},sec={{t="湖畔的沉重货物",b="位于洛克莫丹南部的铁环挖掘场需要持续供应爆破火药，以炸开挖掘现场坚硬的岩石。在火药被运抵塞尔萨玛后，当地的军需官吉恩·角盔安排了三名矮人——胡达尔、米兰和Saean——将这些危险的火药桶沿着湖边道路向南运送。由于货物沉重，运送小队行进缓慢，这让身在塞尔萨玛的旅行者有机会赶上他们，并在路上提供帮助。"},{t="阴影中的背叛",b="沿着南部的道路追上运货马车后，眼前所见的并非是一次例行的运送，而是一片混乱。这批货物遭到了黑铁矮人的伏击，他们一直在蓄意破坏铜须矮人的考古工作。比袭击本身更令人震惊的是随之揭露的背叛：与胡达尔一起工作了近一年的工人Saean被证实是黑铁矮人的同谋，他协助策划了这次伏击。"}},faq={{q="谁发放“补给挖掘场”这个任务？",a="在将火药带给吉恩·角盔后，他会在塞尔萨玛提供这个任务。他会让你沿着洛克湖边向南的道路走，去追上运送小队。",al={"谁发放补给挖掘场任务","补给挖掘场任务起始","补给挖掘场任务怎么接"}},{q="在哪里可以找到胡达尔和马车？",a="胡达尔和马车位于塞尔萨玛以南，顺着沿着洛克湖西侧和南侧弯道延伸、通往铁环挖掘场的道路前行即可找到。",al={"寻找胡达尔","胡达尔位置","洛克莫丹马车在哪里"}},{q="为什么要给铁环发送爆破火药？",a="勘察员基恩萨·铁环和他的团队正在南部挖掘场发掘古代遗物。他们需要爆破火药来炸碎坚硬的岩石并打通地层。",al={"为什么铁环需要火药","铁环爆破火药","为什么往挖掘场送火药"}},{q="是谁伏击了胡达尔的马车？",a="吉恩原本预计运送小队会在塞尔萨玛以南的正常道路上沿着洛克湖行进。当你找到胡达尔时，马车发生了什么真相大白。",al={"谁袭击了马车","洛克莫丹马车伏击","谁袭击了胡达尔"}},{q="Saean在袭击中扮演了什么角色？",a="Saean正与胡达尔和米兰一起运送沉重的爆破火药桶。当你赶上小队时，他在路上的所作所为就会揭晓。",al={"谁是saean","saean背叛","saean做了什么"}},{q="找到胡达尔后下一步是什么任务？",a="与胡达尔交谈可完成这段旅程。他关于这批货物的描述提供了下一步的线索。",al={"补给挖掘场之后是什么任务","胡达尔之后的任务"}}},fp="26,172,29.342.0,24.247.1,48.162.0,40.143.0,42.169.0,28.140.1,39.141.1,43.119.1"}
P.entries["quest:274"] = {n="水坝危机",s="在巨石水坝发现可疑粉末后，位于丹莫德的阿什兰·暗石确认该物质为不稳定的瑟银。如果接触到水，它会引发灾难性的破坏，这种粉末对该地区及附近的矮人领地构成了直接威胁。阿什兰·暗石调制出了一种拆弹胶质，并派人传信给主工程师辛德维尔七世，以便化解这场灾难。",h="在巨石水坝发现可疑粉末后，位于丹莫德的阿什兰·暗石确认该物质为不稳定的瑟银。如果接触到水，它会引发灾难性的破坏，这种粉末对该地区及附近的矮人领地构成了直接威胁。阿什兰·暗石调制出了一种拆弹胶质，并派人传信给主工程师辛德维...",kw={"阿什兰·暗石","爆炸粉末","主工程师辛德维尔七世","黑暗威胁逼近","拆弹胶质","铁炉堡","瑟银","湿地"},ang={["faction:Alliance"]="联盟的防御者必须迅速行动，协助主工程师辛德维尔七世并保护低地，以免敌方破坏者摧毁战略基础设施。",["profession:Engineering"]="工程学专家们会认出瑟银是一种极具威力的挥发性化合物，需要小心处理并采取精确的化学对策，以避免产生巨大的冲击波。",["race:Dwarf"]="对于卡兹莫丹的矮人来说，想到有破坏者在通往丹莫罗和铁炉堡的门口使用这种极不稳定的瑟银，简直是一种生存威胁。"},sec={{t="危险的发现",b="通过检查从巨石水坝带回的样本，阿什兰·暗石立刻辨认出那是瑟银特有的银色结晶，并闻到了它独特的气味。虽然在干燥条件下处于惰性状态，但瑟银一旦受潮就会发生剧烈反应——对于一座拦截着洛克莫丹水域的巨石水坝来说，这简直是噩梦。阿什兰警告说，这种化合物一旦发生失控爆炸，足以将铁炉堡从山中震飞。"},{t="与时间赛跑",b="为了对抗这种不稳定的爆炸物，阿什兰·暗石调制出了一种专门的拆弹胶质。中和这种反应需要一种特定的化学混合物：将这种胶质与潜伏者的毒液、研磨后的莫格罗什水晶以及鳄鱼的眼泪混合。时间紧迫，必须立刻警告主工程师辛德维尔七世，以免湿气引发灾难。"}},faq={{q="在水坝发现了什么种类的爆炸物？",a="阿什兰·暗石确认这种神秘物质是瑟银粉，其特征是明显的银色结晶和刺鼻的化学气味。",al={"这是什么粉末","这种粉末是什么","瑟银粉"}},{q="为什么瑟银在这里如此危险？",a="瑟银在保持干燥时相对无害，但一旦接触到水就会引发灾难性的爆炸。考虑到巨石水坝拦截着洛克莫丹的水域，这使其成为极度危险的地方。",al={"为什么瑟银很危险","什么会导致瑟银爆炸"}},{q="阿什兰·暗石是谁？",a="阿什兰·暗石是一位居住在湿地的联盟矮人专家，拥有分析神秘粉末和制作中和剂所需的工程学与化学专业知识。",al={"阿什兰是谁","阿什兰·暗石的身份"}},{q="主工程师辛德维尔七世是谁？",a="主工程师辛德维尔七世负责该地区的工程和防御事务，他在洛克莫丹的巨石水坝工作，负责维护和保卫矮人的基础设施。",al={"辛德维尔是谁","主工程师辛德维尔"}},{q="如何中和瑟银？",a="中和这种化学反应需要将阿什兰的拆弹胶质与三种稀有的当地材料混合：潜伏者的毒液、一颗研磨后的莫格罗什水晶和鳄鱼的眼泪。",al={"如何拆除瑟银","瑟银拆除配方","拆弹胶质配方"}},{q="对铁炉堡有什么危险？",a="阿什兰警告说，如果在周围的山脉系统中发生失控的爆炸，可能会导致灾难性的地震，足以将铁炉堡从山中震飞。",al={"铁炉堡有危险吗","铁炉堡受到什么威胁"}}},fp="19,208,20.261.0,16.261.1,44.122.0,35.210.0,25.179.0,37.163.0,37.142.0,32.148.0"}
P.entries["quest:2741"] = {n="超级测蛋器",s="克格尔·曲藤的最新发明是一台令人印象深刻的机器，当你靠近它的控制面板时，它疯狂地喷着火花。角鹰兽蛋会被放进里面。",h="克格尔·曲藤的最新发明是一台令人印象深刻的机器，当你靠近它的控制面板时，它疯狂地喷着火花。角鹰兽蛋会被放进里面。",kw={"克格尔·曲藤","蛋蛋机","测蛋仪","菲拉斯","角鹰兽蛋","塔纳利斯"},sec={{t="克格尔·曲藤的机器",b="克格尔·曲藤的最新发明看起来令人印象深刻。当你走到它的控制面板前时，它会疯狂地喷着火花。它是用来处理角鹰兽蛋的，这种蛋可以在菲拉斯南部的群山中，也就是伊斯迪尔废墟附近找到。"},{t="机器的作用",b="把一颗角鹰兽蛋放进去，机器就会发出一连串的蜂鸣声和奇怪的机械噪音。它的测蛋仪会称量并测量这颗蛋，然后迅速地将其打包。出来的东西是一个蛋箱，里面装着各种各样的蛋。"}},faq={{q="谁制造了超级蛋蛋机？",a="克格尔·曲藤，这是他的最新发明。",al={"谁制造了蛋蛋机","蛋蛋机的制造者","克格尔·曲藤的发明"}},{q="机器需要什么才能运行？",a="一颗角鹰兽蛋，你需要把它放进机器里。",al={"我应该给蛋蛋机什么","蛋蛋机所需的物品","角鹰兽蛋机器"}},{q="在哪里可以找到角鹰兽蛋？",a="在菲拉斯南部的群山中，也就是伊斯迪尔废墟附近。",al={"角鹰兽蛋位置","去哪里找角鹰兽蛋","菲拉斯的蛋在哪里"}}},fp="21,158,30.256.0,21.259.1,32.48.0,38.51.0,34.70.0"}
P.entries["quest:2742"] = {n="林吉被困住了！",s="林吉，一个巨魔，丢失了一把斧头并被困在奎尔丹尼小屋中，他恳求别人帮助他逃脱。林吉知道其他人可能不喜欢他这个种族，但他承诺会给予回报，并提到了隐藏在眺望台悬崖上的一个秘密。",h="林吉，一个巨魔，丢失了一把斧头并被困在奎尔丹尼小屋中，他恳求别人帮助他逃脱。林吉知道其他人可能不喜欢他这个种族，但他承诺会给予回报，并提到了隐藏在眺望台悬崖上的一个秘密。",kw={"俘虏","护送","辛特兰","眺望台悬崖","奎尔丹尼","林吉","石板"},sec={{t="逃脱的请求",b="林吉被囚禁在奎尔丹尼小屋中，惊恐万分。斧头不见了，林吉恳求路人帮助他逃离这里。林吉知道很多人不喜欢他这一族，但他愿意为帮助他的善良灵魂提供回报，并声称眺望台悬崖上隐藏着一个秘密。"},{t="逃脱的终点",b="等待着的是一块刻满奇怪符号的巨魔石板。上面的文字无法辨认。"}},faq={{q="谁是林吉？",a="林吉是一个巨魔，他丢失了一把斧头，并被俘虏在辛特兰的奎尔丹尼小屋中。林吉说话时喜欢用第三人称指代自己，并恳求他人帮助他逃脱。",al={"林吉","奎尔丹尼的巨魔是谁","谁是林吉"}},{q="林吉被关在哪里？",a="林吉被关押在辛特兰的奎尔丹尼小屋中。",al={"林吉在哪里","林吉的位置","奎尔丹尼牢笼"}},{q="林吉用什么作为帮助他的回报？",a="林吉为那些帮助他的人准备了回报，并声称眺望台悬崖上隐藏着一个秘密。",al={"林吉的秘密是什么","林吉的奖励","眺望台悬崖有什么"}}},fp="18,239,17.269.0,24.103.1,14.165.0,29.54.0,32.92.0"}
P.entries["quest:2745"] = {n="潜入城堡",s="奶酪商大师兼情报掮客埃林·提亚斯指引你进入Stormwind Keep的王室枢纽。你的目标是与他的同僚泰里恩会合，后者已经在城堡花园中暗中观察腐败的贵族格雷戈尔·雷斯科瓦男爵数周之久。",h="奶酪商大师兼情报掮客埃林·提亚斯指引你进入Stormwind Keep的王室枢纽。你的目标是与他的同僚泰里恩会合，后者已经在城堡花园中暗中观察腐败的贵族格雷戈尔·雷斯科瓦男爵数周之久。",kw={"奶酪店","迪菲亚潜行者","埃林·提亚斯","潜入城堡","雷斯科瓦","stormwind keep","泰里恩"},ang={["class:Rogue"]="潜入人类贵族的中心去协助两名经验丰富的地下特工，凸显了保护暴风城免受其内部宫廷阴影侵害所需的静默、致命的专业手段。",["faction:Alliance"]="随着瓦里安国王失踪，王国无法承受其最高立法机构中的背叛；清除Keep中的阴谋分子对于保持王国稳定至关重要。",["race:Gnome"]="看到泰里恩在Stormwind Keep内进行深入、长期的秘密监视行动，证明了侏儒的独创性不仅限于机械，还延伸到了高风险的间谍活动中。"},sec={{t="法外之事",b="当你把调查结果带给Trade District奶酪店里的埃林·提亚斯时，他迅速领会了深植于王国统治核心的迪菲亚潜行者威胁的严重性。法律途径不足以揭露或惩罚像格雷戈尔·雷斯科瓦男爵这样根基深厚且受到庇护的人。提亚斯提供了一条危险的道路：在Stormwind Keep的围墙内执行法外正义，以彻底切断这一阴谋。"},{t="灌木丛中的眼睛",b="提亚斯在高墙之内并非孤军奋战。数周以来，一名名为泰里恩的特工——一位擅长隐匿的聪明侏儒——一直在监视城堡的庭院和精心修剪的皇家花园。泰里恩观察着雷斯科瓦的一举一动，记录下谁进入了他的房间，以及这个叛徒何时与他秘密的迪菲亚潜行者联络人接头。在不引起皇家卫兵怀疑的情况下找到泰里恩，是行动链条中至关重要的下一步。"},{t="宫廷叛变",b="像雷斯科瓦这样地位显赫的贵族竟与“沉默之刃”马尔宗这样的迪菲亚潜行者刺客直接勾结，这凸显了在瓦里安·乌瑞恩国王缺席的情况下，暴风城的政治核心已经变得多么腐朽。随着宫廷贵族从内部操纵事务，以及不法之徒从西部荒野和赤脊山向边境施压，打击雷斯科瓦代表着在王国彻底崩溃之前切除这颗溃烂的毒瘤的尝试。"}},faq={{q="为什么埃林·提亚斯想要在法律之外处理这件事？",a="雷斯科瓦男爵在贵族议会中拥有巨大的影响力和财富。在没有确凿且具有政治毁灭性证据的情况下，对一位高阶男爵进行常规法律指控，很可能会导致证据被压制，而举报者被处决。提亚斯认识到，直接、隐秘的行动是消除这一威胁的唯一可靠途径。",al={"为什么在法律之外","提亚斯的法外正义","为什么要采取私刑"}},{q="泰里恩藏在哪里？",a="泰里恩藏身于Stormwind Keep的皇家花园中，穿过正门后，就在庭院左侧。他潜伏在灌木丛中，观察着雷斯科瓦男爵的住所，且没有惊动守卫。",al={"泰里恩在哪里","找到泰里恩","泰里恩的位置"}},{q="泰里恩是谁？",a="泰里恩是一名秘密特工，也是埃林·提亚斯值得信赖的伙伴。他已经在Stormwind Keep蹲守了数周，以监视格雷戈尔·雷斯科瓦男爵，并绘制他秘密的迪菲亚潜行者联络网。",al={"泰里恩是谁","侏儒泰里恩","提亚斯的朋友"}},{q="雷斯科瓦男爵是谁？",a="格雷戈尔·雷斯科瓦男爵是一位显赫的暴风城贵族，暗中与迪菲亚潜行者合作，充当他们身居高位的内部人员，从王室内部破坏王国。",al={"雷斯科瓦男爵","雷斯科瓦是谁","雷斯科瓦与迪菲亚潜行者"}},{q="马尔宗是谁？",a="马尔宗，又名“沉默之刃”，是一名精英迪菲亚潜行者刺客，他直接与雷斯科瓦男爵联络，代表兄弟会协调袭击和暗杀行动。",al={"马尔宗","沉默之刃马尔宗","沉默之刃"}},{q="为什么泰里恩担心他的名声？",a="除了在进行秘密监视时暴露身份之外，泰里恩还尖酸刻薄地抱怨说，让全副武装的冒险者在城堡卫兵的眼皮底下和他一起在皇家灌木丛中徘徊，看起来是多么可疑和不雅。",al={"泰里恩躲在灌木丛","灌木丛中的名声"}}},fx={ae2213ef={q="你在暴风城城堡要去对付谁？",a="埃林·提亚斯派你去处理Lord Gregor Lescovar和他的同伙Marzon。Lescovar是个贵族，在暴风城的Stormwind Keep内部活动，涉嫌叛国；Marzon则代表着城墙之外危险的阴谋集团。提亚斯和他的联络人泰里恩希望在两人的密谋威胁王国之前将他们一并铲除。",al={"我们要对付谁","潜入城堡的目标是谁","lescovar和marzon是谁"}},["7d59c2b3"]={q="为什么埃林·提亚斯派你去，而不是动用暴风城卫兵？",a="Lescovar勋爵是Stormwind Keep里的高级贵族，没有确凿证据，官方指控在政治上根本行不通。城卫军听命于宫廷，而贵族在宫廷中势力强大；若通知官方渠道，很可能会惊动Lescovar，或让此事陷入繁琐程序。提亚斯依靠一位独立的冒险者潜入其中、与泰里恩会合，并果断地伸张正义，不让阴谋者察觉。",al={"为什么派我去","为什么不告诉卫兵","为什么不找暴风城卫兵"}}},fp="23,152,24.337.0,21.349.0,20.354.1,56.312.0,23.203.0,14.185.0,21.183.0,14.162.1,43.223.0"}
P.entries["quest:2746"] = {n="必备物品",s="为了将他的机械间谍潜入Stormwind Keep并窃听Lescovar勋爵，秘密行动人员泰里恩需要一些非常特定的伪装材料。你必须提供精良的丝绸和清脆的果园苹果，以组装一个古怪的伪装身份，从而在不被察觉的情况下绕过皇家卫兵。",h="为了将他的机械间谍潜入Stormwind...",kw={"clara","埃林·提亚斯","潜入城堡","lescovar勋爵","丝绸布匹","spybot","stormwind keep","the attack","泰里恩"},ang={["class:Rogue"]="与泰里恩和埃林·提亚斯这样的行动人员并肩工作，突显了军情七处非传统的监视手段，并展示了国内情报部门是如何在贵族眼皮底下运作的。",["faction:Alliance"]="保护年轻的安度因国王和伯瓦尔·弗塔根公爵，需要铲除那些在Stormwind Keep内与法外之徒勾结的腐败贵族。",["profession:Tailoring"]="泰里恩的临时计划需要真正的丝绸布匹，这提醒裁缝们，精美的纺织品对于秘密阴谋来说，就像对于正式礼服一样至关重要。"},sec={{t="紧迫的日程",b="奶酪商人埃林·提亚斯传来的消息加快了针对Gregor Lescovar勋爵的行动。由于怀疑这位贵族在Stormwind Keep内的阴谋对王国构成了直接威胁，提亚斯坚持要求提前行动时间表。躲藏在Stormwind Keep花园里的泰里恩同意推进这一行动，但他坚持认为收集适当的渗透物资需要精心的准备。"},{t="伪装的艺术",b="泰里恩的计划依赖于一种非传统的资产：Spybot，一个小型的机械装置，旨在溜过警惕的城堡卫兵，到达Keep内的Lescovar身边。泰里恩没有依赖简单的潜行，而是构建了一个奇异的女性伪装来转移怀疑。为了完成这种伪装，他派遣行动人员前往城墙外Clara的果园寻找大小合适的苹果，同时要求用丝绸布匹来为这个傀儡剪裁服装。"},{t="揭露叛国罪",b="泰里恩透露，他最初对Lescovar勋爵的监视与迪菲亚潜行者根本没有联系，而是因为有可疑的线索将这位贵族与暮光之锤邪教联系在了一起。发现Lescovar正在积极与迪菲亚潜行者的阴谋家勾结，使得他继续留在皇家法庭已变得站不住脚，将一项常规的监视任务变成了王国心脏地带的一次高风险诱捕行动。"}},faq={{q="泰里恩为什么需要苹果和丝绸布匹？",a="泰里恩正在为他的机械侦察兵Spybot制作一种奇特的女性伪装，以便在不引起警报的情况下溜过Stormwind Keep的皇家卫兵。丝绸被剪裁成临时服装，而来自Clara农场的苹果则提供了完成这种幻象所需的确切形状。",al={"为什么需要苹果","苹果的用途","泰里恩的伪装材料","spybot伪装"}},{q="泰里恩为谁工作？",a="泰里恩与Trade District的奶酪商人埃林·提亚斯协同工作，后者在暴风城经营着自己的朋友网络；提亚斯承认，这次行动只是间接地帮了Mathias Shaw和军情七处一个忙。",al={"泰里恩向谁汇报","泰里恩的效忠对象","埃林·提亚斯与泰里恩"}},{q="我在哪里可以找到Clara的苹果？",a="Clara的农场位于艾尔文森林北部，就在暴风城的城门外。新鲜的苹果可以直接在她的简朴果园周围采集。",al={"clara的农场位置","clara的苹果在哪里","暴风城的新鲜苹果"}},{q="泰里恩最初怀疑Lescovar勋爵在做什么？",a="泰里恩和提亚斯最初追踪的线索表明，Lescovar勋爵与邪恶的暮光之锤邪教有联系。发现他与迪菲亚潜行者的合作证明，他的叛国罪行要深重得多，并且对王权构成了迫在眉睫的威胁。",al={"lescovar与暮光之锤","为什么要调查lescovar","泰里恩与lescovar的历史"}},{q="交付这些物品后的下一步是什么？",a="一旦Spybot装备齐全并被送入Keep，你将接到任务，在后续任务“The Attack!”中直接对抗并消灭这些阴谋家。",al={"接下来发生什么","完成“items of some consequence”之后","“items of some consequence”之后的后续任务"}},{q="为什么要使用机械间谍机器人而不是亲自潜入？",a="Stormwind Keep由皇家哨兵严密把守，他们会仔细盘查每一个进入王座大厅和私人庭院的人。Spybot伪装成一位女祭司，可以走过卫兵并直接与Lescovar交谈，把他引诱到花园里去见Marzon，而那里是任何已知特工都无法接近的地方。",al={"为什么要使用spybot","为什么不亲自潜入","stormwind keep的安保"}}},fp="25,175,21.275.0,23.313.0,18.324.1,43.180.0,26.195.0,31.126.0,58.208.1,51.132.1,62.252.0"}
P.entries["quest:2747"] = {n="特别的蛋",s="克格尔·曲藤很少见到菲拉斯出产的形状特别的蛋。这种蛋是所有蛋中最稀有的。",h="克格尔·曲藤很少见到菲拉斯出产的形状特别的蛋。这种蛋是所有蛋中最稀有的。",kw={"克格尔·曲藤","特别的蛋","菲拉斯","超级自动孵蛋器","塔纳利斯"},sec={{t="菲拉斯的珍品",b="克格尔·曲藤说，很少有蛋能以特别的形状从菲拉斯运出，而这些蛋是所有蛋中最稀有的。克格尔正在寻找的就是这种蛋。"}},faq={{q="谁在寻找特别的蛋？",a="克格尔·曲藤，他是超级自动孵蛋器的发明者。",al={"谁开启特别的蛋","谁给予特别的蛋任务","克格尔·曲藤 蛋"}},{q="这些特别的蛋来自哪里？",a="它们是从菲拉斯找回来的，但很少有形状特别的蛋。",al={"特别的蛋位置","在哪里找到特别的蛋","菲拉斯的蛋"}},{q="这个任务的前置任务是什么？",a="它承接自超级自动孵蛋器。",al={"特别的蛋前置条件","特别的蛋任务线","特别的蛋前置任务"}}},fp="20,110,21.174.0,40.64.0,44.76.0,31.33.0"}
P.entries["quest:2748"] = {n="优良的蛋",s="克格尔·曲藤谈到了那枚优良的蛋，它有很大机会在孵化时不受戈杜尼食人魔邪恶咒语的影响。",h="克格尔·曲藤谈到了那枚优良的蛋，它有很大机会在孵化时不受戈杜尼食人魔邪恶咒语的影响。",kw={"克格尔·曲藤","达纳苏斯","优良的蛋","戈杜尼","食人魔咒语","超级孵蛋器","塔纳利斯"},sec={{t="什么是优良的蛋",b="克格尔·曲藤将优良的蛋描述为在理想条件下，很有机会在孵化时不受戈杜尼食人魔邪恶咒语侵害的蛋。"},{t="克格尔接下来的计划",b="克格尔拿走了这枚蛋，并计划将它送到To Darnassus，希望它能很快孵化。"}},faq={{q="什么样的蛋会被认为是优良的蛋？",a="在理想条件下，它可以免受戈杜尼食人魔咒语带来的邪恶影响并顺利孵化。",al={"什么是优良的蛋","优良的蛋背景故事","为什么是优良的蛋"}},{q="这一步之前发生了什么？",a="它紧接在“超级孵蛋器”任务之后。",al={"优良的蛋前置条件","优良的蛋前置任务"}}},fp="10,122,18.163.0,21.98.1,40.90.0,27.33.0"}
P.entries["quest:2749"] = {n="普通的蛋",s="克格尔·曲藤在研究普通的角鹰兽蛋，这是一场赌博：大约有一半的蛋能孵化。克格尔精心照料它们，祈祷好运。",h="克格尔·曲藤在研究普通的角鹰兽蛋，这是一场赌博：大约有一半的蛋能孵化。克格尔精心照料它们，祈祷好运。",kw={"克格尔·曲藤","菲拉斯","角鹰兽","普通的蛋","塔纳利斯","超级蛋蛋自动机"},sec={{t="一半的机会",b="普通的角鹰兽蛋只有一半左右的孵化率。克格尔·曲藤尽其所能照料每一颗蛋，希望能有好运让它们孵化。"}},faq={{q="克格尔·曲藤是谁？",a="克格尔·曲藤是超级蛋蛋自动机的发明者，致力于研究在菲拉斯发现的角鹰兽蛋。",al={"克格尔是谁","克格尔·曲藤"}},{q="普通的角鹰兽蛋会发生什么？",a="克格尔会照料它并祈祷好运，因为这种蛋只有大约一半能孵化。",al={"克格尔怎么处理蛋","蛋的孵化几率"}},{q="这些蛋从哪来？",a="来自菲拉斯。",al={"我在哪里能找到蛋","普通的蛋位置"}},{q="这一步之前是什么？",a="在此任务之前是“超级蛋蛋自动机”。",al={"前置任务","上一个任务是什么"}}},fp="15,141,13.149.0,25.112.0,44.77.0,30.13.0,27.33.0"}
P.entries["quest:275"] = {n="大地上的脓疱",s="“土地上的脓疱”是绿色守卫者雷希耶尔在湿地东部山脊提供的一个联盟任务。这位孤独的沼泽兽守望者察觉到沼泽中正在酝酿一种非自然的疾病，于是委托旅行者清除潜伏在水道中的染病沼泽爬行者。平息这些蹒跚的植物怪物是雷希耶尔为了消除沼泽日益严重的“热病”所做的努力。",h="“土地上的脓疱”是绿色守卫者雷希耶尔在湿地东部山脊提供的一个联盟任务。这位孤独的沼泽兽守望者察觉到沼泽中正在酝酿一种非自然的疾病，于是委托旅行者清除潜伏在水道中的染病沼泽爬行者。平息这些蹒跚的植物怪物是雷希耶尔为了消除沼...",kw={"土地上的脓疱","沼泽爬行者","绿色守卫者","沼泽","雷希耶尔","湿地沼泽","湿地"},ang={["class:Druid"]="雷希耶尔的任务直接反映了德鲁伊治愈自然世界的职责，清除不安的元素疫病，使大地回归平衡。",["class:Shaman"]="沼泽爬行者代表了大地与水元素的扭曲表现，摧毁它们是一种平息不和谐元素之灵的行为。",["race:NightElf"]="在东部王国发现一头与暴风城结盟的孤独沼泽兽守望者，这表明即使是土地本身的灵魂也会寻求帮助，以呵护受创的土地。"},sec={{t="溃烂的沼泽",b="绿色守卫者雷希耶尔在沼泽中的树林里守护着湿地那片潮湿的广袤土地。这里的沼泽从来都不安宁，但最近一种非自然的疾病开始在泥沼中蔓延。雷希耶尔认为这种折磨是大地本身产生的一种日益严重的“热病”，导致野外的自然力量扭曲成了无意识的、蹒跚而行的怪物。"},{t="净化沼泽",b="这种腐烂的主要症状就是沼泽爬行者的出现——它们是沿着水道蹒跚而行的沼泽植被构成的腐烂元素聚合物。雷希耶尔将其描述为大地上肿胀的病态脓疱。由于它们被折磨的存在只会加剧沼泽的混乱，这位绿色守卫者要求过往的盟军将它们消灭，以便它们那纠结的残骸能重新无害地沉入泥土之中。"}},faq={{q="绿色守卫者雷希耶尔是谁？",a="绿色守卫者雷希耶尔是一头居住在湿地东部绿色守卫者之林的沼泽兽。它致力于照料沼泽地的自然平衡，寻求平复这片土地的苦难，并抑制腐化的元素生长。",al={"谁是雷希耶尔","绿色守卫者雷希耶尔背景故事","谁发布了土地上的脓疱任务"}},{q="什么是沼泽爬行者？",a="沼泽爬行者是徘徊在湿地水道中的敌对植物与沼泽元素生物。它们表现为由藤蔓、泥土和腐烂的沼泽植物构成的笨重、蹒跚的聚合体。",al={"沼泽爬行者","什么是沼泽爬行者","湿地爬行者"}},{q="为什么雷希耶尔想要消灭沼泽爬行者？",a="雷希耶尔将沼泽爬行者视为沼泽日益严重的疾病所产生的发热、病态的体现。它相信消灭它们可以让它们的形态消散并重新沉入大地，从而平复这片焦躁不安的土地。",al={"为什么要消灭沼泽爬行者","为什么会有土地上的脓疱任务"}},{q="是什么导致了湿地的溃烂？",a="雷希耶尔承认它并不完全了解是什么导致了湿地的溃烂在不断加剧。它只是感受到了这片土地悲伤的痛苦，并通过在Elemental Unrest涌现的任何地方安抚它们来治疗这些症状。",al={"为什么湿地会生病","湿地疾病的原因"}},{q="沼泽爬行者在湿地的什么地方？",a="沼泽爬行者游荡在湿地纵横交错的潮湿水道、泥泞岸边和中央河道中，尤其是在绿色守卫者之林以西的深层沼泽附近。",al={"沼泽爬行者位置","去哪里找沼泽爬行者"}},{q="这个任务与雷希耶尔的其他任务有关联吗？",a="是的。“土地上的脓疱”延续了雷希耶尔对苔藓皮豺狼人在“火之禁忌”任务中焚烧湿地树木的担忧，这是它为保护沼泽平衡所做努力的一部分。",al={"绿色守卫者任务线","雷希耶尔任务"}}},fp="20,178,19.249.0,17.281.0,31.211.0,22.169.0,49.184.0,42.149.0,45.143.0,51.148.0"}
P.entries["quest:2750"] = {n="坏掉的蛋",s="克格尔·曲藤谈到了那些无法挽救、永远无法孵化的蛋。",h="克格尔·曲藤谈到了那些无法挽救、永远无法孵化的蛋。",kw={"坏掉的蛋","克格尔·曲藤","菲拉斯","超级蛋蛋自动机","塔纳利斯"},sec={{t="无法挽救的蛋",b="有些角鹰兽蛋是无法挽救的，坏掉的蛋就是指那些永远无法孵化的蛋。克格尔·曲藤专门处理这类蛋。"},{t="它们的下场",b="克格尔会收走这些蛋，以便进行妥善处理。克格尔说，并不是每一枚蛋都能被挽救，你不应该因此气馁，而应该在菲拉斯寻找下一枚蛋再试一次。"}},faq={{q="谁会接收坏掉的蛋？",a="克格尔·曲藤。",al={"我该把坏掉的蛋交给谁","克格尔·曲藤 蛋","谁收坏掉的蛋"}},{q="这枚蛋还能挽救吗？",a="不能。坏掉的蛋是指那些无法挽救且永远无法孵化的蛋。",al={"坏掉的蛋能孵化吗","坏掉的蛋会孵化吗","挽救坏掉的蛋"}},{q="上一个任务是什么？",a="该任务紧随“超级蛋蛋自动机”之后。",al={"前置任务","前置需求","坏掉的蛋的前置任务"}}},fp="9,82,20.131.0,18.176.1,24.18.0,21.63.0,22.33.0"}
P.entries["quest:2751"] = {n="野人装甲",s="“野蛮战具”是奥罗克·沃姆什设立的初始考验。作为奥格瑞玛的一名年迈铁匠，他迫切想要保存自己家族的传承。由于没有后代，奥罗克要求任何想要学艺的铁匠展示出对青铜和基础锻造工艺的掌握，才会传授他的技艺秘诀。",h="“野蛮战具”是奥罗克·沃姆什设立的初始考验。作为奥格瑞玛的一名年迈铁匠，他迫切想要保存自己家族的传承。由于没有后代，奥罗克要求任何想要学艺的铁匠展示出对青铜和基础锻造工艺的掌握，才会传授他的技艺秘诀。",kw={"野蛮战具","锻造","青铜","遗产","沃姆什","奥格瑞玛","奥罗克·沃姆什"},ang={["faction:Horde"]="沃姆什的遗产反映了部落尚武的理念：金属制品注定要在战斗中经受考验，并浸透敌人的鲜血。",["profession:Blacksmithing"]="对于部落的铁匠来说，这项任务是从基础青铜和铜器制作转向中级护甲传统的重大里程碑。"},sec={{t="沃姆什家族的终结",b="奥罗克·沃姆什站在奥格瑞玛的铁砧旁，肩负着沉重的负担。二十代以来，他的家族一直在锻造炉前工作，将无数吨矿石塑造成致命的武器和坚固的护甲，供部落使用。可悲的是，由于没有亲人且无法生育后代，奥罗克认为自己是家族血脉的失败者。面对沃姆什锻造技艺即将彻底失传的困境，他决定抛开血统的傲慢，寻找一位能够将他家族的军械传统传承下去的学徒。"},{t="金属与利齿的考验",b="奥罗克拒绝将秘诀传给门外汉。为了证明在铁砧前的基本能力，他要求提供两件带花纹的青铜护腕、两把青铜巨剑，以及一对锋利的野兽爪子。对奥罗克来说，真正的锻造并非闲暇时的奢侈艺术；它最高的荣誉是看到护甲和钢铁沐浴在敌人的鲜血之中。满足他的要求会让这位老铁匠相信，他家族的遗产有望在精神上得以延续，从而开启通往更深奥金属加工技术的大门。"}},faq={{q="奥罗克·沃姆什是谁？",a="奥罗克·沃姆什是一位居住在奥格瑞玛的大师级铁匠。他是沃姆什家族的第二十代铁匠，但由于缺乏亲人或后代，他决心培养一位外人，而不愿让家族的商业机密就此消失。",al={"奥罗克·沃姆什","奥罗克是谁","沃姆什铁匠"}},{q="为什么奥罗克需要找别人来传授技艺？",a="奥罗克无法生育，也没有尚存于世的亲人来继承他的作坊。如果没有一个学徒来继承他的蓝图和技术，二十代人历尽艰辛获得的锻造知识将随他一同消亡。",al={"为什么需要学徒","奥罗克的继承人","为什么沃姆什遗产即将消亡"}},{q="向奥罗克证明能力需要什么物品？",a="奥罗克要求两件带花纹的青铜护腕、两把锻造的青铜巨剑，以及两只从凶猛掠食野兽身上取下的锋利爪子。",al={"野蛮战具需要什么","野蛮战具任务物品","野蛮战具交任务"}},{q="完成“野蛮战具”后接下来会发生什么？",a="对你掌握的基础青铜技艺感到满意后，奥罗克会继续指导你完成“铁质护肩”，向更沉重的铁质锻造和复杂的板甲制作迈进。",al={"下一个任务","野蛮战具后续任务链","接下来是什么"}}},fp="20,181,25.399.0,25.440.0,19.183.0,42.191.0,53.124.0,49.166.0"}
P.entries["quest:2753"] = {n="踩在脚下",s="“踏平敌阵”是一项由奥格瑞玛的荣誉谷中的奥罗克·沃姆什发布的进阶锻造试炼。通过打造一系列绿铁护甲，锻造师们可以证明自己的耐力并掌握重型铁靴的制作工艺。完成这项任务后，锻造师将获得沃姆什家族代代相传的秘密技巧。",h="“踏平敌阵”是一项由奥格瑞玛的荣誉谷中的奥罗克·沃姆什发布的进阶锻造试炼。通过打造一系列绿铁护甲，锻造师们可以证明自己的耐力并掌握重型铁靴的制作工艺。完成这项任务后，锻造师将获得沃姆什家族代代相传的秘密技巧。",kw={"护甲锻造","锻造","戈罗克","绿铁","奥格瑞玛","奥罗克·沃姆什","踏平敌阵","valley of honor"},ang={["faction:Horde"]="奥罗克的课程提供了经久耐用的铁质护甲图纸，专门针对部落战场上推崇的残酷战斗准则。",["profession:Blacksmithing"]="该任务是部落中志向远大的护甲铸造师的一个重要里程碑，需要进行大量的铁矿熔炼和绿染料准备工作，以解锁专属的靴子制作方案。"},sec={{t="沃姆什的试炼",b="奥罗克·沃姆什在奥格瑞玛训练护甲铸造师时有着严苛且繁重的体能要求。对奥罗克而言，金属加工不仅仅是加热矿石和锤炼形状；这是一项旨在向他的祖辈部族致敬的耐力测试。“踏平敌阵”是他一系列严苛任务中的第三次试炼，要求工匠反复锻造经久耐用的绿铁护甲，以磨练他们的肌肉与意志。"},{t="戈罗克酋长的遗产",b="向这位言辞粗鲁的护甲铸造师交付所需的绿铁装备的锻造师，会得到他难得的赞许。奥罗克将能承受这种艰苦工作量的工匠比作他的祖父，沃姆什的戈罗克酋长。作为交换，奥罗克将传授坚固铁靴的祖传设计图——这种鞋具旨在确保部落战士能将敌人的头颅踩在脚下。"}},faq={{q="谁发布了“踏平敌阵”任务？",a="该任务由奥罗克·沃姆什发布，他是一位位于奥格瑞玛荣誉谷的兽人护甲铸造师。",al={"任务发布者","谁发布了踏平敌阵","奥罗克·沃姆什位置"}},{q="奥罗克·沃姆什在这次试炼中需要什么？",a="奥罗克需要四个绿铁头盔、四个绿铁护腕和两个绿铁护腿，以此证明锻造师对绿铁工艺的掌握。",al={"踏平敌阵交任务","需要什么物品","所需材料"}},{q="沃姆什训练系列任务背后的故事是什么？",a="奥罗克·沃姆什通过惩罚性的体力劳动来考验年轻的锻造师，以发扬他祖先的尚武传统。他坚信艰苦的护甲锻造能锻炼出创造足以承受残酷战争的装备所需的实力。",al={"为什么奥罗克要让你锻造护甲","沃姆什氏族背景"}},{q="沃姆什的戈罗克酋长是谁？",a="沃姆什的戈罗克酋长是奥罗克·沃姆什的祖父。奥罗克对他祖父的武勇极为推崇，会将任何能坚持完成他沉重铁器锻造试炼的锻造师与这位传奇酋长相提并论。",al={"戈罗克酋长","奥罗克祖父"}},{q="“踏平敌阵”的前置任务是什么？",a="“踏平敌阵”直接承接自任务“铁质护肩”，它是奥罗克的一系列多阶段护甲锻造挑战的一部分。",al={"前置任务","系列任务中的前一个任务"}},{q="完成“踏平敌阵”后的下一个任务是什么？",a="完成这项任务后，奥罗克·沃姆什会提供“狂乱之角”，这是在他以“沃姆什的喜悦”终结这一系列任务前，剩下的两个课程中的下一个。",al={"下一个任务","踏平敌阵之后是什么"}}},fp="19,241,19.331.0,22.336.0,41.80.0,45.168.0,49.208.0,29.173.0,40.88.0,60.116.0"}
P.entries["quest:2755"] = {n="沃姆什的喜悦",s="“沃姆什的喜悦”是铁匠奥罗克·沃姆什与一位曾在奥格瑞玛帮助过他的The Adventurer之间一个温馨的告别时刻。这位老兵铁匠感动得热泪盈眶，但他坚称只是眼睛进了煤灰，随后便展示了一项珍贵的家族传统。通过表演那充满活力的沃姆什喜悦之舞，他传承了一段不同寻常的家族遗产。",h="“沃姆什的喜悦”是铁匠奥罗克·沃姆什与一位曾在奥格瑞玛帮助过他的The...",kw={"铁匠","喜悦之舞","沃姆什的喜悦","奥格瑞玛","奥罗克·沃姆什","眼睛进煤灰","valley of honor"},ang={["faction:Horde"]="Valley of Honor是武勇之心的汇聚之地，这使得奥罗克含泪的喜悦和充满激情的舞蹈在奥格瑞玛的兵戈交鸣声中显得格外动人。",["profession:Blacksmithing"]="对于习惯了熔炉那严酷、冷峻高温的铁匠来说，奥罗克这种充满情感的家族舞蹈，为这位老兵工匠的个人生活提供了一个既幽默又温柔的视角。"},sec={{t="被煤灰染色的泪水",b="奥罗克·沃姆什是一位魁梧的铁匠，在奥格瑞玛炙热的熔炉旁工作，比起情感流露，他更以在铁砧上敲打出的沉重撞击声而闻名。然而，在得到The Adventurer的巨大帮助后，这位硬汉工匠也不禁深感触动。他固执地坚持说是一粒煤灰掉进了眼睛里，而不愿承认自己在公开流泪。"},{t="沃姆什的传统",b="奥罗克不愿就这样安静地道别，他坚持要在离开人世前分享沃姆什血脉的最后一个秘密。他立刻跳起了充满活力且令人筋疲力尽的沃姆什喜悦之舞，为他的学徒展示了这项生动的传统，随后教导他们如何用铁拳进行打击。"}},faq={{q="谁是奥罗克·沃姆什？",a="奥罗克·沃姆什是一位位于奥格瑞玛Valley of Honor的兽人铁匠。他对自己家族的技艺和血脉感到无比自豪，并将打铁专长与生动的个人传统融为一体。",al={"奥罗克是谁","奥罗克·沃姆什背景故事","铁匠奥罗克"}},{q="奥罗克为什么在哭？",a="奥罗克坚称他没有哭，只是熔炉里的煤灰掉进了眼睛里。事实上，他被The Adventurer的帮助深深打动了，因为他终于找到了一个值得分享其家族传统的人。",al={"奥罗克为什么哭","奥罗克伤心吗","眼睛进煤灰"}},{q="什么是沃姆什喜悦之舞？",a="喜悦之舞是一套在沃姆什家族中代代相传的剧烈肢体动作。对于已经很久没有练习过这种庆祝舞蹈的奥罗克来说，表演它非常消耗体力。",al={"沃姆什之舞","喜悦之舞","什么是舞蹈"}},{q="这个任务发生在哪里？",a="该任务发生在奥格瑞玛，具体是在Valley of Honor的铁匠炉附近，奥罗克·沃姆什在那里进行金属加工。",al={"任务地点","沃姆什的喜悦在哪里","奥格瑞玛熔炉"}},{q="奥罗克教你什么？",a="除了展示那充满活力的沃姆什喜悦之舞外，奥罗克还承诺传授铁拳的知识，以巩固铁匠与The Adventurer之间的纽带。",al={"沃姆什奖励","我学到了什么","铁拳"}},{q="联盟玩家可以参与这个任务吗？",a="不能。奥罗克·沃姆什效忠于部落，居住在奥格瑞玛的城墙内，这使得该互动仅限于部落的The Adventurer。",al={"联盟沃姆什的喜悦","这是部落专属吗"}}},fp="13,226,19.262.0,19.211.0,19.173.0,20.149.0,31.157.0,33.117.0,26.129.0,47.132.0"}
P.entries["quest:276"] = {n="践踏之爪",s="“践踏之爪”是一项由绿色守卫者雷希耶尔在湿地的绿色守卫者树林发放的联盟任务。沼泽兽守护者被奥加兹之门附近激增的苔藓沼泽豺狼人数量所困扰，他委托冒险者在这些豺狼人的营火和践踏之爪摧毁沼泽之前，将它们清理干净。",h="“践踏之爪”是一项由绿色守卫者雷希耶尔在湿地的绿色守卫者树林发放的联盟任务。沼泽兽守护者被奥加兹之门附近激增的苔藓沼泽豺狼人数量所困扰，他委托冒险者在这些豺狼人的营火和践踏之爪摧毁沼泽之前，将它们清理干净。",kw={"奥加兹","豺狼人","绿色守卫者","杂种狗头人","苔藓沼泽","雷希耶尔","践踏之爪","湿地"},ang={["class:Druid"]="雷希耶尔的使命直接反映了塞纳里奥议会维持生态平衡的宗旨，即剔除不自然的种群高峰，以确保沼泽不会崩溃。",["race:Dwarf"]="随着豺狼人在奥加兹之门外直接肆虐，清理它们不仅保护了沼泽，还确保了连接铁炉堡和米奈希尔港的重要道路的安全。",["race:NightElf"]="暗夜精灵与荒野的自然之灵有着祖传的联系，这使得雷希耶尔提出的治愈沼泽的请求成为一项令人熟悉且倍感荣幸的职责。"},sec={{t="膨胀的沼泽威胁",b="多年来，苔藓沼泽豺狼人一直栖息在湿地，并没有彻底破坏其自然秩序。然而最近，它们的族群数量却向南爆发式增长，直逼丹奥加兹山口。它们沉重的靴子和爪印践踏了稀有的沼泽植物，粗糙的伐木行为剥去了维持营地火堆所需的关键树林。如果任其发展，这些不断壮大的族群将威胁到脆弱的沼泽生态系统，使其退化。"},{t="绿色守卫者的审判",b="绿色守卫者雷希耶尔以平衡而非文明的视角审视着这片沼泽。对于绿色守卫者来说，问题不在于豺狼人的存在，而在于它们失控的种群数量超出了湿地的承载能力。通过将苔藓沼泽豺狼人和杂种狗头人驱赶回可控的数量，冒险者有助于保护湿地，并赢得这位古老荒野守护者勉强的认可。"}},faq={{q="绿色守卫者雷希耶尔是谁？",a="雷希耶尔是一头居住在铁炉堡边境与阿拉希之间湿地道路上的沼泽兽。它致力于保护沼泽，监控着这片土地的健康状况，并委托旅行者控制破坏性的种群数量。",al={"雷希耶尔背景故事","谁发放践踏之爪","绿色守卫者湿地"}},{q="为什么苔藓沼泽豺狼人现在成了问题？",a="虽然苔藓沼泽部族曾经与沼泽共存且未造成长期损害，但它们最近的人口激增导致了大量的森林砍伐以获取木柴，以及对脆弱沼泽植物的大规模践踏。",al={"为什么要在湿地击杀豺狼人","苔藓沼泽豺狼人威胁"}},{q="豺狼人在哪里造成了这种破坏？",a="苔藓沼泽豺狼人和杂种狗头人在湿地南部大量聚集，尤其是在矮人的丹奥加兹山口附近。",al={"苔藓沼泽豺狼人在哪里","践踏之爪位置"}},{q="清理豺狼人之后会发生什么？",a="一旦族群数量减少，雷希耶尔会深入调查它们异常活动和燃料消耗的根源，并派遣冒险者去完成后续任务“禁火”。",al={"践踏之爪后续任务","践踏之爪后续"}},{q="为什么雷希耶尔提到它的信仰受到了考验？",a="雷希耶尔告诉你，它对你们种族的信仰在过去曾受到考验，它对凡人及其快速扩张持谨慎态度。帮助它保护荒野沼泽证明了凡人冒险者可以成为自然的管家，而不是掠夺者。",al={"雷希耶尔对话","过去的信仰考验"}}},fp="13,197,21.320.0,26.287.0,31.233.0,42.194.0,41.125.0,36.135.1,49.215.0"}
P.entries["quest:2766"] = {n="寻找OOX-22/FE！",s="你发现了一个奇怪的蛋状金属装置。里面的声音自我介绍为奥格索普·奥布诺提斯，他的归航机器人坠毁了。他请求你将信标带到位于深痕谷附近山洞中的机器那里。",h="你发现了一个奇怪的蛋状金属装置。里面的声音自我介绍为奥格索普·奥布诺提斯，他的归航机器人坠毁了。他请求你将信标带到位于深痕谷附近山洞中的机器那里。",kw={"求救信标","深痕谷","菲拉斯","归航机器人","机械鸡","奥格索普·奥布诺提斯","oox-22/fe"},sec={{t="蛋里的声音",b="摆弄一番旋钮后，金属蛋弹开，变成了一台侏儒机械装置，里面传出了噼啪作响的声音。奥格索普·奥布诺提斯说归航机器人坠毁了，并承诺如果你能找回它就给予报酬。信标必须带给机器人，奥格索普已经计算出了它的位置：深痕谷附近的一个山洞。"},{t="山洞里有什么",b="在山洞里，你发现了一堆看起来像机器鸡的残骸。奥格索普的声音确认那就是他的归航机器人，并说必须在它飞往藏宝海湾修理前先进行跨接启动。将信标放入其中后，机器人开始嗡嗡作响并恢复了活力，奥格索普的声音随之直接从机器人身上传了出来。"}},faq={{q="是谁在通过求救信标说话？",a="奥格索普·奥布诺提斯。他的归航机器人坠毁了，他请求你将信标带给它。",al={"谁制造了信标","谁在说话","奥格索普是谁"}},{q="信标指引你去哪里？",a="奥格索普已经计算出了机器人的坐标，它位于菲拉斯深痕谷旁边的一个山洞里。",al={"机器人在哪里","归航机器人位置","把信标带到哪里"}},{q="信标是什么？",a="一个奇怪的蛋状金属装置。当你摆弄旋钮时，它会展开成一台侏儒机械装置，里面会传出声音。",al={"蛋是什么","什么是oox-22/fe","求救信标"}},{q="这一步之后是什么？",a="接下来是“救援OOX-22/FE！”。",al={"后续任务","“找到oox-22/fe！”之后是什么","山洞之后"}}},fp="15,243,18.333.0,19.307.1,44.94.0,38.101.0,19.142.0,27.26.0"}
P.entries["quest:2767"] = {n="拯救OOX-22/FE！",s="在深痕谷发现归航机器人OOX-22/FE之后，你再次听到了那个侏儒从机器人里传出的噼啪声。这个机器人需要被护送到被遗忘的海岸码头，之后奥格索普·奥布诺提斯想在藏宝海湾与你谈谈。",h="在深痕谷发现归航机器人OOX-22/FE之后，你再次听到了那个侏儒从机器人里传出的噼啪声。这个机器人需要被护送到被遗忘的海岸码头，之后奥格索普·奥布诺提斯想在藏宝海湾与你谈谈。",kw={"藏宝海湾","深痕谷","菲拉斯","被遗忘的海岸","归航机器人","奥格索普·奥布诺提斯","oox-22/fe","机器鸡"},sec={{t="一个安全的起飞地点",b="那个侏儒的声音说，OOX-22/FE需要一个开阔且安全的地方，以便开始漫长的起飞过程。机器人内置了隐形装置，但奥格索普·奥布诺提斯需要时间让它重新工作。奥格索普建议使用被遗忘的海岸码头，那里足够长，可以完成所有启动工作，因此需要将机器人从它所在的位置护送到那里。"},{t="事后，前往藏宝海湾",b="一旦机器人安全到达码头，奥格索普·奥布诺提斯希望你去藏宝海湾找他谈谈。"}},faq={{q="OOX-22/FE需要去哪里？",a="被遗忘的海岸码头。它需要从你发现它的深痕谷被护送到那里。",al={"我该把这只鸡带到哪里","oox-22/fe的目的地","菲拉斯护送小鸡路线"}},{q="奥格索普·奥布诺提斯是谁？",a="一位发明大师，他的归航机器人系列包括OOX-22/FE。奥格索普通过机器人进行交流，你可以在藏宝海湾找到他。",al={"是谁制造了机器鸡","奥格索普·奥布诺提斯是谁","小鸡发明者"}},{q="为什么机器人需要到达码头？",a="漫长的起飞过程需要一个开阔、安全的地方，奥格索普说码头足够长，可以完成启动工作。机器人的内置隐形功能需要时间才能重新工作。",al={"为什么要护送oox-22","为什么要走去码头"}},{q="事后我该去哪里报告？",a="一旦机器人安全到达码头，就去藏宝海湾找奥格索普·奥布诺提斯谈话。",al={"奥格索普在哪里","交任务地点","之后我该和谁谈话"}}},fp="17,243,24.337.0,21.99.0,32.98.0,28.126.0,42.175.0,29.81.0"}
P.entries["quest:277"] = {n="火焰管制",s="“火的禁忌”是绿色守卫者雷希耶尔在湿地泥泞道路上布置的一项任务。这只沼泽兽深受当地森林痛苦的折磨，因此派遣旅行者去剥夺苔皮豺狼人手中的粗制打火石，这些豺狼人利用它们来点燃并焚烧活木。通过让豺狼人无法取火，雷希耶尔希望保护沼泽中那些古老的枝干免遭吞噬。",h="“火的禁忌”是绿色守卫者雷希耶尔在湿地泥泞道路上布置的一项任务。这只沼泽兽深受当地森林痛苦的折磨，因此派遣旅行者去剥夺苔皮豺狼人手中的粗制打火石，这些豺狼人利用它们来点燃并焚烧活木。通过让豺狼人无法取火，雷希耶尔希望保护...",kw={"粗制打火石","火的禁忌","豺狼人","绿色守卫者","活木","苔皮部族","雷希耶尔","湿地"},ang={["class:Druid"]="作为荒野的守护者，德鲁伊与雷希耶尔有着同样的对树木的敬畏之心，也理解活木被豺狼人的火坑折磨时那种非自然痛苦。",["faction:Alliance"]="苔皮豺狼人威胁着经过湿地的旅行者；帮助当地的灵魂有助于确保连接丹莫罗和阿拉希的贸易路线安全。",["race:NightElf"]="暗夜精灵可能会在雷希耶尔这只感同身受湿地苦难的沼泽兽身上，认出一位活木的同道守护者。"},sec={{t="绿色守卫者的痛苦",b="绿色守卫者雷希耶尔守护着湿地的荒野，与沼泽的树木保持着深厚的精神羁绊。虽然腐烂与新生的自然循环是沼泽的一部分，但这种蓄意的伐木行为深深刺痛了雷希耶尔的灵魂。对于一个活着的沼泽之灵来说，听到活生生的枝干被砍倒并投入炉火中发出的呻吟，是雷希耶尔无法再默默承受的折磨。"},{t="扑灭苔皮豺狼人的火种",b="苔皮部落为了取暖和争夺领地，在湿地横行霸道，他们砍伐的是青翠的活树，而不是收集枯木。为了在不陷入持久消耗战的情况下遏制他们的扩张，雷希耶尔将目标对准了他们破坏的核心工具：那些强壮的豺狼人所使用的粗制打火石。通过剥夺部落的生火工具，雷希耶尔使他们无法再焚烧砍下的木材。雷希耶尔会亲自粉碎收集到的每一块石头，并将粉末撒入海中，确保这些火星永远不会再次点燃森林。"}},faq={{q="谁是绿色守卫者雷希耶尔？",a="绿色守卫者雷希耶尔是一只居住在湿地的沼泽兽。雷希耶尔与当地树木和植物的生命力紧密相连，寻求保护受伤的沼泽免受苔皮豺狼人的蹂躏。",al={"谁是雷希耶尔","绿色守卫者雷希耶尔背景故事","谁发布火的禁忌"}},{q="为什么雷希耶尔想要粗制打火石而不是杀死豺狼人首领？",a="雷希耶尔认为焚烧活木是不可原谅的亵渎。通过夺走打火石，雷希耶尔直接阻止了豺狼人点火烧毁湿地的树木，从而瘫痪了他们的营地，终结了对活木的破坏。",al={"为什么需要打火石","为什么要夺走打火石","粗制打火石的用途"}},{q="打火石上交后会发生什么？",a="雷希耶尔会将粗制打火石砸得粉碎，并将残渣撒入海中，这样它们就再也不能被用来敲击产生火星去对付活木了。",al={"她如何处理打火石","毁掉打火石"}},{q="哪些豺狼人携带打火石？",a="苔皮部落中更强壮的成员携带粗制打火石。较小的苔皮豺狼人和较弱的杂种由于不被信任而没有生火工具，因此也不会携带它们。",al={"谁掉落打火石","哪些豺狼人持有粗制打火石"}},{q="为什么苔皮豺狼人要砍伐树木？",a="苔皮豺狼人砍伐活树是为了供给篝火，在潮湿的沼泽中取暖，而不是依赖干燥的枯木。",al={"为什么豺狼人砍伐树木","苔皮部族伐木"}},{q="收集打火石后的下一步是什么？",a="在你剥夺了豺狼人的火种后，雷希耶尔会派你去处理困扰沼泽的另一种枯萎病，相关后续任务为“土地上的脓包”。",al={"火的禁忌后的任务","交完打火石后的下一步任务"}}},fp="10,232,23.270.0,27.390.0,31.177.0,72.184.0,51.117.0,30.145.0,41.129.0,43.166.1"}
P.entries["quest:278"] = {n="水坝危机",s="这项任务是保卫巨石水坝免受黑铁矮人阴谋破坏的关键一步。主工程师辛德维尔七世委托冒险者从洛克莫丹各地收集稀有的化学和有机试剂，用以调配一种拆除混合剂。如果没有这些成分，防御者将无法中和埋设在巨大石造建筑下的炸药。",h="这项任务是保卫巨石水坝免受黑铁矮人阴谋破坏的关键一步。主工程师辛德维尔七世委托冒险者从洛克莫丹各地收集稀有的化学和有机试剂，用以调配一种拆除混合剂。如果没有这些成分，防御者将无法中和埋设在巨大石造建筑下的炸药。",kw={"鳄鱼的眼泪","黑铁矮人","辛德维尔","洛克莫丹","潜伏者的毒液","莫格罗什水晶","巨石水坝"},ang={["faction:Alliance"]="如果未能消除针对大坝的威胁，将导致灾难性的后果，切断连接铁炉堡与北方王国的关键陆路补给线。",["profession:Engineering"]="工程师们很欣赏辛德维尔的聪明才智，他能配制出一种能够在现场稳定不稳定爆破装置的化学中和剂。",["race:Dwarf"]="对于卡兹莫丹的矮人来说，在巨石水坝阻止黑铁矮人的破坏行动，是保护他们祖传土地和建筑成就的一项神圣职责。"},sec={{t="不稳定的配方",b="为了对抗黑铁矮人破坏者使用的高挥发性爆炸混合物，主工程师辛德维尔七世依靠一种非传统的化学中和剂。中和黑铁爆破粉末所需的并非简单的水或潮湿的沙子，而是一种由当地的潜伏者毒液、从洛克湖栖息的鳄鱼身上提取的眼泪以及莫格罗什水晶制成的强效泥浆。每种成分都带有独特的反应特性，对于使矮人的爆破装置完全失效至关重要。"},{t="危险的收集工作",b="获取这些配料将冒险者带到了洛克莫丹最危险的角落。虽然潜伏者蜘蛛和洛克湖的鳄鱼构成了普通的自然威胁，但获取莫格罗什水晶则需要深入东北部山区的食人魔据点。莫格罗什食人魔嫉妒地守卫着这些稀有的开采矿石，迫使任何想要保护大坝的人必须杀出重重包围，才能获得样本。"}},faq={{q="为什么辛德维尔工程师需要这些特定的试剂？",a="主工程师辛德维尔七世正在调配一种专门的中和化合物，以拆除黑铁矮人的爆炸物。腐蚀性的潜伏者毒液、鳄鱼分泌物以及莫格罗什水晶中发现的魔法矿物，提供了使高级破坏者装置失效所需的精确化学反应。",al={"为什么要蜘蛛毒液","为什么要鳄鱼眼泪","拆除混合剂试剂"}},{q="莫格罗什水晶来自哪里？",a="这些水晶是由占据洛克莫丹东北部山区的莫格罗什食人魔开采并囤积的。因为它们被食人魔视为一种稀有且有价值的商品，所以获取一颗水晶需要冒险进入他们戒备森严的领地。",al={"水晶在哪里","莫格罗什水晶位置","谁有水晶"}},{q="威胁洛克莫丹的黑暗威胁是什么？",a="这种威胁源于企图摧毁巨石水坝的黑铁矮人渗透者。摧毁这一伟大的工程奇迹将淹没下方的湿地，切断联盟的补给线，并对该地区造成毁灭性打击。",al={"什么是黑暗威胁","谁在攻击大坝","黑暗威胁笼罩故事"}},{q="主工程师辛德维尔七世是谁？",a="他是负责监督巨石水坝运作和完整性的矮人总工程师。他负责协调结构的维护和针对破坏活动的当地防御工作。",al={"辛德维尔是谁","主工程师辛德维尔"}},{q="在哪里可以找到这些本地生物？",a="潜伏者蜘蛛在山谷周围的森林荒野中游荡，而鳄鱼则栖息在洛克湖的湖畔及其周边区域。",al={"潜伏者在哪里","鳄鱼位置","去哪里找蜘蛛"}},{q="为什么铁炉堡的卫兵不亲自收集这些物品？",a="登山者和当地卫兵在保卫塞尔萨玛等城镇以及监视黑铁侦察兵方面已经捉襟见肘。专门的采购任务和突袭食人魔领地的行动通常会委托给有能力的旅行冒险者。",al={"为什么要帮助辛德维尔","铁炉堡卫兵在哪里"}}},fp="19,199,17.237.0,18.259.0,58.232.0,37.145.0,44.167.0,37.179.0,44.116.0,61.193.0"}
P.entries["quest:2781"] = {n="通缉：卡利夫·斯科比斯汀",s="加基森水业公司为卡利夫·斯科比德悬赏，此人是沙漠流浪者不法之徒的首领。击杀证明需呈交给加基森的首席工程师沙克斯·比格维兹。",h="加基森水业公司为卡利夫·斯科比德悬赏，此人是沙漠流浪者不法之徒的首领。击杀证明需呈交给加基森的首席工程师沙克斯·比格维兹。",kw={"悬赏","卡利夫·斯科比德","首席工程师沙克斯·比格维兹","加基森","加基森水业公司","热砂港","塔纳利斯","沙漠流浪者"},sec={{t="公司的指控",b="在加基森和热砂港的布告栏上张贴着加基森水业公司发布的高额悬赏，目标是沙漠流浪者不法之徒的首领卡利夫·斯科比德。针对他的指控包括谋杀公司员工、盗窃公司资源以及侵占公司财产。击杀证明需呈交给加基森的首席工程师沙克斯·比格维兹。"},{t="水业公司的期冀",b="首席工程师沙克斯·比格维兹称斯科比德的死是正义的伸张，也是对沙漠流浪者的一记重击，这位工程师称他们为卑劣的游牧民和非法侵占者。公司希望此举能最终将他们从加基森的水井旁赶走，赏金将代表公司支付。"}},faq={{q="谁是卡利夫·斯科比德？",a="他是沙漠流浪者不法之徒的首领，也是加基森水业公司的通缉目标。",al={"卡利夫·斯科比德背景故事","谁领导沙漠流浪者","斯科比德"}},{q="为什么加基森水业公司想要他死？",a="公司指控他谋杀其员工、盗窃其资源并侵占其财产。",al={"为何悬赏斯科比德","卡利夫·斯科比德罪行","加基森水业公司敌人"}},{q="谁支付了卡利夫·斯科比德的赏金？",a="加基森的加基森水业公司首席工程师沙克斯·比格维兹负责接收斯科比德的击杀证明。",al={"谁负责接收斯科比德悬赏","卡利夫的头颅在哪上交","比格维兹悬赏"}},{q="通缉令张贴在哪里？",a="在加基森和热砂港。",al={"卡利夫通缉令位置","哪里领取卡利夫悬赏","斯科比德公告"}}},fp="27,170,21.360.0,32.284.1,27.72.0,51.100.0,44.110.0,37.38.0"}
P.entries["quest:2782"] = {n="林吉的秘密",s="在帮助了林吉之后，你拿到了一块刻有枯木巨魔标记的石板，至今没人能读懂。奥兰·斯内克威瑟是枯木巨魔的研究者，也许能解读它，他住在幽暗城的魔法区。",h="在帮助了林吉之后，你拿到了一块刻有枯木巨魔标记的石板，至今没人能读懂。奥兰·斯内克威瑟是枯木巨魔的研究者，也许能解读它，他住在幽暗城的魔法区。",kw={"辛特兰","magic quarter","奥兰·斯内克威瑟","林吉","石板","幽暗城","枯木"},sec={{t="一块没人能读懂的石板",b="石板上刻满了枯木巨魔的标记，林吉的秘密究竟是什么仍然是个谜。它可能价值连城，也可能一文不值，因为一个陷入困境的枯木巨魔很可能会不惜一切代价脱身。"},{t="幽暗城的学者",b="奥兰·斯内克威瑟是一位著名的枯木巨魔学者，据说住在幽暗城的魔法区。奥兰或许能读懂这块石板。"}},faq={{q="这块石板是从哪里来的？",a="这是林吉藏在眺望台的秘密，是在帮助林吉从奎尔丹尼小屋逃脱后找到的。",al={"林吉石板来源","如何获得石板"}},{q="谁能读懂石板上的标记？",a="奥兰·斯内克威瑟，一位非常了解枯木巨魔的学者，或许能够解读它。",al={"谁能解读石板","谁能读懂枯木标记"}},{q="奥兰·斯内克威瑟在哪里？",a="据了解，奥兰住在幽暗城的魔法区。",al={"奥兰·斯内克威瑟位置","奥兰在哪里"}},{q="这块石板有价值吗？",a="没人说得准。它可能价值连城，也可能一文不值，因为一个陷入困境的枯木巨魔可能会尝试任何方法来摆脱麻烦。",al={"林吉的秘密是什么","石板含义"}}},fp="15,227,24.201.0,26.160.0,32.123.0,40.91.0,34.72.0,23.146.0"}
P.entries["quest:280"] = {n="水坝危机",s="这是一个由主工程师辛德维尔七世发布的紧急任务，目的在于阻止巨石水坝被毁。黑铁破坏者们在水面之下深处安置了一枚瑟福瑞姆炸药，威胁要摧毁这座矮人王国最伟大的工程奇迹之一。",h="这是一个由主工程师辛德维尔七世发布的紧急任务，目的在于阻止巨石水坝被毁。黑铁破坏者们在水面之下深处安置了一枚瑟福瑞姆炸药，威胁要摧毁这座矮人王国最伟大的工程奇迹之一。",kw={"水坝","黑铁","拆除","爆炸物","辛德维尔","暴乱分子","桶","瑟福瑞姆","巨石"},ang={["faction:Alliance"]="巨石水坝的毁灭将摧毁连接卡兹莫丹与北方联盟领地的关键交通路线。",["profession:Engineering"]="直接使用瑟福瑞姆和专业的拆弹化学制剂，突显了爆破与反爆炸化学应用在极端情况下的高风险性。",["race:Dwarf"]="巨石水坝是矮人建筑和荣耀的永恒丰碑；保护它免受黑铁矮人的背叛，对铁炉堡的每一位儿女来说都至关重要。",["race:Gnome"]="侏儒的头脑不仅能理解辛德维尔中和剂背后的复杂化学原理，也能预见到瑟福瑞姆爆炸对矮人工程学造成的恐怖破坏。"},sec={{t="水面下的破坏",b="主工程师辛德维尔七世发现了黑铁暴乱分子正游向巨石水坝的底部，他们携带这一大桶名为瑟福瑞姆的烈性炸药。由于附近没有山地探险队员可以干预，这些渗透者直接将武器安装在了水坝的水下基座上。一旦水坝决堤，洛克湖中全部的蓄水就会倾泻到下方的低地，引发灾难性的洪水，并将瘫痪整个地区的矮人贸易与交通。"},{t="不稳定的中和剂",b="辛德维尔迅速将活性成分配制成了一种拆弹剂，并派出一名勇敢的潜水员径直前往水下的炸弹处。想要中和瑟福瑞姆，就需要旋开水下的炸药桶，并将这种化学溶液直接搅拌进炸药粉末中。混合物发出轻柔的水下嘶嘶声，从而让倒计时停止，在爆炸撕裂砖石之前稳住了炸药。"}},faq={{q="这个任务的目标是什么？",a="你必须潜入洛克湖的水下，到达巨石水坝的基座，找到安置好的瑟福瑞姆炸药桶，并倒入主工程师辛德维尔的拆弹剂来中和爆炸。",al={"任务目标","我在这里该做什么","黑暗威胁临近任务目标"}},{q="是谁安置了爆炸桶？",a="黑铁暴乱分子在当天早些时候渗透进了洛克湖，利用当地山地探险队员不在场的机会，将一枚瑟福瑞姆炸药直接安放在了水坝的水下那一侧。",al={"谁放的炸弹","谁安置了瑟福瑞姆","黑暗威胁临近肇事者"}},{q="如果水坝被毁会发生什么？",a="巨石水坝拦截了巨大的洛克湖。如果水坝破碎，数百万加仑的水将会冲入湿地和周围的峡谷，冲毁道路、城镇和生命。",al={"为什么要保护水坝","炸弹爆炸会发生什么","水坝爆炸风险"}},{q="是谁配置了拆弹剂？",a="主工程师辛德维尔七世使用收集到的试剂配制了这种化学中和剂，制造出了一种可以在不引发意外爆炸的情况下中和瑟福瑞姆炸药的混合物。",al={"谁制作了混合物","辛德维尔的角色","谁制作了化学药剂"}},{q="爆炸桶在哪里？",a="炸药桶位于水下，紧靠着巨石水坝南部面向湖泊一侧深处的水下基座。",al={"炸弹在哪里","炸药桶位置","水下火药桶"}},{q="使用了什么样的爆炸物？",a="黑铁破坏者使用的是瑟福瑞姆，这是一种强力且挥发性极强的爆破化合物，被装在密封的防水桶中。",al={"炸弹由什么制成","炸弹类型","什么炸药"}}},fp="19,157,28.331.0,22.322.1,31.185.0,30.196.0,37.151.0,36.155.0,35.103.0,32.98.0"}
P.entries["quest:282"] = {n="森内尔的观察站",s="在收集了关于寒脊山谷当地威胁的重要情报后，格瑞林·白须委托你将他的发现带给远在卡拉诺斯的兄弟，森内尔·白须。然而，想要离开这片受保护的山谷，你需要穿过一条最近被敌对穴居人占领的隧道，那里有巡山人萨鲁斯把守。",h="在收集了关于寒脊山谷当地威胁的重要情报后，格瑞林·白须委托你将他的发现带给远在卡拉诺斯的兄弟，森内尔·白须。然而，想要离开这片受保护的山谷，你需要穿过一条最近被敌对穴居人占领的隧道，那里有巡山人萨鲁斯把守。",kw={"安威玛尔","寒脊山谷","格瑞林·白须","格瑞林的报告","卡拉诺斯","巡山人萨鲁斯","森内尔·白须","穴居人","隧道"},ang={["faction:Alliance"]="维持矮人山谷之间通道的安全对于铁炉堡的防御和联盟信使的安全至关重要。",["race:Dwarf"]="对于矮人巡山人和新兵来说，穿过东部隧道标志着他们第一次离开寒脊山谷的训练场，正式执行任务。",["race:Gnome"]="作为生活在铜须部族中的侏儒难民，这份公文提供了一条走出最初避难所的路径，去面对困扰丹莫罗的更广泛的问题。"},sec={{t="白须家族的信使",b="格瑞林·白须花费了巨大的精力来记录寒脊山谷周围蠢蠢欲动的巨魔活动。当他的日志被偷走又被找回后，他意识到收集到的情报太过关键，绝不能交给缺乏经验的学徒。为了绕过中间环节，格瑞林挑选了一位经验丰富的冒险者，直接将他的报告送到他在卡拉诺斯负责山谷外行动的兄弟——森内尔·白须手中。"},{t="通往卡拉诺斯的封锁通道",b="离开寒脊山谷已不再是一段简单的路程。连接山谷与丹莫罗广阔雪原的东部隧道已经被掘地的穴居人暴力占据。为了防止毫无防备的平民误入陷阱，铁炉堡卫队在隧道外驻扎了巡山人萨鲁斯。只有携带紧急公务的旅行者才被允许通过哨所，穿越这条地下险道。"}},faq={{q="格瑞林要把报告送给谁？",a="这份报告是写给格瑞林·白须的兄弟——森内尔·白须的。他目前驻扎在群山之外的卡拉诺斯，负责评估该地区的局势。",al={"谁收到报告","森内尔·白须","报告接收者"}},{q="为什么格瑞林的学徒不能递送报告？",a="格瑞林最初打算派他的学徒去，但在最近发生了冰鬃巨魔偷走他日志的事件后，他认为这些信息太重要了，不能交给缺乏经验的人。",al={"为什么不用学徒","格瑞林的学徒"}},{q="为什么出寒脊山谷的隧道有人把守？",a="连接寒脊山谷与丹莫罗其他地区的隧道已经被穴居人完全占领。巡山人萨鲁斯被部署在洞口，在道路被清理干净之前，负责保障平民的安全。",al={"为什么萨鲁斯在守卫","隧道被封锁","为什么隧道关闭"}},{q="巡山人萨鲁斯在哪里？",a="萨鲁斯驻扎在安威玛尔以东，正守在通往卡拉诺斯的寒脊山谷隧道的入口附近。",al={"萨鲁斯的位置","萨鲁斯在哪里","寻找巡山人萨鲁斯"}},{q="是什么让你能够通过穴居人出没的隧道？",a="巡山人萨鲁斯不会让普通的旅行者进入隧道，但携带格瑞林·白须发出的紧急公文证明了你的任务极其重要，值得去冒这个险。",al={"穿过隧道","隧道通行许可"}},{q="与巡山人萨鲁斯交谈后会发生什么？",a="萨鲁斯会提供穿越这条危险地下路线的警告和指导，然后准许你继续向东前往卡拉诺斯。",al={"下一步","见到萨鲁斯之后"}}},fp="20,178,29.308.0,28.232.0,37.123.0,49.145.0,50.153.0,36.108.0,58.90.0,52.120.0"}
P.entries["quest:2821"] = {n="质量的保证",s="在羽月要塞，制皮匠普拉特·马克格鲁比对质量的要求绝不妥协。普拉特偶然发现了厚雪人皮，想要一堆十张。",h="在羽月要塞，制皮匠普拉特·马克格鲁比对质量的要求绝不妥协。普拉特偶然发现了厚雪人皮，想要一堆十张。",kw={"羽月要塞","深痕谷","菲拉斯","被遗忘的海岸","普拉特·马克格鲁比","品质的标志","厚雪人皮","雪人"},sec={{t="普拉特的哲学",b="普拉特·马克格鲁比在制皮方面绝不妥协：只有最好的材料才行。在寻找优质材料时，普拉特偶然发现了厚雪人皮。雪人是菲拉斯的原生生物，深痕谷附近有很多，就在被遗忘的海岸内陆。"},{t="报酬",b="只要带来一堆十张皮，普拉特就会让你在他制作的皮革制品中挑选一件。把它们带回羽月要塞。"},{t="普拉特对毛皮的看法",b="普拉特问你是否停下来感受过毛皮的质地。经过适当处理，它们可能比铁还要坚硬，而且很少有人知道这一点。凭借对鞣制溶液的广泛了解，普拉特希望能制作出带有真正品质标志的制品。"}},faq={{q="是谁在索要毛皮？",a="普拉特·马克格鲁比，羽月要塞的一名制皮匠。",al={"任务发布者","普拉特·马克格鲁比","谁提供品质的标志"}},{q="在哪里可以找到雪人？",a="雪人是菲拉斯的原生生物，在被遗忘的海岸内陆深痕谷附近可以找到许多。",al={"雪人位置","雪人在哪里","深痕谷"}},{q="普拉特需要多少毛皮？",a="十张，作为一堆。",al={"需要多少雪人毛皮","毛皮数量"}},{q="我能用毛皮换到什么？",a="普拉特提供他亲手制作的皮革制品任你选择，作为交换。",al={"普拉特提供什么","品质的标志报酬"}}},fp="19,157,18.249.0,9.138.0,29.254.1,28.59.0,29.107.0,31.26.0,28.91.0"}
P.entries["quest:2822"] = {n="质量的保证",s="在莫沙彻营地，制皮师杉多尔·迅蹄坚持认为质量绝不能妥协。杉多尔发现了一些厚雪人毛皮，想要一堆十张。",h="在莫沙彻营地，制皮师杉多尔·迅蹄坚持认为质量绝不能妥协。杉多尔发现了一些厚雪人毛皮，想要一堆十张。",kw={"莫沙彻营地","深痕谷","菲拉斯","被遗忘的海岸","杉多尔·迅蹄","制皮","厚雪人毛皮","雪人"},sec={{t="荣耀的问题",b="杉多尔·迅蹄以自己的制皮手艺为荣，并声称质量绝不能妥协。最近杉多尔发现了厚雪人毛皮。菲拉斯是雪人的家园，它们经常出没在莫沙彻营地以西的深痕谷，就在被遗忘的海岸内陆。"},{t="报酬",b="只要你拿来一堆十张毛皮，杉多尔就会让你从他制作的皮甲中选择一件。把它们带回莫沙彻营地。"},{t="杉多尔对这些毛皮的想法",b="杉多尔宣称，经过特殊的处理，这些毛皮可以像铁一样坚硬。找到合适的鞣制混合剂需要多次尝试，但杉多尔确信这些毛皮将把质量标准提升到一个新的高度。"}},faq={{q="是谁在索要毛皮？",a="杉多尔·迅蹄，一位在菲拉斯的莫沙彻营地的制皮师。",al={"任务给予者","荣耀的问题任务发布者","杉多尔在哪里"}},{q="在哪里可以找到雪人？",a="雪人是菲拉斯的本土生物。许多雪人可以在莫沙彻营地以西的深痕谷找到，就在被遗忘的海岸内陆。",al={"雪人在哪里","雪人毛皮位置","深痕谷在哪里"}},{q="需要多少毛皮？",a="十张，也就是一堆。",al={"需要多少雪人毛皮","雪人毛皮数量","荣耀的问题任务需求"}},{q="我能用这些毛皮换取什么？",a="杉多尔会让你从他制作的皮甲中任选一件，以交换这堆毛皮。",al={"杉多尔提供什么","荣耀的问题任务奖励"}}},fp="19,164,17.273.0,9.129.0,31.220.1,28.65.0,29.127.0,28.26.0,28.92.0"}
P.entries["quest:283"] = {n="水坝危机",s="“阴影笼罩”是一项紧急任务，旨在保护洛克莫丹免遭灾难。联盟的冒险者受命在巨石水坝遭受毁灭性破坏之前，使用一种中和化学试剂来处理已安放的炸药。",h="“阴影笼罩”是一项紧急任务，旨在保护洛克莫丹免遭灾难。联盟的冒险者受命在巨石水坝遭受毁灭性破坏之前，使用一种中和化学试剂来处理已安放的炸药。",kw={"黑铁矮人","拆弹剂","炸药","辛德维尔","洛克莫丹","破坏行动","巨石水坝"},ang={["faction:Alliance"]="防止大坝决堤保护了铁炉堡与北方的阿拉希及洛丹伦之间的关键陆路通道。",["profession:Engineering"]="在一座巨大的民用工程内部中和不稳定的爆破装置，突显了防御措施和爆破理论的重要意义。",["race:Dwarf"]="巨石水坝是矮人石工技术的巅峰之作；保护它就是为了维护铁炉堡的荣誉与安全，抵御黑铁矮人的恶意。"},sec={{t="避免灾难",b="巨大的巨石水坝拦截了洛克湖浩瀚的湖水，高耸于下方湿地的低地之上。当黑铁矮人破坏者设法在水坝结构内部安放炸药时，整个山谷都面临着毁灭的威胁。使用拆弹剂可以让不稳定的炸药桶安全地熄灭，从而消除了对矮人工程和下游无数生命的直接威胁。"},{t="辛德维尔的慰藉",b="向主工程师辛德维尔七世复命，让现场的铁炉堡监工们松了一口气。辛德维尔称这次干预是铁炉堡王国和联盟的一次重大胜利。即便如此，黑铁矮人能够深入卡兹莫丹进行渗透，这也严峻地提醒着人们，他们那些死敌依然锲而不舍地想要摧毁铁炉堡的成就。"}},faq={{q="这个任务线的目的是什么？",a="该任务线主要讲述了揭露并阻止一场黑铁矮人的破坏阴谋，他们企图引爆炸药以摧毁巨石水坝。",al={"阴影笼罩任务摘要","巨石水坝任务目标","为什么要拆除炸弹"}},{q="是谁安放了炸药？",a="黑铁矮人破坏者在巨石水坝内安放了炸药桶，企图摧毁这一庞大的建筑。",al={"谁安放了炸弹","谁袭击了大坝","黑铁矮人与大坝"}},{q="主工程师辛德维尔七世是谁？",a="主工程师辛德维尔七世是负责洛克莫丹巨石水坝维护、运营和防御的矮人监工。",al={"辛德维尔是谁","辛德维尔背景故事","大坝工程师"}},{q="如果大坝决堤会发生什么？",a="如果巨石水坝被炸开，洛克莫丹巨大的蓄水池将会猛烈排空，淹没下游的湿地，冲毁道路、定居点和重要的交通路线。",al={"大坝被毁的后果","决堤的影响","大坝爆炸"}},{q="炸药是如何拆除的？",a="将特制的拆弹剂浇在炸药上，使火药桶在爆炸前安全地熄灭了。",al={"炸弹如何被阻止","拆弹剂","如何拆除炸药"}},{q="巨石水坝现在安全了吗？",a="虽然即刻的爆炸危机已经解除，水坝也保住了，但辛德维尔指出，由于黑铁矮人的特工继续威胁着该地区，这种防御只能说是暂时稳固。",al={"大坝安全吗","黑铁矮人还在吗","大坝永远安全吗"}}},fp="19,157,19.331.0,19.282.1,38.115.0,33.96.0,37.143.0,42.169.0,31.137.1,33.176.1"}
P.entries["quest:284"] = {n="The Search Continues",s="你继续在附近的鱼人窝棚中寻找米奈希尔雕像。这片窝棚群里没有它的踪影，于是你望向另外两座窝棚。",h="你继续在附近的鱼人窝棚中寻找米奈希尔雕像。这片窝棚群里没有它的踪影，于是你望向另外两座窝棚。",kw={"木桶","奶酪","窝棚","米奈希尔雕像","鱼人","寻找"},sec={{t="空荡的窝棚",b="你搜查了这片鱼人窝棚群，却没有发现米奈希尔雕像的踪迹。北面和东北面的窝棚或许藏着更多线索。"}},faq={{q="我在找什么？",a="你正在寻找米奈希尔雕像。",al={"寻找雕像","米奈希尔雕像","什么雕像"}},{q="我在这些窝棚里发现了什么？",a="你在这片鱼人窝棚群里没有发现米奈希尔雕像的踪迹。",al={"鱼人窝棚","空荡的窝棚","这里有什么"}},{q="接下来该去哪里找？",a="北面和东北面的两座窝棚或许藏着更多线索。",al={"下一个窝棚","去哪里找","北面的窝棚"}},{q="木桶里装着什么？",a="木桶里装着潮湿而刺鼻的奶酪，味道依然不错。",al={"木桶里的东西","奶酪木桶","木桶里有什么"}}},fp="20,135,12.149.0,24.45.0,31.77.0,25.68.0,22.58.0"}
P.entries["quest:2844"] = {n="大保姆",s="罗克比特，一个巨人，本该照看他的小友——暗夜精灵女孩Shay，但她却不知怎么走丢了。他感到十分担忧且不知所措，便请求你帮忙寻找她。",h="罗克比特，一个巨人，本该照看他的小友——暗夜精灵女孩Shay，但她却不知怎么走丢了。他感到十分担忧且不知所措，便请求你帮忙寻找她。",kw={"菲拉斯","巨人守护者","走失的女孩","罗克比特","废墟","shay","沙恩·飘叶"},sec={{t="在他转身之时走失",b="罗克比特本该照看Shay。他最后一次见到她时，两人正走在就在他站立处北面的废墟中。一切本来都好好的，直到他转过身来才发现她不见了。他不知道该怎么办才好，但他知道你的双腿比他走得快得多，所以他请求你去寻找她。"},{t="当你找到她时",b="Shay很高兴被找到了。她承认自己确实有点迷路了，但还是忍不住感叹这个地方真美。"}},faq={{q="罗克比特在找谁？",a="一个小暗夜精灵女孩，名叫Shay，是他的朋友，他本该照看她的。",al={"shay是谁","失踪的女孩是谁","谁迷路了"}},{q="Shay最后一次是在哪里被看到的？",a="罗克比特说，他们正走在他所在位置北面的废墟时，她就消失了。",al={"shay去了哪里","最后一次露面的地点","废墟在哪里"}},{q="为什么罗克比特要让别人去寻找？",a="他感到担忧且不知所措，而且他认为你的双腿比他走得快得多。",al={"为什么罗克比特无法自己搜寻","为什么派冒险者去"}}},fp="18,187,30.319.0,17.116.1,29.89.0,25.98.0,46.94.0"}
P.entries["quest:2845"] = {n="迷路的沙恩",s="一旦找到沙恩·飘叶，她会请求你帮助她回到她的朋友罗克比特身边。她承认只要有新鲜事可看，她就会四处闲逛，但她有一个铃铛，只要摇响它，她就会跑回来。",h="一旦找到沙恩·飘叶，她会请求你帮助她回到她的朋友罗克比特身边。她承认只要有新鲜事可看，她就会四处闲逛，但她有一个铃铛，只要摇响它，她就会跑回来。",kw={"护送","菲拉斯","巨人的守护者","罗克比特","沙恩·飘叶","沙恩的铃铛"},sec={{t="容易分心的女孩",b="沙恩想找到回去找罗克比特的路，他本该照看她的。她承认自己时不时会因为看到太多的新鲜事物而分心，从而四处乱逛。"},{t="箱子里的铃铛",b="沙恩说有一件事总能引起她的注意。她身边的箱子里放着一个她珍视的铃铛，她很喜欢那声音。她保证如果她走丢了，摇响铃铛就会把她唤回来。这个铃铛现在归你保管，她希望你能带她去罗克比特的营地。"}},faq={{q="沙恩·飘叶想回到谁身边？",a="她的朋友罗克比特，他本该照看她的。你要带她去他的营地。",al={"罗克比特是谁","沙恩的朋友","沙恩去哪了"}},{q="为什么沙恩会四处闲逛？",a="她说有太多新鲜事物可看，让她分心了。",al={"沙恩为什么会迷路","沙恩是怎么迷路的","为什么沙恩会四处闲逛"}},{q="我该如何防止沙恩走失？",a="沙恩的铃铛放在她旁边的箱子里。她很喜欢那声音，并保证如果她走丢了，摇响铃铛就会把她唤回来。",al={"如何控制沙恩","沙恩的铃铛","铃铛有什么用"}},{q="在此之前发生了什么？",a="这紧接着任务“巨人的守护者”，在那项任务中，罗克比特派你去寻找沙恩。",al={"前置任务","巨人的守护者","什么任务引导至漫游的沙恩"}}},fp="14,202,24.194.0,21.285.0,45.88.0,25.66.0,33.133.0,23.77.0"}
P.entries["quest:285"] = {n="Search More Hovels",s="鱼人棚屋里没有发现任何线索，但你怀疑米奈希尔雕像就在更北边。你继续寻找下一个线索。",h="鱼人棚屋里没有发现任何线索，但你怀疑米奈希尔雕像就在更北边。你继续寻找下一个线索。",kw={"木桶","米奈希尔雕像","鱼人棚屋","北边棚屋","继续搜寻棚屋"},sec={{t="向北搜寻",b="你认为北边的某间棚屋里藏着米奈希尔雕像。你继续在鱼人居所间搜寻。"}},faq={{q="我在找什么？",a="你正在鱼人棚屋中寻找米奈希尔雕像。",al={"寻找雕像","米奈希尔雕像","我在找什么"}},{q="这些棚屋里有雕像吗？",a="仔细检查这片棚屋，仍一无所获。",al={"空棚屋","这里有什么发现","棚屋里发现了什么"}},{q="雕像可能在哪里？",a="你认为北边的某间鱼人棚屋里可能藏着米奈希尔雕像。",al={"雕像在哪里","北边棚屋","雕像位置"}}},fp="18,125,16.130.0,24.63.0,36.58.0,29.83.0"}
P.entries["quest:286"] = {n="Return the Statuette",s="米奈希尔港的Karl Boran请你带回米奈希尔雕像。这尊小雕像是在从泥浆中捞出的木桶里发现的，找回它对Blind Princess号的船长很重要。",h="米奈希尔港的Karl Boran请你带回米奈希尔雕像。这尊小雕像是在从泥浆中捞出的木桶里发现的，找回它对Blind Princess号的船长很重要。",kw={"木桶","blind princess号","karl boran","米奈希尔港","米奈希尔雕像","圣骑士","小雕像"},sec={{t="小雕像",b="你在木桶里发现了这尊小雕像，里面还塞着细软的稻草。雕像刻画着一位年轻的长发圣骑士，正举起战锤。米奈希尔港的Karl Boran正等着你归还它，Blind Princess号的船长听说货物安然无恙后也会松一口气。"}},faq={{q="米奈希尔雕像是什么？",a="米奈希尔雕像是一尊银色小雕像，刻画着一位年轻的长发圣骑士，举起战锤。",al={"小雕像","米奈希尔小雕像","木桶里有什么"}},{q="小雕像是在哪里发现的？",a="小雕像被细软的稻草包裹着，装在一个从泥浆中捞出的木桶里。",al={"木桶小雕像","它在哪里","稻草木桶"}},{q="谁在等着这尊小雕像？",a="米奈希尔港的Karl Boran正等着米奈希尔雕像。",al={"谁要这尊小雕像","归还小雕像","karl boran"}},{q="归还后谁会松一口气？",a="Blind Princess号的船长会因珍贵货物失而复得而松一口气。",al={"船长松一口气","blind princess号货物","谁拥有货物"}},{q="小雕像刻画的是什么？",a="它刻画着一位年轻的长发圣骑士，高举着战锤。",al={"小雕像上是谁","圣骑士小雕像","战锤小雕像"}}},fp="20,178,12.235.0,31.103.0,30.76.0,33.68.0,41.94.0,31.72.0"}
P.entries["quest:2862"] = {n="与豺狼人开战",s="在莫沙彻营地，哈杜肯·迅蹄称豺狼人对营地本身构成了长久的威胁，而且近来它们的袭击变得愈发狂暴。哈杜肯要求你带回十个木爪豺狼人鬃毛，以削减它们的数量。",h="在莫沙彻营地，哈杜肯·迅蹄称豺狼人对营地本身构成了长久的威胁，而且近来它们的袭击变得愈发狂暴。哈杜肯要求你带回十个木爪豺狼人鬃毛，以削减它们的数量。",kw={"先发制人","莫沙彻营地","菲拉斯","豺狼人","哈杜肯·迅蹄","鬃毛","木爪"},sec={{t="对营地的威胁",b="对哈杜肯而言，这些豺狼人是否属于菲拉斯并不重要。他警告说，如果营地不能坚定决心，他们就会被彻底赶出这一地区。随着对营地的袭击变得愈发频繁，他想要削减它们的数量，并承诺为十个木爪豺狼人鬃毛提供丰厚的报酬。"},{t="哈杜肯的回应",b="哈杜肯称这些鬃毛是一个好的开始。他曾向其他人提出过同样的要求；许多人以前也与豺狼人战斗过，过去的努力确实遏制了它们。最近，豺狼人更频繁地向北推进至营地控制的区域，它们的袭击变得野蛮且近乎绝望。哈杜肯说他有一个计划，或许能解决这个问题。"}},faq={{q="在菲拉斯是谁提供了这份悬赏？",a="莫沙彻营地的哈杜肯·迅蹄。",al={"谁发布了针对木爪的战争","在哪里交还针对木爪的战争任务","针对木爪的战争任务发布者"}},{q="为什么莫沙彻营地要针对木爪豺狼人？",a="哈杜肯认为它们对营地构成了持续的威胁，且袭击愈发狂暴。他担心如果营地不坚守阵地，就会被彻底赶出这一地区。",al={"为什么要与木爪战斗","木爪问题","为什么豺狼人在袭击"}},{q="哈杜肯·迅蹄需要什么证明？",a="十个木爪豺狼人鬃毛。",al={"针对木爪的战争需要什么物品","木爪任务物品","我应该带什么给哈杜肯"}}},fp="18,202,20.301.0,18.345.1,34.37.0,49.170.0,45.24.0"}
P.entries["quest:2863"] = {n="突然袭击",s="哈杜肯·迅蹄打算打破与木爪豺狼人之间的僵局：在短时间内连续击杀几名自称为“阿尔法”的豺狼人领袖。哈杜肯希望由你来执行这个计划。",h="哈杜肯·迅蹄打算打破与木爪豺狼人之间的僵局：在短时间内连续击杀几名自称为“阿尔法”的豺狼人领袖。哈杜肯希望由你来执行这个计划。",kw={"阿尔法突袭","菲拉斯","豺狼人","哈杜肯·迅蹄","木爪","木爪阿尔法"},sec={{t="一小时内击杀五个阿尔法",b="哈杜肯推断，如果这些自称为“阿尔法”的豺狼人领袖一个接一个地倒下，它们的队伍就会陷入混乱。这也将传达出一个信息：部落有能力也有决心消灭它们。你必须执行哈杜肯的意志：在一小时内击杀五个阿尔法，否则僵局将无法打破。"},{t="后续",b="哈杜肯认为，削减兵力和击杀领袖会让豺狼人在突袭营地前产生犹豫。但麻烦还没有结束。哈杜肯想在豺狼人重新集结之前，查清到底是什么让它们变得如此疯狂。"}},faq={{q="谁发布了这个任务？",a="哈杜肯·迅蹄，他正在为部落处理与木爪豺狼人之间的僵局。",al={"谁发布阿尔法突袭任务","哈杜肯·迅蹄","任务发布者"}},{q="为什么要设定一小时的限制？",a="这个计划只有在阿尔法们快速接连倒下时才会奏效，因为这样才能让豺狼人的队伍陷入混乱。必须在一小时内击杀五个。",al={"为什么限制一小时","为什么连续击杀","阿尔法突袭时间限制"}},{q="什么是阿尔法？",a="它们是木爪豺狼人中的领袖，自称为阿尔法。",al={"木爪阿尔法","豺狼人阿尔法","目标是谁"}},{q="我需要击杀多少个阿尔法？",a="五个，必须在一小时内全部完成，然后回到哈杜肯·迅蹄那里。",al={"需要多少阿尔法","阿尔法计数"}}},fp="12,213,22.306.0,10.244.1,21.97.0,23.150.0,20.70.0,28.68.0"}
P.entries["quest:2866"] = {n="索兰萨尔废墟",s="珊蒂斯·羽月告诉你，南边的索兰萨尔废墟现在挤满了怒鳞娜迦。她让你穿过废墟，留意那里是否有任何不同寻常的地方。",h="珊蒂斯·羽月告诉你，南边的索兰萨尔废墟现在挤满了怒鳞娜迦。她让你穿过废墟，留意那里是否有任何不同寻常的地方。",kw={"羽月要塞","菲拉斯","凉亭","符文","怒鳞","娜迦","珊蒂斯·羽月","索兰萨尔"},sec={{t="古石之中的娜迦",b="索兰萨尔废墟的历史远比现代更为久远。珊蒂斯说他们最初探索过这个地方，没发现什么特别之处，便没再去管它。然而最近，大量的怒鳞娜迦占领了这里。起初这看起来像是进攻的前兆，这种威胁依然存在，但珊蒂斯认为可能还有别的事情正在发生。你需要穿过废墟，留意那里是否有任何不同寻常的地方。"},{t="显眼之处",b="看着凉亭，你发现它与周围的石造建筑格格不入。这显然是后来新建的。凉亭的侧面刻着重复的小型符文，没人知道它们来自何处，也不知道它们意味着什么。石头摸起来甚至还有温热感。"}},faq={{q="索兰萨尔废墟在哪里？",a="它们位于珊蒂斯·羽月的南边。",al={"索兰萨尔废墟位置","索兰萨尔在哪里","索兰萨尔在哪找"}},{q="为什么珊蒂斯·羽月会担心这些废墟？",a="怒鳞娜迦最近大量占据了废墟。起初这看起来像是准备进攻，这种威胁依然存在，但珊蒂斯认为可能还有别的事情正在发生。",al={"为什么要派我去索兰萨尔","珊蒂斯·羽月索兰萨尔原因","为什么要调查索兰萨尔"}},{q="在娜迦到来之前，索兰萨尔废墟是什么样的地方？",a="这些废墟的历史远比现代更为久远。珊蒂斯说他们最初探索过这里，没发现什么特别之处，便让它保持了原样。",al={"索兰萨尔历史","索兰萨尔是什么"}},{q="废墟里的是哪些娜迦？",a="怒鳞娜迦。",al={"索兰萨尔里有什么人","索兰萨尔敌人","索兰萨尔的娜迦部族"}}},fp="21,195,22.435.0,15.268.1,32.46.0,54.201.0,56.135.0,28.19.0"}
P.entries["quest:2867"] = {n="返回羽月要塞",s="你在索兰萨尔废墟中心发现了一座奇怪的凉亭。现在是时候回到羽月要塞，向珊蒂斯·羽月将军汇报这件事了。",h="你在索兰萨尔废墟中心发现了一座奇怪的凉亭。现在是时候回到羽月要塞，向珊蒂斯·羽月将军汇报这件事了。",kw={"羽月要塞","菲拉斯","仇恨之尾","娜迦","索兰萨尔废墟","珊蒂斯·羽月","索兰萨尔凉亭"},sec={{t="带回报告",b="珊蒂斯·羽月将军在羽月要塞等着听你关于在废墟中心发现的那个奇怪凉亭的消息。带着你的发现回到要塞去吧。"},{t="在你返回时",b="珊蒂斯认为你关于凉亭的报告令人不安。即使娜迦无意攻击，她们留下来对我们进军菲拉斯来说也是个坏兆头。要塞急需更多人手来对抗仇恨之尾娜迦，只要你愿意，珊蒂斯愿意提供更多任务给你。"}},faq={{q="废墟探索后我应该向谁汇报？",a="羽月要塞的珊蒂斯·羽月将军。",al={"我应该把这个交给谁","谁需要这份报告","在哪里交回羽月要塞任务"}},{q="我应该报告什么？",a="索兰萨尔废墟中心矗立着的那座奇怪凉亭。",al={"我该告诉珊蒂斯什么","在索兰萨尔发现了什么"}},{q="这之前的任务是什么？",a="这是“索兰萨尔废墟”的后续，珊蒂斯曾派你去探索废墟并调查那里的娜迦。",al={"前置任务","什么任务指向这里"}}},fp="32,180,24.192.0,14.279.1,35.56.0,21.69.0,23.108.0"}
P.entries["quest:2869"] = {n="憎世纳迦之战",s="羽月要塞的拉托尼库斯·月矛想要正面迎击仇恨之峰纳迦，而不是坐以待毙。他要求你收集十片完好的仇恨之峰鳞片。",h="羽月要塞的拉托尼库斯·月矛想要正面迎击仇恨之峰纳迦，而不是坐以待毙。他要求你收集十片完好的仇恨之峰鳞片。",kw={"未雨绸缪","羽月要塞","菲拉斯","仇恨之峰","仇恨之峰纳迦鳞片","拉托尼库斯·月矛","纳迦","萨尔多岛"},sec={{t="未雨绸缪",b="无论纳迦在图谋什么，拉托尼库斯·月矛都认为他们迟早会试图占领这座岛屿，因此必须在为时已晚之前采取强硬的手段。他需要十片完好的仇恨之峰鳞片，并希望你自己想办法弄到手。他指望通过这种方式削弱萨尔多岛上的纳迦势力，这也将是你第一次与纳迦交手。"},{t="和平与职责",b="拉托尼库斯明确表示，暗夜精灵并非好战之徒，而是致力于追求和平与和谐。但他同时也表示，这并不意味着他们会放弃守护自己的利益，而守护这些利益正是他对羽月将军和这座要塞应尽的职责。"},{t="事后",b="拉托尼库斯表示这些鳞片非常完美，打算把它们送给普拉特，看看能不能从中制作出有用的东西。他还有其他任务要交给你。"}},faq={{q="是谁发布了这个任务，在哪里领取？",a="拉托尼库斯·月矛，在羽月要塞，既负责发布收集鳞片的任务，也负责接收任务物品。",al={"谁发布了未雨绸缪","拉托尼库斯·月矛的位置","去哪里交未雨绸缪任务"}},{q="拉托尼库斯·月矛为什么要仇恨之峰鳞片？",a="他推测纳迦迟早会采取行动控制萨尔多岛，因此想要先发制人采取强硬措施。收集鳞片意味着削弱他们在岛上的势力。",al={"为什么要杀仇恨之峰","仇恨之峰鳞片的用途","为什么要收集纳迦鳞片"}},{q="需要多少鳞片？",a="十片完好的仇恨之峰鳞片。",al={"需要多少鳞片","鳞片数量"}},{q="在哪里可以找到仇恨之峰纳迦？",a="拉托尼库斯提到了萨尔多岛上有纳迦的驻军。",al={"仇恨之峰的位置","去哪里找仇恨之峰","萨尔多岛纳迦"}}},fp="21,170,28.398.0,14.241.0,10.189.1,31.92.0,52.148.0,27.40.0,35.52.0"}
P.entries["quest:287"] = {n="霜鬃巨魔要塞",s="霜鬃巨魔要塞是森内尔·白须在卡拉诺斯发布的一项联盟侦察任务。在追踪充满敌意的霜鬃巨魔到涌冰湖附近守卫森严的洞穴要塞后，森内尔招募了勇敢的斥候深入其中，消灭他们的猎头者，并为他的侦察报告提供关键情报。",h="霜鬃巨魔要塞是森内尔·白须在卡拉诺斯发布的一项联盟侦察任务。在追踪充满敌意的霜鬃巨魔到涌冰湖附近守卫森严的洞穴要塞后，森内尔招募了勇敢的斥候深入其中，消灭他们的猎头者，并为他的侦察报告提供关键情报。",kw={"烈酒村","丹莫罗","霜鬃猎头者","霜鬃巨魔要塞","冰霜巨魔","涌冰湖","卡拉诺斯","森内尔·白须","报告"},ang={["faction:Alliance"]="确保丹莫罗的安全可以保证连接铁炉堡与邻近王国的山区道路免受敌对部落的伏击。",["race:Dwarf"]="霜鬃巨魔挑战着铁炉堡在丹莫罗雪山的主导地位；侦察他们的主要洞穴要塞对王国的防御至关重要。",["race:Gnome"]="随着诺莫瑞根陷落后侏儒们在丹莫罗和卡拉诺斯定居，遏制霜鬃巨魔的攻势能确保脆弱的难民补给线安全。"},sec={{t="进度落后的斥候",b="驻扎在卡拉诺斯的登山者兼斥候森内尔·白须负责监视丹莫罗各地不断逼近的霜鬃巨魔威胁。虽然他成功追踪到这些好战部落位于烈酒村西南方的巢穴，但巨魔的数量之多让他犹豫不决。他不愿只身犯险，且官方报告的进度严重滞后，于是森内尔雇佣了路过的冒险者代他潜入这处冰冷的隐蔽点。"},{t="突入洞穴",b="这座要塞开凿在俯瞰涌冰湖的西侧山峰中，是一个挤满了敌对冰霜巨魔的冰冷堡垒。为了完成森内尔的任务，斥候必须一路杀入深层的地下隧道，消灭驻扎在岩架上的凶猛霜鬃猎头者，并测绘内部布局。从地穴中生还后，冒险者能提供森内尔完成呈交铁炉堡军事指挥官报告所需的关键情报。"}},faq={{q="霜鬃巨魔要塞位于哪里？",a="霜鬃巨魔要塞是一个位于丹莫罗最西侧、烈酒村西南方的洞穴。从卡拉诺斯出发，沿路向北前往桥梁，顺着冰封的河流向西经过涌冰湖到达烈酒村，然后向西南方向进入山区即可到达。",al={"寻找霜鬃巨魔要塞","洞穴在哪里","霜鬃巨魔要塞位置"}},{q="森内尔·白须是谁？",a="森内尔·白须是一位驻扎在卡拉诺斯雷酒酿制厂外的矮人斥候。他负责追踪丹莫罗当地的威胁，并汇编关于好战的霜鬃巨魔的战略情报报告。",al={"森内尔·白须","谁给予任务","卡拉诺斯任务给予者"}},{q="为什么森内尔不亲自去探索要塞？",a="森内尔侦察了入口并发现了部落的聚集地，但发现洞穴里挤满了武装巨魔，他不敢独自进入。由于担心自身安全且侦察任务即将逾期，他将这项危险的侦察工作委派给了有能力的冒险者。",al={"森内尔为什么害怕","森内尔为什么没去"}},{q="霜鬃巨魔是什么人？",a="霜鬃巨魔是丹莫罗雪山原生的冰霜巨魔部落。他们是铁炉堡矮人和侏儒的死敌，经常从分布在该地区的隐蔽营地中突袭贸易路线、营地和定居点。",al={"霜鬃","丹莫罗巨魔"}},{q="完成对要塞的侦察后会发生什么？",a="一旦你带着关于要塞布局和猎头者伤亡情况的消息返回，森内尔就会写完他的报告，并立即要求你将这些紧急文书送到他在丹莫罗的上级手中。",al={"后续任务","霜鬃巨魔要塞之后","报告任务"}},{q="你需要进入洞穴多深？",a="你需要深入到超过入口处的内部密室，直到完成洞穴布局的侦察并消灭五名霜鬃猎头者，以确认已彻底调查了洞穴深处。",al={"完全探索霜鬃巨魔要塞","洞穴探索触发"}}},fp="14,214,23.234.0,20.334.0,32.263.0,24.184.0,42.249.0,29.225.0,52.176.1,41.175.0"}
P.entries["quest:2870"] = {n="击败沙尔扎鲁",s="羽月要塞的拉托尼库斯·月矛告诉你，侦察兵已经确认了一位残忍的纳迦皇室成员：沙尔扎鲁。他请求你去阻止沙尔扎鲁，并将这位纳迦领主发掘出的遗物带回来。",h="羽月要塞的拉托尼库斯·月矛告诉你，侦察兵已经确认了一位残忍的纳迦皇室成员：沙尔扎鲁。他请求你去阻止沙尔扎鲁，并将这位纳迦领主发掘出的遗物带回来。",kw={"羽月要塞","菲拉斯","hatecrest","恐怖之岛","拉托尼库斯·月矛","沙尔扎鲁","神秘遗物","纳迦"},sec={{t="纳迦的指挥链",b="新的侦察报告让拉托尼库斯·月矛清楚地了解了纳迦的领导方式。皇室成员身居其队伍高层，并负责下达命令。其中最残忍的一位就是沙尔扎鲁。"},{t="一件奇怪的遗物",b="据侦察兵报告，沙尔扎鲁在恐怖之岛水域上方、主遗迹南面的一处洞穴中，亲自发掘出了一件奇怪的遗物。拉托尼库斯希望你能除掉沙尔扎鲁以终结他们的挖掘行动，并将那件神秘遗物带回羽月要塞以便研究。"},{t="完成任务后",b="拉托尼库斯认为沙尔扎鲁的倒台将使纳迦陷入一阵混乱，甚至可能是彻底的混乱，现在的威胁比以往任何时候都更容易控制。随后，他还有一件事要拜托你。"}},faq={{q="谁是沙尔扎鲁？",a="侦察兵确认的一位残忍的纳迦皇室成员。皇室成员身居纳迦队伍高层，负责下达命令。",al={"沙尔扎鲁","沙尔扎鲁是谁","沙尔扎鲁背景故事"}},{q="沙尔扎鲁在哪里？",a="侦察兵发现挖掘点位于恐怖之岛水域上方、主遗迹南面的一处洞穴中。",al={"沙尔扎鲁位置","沙尔扎鲁洞穴位置","寻找沙尔扎鲁"}},{q="那件遗物是什么？",a="一件沙尔扎鲁在纳迦挖掘过程中亲自发掘出来的奇怪遗物。拉托尼库斯想将其带回以便研究。",al={"神秘遗物 菲拉斯","遗物是什么","沙尔扎鲁的遗物"}},{q="我该把遗物交给谁？",a="交给羽月要塞的拉托尼库斯·月矛。",al={"谁需要遗物","沙尔扎鲁任务提交"}}},fp="21,219,25.203.0,12.327.0,15.214.1,21.106.0,31.96.0,18.130.0,29.50.0"}
P.entries["quest:2871"] = {n="递送遗物",s="拉托尼库斯·月矛请求你将神秘遗物送到羽月要塞，交给他的妻子维斯提亚·月矛。他完全搞不懂这个装置，希望她能看出这是什么东西。",h="拉托尼库斯·月矛请求你将神秘遗物送到羽月要塞，交给他的妻子维斯提亚·月矛。他完全搞不懂这个装置，希望她能看出这是什么东西。",kw={"交付遗物","羽月要塞","菲拉斯","拉托尼库斯·月矛","神秘遗物","维斯提亚·月矛"},sec={{t="学者的眼光",b="即使打赌输了，拉托尼库斯·月矛也没能搞懂这个装置。他说，他的妻子维斯提亚是他们社区里优秀的牧师，也是随处可见的最博学的学者之一。如果有人能弄清楚这个遗物是什么，那一定就是她，而他们必须知道答案。她就在不远处，毫无疑问正在忙于研究。"},{t="维斯提亚的初步观察",b="维斯提亚知道你曾帮助羽月将军和拉托对抗纳迦。当她拿到遗物时，第一眼判断它看起来并不属于它被发现的那些遗迹，也不是纳迦的设计，而是更加外来的东西。研究它需要时间，一旦完成，如果你们还在附近，她可能会再次寻求你的帮助。"}},faq={{q="维斯提亚·月矛是谁？",a="拉托尼库斯·月矛的妻子。拉托尼库斯称她是他们社区里优秀的牧师，也是一位博学的学者。她就在羽月要塞。",al={"维斯提亚·月矛","维斯提亚是谁","拉托的妻子"}},{q="神秘遗物来自哪里？",a="这是沙尔扎鲁领主在恐怖之岛的洞穴里挖掘纳迦时发现的遗物。",al={"遗物来自哪里","遗物起源","神秘遗物来源"}},{q="拉托尼库斯·月矛对这个遗物了解多少？",a="知之甚少。他说他完全搞不懂这个装置，所以才想让他的妻子看一看。",al={"拉托尼库斯了解什么","拉托的装置"}},{q="我该把遗物带到哪里去？",a="带给羽月要塞的维斯提亚·月矛。拉托尼库斯说她就在转角处。",al={"谁来接收遗物","交付遗物的目的地"}}},fp="20,196,15.344.0,19.362.1,24.153.0,42.98.0,52.109.0,26.91.0"}
P.entries["quest:2872"] = {n="斯杜雷的债务",s="“海狼”马克基雷和他的老朋友斯杜雷打了个赌，赌谁的朗姆酒更烈。斯杜雷在热砂港当酒保，现在他似乎想赖账，所以马克基雷让你去和他谈谈。",h="“海狼”马克基雷和他的老朋友斯杜雷打了个赌，赌谁的朗姆酒更烈。斯杜雷在热砂港当酒保，现在他似乎想赖账，所以马克基雷让你去和他谈谈。",kw={"舱底朗姆酒","藏宝海湾","马克基雷","朗姆酒","热砂港","斯杜雷","塔纳利斯","赌注"},sec={{t="朗姆酒与金钱的问题",b="斯杜雷欠“海狼”马克基雷一瓶非常特别的朗姆酒。斯杜雷曾吹嘘说，热砂港的朗姆酒比藏宝海湾的任何酒都要烈，并且说如果马克基雷尝过之后不认同，他就双倍奉还欠款。现在马克基雷觉得斯杜雷是不敢把酒交出来了，但马克基雷从不退缩。你被要求去热砂港的酒吧找斯杜雷谈谈。"},{t="斯杜雷的回答",b="斯杜雷并不害怕交出热砂港的舱底朗姆酒，他也这么说了。问题是，现在已经没有朗姆酒可以给他了。"}},faq={{q="谁是“海狼”马克基雷？",a="斯杜雷的朋友，和他打赌谁的朗姆酒更烈。他提到了藏宝海湾，说那是用来比较的地方。",al={"马克基雷是谁","“海狼”马克基雷","斯杜雷的债务任务发布者"}},{q="斯杜雷在哪里？",a="斯杜雷是位于塔纳利斯热砂港的酒保。",al={"斯杜雷在哪里","斯杜雷位置","寻找斯杜雷"}},{q="斯杜雷和马克基雷打了什么赌？",a="斯杜雷吹嘘说热砂港的朗姆酒胜过藏宝海湾的任何酒。如果马克基雷尝过之后不认同，斯杜雷就会双倍偿还他欠的钱。",al={"赌注是什么","打什么赌","斯杜雷的赌注"}}},fp="13,202,24.414.0,15.120.1,28.127.0,24.54.0,40.157.0"}
P.entries["quest:2873"] = {n="斯杜雷的货物",s="斯杜雷的朗姆酒喝光了，而且还因为一个赌注欠了朋友一笔债。库尔戈船长偷走了最后一批货物，并把它藏在南边那个有围墙的海盗镇里。所以斯杜雷请求你把它找回来。",h="斯杜雷的朗姆酒喝光了，而且还因为一个赌注欠了朋友一笔债。库尔戈船长偷走了最后一批货物，并把它藏在南边那个有围墙的海盗镇里。所以斯杜雷请求你把它找回来。",kw={"库尔戈","落帆海湾","马克基雷","朗姆酒","货物","热砂港","斯杜雷","塔纳利斯"},sec={{t="被盗的货物",b="斯杜雷答应给藏宝海湾的“海狼”马克基雷的朗姆酒已经没了，而他需要用这些酒来偿还赌债。库尔戈船长偷走了最后一批货，并把它藏在南边那个叫落帆海湾的有围墙的海盗镇里。斯杜雷请求你找回这批朗姆酒，好让他证明卡利姆多的酒比藏宝海湾能提供的任何酒都要好。"},{t="存放在哪里",b="在海盗镇里，朗姆酒被装在西北方那座房子的上层木箱中。"}},faq={{q="斯杜雷是谁？",a="斯杜雷在塔纳利斯的热砂港，他欠了藏宝海湾的“海狼”马克基雷一些朗姆酒来偿还赌注。",al={"斯杜雷","谁发布斯杜雷的货物任务","塔纳利斯的斯杜雷"}},{q="为什么斯杜雷想要拿回他的货物？",a="库尔戈船长偷走了他最后一批朗姆酒。斯杜雷需要用它来偿还与马克基雷的赌约，并证明卡利姆多的酒胜过藏宝海湾的酒。",al={"为什么要朗姆酒","斯杜雷的动机","斯杜雷的货物是什么"}},{q="海盗把朗姆酒藏在哪里了？",a="在南边那个有围墙的海盗镇，即落帆海湾，位于西北方向那座房子的上层木箱里。",al={"斯杜雷的朗姆酒位置","货物在哪里","落帆海湾的朗姆酒"}},{q="库尔戈船长是谁？",a="就是他偷走了斯杜雷最后一批朗姆酒，并将其藏在南边那个有围墙的海盗镇里。",al={"库尔戈","库尔戈船长"}},{q="这一步在任务链中处于什么位置？",a="它是斯杜雷的债务任务之后的后续。",al={"斯杜雷的货物任务链","斯杜雷的债务之后是什么任务"}},{q="“海狼”马克基雷是谁？",a="他在藏宝海湾，和斯杜雷打赌看谁的朗姆酒更好。",al={"海狼马克基雷","藏宝海湾的马克基雷"}}},fp="17,187,17.354.0,16.96.0,14.109.0,39.148.0,35.113.0,22.100.0,38.25.0,28.73.0"}
P.entries["quest:2874"] = {n="给马克基雷的货物",s="斯杜雷递给你一瓶热砂港舱底朗姆酒，让你带给藏宝海湾的“海狼”马克基雷，好让他彻底打消对藏宝海湾酒类的执念。",h="斯杜雷递给你一瓶热砂港舱底朗姆酒，让你带给藏宝海湾的“海狼”马克基雷，好让他彻底打消对藏宝海湾酒类的执念。",kw={"藏宝海湾","马克基雷","“海狼”马克基雷","热砂港舱底朗姆酒","斯杜雷","斯杜雷的债务","斯杜雷的货物","塔纳利斯"},sec={{t="送酒任务",b="在你帮忙运送了货物之后，斯杜雷给了你一瓶热砂港舱底朗姆酒。你得把它送到藏宝海湾的马克基雷手里，这样他终于可以放弃他那关于当地酒水的疯狂想法了。"},{t="马克基雷的定论",b="马克基雷尝了尝朗姆酒，对这种糟糕透顶的味道感到难以置信，这让他很高兴。斯杜雷信守了他关于舱底朗姆酒的诺言，所以他不必再支付欠款。马克基雷称这东西浓得像砂砾，喝起来像岩浆一样灼烧。"}},faq={{q="谁给了你这瓶酒？",a="热砂港的斯杜雷。",al={"谁开启了送酒给马克基雷的任务","送酒给马克基雷的任务发布者"}},{q="谁接收这瓶朗姆酒？",a="藏宝海湾的“海狼”马克基雷。",al={"我该把酒带到哪里","谁收到了朗姆酒","马克基雷的位置"}},{q="运送的是哪种酒？",a="一瓶热砂港舱底朗姆酒。",al={"这是什么朗姆酒","斯杜雷给了什么酒"}},{q="这一步在任务链中处于什么位置？",a="它紧接在“斯杜雷的债务”和“斯杜雷的货物”之后。",al={"送酒给马克基雷之前是什么任务","送酒给马克基雷的任务链"}}},fp="20,155,17.216.0,19.224.1,25.29.0,31.35.0,40.35.0,38.47.0"}
P.entries["quest:2875"] = {n="通缉：安德雷·费尔比德",s="加基森和热砂港的一张悬赏通告点名了海盗安德雷·火须，他被控犯下了针对热砂财团和加基森的罪行。通告声明，将其头颅送至热砂港的安全主管吉罗姆·比格维兹处，即视为一份具有约束力的合同。",h="加基森和热砂港的一张悬赏通告点名了海盗安德雷·火须，他被控犯下了针对热砂财团和加基森的罪行。通告声明，将其头颅送至热砂港的安全主管吉罗姆·比格维兹处，即视为一份具有约束力的合同。",kw={"安德雷·火须","比格维兹","加基森","海盗据点","热砂港","塔纳利斯","悬赏海报"},sec={{t="法令",b="这张通告称安德雷·火须是一个卑劣的海盗，被控犯下了针对热砂财团和加基森的罪行。执政议会已颁布法令，任何阅读此通告的人均可使用致命武力来抓捕安德雷及其同伙。他就在热砂港沿海岸向南走一段路的海盗据点内，站在围墙内的一处篝火旁。"},{t="作为代理的头颅",b="另一条法令指出，如果安德雷死亡或在审讯时无法到场，他的头颅可以作为他的代理。将其送至热砂港的安全主管吉罗姆·比格维兹处，即视为一份具有约束力的合同。"},{t="付款条款",b="比格维兹很高兴安德雷终究还是会出席他的审判。当你签名后就会发放报酬，比格维兹挥挥手说那些小字条款无伤大雅，还补充说它们太小了，用放大镜也看不清。"}},faq={{q="谁是安德雷·火须？",a="一名被控犯下针对热砂财团和加基森罪行的海盗。",al={"安德雷·火须","谁是安德雷","火须 塔纳利斯"}},{q="哪里可以找到悬赏通告？",a="在加基森和热砂港。",al={"任务起始点","悬赏海报位置","悬赏安德雷·火须海报"}},{q="安德雷·火须在哪里？",a="在热砂港沿海岸向南走一段路的海盗据点，围墙内的一处篝火旁。",al={"火须位置","火须在哪里","寻找安德雷·火须"}},{q="处理掉安德雷后，谁负责接收头颅？",a="热砂港的安全主管吉罗姆·比格维兹。",al={"向谁上交火须","比格维兹位置","火须头颅上交处"}},{q="为什么需要他的头颅？",a="根据法令，如果他在审讯时死亡或无法到场，头颅可以作为他的代理。",al={"为什么需要头颅","头颅作为代理","审判代理"}}},fp="23,277,10.363.0,17.224.0,16.216.1,23.62.0,37.38.0,33.105.0,47.50.0,25.101.0"}
P.entries["quest:2876"] = {n="船运时刻表",s="一份卷轴记录了在热砂港和藏宝海湾之间航行的船只，其中一些航程旁边有标记。它应该交到热砂港的一位负责人手中。",h="一份卷轴记录了在热砂港和藏宝海湾之间航行的船只，其中一些航程旁边有标记。它应该交到热砂港的一位负责人手中。",kw={"比格维兹","藏宝海湾","海盗","船只时刻表","热砂港","塔纳利斯"},sec={{t="这卷卷轴",b="卷轴列出了往返于热砂港和藏宝海湾之间的货运船只，包括已完成和将要进行的航次，以及船只的名称。有些航程旁边打了个大大的叉，另一些则写着关于战利品或激烈战斗的笔记。这份卷轴是给热砂港的一位负责人的。"},{t="港口的反应",b="安全主管吉罗姆·比格维兹发现时刻表上的日期和时间十分准确，并担心海盗船长会利用它做出什么事来。在听说你是从海盗手中夺取它之后，比格维兹称这是一个令人不安的消息，他感谢了你，并对海盗已死感到高兴。"}},faq={{q="时刻表上写了什么？",a="往返于热砂港和藏宝海湾之间的船名及航行时间，包括过去和未来的航次，一些航程旁边有大大的叉号，另一些旁边则有关于战利品或激烈战斗的注释。",al={"船只时刻表写了什么","船只时刻表文本","货运备注"}},{q="谁需要看这份文件？",a="热砂港的一位负责人。安全主管吉罗姆·比格维兹就是接收它的人。",al={"我该把时刻表交给谁","船只时刻表上交","时刻表交到哪里"}}},fp="14,165,10.312.0,19.257.1,32.190.0,31.95.0"}
P.entries["quest:2877"] = {n="清理隐匿石",s="来自鹰巢山的弗拉加尔需要一支清理小队去清理隐匿石周围的区域，部落弃守了那里，现在那里已被淤泥怪和软泥怪占领了。蛮锤部族计划在清理干净后利用那片区域。",h="来自鹰巢山的弗拉加尔需要一支清理小队去清理隐匿石周围的区域，部落弃守了那里，现在那里已被淤泥怪和软泥怪占领了。蛮锤部族计划在清理干净后利用那片区域。",kw={"鹰巢山","弗拉加尔","绿色淤泥怪","辛特兰","翡翠软泥怪","隐匿石","蛮锤部族"},sec={{t="领土问题",b="比起铁炉堡的兄弟，蛮锤部族更铭记过去。弗拉加尔说，在这里，通过亲力亲为才能赢得友谊。部落弃守了他们在辛特兰隐匿石周围的据点，如今那里已经被恶心的淤泥怪和软泥怪占领了。蛮锤部族对那块土地另有打算，但首先得先清理掉那些滋生的怪物。"},{t="清理地面",b="击杀十只绿色淤泥怪和十只翡翠软泥怪，然后向在鹰巢山等待的弗拉加尔汇报。"}},faq={{q="弗拉加尔是谁？",a="弗拉加尔是位于辛特兰鹰巢山的一名蛮锤矮人，他希望清理隐匿石。",al={"谁发布隐匿石清理任务","弗拉加尔"}},{q="为什么蛮锤部族想要清理隐匿石？",a="部落弃守了他们在隐匿石周围的阵地，被淤泥怪和软泥怪占领了。蛮锤部族对该区域有计划，但首先需要一支清理小队。",al={"为什么要杀死软泥怪","蛮锤部族隐匿石计划"}},{q="什么生物栖息在隐匿石？",a="绿色淤泥怪和翡翠软泥怪已经占领了那里旧的部落阵地。",al={"隐匿石怪物","隐匿石有什么"}},{q="为什么弗拉加尔要提到铁炉堡？",a="弗拉加尔说，比起铁炉堡的兄弟，蛮锤部族更铭记过去，并且在这里，通过亲力亲为才能赢得友谊。",al={"蛮锤部族与铁炉堡的区别","弗拉加尔与铁炉堡"}}},fp="19,222,21.380.0,19.114.0,29.104.0,47.169.0,35.72.0,36.145.0"}
P.entries["quest:2879"] = {n="艾奎尼克斯法杖",s="特洛亚斯·月风认为他的法杖可能是艾奎尼克斯法杖，那是鸦风废墟中一座纪念碑的钥匙。为了查明真相，你需要收集在那片废墟中仍在燃烧的四团火焰的精华。",h="特洛亚斯·月风认为他的法杖可能是艾奎尼克斯法杖，那是鸦风废墟中一座纪念碑的钥匙。为了查明真相，你需要收集在那片废墟中仍在燃烧的四团火焰的精华。",kw={"拜尔坦","梦境之树","艾奎尼克斯巨石","菲拉斯","伊姆贝尔","拉哈萨","鸦风废墟","萨姆哈","艾奎尼克斯法杖","特洛亚斯·月风"},sec={{t="巨石之匙",b="当你回到特洛亚斯·月风身边时，他说他的法杖可能是艾奎尼克斯法杖，这实际上是艾奎尼克斯巨石的钥匙。那座巨石耸立在鸦风废墟中。在这些废墟里，有四团火焰仍在燃烧，分别是萨姆哈、伊姆贝尔、拜尔坦和拉哈萨。每团火焰都能提供一种精华，你需要站在巨石旁使用这四种精华来为法杖充能。如果它确实是艾奎尼克斯法杖，巨石就会打开，并显露出一件神圣的宝物。"},{t="在巨石旁",b="充能后的法杖几乎令人无法握持，强大的力量在你体内轰鸣。你触碰巨石冰冷的表面，一扇小门随之开启，让你得以取出里面的东西。光束从巨石周围倾泻而出。"}},faq={{q="艾奎尼克斯巨石位于哪里？",a="在大陆上梦境之树的西面，鸦风废墟里。",al={"艾奎尼克斯巨石位置","巨石在哪里","寻找艾奎尼克斯巨石"}},{q="我需要哪四团火焰？",a="萨姆哈、伊姆贝尔、拜尔坦和拉哈萨，这些火焰仍在鸦风废墟中燃烧。你需要收集每团火焰的精华。",al={"四团火焰","菲拉斯的火焰名称","鸦风废墟的火焰"}},{q="艾奎尼克斯法杖有什么用？",a="特洛亚斯·月风说它是开启艾奎尼克斯巨石的钥匙，里面藏有一件神圣的宝物。",al={"法杖有什么用","艾奎尼克斯法杖的用途","为什么要为法杖充能"}},{q="我在哪里为法杖充能？",a="站在艾奎尼克斯巨石旁，使用那四团火焰的精华。",al={"在哪里使用精华","充能法杖的位置"}}},fp="20,203,22.463.0,12.229.1,38.64.0,32.115.0,33.101.0,30.78.0"}
P.entries["quest:288"] = {n="第三舰队",s="在大副菲兹莫斯坐在米奈希尔港深水旅店外，用矮人蜜酒浇愁。他是库尔提拉斯第三舰队唯一的幸存者，这支骄傲的海军舰队在第二次战争期间被兽人奴役的红龙在湿地海岸外焚毁。",h="在大副菲兹莫斯坐在米奈希尔港深水旅店外，用矮人蜜酒浇愁。他是库尔提拉斯第三舰队唯一的幸存者，这支骄傲的海军舰队在第二次战争期间被兽人奴役的红龙在湿地海岸外焚毁。",kw={"深水旅店","末日舰队","龙喉氏族","菲兹莫斯","库尔提拉斯","米奈希尔港","红龙","第三舰队","波浪女王号","湿地"},ang={["faction:Alliance"]="听到菲兹莫斯讲述“波浪女王号”的陨落，让联盟的保卫者们回想起部落的骑龙者在卡兹莫丹留下的持久伤痕。",["race:Dwarf"]="格瑞姆巴托的阴影笼罩着整个卡兹莫丹，在其深处繁育的巨龙对矮人的土地和人类盟友都造成了巨大的破坏。",["race:Human"]="第三舰队的覆灭是一个苦涩的提醒，让人想起库尔提拉斯和联盟对抗龙喉氏族时所进行的一场场灾难性的海战。"},sec={{t="水手的悲伤",b="大副菲兹莫斯整日瘫坐在米奈希尔港深水旅店外，饱受宿醉和挥之不去的记忆折磨。他曾经是隶属于库尔提拉斯海上旗帜的一艘战列舰“波浪女王号”上的军官，如今却用痛苦的记忆换取一瓶瓶矮人蜜酒。任何愿意请他喝酒的人，都能听到他讲述关于第二次战争中最具毁灭性的海军屠杀之一的亲身经历。"},{t="波浪之上的烈火",b="第二次战争期间，第三舰队航行在卡兹莫丹的海岸线上，灾难从天而降。龙喉氏族在格瑞姆巴托奴役了红龙军团，对毫无防备的战舰喷吐龙火。菲兹莫斯回忆起木质船壳在滔天烈焰下无助地燃烧，将整船船员拖入深渊。菲兹莫斯独自幸存并被冲上岸，留下了他那陨落的战友们在那片如今被称为“末日舰队”的水下坟场中。"}},faq={{q="谁是大副菲兹莫斯？",a="他是一位坐在米奈希尔港深水旅店外借酒消愁的老水手。他曾是库尔提拉斯战舰“波浪女王号”的大副，也是第三舰队覆灭后已知的唯一幸存者。",al={"菲兹莫斯","喝醉的水手是谁","菲兹莫斯 旅店"}},{q="第三舰队遭遇了什么？",a="库尔提拉斯的第三舰队在第二次战争期间，于湿地海岸外遭到伏击并被焚毁。来自龙喉氏族的骑龙兽人从天而降喷吐烈火，将舰队的船只和水手送入了海底。",al={"第三舰队的命运","舰队是如何沉没的","库尔提拉斯船只沉没"}},{q="为什么龙会攻击人类船只？",a="第二次战争期间，龙喉氏族在附近的格瑞姆巴托利用恶魔之魂奴役了红龙女王阿莱克丝塔萨。在黑暗魔法的束缚下，红龙被迫成为部落的恐怖坐骑和攻城武器。",al={"龙喉氏族的巨龙","湿地的红龙","为什么兽人骑龙"}},{q="船只到底沉没在哪里？",a="烧焦的残骸沉没在湿地西海岸，米奈希尔港以北的水域，这片悲惨的区域如今被称为“末日舰队”。",al={"末日舰队在哪里","湿地沉船地点","第三舰队残骸"}},{q="菲兹莫斯想要什么饮料？",a="他需要一壶矮人蜜酒来打开话匣子，并缓解他剧烈的宿醉，这可以直接从深水旅店内的旅店老板那里买到。",al={"菲兹莫斯 蜜酒","菲兹莫斯想要什么","一壶蜜酒"}},{q="第三舰队隶属于哪个国家？",a="这支舰队属于库尔提拉斯，这个岛屿海洋王国强大的海军在第二次战争期间是联盟海军力量的支柱。",al={"第三舰队是暴风城的吗","库尔提拉斯舰队","谁拥有波浪女王号"}}},fp="15,204,16.415.0,19.454.0,30.233.0,33.194.0,39.218.0,34.141.0,33.148.0,38.144.0"}
P.entries["quest:2880"] = {n="巨魔部族项链",s="鹰巢山的弗拉加尔坚持认为，蛮锤部族不隶属于任何联盟，并且只以行事来衡量他人。从辛特兰的巨魔身上收集五条部落项链，对你而言会是一个好的开始。",h="鹰巢山的弗拉加尔坚持认为，蛮锤部族不隶属于任何联盟，并且只以行事来衡量他人。从辛特兰的巨魔身上收集五条部落项链，对你而言会是一个好的开始。",kw={"鹰巢山","悬赏","弗拉加尔","辛特兰","巨魔部落项链","巨魔","蛮锤"},sec={{t="赢得蛮锤的尊重",b="弗拉加尔不喜欢空谈，他明确表示蛮锤部族是独立的。任何希望与他们交朋友的人都必须首先证明自己的价值。在辛特兰山坡上游荡的巨魔有时会佩戴部落项链，将其中五条带给鹰巢山的弗拉加尔，便是一个好的开始。"}},faq={{q="弗拉加尔为什么想要巨魔项链？",a="弗拉加尔凭行动而非言语来评判他人，并表示对于任何寻求蛮锤友谊的人来说，五条项链是一个好的开始。",al={"为什么要巨魔项链","巨魔项链悬赏目的","弗拉加尔为什么要项链"}},{q="蛮锤部族是联盟的一部分吗？",a="弗拉加尔坚称他们不是。蛮锤部族是独立的，并且通过行动和作为来评判他人。",al={"蛮锤部族是联盟吗","鹰巢山属于联盟吗","蛮锤部族立场"}},{q="在哪里可以找到巨魔部落项链？",a="据说在辛特兰山坡上游荡的巨魔偶尔会携带这些项链。",al={"哪里获取巨魔部落项链","巨魔项链位置","如何获得巨魔项链"}},{q="我该把项链交给谁？",a="将五条项链交给鹰巢山的弗拉加尔。",al={"谁需要巨魔项链","弗拉加尔交任务","弗拉加尔在哪里"}}},fp="21,196,25.328.0,52.135.0,41.105.0,42.77.0,33.57.0"}
P.entries["quest:2881"] = {n="巨魔部族项链",s="身为蛮锤部族一员的弗拉加尔已经从你这里收过一次巨魔部族项链作为赏金。只要你每次带回五个，这个赏金任务就一直有效。",h="身为蛮锤部族一员的弗拉加尔已经从你这里收过一次巨魔部族项链作为赏金。只要你每次带回五个，这个赏金任务就一直有效。",kw={"弗拉加尔","辛特兰","部族项链","巨魔项链赏金","巨魔","蛮锤部族"},sec={{t="长期有效的赏金",b="弗拉加尔提醒你，虽然第一次上交已经完成，但只要你找到更多的巨魔部族项链，随时欢迎上交。弗拉加尔说，凡是为蛮锤部族而战的人，蛮锤部族也会反过来为他们而战。弗拉加尔只会在凑齐五个项链时才算作一批。"},{t="弗拉加尔的认可",b="交货时，弗拉加尔显得很高兴，他将这些项链视为你愿意干脏活累活的证明。弗拉加尔说，这种意愿在蛮锤部族中是备受推崇的。"}},faq={{q="谁需要巨魔部族项链？",a="弗拉加尔，他以蛮锤部族一员的身份发言。",al={"谁发布了这个赏金","弗拉加尔的角色","谁负责接收项链"}},{q="需要多少条巨魔部族项链？",a="一次五个。弗拉加尔说必须要有五个才算数。",al={"项链数量","多少条项链","赏金要求"}},{q="为什么弗拉加尔要收集这些项链？",a="弗拉加尔将它们视为愿意为蛮锤部族而战的标志，并表示这样做的人会发现蛮锤部族也愿意为他们而战。",al={"为什么要巨魔项链","蛮锤部族的动机","赏金的目的"}},{q="在此赏金任务之前有什么？",a="第一次巨魔项链赏金任务，你已经为弗拉加尔完成了。",al={"前置任务","上一步骤","之前的赏金"}}},fp="21,179,16.328.0,18.169.1,37.60.0,43.63.0,55.149.0,29.87.0"}
P.entries["quest:289"] = {n="被诅咒的船员",s="大副菲兹莫斯是库尔提拉斯第三舰队唯一的幸存者，他恳求人们怜悯他那些迷失的兄弟。这些溺亡的水手和海军陆战队员被困在湿地海岸外沉船上隐藏的一件神秘遗物中，他们作为不得安息的亡灵在残骸中徘徊。",h="大副菲兹莫斯是库尔提拉斯第三舰队唯一的幸存者，他恳求人们怜悯他那些迷失的兄弟。这些溺亡的水手和海军陆战队员被困在湿地海岸外沉船上隐藏的一件神秘遗物中，他们作为不得安息的亡灵在残骸中徘徊。",kw={"被诅咒的船员","被诅咒的海军陆战队员","被诅咒的水手","菲兹莫斯","库尔提拉斯","米奈希尔","斯涅利格","鼻烟盒","第三舰队","湿地"},ang={["class:Paladin"]="第三舰队的水手们是无辜的，他们被一件邪恶的遗物所困；让他们安息可以净化亵渎之举，并为黑暗的水域带来光明。",["faction:Alliance"]="库尔提拉斯长期以来一直为大联盟提供最优秀的水手；让他们受折磨的灵魂安息，是任何联盟冒险者应尽的庄严职责。",["race:Human"]="人类旅行者能感受到与这些落难水手的兄弟情谊，并认可库尔提拉斯王国共享的海军传统。"},sec={{t="不安的舰队",b="当库尔提拉斯第三舰队在米奈希尔港北部的参差海岸触礁沉没时，它们的悲剧并没有随着沉入海底而结束。虽然大副菲兹莫斯设法活着游上了岸，但他其他的船员却遭遇了比死亡更可怕的命运。隐藏在其中一艘船壳深处的一件神秘而可怕的宝藏，向垂死的水手们释放了诡异的魔法，将他们的灵魂束缚在被海水冲刷的船体上，使他们无法得到死亡的安宁。"},{t="刀锋下的慈悲",b="菲兹莫斯徘徊在米奈希尔港的酒馆里，每晚都受到他昔日船友呻吟和哭喊的困扰。他相信终结这些行尸走肉的生命能给他们带来解脱，于是他派遣冒险者深入腐烂、溺水的沉船，去击倒那些被诅咒的水手、经验丰富的海军陆战队员，以及他昔日的同僚大副斯涅利格，并找回斯涅利格的鼻烟盒，作为他的朋友终于获得安息的沉重证明。"}},faq={{q="大副斯涅利格是谁？",a="大副斯涅利格曾与大副菲兹莫斯一同在命运多舛的库尔提拉斯第三舰队服役。在舰队于湿地北海岸失事后，斯涅利格与其他船员一起溺水身亡，随后被藏在船上的邪恶遗物复活。如今，他作为亡灵怪物徘徊在其中一艘沉船被洪水淹没的货舱里。",al={"斯涅利格","大副斯涅利格","斯涅利格是谁"}},{q="为什么水手和海军陆战队员会被诅咒？",a="据菲兹莫斯所说，舰队中的一艘船载有一件隐藏的邪恶宝藏。当船只在海岸边失事时，这件神器的黑暗能量将溺亡船员的灵魂束缚在腐烂的船壳上，阻止了他们的灵魂超度，并将他们强行禁锢在亡灵的折磨中。",al={"为什么他们是亡灵","第三舰队诅咒","被诅咒的水手起因"}},{q="沉船在哪里？",a="第三舰队的沉船残骸位于湿地北部的离岸水域，米奈希尔港的北边。被诅咒的船员在被淹没的甲板和周围的水域中游荡，斯涅利格本人则潜伏在南部沉船破裂的船壳内。",al={"船在哪里","沉船位置","斯涅利格在哪里"}},{q="为什么菲兹莫斯想要斯涅利格的鼻烟盒？",a="鼻烟盒是大副斯涅利格生前的一件私人纪念品。把它带回给菲兹莫斯，可以作为切实的证据，证明他那被诅咒的同伴终于从海浪下腐烂的监狱中得到了解脱。",al={"斯涅利格的鼻烟盒","鼻烟盒","为什么是鼻烟盒"}},{q="大副菲兹莫斯是谁？",a="菲兹莫斯是一名库尔提拉斯水手，也是第三舰队唯一已知的生还者。他被悲伤和内疚所击垮，留在了米奈希尔港，被溺亡兄弟的噩梦所困扰，绝望地寻找愿意结束他们痛苦的旅行者。",al={"菲兹莫斯","大副菲兹莫斯"}},{q="杀死船员真的能打破诅咒吗？",a="击倒水手和海军陆战队员只能让他们不得安息的灵魂获得暂时的喘息，但这并不能完全打破诅咒。诅咒的根源仍然与隐藏在残骸上的那件神秘遗物紧密相连。",al={"诅咒解除了吗","这能结束诅咒吗"}}},fp="15,294,16.359.0,18.469.1,27.294.0,39.281.0,35.222.0,45.184.0,30.231.0,47.198.1"}
P.entries["quest:29"] = {n="湖中试炼",s="月神湖试炼是月光林地举办的一项限时挑战，旨在测试初学者的身体敏捷度和速度。挑战者必须潜入月神湖获取一枚不稳定的神殿灵珠，并在它消散之前将其带到雷姆洛斯神殿。成功完成试炼将获得守望者Tajarri的认可，并向塞纳里奥议会对平衡的奉献致敬。",h="月神湖试炼是月光林地举办的一项限时挑战，旨在测试初学者的身体敏捷度和速度。挑战者必须潜入月神湖获取一枚不稳定的神殿灵珠，并在它消散之前将其带到雷姆洛斯神殿。成功完成试炼将获得守望者Tajarri的认可，并向塞纳里奥议会对...",kw={"塞纳里奥议会","月神湖","月光林地","remulos","神殿灵珠","雷姆洛斯神殿","tajarri","月神湖试炼"},ang={["class:Druid"]="这项试炼测试德鲁伊必备的敏捷与应变能力，是月光林地向守护者Remulos致敬的成人礼。"},sec={{t="敏捷测试",b="月神湖试炼是由月光林地的守护者们监督的一项入门仪式。挑战者需要潜入月神湖平静的水域，寻回静置在沉入湖底的精致神殿灵珠。由于灵珠在离开存放处后会迅速衰变，这项试炼要求参与者具备敏锐的身体协调性、敏锐的感知力，并能在其魔力消散前将其快速送达目的地。"},{t="向守护者致敬",b="获取灵珠后，奔跑者必须赶往月光林地西北部的雷姆洛斯神殿。这座纪念碑是为守护者Remulos树立的永恒丰碑，他指引着塞纳里奥议会致力于维护自然与世界的平衡。在神殿激活灵珠是对议会内部重要性的一种仪式性认可。在那里，值得信赖的守望者Tajarri会迎接成功克服试炼时间限制与竞争的初学者。"}},faq={{q="什么是月神湖试炼？",a="月神湖试炼是在月光林地进行的一项敏捷与专注力的测试。初学者需要潜入月神湖冰冷的深处取回一枚会衰变的神殿灵珠，并在其能量消散前将其带到避难所的雷姆洛斯神殿。",al={"什么是月神湖试炼","月神湖试炼的目的","这是什么任务"}},{q="雷姆洛斯神殿在哪里？",a="雷姆洛斯神殿位于月光林地西北部。它致力于纪念守护者Remulos及其对塞纳里奥议会的指引，由守望者Tajarri负责守护和维护。",al={"雷姆洛斯神殿在哪里","神殿位置","月光林地雷姆洛斯神殿"}},{q="Tajarri是谁？",a="Tajarri是月光林地值得信赖的守望者之一，负责照看雷姆洛斯神殿。她监督月神湖试炼的完成情况，并欢迎那些带来灵珠以向神殿致敬的初学者。",al={"tajarri是谁","月光林地tajarri","神殿守望者tajarri"}},{q="什么是神殿灵珠？",a="神殿灵珠是从月神湖湖底取回的圣物。它一旦离开水面就会迅速衰变，需要携带者迅速奔跑，将其送往雷姆洛斯神殿激活，以此作为祭品。",al={"什么是神殿灵珠","为什么灵珠会衰变","神殿灵珠的用途"}},{q="为什么要在该神殿供奉守护者Remulos？",a="守护者Remulos是一位受人尊敬的林地守护者，他指引塞纳里奥议会维护自然与世界的平衡。位于月光林地西北部的神殿是他领导力与原则的永恒象征。",al={"守护者remulos是谁","remulos相关传说","为什么要向remulos致敬"}},{q="在神殿供奉灵珠有什么意义？",a="在雷姆洛斯神殿激活灵珠是对塞纳里奥议会所维护的神圣平衡的致敬，也是对该神殿在月光林地内长久精神重要性的认可。",al={"使用灵珠有什么效果","为什么要在大神殿激活灵珠"}}},fp="17,295,19.299.0,21.340.0,30.252.0,39.157.0,15.173.0,24.216.0,45.199.0,52.184.0"}
P.entries["quest:290"] = {n="解除诅咒",s="大副菲兹莫斯认为，他那些落难船员身上所缠绕的无法安息的诅咒，源自他们沉没的船只“无畏号”上所封存的一件黑暗圣物。为了让他的弟兄们得到解脱，冒险者必须面对哈林多尔船长的鬼魂，夺取保险箱钥匙，并从沉没的船体中找回这件遗物。",h="大副菲兹莫斯认为，他那些落难船员身上所缠绕的无法安息的诅咒，源自他们沉没的船只“无畏号”上所封存的一件黑暗圣物。为了让他的弟兄们得到解脱，冒险者必须面对哈林多尔船长的鬼魂，夺取保险箱钥匙，并从沉没的船体中找回这件遗物。",kw={"哈林多尔船长","菲兹莫斯","戈罗林·钢眉","无畏号","解除诅咒","米奈希尔港","保险箱","第三舰队","湿地"},ang={["class:Priest"]="解开精神上的苦难并净化被玷污的遗物需要属灵的权威，这就是为什么菲兹莫斯将保险箱内物品的最终净化工作托付给圣职者的原因。",["faction:Alliance"]="第三舰队的水手们生前效忠于联盟，让他们饱受折磨的灵魂安息是每一位途径米奈希尔港的联盟勇士应尽的荣誉义务。"},sec={{t="船长的重担",b="大副菲兹莫斯在第三舰队那场悲剧性的命运中幸存了下来，但他战友们的记忆时刻困扰着他的清醒时刻和梦境。他始终坚信，缠绕着他船员们的亡灵诅咒与锁在他那艘旧船“无畏号”保险箱里的一件神秘而邪恶的物体有关。哈林多尔船长的幽灵残骸依然在守护着这艘沉船，即使死后，他依然顽固地守护着这艘船最深层秘密的钥匙。"},{t="开启深渊",b="在湿地北部雾气缭绕的海岸外，散落着第三舰队残破的船骸。在“无畏号”被淹没的船体内，这艘船紧锁的保险箱里装着导致船员们痛苦不堪的核心遗物。要取回它，必须在甲板上击败哈林多尔那饱受折磨的鬼魂，拿到生锈的钥匙，并闯入被水淹没的内部，取回这件黑暗圣物，以便让神圣之手将其净化。"}},faq={{q="在这个任务中，你要搜索的是哪艘船？",a="你要搜索的是“无畏号”，也就是第三舰队那艘沉没在湿地西北海岸外的船只。",al={"哪艘船","无畏号沉船","保险箱在哪里"}},{q="哈林多尔船长是谁？",a="哈林多尔船长曾是“无畏号”的指挥官。死后，他那不得安息的灵魂徘徊在废弃船只的甲板上，顽固地紧握着保险箱的钥匙。",al={"哈林多尔是谁","哈林多尔船长背景故事"}},{q="为什么大副菲兹莫斯想要打开保险箱？",a="菲兹莫斯认为保险箱内锁着一件被诅咒的物体，正是它导致他船员们的灵魂陷入无尽的折磨，打开它是找回该圣物并将其净化的唯一途径。",al={"菲兹莫斯的目标","为什么打开保险箱","任务目的"}},{q="“无畏号”的保险箱在哪里？",a="保险箱位于“无畏号”下层船舱内部，已被水淹没，可以通过沉船侧面海浪下的破洞进入。",al={"保险箱位置","箱子在哪里","如何找到保险箱"}},{q="找到被诅咒的物体后，谁能净化它？",a="菲兹莫斯指示冒险者将找回的物体带给米奈希尔港的矮人牧师戈罗林·钢眉，以洗净其污秽。",al={"谁来净化遗物","戈罗林·钢眉是谁","把诅咒之物带给谁"}},{q="当初是什么导致了这艘船沉没？",a="在第二次战争期间，第三舰队遭到了兽人操控的红龙攻击，船只在湿地海岸外被烧毁并沉没；船上载着的被诅咒的财宝让溺亡的船员们无法安息。",al={"第三舰队如何沉没","第三舰队沉没原因"}}},fp="17,210,18.311.0,20.336.1,46.101.0,24.126.0,58.165.0,42.122.0,55.126.0,45.193.0"}
P.entries["quest:2902"] = {n="调查木爪岭",s="哈杜肯·迅蹄确信木爪豺狼人遵循着某种成文的战略。他派遣你去莫沙彻营地南部的豺狼人营地搜寻任何类似作战计划的东西。",h="哈杜肯·迅蹄确信木爪豺狼人遵循着某种成文的战略。他派遣你去莫沙彻营地南部的豺狼人营地搜寻任何类似作战计划的东西。",kw={"作战地图","作战计划","莫沙彻营地","菲拉斯","豺狼人","哈杜肯·迅蹄","木爪部族"},sec={{t="搜寻计划",b="此任务在“阿尔法打击”之后。哈杜肯对豺狼人的智商没什么好感，但他确信他们保留了某种战略记录，因为他们最近的袭击行动协调得太过完美，不像是临时起意。如果他能看到那些计划，就能更好地理解是什么激怒了他们。他派遣你回到木爪部族，去寻找任何看起来像是作战计划的东西并带给他。"},{t="地图显示了什么",b="这张地图确实是哈杜肯想要的。上面的箭头可能显示了部队的动向，但大多数都指向南方，远离北部的莫沙彻营地。地图的其他地方画着一个你认为是巨大昆虫的图案，下面有刻痕，或许是豺狼人遭到未知虫子袭击的损失计数。"}},faq={{q="是谁派遣你去调查木爪豺狼人的？",a="在莫沙彻营地的哈杜肯·迅蹄。",al={"谁给予木爪调查任务","木爪调查任务发布者"}},{q="为什么哈杜肯认为豺狼人有作战计划？",a="他们的袭击协调得太过完美，不像是临时起意，因此哈杜肯推断必然有一份成文的战略，能揭示是什么让他们如此躁动不安。",al={"为什么豺狼人会有计划","木爪部族战略"}},{q="作战计划在哪里？",a="在莫沙彻营地南部的豺狼人营地中。",al={"木爪部族计划在哪里","哪里寻找木爪作战地图"}},{q="“木爪调查”之前的任务是什么？",a="“阿尔法打击”是此任务前的一步。",al={"木爪调查之前的任务","木爪任务链前置条件"}}},fp="21,176,18.372.0,18.296.1,48.37.0,54.146.0,35.41.0,39.61.0"}
P.entries["quest:2903"] = {n="作战计划",s="你拿到了豺狼人的作战计划。接下来要做的就是把它们带回莫沙彻营地的哈杜肯·迅蹄那里，或许他或营地里的其他人能弄明白这些豺狼人到底想干什么。",h="你拿到了豺狼人的作战计划。接下来要做的就是把它们带回莫沙彻营地的哈杜肯·迅蹄那里，或许他或营地里的其他人能弄明白这些豺狼人到底想干什么。",kw={"作战计划","莫沙彻营地","菲拉斯","豺狼人","哈杜肯·迅蹄","木爪"},sec={{t="返回莫沙彻营地",b="在“木爪调查”之后，你拿到了木爪作战计划，现在唯一剩下的步骤就是将其交还给营地里的哈杜肯·迅蹄。哈杜肯一直在寻找豺狼人意图的切实证据。"},{t="哈杜肯的解读",b="哈杜肯说这正是他们所需要的。大部分潦草的字迹他都看不懂，但他见过足够多的作战计划，足以读懂目前的局势：豺狼人在两线作战。营地是其中一条战线，但它们的主力正对准南方的某个敌人。他感觉到这一切背后还有更大的阴谋，并认为现在是时候搞清楚那个第二个敌人是谁了。"}},faq={{q="这些作战计划需要送到哪里？",a="送到莫沙彻营地的哈杜肯·迅蹄那里。",al={"谁来接收计划","作战计划交还地点","作战计划交还"}},{q="这一步之前发生了什么？",a="“木爪调查”，即对豺狼人计划的搜寻。",al={"前置任务","导致作战计划的任务","作战计划的前提条件"}},{q="这些作战计划是从哪里来的？",a="它们是豺狼人自己的计划，是在“木爪调查”期间于莫沙彻营地南部的豺狼人营地中搜出来的。",al={"谁制作了地图","哪些豺狼人制定了计划","木爪计划来源"}}},fp="16,178,20.206.0,17.351.1,39.40.0,27.56.0,37.112.0"}
P.entries["quest:2904"] = {n="一团混乱",s="在诺莫瑞根遭受辐射的废墟深处，一名受伤的地精克努比在遭到黑铁矮人伏击后，虚弱地躺在穴居人之中。救出他可以揭露黑铁矮人参与地下钻探机械的不安情报，这必须被传达到藏宝海湾。",h="在诺莫瑞根遭受辐射的废墟深处，一名受伤的地精克努比在遭到黑铁矮人伏击后，虚弱地躺在穴居人之中。救出他可以揭露黑铁矮人参与地下钻探机械的不安情报，这必须被传达到藏宝海湾。",kw={"藏宝海湾","clockwerk run","黑铁矮人","诺莫瑞根","克努比","斯库提","超级钻机","tinkerwiz","穴居人"},ang={["faction:Alliance"]="揭露丹莫罗边境内的黑铁勾结行为证实了索瑞森大帝的特工正在积极破坏联盟在诺莫瑞根的恢复工作。",["profession:Engineering"]="黑铁机械师正在建造一台巨大的超级钻机的发现，引起了任何追踪先进地下硬件的工程师的极大关注。",["race:Gnome"]="从诺莫瑞根受污染的深处营救一名被困的幸存者是一项光荣的职责，尤其是在面对黑铁渗透者和野蛮穴居人的共同恶意时。"},sec={{t="伤痕累累的幸存者",b="当在诺莫瑞根危险的内室中穿行时，冒险者发现了困在宿舍区的克努比。这名地精遭到了严重的殴打，神志不清，他在被黑铁矮人俘虏后幸存下来，却被遗弃在野蛮的穴居人中自生自灭。遇到友善的面孔是他活着穿过受污染的走廊逃生的唯一机会。"},{t="地下阴谋",b="克努比掌握着关于在丹莫罗地下活动的黑暗势力的重要信息。他揭露了黑铁氏族正积极参与建造一台巨大的超级钻机。当克努比横跨海洋逃往棘齿城，警告地精工程师Tinkerwiz这一潜在威胁时，他派遣他的救命恩人前往南方的藏宝海湾，向地精工程师斯库提传递消息。"}},faq={{q="谁是克努比？",a="克努比是一名冒险深入诺莫瑞根废墟的地精。在获救之前，他遭到了伏击，被黑铁矮人殴打至濒死，并被遗弃给穴居人。",al={"克努比","克努比是谁"}},{q="克努比必须护送到哪里？",a="克努比必须被安全地护送穿过充满敌意的大厅，回到安全的Clockwerk Run出口和这座堕落城市上层的入口走廊。",al={"克努比带去哪","护送目的地","clockwerk run出口"}},{q="黑铁矮人为什么要插手？",a="黑铁矮人一直在地下进行密谋，协助设计和建造一台巨大的超级钻机。克努比在被矮人伏击前发现了这个阴谋。",al={"为什么是黑铁矮人","黑铁超级钻机","诺莫瑞根的黑铁矮人"}},{q="克努比逃脱后去了哪里？",a="到达安全地带后，克努比横跨海洋前往贫瘠之地的棘齿城，警告技师Tinkerwiz关于黑铁矮人参与地下钻井设备的事宜。",al={"克努比去了哪","克努比 棘齿城","警告tinkerwiz"}},{q="为什么必须向藏宝海湾的斯库提汇报？",a="斯库提是驻扎在藏宝海湾的地精工程师，他与Tinkerwiz合作，协调涉及高科技地下设备和应答器网络的操作。",al={"为什么找斯库提","藏宝海湾交任务","斯库提的联系"}},{q="这与麦克尼尔·瑟玛普拉格有什么关系？",a="斯库提认识到麦克尼尔·瑟玛普拉格在诺莫瑞根内部构成的持续威胁。帮助克努比可以为打算返回并对抗这位叛徒麦克尼尔的冒险者提供援助和补给。",al={"瑟玛普拉格的联系","对抗瑟玛普拉格"}}},fp="11,166,19.204.0,20.250.1,16.147.0,32.119.0,40.149.0,38.164.1,43.127.0,46.191.0"}
P.entries["quest:291"] = {n="森内尔的报告",s="将森内尔·白须关于霜鬃巨魔的报告从卡拉诺斯送往铁炉堡的参议员巴林·红石手中。森内尔警告说这位参议员脾气不好，并让你千万别提起是谁帮忙搜集了这些情报。",h="将森内尔·白须关于霜鬃巨魔的报告从卡拉诺斯送往铁炉堡的参议员巴林·红石手中。森内尔警告说这位参议员脾气不好，并让你千万别提起是谁帮忙搜集了这些情报。",kw={"巴林·红石","矮人参议院","霜鬃","high seat","铁炉堡","卡拉诺斯","magni bronzebeard","森内尔·白须","报告"},ang={["faction:Alliance"]="这次投递是对铁炉堡城市布局以及在丹莫罗内部塑造联盟国内政策的政治官僚体系的初步介绍。",["race:Dwarf"]="对于矮人玩家来说，走进High Seat递交快报，可以亲身领略国王麦格尼的王权与矮人参议院的议会权力之间那微妙的平衡。"},sec={{t="送往首都的快报",b="在深入霜鬃巨魔要塞进行了一次大胆的侦察后，森内尔·白须草拟了一份紧急报告，详细说明了丹莫罗正面临日益严重的巨魔威胁。这位驻扎在卡拉诺斯的山地探险队员需要一名信使将这些情报直接送达铁炉堡的参议员巴林·红石手中。为了在政府眼中保持自己的声望，白须兴高采烈地告诫他的跑腿人，千万不要提及究竟是谁在雪山峭壁中完成了这项危险的实地工作。"},{t="High Seat的摩擦",b="当这份文件被呈交给皇家法庭的红石参议员时，立刻引起了他的愤怒。这位脾气暴躁的参议员不仅没有对敌方巨魔动向的情报表示感谢，反而因为发现报告引用了国王麦格尼·铜须的个人授权来批准白须的行动而大发雷霆。这次投递暴露了铁炉堡管理大厅内持续不断的权力斗争，突显了参议院对行政法令以及以国王名义进行的未经批准的实地行动有多么反感。"}},faq={{q="森内尔·白须是谁？",a="森内尔·白须是一位驻扎在丹莫罗卡拉诺斯附近的矮人山地探险队员。他负责监督针对侵犯矮人定居点的霜鬃巨魔部落的侦察和军事侦探工作。",al={"森内尔·白须","谁给的报告","白须 卡拉诺斯"}},{q="参议员巴林·红石是谁？",a="巴林·红石是一位脾气暴躁、出身显贵的矮人参议员，常驻在铁炉堡国王麦格尼·铜须的王座室附近。他极力维护立法权威，并且很容易对普通请愿者感到厌烦。",al={"巴林·红石","谁是参议员","红石 铁炉堡"}},{q="为什么红石参议员会对这份报告感到愤怒？",a="森内尔警告说红石性格暴躁。当你将报告送达时，就会发现这位参议员对报告的反应。",al={"为什么红石很生气","为什么参议员大吼大叫","参议院与麦格尼"}},{q="为什么森内尔·白须要求对你的帮助保密？",a="白须希望他在铁炉堡的上司相信是他本人亲自管理并完成了艰苦的实地侦察，从而提升自己的地位，而不是承认是一名为流浪的冒险者执行了这项任务。",al={"为什么森内尔要冒领功劳","白须偷取功劳","森内尔的秘密"}},{q="报告在哪里送达？",a="这份报告被送达至铁炉堡High Seat内的参议员巴林·红石手中，那里是国王麦格尼·铜须举行朝会的大厅。",al={"去哪里提交报告","巴林·红石的位置","报告提交"}},{q="这个任务揭示了铁炉堡政治的什么信息？",a="这次投递引出了铁炉堡参议院以及接收边境报告的官员。红石的反应让人能更近距离地窥见其政治内幕。",al={"铁炉堡政府背景","矮人参议院背景","麦格尼与参议院"}}},fp="11,163,25.197.0,25.281.1,24.190.0,30.157.0,47.110.1,55.190.0,30.139.0,53.163.1"}
P.entries["quest:292"] = {n="帕雷斯之眼",s="在这个任务中，一位冒险者从被淹没的“无畏号”残骸中找回了一颗名为被诅咒的帕雷斯之眼的黑色脉动宝石。这件邪恶的遗物是应饱受折磨的水手费兹西蒙斯的请求找回的，它必须被带到米奈希尔港，以便矮人牧师戈罗林·钢眉能够预见如何净化它的枯萎诅咒。",h="在这个任务中，一位冒险者从被淹没的“无畏号”残骸中找回了一颗名为被诅咒的帕雷斯之眼的黑色脉动宝石。这件邪恶的遗物是应饱受折磨的水手费兹西蒙斯的请求找回的，它必须被带到米奈希尔港，以便矮人牧师戈罗林·钢眉能够预见如何净化它...",kw={"被诅咒的帕雷斯之眼","帕雷斯之眼","费兹西蒙斯","戈罗林·钢眉","无畏号","米奈希尔港","第三舰队","湿地"},ang={["class:Priest"]="处理像帕雷斯之眼这样的圣物所遭受的玷污，使得这次调查与圣光牧师们直接相关。",["faction:Alliance"]="第三舰队是一支联盟远征军，它的毁灭让米奈希尔港变得脆弱；找回它的遗物有助于让失去的同伴得到安息。",["race:Dwarf"]="发掘卡兹莫丹海岸附近的遗失圣物，触及了矮人致力于收回隐藏圣物的使命，并得到了铁炉堡神职人员如戈罗林·钢眉的协助。"},sec={{t="枯萎的圣物",b="在巴拉丁海湾那危机四伏的海水之下，沉船“无畏号”的锁闭强力保险箱里，静卧着一件不寻常的宝藏。箱子里装着一颗散发着令人不安光芒的黑色宝珠：帕雷斯之眼。这颗特殊的宝石并没有汇聚圣光，而是被扭曲成了一台充满苦难的机器，与第三舰队水手们那些不得安息的灵魂及厄运紧密相连。"},{t="寻求圣职的帮助",b="意识到这种黑暗魔法超出了普通打捞的范畴，这件圣物被直接带到了米奈希尔港的岸上。在那里，圣光的矮人牧师戈罗林·钢眉检查了这件异常物品。虽然他对这种圣洁的装置竟然曾属于第三舰队感到震惊，但戈罗林立刻识别出了它那不自然的腐化，并开始准备必要的仪式来消除其黑暗的影响。"}},faq={{q="什么是帕雷斯之眼？",a="帕雷斯之眼是一颗古老而强大的圣洁宝石。通常它与圣光能量相关联，但这颗特殊的宝石曾随第三舰队的沉船“无畏号”一同沉没，并已被扭曲和诅咒，散发着黑暗魔法。",al={"帕雷斯之眼背景故事","什么是帕雷斯","被诅咒的帕雷斯之眼"}},{q="帕雷斯之眼是在哪里找到的？",a="它是在湿地迷雾笼罩的海岸附近，从沉没的“无畏号”那被水淹没的残骸中的一个锁闭保险箱里找回的。",al={"在哪里可以找到眼睛","帕雷斯之眼位置","无畏号保险箱"}},{q="为什么戈罗林·钢眉关心这件圣物？",a="戈罗林·钢眉是一位驻扎在米奈希尔港的矮人牧师。作为圣光的修行者，他拥有识别古老圣物并开始打破邪恶诅咒所需仪式所需的圣职知识。",al={"谁是戈罗林·钢眉","为什么找钢眉"}},{q="费兹西蒙斯是怎么知道帕雷斯之眼的？",a="费兹西蒙斯是第三舰队的幸存者，至今仍受着那场悲剧的折磨。他因受到创伤而在米奈希尔的酒馆寻求庇护，他知道 wreckage 中隐藏着这件折磨他阵亡船员的黑暗遗物。",al={"费兹西蒙斯的关联","费兹西蒙斯为什么派我去"}},{q="为什么这只眼睛会被诅咒？",a="虽然其具体的腐化原因仍与第三舰队沉船上那些超自然的死亡和挥之不去的亡灵有关，但这件圣物是在舰队沉入海底时或之后吸收了黑暗能量。",al={"为什么它被诅咒了","眼睛诅咒起源"}},{q="把这只眼睛交给戈罗林之后会发生什么？",a="戈罗林检查了被诅咒的宝石，认定它不能维持在枯萎的状态，并指导冒险者去净化圣物所受的腐化影响。",al={"后续任务","如何处理这只眼睛"}}},fp="17,197,16.289.0,22.247.1,26.197.0,28.117.0,50.174.0,40.202.0,22.220.0,44.131.1"}
P.entries["quest:2922"] = {n="拯救尖端机器人！",s="大工匠欧沃斯巴克委托联盟冒险者从诺莫瑞根受辐射的废墟中取回尖端机器人的存储器核心。这台曾经乐于助人的机械助手在城市陷落期间遭受了严重的脑部极化，导致它陷入疯狂。欧沃斯巴克希望找回它的核心能让他扭转这种损坏，并修复他心爱的创造物。",h="大工匠欧沃斯巴克委托联盟冒险者从诺莫瑞根受辐射的废墟中取回尖端机器人的存储器核心。这台曾经乐于助人的机械助手在城市陷落期间遭受了严重的脑部极化，导致它陷入疯狂。欧沃斯巴克希望找回它的核心能让他扭转这种损坏，并修复他心爱的...",kw={"诺莫瑞根","存储器核心","负电子","欧沃斯巴克","正电子","尖端机器人","tinker town"},ang={["faction:Alliance"]="从诺莫瑞根受污染的周边地区回收有价值的失落技术，对于支持在铁炉堡避难的侏儒难民至关重要。",["profession:Engineering"]="尖端机器人的处理器从正电子到负电子的转变，对于致力于高复杂度计算矩阵的技师来说是一个警示故事。",["race:Gnome"]="对于侏儒工程师来说，尖端机器人代表了失去家园城市带来的悲剧性附带损害，证明了即使是他们最出色的智力成就也可能因灾难而扭曲。"},sec={{t="颠倒的思维",b="在诺莫瑞根遭遇灾难之前，尖端机器人是侏儒智慧的结晶。它由大工匠欧沃斯巴克设计，内置了无数小玩意和涵盖海量技术知识的知识库，以此协助研究人员工作。然而，穴居人入侵和有毒辐射泄露造成的混乱并没有放过这台机器。一阵杂散的电流冲击了尖端机器人脆弱的内部结构，使其正电子大脑完全极化，转变成了不稳定的负电子状态。"},{t="打捞行动",b="尖端机器人被困在诺莫瑞根受污染的大厅中，现在陷入了疯狂的狂乱状态，攻击视线内的任何人。尽管它发生了严重的故障，欧沃斯巴克仍拒绝将其视为废铁。他招募有能力的行动人员去追踪这台失控的机器人，从其金属底盘中取出存储器核心，并将其安全送回铁炉堡，以便大工匠能够解除极化并修复尖端机器人的思维。"}},faq={{q="尖端机器人是谁？",a="尖端机器人是大工匠欧沃斯巴克发明的一种机械助手。在诺莫瑞根陷落之前，它凭借庞大的知识数据库和内置的小玩意，协助大工匠及其同事开展工作。",al={"什么是尖端机器人","尖端机器人背景故事","欧沃斯巴克与尖端机器人"}},{q="为什么尖端机器人会变得敌对？",a="在诺莫瑞根陷落期间，一道杂散的电火花震击了尖端机器人的正电子大脑。这次冲击使其神经排列反转为负电子状态，将它乐于助人的性格变成了狂乱的暴走。",al={"为什么尖端机器人会发狂","尖端机器人发生了什么","尖端机器人极化"}},{q="在哪里可以找到尖端机器人？",a="尖端机器人在诺莫瑞根的外围走廊和大厅中徘徊，就在流亡侏儒和矮人远征军活动的防御线之外。",al={"尖端机器人在哪里","尖端机器人位置","找到尖端机器人"}},{q="谁发布了这个任务？",a="大工匠欧沃斯巴克在铁炉堡的Tinker Town提供这个任务，他在那里代表大工匠格尔宾·梅卡托克监督打捞和研究工作。",al={"谁发布拯救尖端机器人大脑的任务","欧沃斯巴克位置"}},{q="尖端机器人真的能被修复吗？",a="大工匠欧沃斯巴克相信，取回尖端机器人的存储器核心将使他能够诊断出负电子极化的确切原因，并使这台机器人恢复正常工作状态。",al={"尖端机器人修好了吗","可以修复尖端机器人吗","尖端机器人幸存了吗"}},{q="归还存储器核心后会发生什么？",a="收到核心后，欧沃斯巴克立即着手准备拆解和重新配置那些颠倒的电路，尽管在他那杂乱的工作室里找到合适的工具本身就是一项挑战。",al={"尖端机器人任务结局","上交尖端机器人核心"}}},fp="21,341,15.420.0,17.407.0,15.180.0,31.187.0,27.146.0,21.136.0,30.153.0,45.182.1"}
P.entries["quest:2923"] = {n="工匠大师欧沃斯巴克",s="这项任务指引暴风城的联盟冒险者前往铁炉堡的Tinker Town，大工匠Tinkmaster Overspark正在那里为一个悲剧性的故障而哀伤。萨尔努修士传信说，Overspark的机械创造物Techbot在诺莫瑞根受辐射的废墟中失控了。找到这位大工匠是找回这个迷失构装体记忆核心的第一步。",h="这项任务指引暴风城的联盟冒险者前往铁炉堡的Tinker Town，大工匠Tinkmaster...",kw={"诺莫瑞根","铁炉堡","overspark","sarno","techbot","tinker town","tinkmaster"},ang={["faction:Alliance"]="援助Tinker Town中流离失所的侏儒难民，加强了暴风城与矮人及侏儒王国之间至关重要的联系。",["profession:Engineering"]="Overspark的创造物代表了侏儒创造力的尖端水平，使得任何检查他那失控构装体的机会都成为了一次有益的尝试。",["race:Gnome"]="每一个抢救出的创造物和找回的记忆核心，都代表着在辐射和穴居人将其彻底摧毁前，你那沦陷家园的一丝存留。"},sec={{t="来自大教堂的恳求",b="萨尔努修士在暴风城照料着来往的旅客，他分享了一个在侏儒难民中酝酿的不幸困境。Tinkmaster Overspark——诺莫瑞根奇迹背后的天才之一——对于Techbot的腐化感到心烦意乱，那曾是一个忠实服务于修补匠的机械仆从，直到城市陷入废墟。"},{t="前往Tinker Town",b="该任务派遣热心人士通过矿道地铁前往铁炉堡繁华的Tinker Town飞地。在那里，Overspark正急切地寻找足够勇敢的冒险者，深入诺莫瑞根受辐射的大厅，在构装体造成不可挽回的伤害之前，抢救Techbot剩余的机能。"}},faq={{q="Tinkmaster Overspark是谁？",a="Tinkmaster Overspark是一位侏儒工程师，也是侏儒工程学的训练师。目前驻扎在铁炉堡的Tinker Town，他孜孜不倦地协调收复工作，并从他们被毁的首都中抢救流失的侏儒科技。",al={"overspark","谁是overspark","tinkmaster overspark"}},{q="谁发布了这个任务？",a="萨尔努修士，一位位于暴风城的人类牧师，将这个任务交给冒险者，指引他们前往铁炉堡援助那些需要帮助的侏儒。",al={"任务发布者","如何获取tinkmaster overspark的任务"}},{q="Techbot是什么？",a="Techbot是Tinkmaster Overspark设计的一个机械创造物。它曾是侏儒工程师们得力而友好的工具，但在诺莫瑞根灾难性陷落后发生故障，并在受辐射的城市中失控。",al={"techbot","techbot发生了什么"}},{q="在哪里可以找到Tinkmaster Overspark？",a="Overspark居住在铁炉堡东区的侏儒区Tinker Town，周围满是避难的修补匠同僚和实验性机器。",al={"overspark位置","overspark在哪里"}},{q="与Overspark交谈后会发生什么？",a="向Overspark报告后，他会提供任务“拯救Techbot的大脑！”，要求你深入诺莫瑞根停用Techbot，并取回它的记忆核心以便进行修复。",al={"下一个任务","拯救techbot的大脑"}},{q="为什么联盟会对一个发明家的坏机器感兴趣？",a="除了对流亡侏儒的同情之外，诺莫瑞根内徘徊的失控自动机对任何试图收复地下首都或保护丹莫罗边境的探险队构成了直接威胁。",al={"为什么要在意techbot","techbot的重要性"}}},fp="20,235,25.293.0,14.259.0,28.211.0,22.91.0,16.197.0,40.151.0,41.136.0,63.172.0"}
P.entries["quest:2924"] = {n="基础模组",s="“基础模组”是联盟的一项任务，由位于铁炉堡Tinker Town的Klockmort Spannerspan发布。冒险者们受命深入诺莫瑞根那充满辐射的废墟，回收在侏儒仓促撤离时被遗弃的关键通用组件。",h="“基础模组”是联盟的一项任务，由位于铁炉堡Tinker Town的Klockmort Spannerspan发布。冒险者们受命深入诺莫瑞根那充满辐射的废墟，回收在侏儒仓促撤离时被遗弃的关键通用组件。",kw={"人造物外推器","基础模组","诺莫瑞根","侏儒工程学","铁炉堡","klockmort spannerspan","tinker town"},ang={["faction:Alliance"]="协助流亡的侏儒收回他们失落的技术，能够增强铁炉堡内联盟的技术基础。",["profession:Engineering"]="每一位工程师都明白缺少一个通用组件的痛苦；回收这些设备突显了诺莫瑞根沦陷前工艺的纯粹复杂性。",["race:Gnome"]="回收这些组件关系到民族自尊心和技术传承，确保流亡在铁炉堡并不会阻碍侏儒的独创性。"},sec={{t="被遗忘在大迁徙中",b="当穴居人入侵淹没了诺莫瑞根，有毒的辐射充斥了它的走廊时，逃亡的侏儒只能带走手头能拿到的东西。在无数被留下的奇迹中，包括了“基础模组”的储备——这是一种深受工匠和技师青睐的、近乎通用的专业机械组件。如今，在大师级技师Klockmort Spannerspan在铁炉堡Tinker Town开展工作时，他开创性的新实验因缺乏这些组件而陷入停滞。"},{t="探索外推器",b="这些至关重要的设备被存放在名为“人造物外推器”的重型蒸汽动力存储单元中，位于这座沦陷城市深处。回收它们需要勇闯充满辐射的大厅，那里爬满了变异的麻风侏儒、故障的防御自动机和野性的穴居人。回收十二个组件的储备能让Klockmort恢复他关键的工作，推动侏儒的创新，尽管他们流亡在外。"}},faq={{q="什么是基础模组？",a="基础模组是侏儒工程师开发的一种近乎通用的机械组件。它深受技师和铁匠的重视，是制造复杂装置和先进实验机械的关键基石。",al={"什么是基础模组","基础模组","这是什么"}},{q="谁发布了“基础模组”任务？",a="该任务由侏儒工程师Klockmort Spannerspan发布，他位于铁炉堡的Tinker Town。",al={"任务发布者","谁开启此任务","在哪能找到基础模组"}},{q="基础模组在诺莫瑞根的什么地方可以找到？",a="它们被存放在诺莫瑞根深处的容器中，这些容器被称为“人造物外推器”，看起来像分散在下层大厅各处的高大蒸汽动力橱柜或壁橱。",al={"它们在哪","外推器位置","如何找到基础模组"}},{q="它们为什么会被遗弃在诺莫瑞根？",a="在穴居人突然入侵和随后的放射性灾难期间，侏儒们在极度恐慌中逃离了他们的首都。在撤离的混乱中，这些关键组件的储备被留在了下层车间里。",al={"为什么会被遗弃","为什么它们在诺莫瑞根","基础模组的背景故事"}},{q="Klockmort需要它们做什么？",a="Klockmort Spannerspan需要大量这些通用组件来为他准备在铁炉堡车间进行的一系列复杂新实验提供动力。",al={"klockmort为什么想要它们","klockmort的计划"}},{q="接取此任务前是否需要完成“Klockmort的必需品”？",a="虽然快递任务“Klockmort的必需品”会为你引荐Klockmort并指引你前往他的车间，但这并不是接取“基础模组”任务的严格前提。",al={"前置条件","前置","是否需要完成klockmort的必需品"}}},fp="21,215,23.375.0,25.343.0,32.217.0,42.94.0,56.169.0,40.160.0,34.109.0,60.136.0"}
P.entries["quest:2925"] = {n="帮助科劳莫特",s="“Klockmort's Essentials”是一份传唤，传达了暗夜精灵Mathiel发给他的侏儒朋友Klockmort Spannerspan的紧急消息。因为无法擅离职守前往丹莫罗，Mathiel请求过往的联盟冒险者前往铁炉堡，回应Klockmort的求助。这份请求指引冒险者前往工匠区，为深入诺莫瑞根受辐射的大厅的危险旅程做准备。",h="“Klockmort's Essentials”是一份传唤，传达了暗夜精灵Mathiel发给他的侏儒朋友Klockmort...",kw={"essential artificials","诺莫瑞根","铁炉堡","klockmort spannerspan","klockmort's essentials","麻风侏儒","mathiel","工匠区"},ang={["faction:Alliance"]="这个任务架起了联盟领土遥远地区之间的桥梁，将暗夜精灵的土地与矮人的铁炉堡山中大厅连接起来，共同防御。",["race:Gnome"]="对于侏儒来说，任何指引冒险者前往工匠区的跑腿任务，都有助于他们为收复失落的家园诺莫瑞根而进行的绝望且持续的斗争。"},sec={{t="跨越大陆的呼唤",b="即便在动荡时期，消息也能传得很远。当Klockmort Spannerspan发现自己需要勇敢的盟友去执行前往诺莫瑞根的任务时，他跨越海洋向他的暗夜精灵熟人Mathiel寻求帮助。Mathiel受限于自己的岗位，无法亲自前往这座山中王国，但他不愿对朋友的请求置之不理。于是，他转而向在达纳苏斯的战士区拜访他的有能力的联盟冒险者求助，请他们代他前往丹莫罗。"},{t="前往工匠区之路",b="Klockmort Spannerspan在铁炉堡的工匠区工作，这里是喧闹的难民区，自那座地下城市发生灾难性陷落以来，流离失所的侏儒们便聚集于此。在齿轮的嗡嗡声和蒸汽云中，Klockmort正在制定计划，以取回遗留在诺莫瑞根受污染的走廊中的重要机械。接受Mathiel的推荐会将冒险者直接引向Klockmort的工坊，使他们加入他的收复工作。"}},faq={{q="谁给予“Klockmort's Essentials”任务？",a="该任务由Mathiel提供，他是一位暗夜精灵，收到了他的侏儒朋友Klockmort Spannerspan的消息。Mathiel无法亲自前往铁炉堡，因此他请求值得信赖的联盟冒险者代他前往。",al={"任务给予者","谁开启了klockmort's essentials","mathiel任务"}},{q="我在哪里可以找到Klockmort Spannerspan？",a="Klockmort Spannerspan居住在铁炉堡的工匠区。他位于那些因失去家园而流离失所的侏儒们建立的工坊和难民设施之中。",al={"klockmort在哪里","klockmort的位置","铁炉堡的klockmort spannerspan"}},{q="为什么Klockmort需要在诺莫瑞根寻求帮助？",a="诺莫瑞根被入侵，并因有毒辐射而荒废，到处都是穴居人、疯狂的麻风侏儒和失控的自动装置。Klockmort需要无畏的冒险者去面对这些危险，并从废墟中取回重要的机械零件。",al={"klockmort想要什么","为什么进行诺莫瑞根任务","klockmort的目的"}},{q="这个任务是进入诺莫瑞根所必需的吗？",a="不，这只是一个可选的引导任务，将你从Mathiel直接引向Klockmort Spannerspan。即使没有Mathiel的介绍，你也可以在铁炉堡与Klockmort交谈并直接接受他的地下城任务。",al={"这个任务是强制的吗","诺莫瑞根的前置任务","我可以跳过klockmort's essentials吗"}},{q="“Klockmort's Essentials”之后的任务是什么？",a="与Klockmort Spannerspan交谈可完成此项跑腿任务，并立即引出任务“Essential Artificials”，该任务指引冒险者深入诺莫瑞根地下城。",al={"下一个任务","后续任务","essential artificials的后续"}},{q="为什么Mathiel会有兴趣帮助铁炉堡的侏儒？",a="Mathiel和Klockmort是多年的私交好友。尽管Mathiel驻守在遥远的地方，无法擅离职守，但他对朋友的关心驱使他寻找值得信赖的人去伸出援手。",al={"mathiel的联系","为什么mathiel关心","mathiel和klockmort"}}},fp="22,166,24.294.0,22.296.0,43.175.0,38.152.0,43.184.0,43.150.0,42.121.0,58.162.0"}
P.entries["quest:2926"] = {n="诺恩",s="“诺莫瑞根毒液”是奥齐·电环在卡拉诺斯提供的一项联盟任务。奥齐试图合成一种针对麻风侏儒的治疗剂——或者说，他只是想调制一种极其烈性的饮料——于是他委托冒险者前往诺莫瑞根，从发光的穴居人身上收集放射性尘埃。",h="“诺莫瑞根毒液”是奥齐·电环在卡拉诺斯提供的一项联盟任务。奥齐试图合成一种针对麻风侏儒的治疗剂——或者说，他只是想调制一种极其烈性的饮料——于是他委托冒险者前往诺莫瑞根，从发光的穴居人身上收集放射性尘埃。",kw={"诺恩","诺莫瑞根毒液","诺莫瑞根","绿色荧光","受辐射的穴居人","卡拉诺斯","麻风侏儒","奥齐·电环","铅瓶","辐射"},ang={["faction:Alliance"]="从诺莫瑞根泄漏出的污染威胁着整个丹莫罗，因此任何试图了解或中和这些放射性尘埃的行为对于区域安全来说都至关重要。",["profession:Engineering"]="使用屏蔽铅瓶处理原始放射性径流，展现了侏儒们典型的、高风险的实地科学实验方式。",["race:Gnome"]="对于流亡的侏儒来说，寻找任何能够治愈受辐射同胞的方法的渴望，使得即使是奥齐这种近乎疯狂的实验也值得一试。"},sec={{t="解药还是鸡尾酒",b="自从诺莫瑞根陷落以来，像诺恩这样的难民就一心想要铲除穴居人入侵者，并扭转导致他们同胞发生突变的放射性感染。相比之下，奥齐·电环和他的搭档拉兹·滑链在卡拉诺斯的工作室里采取的方法则显得不那么正统。虽然奥齐声称是在为麻风侏儒寻找解药，但他毫不避讳地承认，他们的实验配方很可能最终只是调制出一种味道特别冲的朗姆酒。"},{t="采集荧光",b="为了改进他们的混合物，发明家们需要直接从灾难中心获取原始的毒性残留物。奥齐给冒险者装备了一个铅制收集瓶，并派遣他们前往诺莫瑞根的破损隧道。在那里，游荡的受辐射入侵者和掠夺者——那些浸透了泄漏废料的穴居人——身上散发着收集瓶所需的、令人作呕的绿色能量。"},{t="头发与美好的希望",b="在获得装满绿色荧光物质的药瓶后，奥齐立刻着手进行活体试验。除了希望恢复一名被俘虏的麻风侏儒的理智和健康外，这位修补匠对这种药剂还怀有个人私心，他相信这种放射性混合物或许也能奇迹般地治愈他的秃顶。"}},faq={{q="谁发布了“诺莫瑞根毒液”任务？",a="该任务由驻扎在丹莫罗卡拉诺斯的侏儒修补匠奥齐·电环发布。",al={"谁发布诺莫瑞根毒液","诺莫瑞根毒液任务发布者","奥齐·电环任务"}},{q="我需要为这个任务收集什么？",a="你必须对诺莫瑞根外部通道中那些发光的、受辐射的穴居人（特别是受辐射的入侵者或受辐射的掠夺者）使用空铅瓶，直到瓶子装满放射性尘埃。",al={"诺莫瑞根毒液目标","诺莫瑞根毒液收集什么","装满的铅瓶"}},{q="我在哪里可以找到受辐射的穴居人？",a="它们位于诺莫瑞根副本入口前的外部洞穴和蜿蜒大厅中，你无需踏入地下城内部即可完成任务。",al={"受辐射的穴居人在哪里","诺莫瑞根毒液穴居人位置","受辐射的入侵者位置"}},{q="我在接取此任务前必须完成“事发之后”吗？",a="不需要。虽然“事发之后”在剧情上与卡拉诺斯的局势相关并引出该任务，但奥齐会独立提供“诺莫瑞根毒液”。",al={"事发之后是前置任务吗","诺莫瑞根毒液前提"}},{q="奥齐试图用放射性尘埃达成什么目的？",a="奥齐声称他和拉兹正在尝试为麻风侏儒研制解药，尽管他也承认调制出的东西可能只是一种高纯度的朗姆酒。私下里，他还希望这种药剂能让他重新长出头发。",al={"奥齐为什么要放射性物质","诺莫瑞根毒液的用途"}},{q="“诺莫瑞根毒液”之后的任务是什么？",a="上交装满的药瓶后，后续任务是“唯一的解药是更多的绿色荧光”，该任务需要深入诺莫瑞根内部。",al={"诺莫瑞根毒液后续","诺莫瑞根毒液之后是什么"}}},fp="8,183,20.360.0,19.298.0,19.200.1,30.65.0,41.146.0,39.164.0,63.128.0,64.118.0,28.95.0"}
P.entries["quest:2927"] = {n="灾难之后",s="“大难之后”是一项联盟任务，它将铁炉堡的幸存者与驻扎在丹莫罗的研究员联系在了一起。诺恩因那场导致他失去了传奇秀发和家园的灾难性辐射泄漏而悲痛万分，他派遣冒险者前往卡拉诺斯协助奥齐·电环寻找解决方案。",h="“大难之后”是一项联盟任务，它将铁炉堡的幸存者与驻扎在丹莫罗的研究员联系在了一起。诺恩因那场导致他失去了传奇秀发和家园的灾难性辐射泄漏而悲痛万分，他派遣冒险者前往卡拉诺斯协助奥齐·电环寻找解决方案。",kw={"诺恩","侏儒爆炸头","诺莫瑞根","卡拉诺斯","奥齐·电环","辐射泄漏","大难之后","穴居人"},ang={["faction:Alliance"]="联盟英雄协助丹莫罗的侏儒思想家们遏制威胁着这座山脉王国的奇异生化灾难。",["profession:Engineering"]="奥齐·电环的努力凸显了侏儒工匠在面对失控的科技灾难时所采用的试错方法。",["race:Gnome"]="对于侏儒而言，诺恩那独特的哀叹捕捉到了每一位被驱逐出奇迹之都的难民心中那份深沉的悲剧、古怪的自豪感以及苦涩的复仇心理。"},sec={{t="悲惨的损失",b="诺莫瑞根的陷落给每一位幸存者都留下了深重的创伤，诺恩也不例外。作为铁炉堡Tinker Town的一名难民，诺恩不仅哀悼被穴居人入侵者窃取的机械仙境，还哀悼他那珍贵的侏儒爆炸头——当一股有毒尘埃喷涌而出击中他时，这头引以为傲的秀发瞬间掉光了。怀着对穴居人的余怒和收复城市的绝望希望，他指引同情的旅行者去寻找那些可能仍有科学能力挽救残局的同事们。"},{t="通往卡拉诺斯之路",b="诺恩没有屈服于绝望，而是将联盟的勇士们指向了卡拉诺斯，那里富有创造力的思想家们已经开始着手应对辐射尘埃。其中最主要的是奥齐·电环，他正与搭档拉兹·滑链并肩作战。奥齐清晰地记得那场灾难的可怕时刻，回想起诺恩的头发是如何成簇脱落，而疯狂和复仇的渴望又是如何占据了他的内心。现在，在冰雪覆盖的城镇相对安全的庇护下，奥齐将他那工程学天才用于分析污染，希望能找到解毒剂。"}},faq={{q="诺恩是谁？",a="诺恩是铁炉堡Tinker Town里的一名侏儒难民。由于穴居人入侵和城市放射性废料泄露灾难，他感到极度痛苦，尤其是对自己曾经引以为傲的侏儒爆炸头的突然失去感到无比受挫。",al={"诺恩","秃头侏儒","谁发布大难之后任务"}},{q="为什么诺恩要让你去找奥齐·电环？",a="诺恩相信拯救诺莫瑞根还有希望。奥齐·电环和他的搭档拉兹驻扎在卡拉诺斯，正在对附着在城市上的有毒辐射进行研究，并试图研制出治疗方法。",al={"为什么要去找奥齐","奥齐·电环任务","卡拉诺斯工程师"}},{q="诺莫瑞根发生了什么导致了这一切？",a="在野蛮的穴居人进行大规模地下入侵期间，大工匠Gelbin Mekkatorque听从了建议，将放射性有毒废料排入下层大厅以消灭敌人。这个计策悲剧性地失败了，导致无数侏儒变异或死亡，并使这座科技之城在未能彻底消灭穴居人的情况下变得不再适合居住。",al={"诺莫瑞根发生了什么","为什么诺莫瑞根有辐射","穴居人入侵"}},{q="到达奥齐那里后，这个任务链会引向何处？",a="向奥齐报到将开启任务“诺姆药剂”，奥齐会要求你直接从诺莫瑞根外的受辐射穴居人身上收集放射性尘埃，以测试实验性的中和混合剂。",al={"大难之后后续","大难之后之后是什么","下一个任务"}}},fp="13,196,13.310.0,20.381.0,14.200.0,45.194.0,42.273.0,54.170.0"}
P.entries["quest:2928"] = {n="陀螺式挖掘机",s="在暴风城的Dwarven District深处，沉默的舒尼正在准备一支巨大的钻地机车队，打算将它们运往丹莫罗。由于机械零件短缺，她的工作陷入了停滞，于是她派遣冒险者进入诺莫瑞根受辐射的废墟中，从失控的自动机械身上搜集完好的齿轮和内部零件。",h="在暴风城的Dwarven...",kw={"丹莫罗","dwarven district","挖掘机","诺莫瑞根","侏儒工程学","旋风钻地","robo-mechanical guts","沉默的舒尼"},ang={["faction:Alliance"]="在暴风城支援侏儒的挖掘后勤工作，加强了作为主人的人类与致力于收复家园的流亡幸存者之间的联系。",["profession:Engineering"]="从倒下的诺莫瑞根仆从身上拆解高精度的钟表内部结构，是学习先进侏儒设计和重型机械修理的实践课。",["race:Gnome"]="每一件打捞上来的组件都让舒尼的地下车队离可用状态更近了一步，这让收复失地和工业复兴的梦想在暴风城内得以延续。"},sec={{t="急需零件的车队",b="在暴风城的Dwarven District，侏儒工程师们正在不懈努力，支援他们流离失所的同胞。沉默的舒尼就是其中之一，她负责一项雄心勃勃的地下工程：一支目的地为丹莫罗的旋风钻地机车队。这个项目正面临着关键的瓶颈，因为她缺少让这些巨大的挖掘设备运转所需的必要部件。"},{t="在堕落之城的打捞行动",b="与其从头锻造新零件，舒尼将目光直接投向了侏儒高科技的源头：诺莫瑞根这座失落的城市。废墟和周围的隧道里爬满了故障的防御机器人、机械哨兵和无人看管的钟表工匠。冒险者们被派往那里，拆解这些失控的机器，并将两打Robo-Mechanical Guts带回人类领地。"},{t="一项伟大的事业",b="带回两打机械内部零件所提供的废料，仅够拼凑出一台挖掘机。面对车队中剩余的近四百台机器，舒尼那建立大规模地下运输系统的梦想依然是一项艰巨且进度极其缓慢的工程。即便如此，每一台能够正常运转的机器都代表着向收复在诺莫瑞根灾难中失去的领土迈出了一小步。"}},faq={{q="什么是旋风钻地机？",a="它们是重型侏儒隧道挖掘机或钻地机，专为地下挖掘和运输而设计。沉默的舒尼正试图组装一支完整的钻地机车队，以便将人员或补给运往丹莫罗。",al={"旋风钻地机","什么是挖掘机","侏儒钻地机"}},{q="沉默的舒尼是谁？",a="舒尼是一位驻扎在暴风城Dwarven District的侏儒工程师。尽管她有个“沉默”的绰号，但她其实是一位直言不讳、要求严格的监工，一心想要修复数百台机械挖掘机。",al={"沉默的舒尼","舒尼","谁是舒尼"}},{q="为什么舒尼特别需要诺莫瑞根的零件？",a="诺莫瑞根到处都是失控的自动机械、钟表仆从和防御机甲。由于城市陷落时标准的制造业供应链被切断，这些失控的机器人成为了目前最丰富的、可兼容的侏儒备用零件来源。",al={"为什么要诺莫瑞根的零件","为什么要机器人内部零件","诺莫瑞根打捞"}},{q="Robo-Mechanical Guts在哪里可以找到？",a="这些可打捞的内部零件可以从诺莫瑞根走廊里游荡的机械哨兵、钟表构装体和其他敌对生物身上搜集，无论是在受损的设施内部还是在其上层的隧道入口处。",al={"robo-mechanical guts","哪里获取内部零件","诺莫瑞根机械内部零件"}},{q="修理好一台机器就能完成舒尼的车队吗？",a="不能。两打机械内部零件只够修理一台挖掘机。在交付零件时，舒尼指出她还有398台挖掘机需要修理。",al={"挖掘机有多少","舒尼车队规模","钻地机有多少"}},{q="为什么要为丹莫罗准备一支挖掘车队？",a="丹莫罗是侏儒的祖居地，也是他们陷落的首都所在地。准备重型隧道挖掘机可以提供一种在白雪皑皑的山区进行挖掘、清理碎石并支援行动的方法。",al={"前往丹莫罗的车队","为什么是丹莫罗","挖掘机的用途"}}},fp="30,178,23.289.0,26.332.0,24.290.0,40.208.0,25.146.0,55.250.0,41.172.0,45.115.0,57.182.0"}
P.entries["quest:293"] = {n="净化帕雷斯之眼",s="“净化之眼”是一个联盟任务，它指引探险者从阴暗的The Marshlands出发，前往人类首都暴风城。在找回被称为帕雷斯之眼的受诅咒宝珠后，旅行者必须寻求大主教本尼迪塔斯帮助，以清除其残留的污秽。",h="“净化之眼”是一个联盟任务，它指引探险者从阴暗的The Marshlands出发，前往人类首都暴风城。在找回被称为帕雷斯之眼的受诅咒宝珠后，旅行者必须寻求大主教本尼迪塔斯帮助，以清除其残留的污秽。",kw={"大主教本尼迪塔斯","cathedral of light","净化之眼","被诅咒的帕雷斯之眼","帕雷斯之眼","戈罗林·钢眉","暴风城","湿地"},ang={["class:Paladin"]="圣骑士将从黑暗沼泽中回收圣物视为一项庄严的职责，他们认为帕雷斯之眼的腐蚀是对圣光的一种亵渎，必须在暴风城神圣的大厅内将其净化。",["class:Priest"]="对于圣光教会的牧师来说，处理被诅咒的帕雷斯之眼展现了神圣工艺在绝望面前是多么脆弱易变，这突显了大主教本尼迪塔斯的净化干预是何等重要。",["faction:Alliance"]="该任务突显了The Marshlands的矮人前哨与暴风城精神领袖之间的合作，通过共同的信仰将王国紧密联系在一起。"},sec={{t="受玷污的圣物",b="从沼泽地找回的帕雷斯之眼不再闪耀着圣洁的光辉。相反，它沉浸在令人不安的阴影之中，承载着它失落之地所发生的悲剧带来的残留悲伤与创伤。矮人戈罗林·钢眉认出了这颗宝珠的力量，但他承认自己缺乏解除这种沉重折磨的神圣技艺。"},{t="前往大教堂",b="由于帕雷斯之眼最初是由人类圣光教会的牧师铸造的，只有他们最高阶层的成员才拥有消除这种玷污的知识。戈罗林指引探险者前往暴风城，将这颗黯淡的宝珠呈献给圣光教会的领袖大主教本尼迪塔斯。本尼迪塔斯认识到未经净化的圣物蕴含着巨大的危险，并亲自担负起恢复其神圣光辉的责任。"}},faq={{q="什么是帕雷斯之眼？",a="帕雷斯之眼是由人类牧师铸造的神圣宝珠，旨在散发出圣洁的光辉。当未受玷污时，它们的力量与圣光相契合；但若受到腐蚀，它们周围的能量就会变得不稳定且危险。",al={"帕雷斯之眼背景故事","这颗宝珠是什么","什么是帕雷斯之眼"}},{q="为什么戈罗林·钢眉不能亲自净化这只眼睛？",a="戈罗林·钢眉是一位驻扎在The Marshlands的矮人，他不具备驱逐这种黑暗折磨所需的专业礼仪技巧。由于该圣物是由人类圣光教会的牧师所造，解除其腐蚀需要该传统的权威人士出手。",al={"为什么要派我去暴风城","戈罗林净化","为什么是本尼迪塔斯"}},{q="谁是大主教本尼迪塔斯？",a="大主教本尼迪塔斯是圣光教会受人尊敬的领袖，居住在暴风城宏伟的Cathedral of Light中。他是联盟精神指引的支柱。",al={"谁是本尼迪塔斯","大主教本尼迪塔斯","暴风城大主教"}},{q="为什么这只眼睛被描述为肮脏或悲伤的？",a="根据大主教本尼迪塔斯的说法，这颗宝珠见证了The Marshlands发生的一起巨大的悲剧事件，随着时间的推移吸收了那种痛苦。这种残留的悲伤转化为了腐蚀性的诅咒，扭曲了圣物原本的力量。",al={"为什么它会被诅咒","帕雷斯之眼悲剧","被诅咒的帕雷斯之眼"}},{q="本尼迪塔斯收到宝珠后会发生什么？",a="本尼迪塔斯同意执行净化仪式。他警告说，帕雷斯之眼本应闪耀着光芒，而让这样的神器保持受玷污的状态，会对周围的人造成严重的精神和身体威胁。",al={"本尼迪塔斯净化了它吗","帕雷斯之眼的结局"}},{q="Cathedral of Light位于何处？",a="Cathedral of Light矗立在暴风城北区的Cathedral Square。大主教本尼迪塔斯就站在圣所中心的主祭坛前。",al={"cathedral of light在哪里","cathedral of light位置","寻找本尼迪塔斯"}}},fx={["6f168d84"]={q="戈罗林·钢眉为什么想净化帕雷斯之眼？",a="戈罗林知道，被诅咒的帕雷斯之眼是一件极其危险的圣物。它由人类圣光牧师创造，原本能够绽放明亮光芒；但一旦遭遇悲剧和黑暗力量的污染，其魔力便会变得危险而具有腐蚀性。矮人工艺和他自己的本领都无法消除这种灵性诅咒，因此他坚持要把它送到暴风城，以免腐化之力继续伤害你或周围的土地。",al={"为何净化帕雷斯之眼","戈罗林·钢眉的动机","为何把帕雷斯之眼送去暴风城"}}},fp="17,203,15.267.0,24.379.0,26.194.0,51.224.0,29.168.0,48.180.0,46.160.0,40.167.0"}
P.entries["quest:2930"] = {n="抢救数据",s="当地精撤离他们那辐射遍地的首都时，大量关键的技术知识和记录被遗弃在了那里。铁炉堡的大机械师卡斯派普招募大胆的特工潜入诺莫瑞根，并取回一张高安全级别的彩色穿孔卡片。为了穿过层层的计算机权限验证，快递员必须在被废弃的城市深处，一路打通那些逐步强化的终端。",h="当地精撤离他们那辐射遍地的首都时，大量关键的技术知识和记录被遗弃在了那里。铁炉堡的大机械师卡斯派普招募大胆的特工潜入诺莫瑞根，并取回一张高安全级别的彩色穿孔卡片。为了穿过层层的计算机权限验证，快递员必须在被废弃的城市深处...",kw={"卡斯派普","数据救援","engineering labs","诺莫瑞根","矩阵打孔机","彩色穿孔卡片","穿孔卡片","tinker town","train depot"},ang={["faction:Alliance"]="支持卡斯派普的回收工作有助于帮助在铁炉堡流离失所的地精政府，并加强大联盟内部的团结和技术实力。",["profession:Engineering"]="矩阵打孔机网络展示了极其完善的自动化数据存储技术，体现了Tinkers' Court设计的复杂算法清除机制。",["race:Gnome"]="从诺莫瑞根回收数据代表着收回被窃的遗产。每一张回收的穿孔卡片都能确保你们陷落之城的创造力得以保存，而不是随着穴居人和辐射一起消失。"},sec={{t="地下室遗失的档案",b="诺莫瑞根因穴居人入侵和致命辐射而突然陷落，迫使地精民众放弃了数百年的先进研究、蓝图和市政日志。散布在各个技术走廊中的是矩阵打孔机终端，这些自动化数据中心负责监管安全许可和文件存储。对于像大机械师卡斯派普这样的流亡领袖来说，从这些废墟深处恢复这些编码档案，是Tinker Town难民社区最优先考虑的事项之一。"},{t="穿孔的层级",b="地精的数据协议要求在授予中央主机访问权限之前，必须进行严格的验证。操作该系统需要从内门外废墟中找到的一张白色穿孔卡片开始。将其插入Train Depot的矩阵打孔机3005-A，会生成一张黄色卡片，然后必须将其带入宿舍区的3005-B终端进行蓝色升级，再通过3005-C型号升级为红色卡片，最后带入Engineering Labs进行编码，最终获得梦寐以求的彩色穿孔卡片。"},{t="二进制里的地精式幽默",b="虽然卡斯派普将这项任务视为极其紧迫的市政要务，但实际的穿孔卡片上记录的二进制数据流，却揭示了诺莫瑞根计算行会那些古怪且玩世不恭的想法。在真实的技术数据中，这些穿孔模式翻译出来是一些幽默的俏皮话、荒诞的职场抱怨，以及关于大工匠Gelbin Mekkatorque穿着暗夜精灵内衣的低俗笑话——这表明即使在高科技基础设施的核心地带，地精工程师们也总是忍不住要搞点恶作剧。"}},faq={{q="什么是彩色穿孔卡片？",a="彩色穿孔卡片是诺莫瑞根自动化主机所认可的最高级别安全数据卡。它是在Engineering Labs深处的矩阵打孔机3005-D终端处处理一张红色穿孔卡片后创建的。",al={"彩色穿孔卡片","什么是穿孔卡片","诺莫瑞根穿孔卡片"}},{q="穿孔卡片的序列从哪里开始？",a="该序列从一张基础的白色穿孔卡片开始，这张卡片是从副本入口外、Train Depot附近的穴居人和机械残骸中回收的。",al={"白色穿孔卡片哪里获取","如何开始穿孔卡片任务","第一张穿孔卡片"}},{q="矩阵打孔机终端位于何处？",a="3005-A型号位于副本外的Train Depot。3005-B型号位于Clean Zone后的宿舍区内。3005-C型号位于前方的猫道平台上，而3005-D型号则位于Engineering Labs的下层。",al={"终端位置","矩阵打孔机在哪里","穿孔卡片机器"}},{q="大机械师卡斯派普是谁？",a="大机械师卡斯派普是一位居住在铁炉堡Tinker Town难民当中的资深地精工程师。为了挽救诺莫瑞根的知识遗产，他极力组织前往这座陷落之城的侦察和回收任务。",al={"卡斯派普","谁发布数据救援任务","卡斯派普背景故事"}},{q="卡片上到底有什么数据？",a="当从原始ASCII二进制翻译过来时，这些穿孔卡片包含的内容包括地精工程学的调侃、关于像萨尔和Mekkatorque这样地区领袖的轻松玩笑，以及除了城市关键计算数据之外的一些古怪注释。",al={"卡片文本","二进制翻译","二进制说了什么"}},{q="部落玩家可以访问这些终端吗？",a="这项任务本身仅向联盟玩家提供，由铁炉堡的大机械师卡斯派普发布，尽管从技术上讲，副本内的实体打孔机终端可以被任何携带必要卡片的玩家操作。",al={"部落数据救援","部落穿孔卡片","部落能用终端吗"}}},fp="11,210,32.373.0,27.423.0,24.288.1,33.186.0,45.138.0,51.234.0,32.192.0,35.163.0,41.165.0"}
P.entries["quest:2931"] = {n="卡斯派普的任务",s="“卡斯派普的任务”是联盟的一项征召，旨在指引有能力的冒险者前往铁炉堡寻找大机械师卡斯派普。卡斯派普正在协调针对诺莫瑞根受辐射废墟的危险打捞行动，以提取至关重要的机械与技术记录。这是一份官方简报，指引雇佣兵前往这座沦陷的城市内部执行深入回收任务。",h="“卡斯派普的任务”是联盟的一项征召，旨在指引有能力的冒险者前往铁炉堡寻找大机械师卡斯派普。卡斯派普正在协调针对诺莫瑞根受辐射废墟的危险打捞行动，以提取至关重要的机械与技术记录。这是一份官方简报，指引雇佣兵前往这座沦陷的城...",kw={"学会","卡斯派普","数据救援","加克希姆","诺莫瑞根","铁炉堡","尘链","技师区"},ang={["faction:Alliance"]="协助流离失所的侏儒盟友保住他们遗失的档案，有助于稳定技师区，并加强联盟整体的技术地位。",["profession:Engineering"]="诺莫瑞根内的数据核心拥有艾泽拉斯其他任何地方都无法比拟的计算奇迹和先进蓝图。",["race:Gnome"]="每一次回收行动都代表着你那陷落家园的一小部分得以从辐射和毁灭中保存下来，这使得卡斯派普的任务成为了关乎文化存亡的大事。"},sec={{t="召唤技师区",b="在诺莫瑞根不幸陷落并随后因辐射被隔离之后，幸存的侏儒们在铁炉堡的技师区找到了避难所。尽管他们伟大的家园仍被穴居人和受辐射的构装体占据，但至关重要的操作记录和机械蓝图仍深埋在城市尚存的计算阵列中。大机械师卡斯派普意识到这些文件对于夺回或了解真相至关重要，于是开始积极招募愿意深入有毒大厅的勇敢外来者。"},{t="协会的认可",b="有关卡斯派普行动的消息由“奥术、炼金与工程科学启蒙协会”的加克希姆·尘链等人传播。虽然卡斯派普本人并非这一杰出学术团体的成员，但侏儒同胞们非常尊重他的技术头脑，足以认可这项工作。尘链自己的计算显示，卡斯派普的任务具有极高战略价值的概率高达84%，这促使旅行者们前往技师区接受命令。"}},faq={{q="大机械师卡斯派普是谁？",a="大机械师卡斯派普是一位受人尊敬的侏儒工程师，常驻铁炉堡的技师区。他负责组织打捞小队和数据回收行动，重点关注诺莫瑞根的地下废墟。",al={"卡斯派普","卡斯派普是谁","大机械师卡斯派普"}},{q="为什么卡斯派普想要诺莫瑞根的数据？",a="诺莫瑞根遭到污染并撤离时，海量的关键技术知识、蓝图和内部系统日志都被遗留在了主机内存中。找回这些信息对于希望重建家园的流离失所的侏儒们来说至关重要。",al={"诺莫瑞根数据","为什么要回收数据","诺莫瑞根记录"}},{q="加克希姆·尘链是谁？",a="加克希姆·尘链是一位隶属于“奥术、炼金与工程科学启蒙协会”的侏儒学者。他担任倡导者和联络人，引导有能力的冒险者参与卡斯派普的回收工作。",al={"加克希姆","尘链"}},{q="在哪里可以找到卡斯派普？",a="大机械师卡斯派普驻扎在铁炉堡东区的技师区，这是侏儒定居的区域。",al={"卡斯派普位置","卡斯派普在哪里"}},{q="向卡斯派普报到后会发生什么？",a="向大机械师卡斯派普报到后，将直接开启一项名为“数据救援”的城市内部任务，冒险者必须深入诺莫瑞根被污染的内部，提取计算机穿孔卡片和存储介质。",al={"后续任务","what comes next","卡斯派普之后"}},{q="什么是奥术、炼金与工程科学启蒙协会？",a="奥术、炼金与工程科学启蒙协会是一个享有盛誉的侏儒知识分子社团，致力于严谨的科学、魔法和机械研究。其成员（如加克希姆·尘链）运用严密的概率分析来评估关键任务。",al={"协会","启蒙协会"}}},fp="15,157,20.417.0,20.356.0,32.167.0,44.217.0,24.190.0,28.111.0,41.184.0,81.231.0"}
P.entries["quest:2932"] = {n="可怕的消息",s="尼姆布亚想要惩罚枯木巨魔，因为他们背叛了萨尔，尽管他们曾经是部落的盟友。尼姆布亚的长矛需要带上枯木巨魔的头颅，并插在辛特兰的一座枯木村中。",h="尼姆布亚想要惩罚枯木巨魔，因为他们背叛了萨尔，尽管他们曾经是部落的盟友。尼姆布亚的长矛需要带上枯木巨魔的头颅，并插在辛特兰的一座枯木村中。",kw={"血色的警告","辛特兰","西利瓦萨","尼姆布亚","塔伦米尔","萨尔","枯木部族","祖瓦沙"},sec={{t="血色的警告",b="枯木巨魔曾经与部落并肩作战，直到他们背叛了萨尔。尼姆布亚交给你一根长矛，派你去遥远的北方——塔伦米尔（被被遗忘者控制的村庄）东北方的辛特兰。去那里猎杀枯木巨魔并收集他们的头颅，然后将长矛插在西利瓦萨或祖瓦沙，这是他们较小的两个村庄，让他们知道背叛的代价。事后，尼姆布亚会在荆棘谷等待。"}},faq={{q="为什么尼姆布亚想要惩罚枯木巨魔？",a="尼姆布亚说他们曾是部落的盟友，却反戈一击背叛了萨尔，这种背叛不可饶恕。",al={"为什么要攻击枯木部族","枯木部族的背叛","血色的警告任务原因"}},{q="尼姆布亚派你去哪里插上长矛？",a="西利瓦萨或祖瓦沙，这是位于辛特兰的两个较小的枯木村庄。",al={"长矛插在哪里","尼姆布亚的长矛位置","血色的警告任务地点"}},{q="辛特兰在塔伦米尔的什么方向？",a="它们位于塔伦米尔（被遗忘者控制的村庄）的东北方，距离在荆棘谷的尼姆布亚很遥远。",al={"辛特兰的位置","辛特兰在哪里"}},{q="谁发布了“血色的警告”？",a="位于荆棘谷的尼姆布亚交给你长矛，并在那里等待消息。",al={"血色的警告任务发布者","尼姆布亚是谁"}}},fp="12,213,18.440.0,54.111.0,46.78.0,43.115.0,23.72.0"}
P.entries["quest:2933"] = {n="毒液瓶",s="在辛特兰的枯木村中，到处都是装着邪恶绿色毒液的瓶子。数量如此之多，说明枯木巨魔非常看重它。附近的塔伦米尔的一位药剂师或许会对样本感兴趣。",h="在辛特兰的枯木村中，到处都是装着邪恶绿色毒液的瓶子。数量如此之多，说明枯木巨魔非常看重它。附近的塔伦米尔的一位药剂师或许会对样本感兴趣。",kw={"药剂师林度恩","蛛形纲生物","辛特兰","塔伦米尔","巨魔毒液","毒液瓶","枯木"},sec={{t="毒性的发现",b="枯木村里的瓶子装着一种邪恶的绿色毒液。数量非常多，枯木巨魔一定认为它很重要。可以将样本带给塔伦米尔的一位药剂师，他可能想看看。"},{t="林度恩的鉴定",b="药剂师林度恩当天所有的实验都失败了，他接过瓶子，断定里面的东西是从某种蛛形纲生物身上提取的毒液。林度恩询问这东西是从哪儿来的。"}},faq={{q="在哪里可以找到毒液瓶？",a="它们就在辛特兰的枯木村里，数量很多。",al={"毒液瓶位置","哪里能找到毒液瓶","枯木毒液"}},{q="谁对这些毒液瓶感兴趣？",a="建议是把样本带给塔伦米尔的一位药剂师，你需要找的是药剂师林度恩。",al={"谁想要毒液","在哪里上交毒液瓶","塔伦米尔药剂师"}},{q="瓶子里装的是什么？",a="一种邪恶的绿色毒液，考虑到枯木巨魔保留了这么多瓶子，他们似乎非常看重它。",al={"毒液是什么","瓶子里有什么"}}},fp="13,193,17.218.0,15.177.1,34.70.0,39.107.0,23.98.0"}
P.entries["quest:2934"] = {n="完好无损的毒囊",s="塔伦米尔的药剂师林度恩需要一份之前送来的那种毒液的新鲜样本，并让你去辛特兰猎杀那些能产生毒液的蜘蛛。时间很紧，因为它必须保持新鲜才能送达。",h="塔伦米尔的药剂师林度恩需要一份之前送来的那种毒液的新鲜样本，并让你去辛特兰猎杀那些能产生毒液的蜘蛛。时间很紧，因为它必须保持新鲜才能送达。",kw={"药剂师林度恩","辛特兰","沙德拉洛","蜘蛛毒液","塔伦米尔","毒液囊"},sec={{t="新鲜样本",b="在收集完“毒液瓶”后，药剂师林度恩想要一些更新鲜的东西。产出这种毒液的蜘蛛一定生活在辛特兰，他需要一个未受损的毒液囊。在巨魔城市沙德拉洛附近游荡着许多这样的蜘蛛。你不能浪费任何时间，因为毒液囊必须在送达时保持新鲜。林度恩急于用它进行实验，并已经订购了几只非常可爱的小动物来做测试。"}},faq={{q="是谁要求获取未受损的毒液囊？",a="塔伦米尔的药剂师林度恩要求获取它，并在那里等待交付。",al={"谁发布未受损的毒液囊任务","谁开启未受损的毒液囊任务","未受损的毒液囊任务发布者"}},{q="在哪里可以找到这些蜘蛛？",a="在辛特兰，在巨魔城市沙德拉洛附近可以找到许多蜘蛛。",al={"蜘蛛位置","蜘蛛在哪里","哪里可以找到未受损的毒液囊"}},{q="为什么药剂师林度恩说不能耽搁？",a="新鲜度至关重要，所以林度恩希望立即送达毒液囊。",al={"为什么有时间限制","为什么毒液囊会变质","未受损的毒液囊计时器"}},{q="这一步之前发生了什么？",a="它接在“毒液瓶”任务之后，在那个任务中，来自枯木村的毒液样本被送交给了林度恩。",al={"前置任务","未受损的毒液囊之前的任务是什么","未受损的毒液囊先决条件"}}},fp="19,192,14.409.0,37.67.0,31.84.0,43.71.0,27.100.0"}
P.entries["quest:2935"] = {n="请教加德林大师",s="药剂师林度恩发现从护巢蛛身上提取的毒液效果不如你最初带来的样本，这说明还有另一种蜘蛛。林度恩让你去找位于杜隆塔尔森金村的加德林大师，他可能知道更多情况。",h="药剂师林度恩发现从护巢蛛身上提取的毒液效果不如你最初带来的样本，这说明还有另一种蜘蛛。林度恩让你去找位于杜隆塔尔森金村的加德林大师，他可能知道更多情况。",kw={"药剂师林度恩","咨询加德林大师","杜隆塔尔","辛特兰","加德林大师","森金村","毒液","枯木"},sec={{t="寻找更强的毒液",b="药剂师林度恩发现从护巢蛛身上提取的毒液效果不如你最初带来的样本，因此它一定来自另一种蜘蛛。林度恩需要一种效果更强的新样本。要了解它的来源，请去询问一位对枯木巨魔非常了解的巨魔：位于杜隆塔尔森金村的加德林大师。如果运气好的话，加德林能说出那种毒液的来源。"}},faq={{q="药剂师林度恩为什么要让你去找加德林大师？",a="护巢蛛毒液比第一份样本要弱，这说明毒液来自不同的蜘蛛。加德林是一位对枯木巨魔非常了解的巨魔，或许能指出毒液的来源。",al={"为什么要咨询加德林","为什么要前往森金","林度恩与加德林"}},{q="加德林大师在哪里？",a="加德林大师位于杜隆塔尔的森金村。",al={"加德林在哪里","加德林大师的位置","寻找加德林大师"}},{q="这个任务之前发生了什么？",a="在此之前，你给药剂师林度恩带去了一个从辛特兰获得的完整毒囊。",al={"前置条件","之前发生了什么","上一个任务"}}},fp="21,224,20.370.0,52.194.0,31.48.0,30.85.0"}
P.entries["quest:2937"] = {n="召唤沙德拉",s="加德林大师给了你一张羊皮纸，要你在辛特兰枯木巨魔领地深处的沙德拉洛祭坛上诵读，以召唤蜘蛛之神沙德拉。随后，你需要将她的毒液带给塔伦米尔的药剂师林度恩。",h="加德林大师给了你一张羊皮纸，要你在辛特兰枯木巨魔领地深处的沙德拉洛祭坛上诵读，以召唤蜘蛛之神沙德拉。随后，你需要将她的毒液带给塔伦米尔的药剂师林度恩。",kw={"药剂师林度恩","辛特兰","加德林大师","沙德拉","沙德拉洛","蜘蛛之神","塔伦米尔","枯木"},sec={{t="蜘蛛之神的召唤",b="加德林大师的羊皮纸需要在辛特兰枯木巨魔领地深处的沙德拉洛祭坛上诵读。这样做可以召唤出蜘蛛之神沙德拉。你必须在那里击败她，并将她的毒液带给塔伦米尔的药剂师林度恩。"}},faq={{q="是谁提供了召唤沙德拉的羊皮纸？",a="加德林大师给了你这张羊皮纸。",al={"谁给了召唤沙德拉的任务","召唤沙德拉的任务发布者"}},{q="在哪里召唤沙德拉？",a="在辛特兰，沙德拉洛的祭坛，位于枯木巨魔领地内部。",al={"在哪里召唤沙德拉","沙德拉洛祭坛位置","沙德拉位置"}},{q="击败沙德拉后，谁会接收毒液？",a="塔伦米尔的药剂师林度恩。",al={"我该把毒液交给谁","召唤沙德拉任务上交地点","药剂师林度恩位置"}}},fp="16,222,22.240.0,44.38.0,25.77.0,47.33.0"}
P.entries["quest:2938"] = {n="送往幽暗城的毒药",s="药剂师林度恩对从枯木巨魔的蜘蛛神身上提取的毒液感到非常满意，他希望将一份样本送到位于幽暗城药剂师区的上级那里，也就是大药剂师法拉尼尔。一个包裹被托付给你，准备送往那里。",h="药剂师林度恩对从枯木巨魔的蜘蛛神身上提取的毒液感到非常满意，他希望将一份样本送到位于幽暗城药剂师区的上级那里，也就是大药剂师法拉尼尔。一个包裹被托付给你，准备送往那里。",kw={"apothecarium","药剂师林度恩","法拉尼尔的包裹","大药剂师法拉尼尔","沙德拉","毒液送到幽暗城"},sec={{t="强效发现",b="林度恩用一剂毒液杀死了近两打兔子。其中一些兔子非常幼小，所以它们的抵抗力肯定很低，但不可否认这种毒药非常强大。林度恩确信法拉尼尔会想要亲自测试它，于是递给你一个包裹，让你送往幽暗城的药剂师区。"}},faq={{q="是谁把包裹送到幽暗城的？",a="药剂师林度恩在测试了从枯木巨魔的蜘蛛神身上取下的毒液后，将其寄出。",al={"谁把毒液送到幽暗城","毒液送到幽暗城任务发布者","谁开启毒液送到幽暗城任务"}},{q="谁应该在幽暗城接收这些毒液？",a="大药剂师法拉尼尔，即林度恩的上级，他位于幽暗城的药剂师区。",al={"谁接收包裹","幽暗城的毒液去往何处","谁是法拉尼尔"}},{q="在测试过程中，这种毒液的效力如何？",a="单剂量就足以杀死近两打兔子，尽管其中一些非常年幼且体型微小。",al={"沙德拉毒液有多强","林度恩兔子测试"}},{q="这次运送之前发生了什么？",a="在此之前是“召唤沙德拉”任务，在该任务中，毒液是从蜘蛛神身上获取的。",al={"毒液送到幽暗城的前置任务","毒液送到幽暗城的前提条件"}}},fp="22,223,13.316.0,43.90.0,54.83.0,40.96.0,32.78.0"}
P.entries["quest:2939"] = {n="寻找知识",s="特洛亚斯·月风在菲拉斯的废墟瓦砾中发现了一根看似普通的法杖，但他总觉得事情没那么简单。他让你去找他在鲁瑟兰村的同事达蕾恩·轻风。",h="特洛亚斯·月风在菲拉斯的废墟瓦砾中发现了一根看似普通的法杖，但他总觉得事情没那么简单。他让你去找他在鲁瑟兰村的同事达蕾恩·轻风。",kw={"安格拉斯","达纳苏斯","达蕾恩·轻风","菲拉斯","废墟","鲁瑟兰村","法杖","特洛亚斯·月风"},sec={{t="一根普通的法杖",b="特洛亚斯·月风说菲拉斯的废墟虽然危险，但却隐藏着关于过去发生的许多事情的秘密。几天前，他在南边的瓦砾中搜寻时，偶然发现了一根看起来很普通的法杖，但他总觉得这根法杖大有来头。他和安格拉斯查阅了所有的书籍，却找不到关于它的一星半点记载。"},{t="达纳苏斯的同事",b="特洛亚斯在达纳苏斯有一位同事，也许能认出这根法杖。他让你去鲁瑟兰村找她，也就是达蕾恩·轻风。"},{t="达蕾恩的回复",b="达蕾恩抱怨说，特洛亚斯总是用他发现重要东西的荒唐念头来打扰她。在她看来，现在住在那些废墟里的食人魔或鹰身人大概早就把真正有价值的东西搬走了。她补充说，你可以在这儿四处看看，不过她怀疑这里的书能不能帮上忙。"}},faq={{q="是谁让你去找达蕾恩·轻风的？",a="特洛亚斯·月风，他想弄清楚他在菲拉斯废墟中发现的法杖到底是什么。",al={"谁开启了寻求知识的任务","任务发布者"}},{q="特洛亚斯发现了什么？",a="一根看起来很普通的法杖，是在特洛亚斯工作地点的南边瓦砾中发现的。他觉得事情没那么简单。",al={"特洛亚斯发现了什么","菲拉斯法杖"}},{q="达蕾恩·轻风在哪里？",a="在鲁瑟兰村。特洛亚斯说她是他在达纳苏斯的同事。",al={"达蕾恩·轻风的位置","达蕾恩在哪里"}},{q="特洛亚斯为什么要让你去找达蕾恩？",a="他和安格拉斯在书里找不到关于这根法杖的任何记载，或许达蕾恩能告诉他们这到底是什么东西。",al={"为什么要拜访达蕾恩·轻风","为什么去达纳苏斯"}}},fp="22,223,17.329.0,24.152.0,13.305.1,33.92.0,21.124.0,25.72.0,34.112.0"}
P.entries["quest:294"] = {n="奥莫尔的复仇",s="“奥莫尔的复仇”开启了奥莫尔·铁衣的复仇之旅，他是一位被困在湿地维尔加挖掘场高处的探险家。在挖掘出古代化石遗骨后，矮人挖掘小队无意中引来了成群饥饿的斑点迅猛龙，它们屠杀了小队的同伴，并将幸存者困在了一处岩石峭壁上。",h="“奥莫尔的复仇”开启了奥莫尔·铁衣的复仇之旅，他是一位被困在湿地维尔加挖掘场高处的探险家。在挖掘出古代化石遗骨后，矮人挖掘小队无意中引来了成群饥饿的斑点迅猛龙，它们屠杀了小队的同伴，并将幸存者困在了一处岩石峭壁上。",kw={"斑点迅猛龙","斑点尖啸者","奥莫尔·铁衣","奥莫尔的复仇","勘察员维尔加","湿地","维尔加挖掘场"},ang={["class:Hunter"]="在挖掘场外斜坡上徘徊的极具攻击性的斑点迅猛龙，为敏锐的猎人提供了在沼泽地形中研究危险爬行动物追踪习性的机会。",["race:Dwarf"]="看到矮人同胞在探险者协会的一次考古活动中遇害，这使得清理这处被迅猛龙盘踞的采石场成为了一项关乎祖先荣誉和正义复仇的行动。"},sec={{t="掘出的恐惧",b="维尔加挖掘场本应是矮人考古学的伟大成就，旨在揭开掩埋在湿地泥沼之下的巨大史前遗骸。然而，挖掘这些巨大骨骼的举动却引起了沼泽土生迅猛龙的注意。受骚乱吸引，成群的斑点掠食者蜂拥至挖掘场，令挖掘队员措手不及，并对他们展开了屠杀。"},{t="痛苦的坚守",b="只有少数矮人在最初的屠杀中幸存下来。奥莫尔·铁衣、麦琳·石纹和勘察员维尔加设法爬上了俯瞰挖掘坑的峭壁，但他们仍然被下方极具攻击性的龙群困住。在悲痛和怒火的驱使下，奥莫尔拒绝仅仅躲藏起来。出于保护战栗的勘察员和麦琳的职责，他招募有能力的旅者去清理周围的斑点迅猛龙和斑点尖啸者，作为他复仇的第一步。"}},faq={{q="这里的挖掘人员发生了什么事？",a="当矮人考古学家在盆地中发现巨型骨骼时，骚乱和气味将当地的迅猛龙群从沼泽中吸引了出来。这些掠食者冲垮了营地，屠杀了大部分人员，并将三名幸存者困在了高耸的峭壁之上。",al={"迅猛龙为什么在这里","维尔加挖掘场屠杀","是什么杀死了矮人"}},{q="奥莫尔·铁衣是谁？",a="奥莫尔是被困在维尔加挖掘场的幸存矮人挖掘人员之一。虽然他感到有义务留下来保护受惊的勘察员维尔加和麦琳·石纹，但他内心最渴望的，是对屠杀了他的战友的迅猛龙进行血腥报复。",al={"奥莫尔是谁","奥莫尔·铁衣背景故事"}},{q="这些迅猛龙是从哪里来的？",a="斑点迅猛龙和斑点尖啸者是湿地的原生掠食者，潜伏在挖掘峭壁以西的泥泞斜坡和沼泽地，以及通往挖掘场洞穴的路径上。",al={"斑点迅猛龙在哪里","湿地迅猛龙位置"}},{q="为什么奥莫尔不亲自去猎杀这些迅猛龙？",a="虽然奥莫尔渴望亲手让迅猛龙血债血偿，但他有义务守卫受惊的勘察员维尔加和麦琳·石纹，以确保他们的峭壁避难所不被攻破。",al={"为什么奥莫尔不战斗","为什么奥莫尔被困"}},{q="清理这些迅猛龙能结束奥莫尔的怨恨吗？",a="不。斩杀普通的斑点迅猛龙和尖啸者只是奥莫尔为阵亡朋友复仇计划的第一步，接下来他还将对迅猛龙群进行更严厉的打击。",al={"这是奥莫尔复仇的终点吗","奥莫尔接下来会怎样"}},{q="挖掘骨骼为什么会引来迅猛龙？",a="湿地的迅猛龙领地意识极强，并且会积极地进行搜寻。爆破和挖掘古代巨兽遗骸破坏了盆地的自然平衡，将好奇且饥饿的掠食者直接吸引到了挖掘营地的中心。",al={"骨骼为什么会吸引迅猛龙","恐龙骨骼与迅猛龙"}}},fp="15,252,17.286.0,14.376.0,37.221.0,23.229.0,33.196.0,43.176.0,46.176.0,49.197.0"}
P.entries["quest:2940"] = {n="菲拉斯的历史",s="你发现了一本书，它看起来已经很久没人翻动过了，这可能正是特洛亚斯所需要的东西。这本书属于达蕾恩·轻风，所以你需要先询问是否可以借阅。",h="你发现了一本书，它看起来已经很久没人翻动过了，这可能正是特洛亚斯所需要的东西。这本书属于达蕾恩·轻风，所以你需要先询问是否可以借阅。",kw={"书","达蕾恩·轻风","菲拉斯","历史","寻求知识","传说","特洛亚斯"},sec={{t="一本被遗忘的书",b="书的封面磨损严重，纸页也已泛黄。仔细看过之后，你怀疑这正是特洛亚斯正在寻找的东西。你捡起了它，但转念一想，没经过允许就拿走并不妥当。这是达蕾恩·轻风的书，所以应该先问问她。"},{t="达蕾恩的答复",b="达蕾恩·轻风思考了一会儿。她同意让你借阅《菲拉斯：历史》，但前提是你得先帮她一个忙。"}},faq={{q="《菲拉斯：历史》是什么书？",a="一本封面磨损、纸页泛黄的书，看起来好像很久没人翻动过了。这可能正是特洛亚斯正在寻找的东西。",al={"这本书是什么","菲拉斯：历史之书","特洛亚斯的书"}},{q="谁拥有这本书？",a="达蕾恩·轻风。借阅之前你应该先征得她的同意。",al={"谁拥有菲拉斯：历史","谁有这本书","达蕾恩·轻风是谁"}},{q="在这之前的任务是什么？",a="它的前置任务是“寻求知识”，在那项任务中，特洛亚斯·月风让你去找达蕾恩·轻风谈谈关于他法杖的事。",al={"上一个任务","上一个任务是什么","任务前置"}}},fp="18,192,16.252.0,14.142.1,36.148.0,18.59.0,23.117.0"}
P.entries["quest:2941"] = {n="海龟照片",s="达蕾恩·轻风对辛特兰海滩上的鳄鱼非常着迷，尤其是对一只名为甘美拉的巨型鳄鱼。她的研究让她无法脱身，因此她交给你一封信，让你带给塔纳利斯的克格尔·曲藤。",h="达蕾恩·轻风对辛特兰海滩上的鳄鱼非常着迷，尤其是对一只名为甘美拉的巨型鳄鱼。她的研究让她无法脱身，因此她交给你一封信，让你带给塔纳利斯的克格尔·曲藤。",kw={"克格尔·曲藤","达蕾恩·轻风","甘美拉","鳄鱼","快照","超级摄影器fx","塔纳利斯","借用者"},sec={{t="甘美拉的照片",b="达蕾恩·轻风说她研究过许多课题，而她最近迷上了生活在辛特兰海滩沿岸的鳄鱼。她特别想见见一只被称为甘美拉的巨型鳄鱼。她很想亲自前往，但她的研究让她留在了这里，因此能有一张甘美拉的照片就是退而求其次最好的选择了。"},{t="致塔纳利斯的信",b="达蕾恩递给你一封写给塔纳利斯的克格尔·曲藤的信。克格尔为达蕾恩制造了一项发明，可以捕捉图像，达蕾恩认为克格尔称之为快照。"},{t="克格尔的反应",b="克格尔把你当成了达蕾恩的实习生，并称赞达蕾恩是一位博学的历史学家。然后克格尔去取超级摄影器FX，并确信你会喜欢它的。"}},faq={{q="是谁派你去塔纳利斯的？",a="达蕾恩·轻风，她给了你一封信让你带去。她的研究让她无法亲自前往。",al={"任务发布者","谁发布了借用者","达蕾恩·轻风"}},{q="克格尔·曲藤是谁？",a="塔纳利斯的一位居民，他为达蕾恩制造了一项可以捕捉图像的发明，达蕾恩认为这叫作快照。",al={"克格尔是谁","克格尔·曲藤的位置","塔纳利斯的克格尔"}},{q="为什么达蕾恩想要甘美拉的照片？",a="达蕾恩对辛特兰海滩上的鳄鱼很着迷，特别想看看甘美拉。研究工作让达蕾恩无法亲身前往，所以照片是最好的替代品。",al={"甘美拉鳄鱼","为什么找甘美拉","巨型鳄鱼"}},{q="甘美拉是什么？",a="辛特兰海滩上的一只巨型鳄鱼。",al={"甘美拉是谁","甘美拉"}}},fp="12,229,22.320.0,21.171.0,17.176.1,25.92.0,25.125.0,43.176.0,18.48.0"}
P.entries["quest:2942"] = {n="晨光石",s="当你从艾奎尼克斯巨石上取下神器的那一刻，艾奎尼克斯法杖的力量开始消散。你必须带着烁光之石和法杖回到羽月要塞，交给特洛亚斯·月风。",h="当你从艾奎尼克斯巨石上取下神器的那一刻，艾奎尼克斯法杖的力量开始消散。你必须带着烁光之石和法杖回到羽月要塞，交给特洛亚斯·月风。",kw={"艾奎尼克斯巨石","羽月要塞","菲拉斯","晨光石","烁光之石","艾奎尼克斯法杖","特洛亚斯·月风"},sec={{t="回到羽月要塞",b="当神器离开巨石时，法杖的能量开始消散。羽月要塞的特洛亚斯·月风急于知道你的发现，所以把烁光之石和法杖都带去给他。"},{t="特洛亚斯的发现",b="在你离开期间，特洛亚斯一直在研读，他将这块石头命名为“晨光石”。他还不确定它的用途，但像这样被隐藏在巨石之中的东西一定具有重大意义。他将继续他的研究，并希望你能支持他。"}},faq={{q="这个任务从哪里开始？",a="在艾奎尼克斯巨石处，一旦神器被取下即可开始。",al={"在哪里接这个任务","晨光石任务起始点","艾奎尼克斯巨石起始"}},{q="我该把石头带给谁？",a="带给羽月要塞的特洛亚斯·月风。记得把艾奎尼克斯法杖也带上。",al={"晨光石交予谁","特洛亚斯·月风在哪里","谁接收烁光之石"}},{q="艾奎尼克斯法杖会怎么样？",a="在神器从巨石上被取下的那一刻，它的能量就开始消散了。",al={"艾奎尼克斯法杖能量","法杖会发生什么","为什么法杖失去了力量"}},{q="这个任务之前的内容是什么？",a="它承接任务“艾奎尼克斯法杖”，在该任务中，你在巨石旁为法杖充能。",al={"前置任务","晨光石的前置任务是什么","任务先决条件"}}},fp="16,213,30.204.0,17.267.1,22.66.0,28.77.0,37.77.0,23.86.0"}
P.entries["quest:2943"] = {n="向特洛亚斯回复",s="达蕾恩·轻风交给你一本《菲拉斯：历史》，并嘱托你要妥善保管。这本书要送到羽月要塞的特洛亚斯·月风那里，他肯定已经迫不及待地想看到你回来了。",h="达蕾恩·轻风交给你一本《菲拉斯：历史》，并嘱托你要妥善保管。这本书要送到羽月要塞的特洛亚斯·月风那里，他肯定已经迫不及待地想看到你回来了。",kw={"达纳苏斯","达蕾恩·轻风","羽月要塞","菲拉斯","菲拉斯：历史","特洛亚斯·月风"},sec={{t="借阅的书籍",b="在你身后的是超级摄影器FX，达蕾恩·轻风交给你她的书，并要求你妥善保管。她催促你快点出发，确信特洛亚斯正盼望着你的归来。这本书是给羽月要塞的特洛亚斯·月风准备的。"},{t="特洛亚斯阅读",b="特洛亚斯很高兴你能把这本书带来。他翻看了一遍，快速浏览了书页，然后惊呼他想他已经找到了。"}},faq={{q="我送的是什么？",a="达蕾恩·轻风的书，《菲拉斯：历史》。",al={"这是什么书","我该带给特洛亚斯什么","菲拉斯：历史书籍"}},{q="特洛亚斯·月风在哪里？",a="在羽月要塞。",al={"特洛亚斯的位置","特洛亚斯·月风在哪里","我该去哪里"}},{q="是谁给你的书？",a="达蕾恩·轻风，她要你妥善保管它。",al={"谁发布的任务","任务发布者","达蕾恩·轻风"}},{q="在此之前发生了什么？",a="它是紧随“超级摄影器FX”之后的任务。",al={"上一个任务","我刚才做了什么","之前的任务链"}}},fp="16,182,15.245.0,12.116.1,21.43.0,27.26.0,23.49.0,22.32.0"}
P.entries["quest:2944"] = {n="超级摄影器FX",s="克格尔·曲藤准备好了一台新的拍照设备——超级摄影器FX，并把它交给你试用。拍摄目标是Gammerita，一只来自辛特兰的生物。拿到她的快照后，你将其连同设备一起带给鲁瑟兰村的达蕾恩·轻风。这是任务“The Borrower”的后续。",h="克格尔·曲藤准备好了一台新的拍照设备——超级摄影器FX，并把它交给你试用。拍摄目标是Gammerita，一只来自辛特兰的生物。拿到她的快照后，你将其连同设备一起带给鲁瑟兰村的达蕾恩·轻风。这是任务“The...",kw={"克格尔·曲藤","达蕾恩·轻风","gammerita","鲁瑟兰村","快照","超级摄影器fx","辛特兰"},sec={{t="一台待测设备",b="在完成“The Borrower”之后，克格尔·曲藤会将他们的新发明：超级摄影器FX交给你。使用方法很简单：对准你想要拍摄的目标并按下按钮即可。克格尔把它交给你进行试用。"},{t="拍摄目标",b="拍摄目标是Gammerita，一只你曾向克格尔提及过的来自辛特兰的生物。克格尔祝你好运，希望你能找到她，并认为达蕾恩·轻风会对这张快照感到满意。一旦你拍好了，就带着照片和设备去找鲁瑟兰村的达蕾恩。"}},faq={{q="谁提供了超级摄影器FX？",a="克格尔·曲藤将这个新发明的设备交给你，让你试用。",al={"谁提供超级摄影器","克格尔任务发布者","如何获得超级摄影器fx"}},{q="我该用超级摄影器FX拍摄什么？",a="Gammerita，一只来自辛特兰的生物。克格尔祝你好运，希望你能找到她。",al={"gammerita位置","gammerita在哪里","gammerita的快照"}},{q="谁来接收快照？",a="鲁瑟兰村的达蕾恩·轻风。你需要把快照和设备都交给她。",al={"上交超级摄影器fx","照片交给谁","达蕾恩·轻风是谁"}},{q="该系列任务的下一步是什么？",a="该任务链的后续是“Return to Troyas”。",al={"超级摄影器之后的后续任务","超级摄影器fx之后的内容"}}},fp="20,293,16.215.0,11.271.0,31.76.0,47.79.0,26.86.0,29.40.0"}
P.entries["quest:2945"] = {n="脏兮兮的戒指",s="在诺莫瑞根受辐射的废墟深处，冒险者可以从黑铁矮人入侵者身上获得一件包裹着厚厚有毒污垢和硬泥的珠宝。要发现它的真实身份，需要使用位于宿舍区的工业清洗自动化装置——Sparklematic 5200。一旦清洗干净，戒指就会显露出个人标记，从而开启一段归还或重铸这件传家宝的旅程。",h="在诺莫瑞根受辐射的废墟深处，冒险者可以从黑铁矮人入侵者身上获得一件包裹着厚厚有毒污垢和硬泥的珠宝。要发现它的真实身份，需要使用位于宿舍区的工业清洗自动化装置——Sparklematic...",kw={"clean zone","黑铁矮人","宿舍区","诺莫瑞根","污损的戒指","戒指的回归","sparklematic 5200"},ang={["profession:Engineering"]="Sparklematic 5200是典型奇特侏儒工程学的典范，将工业溶剂刷洗与自动礼品包装机结合在了一起。",["race:Dwarf"]="这枚戒指出现在潜入的黑铁矮人身上，暗示着这是在诺莫瑞根陷落的混乱中，从铁炉堡或侏儒受害者那里搜刮来的战利品。",["race:Gnome"]="即使在城市陷落的灾难性时刻，侏儒们设计出的卫生装置在完成危险的工业清洗循环后，依然会发出愉快的钟声并系上蝴蝶结。"},sec={{t="污垢下的遗物",b="诺莫瑞根的走廊里满是毒泥、油污和放射性尘埃，因此在战斗中掉落的物品被覆盖上一层坚硬的污泥也就不足为奇了。潜入城市的黑铁矮人经常携带弄得非常脏的饰品，其中最主要的就是这枚污损的戒指。这层污垢太硬了，普通的洗涤根本无法清除，让人完全看不清戒指底下的金属到底是铜、金还是废铁。"},{t="Sparklematic 5200",b="要清洗戒指，必须在Clean Zone宿舍找到Sparklematic 5200。这台机器是侏儒工程学的杰作，其设计极其荒谬有趣：它接受硬币，对严重污损的物品进行剧烈的内部冲刷，最后将其清洗得光亮如新，并用礼品盒精美包装，还系上蝴蝶结。洗掉辐射污泥后，戒指内环显露出城市的印章和刻有的首字母缩写，将一件捡来的饰品变成了一个归还的任务。"}},faq={{q="在哪里可以找到污损的戒指？",a="污损的戒指可以从诺莫瑞根这个被围困的副本里遇到的黑铁矮人尸体中获得。",al={"戒指掉落","污损的戒指在哪里掉落","谁掉落污损的戒指"}},{q="如何清洗戒指？",a="将戒指带到位于诺莫瑞根Clean Zone宿舍的Sparklematic 5200处。放入戒指并支付所需的硬币费用，即可启动强力自动清洗程序，去除硬化的污垢。",al={"清洗戒指","如何清洗污损的戒指","在哪里清洗戒指"}},{q="戒指清洗后会发生什么？",a="Sparklematic会弹出一个包装整齐的盒子，里面装着一枚带有独特个人刻印的复原戒指。这标志着任务“戒指的回归”的开始，引导你去寻找它的原主人。",al={"污损的戒指后续任务","清洗后的戒指做什么","sparklematic戒指结果"}},{q="部落玩家能完成这个任务吗？",a="可以。部落冒险者可以使用Sparklematic 5200来清洗戒指。但是，任务链的后续步骤会有所不同，最终会将部落玩家引导至奥格瑞玛的一位工程师处，而不是将其归还给铁炉堡。",al={"污损的戒指是联盟专属吗","部落污损的戒指","部落可以清洗戒指吗"}},{q="为什么清洗后戒指会被包在礼品盒里？",a="Sparklematic 5200的设计带有典型的侏儒奇思妙想。除了强力刷洗污泥和垢物外，该装置还被编程为在处理完成后自动包装物品，并在上面系上装饰性的蝴蝶结。",al={"礼品包装的戒指","为什么sparklematic有礼品盒"}},{q="有多台Sparklematic机器吗？",a="Clean Zone宿舍的墙边排列着几台Sparklematic装置，但只有一台能正确处理该戒指：即当你沿着楼梯进入时，靠近友善侏儒的那台。",al={"哪一台sparklematic","sparklematic 5200位置"}}},fp="20,180,24.283.0,21.283.1,43.51.0,26.150.0,39.190.0,38.158.0,53.138.0,41.168.0"}
P.entries["quest:2947"] = {n="戒指归来",s="在清理掉诺莫瑞根自动清洁装置中积攒的地下淤泥后，一位冒险者发现了一枚印有铁炉堡徽记并刻有“TdK”缩写的纯金戒指。顺着这些标记，冒险者来到了铁炉堡繁忙的工匠区，找到了这位古怪的创作者。",h="在清理掉诺莫瑞根自动清洁装置中积攒的地下淤泥后，一位冒险者发现了一枚印有铁炉堡徽记并刻有“TdK”缩写的纯金戒指。顺着这些标记，冒险者来到了铁炉堡繁忙的工匠区，找到了这位古怪的创作者。",kw={"闪亮的金戒指","黑铁","铁炉堡徽记","mystic ward","闪光塔","塔瓦斯德·基瑟尔","tdk"},ang={["faction:Alliance"]="在黑铁矮人渗透者手中发现刻有铁炉堡标志的文物，加剧了索瑞森大帝的特工对联盟山中家园构成的日益严重的威胁。",["race:Gnome"]="回收从沦陷之城中遗失的手工艺品，为我们提供了一个难得的机会，得以一窥瑟玛普拉格引发灾难前，侏儒们享受的宁静的日常生活。"},sec={{t="污泥覆面的宝藏",b="在诺莫瑞根布满辐射的废墟深处，古老的机械依然在轰鸣，仿佛在蔑视那些入侵的穴居人。将一枚脏兮兮、结块的饰品放入闪光塔5200型中，就能去除多年积压的辐射毒垢，露出这枚闪烁着奥术力量光芒的闪亮的金戒指。戒指内侧印有清晰的铁炉堡徽记，旁边还整齐地刻着“TdK”三个缩写字母。"},{t="秘法区的工匠",b="这些缩写属于塔瓦斯德·基瑟尔，一位住在铁炉堡秘法区的古怪侏儒珠宝匠——他常常表现得像是在疯狂地抵御那些并不存在的讨债人。塔瓦斯德很快就认出，这是他在诺莫瑞根沦陷前在旧店里制作的标准设计之一。得知这件饰品是在黑铁矮人渗透者手中发现的，这让这位工匠深感不安，暗示了这座失落科技之城阴影下涌动的阴谋。"}},faq={{q="谁制作了在诺莫瑞根发现的戒指？",a="“TdK”的缩写属于塔瓦斯德·基瑟尔，一位目前住在铁炉堡秘法区的古怪侏儒珠宝匠。在诺莫瑞根沦陷前，塔瓦斯德曾在城内经营一家珠宝店，并制作了几枚这种设计的简单魔法戒指。",al={"谁制作了这枚戒指","戒指缩写tdk","tdk是谁"}},{q="这枚戒指最初来自哪里？",a="这枚戒指最初是在诺莫瑞根深处发现的，当时它被包裹在淤泥中，由黑铁矮人等敌对入侵者携带。在经过闪光塔5200型自动清洁后，它恢复了金色的光泽和制造者的标记。",al={"戒指在哪里被发现","戒指来自哪里"}},{q="为什么黑铁矮人会带着塔瓦斯德的戒指？",a="塔瓦斯德也不完全确定，但他指出，在黑铁矮人渗透者身上发现他沦陷前的作品，为围绕诺莫瑞根沦陷的阴谋又增添了一层可疑的色彩。它很可能是从他废弃的作坊中流出的，或者是从那些没能逃过入侵的受害者身上掠夺来的。",al={"为什么黑铁矮人有它","黑铁戒指传说"}},{q="为什么塔瓦斯德·基瑟尔认为你是他的房东？",a="塔瓦斯德出了名的神经质、古怪，而且在铁炉堡经常拖欠房租。每当有陌生人咄咄逼人地靠近他的商店时，他就会以为他们是来催债的法警或房东。",al={"为什么塔瓦斯德那么多疑","塔瓦斯德房租"}},{q="塔瓦斯德会制作被诅咒的珠宝吗？",a="塔瓦斯德向所有潜在的顾客断言他从不制作被诅咒的物品，尽管他那种紧张、先发制人的否认往往引出比答案更多的问题。",al={"塔瓦斯德是否有诅咒","铁炉堡诅咒珠宝"}},{q="我可以留下这枚戒指而不是归还它吗？",a="虽然这件饰品本身就拥有魔法属性，但把它展示给它的创造者看，可以让塔瓦斯德检查这件作品，并提出通过后续工作进一步精炼它的附魔。",al={"保留戒指","我应该归还戒指吗"}}},fp="18,80,24.278.0,30.338.1,38.204.0,40.217.0,51.190.0,55.197.0,33.143.0,49.121.0"}
P.entries["quest:2948"] = {n="侏儒的手艺",s="当冒险者将一枚从诺莫瑞根受辐射的深处找回的戒指交给塔瓦斯德·基瑟尔时，他表示只要冒险者能提供材料，他就愿意对其进行升级。在矮人主城铁炉堡中时运不济的这位侏儒工匠，利用白银、苔藓玛瑙和复杂的网格工艺，打造出了一件远胜于前的饰品。",h="当冒险者将一枚从诺莫瑞根受辐射的深处找回的戒指交给塔瓦斯德·基瑟尔时，他表示只要冒险者能提供材料，他就愿意对其进行升级。在矮人主城铁炉堡中时运不济的这位侏儒工匠，利用白银、苔藓玛瑙和复杂的网格工艺，打造出了一件远胜于前的...",kw={"闪亮的金戒指","侏儒的改良","诺莫瑞根","铁炉堡","苔藓玛瑙","银锭","塔瓦斯德"},ang={["faction:Alliance"]="这一任务发生在诺莫瑞根和铁炉堡之间，加强了联盟英雄与这座沦陷的侏儒首都的流亡难民之间建立的深厚联系。",["profession:Mining"]="矿工们提供了塔瓦斯德进行珠宝加工所需的必要原材料——在地下矿脉中发现的熔炼银和切割好的苔藓玛瑙。",["race:Gnome"]="这个任务突显了侏儒工匠的自豪感与韧性，即使背井离乡、原材料匮乏，他们也拒绝生产劣质的产品。"},sec={{t="流亡的侏儒工匠",b="塔瓦斯德·基瑟尔是诺莫瑞根在遭受穴居人入侵和辐射而惨遭沦陷后，逃离家园的众多侏儒难民之一。他居住在铁炉堡的Mystic Ward，发现自己时运不济、库存耗尽，且急于证明尽管身处流亡之中，但他作为珠宝大师和技师的才华并未受损。"},{t="升级旧戒指",b="当冒险者向塔瓦斯德展示一枚他自己在沦陷前设计的简单戒指，并经过Sparklematic 5200除垢之后，塔瓦斯德既感激又雄心勃勃。与其让客户带着他认为过时且简单的戒指设计离开，他坚持要对其进行改进。通过在戒圈上覆盖一层精致的白银和苔藓玛瑙网格，他打造出了一件精良的饰品，展现了他不断精进的金属与宝石加工技艺。"}},faq={{q="塔瓦斯德·基瑟尔是谁？",a="塔瓦斯德·基瑟尔是一位技艺精湛的侏儒工匠兼珠宝匠，目前流亡在铁炉堡。诺莫瑞根沦陷前，他曾在那儿经营一家小型珠宝店，而他在那里制作的一枚戒指可以被找回，并带给他位于Mystic Ward的住所。",al={"塔瓦斯德","塔瓦斯德·基瑟尔","铁炉堡侏儒珠宝匠"}},{q="这枚被升级的戒指背后有什么故事？",a="这枚基础戒指是塔瓦斯德在诺莫瑞根旧店中制作的几款简单戒指之一，后来在废墟中的黑铁矮人身上被发现。在被冒险者从这座废弃城市内的Sparklematic 5200清洁机中找回后，塔瓦斯德主动提出将其进行翻新，并把这枚朴素的戒指装饰成一件更为精美的饰品。",al={"戒指来源","脏兮兮的戒指来源"}},{q="为什么塔瓦斯德要求玩家提供材料？",a="和许多被赶出诺莫瑞根的侏儒难民一样，塔瓦斯德正面临经济困境，在铁炉堡的原材料储备也已耗尽。如果没有赞助者，他就缺乏进行精细网格工艺所需的白银和苔藓玛瑙。",al={"为什么需要白银和苔藓玛瑙","为什么塔瓦斯德没有材料"}},{q="这个任务链从哪里开始？",a="该任务链始于诺莫瑞根地下城，通过从敌人身上获得一枚脏兮兮的戒指，在Sparklematic 5200机器上将其清洁干净，然后顺着刻在上面的缩写“TdK”找到铁炉堡的塔瓦斯德。",al={"如何开始侏儒的改良","戒指任务线起始"}},{q="塔瓦斯德对他在铁炉堡的处境感到苦恼吗？",a="虽然他感叹自己陷入了所谓的“不公正的经济困境”，但塔瓦斯德依然保持着高昂的精神和职业自豪感。他坚信，一旦他东山再起，他将凭借打造出世上最精美的饰品而闻名艾泽拉斯。",al={"塔瓦斯德背景故事","塔瓦斯德性格"}},{q="部落可以进行这个任务吗？",a="不可以。虽然部落玩家可以在诺莫瑞根清洗脏兮兮的物品，但他们的戒指任务版本会将他们指引向另一位联系人——位于奥格瑞玛的诺格，而不是铁炉堡的塔瓦斯德。",al={"部落可以进行侏儒的改良吗","部落戒指升级"}}},fp="17,153,26.270.0,22.232.0,26.213.0,51.266.0,56.136.0,34.176.0,51.197.0,41.132.0"}
P.entries["quest:2949"] = {n="戒指归来",s="在诺莫瑞根的Clean Zone通过Sparklematic 5200洗去污垢后，一位冒险者发现了一枚带有奥格瑞玛印记并刻有“NOG”字母的戒指。顺藤摸瓜回到部落的首都，线索直接指向了地精工程师诺格，他对这座城市的陷落有着自己独到的见解。",h="在诺莫瑞根的Clean Zone通过Sparklematic...",kw={"闪亮的金戒指","黑铁矮人","诺莫瑞根","诺格","奥格瑞玛","戒指的归还","sparklematic 5200","valley of honor"},ang={["faction:Horde"]="在东部王国首屈一指的技术之都深处发现部落的标志是罕见的景象，这吸引了部落的冒险者从卡兹莫丹直接返回Valley of Honor。",["profession:Engineering"]="奥格瑞玛的地精工程师们不断地将自己与侏儒的发明进行比较，诺格渴望剖析从他们那座陨落的技术奇迹中心地带取回的任何东西。"},sec={{t="一个奇特的发现",b="诺莫瑞根是位于卡兹莫丹深处的一座联盟城市，因此发现一枚带有奥格瑞玛官方印记的戒指是完全出人意料的。这件饰品在经过侏儒的Sparklematic清洗装置处理后，洗去了厚厚的地下淤泥，显露出涌动的魔法能量和勉强可辨的“NOG”字母。无论它是在卡利姆多制造的，还是在一次注定失败的探险中被带去的，这件饰品显然与部落首都渊源颇深。"},{t="侏儒间的竞争与黑铁矮人的阴谋",b="将戒指带回奥格瑞玛的Valley of Honor，直接就能找到工程师诺格。他很快澄清说这枚戒指并非他个人的饰品，但其来历却引发了耐人寻味的疑问。地精一直瞧不起侏儒发明家，视其为古怪的竞争对手。在诺格看来，黑铁矮人在诺莫瑞根持有这枚戒指的事实表明，侏儒可能窃取并改造了黑铁矮人的傀儡设计，这让黑铁矮人急于报复，他认为这条线索值得调查。"}},faq={{q="为什么在诺莫瑞根发现的戒指上会有奥格瑞玛的印记？",a="这枚戒指究竟是如何进入诺莫瑞根的具体情况尚不清楚，但它被带到了废墟深处，并被黑铁矮人回收。其奥格瑞玛的徽记将其与在杜隆塔尔活动的部落金属工人和工匠联系了起来。",al={"为什么会有奥格瑞玛印记","诺莫瑞根的部落戒指","戒指是如何到达那里的"}},{q="诺格是谁？",a="诺格是位于奥格瑞玛Valley of Honor的一名地精工程师。他负责工程补给和机械设备，他的名字与清洗后的戒指上，奥格瑞玛印记旁刻着的磨损字母相吻合。",al={"诺格是谁","诺格 奥格瑞玛","带有nog字母的戒指"}},{q="什么是Sparklematic 5200？",a="Sparklematic 5200是位于诺莫瑞根Clean Zone内的一套自动化工业清洗系统。它能清除从废墟走廊中拖出的物品上厚厚的有毒淤泥和辐射。",al={"什么是闪光机器","sparklematic 5200","清洗机器"}},{q="这枚戒指是诺格的吗？",a="不是。当把清洗过的戒指展示给他看时，诺格仔细检查后承认这不属于他。不过，他认可了其工艺，并利用自己的工程学专长为冒险者对其进行了进一步的改造。",al={"这是诺格的戒指吗","诺格弄丢戒指了吗","谁拥有这枚戒指"}},{q="诺格认为诺莫瑞根发生了什么？",a="诺格怀疑侏儒窃取了黑铁矮人的先进傀儡蓝图。他推断黑铁矮人会因此寻求重大的报复，并认为这条线索值得调查。",al={"诺格对诺莫瑞根的理论","诺莫瑞根发生了什么","为什么是黑铁矮人"}},{q="我可以留下这枚戒指，而不是把它还给诺格吗？",a="你可以选择立即佩戴这枚戒指，或者把它带到奥格瑞玛。然而，把它交给诺格可以让这位地精工程师检查其工艺，并提供进一步的改进。",al={"保留闪亮的金戒指","我应该归还戒指吗","我必须把它交给诺格吗"}}},fp="18,140,19.394.0,37.391.1,63.203.0,12.163.0,30.193.0,23.151.1,44.169.0,52.157.0"}
P.entries["quest:295"] = {n="奥莫尔的复仇",s="“奥莫尔的复仇”是联盟的一项任务，由湿地维尔加挖掘场的奥莫尔·铁衣发布。随着最初的迅猛龙侦察兵被清理干净，奥莫尔要求屠杀那些将他的探险队赶出挖掘场的更强壮的斑点镰爪龙和剃刀龙。",h="“奥莫尔的复仇”是联盟的一项任务，由湿地维尔加挖掘场的奥莫尔·铁衣发布。随着最初的迅猛龙侦察兵被清理干净，奥莫尔要求屠杀那些将他的探险队赶出挖掘场的更强壮的斑点镰爪龙和剃刀龙。",kw={"矮人","挖掘","探险者协会","斑点剃刀龙","斑点镰爪龙","奥莫尔·铁衣","迅猛龙","湿地","维尔加挖掘场"},ang={["class:Hunter"]="湿地的斑点迅猛龙是领地意识极强的群体猎手，在封闭、泥泞的战壕中带来了致命的追踪挑战。",["faction:Alliance"]="收复维尔加挖掘场可以确保连接湿地到阿拉希高地的东部道路上的作业安全。",["race:Dwarf"]="奥莫尔的愤怒反映了探险者协会强烈的自豪感，他们拒绝让野兽永久阻碍矮人挖掘他们祖先历史的努力。"},sec={{t="升级狩猎",b="奥莫尔·铁衣对那些在维尔加挖掘场横行霸道的迅猛龙怀恨在心，这是他个人的恩怨。在清理了那些占领了上层营地的幼龙后，他让你去对付那些在底层挖掘场潜伏的成年捕食者。这些斑点镰爪龙和剃刀龙对任何重建考古工作的希望构成了核心威胁，它们撕碎了矮人勘察员，在战壕中留下了破碎的板条箱和废弃的十字镐。"},{t="战壕中的鲜血",b="挖掘坑实际上已经变成了迅猛龙的巢穴。当奥莫尔在俯瞰挖掘场的山脊上沉思时，他指引有能力的冒险者进入泥潭，直接打击那些成熟的野兽。虽然勘察员维尔加和他的船员希望抢救古代遗物，但奥莫尔完全被复仇冲昏了头脑，要求在考虑对付该区域的顶级恐怖生物之前，先清点一大批死掉的镰爪龙和剃刀龙。"}},faq={{q="为什么奥莫尔对这些迅猛龙如此愤怒？",a="斑点迅猛龙暴力涌入并占领了维尔加挖掘场，赶走了矮人团队，并屠杀了所有没能及时逃脱的人。奥莫尔·铁衣流离失所且满心苦涩，他拒绝让这些野兽在不付出血的代价的情况下控制挖掘场。",al={"奥莫尔为何愤怒","奥莫尔复仇原因","为什么要在湿地猎杀迅猛龙"}},{q="在哪里可以找到斑点镰爪龙和剃刀龙？",a="这两种迅猛龙都在维尔加挖掘场的下层战壕和周围的土方工程中出没，该挖掘场位于湿地米奈希尔港以东，丹莫德以西。",al={"斑点镰爪龙位置","斑点剃刀龙位置","在哪里找到奥莫尔的目标迅猛龙"}},{q="奥莫尔·铁衣是谁？",a="奥莫尔·铁衣是一位驻扎在维尔加挖掘场的矮人探险者协会成员。在挖掘场遭受灾难性的入侵后，他将消灭困扰他们工作的迅猛龙群作为自己的个人使命。",al={"奥莫尔是谁","奥莫尔·铁衣背景故事"}},{q="清理这些迅猛龙后会发生什么？",a="一旦你清理了镰爪龙和剃刀龙，奥莫尔就会将注意力转向萨尔托斯，他认为这只大型迅猛龙是当地龙群的首领，并指引你去终结迅猛龙入侵的根本源头。",al={"奥莫尔的复仇之后做什么","奥莫尔的复仇后续任务","清理镰爪龙后的下一个任务"}},{q="这个任务与其他挖掘场的任务有关联吗？",a="是的。当冒险者为奥莫尔在整个下层挖掘场猎杀迅猛龙时，他们经常会协助勘察员维尔加和他的团队完成“揭示过去”任务，收集散落在同一战壕中的破碎土灵遗物。",al={"维尔加挖掘场任务","与揭示过去任务的联系"}},{q="矮人们最初为什么要在这里挖掘？",a="铁炉堡的探险者协会建立了维尔加挖掘场，以寻找泰坦遗物并揭示矮人种族的古老历史，但当具有攻击性的野生动物占领了挖掘场后，他们的行动被迫停止了。",al={"为什么在湿地挖掘","维尔加挖掘场目的"}}},fp="15,200,19.351.0,21.347.0,39.256.0,54.188.0,23.214.0,41.196.1,62.208.0,53.217.0"}
P.entries["quest:2950"] = {n="诺格的手艺",s="“诺格的戒指改造”总结了对一件从诺莫瑞根废墟带回奥格瑞玛的污浊饰品的调查。为了换取稀有材料和关于黑铁矮人活动的宝贵情报，地精工程师诺格对找回的珠宝进行了改良，他渴望证明地精的工艺优于侏儒的设计。",h="“诺格的戒指改造”总结了对一件从诺莫瑞根废墟带回奥格瑞玛的污浊饰品的调查。为了换取稀有材料和关于黑铁矮人活动的宝贵情报，地精工程师诺格对找回的珠宝进行了改良，他渴望证明地精的工艺优于侏儒的设计。",kw={"闪亮的金戒指","黑铁","诺莫瑞根","地精工程学","苔藓玛瑙","诺格","奥格瑞玛","银锭"},ang={["faction:Horde"]="从像诺莫瑞根这样倾向联盟的地方回收技术，并将其交给奥格瑞玛的工匠，能为部落提供关于敌人能力的至关重要的情报。",["profession:Engineering"]="这个任务展示了地精的创造力与侏儒的小玩意儿之间持续不断的意识形态竞争，凸显了地精为了实现最大产出而激进地改造现有技术的方法。",["profession:Mining"]="改良找回的戒指需要珍贵的地球萃取物——精炼的银锭和苔藓玛瑙——这需要熟练的矿工和宝石切割师的服务。"},sec={{t="地精的优越性",b="当一名冒险者将从诺莫瑞根深处找回并清洗干净的金戒指带到位于Valley of Honor的诺格工作室时，这位工程师与生俱来的傲慢便显露无遗。诺格嘲讽这种原始手艺不过是侏儒的粗糙之作，并提出了一笔交易。只要支付原材料和一笔微薄的费用，他承诺改进这件联盟饰品，打造一个精致的银锭和苔藓玛瑙晶格，用以增强戒指内部流动的魔法。"},{t="矮人疑云",b="诺格突然愿意升级这枚戒指并不仅仅是出于商业利益。有报告称黑铁矮人潜伏在这座被围困的侏儒城市中，这引起了他极大的关注。对诺格而言，矮人的出现解释了为什么侏儒能够突然制造出这种尖端机械——这是地精认为属于自己独有的领域。搜集到这些情报，冒险者不仅能获得一件升级后的珠宝，还能得到诺格勉强的尊敬。"}},faq={{q="诺格是谁？",a="诺格是一位在奥格瑞玛Valley of Honor活动的著名地精工程师。他与the Drag和Valley of Honor的其他工匠密切合作，经常处理从危险探险中带回的奇特机械制品和图纸。",al={"诺格是谁","诺格 奥格瑞玛","诺格 npc"}},{q="重铸戒指需要什么材料？",a="诺格需要原先的闪亮的金戒指、一个银锭、一个苔藓玛瑙，以及三十枚银币作为劳务费和工作室的开销。",al={"戒指材料","诺格所需材料","诺格需要什么"}},{q="为什么诺格对诺莫瑞根感兴趣？",a="诺莫瑞根拥有巨大的技术价值。地精在技术领域与侏儒竞争激烈，而诺格对“黑铁矮人参与了这座没落科技之城内部技术异常”的传闻尤为感兴趣。",al={"为什么诺格关心诺莫瑞根","诺莫瑞根 地精的兴趣"}},{q="诺格到底对戒指做了什么？",a="诺格在金戒指外围直接构建了一个银锭和苔藓玛瑙的晶格。这个精致的框架能够引导并稳定珠宝中潜在的附魔，使其比原先的侏儒设计更坚固、更强大。",al={"戒指升级背景故事","戒指发生了什么变化"}},{q="这个任务链从哪里开始？",a="该任务链始于诺莫瑞根深处，当时一名冒险者从一名黑铁矮人身上拾取了一枚布满污垢的戒指，并使用闪光自动机5200将其洗净。",al={"任务链起始","如何开始诺格任务","戒指任务线起始"}},{q="为什么诺格怀疑黑铁矮人？",a="地精工程师对侏儒的创新持怀疑态度。在诺格看来，侏儒中任何突然迸发的激进机械灵感，一定受到了外部干涉者的影响或供应——也就是那些诡计多端的黑铁部族。",al={"为什么是黑铁矮人","黑铁矮人的联系"}}},fp="16,193,18.324.0,15.328.1,12.220.0,46.139.0,37.232.0,39.188.0,34.138.0,40.176.0"}
P.entries["quest:2951"] = {n="超级清洁器5200型！",s="在诺莫瑞根的深处，火花机5200是一台在混乱中依然能够正常运转的自动清洁设备。只要往里投入从地下大厅中拾获的脏兮兮的东西，并支付一笔象征性的费用，冒险者就能将回收到的饰品、宝石和废料恢复到崭新的状态。它是侏儒工程学持久的独创性与怪异性的鲜活证明。",h="在诺莫瑞根的深处，火花机5200是一台在混乱中依然能够正常运转的自动清洁设备。只要往里投入从地下大厅中拾获的脏兮兮的东西，并支付一笔象征性的费用，冒险者就能将回收到的饰品、宝石和废料恢复到崭新的状态。它是侏儒工程学持久的...",kw={"清洁器","侏儒","诺莫瑞根","脏兮兮的","机器","回收","火花机","火花机5200","穴居人"},ang={["faction:Alliance"]="对于在诺莫瑞根大厅中冒险的联盟回收小队来说，这台机器提供了一种在将回收的遗物带回铁炉堡之前对其进行清洗的即时方法。",["profession:Engineering"]="工程师们会欣赏这种坚固的电机和分类架构，它能在不卡壳或爆炸的情况下清洁和处理未知的碎片。",["race:Gnome"]="这台机器反映了经典的侏儒韧性：即使在灾难性的家园撤离期间，商业活动和闪耀的清洁工作依然在不间断地进行。"},sec={{t="污垢中的灯塔",b="在诺莫瑞根饱受辐射沉降物和穴居人侵扰的困境中，一小群幸存的侏儒在他们的非凡发明——火花机5200附近维持着一条安全防线。这台坚固的装置旨在清除回收贵重物品上附着的恶劣地下污垢，它承诺要让一切“重焕光彩”。即使地下怪物不断撞击着舱壁，这台机器依然时刻准备着进行商业运作。"},{t="疯狂的运作",b="这种清洁机制绝非温和。一旦冒险者投入了一件沾满污垢的遗物并支付三枚银币，火花机就会陷入猛烈的搅动状态。整个铁制装置会发出呻吟、剧烈震动，并左右摇晃，将有毒的淤泥、受辐射的油脂和岩石粉尘剥离。片刻之后，它便会吐出埋藏在污垢之下的物品，从珍贵的矿物到机械零件应有尽有。"}},faq={{q="什么是火花机5200？",a="火花机5200是一台位于诺莫瑞根安全区域的侏儒自动清洁装置。它的设计初衷是去除从沦陷的城市各处回收的物品上那顽固的放射性油脂、淤泥和污垢。",al={"火花机5200的作用","火花机装置","诺莫瑞根清洁机器"}},{q="这台机器需要什么才能运作？",a="操作火花机需要一件在诺莫瑞根的怪物和碎片中发现的“脏兮兮的东西”，以及直接投入机器投币口的三枚银币作为处理费。",al={"如何使用火花机","火花机费用","火花机投入什么"}},{q="为什么战区中间会有这样一台可以运作的机器？",a="侏儒文明建立在自动化的家庭和工业便利设施之上。当穴居人入侵和有毒气体通风口摧毁了这座城市时，幸存的侏儒退守到了加固的车间里，像火花机这样的机器在那里得以保持完好并持续供电。",al={"为什么火花机会在这里","谁把火花机放进了诺莫瑞根"}},{q="清洁脏兮兮的东西后会得到什么？",a="机器会退还给你完全洗去污垢的回收物品，其中可能包含埋在淤泥下的有用贸易物资、制造石、宝石或备用的工程学零件。",al={"从火花机能得到什么","火花机掉落","脏兮兮的东西奖励"}},{q="我可以使用火花机5200不止一次吗？",a="是的。在最初的演示运行之后，只要你提供更多的脏兮兮的东西和银币，就可以通过持续的清洁任务反复使用该装置。",al={"火花机是否可重复使用","可以清洗多个脏兮兮的物品吗","更多火花机相关信息"}},{q="为什么清洁时机器会剧烈晃动？",a="诺莫瑞根内部附着的污垢密度大、毒性强且已经硬化。这台机器依靠高速搅动和内部刷洗装置来切除污垢，导致整个底盘在运作时发生晃动并发出呻吟。",al={"火花机晃动","火花机坏了吗"}}},fp="22,160,21.270.0,18.308.0,30.198.0,41.141.0,64.236.0,53.167.0,47.125.0,56.162.0"}
P.entries["quest:2952"] = {n="超级清洁器5200型！",s="在诺莫瑞根饱受辐射的大厅深处，坐落着闪光机器5200型。这是一种自动清洁装置，旨在清除回收废料上的有毒污垢。操作这台机器可以洗去污损物品上的厚重积垢，并将回收的物品包装成精美的礼盒。",h="在诺莫瑞根饱受辐射的大厅深处，坐落着闪光机器5200型。这是一种自动清洁装置，旨在清除回收废料上的有毒污垢。操作这台机器可以洗去污损物品上的厚重积垢，并将回收的物品包装成精美的礼盒。",kw={"清洁","装置","净化","诺莫瑞根","污垢","机器","闪光机器"},ang={["profession:Engineering"]="研究闪光机器可以让人一窥自动颗粒清洁和快速包装机制，这些机制经过精心设计，能够经受住强烈的环境辐射。",["race:Gnome"]="闪光机器是沦陷前家园的鲜明写照：即使是一个工业清洗装置，也必须发出欢快的叮当声，并将成品像生日礼物一样包装好交付。"},sec={{t="自动清洁",b="侏儒工程学向来推崇效率与奇思妙想并重。闪光机器5200型被制造出来用以处理有毒和受污染的废弃物，通过自动循环清除污垢和腐蚀性残留物。一旦放入物品并支付费用，该装置就会在发出嘈杂声的过程中完成清洁流程，随后发出愉快的叮当声，将剩下的残余物整齐地包裹进系着蝴蝶结的礼物中。"},{t="污泥中的宝藏",b="自诺莫瑞根沦陷于穴居人手中，随后发生辐射灾难以来，无数个人物品和技术残骸都被工业泥沼所掩埋。将脏兮兮的东西投入机器的冒险者们，可以找回在城市排气时被吞没的遗失宝石、原生矿石以及早已失传的贵重物品。"}},faq={{q="闪光机器5200型有什么用？",a="闪光机器5200型是诺莫瑞根内部的一台自动清洁机器。当提供脏兮兮的东西和一定费用时，它会清除污泥、污垢和放射性废料，并将清洁后的物品装在一个小礼盒中返还。",al={"什么是闪光机器5200型","闪光机器如何工作","闪光机器功能"}},{q="闪光机器5200型位于哪里？",a="该机器位于沦陷城市诺莫瑞根的内部走廊，靠近曾经有幸存者和自动净化系统运作的Clean Zone。",al={"闪光机器位置","清洁机器在哪里","找到闪光机器"}},{q="为什么机器会把物品包上蝴蝶结？",a="它的程序设计带有典型的侏儒式奇思妙想。即使在洗去了物品上危险的放射尘埃和有毒污垢后，其创造者也将最终循环设计为将修复后的物品包装成令人愉悦、打结整齐的礼物。",al={"为什么是礼盒","闪光机器包装礼物","系着蝴蝶结"}},{q="部落的冒险者可以使用闪光机器5200型吗？",a="可以。闪光机器5200型是一台全自动装置，不在乎阵营偏见。只要有访客投入钱币和污损的物品，机器就会执行其循环。",al={"部落闪光机器","部落可以清洁污垢吗","闪光机器是中立的吗"}},{q="我可以使用多次闪光机器吗？",a="可以。在首次操作后，机器会解锁一个可重复的任务，允许任何在地下城中发现脏兮兮的东西的人反复对其进行处理。",al={"闪光机器可以重复使用吗","闪光机器的更多用途","刷脏兮兮的东西"}},{q="这个任务之后会发生什么？",a="完成这次初始清洁后，会直接开启名为“闪光机器的更多用途”的可重复清洁循环，让你能够清洁随身携带的任何其他脏兮兮的东西。",al={"闪光机器后续任务","闪光机器5200型之后是什么"}}},fp="22,164,19.252.0,22.257.0,35.204.0,39.157.0,41.174.0,48.134.0,42.171.0,30.140.0"}
P.entries["quest:2953"] = {n="再次使用超级清洁器",s="在诺莫瑞根的辐射废墟深处，矗立着“闪光机器5200型”，这是一款在城市大撤离时留下的自动化清洁设备。只需支付少量的银币，这台机器就能卖力地把覆满在这座陨落首都内的污垢和放射性淤泥中的可回收物品刷洗干净。",h="在诺莫瑞根的辐射废墟深处，矗立着“闪光机器5200型”，这是一款在城市大撤离时留下的自动化清洁设备。只需支付少量的银币，这台机器就能卖力地把覆满在这座陨落首都内的污垢和放射性淤泥中的可回收物品刷洗干净。",kw={"自动化","清洁机器","清洁","诺莫瑞根","布满污垢的","闪光机器"},ang={["profession:Engineering"]="操作该设备可以让工程师亲眼见证强健的侏儒溶剂循环系统和投币启动的自动化功能。",["race:Gnome"]="闪光机器是侏儒机械耐用性的证明，在你们家园的有毒废墟中依然可靠地运作着。"},sec={{t="自动修复",b="闪光机器5200型代表了侏儒在穴居人入侵和随后的放射性尘埃蔓延之前，在诺莫瑞根各处安装的巧妙自动化设施。尽管走廊里充斥着有毒废料和敌对的自动装置，但只要投下三枚银币并放入一件布满污垢的文物，这台装置依然会一丝不苟地执行它的预设程序。"},{t="淤泥中的奇迹",b="当启动时，闪光机器会剧烈晃动，同时用强效的侏儒清洁溶剂冲洗和刷洗放入其中的圣物。清洗周期结束后，机器会发出一声欢快的提示音，并吐出一个包装整齐的盒子，里面装着从腐蚀性的穴居人黏液和有毒污垢下保存下来的回收品。"}},faq={{q="什么是闪光机器5200型？",a="闪光机器5200型是位于诺莫瑞根内部的侏儒自动化清洁设备。它可以清除回收物品上的腐蚀性淤泥、污垢和放射性残渣，使其恢复为可辨认的回收品。",al={"闪光机器5200型","机器的作用","诺莫瑞根清洁器"}},{q="为什么机器需要支付钱币？",a="闪光机器需要三枚银币才能启动清洗周期。其收费的具体原因并未说明。",al={"为什么要付银币","闪光机器费用"}},{q="可以放入什么样的物品？",a="该机器专门清洁布满污垢的物品，包括从死去的穴居人、腐化的哨兵以及游荡在诺莫瑞根隧道中的辐射怪物身上回收的圣物。",al={"脏兮兮的东西","我可以清洗什么物品"}},{q="闪光机器免受辐射影响吗？",a="虽然外围隧道中充满了放射性废料，但闪光机器5200型依然保持运转，部署专业的侏儒清洁剂来刷掉进入机器内部的物品表面危险的残留物。",al={"闪光机器辐射","闪光机器污染"}},{q="两个阵营都能使用闪光机器5200型吗？",a="是的。闪光机器5200型是一台完全机械化的自动化装置，以中立方式运行，无论访客阵营如何，都会接受支付和布满污垢的物品。",al={"部落闪光机器","谁能使用它"}},{q="谁设计了闪光机器？",a="其制造者没有被提及。闪光机器是一款仍在诺莫瑞根内部工作的侏儒清洁机器。",al={"闪光机器制造者","谁建造了闪光机器"}}},fp="24,191,21.313.0,21.282.0,30.201.0,34.103.0,40.158.0,40.180.0,44.149.0,30.100.0"}
P.entries["quest:2954"] = {n="石头卫士",s="你带着白金圆盘前往塔纳利斯沙漠，诺甘农的石之守护者已经出现在奥丹姆基座处。它守卫着通往奥丹姆建筑群的入口，只允许那些圆盘组合中包含奥丹姆圆盘的人进入。在继续前进之前，你得先了解它的故事。",h="你带着白金圆盘前往塔纳利斯沙漠，诺甘农的石之守护者已经出现在奥丹姆基座处。它守卫着通往奥丹姆建筑群的入口，只允许那些圆盘组合中包含奥丹姆圆盘的人进入。在继续前进之前，你得先了解它的故事。",kw={"创造者","奥丹姆圆盘","白金圆盘","诺甘农的石之守护者","塔纳利斯","奥达曼","奥丹姆","奥丹姆基座"},sec={{t="基座处的守护者",b="当你带着白金圆盘被派往塔纳利斯沙漠时，守护者的出现正是所期望的反应。它自称为入口的守卫，除非奥丹姆圆盘已经与你的圆盘组合整合，否则它不会让你进入奥丹姆建筑群。在进一步行动之前，你需要找出石之守护者背后的故事，然后使用奥丹姆基座。"},{t="守护者的解释",b="石之守护者在那里代表创造者控制谁可以进入奥丹姆建筑群，只让那些展示了正确序列圆盘的人进入。奥丹姆圆盘是创造者制作的圆盘，存储了他们在奥丹姆的活动数据。它们的大小与你自己的圆盘几乎相同，但它们的标记关注的是奥丹姆而非奥达曼。奥丹姆是一个研究设施，创造者在那里工作以增强艾泽拉斯的生物圈，而他们工作的细节是为那些持有圆盘的人准备的。最后，守护者承诺，一旦你访问基座，你的圆盘就会被归还，而且一旦你的组合中有这些圆盘，你就可以进入建筑群。"},{t="守护者提供的更多信息",b="石之守护者补充说，创造者控制着这个世界所有建筑群的这些圆盘的分配，并且艾泽拉斯已经被重新安排了访问计划。每当来自外部或内部的力量破坏了这些世界的矩阵动态平衡时，创造者就会利用访问来重新建立对已播种世界的控制，这绝非儿戏。"}},faq={{q="诺甘农的石之守护者是谁？",a="一位守卫着塔纳利斯沙漠中奥丹姆基座的入口守护者，负责决定谁可以进入奥丹姆建筑群。",al={"什么是石之守护者","奥丹姆的守护者是谁","石之守护者的身份"}},{q="为什么石之守护者拒绝进入？",a="只有当奥丹姆圆盘已经与你的圆盘组合整合时才允许进入，而你目前还没有这些圆盘。",al={"为什么我无法进入奥丹姆","缺失奥丹姆圆盘","奥丹姆拒绝进入"}}},fp="17,277,26.403.0,25.672.1,21.369.2,38.128.0,38.119.0"}
P.entries["quest:296"] = {n="奥莫尔的复仇",s="奥莫尔的复仇是奥莫尔·铁衣为在维尔加挖掘场被屠杀的矮人挖掘者复仇而进行的行动的顶点。奥莫尔确信一只名为萨尔图斯的狡猾野兽是这场凶猛迅猛龙袭击的始作俑者，于是派遣一名冒险者去杀死这个兽群首领，并取回他的爪子作为证明。",h="奥莫尔的复仇是奥莫尔·铁衣为在维尔加挖掘场被屠杀的矮人挖掘者复仇而进行的行动的顶点。奥莫尔确信一只名为萨尔图斯的狡猾野兽是这场凶猛迅猛龙袭击的始作俑者，于是派遣一名冒险者去杀死这个兽群首领，并取回他的爪子作为证明。",kw={"探险者协会","奥莫尔·铁衣","迅猛龙","萨尔图斯","爪子","湿地","维尔加挖掘场"},ang={["class:Hunter"]="萨尔图斯是湿地的顶级掠食者之一，需要敏锐的追踪技巧才能攀上山脊并击倒这位兽群首领。",["faction:Alliance"]="保障沼泽地中矮人探险队的安全，能确保铁炉堡与北方土地之间的联盟立足点保持稳固。",["race:Dwarf"]="对矮人来说，为在维尔加挖掘场被屠杀的探险者协会人员复仇，是告慰国王麦格尼逝去子民的荣誉之事。"},sec={{t="打击兽群首领",b="在探险者协会的挖掘者于维尔加挖掘场惨遭屠杀后，奥莫尔·铁衣从他的山脊上注视着成群的迅猛龙，并观察到了一只比其他迅猛龙大得多的野兽。这只名为萨尔图斯的巨大而凶残的迅猛龙栖息在挖掘场上方，指挥或领导着驱逐矮人们的兽群。对奥莫尔来说，这只野兽不仅仅是野生动物，更是攻击国王麦格尼·铜须子民的罪魁祸首。"},{t="湿地的正义",b="奥莫尔要求为这场大屠杀伸张正义，指示冒险者攀登挖掘场的高墙，终结萨尔图斯的生命。通过取回这只野兽强有力的爪子之一，倒下的工人们将得到复仇，并向整个沼泽地传递一个严厉的信息：针对矮人探险队的袭击绝不会不了了之。"}},faq={{q="谁是萨尔图斯？",a="萨尔图斯是一只巨大的、具有威胁性的迅猛龙，它领导着占据了湿地维尔加挖掘场的兽群。奥莫尔·铁衣认为它指挥了那场屠杀矮人挖掘者的袭击。",al={"谁是萨尔图斯","迅猛龙首领是谁","萨尔图斯背景故事"}},{q="萨尔图斯在哪里？",a="萨尔图斯在维尔加挖掘场西北角的一条通往西墙的高处小径上徘徊。",al={"寻找萨尔图斯","萨尔图斯在哪里刷新","萨尔图斯路径"}},{q="为什么奥莫尔想杀死萨尔图斯，而不是仅仅把它赶走？",a="奥莫尔将这场迅猛龙袭击视为直接针对国王麦格尼子民的罪行。由于无辜的矮人工作者在履行职责时丧生，奥莫尔认为唯有死亡才能告慰逝者。",al={"奥莫尔复仇的原因","为什么杀死萨尔图斯"}},{q="奥莫尔需要什么证明？",a="奥莫尔要求得到萨尔图斯的一只爪子，以证实这只巨大的掠食者确实已被杀死。",al={"萨尔图斯证明","萨尔图斯之爪"}},{q="挖掘场的受害者是谁？",a="被探险者协会派遣来挖掘泰坦神器的矮人考古学家和劳工在迅猛龙群占领挖掘场时措手不及，惨遭屠杀。",al={"谁在维尔加丧生","挖掘场受害者"}},{q="杀死萨尔图斯能确保挖掘场的安全吗？",a="虽然杀死萨尔图斯消除了兽群中最致命的威胁，并为逝者带来了报应，但迅猛龙仍然在战壕中爬行，使该地点依然危险且基本处于废弃状态。",al={"维尔加现在安全吗","奥莫尔成功了吗"}}},fp="15,246,27.406.0,23.296.0,17.190.0,27.109.0,68.194.0,30.90.0,44.193.0,50.181.0"}
P.entries["quest:2962"] = {n="更多的辐射尘！",s="在对地表的穴居人进行了早期但没有定论的测试后，奥齐·电环委托冒险者直接从诺莫瑞根内部找回纯净的高强度辐射尘。他的最终目标是了解摧毁了他的人民的有毒辐射，并为受折磨的麻风侏儒配制一种治疗方法。",h="在对地表的穴居人进行了早期但没有定论的测试后，奥齐·电环委托冒险者直接从诺莫瑞根内部找回纯净的高强度辐射尘。他的最终目标是了解摧毁了他的人民的有毒辐射，并为受折磨的麻风侏儒配制一种治疗方法。",kw={"gnogaine","诺莫瑞根","hall of gears","卡拉诺斯","麻风侏儒","奥齐·电环","辐射","辐射尘"},ang={["faction:Alliance"]="稳定丹莫罗并收复诺莫瑞根需要了解那些仍在腐蚀铁炉堡门口的致命危害。",["profession:Engineering"]="辐射储存的不稳定性需要坚固的铅屏蔽和精密的仪器，这体现了工程学失败时的灾难性后果。",["race:Gnome"]="每个侏儒都背负着失去家园的悲痛。帮助奥齐测试可怕的变异是否可以逆转，触动了他们救赎堕落同胞希望的核心。"},sec={{t="纯净样本",b="奥齐·电环在城市外的初步试验失败了。在丹莫罗游荡的受辐射穴居人身上携带的残留物不足且不纯，让他在卡拉诺斯的实验室得到的疑问比答案还多。为了给麻风侏儒设计出真正的疗法，电环断定科学的严谨性要求直接从城市深处的有毒腹地获取新鲜、浓缩的样本。"},{t="直接获取",b="要获得足够强度的辐射尘，就意味着必须深入诺莫瑞根。Hall of Gears和Clean Zone周围的下层区域挤满了因放射性废物灾难性泄漏而产生的受辐射惊骇怪、潜伏者和粘液怪。将这种不稳定的软泥提取到厚重的铅瓶中是一项危险的工作：辐射尘会迅速降解，使得储存过程极不稳定且对时间非常敏感。"}},faq={{q="为什么奥齐需要辐射尘？",a="奥齐·电环正试图为麻风侏儒合成一种解药，他们的身心在诺莫瑞根陷落期间释放的辐射尘中被摧毁了。他相信了解这种未稀释的毒素是扭转其可怕影响的第一步。",al={"奥齐·电环 治疗","为什么要获取辐射尘","麻风侏儒的治疗方法"}},{q="玩家在哪里可以找到辐射尘？",a="辐射尘必须从诺莫瑞根深处发现的活体受辐射惊骇怪、潜伏者和粘液怪身上收集，特别是在Hall of Gears周围的下层和Clean Zone之后。",al={"高强度辐射尘在哪里","辐射尘位置 诺莫瑞根"}},{q="为什么地表穴居人的样本被否决了？",a="在诺莫瑞根外游荡的穴居人没有携带足够的浓缩污染物。它们的样本太弱且不纯，无法作为奥齐治疗实验的可靠研究材料。",al={"为什么不用穴居人","gnogaine有什么问题"}},{q="为什么辐射尘有时限？",a="辐射尘非常不稳定且活跃。即使在铅制的收集瓶中，不稳定的辐射也会迅速分解，迫使研究人员必须在它失去效力之前将其送回卡拉诺斯的实验室。",al={"为什么辐射尘会失效","辐射尘持续时间"}},{q="奥齐希望帮助的麻风侏儒是谁？",a="麻风侏儒是诺莫瑞根的前公民，当为了对抗穴居人而打开辐射阀门时，他们被困在了里面。他们没有死，而是变异成了病态、疯狂的幸存者，对他们以前的同胞充满敌意。",al={"麻风侏儒背景","什么是麻风侏儒"}},{q="谁发布了这个任务？",a="这个任务由奥齐·电环发布，他是一位驻扎在丹莫罗卡拉诺斯的侏儒研究员，致力于补救诺莫瑞根灾难的后果。",al={"谁发布任务","奥齐·电环位置"}}},fp="32,127,13.315.0,21.345.0,40.206.0,39.159.0,44.164.0,35.135.0,45.188.0,22.168.0"}
P.entries["quest:2969"] = {n="精灵龙的自由",s="恐怖图腾氏族正在捕捉精灵龙，而辛达尔·月纹和杰卡伊不知道他们的目的。辛达尔请求你带上强力的盟友，用一把钥匙打开恐怖图腾营地里的笼子，并确保这些精灵龙活着逃出去。辛达尔会随你一同前往，而杰卡伊会留在原地。",h="恐怖图腾氏族正在捕捉精灵龙，而辛达尔·月纹和杰卡伊不知道他们的目的。辛达尔请求你带上强力的盟友，用一把钥匙打开恐怖图腾营地里的笼子，并确保这些精灵龙活着逃出去。辛达尔会随你一同前往，而杰卡伊会留在原地。",kw={"竹笼","艾露恩","精灵龙","菲拉斯","恐怖图腾营地","杰卡伊","辛达尔·月纹","小精龙"},sec={{t="笼中龙",b="辛达尔·月纹称捕捉精灵龙的恐怖图腾氏族卑鄙无耻，并表示无论她还是杰卡伊都无法猜出他们的计划，只知道他们没安好心。他们两人没有足够的实力杀入营地，所以辛达尔向你求助。竹笼钥匙可以打开笼子，辛达尔希望这些精灵龙能活着逃离。欢迎带上强力的盟友。"},{t="辛达尔的瞭望点",b="你可以在恐怖图腾营地后方水面上方的岩架上找到辛达尔。沿着悬崖边的一条小路向上走就能到达那里。辛达尔会随你一同杀入营地，而杰卡伊则留在原地。"},{t="后续",b="一旦精灵龙获得自由，辛达尔会感谢艾露恩。危险尚未结束：被释放的龙并不一定能一直自由，所以辛达尔和杰卡伊打算向恐怖图腾发起反击。辛达尔让你去和杰卡伊谈谈。"}},faq={{q="谁在捕捉精灵龙？",a="根据辛达尔·月纹的说法，是恐怖图腾氏族。至于他们想要这些龙做什么，辛达尔和杰卡伊也说不清楚。",al={"谁捕捉了精灵龙","谁囚禁了精灵龙","恐怖图腾笼子"}},{q="辛达尔·月纹在哪里？",a="在恐怖图腾营地后方水面上方的岩架上。穿过营地左侧，沿着树后的一条小路爬上悬崖即可到达。",al={"辛达尔在哪里","辛达尔·月纹位置","如何找到辛达尔·月纹"}},{q="杰卡伊会一起去吗？",a="不会。杰卡伊留在原地，而辛达尔会随你一同前往。",al={"杰卡伊是否帮忙","杰卡伊的参与"}},{q="我需要什么来释放精灵龙？",a="竹笼钥匙。辛达尔会把这把钥匙交给你，用它就能打开恐怖图腾营地里的笼子。辛达尔希望你带上强力的盟友。",al={"竹笼钥匙","如何释放精灵龙"}},{q="这个任务之后是什么？",a="“伸张正义”是该系列任务的下一步。",al={"“众生平等”后续任务","拯救精灵龙之后的后续"}}},fp="25,273,18.402.0,16.184.0,9.231.1,36.115.0,27.141.0,24.53.0,42.123.0,24.45.0"}
P.entries["quest:297"] = {n="收集石像",s="“收集神像”是麦格玛尔·落斧指派的一项任务，要求从被占领的挖掘场中找回神秘的雕刻石制遗物。新出土的神像对当地的穴居人产生了一种奇怪的影响，使他们陷入了暴力的狂乱之中。",h="“收集神像”是麦格玛尔·落斧指派的一项任务，要求从被占领的挖掘场中找回神秘的雕刻石制遗物。新出土的神像对当地的穴居人产生了一种奇怪的影响，使他们陷入了暴力的狂乱之中。",kw={"狂暴","雕刻石制神像","挖掘","收集神像","麦格玛尔·落斧","遗迹","穴居人"},ang={["faction:Alliance"]="联盟的冒险者协助矮人探险队在野蛮的穴居人造成进一步破坏之前，确保这些危险的遗物安全无虞。",["race:Dwarf"]="矮人挖掘者致力于从被穴居人盘踞的遗迹中找回古代神器，以揭开它们背后的历史秘密。"},sec={{t="出土的遗物",b="在野蛮的穴居人浮出地面并占领挖掘场之前不久，研究人员发现了一大批奇怪的雕刻石制神像。突如其来的穴居人袭击迫使探险队在还没来得及进行正式研究之前就逃离了遗迹。现在，这些野蛮的生物紧紧抓着古老的遗物，在挖掘场四处游荡，阻止任何人和平返回。"},{t="野蛮的狂乱",b="穴居人不仅仅是偷走了这些遗物，他们似乎深受其影响。这些奇怪的雕刻品散发出一种令人不安的力量，使这些生物陷入了无法控制的狂暴状态。为了了解这些神器究竟是什么，并平息该地区肆虐的暴力狂乱，麦格玛尔·落斧试图从穴居人手中夺回神像并进行安全研究。"}},faq={{q="谁是麦格玛尔·落斧？",a="麦格玛尔·落斧是一位挖掘者，他寻求找回在穴居人占领该地区前不久，从挖掘场出土的雕刻石制神像。",al={"谁是麦格玛尔·落斧","任务发布者","麦格玛尔"}},{q="什么是雕刻石制神像？",a="它们是在挖掘场出土的神秘雕刻石制遗物。它们拥有一种令人不安的力量，会驱使附近的穴居人陷入狂暴的疯狂之中。",al={"什么是雕刻石制神像","奇怪的神像","出土的神像"}},{q="为什么神像会让穴居人陷入狂暴？",a="神像对穴居人产生了一种奇怪且无法解释的影响，在穴居人持有这些神像时，会激起他们的狂怒并驱使他们彻底陷入疯狂。",al={"为什么穴居人会狂暴","神像使穴居人疯狂","穴居人狂怒"}},{q="为什么麦格玛尔·落斧要收集这些神像？",a="麦格玛尔·落斧希望安全地找回这些神像，以便研究它们的起源和属性，并将这些不稳定的神器从穴居人的魔爪中移除。",al={"为什么要找回神像","收集神像的目的","麦格玛尔的研究"}},{q="挖掘场发生了什么？",a="在神像被发现后不久，穴居人突然从挖掘场内部涌出，将挖掘者们赶出了遗迹。",al={"谁涌入了挖掘场","穴居人入侵","挖掘场被占领"}},{q="在哪里可以找到神像？",a="雕刻石制神像由那些盘踞在最初发现遗物的挖掘场内的穴居人所持有。",al={"去哪找神像","谁拥有神像","雕刻石制神像的位置"}}},fp="15,126,20.301.0,15.306.0,22.108.0,32.144.0,44.124.0,49.142.0,37.132.0,26.97.0"}
P.entries["quest:2970"] = {n="菲拉斯的正义",s="随着小精龙获得自由，耶尔卡·月纹和Kindal打算向恐怖图腾氏族发起反击。耶尔卡请求你消灭恐怖图腾自然学家、恐怖图腾劫掠者和恐怖图腾萨满祭司，然后回来找他。此任务紧接“众生自由”。",h="随着小精龙获得自由，耶尔卡·月纹和Kindal打算向恐怖图腾氏族发起反击。耶尔卡请求你消灭恐怖图腾自然学家、恐怖图腾劫掠者和恐怖图腾萨满祭司，然后回来找他。此任务紧接“众生自由”。",kw={"伸张正义","菲拉斯","恐怖图腾","耶尔卡·月纹","辛达尔·月纹","自然学家","劫掠者","萨满祭司"},sec={{t="反击恐怖图腾",b="在“众生自由”任务完成后，耶尔卡·月纹会告诉你，他和Kindal现在要对恐怖图腾发起反击。他们两人联手可以在几乎没有风险的情况下削减这些牛头人的数量，但他们依然欢迎你的帮助。你已经看到了下方营地的情况，在东边还有更多营地。用你自己的战术去对付恐怖图腾自然学家、恐怖图腾劫掠者和恐怖图腾萨满祭司，然后回到耶尔卡等待的地方。"}},faq={{q="谁给予“伸张正义”？",a="在Kindal告诉你他们在拯救小精龙之后的打算后，位于菲拉斯的耶尔卡·月纹会给予此任务。",al={"谁给予伸张正义","伸张正义任务发布者","耶尔卡·月纹"}},{q="哪些恐怖图腾是目标？",a="恐怖图腾氏族牛头人中的恐怖图腾自然学家、恐怖图腾劫掠者和恐怖图腾萨满祭司。",al={"我需要击杀哪些敌人","伸张正义目标","击杀恐怖图腾"}},{q="恐怖图腾营地在哪里？",a="在耶尔卡下方就能看到一个营地，耶尔卡说在东边还有更多营地。",al={"恐怖图腾在哪里","恐怖图腾营地位置","我该去哪里"}},{q="“伸张正义”之前是什么任务？",a="“众生自由”，在那个任务中你从恐怖图腾营地解救了小精龙。",al={"前置任务","伸张正义先决条件","上一步骤"}}},fp="14,243,33.408.0,25.109.0,29.103.0,30.82.0,33.89.0"}
P.entries["quest:2972"] = {n="菲拉斯的正义",s="在荒野之中，耶尔卡·月纹和Kindal没有太多东西可以用来表达谢意，所以耶尔卡递给你一枚图章戒指。你需要带着它去达纳苏斯的Temple of the Moon寻找泰兰德·语风，这枚戒指会告诉她他们二人一切安好，也能为你的故事增添可信度。此任务紧接在“执行正义”之后。",h="在荒野之中，耶尔卡·月纹和Kindal没有太多东西可以用来表达谢意，所以耶尔卡递给你一枚图章戒指。你需要带着它去达纳苏斯的Temple of the...",kw={"达纳苏斯","菲拉斯","耶尔卡·月纹","辛达尔·月纹","图章戒指","泰达希尔","temple of the moon","泰兰德·语风"},sec={{t="给大祭司的戒指",b="在菲拉斯的荒野中，耶尔卡·月纹和Kindal能拿出来的东西不多，但他们不希望让你感到不受重视。耶尔卡递给你一枚图章戒指，并指引你前往达纳苏斯，大祭司泰兰德·语风正在那里的Temple of the Moon等待。这枚戒指将证明他们二人平安无事，也能印证你所讲述的故事。"},{t="泰兰德的答复",b="泰兰德很高兴你能帮助巨龙和她的一位祭司，并表示耶尔卡让你来找她是正确的。她承诺会将戒指归还给耶尔卡。斥候很快就会前往菲拉斯，到时候他们会顺便处理这枚戒指的事宜。"}},faq={{q="谁给的图章戒指？",a="菲拉斯的耶尔卡·月纹，作为他和Kindal的谢礼。",al={"谁开启了这个任务","任务发布者"}},{q="图章戒指要送到哪里？",a="送到位于达纳苏斯Temple of the Moon的大祭司泰兰德·语风那里。",al={"我该把戒指带去哪里","任务交付地点","谁收到了耶尔卡的图章戒指"}},{q="为什么耶尔卡要给你这枚戒指？",a="耶尔卡和Kindal在荒野中没有太多东西可以提供。这枚戒指可以向泰兰德证明他们一切安好，并为你的故事提供佐证。",al={"图章戒指的用途","为什么要给耶尔卡的图章戒指"}},{q="任务链的下一步是什么？",a="任务链继续进行，接下来是“寻找家园的孤儿”。",al={"后续任务","接下来要去哪里"}}},fp="14,331,29.351.0,16.273.1,26.66.0,30.84.0,35.131.0,29.52.0"}
P.entries["quest:2973"] = {n="新斗篷的光辉",s="克鲁伊格·碎颅与他的同伴们受奥格瑞玛的主人派遣，来到了菲拉斯。克鲁伊格打算为他的伴侣科琳制作一件披风，并请求你收集十枚虹彩小精龙之翼。",h="克鲁伊格·碎颅与他的同伴们受奥格瑞玛的主人派遣，来到了菲拉斯。克鲁伊格打算为他的伴侣科琳制作一件披风，并请求你收集十枚虹彩小精龙之翼。",kw={"莫沙彻营地","披风","仙女龙","菲拉斯","虹彩之翼","科琳","克鲁伊格·碎颅","小精龙"},sec={{t="科琳的披风",b="克鲁伊格与同伴们受奥格瑞玛的主人派遣，来到了菲拉斯。克鲁伊格的伴侣科琳喜欢新衣服，所以克鲁伊格计划用仙女龙精致的翅膀装饰一件披风。克鲁伊格想要的那种拥有美丽翅膀的小精龙栖息在莫沙彻营地的西边，他请求你收集十枚虹彩小精龙之翼。"},{t="克鲁伊格的警告",b="克鲁伊格提醒说，被激怒的小精龙很危险。他还告诫你要特别小心附近那些也喜欢藏在森林里的暗夜精灵。"}},faq={{q="克鲁伊格·碎颅是谁？",a="克鲁伊格·碎颅就在莫沙彻营地。他是受奥格瑞玛主人的派遣，与同伴一起来到菲拉斯的。",al={"克鲁伊格是谁","克鲁伊格·碎颅背景故事","菲拉斯的克鲁伊格"}},{q="为什么克鲁伊格需要小精龙之翼？",a="克鲁伊格打算为喜欢新衣服的伴侣科琳制作一件装饰有仙女龙翅膀的披风。",al={"为什么需要小精龙翅膀","小精龙之翼用途","克鲁伊格在做什么"}},{q="小精龙在哪里？",a="莫沙彻营地以西。",al={"去哪里找小精龙","小精龙位置","菲拉斯的仙女龙在哪里"}},{q="克鲁伊格警告了哪些危险？",a="克鲁伊格说被激怒的小精龙很危险，而且在森林里出没的暗夜精灵也需要格外留心。",al={"克鲁伊格的警告","菲拉斯森林中的威胁"}}},fp="19,191,18.338.0,15.156.0,27.119.0,40.98.0,37.21.0,35.140.0"}
P.entries["quest:2974"] = {n="可怕的发现",s="莫沙彻营地的克鲁伊格·碎颅对于你在菲拉斯遇到牛头人的消息感到惊讶，而得知他们是恐怖图腾部族时更是如此。克鲁伊格的主人之一贝尔格罗姆曾悬赏过这一族群。克鲁伊格希望你回去带给他二十只恐怖图腾之角。",h="莫沙彻营地的克鲁伊格·碎颅对于你在菲拉斯遇到牛头人的消息感到惊讶，而得知他们是恐怖图腾部族时更是如此。克鲁伊格的主人之一贝尔格罗姆曾悬赏过这一族群。克鲁伊格希望你回去带给他二十只恐怖图腾之角。",kw={"贝尔格罗姆","莫沙彻营地","菲拉斯","恐怖图腾","犄角","克鲁伊格·碎颅"},sec={{t="恐怖图腾的传闻",b="你告诉克鲁伊格·碎颅你在该地区遇到的牛头人的事情，克鲁伊格很快就指出他们是恐怖图腾部族。克鲁伊格的主人之一贝尔格罗姆对这一族群很感兴趣，并悬赏了他们。克鲁伊格告诉你，恐怖图腾不可小觑，他们是邪恶的。你回到那里，击杀他们并把二十只角带回莫沙彻营地，这样就能在他们夷平村庄或窃取土地之前先发制人。"},{t="交付犄角",b="克鲁伊格评价这些角质量不错，并说你已经帮了两次忙了。等克鲁伊格回到奥格瑞玛，贝尔格罗姆就会听到这件事。"}},faq={{q="谁发放“严酷的发现”任务？",a="莫沙彻营地的克鲁伊格·碎颅，在你告诉克鲁伊格你在这个地区遇到了牛头人之后。",al={"谁发放严酷的发现","克鲁伊格·碎颅任务","严酷的发现任务发放者"}},{q="为什么克鲁伊格想要恐怖图腾的角？",a="克鲁伊格称恐怖图腾部族为邪恶之徒，并希望在他们夷平村庄或窃取土地之前予以打击。奥格瑞玛的一位主人贝尔格罗姆也悬赏了他们。",al={"为什么杀恐怖图腾","菲拉斯的恐怖图腾威胁","为什么需要恐怖图腾之角"}},{q="贝尔格罗姆是谁？",a="克鲁伊格称贝尔格罗姆为主人之一，他对恐怖图腾很感兴趣，并悬赏了他们。",al={"奥格瑞玛的贝尔格罗姆","贝尔格罗姆是谁"}},{q="克鲁伊格想要多少只角？",a="二十只恐怖图腾之角，带给莫沙彻营地的克鲁伊格。如果你能办到，克鲁伊格想要成堆的角。",al={"恐怖图腾之角数量","需要多少恐怖图腾之角"}},{q="“严酷的发现”后续是什么？",a="该任务线继续进行“严酷的发现（2）”。",al={"严酷的发现的后续任务","严酷的发现任务链"}}},fp="16,261,21.438.0,19.126.1,27.90.0,36.176.0,15.106.0,31.107.0,30.44.0"}
P.entries["quest:2975"] = {n="菲拉斯的食人魔",s="莫沙彻营地的洛卡·奥赫想要在戈杜尼食人魔进一步向菲拉斯扩张之前将其击退。沿着北边的河流走就能找到他们的前哨站，你需要去那里削减食人魔、食人魔法师和蛮兵的数量。",h="莫沙彻营地的洛卡·奥赫想要在戈杜尼食人魔进一步向菲拉斯扩张之前将其击退。沿着北边的河流走就能找到他们的前哨站，你需要去那里削减食人魔、食人魔法师和蛮兵的数量。",kw={"蛮兵","莫沙彻营地","菲拉斯","戈杜尼","食人魔","食人魔法师","洛卡·奥赫"},sec={{t="戈杜尼的印记",b="洛卡·奥赫指出，戈杜尼食人魔部落在这附近非常显眼，他们的存在本身就是对这片土地的创伤。必须在他们深入菲拉斯之前将他们赶回去。他们的前哨站位于北面的河流上方。去那里杀掉十个戈杜尼食人魔、十个戈杜尼食人魔法师和五个戈杜尼蛮兵，让他们知道这里不欢迎他们。"}},faq={{q="谁想要击退戈杜尼食人魔？",a="莫沙彻营地的洛卡·奥赫。",al={"谁发布任务","任务发布者","洛卡·奥赫"}},{q="为什么洛卡·奥赫想要击退戈杜尼？",a="洛卡·奥赫说他们的存在本身就破坏了这片土地，必须在他们进一步扩张到菲拉斯之前阻止他们。",al={"为什么要杀食人魔","戈杜尼的动机","为什么要与戈杜尼战斗"}},{q="戈杜尼前哨站在哪里？",a="洛卡·奥赫说沿着北边的河流走，就能找到前哨站。",al={"食人魔前哨站位置","食人魔在哪里","菲拉斯的戈杜尼位置"}},{q="需要杀死哪些戈杜尼？",a="十个戈杜尼食人魔、十个戈杜尼食人魔法师和五个戈杜尼蛮兵。",al={"要杀多少食人魔","戈杜尼击杀计数"}},{q="这个任务后续是什么？",a="任务链后续是菲拉斯的食人魔（2）。",al={"下一个任务菲拉斯的食人魔","菲拉斯的食人魔任务链"}}},fp="20,210,24.356.0,41.26.0,49.116.0,30.76.0,29.68.0,24.48.0"}
P.entries["quest:2976"] = {n="可怕的发现",s="克鲁伊格·碎颅承认曾经提到过悬赏的事，并表示干活的人理应获得最好的报酬。这些角被装进一个板条箱让你带给贝尔戈洛姆·石槌，他在奥格瑞玛的荣誉谷，他会想听听你的讲述。这是在“残酷的发现”第一部分之后。",h="克鲁伊格·碎颅承认曾经提到过悬赏的事，并表示干活的人理应获得最好的报酬。这些角被装进一个板条箱让你带给贝尔戈洛姆·石槌，他在奥格瑞玛的荣誉谷，他会想听听你的讲述。这是在“残酷的发现”第一部分之后。",kw={"贝尔戈洛姆·石槌","悬赏","菲拉斯","恐怖图腾","角","克鲁伊格·碎颅","奥格瑞玛","valley of honor"},sec={{t="装角的板条箱",b="在“残酷的发现”第一部分之后，克鲁伊格·碎颅先是吃了一惊，随即承认确实提到了悬赏。既然活是你干的，克鲁伊格觉得让你拿走最好的那份报酬是理所应当的。这些角被装进了一个板条箱交给你。这个板条箱要送去给位于荣誉谷的贝尔戈洛姆·石槌，他想知道你的见闻，并会让你的辛苦付出得到回报。"},{t="贝尔戈洛姆的兴趣",b="贝尔戈洛姆·石槌被关于恐怖图腾的消息所震惊，并询问你是否真的在菲拉斯的狩猎中遇到了他们。贝尔戈洛姆的同僚们也会想听这个故事，所以他让你在清点硬币的时候多讲一些。贝尔戈洛姆最后对你提供的情报表示了感谢。"}},faq={{q="是谁发布了“残酷的发现”的这一部分？",a="克鲁伊格·碎颅，他让人把角装进板条箱交给了你。",al={"谁发布残酷的发现","克鲁伊格·碎颅任务","残酷的发现2任务发布者"}},{q="恐怖图腾之角要送到哪里去？",a="送到贝尔戈洛姆·石槌那里，他在奥格瑞玛的荣誉谷等着。",al={"我该把角带去哪里","贝尔戈洛姆·石槌位置","残酷的发现2任务交还"}},{q="为什么悬赏归你？",a="克鲁伊格说活是你干的，所以最好的报酬理应归你。",al={"为什么是恐怖图腾之角","残酷的发现悬赏"}},{q="贝尔戈洛姆想要从你这里得到什么？",a="克鲁伊格说贝尔戈洛姆会很急切地想听听你的见闻，并会让你的辛苦付出得到回报。",al={"贝尔戈洛姆·石槌恐怖图腾","为什么要关心菲拉斯的恐怖图腾"}},{q="这一步之前是什么？",a="“残酷的发现”第一部分，在那一部分中，你带给了克鲁伊格恐怖图腾的角。",al={"残酷的发现任务链","残酷的发现2前置条件","前置任务"}}},fp="16,302,18.370.0,18.257.1,40.62.0,43.67.0,24.79.0,32.93.0,28.71.0"}
P.entries["quest:2978"] = {n="戈杜尼卷轴",s="一张弄脏的卷轴躺在戈杜尼前哨站里，捡起它可以看到上面似乎描绘了一次集会或仪式。莫沙彻营地的洛卡·奥赫会对它很感兴趣，也会在意它对戈杜尼食人魔意味着什么。",h="一张弄脏的卷轴躺在戈杜尼前哨站里，捡起它可以看到上面似乎描绘了一次集会或仪式。莫沙彻营地的洛卡·奥赫会对它很感兴趣，也会在意它对戈杜尼食人魔意味着什么。",kw={"莫沙彻营地","仪式","菲拉斯","戈杜尼前哨站","戈杜尼卷轴","食人魔","洛卡·奥赫"},sec={{t="弄脏的卷轴",b="拿起这张弄脏的卷轴，你发现它似乎描绘了某种集会或仪式。你认为莫沙彻营地的洛卡·奥赫会想要看看它，并了解这对戈杜尼食人魔可能意味着什么。"}},faq={{q="戈杜尼卷轴上画了什么？",a="它似乎展示了某种集会或仪式。",al={"卷轴上显示什么","戈杜尼卷轴内容","卷轴图画"}},{q="谁想要戈杜尼卷轴？",a="莫沙彻营地的洛卡·奥赫。",al={"谁想要卷轴","我该把卷轴交给谁","戈杜尼卷轴交任务"}},{q="戈杜尼卷轴在哪里可以找到？",a="在戈杜尼前哨站，你可以在那里拾取它。",al={"戈杜尼卷轴在哪里","戈杜尼卷轴位置"}},{q="戈杜尼卷轴之后是什么任务？",a="该任务线接下来是“黑暗仪式”。",al={"下一个任务是什么","戈杜尼卷轴之后","戈杜尼卷轴任务线"}}},fp="19,206,17.210.0,35.50.0,30.27.0,35.50.0,33.37.0"}
P.entries["quest:2979"] = {n="黑暗仪式",s="在你带回戈杜尼卷轴后，莫沙彻营地的洛卡·奥赫解读出这是戈杜尼法师领主们所策划的一场黑暗仪式的计划。洛卡·奥赫希望你能从其中一位法师领主手中夺取一颗宝珠，以便进一步了解这场仪式以及戈杜尼所使用的魔法。",h="在你带回戈杜尼卷轴后，莫沙彻营地的洛卡·奥赫解读出这是戈杜尼法师领主们所策划的一场黑暗仪式的计划。洛卡·奥赫希望你能从其中一位法师领主手中夺取一颗宝珠，以便进一步了解这场仪式以及戈杜尼所使用的魔法。",kw={"莫沙彻营地","黑暗仪式","菲拉斯","戈杜尼","戈杜尼宝珠","法师领主","洛卡·奥赫"},sec={{t="黑暗仪式的计划",b="洛卡·奥赫仔细研究了你带回的戈杜尼卷轴，将其解读为一场黑暗仪式的计划。据洛卡所知，是戈杜尼法师领主们在进行这场仪式。必须找到一位法师领主，并从他那里夺取一颗宝珠。法师的宝珠蕴含着巨大的力量，它应该能揭示更多关于这场仪式以及戈杜尼所操纵的魔法的信息。"},{t="当宝珠被送达时",b="一旦拿到宝珠，洛卡·奥赫说它将透露更多关于戈杜尼的信息，而这些知识将被用于策划他们的覆灭。"}},faq={{q="谁给予黑暗仪式任务？",a="莫沙彻营地的洛卡·奥赫，在你带回戈杜尼卷轴之后。",al={"谁给予黑暗仪式","黑暗仪式任务给予者"}},{q="谁在执行这场黑暗仪式？",a="洛卡·奥赫从计划中解读出，是戈杜尼法师领主们在执行仪式。",al={"谁在执行黑暗仪式","戈杜尼仪式领导者"}},{q="洛卡·奥赫想要什么样的宝珠？",a="一颗从戈杜尼法师领主手中夺取的宝珠。法师的宝珠蕴含着强大的力量，洛卡·奥赫希望能借此了解更多关于这场仪式和戈杜尼魔法的信息。",al={"为什么要获取戈杜尼宝珠","戈杜尼宝珠的目的"}},{q="黑暗仪式之后是什么？",a="该任务线接下来是戈杜尼宝珠。",al={"黑暗仪式后的下一个任务","黑暗仪式任务线"}}},fp="13,246,25.346.0,25.133.1,24.69.0,34.75.0,28.170.0,27.40.0"}
P.entries["quest:298"] = {n="挖掘进度报告",s="“挖掘进度报告”是联盟的一项跑腿任务，需要从洛克莫丹的挖掘场送回镇上。勘察员基恩萨·铁环会委托一位冒险者将他最新的挖掘报告和一份炸药补给订单送到塞尔萨玛的吉恩·角盔手中。",h="“挖掘进度报告”是联盟的一项跑腿任务，需要从洛克莫丹的挖掘场送回镇上。勘察员基恩萨·铁环会委托一位冒险者将他最新的挖掘报告和一份炸药补给订单送到塞尔萨玛的吉恩·角盔手中。",kw={"爆破粉","挖掘进度报告","探险者协会","吉恩·角盔","洛克莫丹","勘察员基恩萨·铁环","塞尔萨玛","穴居人"},ang={["faction:Alliance"]="保持塞尔萨玛与偏远哨所之间的补给线畅通，可以确保联盟在整个洛克莫丹群山中保持稳固的权威。",["profession:Mining"]="矿工们非常了解在破碎致密基岩和挖掘古代地层时，可靠的爆破粉是多么必要。",["race:Dwarf"]="对于矮人冒险者来说，帮助铁环维护了探险者协会至关重要的历史追求，并保护了族人免受贪婪穴居人的入侵。"},sec={{t="致塞尔萨玛的公文",b="勘察员基恩萨·铁环在洛克莫丹的考古工作需要附近定居点的持续后勤支持。挖掘是项艰苦的劳动，需要镐头、人力和大量的爆破粉来劈开顽固的基岩。铁环依靠信使将他的定期状态报告和物资申请单送到驻扎在塞尔萨玛的当地探险队联络员吉恩·角盔那里。"},{t="丢失的军需品",b="收到铁环的公文后，吉恩·角盔得知挖掘现场正面临凶猛穴居人的严重骚扰。虽然吉恩·角盔同意提供粉末来炸开岩石或轰炸穴居人是值得的工作，但铁环重新提出的申请引发了直接的担忧。吉恩·角盔在几周前就已经发运了一大批爆破粉，这让他不禁怀疑，那些失踪的军需品在崎岖的山路上究竟遭遇了什么。"}},faq={{q="是谁把这份报告交给你的？",a="勘察员基恩萨·铁环在位于洛克莫丹东南丘陵的铁环挖掘场交给你这份报告。他正在那里监督考古挖掘工作。",al={"任务发布者","谁开启挖掘进度报告","铁环位置"}},{q="谁是吉恩·角盔？",a="吉恩·角盔是探险者协会驻扎在塞尔萨玛的一位矮人联络员。他负责协调洛克莫丹各地考古探险队的当地后勤和补给。",al={"吉恩·角盔在哪里","谁是接收者","塞尔萨玛联络员"}},{q="为什么勘察员基恩萨·铁环需要更多的爆破粉？",a="铁环表面上需要爆破粉来清理挖掘用的坚硬岩石。然而，挖掘现场到处都是充满敌意的穴居人，这使得炸药在防御方面也同样至关重要。",al={"为什么要爆破粉","铁环为何需要粉末"}},{q="上一批粉末运到哪里去了？",a="吉恩·角盔几周前发出了一批爆破粉，但从未抵达挖掘场。它的神秘失踪预示着连接塞尔萨玛和边远站点之间的补给线出现了问题。",al={"粉末去哪了","丢失的爆破粉"}},{q="递交进度报告后会发生什么？",a="在审阅了铁环的困境和尚未解决的粉末失踪问题后，吉恩·角盔会指示你将探险队的情况汇报给铁炉堡的上级。",al={"后续任务","接下来做什么","向铁炉堡汇报"}},{q="为什么穴居人会攻击挖掘现场？",a="矮人的挖掘工作经常会挖出地下墓室并干扰穴居人的巢穴。这些生物将矿工视为领地入侵者，并会猛烈袭击任何在地下挖掘的人。",al={"穴居人攻击原因","为什么穴居人讨厌铁环"}}},fp="26,133,23.204.0,17.267.1,29.150.0,21.160.0,51.159.0,49.173.0,50.144.0,45.147.0"}
P.entries["quest:2980"] = {n="菲拉斯的食人魔",s="莫沙彻营地的洛卡·奥赫确信你是一名真正的战士，便派你去营地西南方的高原荒野。在暗夜精灵曾经拥有的遗迹废墟中，戈杜尼食人魔正变得比以前更加强悍，必须将它们击退。此任务紧随“菲拉斯的食人魔”之后。",h="莫沙彻营地的洛卡·奥赫确信你是一名真正的战士，便派你去营地西南方的高原荒野。在暗夜精灵曾经拥有的遗迹废墟中，戈杜尼食人魔正变得比以前更加强悍，必须将它们击退。此任务紧随“菲拉斯的食人魔”之后。",kw={"莫沙彻营地","菲拉斯","戈杜尼","高原荒野","重锤者","洛卡·奥赫","萨满祭司","术士"},sec={{t="前往高原荒野",b="洛卡·奥赫认为你已经证明了自己是一名真正的战士，并委托你执行下一阶段的任务。高原荒野位于营地的西南方，那里有暗夜精灵曾拥有的废弃且破损的建筑。枯萎的树木和亵渎的土地表明了戈杜尼食人魔的所在地。洛卡警告说，这些食人魔比之前的那些要强悍得多。必须击杀十个戈杜尼萨满祭司、十个戈杜尼术士和五个戈杜尼重锤者。"}},faq={{q="谁派你去高原荒野？",a="莫沙彻营地的洛卡·奥赫。",al={"任务发放者","洛卡·奥赫","谁开启任务"}},{q="这些戈杜尼食人魔在哪里？",a="在莫沙彻营地西南方的高原荒野，围绕着暗夜精灵曾拥有过的破损建筑。枯萎的树木和亵渎的土地就是标志。",al={"食人魔在哪里","高原荒野位置","废墟位置"}},{q="必须杀死哪些食人魔？",a="十个戈杜尼萨满祭司、十个戈杜尼术士和五个戈杜尼重锤者。",al={"要杀谁","食人魔目标","戈杜尼类型"}},{q="这一步之前是什么？",a="第一阶段“菲拉斯的食人魔”，洛卡·奥赫在那时派你去对付北边前哨站的食人魔。",al={"前置条件","上一个任务","任务链顺序"}}},fp="20,276,24.452.0,37.26.0,25.166.0,27.70.0,28.108.0"}
P.entries["quest:2982"] = {n="高原荒野",s="安吉拉斯·月风和Troyas一直在考察菲拉斯森林中的古老遗迹，但最近Troyas开始独自前往高原荒野，这让安吉拉斯感到担忧。Gordunni食人魔占据了那片土地。安吉拉斯希望你能通过铲除那些食人魔，让东南方的遗迹变得稍微安全一些。",h="安吉拉斯·月风和Troyas一直在考察菲拉斯森林中的古老遗迹，但最近Troyas开始独自前往高原荒野，这让安吉拉斯感到担忧。Gordunni食人魔占据了那片土地。安吉拉斯希望你能通过铲除那些食人魔，让东南方的遗迹变得稍微...",kw={"安吉拉斯·月风","菲拉斯","gordunni","gordunni蛮兵","gordunni萨满祭司","gordunni术士","高原荒野","食人魔","troyas"},sec={{t="对Troyas的担忧",b="安吉拉斯·月风承认这项工作很危险，但她和Troyas一直都在考察散布在菲拉斯森林中的遗迹。最近，Troyas独自前往高原荒野，这让安吉拉斯很担心。Gordunni食人魔已经占领了那里，并且对进入其领地的任何人都不友善。安吉拉斯希望你能前往东南方的遗迹，铲除其中的一些食人魔，好让Troyas的处境更安全些：击败八个Gordunni术士、八个Gordunni萨满祭司和八个Gordunni蛮兵。"},{t="事成之后",b="一旦任务完成，安吉拉斯会非常感激，并请你不要向Troyas透露半个字。"}},faq={{q="是谁让你去清理高原荒野的？",a="安吉拉斯·月风，她和Troyas一起调查菲拉斯的遗迹。",al={"谁是安吉拉斯","安吉拉斯·月风","谁发布了高原荒野的任务"}},{q="为什么安吉拉斯想要消减Gordunni食人魔的数量？",a="Troyas一直独自前往高原荒野，这让安吉拉斯很担心。Gordunni食人魔已经占据了该地区，并且不欢迎任何访客进入他们的领地。",al={"为什么要杀gordunni","为什么要杀高原荒野的食人魔","安吉拉斯的理由"}},{q="高原荒野的遗迹在哪里？",a="安吉拉斯指引你前往东南方的遗迹。",al={"高原荒野在哪里","高原荒野的位置","东南方的遗迹"}},{q="必须消灭哪些Gordunni？",a="八个Gordunni术士、八个Gordunni萨满祭司和八个Gordunni蛮兵。",al={"我在高原荒野要杀谁","高原荒野的gordunni目标"}},{q="关于Gordunni的魔法有什么说法？",a="安吉拉斯警告说，Gordunni的魔法似乎在摧残他们脚下的土地，并叮嘱你在他们附近时要保持警惕。",al={"gordunni的魔法","食人魔的法术","什么魔法造成了破坏"}}},fp="19,277,16.494.0,9.94.1,46.79.0,53.159.0,34.49.0,29.74.0,40.128.0"}
P.entries["quest:2985"] = {n="水之召唤",s="Call of Water标志着萨满祭司开始与治愈和适应的流体元素进行交流。在证明了对大地和火焰的掌控之后，初学者会在剃刀岭受到斯瓦特的指引，前往贫瘠之地东海岸寻找隐居的水之先知伊斯伦。",h="Call of Water标志着萨满祭司开始与治愈和适应的流体元素进行交流。在证明了对大地和火焰的掌控之后，初学者会在剃刀岭受到斯瓦特的指引，前往贫瘠之地东海岸寻找隐居的水之先知伊斯伦。",kw={"call of water","水之先知伊斯伦","棘齿城","剃刀岭","萨满祭司","怒水河","斯瓦特","贫瘠之地","水之图腾"},ang={["class:Shaman"]="这次召唤标志着从毁灭之火和坚毅大地向修复、恢复之力的水元素的关键转变，解锁了施放治疗图腾所需的精神导管。",["faction:Horde"]="卡利姆多各地的部落萨满祭司——无论是兽人、巨魔还是牛头人——都会被指引前往贫瘠之地海岸的水之先知伊斯伦处，以进行他们的水之洗礼。"},sec={{t="元素的转变",b="萨满祭司的修行需要平衡。在学会了大地坚定的韧性并忍受了火焰狂野的凶猛之后，初学者们被召唤去感受水流那灵动且富有适应力的本质。在剃刀岭，兽人萨满训练师斯瓦特会评估学生们的精神成长。当一名初学者证明了自己能够驾驭烈焰而不被其吞噬，斯瓦特就会认定他们的精神已经足够坚韧，可以去寻求水的教诲了。"},{t="商旅海岸的隐士",b="为了学习水之灵魂的秘密，萨满祭司必须沿怒水河南下进入贫瘠之地，并向东推进至海岸，就在繁忙的地精港口棘齿城之外。在那里，在巨大的鲨鱼尸骸旁的海滩上，住着水之先知伊斯伦。与杜隆塔尔城镇中的训练师不同，伊斯伦居住在咸涩的海浪无休止地拍打陆地的地方，她是部落与水进行沟通的主要指引者。"}},faq={{q="谁发布了这个任务？",a="剃刀岭的兽人萨满训练师斯瓦特会在你证明了自己对火焰和大地的掌控后，发布这个任务。",al={"任务发布者","谁开启call of water","斯瓦特"}},{q="我可以在哪里找到水之先知伊斯伦？",a="水之先知伊斯伦居住在贫瘠之地的东海岸，棘齿城以南。沿着怒水河南下离开杜隆塔尔，朝棘齿城过后的海岸方向前进，寻找她那以巨大的搁浅鲨鱼为标志的营地。",al={"伊斯伦在哪里","伊斯伦位置","如何找到水之先知伊斯伦"}},{q="为什么萨满祭司必须按特定顺序学习元素？",a="萨满传统要求初学者循序渐进地建立精神平衡。在有了大地的稳固和火焰的磨砺后，灵魂变得足够稳定，才能承受水那灵动、多变且纯净的特质，而不至于被冲走。",al={"元素顺序","为什么火之后是水","萨满祭司进阶"}},{q="其他职业可以接这个任务吗？",a="不能。Call of Water任务是萨满祭司专属的，他们需要通过任务来赢得水之灵魂的青睐并获得他们的水之图腾。",al={"非萨满职业可以完成吗","call of water是萨满专属吗"}},{q="我在寻找伊斯伦时应该注意什么地标？",a="寻找棘齿城以南海岸线上一条巨大的搁浅鲨鱼。伊斯伦就在它旁边搭建了住所。",al={"鲨鱼地标","如何发现伊斯伦的营地","伊斯伦海岸"}},{q="找到水之先知伊斯伦之后会发生什么？",a="与伊斯伦交谈将开启真正的水之试炼，要求萨满祭司横跨卡利姆多和洛丹伦去收集纯净的水滴并面对各种灵魂，之后才能获得图腾。",al={"下一步","伊斯伦的作用","call of water之后"}}},fp="13,178,23.275.0,33.324.0,21.109.0,33.204.0,57.149.0,41.93.0,57.86.0,44.176.1"}
P.entries["quest:2987"] = {n="戈杜尼钴矿石",s="奥尔文·吉兹米克刚到菲拉斯，听说戈杜尼食人魔埋藏了一些有趣的矿石。奥尔文提供了一把铲子，并让你前往莫沙彻营地以北的戈杜尼前哨站，循着蓝色的光芒挖掘十二份戈杜尼钴矿。",h="奥尔文·吉兹米克刚到菲拉斯，听说戈杜尼食人魔埋藏了一些有趣的矿石。奥尔文提供了一把铲子，并让你前往莫沙彻营地以北的戈杜尼前哨站，循着蓝色的光芒挖掘十二份戈杜尼钴矿。",kw={"莫沙彻营地","钴矿","菲拉斯","吉兹米克","戈杜尼","戈杜尼前哨站","食人魔","奥尔文","铲子"},sec={{t="埋藏的矿石",b="奥尔文·吉兹米克才刚刚抵达菲拉斯，就听说戈杜尼食人魔拥有一些有趣的矿石。奥尔文不知道食人魔想干什么，但他们守护得非常严密，从不随手乱放。他们把矿石埋了起来，以防像奥尔文这样的人染指。奥尔文给了你一把铲子。戈杜尼前哨站位于营地以北；蓝色的光芒指明了挖掘的位置。需要收集十二份戈杜尼钴矿。"},{t="当交付钴矿时",b="奥尔文打算在接下来的旅途中带着这些钴矿，他确信会有人出高价购买，并会给你一些报酬作为辛苦费。"}},faq={{q="谁需要戈杜尼钴矿？",a="位于莫沙彻营地的奥尔文·吉兹米克，他刚到菲拉斯。",al={"戈杜尼钴矿任务起始人","奥尔文·吉兹米克任务","谁需要钴矿"}},{q="戈杜尼钴矿在哪里？",a="埋藏在莫沙彻营地以北的戈杜尼前哨站。",al={"戈杜尼钴矿位置","菲拉斯哪里能找到钴矿","戈杜尼前哨站在哪里"}},{q="如何发现埋藏的钴矿？",a="蓝色的光芒会显示位置，然后你就可以进行挖掘。",al={"如何发现钴矿","在菲拉斯寻找钴矿","食人魔埋藏地的蓝光"}},{q="为什么食人魔要埋藏他们的钴矿？",a="奥尔文说食人魔对这些矿石保护有加，将它们埋起来是为了防止像奥尔文这样的人染指。至于他们想要这些矿石做什么，奥尔文也说不清楚。",al={"为什么钴矿被埋起来","为什么戈杜尼食人魔要埋藏钴矿","埋藏的食人魔钴矿"}},{q="奥尔文需要多少钴矿？",a="十二份，需要用奥尔文的铲子挖掘。",al={"钴矿数量","需要多少戈杜尼钴矿"}}},fp="15,273,15.431.0,28.147.1,26.65.0,29.54.0,34.50.0,35.144.0,32.43.0"}
P.entries["quest:2988"] = {n="枯木巨魔的牢笼",s="鹰巢山狮鹫管理员塔隆艾克斯告诉你，最强大的狮鹫迅翼的后代——利喙失踪了。据推测，这只幼狮鹫是被巨魔抓走的。他请求你去枯木巨魔的两个村庄，搜查所有的笼子，寻找利喙的踪迹。",h="鹰巢山狮鹫管理员塔隆艾克斯告诉你，最强大的狮鹫迅翼的后代——利喙失踪了。据推测，这只幼狮鹫是被巨魔抓走的。他请求你去枯木巨魔的两个村庄，搜查所有的笼子，寻找利喙的踪迹。",kw={"笼子","狮鹫","辛特兰","利喙","迅翼","塔隆艾克斯","巨魔","枯木"},sec={{t="失踪的后代",b="利喙几天前与他的父母外出狩猎时失踪了。塔隆艾克斯和其他人认为巨魔抓走了他，因此请求你的帮助。你需要去枯木巨魔的两个村庄查看三个笼子，并将你的发现告诉塔隆艾克斯。"},{t="来自村庄的消息",b="利喙不在枯木村庄里。塔隆艾克斯听到这个消息后神情严峻。这只幼狮鹫注定要带领下一代狮鹫，如果他丢了，狮鹫群的力量和精神将会遭受重创。"}},faq={{q="利喙是谁？",a="利喙是迅翼的后代，塔隆艾克斯称迅翼为最强大的狮鹫。利喙在几天前与父母狩猎时失踪了。",al={"利喙","这只狮鹫是谁","迅翼的后代"}},{q="为什么怀疑是枯木巨魔干的？",a="塔隆艾克斯和其他人认为巨魔抓走了利喙，所以枯木村庄的笼子是首要搜查目标。",al={"为什么是巨魔","枯木部族的牵连","谁抓走了利喙"}},{q="我该去哪里寻找利喙？",a="去枯木巨魔的两个村庄查看笼子，然后回来告诉狮鹫管理员塔隆艾克斯你的发现。",al={"笼子在哪里","枯木笼子位置","去哪里寻找利喙"}}},fp="16,176,14.270.0,22.200.1,17.152.0,40.133.0,32.122.0"}
P.entries["quest:2989"] = {n="祖尔祭坛",s="枯木巨魔那里没有尖喙，因此狮鹫管理员塔隆艾克斯怀疑是不是邪枝巨魔把这只幼年狮鹫抓走了。你被派往邪枝巨魔领地西侧边缘的祖尔祭坛去寻找它。",h="枯木巨魔那里没有尖喙，因此狮鹫管理员塔隆艾克斯怀疑是不是邪枝巨魔把这只幼年狮鹫抓走了。你被派往邪枝巨魔领地西侧边缘的祖尔祭坛去寻找它。",kw={"祖尔祭坛","狮鹫管理员塔隆艾克斯","辛特兰","尖喙","邪枝巨魔","枯木巨魔"},sec={{t="另一个部落，另一番搜寻",b="枯木巨魔的笼子里没有尖喙的踪迹。塔隆艾克斯现在怀疑是邪枝巨魔干的，并派你去他们领地西侧边缘的祖尔祭坛，去祭坛顶部寻找那只幼年狮鹫。塔隆艾克斯不敢去想，如果落入邪枝巨魔手中，那只俘虏会遭遇什么。"},{t="来自祭坛的消息",b="尖喙不在祭坛上。塔隆艾克斯认为这既是坏消息也是好消息：众所周知，邪枝巨魔会进行献祭仪式，所以没在那里找到这只狮鹫也算是一种解脱。塔隆艾克斯感谢你的帮助，并表示前方还有更艰巨的任务在等着。"}},faq={{q="为什么狮鹫管理员塔隆艾克斯要派你去祖尔祭坛？",a="枯木巨魔那里没有尖喙，所以塔隆艾克斯认为可能是邪枝巨魔把它抓走了。",al={"为什么去祖尔祭坛","去祖尔祭坛的原因","为何前往祖尔祭坛"}},{q="祖尔祭坛在哪里？",a="祖尔祭坛位于辛特兰邪枝巨魔领地的西侧边缘。你需要去检查一下祭坛顶部。",al={"祖尔祭坛位置","祖尔祭坛在哪里"}},{q="尖喙是谁？",a="尖喙是迅翼的后代，也是塔隆艾克斯自其失踪后一直在寻找的幼年狮鹫。",al={"尖喙是谁","尖喙背景故事"}},{q="为什么塔隆艾克斯担心邪枝巨魔？",a="塔隆艾克斯担心，如果邪枝巨魔抓到了尖喙，没人知道他们会怎么对待它。",al={"为什么邪枝巨魔很危险","邪枝巨魔的行为"}}},fp="16,235,29.312.0,19.269.1,62.105.0,34.113.0,17.103.0,52.99.0"}
P.entries["quest:299"] = {n="发现历史",s="勘察员维尔加需要从他在湿地被占据的挖掘场中找到四块戈阿兹之石。石上的铭文还等待着翻译。",h="勘察员维尔加需要从他在湿地被占据的挖掘场中找到四块戈阿兹之石。石上的铭文还等待着翻译。",kw={"ados","戈阿兹之石","golm","modr","neru","上古之神","勘察员维尔加","泰坦","揭开往事","湿地","维尔加挖掘场"},ang={["faction:Alliance"]="支持探险者协会在整个湿地的挖掘工作可以加强联盟的地位，并在宝贵的知识落入野蛮或敌对势力手中之前将其保护起来。",["race:Dwarf"]="探险者协会认为每一件回收的圣物对于解开矮人起源之谜都至关重要，而戈阿兹之石上的泰坦铭文直接关联着那段古老的传承。"},sec={{t="碎裂的石板",b="在猛禽类生物蜂拥至湿地的这处挖掘场之前，勘察员维尔加发掘出了一件重要的圣物：戈阿兹之石。起初，尝试破译其古老文字的工作只断断续续地解读出了一些关于“神圣计划”和“末日预言”的只言片语。遗憾的是，石板的关键部分在四处地方断裂开来，重要内容散落在满是化石的泥土之中。"},{t="勇闯挖掘场",b="重建这块石板需要搜寻被猛禽类生物占据的挖掘场地，找到四块失落的碎片：Ados、Modr、Golm和Neru。这些碎片埋藏在松软的泥土和半挖掘出来的文物之中，周围有充满攻击性的剃刀爪和镰爪猛禽守护，想要找齐每一块碎片，就必须杀出重围，击败这些沼泽地中的顶级掠食者。"},{t="禁锢于大地之下",b="当戈阿兹之石被拼凑完整后，它显露出了泰坦那微妙而晦涩的语言。维尔加破译了重新组合后的符文，揭示出了一段令人不寒而栗的铭文：“古神……禁锢于大地之下。”这绝非单纯的历史奇闻，石板暗示了世界初创时期泰坦所经历的斗争，以及埋藏在艾泽拉斯地壳之下的阴影邪恶。"}},faq={{q="什么是戈阿兹之石？",a="戈阿兹之石是勘察员维尔加在湿地的挖掘场发现的一件古老的泰坦圣物。它包含了关于宇宙历史、神圣计划以及禁锢在深层地底的古老实体的神秘铭文。",al={"戈阿兹之石背景故事","什么是戈阿兹石板","湿地石板碎片"}},{q="谁发布了“揭开往事”这个任务？",a="勘察员维尔加在湿地米奈希尔港以东，维尔加挖掘场上方的高处发布了这个任务。他因受到野性猛禽的威胁而被赶出了挖掘场。",al={"谁开启了揭开往事任务","在哪里接取揭开往事"}},{q="完成石板需要哪些碎片？",a="你需要四块特定的石板碎片：Ados、Modr、Golm和Neru。它们散落在猛禽出没的采石场各处的松软土堆和古代瓮中。",al={"需要哪些碎片","石板碎片名称","ados modr golm neru"}},{q="为什么勘察员维尔加不能亲自去回收碎片？",a="维尔加是一位年迈的矮人学者。当凶残的猛禽突然入侵并占领了采石场时，他被迫撤退，且没有足够的体力独自与这些猛禽群战斗。",al={"为什么维尔加不自己去拿石头","为什么维尔加请求你帮忙"}},{q="破译后的泰坦符文揭示了什么？",a="当四块失落的碎片归位后，维尔加破译了泰坦文字，读出了这段话：“古神……禁锢于大地之下。”这暗示了在塑造艾泽拉斯时被锁住的远古宇宙实体。",al={"戈阿兹之石说了什么","湿地泰坦语言翻译","古神禁锢于大地之下"}},{q="这个任务与其他附近的探险活动有关联吗？",a="是的。它直接补充了奥莫尔·铁衣的任务线“奥莫尔的复仇”，该任务要求冒险者在同一个挖掘场削减猛禽的数量。",al={"挖掘场附近的任务","奥莫尔·铁衣关联","奥莫尔的复仇任务链接"}}},fx={["2fe7ef8c"]={q="为什么勘察员维尔加想要找回石板碎片？",a="勘察员维尔加在迅猛龙攻占挖掘现场前，发现了一件名为戈阿兹之石的巨大遗物。石碑上已翻译的泰坦文字提到了“神圣计划”和“注定毁灭的预言”，但铭文在四处缺失的部分处戛然而止。维尔加担心时日无多，急切地想要重新拼好整块石板，以便解读剩下的文字，揭开埋藏在挖掘现场地下的秘密。",al={"维尔加的动机","为什么要找碎片","维尔加为什么需要碎片"}},f38df7d0={q="阿多斯、莫德、戈尔姆和涅鲁碎片是什么？",a="阿多斯、莫德、戈尔姆和涅鲁碎片是从戈阿兹之石上断裂缺失的四块碎片。每块碎片都刻有一段古老的泰坦文字，是补全铭文所必需的。将它们重新嵌回主石板后，勘察员维尔加就能完成文本翻译，揭示有关被囚禁在地下的古老存在的不祥篇章。",al={"碎片是什么","阿多斯 莫德 戈尔姆 涅鲁","石板碎片的含义"}}},fp="19,135,16.274.0,20.277.0,24.249.1,23.184.1,40.167.0,49.150.0,59.169.0,43.188.1,54.107.0"}
P.entries["quest:2990"] = {n="萨迪斯·格希德",s="狮鹫管理员塔隆斧递给你一根从幼狮鹫锋喙的巢穴中取出的羽毛。你需要把它带给居住在诅咒之地守望堡法师塔里的占卜师萨迪斯·格希德。",h="狮鹫管理员塔隆斧递给你一根从幼狮鹫锋喙的巢穴中取出的羽毛。你需要把它带给居住在诅咒之地守望堡法师塔里的占卜师萨迪斯·格希德。",kw={"鹰巢山","诅咒之地","占卜","狮鹫","守望堡","锋喙","塔隆斧","萨迪斯·格希德"},sec={{t="给占卜师的恳求",b="多年前，萨迪斯·格希德离开了鹰巢山去追寻更黑暗的知识，但塔隆斧说他的内心依然属于蛮锤部族。如果幸运的话，借助占卜魔法和从锋喙巢穴取来的羽毛，萨迪斯或许能找到这只幼狮鹫。塔隆斧说，你能在诅咒之地守望堡的法师塔里找到萨迪斯。"},{t="占卜师的欢迎",b="萨迪斯把你当作一位带着礼物的人来迎接。他一眼就看出那根羽毛属于一只优秀的狮鹫，如果这只狮鹫能平安长大，未来必将成就非凡。随后，他让你仔细听好。"}},faq={{q="萨迪斯·格希德是谁？",a="萨迪斯·格希德是一位占卜师。多年前他离开了鹰巢山去追寻更黑暗的知识，但塔隆斧说他的内心依然属于蛮锤部族。",al={"萨迪斯·格希德背景故事","萨迪斯是谁"}},{q="为什么你需要锋喙的羽毛？",a="这根羽毛是在锋喙栖息的巢穴中收集到的。塔隆斧希望萨迪斯能利用他的占卜魔法，通过羽毛找到这只幼年狮鹫。",al={"为什么需要锋喙的羽毛","羽毛的用途"}},{q="萨迪斯·格希德在哪里？",a="萨迪斯·格希德居住在诅咒之地的守望堡法师塔内。",al={"萨迪斯·格希德位置","萨迪斯在哪里"}}},fp="17,210,19.325.0,21.203.1,25.142.0,36.144.0,35.80.0"}
P.entries["quest:2992"] = {n="占卜",s="萨迪斯·格希德让你离远一点，好让他进行占卜仪式。他打算顺着你带来的那根羽毛与它主人之间的联系，一直追踪到锋喙的位置。",h="萨迪斯·格希德让你离远一点，好让他进行占卜仪式。他打算顺着你带来的那根羽毛与它主人之间的联系，一直追踪到锋喙的位置。",kw={"羽毛","狮鹫","仪式","锋喙","萨迪斯·格希德","占卜"},sec={{t="占卜仪式",b="萨迪斯顺着锋喙的羽毛与这只狮鹫主人之间的联系进行追踪，希望能借此找到锋喙本人。他要求保持安静，并给他留出足够的空间。他承认仪式可能会出错，并警告说如果发生那种情况，你最好闭上眼睛。"},{t="当仪式结束时",b="仪式成功了。萨迪斯瞥见了锋喙的踪迹，并能告诉你去哪里寻找。"}},faq={{q="萨迪斯·格希德在仪式中做什么？",a="萨迪斯正在进行占卜仪式。他正在寻找你带来的羽毛与锋喙之间的联系，并打算顺着这条线索亲自找到锋喙。",al={"什么是占卜","格希德的仪式","格希德如何找到锋喙"}},{q="锋喙是谁？",a="锋喙是一只幼年狮鹫，你带给萨迪斯的那根羽毛就是它的，也是狮鹫管理员塔隆斧一直在努力寻找的对象。",al={"锋喙","锋喙是谁"}},{q="仪式危险吗？",a="萨迪斯警告说，如果仪式没有按计划进行，你最好闭上眼睛。他请求你在他工作时离远一点。",al={"占卜危险吗","为什么要闭上眼睛","占卜风险"}}},fp="14,192,22.247.0,20.90.1,47.150.0,17.126.0,24.140.0"}
P.entries["quest:2993"] = {n="返回辛特兰",s="萨迪斯·格希德告诉了你锐喙被关押的地方：在辛特兰辛萨罗山顶的一座悬崖边上的笼子里。邪枝巨魔的高阶女祭司——邪恶女祭司海克斯拥有钥匙。你需要把这个消息带给鹰巢山狮鹫管理员塔隆艾克斯。",h="萨迪斯·格希德告诉了你锐喙被关押的地方：在辛特兰辛萨罗山顶的一座悬崖边上的笼子里。邪枝巨魔的高阶女祭司——邪恶女祭司海克斯拥有钥匙。你需要把这个消息带给鹰巢山狮鹫管理员塔隆艾克斯。",kw={"狮鹫管理员塔隆艾克斯","辛特兰","辛萨罗","锐喙","萨迪斯·格希德","邪恶女祭司海克斯","邪枝"},sec={{t="锐喙的下落",b="萨迪斯完成了他的任务，他祝你好运并告诉你他所打探到的消息。锐喙被关在辛特兰辛萨罗山顶一座高悬崖上的笼子里。邪枝巨魔的高阶女祭司，邪恶女祭司海克斯，拥有那个笼子的钥匙。把这个消息带给狮鹫管理员塔隆艾克斯。"},{t="塔隆艾克斯的答复",b="塔隆艾克斯询问萨迪斯说了些什么。在得知邪枝巨魔抓住了锐喙后，塔隆艾克斯感到无法忍受，并宣称必须组织一支力量去救回这只狮鹫。"}},faq={{q="是谁透露了锐喙的下落？",a="萨迪斯·格希德，他在执行了占卜仪式后告诉你锐喙被关押在什么地方。",al={"谁告诉你锐喙的位置","锐喙位置来源","谁找到了锐喙"}},{q="锐喙被关在哪里？",a="锐喙被关在辛特兰辛萨罗山顶的一座高悬崖上的笼子里。",al={"锐喙在哪里","锐喙的关押地点","锐喙的悬崖"}},{q="谁拥有锐喙笼子的钥匙？",a="邪枝巨魔的高阶女祭司，邪恶女祭司海克斯，持有钥匙。",al={"锐喙的钥匙","谁有笼子钥匙","邪恶女祭司海克斯的钥匙"}},{q="你应该把这个消息交给谁？",a="把它带给辛特兰的狮鹫管理员塔隆艾克斯。",al={"我应该找谁汇报","重返辛特兰的任务交接地点","狮鹫管理员塔隆艾克斯的位置"}},{q="在此次任务之前发生了什么？",a="萨迪斯·格希德刚刚执行了占卜仪式以寻找锐喙。",al={"上一个任务","是什么导致了重返辛特兰","前置步骤"}}},fp="25,245,23.294.0,17.178.1,38.100.0,30.72.0,38.76.0,31.54.0,30.80.0"}
P.entries["quest:2994"] = {n="拯救沙普比克",s="狮鹫管理员塔隆艾克斯派你去往辛萨罗的顶峰，那座山峰正位于邪枝巨魔领地的中心。邪恶女祭司海克斯拥有开启尖喙牢笼的钥匙，你必须从她手中夺取钥匙并救出那只狮鹫。",h="狮鹫管理员塔隆艾克斯派你去往辛萨罗的顶峰，那座山峰正位于邪枝巨魔领地的中心。邪恶女祭司海克斯拥有开启尖喙牢笼的钥匙，你必须从她手中夺取钥匙并救出那只狮鹫。",kw={"鹰巢山","狮鹫管理员塔隆艾克斯","辛特兰","辛萨罗","拯救尖喙","尖喙","邪恶女祭司海克斯","邪枝巨魔"},sec={{t="前往辛萨罗",b="根据萨迪斯·格希德的预言以及你向塔隆艾克斯的汇报，营救尖喙的方法已经很明确了。辛萨罗位于邪枝巨魔领地的中心，你必须一路杀到它的顶峰。邪恶女祭司海克斯持有尖喙牢笼的钥匙。从她身上把它拿走，然后找到牢笼，救出那只狮鹫。"},{t="塔隆艾克斯的谢意",b="迅风和利爪已经把他们的孩子接回家了，现在还在对他疼爱有加。这一幕让塔隆艾克斯热泪盈眶。塔隆艾克斯说这份恩情无以为报，鹰巢山的狮鹫和骑士们将永远传唱你的名字。"}},faq={{q="是谁派你去营救尖喙的？",a="在预言揭示了狮鹫被关押的位置后，狮鹫管理员塔隆艾克斯请求你去营救尖喙。",al={"谁发布了拯救尖喙的任务","尖喙任务发布者","我在哪里开始拯救尖喙的任务"}},{q="尖喙被关在哪里？",a="尖喙被关在辛萨罗的顶峰，那里位于辛特兰的邪枝巨魔领地内。",al={"尖喙在哪里","尖喙位置","尖喙的牢笼在哪里"}},{q="谁持有尖喙牢笼的钥匙？",a="邪恶女祭司海克斯拥有打开尖喙牢笼所需的钥匙。",al={"谁掉落尖喙的钥匙","海克斯的钥匙在哪里","邪恶女祭司海克斯的钥匙"}}},fp="16,221,14.323.0,17.241.1,34.110.0,30.104.0,38.64.0"}
P.entries["quest:2996"] = {n="寻找斯坦哈德",s="“寻找斯坦哈德”是部落术士在掌握了基础召唤术后必经的仪式。在奥格瑞玛暗影裂口的甘鲁尔·血眼的指引下，修行者必须前往南方的棘齿城，向一位人类叛逃召唤师求学。",h="“寻找斯坦哈德”是部落术士在掌握了基础召唤术后必经的仪式。在奥格瑞玛暗影裂口的甘鲁尔·血眼的指引下，修行者必须前往南方的棘齿城，向一位人类叛逃召唤师求学。",kw={"贫瘠之地","cleft of shadow","地狱猎犬任务","甘鲁尔·血眼","棘齿城","寻找斯坦哈德","斯坦哈德·法尔杉","卡班法典"},ang={["class:Warlock"]="这个任务标志着你开始掌握中阶恶魔实体，测试你是否准备好奴役这种吞噬魔法的地狱猎犬。",["faction:Horde"]="部落大师愿意将学徒送到一个人类隐士那里，这表明了术士结社的运作方式独立于大酋长的正式外交政策之外。"},sec={{t="离开奥格瑞玛的阴影",b="在暗影裂口的黑暗洞穴中，兽人术士训练师甘鲁尔·血眼指导着年轻的修行者掌握操纵虚空的险恶艺术。最终，术士学徒将达到一个瓶颈，仅靠部落内部的教导已不足够。甘鲁尔承认，那些更不稳定的实体需要专业的指导，因此他将学徒们指引到城墙之外，去寻找一位对黑暗奥术有着更深造诣的人物。"},{t="非正统的联盟",b="甘鲁尔选择的导师是斯坦哈德·法尔杉，一位居住在俯瞰棘齿城地精港口的孤立塔楼中的人类法师。尽管部落与人类之间仇恨深重，但术士的存在超越了常规的阵营忠诚。力量、纪律和仪式知识高于血统，比起学徒的肤色，斯坦哈德更关心他们内心的仇恨和奴役潜能。"}},faq={{q="为什么兽人术士要让我去找一个人类？",a="术士们秉持着务实的哲学，认为黑暗知识高于种族忠诚。甘鲁尔·血眼认识到斯坦哈德·法尔杉在进阶恶魔学领域拥有稀有而强大的专长。在追求危险召唤的过程中，导师的技能远比阵营界限更为重要。",al={"为什么要向人类学习","人类术士斯坦哈德","为什么是斯坦哈德"}},{q="我在哪里可以找到斯坦哈德·法尔杉？",a="斯坦哈德·法尔杉居住在贫瘠之地的高地峭壁上，俯瞰着地精港口棘齿城，就站在繁忙码头上方的私人塔楼外。",al={"斯坦哈德位置","斯坦哈德在哪里","棘齿城的斯坦哈德之塔"}},{q="斯坦哈德教导什么力量？",a="斯坦哈德指导术士完成束缚地狱猎犬所需的复杂仪式——这是一种来自扭曲虚空的、贪婪且吞噬魔法的恶魔。他的课程深入研究奥术文献，随后会测试你奴役这种野兽的能力。",al={"斯坦哈德解锁什么","我能从斯坦哈德那里得到什么","寻找斯坦哈德任务奖励"}},{q="甘鲁尔·血眼是谁？",a="甘鲁尔·血眼是位于奥格瑞玛下方暗影裂口的一位著名兽人术士导师。他负责训练部落的初级术士掌握邪能魔法的基础知识以及召唤低级仆从的技巧。",al={"甘鲁尔是谁","甘鲁尔·血眼","奥格瑞玛术士训练师"}},{q="有其他方法开启这个任务吗？",a="有的。被遗忘者术士会从幽暗城的魔法区收到一个平行的召唤任务，该任务同样会指引他们前往棘齿城上方寻找同一位人类导师。",al={"寻找斯坦哈德幽暗城","被遗忘者寻找斯坦哈德","幽暗城版本"}},{q="棘齿城对部落术士有危险吗？",a="棘齿城由热砂港经营，是一个严格中立的港口。只要你保持和平，不在城内攻击其他旅人，地精卫兵就不会找你的麻烦。",al={"棘齿城安全吗","棘齿城卫兵敌对","中立港口"}}},fp="15,157,32.279.0,22.353.0,44.217.0,32.116.0,30.184.1,24.185.0,41.144.0,47.166.0"}
P.entries["quest:2997"] = {n="圣洁之书",s="《神圣之书》是一份入门指引，召唤年轻的矮人圣骑士离开丹莫罗的实地任务，前往铁炉堡这座山中之城。在阿扎尔·战锤的派遣下，新兵需前往Hall of Mysteries的高处寻求蒂萨·热炉的指引。这标志着圣骑士在圣光之道中更深层次试炼的正式开始。",h="《神圣之书》是一份入门指引，召唤年轻的矮人圣骑士离开丹莫罗的实地任务，前往铁炉堡这座山中之城。在阿扎尔·战锤的派遣下，新兵需前往Hall of...",kw={"阿扎尔·战锤","丹莫罗","hall of mysteries","圣光","铁炉堡","mystic ward","圣骑士","救赎","蒂萨·热炉","神圣之书"},ang={["class:Paladin"]="这一成人礼将冰雪中的军事历练与圣职者所应具备的深厚精神修行连接了起来。",["faction:Alliance"]="对圣光的共同崇敬将卡兹莫丹的矮人卫士与洛丹伦和暴风城的人类盟友联合在了一起。",["race:Dwarf"]="矮人圣骑士将族人坚韧的体魄与圣光的教义结合在一起，而这一切都集中在铁炉堡Hall of Mysteries的密室之中。"},sec={{t="High Seat的召唤",b="虽然矮人新兵最初是在保卫丹莫罗冰封的村庄和道路中开始他们的训练，但仅凭武艺并不足以造就一名圣骑士。当阿扎尔·战锤认为一名守卫已准备好接受更深入的精神教导时，他便会察觉到。他不再让受训者继续进行标准的军事演练，而是将有潜力的候选人送入铁炉堡的核心，在城中受人尊崇的圣职长者指导下开始真正的入门训练。"},{t="Hall of Mysteries",b="这份召唤指引新兵前往Mystic Ward，攀登至宁静的Hall of Mysteries内。蒂萨·热炉就站在那里，身处神圣遗物与庄严研究之中。作为受人尊敬的矮人圣光勇士之一，她会测试新晋圣骑士是否做好了准备去领悟自我牺牲、仁慈以及神圣使命背后的沉重道德责任。"}},faq={{q="这个任务的目的是什么？",a="它作为开篇召唤，指引矮人圣骑士离开丹莫罗的偏远训练场，前往铁炉堡寻找蒂萨·热炉，从而启动理解圣光并获得复活之力所需的试炼。",al={"为什么我需要这个任务","神圣之书有什么用","神圣之书的目的"}},{q="蒂萨·热炉是谁？",a="蒂萨·热炉是一位资深的矮人圣骑士，也是一位受人尊敬的导师，驻守在铁炉堡的Hall of Mysteries楼上。她负责年轻圣骑士的精神指导，并指引他们完成《神圣之书》中的神圣试炼。",al={"蒂萨是谁","蒂萨·热炉的背景故事","热炉是谁"}},{q="Hall of Mysteries在哪里？",a="Hall of Mysteries位于铁炉堡西部的Mystic Ward内。它是这座矮人主城的精神与奥术中心，聚集了牧师、圣骑士和法师。",al={"hall of mysteries在哪里","寻找hall of mysteries","铁炉堡的hall of mysteries"}},{q="是谁派遣圣骑士执行此任务？",a="阿扎尔·战锤，一位在丹莫罗工作的圣骑士训练师。一旦新兵表现出在保卫当地矮人定居点方面的军事奉献精神，他就会将这些有潜力的学员送往铁炉堡。",al={"谁开启了神圣之书任务","神圣之书任务发布者","阿扎尔·战锤"}},{q="为什么矮人圣骑士必须在铁炉堡学习？",a="像阿扎尔这样的实地训练师教授的是基础战斗技巧，但圣光的正式教义、神圣典籍和长者都居住在Hall of Mysteries。进阶的仪式和精神教条必须在像蒂萨·热炉这样的资深导师指导下直接学习。",al={"为什么要前往铁炉堡","为什么要在铁炉堡训练"}},{q="与蒂萨·热炉交谈后会发生什么？",a="与蒂萨交谈将开启矮人《神圣之书》的真正试炼，挑战圣骑士在圣光服务中展现出虔诚、同情和牺牲精神。",al={"what comes next","神圣之书之后的下一个任务","蒂萨会给我什么"}}},fp="16,213,23.242.0,21.221.0,34.225.0,24.203.0,39.169.0,37.164.0,45.238.0,50.157.0"}
P.entries["quest:2998"] = {n="圣洁之书",s="“神圣之书”标志着为联盟效力的人类圣骑士新秀们迎来了一次重要的召唤。在闪金镇的威尔海姆修士等当地导师的指派下，新兵们将前往暴风城的Cathedral of Light会见达索瑞恩·拉尔。响应这一召唤，便开启了掌握复活这一神圣天赋所必需的试炼。",h="“神圣之书”标志着为联盟效力的人类圣骑士新秀们迎来了一次重要的召唤。在闪金镇的威尔海姆修士等当地导师的指派下，新兵们将前往暴风城的Cathedral of...",kw={"威尔海姆修士","cathedral of light","达索瑞恩·拉尔","闪金镇","圣骑士","救赎","暴风城","神圣之书"},ang={["class:Paladin"]="这个任务是人类圣骑士的一场成人礼，标志着你的导师正式认可了你的功绩，并指引你来到白银之手的高级指挥官面前。",["faction:Alliance"]="在暴风城招募并测试神圣战士，确保了联盟在动荡时期能够拥有专注的一线治疗者和战斗人员。",["race:Human"]="从乡村风格的艾尔文森林前往宏伟的Cathedral of Light，将人类保卫者与王国最深厚的精神和军事机构紧密地联系在了一起。"},sec={{t="前往首都的召唤",b="在艾尔文森林开始冒险的圣骑士新兵们，起初都在通过帮助当地居民以及与狼群、迪菲亚强盗和狗头人作战来磨练战斗技巧。一旦新兵展现出足够的战斗素养和对圣光的虔诚，威尔海姆修士等导师便会亲自发出召唤。富有影响力的圣骑士领袖会留意到这些有前途的学生，引导他们离开当地的教堂哨所，直接前往王国的精神中心进行报到。"},{t="Cathedral of Light",b="坐落在暴风城Cathedral Square的Cathedral of Light，是王国牧师和白银之手骑士团的最高圣殿。达索瑞恩·拉尔就在这里居住，负责监督这些向圣光誓效忠之人的成长。走在宏伟的拱顶之下，新兵们站在高级圣骑士面前，接受“神圣之书”的正式试炼——这些挑战旨在考验他们坚定的同情心、坚毅和牺牲精神。"}},faq={{q="是谁指派我因这个任务前往暴风城的？",a="威尔海姆修士，这位驻扎在闪金镇Lion's Pride Inn附近的圣骑士训练师，会在你展现出足够的潜力和实力后发出这一召唤。",al={"任务发布者","谁提供任务","威尔海姆修士"}},{q="我在哪里可以找到达索瑞恩·拉尔？",a="达索瑞恩·拉尔居住在位于暴风城西北部Cathedral Square内的Cathedral of Light中。他大部分时间都在大教堂的宏伟厅堂下指导圣骑士。",al={"达索瑞恩·拉尔位置","达索瑞恩·拉尔在哪里","圣骑士导师位置"}},{q="为什么这个召唤对圣骑士如此重要？",a="向达索瑞恩·拉尔报到标志着从基础战斗训练到深入圣光共融的转变。它开启了“神圣之书”的试炼，最终将赋予你通过圣光将阵亡的盟友从死亡中唤回的神圣力量。",al={"为什么要做这个任务","任务重要性","圣骑士试炼"}},{q="非人类圣骑士是否也会接到这个完全相同的任务？",a="这个版本的召唤源自艾尔文森林的威尔海姆修士，是专门针对人类圣骑士的。矮人圣骑士会在丹莫罗接到类似的召唤，前往铁炉堡找他们自己的导师。",al={"矮人圣骑士","矮人可以做这个任务吗","这个任务只有人类能做吗"}},{q="向达索瑞恩·拉尔报到后会发生什么？",a="见到达索瑞恩·拉尔后，他会欢迎你来到暴风城，并立即向你展示“神圣之书”的试炼，考验你的同情心以及保护弱小的决心。",al={"后续任务","接下来发生什么","神圣之书后续步骤"}},{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是暴风王国和白银之手骑士团中最具影响力的圣骑士之一，负责在首都指导新一代的神圣战士。",al={"达索瑞恩是谁","达索瑞恩·拉尔背景故事"}}},fp="16,205,24.425.0,22.397.0,41.155.0,32.168.0,46.251.0,47.171.0,47.177.0,22.164.0"}
P.entries["quest:2999"] = {n="圣洁之书",s="“神圣之书”是为在丹莫罗服役的年轻矮人圣骑士提供的成人礼任务。在铁炉堡神秘大厅的圣骑士训练师布兰度尔·铁锤的指引下，初学者将被派往楼上与受人尊敬的圣骑士训练师蒂萨·热炉交谈。这标志着从基础武力训练向圣光之道更深层的精神职责与神圣誓言的转变。",h="“神圣之书”是为在丹莫罗服役的年轻矮人圣骑士提供的成人礼任务。在铁炉堡神秘大厅的圣骑士训练师布兰度尔·铁锤的指引下，初学者将被派往楼上与受人尊敬的圣骑士训练师蒂萨·热炉交谈。这标志着从基础武力训练向圣光之道更深层的精神职...",kw={"布兰度尔·铁锤","神秘大厅","铁炉堡","圣骑士","救赎","蒂萨·热炉","神圣之书"},ang={["class:Paladin"]="这个任务标志着初学者从粗糙的武力操练转向圣光深层精神重负的时刻，并为获得救赎力量的试炼做好准备。",["race:Dwarf"]="矮人圣骑士将圣光的奉献与卡兹莫丹深厚的职责与兄弟会传统相结合，响应着铁炉堡山脉大厅内的召唤。"},sec={{t="高阶宝座的召唤",b="当新手圣骑士还在安威玛尔和卡拉诺斯抵御穴居人和霜鬃巨魔时，他们的职责终将要求他们有更深层的奉献。布兰度尔·铁锤在认可了一名初学者的武技修养后，会建议他们暂时放下在雪地山口的任务，前往铁炉堡他所在的神秘大厅寻找指导。在那里，资深圣骑士会监督该职业的精神成长。"},{t="蒂萨·热炉的指引",b="蒂萨·热炉是铁炉堡矮人中最受尊敬的圣骑士之一。她的职责是指导初学者理解圣光的真正重负，不仅是简单的剑术与锤击，更要传授同情、正义与自我牺牲。寻找到她便开启了对“神圣之书”的正式研究，这一神圣过程旨在赋予圣骑士复活倒下者的能力。"}},faq={{q="这个任务的目的是什么？",a="这个任务将年轻的矮人圣骑士从他们的训练师布兰度尔·铁锤处引向铁炉堡的资深圣骑士蒂萨·热炉。它是研究“神圣之书”并获得精神复活力量所需试炼的开端。",al={"这个任务有什么用","神圣之书起始","为什么要做这个任务"}},{q="布兰度尔·铁锤是谁？",a="布兰度尔·铁锤是一位驻扎在铁炉堡神秘大厅的矮人圣骑士训练师。他在那里监督年轻的圣骑士，当他们准备好承担更重大的神圣职责时，将有前途的初学者送往楼上寻找蒂萨·热炉。",al={"谁发布这个任务","布兰度尔的作用","布兰度尔·铁锤背景故事"}},{q="蒂萨·热炉是谁？",a="蒂萨·热炉是一位受人尊敬的资深圣骑士，位于铁炉堡神秘大厅的楼上。她指导年轻的圣骑士，教导他们除了武力之外，圣光对他们有着怎样的真正要求。",al={"蒂萨在哪里","蒂萨·热炉的作用","谁是蒂萨"}},{q="这个任务接下来指向哪里？",a="与蒂萨·热炉交谈将启动“神圣之书”的具体试炼。这些任务旨在考验圣骑士的奉献精神、仁慈之心以及为了圣光而保护和恢复生命意志。",al={"后续任务","接下来是什么","神圣之书任务链"}},{q="为什么矮人圣骑士必须寻求“神圣之书”？",a="为了掌握将倒下的盟友起死回生的奇迹，圣骑士必须理解真正的无私与精神职责。“神圣之书”通过正式课程和信仰考验引导初学者，而这些是引导如此强大神圣力量所必需的。",al={"为什么是神圣之书","圣骑士复活任务背景","矮人救赎"}},{q="人类会在铁炉堡接受同样的指导吗？",a="人类圣骑士会通过暴风城的Cathedral of Light进行平行的旅程，而不是在铁炉堡。这个从布兰度尔·铁锤到蒂萨·热炉的具体召唤是专为在铁炉堡训练的矮人量身定做的。",al={"人类能做这个吗","这是矮人专属吗","人类神圣之书"}}},fp="16,184,25.261.0,30.253.0,34.221.0,26.233.0,24.169.0,32.174.0,56.207.0,53.169.0"}
P.entries["quest:3000"] = {n="圣洁之书",s="这个任务指引在远方游历的矮人圣骑士回到家乡铁炉堡，以进一步完成他们的神圣使命。该任务由暴风城的格雷森·沙东布瑞克公爵发布，旨在引导初出茅庐的勇士前往蒂萨·热炉处，她是神秘大厅最受尊敬的导师之一。回到家乡标志着他们正式开始接受《神圣法典》的试炼。",h="这个任务指引在远方游历的矮人圣骑士回到家乡铁炉堡，以进一步完成他们的神圣使命。该任务由暴风城的格雷森·沙东布瑞克公爵发布，旨在引导初出茅庐的勇士前往蒂萨·热炉处，她是神秘大厅最受尊敬的导师之一。回到家乡标志着他们正式开始...",kw={"矮人圣骑士","hall of mysteries","铁炉堡","格雷森·沙东布瑞克公爵","mystic ward","救赎","蒂萨·热炉","神圣法典"},ang={["class:Paladin"]="这标志着矮人圣骑士的一个重要成年仪式，让他们走上研读《神圣法典》并掌握复活之赐的道路。",["faction:Alliance"]="暴风城的圣骑士与铁炉堡的导师之间共同的训练和相互尊重，彰显了矮人与人类之间紧密的精神联盟。",["race:Dwarf"]="这个任务架起了你在人类领地的冒险与你对卡兹莫丹职责之间的桥梁，召唤你回到铁炉堡的祖居地，在你的族中长者指导下接受训练。"},sec={{t="召唤回家",b="虽然矮人圣骑士经常援助暴风城王国并在人类领地内四处冒险，但他们的精神和武力根基仍扎根于卡兹莫丹。格雷森·沙东布瑞克公爵在认定一名矮人的实战训练已足够成熟时，会建议他们回到铁炉堡的核心。在那里，他们的族人会监督他们履行作为一名白银之手骑士所应尽的深刻精神义务。"},{t="神秘大厅",b="在回到这座山中之城后，圣骑士将被指引前往神秘区。蒂萨·热炉就居住在神秘大厅深处的上层。作为矮人圣骑士新生代的受人尊敬的导师，她负责帮助他们做好准备，通过《神圣法典》中记载的神圣试炼来肩负起圣光的重担。"}},faq={{q="为什么格雷森·沙东布瑞克公爵要让我回铁炉堡？",a="格雷森公爵认为，虽然你已经在战场上证明了自己的实力，但年轻的矮人圣骑士理应在蒂萨·热炉的指导下，直接向自己的族人学习圣光更深奥的教义和试炼。",al={"为什么要回铁炉堡","为什么格雷森让我离开","为什么要拜访蒂萨"}},{q="蒂萨·热炉是谁？",a="蒂萨·热炉是铁炉堡最受尊敬的矮人圣骑士之一。她驻守在神秘大厅的楼上，负责指导成长中的圣骑士，并监督那些考验他们对圣光奉献精神的试炼。",al={"蒂萨·热炉","蒂萨是谁","圣骑士训练师蒂萨"}},{q="我在哪里可以找到蒂萨·热炉？",a="她位于铁炉堡神秘区的神秘大厅内。前往圣所的楼上就能找到她。",al={"蒂萨在哪里","蒂萨·热炉位置","如何找到蒂萨"}},{q="什么是《神圣法典》？",a="《神圣法典》包含了圣骑士为了掌握圣光力量——特别是复活的力量和对阵亡盟友的无私奉献——所必须经历的神圣教义和严苛试炼。",al={"神圣法典的含义","什么是神圣法典","圣骑士之书"}},{q="人类圣骑士能做这个版本的任务吗？",a="不能。这个特定的召唤任务专门指引矮人圣骑士回到他们家乡的导师处，而人类圣骑士则直接在暴风城的格雷森·沙东布瑞克公爵和达索瑞恩·拉尔的指导下进行试炼。",al={"人类能做这个吗","这是矮人专属任务吗"}},{q="向蒂萨·热炉报到后会发生什么？",a="一旦你向蒂萨做了自我介绍，她就会通过《神圣法典》为你布置正式的矮人试炼，考验你是否准备好掌握圣光的救赎力量。",al={"what comes next","神圣法典之后的下一个任务","与蒂萨交谈后"}}},fp="16,201,14.310.0,21.262.0,62.178.0,24.159.0,34.92.0,29.156.0,48.174.0,49.176.0"}
P.entries["quest:3001"] = {n="寻找斯坦哈德",s="“寻找斯坦哈德”是幽暗城的凯伦丁·哈加尔交给部落术士的一项任务。哈加尔指引他的学生跨越无尽之海，前往棘齿城上方尘土飞扬的山丘。那里的一位人类术士掌握着通往更深奥、更危险的召唤仪式的钥匙。这标志着术士从基础暗影法术向召唤地狱猎犬这一高难度技艺的转变。",h="“寻找斯坦哈德”是幽暗城的凯伦丁·哈加尔交给部落术士的一项任务。哈加尔指引他的学生跨越无尽之海，前往棘齿城上方尘土飞扬的山丘。那里的一位人类术士掌握着通往更深奥、更危险的召唤仪式的钥匙。这标志着术士从基础暗影法术向召唤地...",kw={"贫瘠之地","凯伦丁·哈加尔","地狱猎犬","棘齿城","寻找斯坦哈德","斯坦哈德·法尔杉","法术典籍","幽暗城","术士"},ang={["class:Warlock"]="这项任务是你大约三十级左右的一个关键通过仪式，标志着你将从束缚小鬼和虚空行者转向驾驭捕食性的地狱猎犬。",["faction:Horde"]="被遗忘者和兽人术士必须放下他们对人类惯常的敌意，长途跋涉前往中立的棘齿城，向一位活着的人类术士学习。",["race:Undead"]="凯伦丁·哈加尔亲自派遣被遗忘者门徒离开幽暗城，证明了即使是希尔瓦娜斯的忠实拥护者也会利用活着的大师来扩展他们的军火库。"},sec={{t="跨海大师",b="凯伦丁·哈加尔是幽暗城Magic Quarter的被遗忘者术士训练师，负责监督那里的暗影魔法，他很清楚何时一名学徒已经超越了基础教学的范畴。他没有将学生局限在洛丹伦的废墟之中，而是命令他们去寻找斯坦哈德·法尔杉。哈加尔警告说，虽然斯坦哈德是一位活着的人类，但他绝非弱者，且绝不能将其视为敌人。对于术士来说，对恶魔掌握力的追求通常会超越种族和阵营的界限。"},{t="棘齿城的眺望台",b="斯坦哈德在贫瘠之地棘齿城地精港口上方高耸的悬崖上，保持着相对中立的地位。在他那靠近石制瞭望塔的栖身之处，他轻蔑地俯视着下方忙碌的水手、雇佣兵和商人，嘲笑着他们对扭曲虚空的全然无知。斯坦哈德并不介意来到他面前的部落术士眼中的不信任或隐隐的仇恨；相反，他将这种原始的恶意视为一种可以塑造为黑暗权威的强大燃料。"}},faq={{q="为什么幽暗城的术士会把我送到一个人类那里去？",a="术士在追求稀有且强大的黑暗知识时，经常会抛开阵营隔阂。凯伦丁·哈加尔承认，斯坦哈德·法尔杉在更高等的恶魔召唤术上拥有哈加尔无法提供的专业造诣。在追求恶魔之力的道路上，知识远比导师的血统重要。",al={"为什么是人类训练师","为什么要送到人类那里","凯伦丁派遣至斯坦哈德"}},{q="斯坦哈德·法尔杉具体在哪里？",a="斯坦哈德·法尔杉居住在贫瘠之地，位于棘齿城地精港口上方的高耸悬崖上。他就站在俯瞰海湾和下方繁忙港口码头的石塔旁边。",al={"斯坦哈德位置","斯坦哈德在哪里","如何找到斯坦哈德"}},{q="斯坦哈德教授什么样的力量？",a="斯坦哈德引导经验丰富的术士完成从扭曲虚空束缚高等恶魔所需的复杂仪式，这直接通向召唤并驾驭地狱猎犬所必需的危险考验。",al={"斯坦哈德教授什么","这个任务是为了什么","地狱猎犬任务"}},{q="斯坦哈德是联盟的吗？",a="尽管是人类，但斯坦哈德在中立的地精领地棘齿城开展活动，并且与大联盟没有任何关联。他是一位独立的修行者，可以与任何有能力在通过他训练后存活下来的部落和联盟术士自由往来。",al={"斯坦哈德是联盟吗","斯坦哈德阵营","斯坦哈德友好吗"}},{q="到达斯坦哈德那里之后会发生什么？",a="抵达后，斯坦哈德会考验你的决心，并让你去取回散落的“法术典籍”的残页和组件，开启一场范围广泛的任务，以解锁召唤地狱猎犬的仪式。",al={"在斯坦哈德之后做什么","法术典籍","后续任务"}},{q="为什么斯坦哈德欢迎学生心中的仇恨？",a="恶魔魔法以强烈的情感、支配欲和意志力为食。斯坦哈德认为仇恨是一种专注而强大的纪律，可以被引导来压制那些混乱的虚空实体，否则这些实体会反噬未受过训练的召唤师。",al={"为什么斯坦哈德喜欢仇恨","眼中的仇恨"}}},fp="15,203,23.389.0,23.379.0,50.293.0,40.162.0,38.207.0,36.229.0,36.207.0,48.209.0"}
P.entries["quest:3002"] = {n="戈杜尼宝珠",s="洛卡·奥赫很了解敌人，但他是个战士，无法说出戈杜尼宝珠到底有什么能力。洛卡知道奥格瑞玛有一位法师能说出更多信息。这枚宝珠需要你带给奥格瑞玛暗棘小屋的尤塞尔奈。这是在“黑暗仪式”之后的任务。",h="洛卡·奥赫很了解敌人，但他是个战士，无法说出戈杜尼宝珠到底有什么能力。洛卡知道奥格瑞玛有一位法师能说出更多信息。这枚宝珠需要你带给奥格瑞玛暗棘小屋的尤塞尔奈。这是在“黑暗仪式”之后的任务。",kw={"暗棘小屋","菲拉斯","戈杜尼","戈杜尼宝珠","奥格瑞玛","洛卡·奥赫","尤塞尔奈"},sec={{t="战士的知识之外",b="在“黑暗仪式”之后，洛卡·奥赫拿着宝珠，但他承认自己只是个战士，根本不知道这东西有什么用。洛卡知道奥格瑞玛有一位法师能说出更多情况，于是让你带着宝珠去寻找在暗棘小屋的尤塞尔奈。"},{t="尤塞尔奈的结论",b="尤塞尔奈觉得这枚宝珠很迷人。尤塞尔奈说，它非常强大，但也非常危险。"}},faq={{q="是谁让你去找尤塞尔奈的？",a="洛卡·奥赫，在你拿到了“黑暗仪式”中要求你夺取的宝珠之后。",al={"戈杜尼宝珠系列任务","黑暗仪式后续","戈杜尼宝珠的前置任务"}},{q="为什么洛卡·奥赫不检查一下这枚宝珠？",a="洛卡·奥赫是个战士，根本说不出这枚宝珠有什么用，但他知道奥格瑞玛有一位法师能给出更多信息。",al={"为什么要将宝珠送到奥格瑞玛","为什么洛卡·奥赫要把宝珠送走","为什么是尤塞尔奈"}},{q="尤塞尔奈在哪里？",a="在奥格瑞玛的暗棘小屋里。",al={"尤塞尔奈位置","尤塞尔奈在哪里","暗棘小屋位置"}},{q="在“戈杜尼宝珠”之前的任务是什么？",a="“黑暗仪式”，在那项任务中洛卡·奥赫派你去从一名戈杜尼法师领主手中夺取宝珠。",al={"戈杜尼宝珠前置条件","戈杜尼宝珠前序任务"}}},fp="16,252,28.248.0,19.98.1,27.65.0,39.116.0,19.36.0,35.84.0"}
P.entries["quest:301"] = {n="向铁炉堡报告",s="这项任务将一位冒险者从洛克莫丹的塞尔萨玛送往铁炉堡的中心地带，带去来自铁环挖掘场的重要更新。将挖掘进度报告送交至Hall of Explorers的勘察员塔伯斯·雷矛，将引发对缺失的爆破火药和山脚下停滞的考古工作的调查。",h="这项任务将一位冒险者从洛克莫丹的塞尔萨玛送往铁炉堡的中心地带，带去来自铁环挖掘场的重要更新。将挖掘进度报告送交至Hall of Explorers的勘察员塔伯斯·雷矛，将引发对缺失的爆破火药和山脚下停滞的考古工作的调查。",kw={"爆破火药","探险者协会","铁环营地","吉恩·角盔","洛克莫丹","勘察员塔伯斯·雷矛","报告铁炉堡","塞尔萨玛"},ang={["faction:Alliance"]="这项任务展示了联盟的后勤能力，将山谷中遥远的研究营地与铁炉堡的军事和学术领导层连接起来。",["race:Dwarf"]="对矮人来说，应对探险者协会的官僚作风以及处理雷矛氏族传说中的脾气，是他们在首都大厅中熟悉的一种通过仪式。"},sec={{t="探险者协会的信使",b="卡兹莫丹各地的考古探险队在很大程度上依赖于探险者协会的资金、补给和监督。当洛克莫丹南部的勘察员基恩萨·铁环的挖掘场缺乏爆破补给时，他的监管人无法简单地在当地征用更多物资。塞尔萨玛旅店的吉恩·角盔委托一位冒险者将勘察员基恩萨·铁环的书面报告翻越山口直接送交至协会总部的勘察员塔伯斯·雷矛手中。"},{t="雷矛的脾气",b="勘察员塔伯斯·雷矛代表了他所在氏族那种雷厉风行、火爆坚决的性格特征。他驻扎在铁炉堡宏伟的图书馆和Hall of Explorers中，期待着协会挖掘工作能迅速取得切实成果。在收到这封信后，雷矛愤怒地发现勘察员基恩萨·铁环未能说明数周前寄出的一大批爆破火药的去向，这表明洛克莫丹的补给线已经出现了危险的中断。"}},faq={{q="为什么这份报告需要被送到铁炉堡？",a="探险者协会严格管理着像爆破火药这类宝贵资源的分配。野外挖掘点如果没有驻扎在Hall of Explorers总部的资深勘察员的正式授权，就无法订购危险的爆炸物。",al={"为什么要去铁炉堡","为什么要将报告交给雷矛","铁炉堡报告原因"}},{q="谁是勘察员塔伯斯·雷矛？",a="他是驻扎在铁炉堡的探险者协会的一位高级官员。作为引以为傲的雷矛氏族的一员，他因脾气暴躁以及对停滞的挖掘点和丢失的库存缺乏耐心而臭名昭著。",al={"谁是雷矛","勘察员雷矛背景故事"}},{q="勘察员基恩萨·铁环最初的爆破火药去哪了？",a="一批爆破火药在数周前就已发出，但勘察员基恩萨·铁环只字未提是否收到。这引发了人们的担忧，担心石腭怪或强盗在洛克莫丹的道路上伏击了运输车。",al={"爆破火药发生了什么","丢失的爆破火药","火药在哪里"}},{q="在铁炉堡哪里可以找到勘察员塔伯斯·雷矛？",a="勘察员塔伯斯·雷矛位于探险者大厅（也被称为图书馆或Hall of Explorers），坐落在铁炉堡的东北翼。",al={"雷矛的位置","雷矛在哪里","探险者大厅位置"}},{q="是谁在塞尔萨玛交给你报告的？",a="吉恩·角盔居住在塞尔萨玛的烈酒旅店，担任联络人，负责协调勘察员基恩萨·铁环的偏远营地与城市领导层之间的报告和通讯。",al={"谁发布了报告铁炉堡任务","吉恩·角盔的角色"}},{q="雷矛读完报告后会发生什么？",a="对不知去向的弹药和停滞的进度感到愤怒，雷矛命令玩家组织一批新的爆破火药，并直接送回给勘察员基恩萨·铁环。",al={"what comes next","报告铁炉堡之后的后续任务"}}},fp="19,191,24.427.0,20.376.1,57.193.0,28.209.0,45.173.0,52.154.0,38.164.0,46.201.1"}
P.entries["quest:302"] = {n="铁环的火药",s="“给铁环的火药”是一项联盟递送任务，它连接了位于铁炉堡的探险者协会总部与洛克莫丹。在获得勘察员塔伯斯·雷矛的正式批准后，冒险者被派往塞尔萨玛，负责监管一批运往铁环挖掘场的关键炸药。",h="“给铁环的火药”是一项联盟递送任务，它连接了位于铁炉堡的探险者协会总部与洛克莫丹。在获得勘察员塔伯斯·雷矛的正式批准后，冒险者被派往塞尔萨玛，负责监管一批运往铁环挖掘场的关键炸药。",kw={"探险者协会","胡达尔","铁炉堡","吉恩·角盔","洛克莫丹","给铁环的火药","勘察员塔伯斯·雷矛","塞尔萨玛"},ang={["faction:Alliance"]="维护洛克莫丹交通道路的安全对于巩固铁炉堡与东部边境之间的联盟关系至关重要。",["profession:Mining"]="炸药是矮人行业不可或缺的工具，无论是矿工还是挖掘者，都需要利用它来凿开深层的基岩。",["race:Dwarf"]="对于矮人来说，确保挖掘火药不仅仅是后勤支援，它还有助于揭开其种族神秘起源的神圣事业。"},sec={{t="官僚作风与炸药",b="卡兹莫丹山脉的考古发掘工作需要重型装备。当勘察员基恩萨·铁环在洛克莫丹南部的探险队耗尽了炸药储备时，消息被传回了位于铁炉堡的协会领导层。勘察员塔伯斯·雷矛迅速批准了征用申请，并指引信使前往塞尔萨玛——该山谷的主要后勤枢纽——与吉恩·角盔进行对接。"},{t="错过的出发时间",b="由于此前经过洛克湖的补给车队要么离奇失踪，要么遭到了当地穴居人的骚扰，塔伯斯·雷矛明确要求信使亲自护送这辆火药马车。然而，繁文缛节和漫长的路途拖慢了协会的效率。当信使抵达塞尔萨玛的烈酒旅店时，吉恩·角盔已经在胡达尔和两名矮人搬运工的护送下派出了马车，信使不得不沿着大路匆忙追赶。"}},faq={{q="为什么要把炸药送给铁环？",a="勘察员基恩萨·铁环在洛克莫丹南部领导着一项至关重要的矮人考古挖掘工作。挖掘深埋的文物需要炸开坚硬的岩层，而在面对日益严重的穴居人侵扰时，他的团队耗尽了补给。",al={"为什么需要火药","铁环的炸药","火药的用途"}},{q="勘察员塔伯斯·雷矛是谁？",a="勘察员塔伯斯·雷矛是驻扎在铁炉堡探险者大厅的一位矮人探险者协会高级官员。他负责审查现场请求、批准关键设备，并管理整个卡兹莫丹各大主要挖掘点的后勤工作。",al={"塔伯斯·雷矛的角色","任务发布者"}},{q="吉恩·角盔是谁？",a="吉恩·角盔是驻扎在洛克莫丹塞尔萨玛的一位探险者协会联络人。他负责准备补给物资，并组织前往该山谷更危险地带的运输队。",al={"吉恩·角盔的位置","吉恩·角盔在哪里"}},{q="为什么这批货物需要护送？",a="此前运往挖掘场的补给品未能抵达目的地。随着从山丘和挖掘点涌出的穴居人占领了洛克莫丹，主干道上的补给线变得越来越危险。",al={"为什么护送火药","穴居人袭击马车"}},{q="抵达塞尔萨玛后会发生什么？",a="吉恩·角盔已经让马车在胡达尔以及搬运工米兰和Saean的护送下出发了。你必须沿着南部的道路追赶他们，以免发生意外。",al={"我错过了马车吗","货物在哪里"}},{q="这项任务在探险者协会的故事线中处于什么位置？",a="它起到了信使纽带的作用，连接了来自挖掘点的最初请求、铁炉堡的中心权力机构，以及通过塞尔萨玛派往现场的补给，从而保障了探险队持续的挖掘工作。",al={"铁环任务链","挖掘任务线"}}},fp="18,229,31.302.0,18.311.1,46.177.0,28.223.0,21.171.0,52.164.0,42.152.1,61.174.0"}
P.entries["quest:3022"] = {n="小心运送",s="克格尔·曲藤交给你一箱蛋，并请你把它带给德鲁伊艾瑞拉斯·琥珀，他就在泰达希尔的一个小村庄，鲁瑟兰村里。",h="克格尔·曲藤交给你一箱蛋，并请你把它带给德鲁伊艾瑞拉斯·琥珀，他就在泰达希尔的一个小村庄，鲁瑟兰村里。",kw={"克格尔·曲藤","艾瑞拉斯·琥珀","角鹰兽蛋","鲁瑟兰村","塔纳利斯","泰达希尔"},sec={{t="一箱蛋",b="克格尔·曲藤交给你一箱精心包装的蛋。那是角鹰兽蛋，它们是要送给一位名叫艾瑞拉斯·琥珀的德鲁伊的。"},{t="鲁瑟兰的德鲁伊",b="艾瑞拉斯·琥珀是一位照料这些蛋的德鲁伊。他帮助它们孵化，然后训练幼年的角鹰兽。鲁瑟兰村是位于泰达希尔南部的一个小村庄。"}},faq={{q="克格尔·曲藤给的箱子里装的是什么？",a="这箱精心包装的箱子里装的是角鹰兽蛋。",al={"箱子里是什么","精心包装的箱子内容物","我携带的是什么"}},{q="这箱蛋要送到哪里去？",a="这箱蛋要送到泰达希尔的鲁瑟兰村，交给德鲁伊艾瑞拉斯·琥珀。",al={"我该把箱子带到哪里","艾瑞拉斯·琥珀的位置","鲁瑟兰村在哪里"}},{q="艾瑞拉斯·琥珀是谁？",a="艾瑞拉斯·琥珀是鲁瑟兰村的一位德鲁伊。他负责照看角鹰兽蛋，并在它们孵化后训练幼年的角鹰兽。",al={"艾瑞拉斯是谁","琥珀的背景故事","谁负责接收这些蛋"}}},fp="16,161,15.141.0,23.178.0,48.49.0,32.94.0,23.130.0"}
P.entries["quest:303"] = {n="黑铁战争",s="在湿地的北缘，莫特雷·加玛森正进行着一场绝望的防御战，试图从黑铁部族手中夺回丹莫德。在敌方破坏者炸毁了萨多尔大桥并占领该镇后，铁炉堡山地巡逻队只能苦苦支撑，等待着可能永远不会到来的增援。",h="在湿地的北缘，莫特雷·加玛森正进行着一场绝望的防御战，试图从黑铁部族手中夺回丹莫德。在敌方破坏者炸毁了萨多尔大桥并占领该镇后，铁炉堡山地巡逻队只能苦苦支撑，等待着可能永远不会到来的增援。",kw={"铜须","黑铁","爆破手","丹莫德","铁炉堡","莫特雷·加玛森","破坏者","萨多尔大桥","湿地"},ang={["faction:Alliance"]="萨多尔大桥的毁灭和丹莫德的陷落切断了暴风城的北方盟友与南方王国之间的陆路交通。",["profession:Engineering"]="黑铁破坏者部署特种炸药来粉碎古老矮人石结构的精准度，揭示了他们对结构爆破令人胆寒的掌握程度。",["race:Dwarf"]="对于铜须矮人来说，失去丹莫德是一种苦涩的羞辱，也是对卡兹莫丹主权的直接威胁，这需要向他们世仇的敌人复仇。"},sec={{t="北门的战线",b="丹莫德曾是铁炉堡引以为傲的堡垒，守护着萨多尔大桥的南端，那座连接卡兹莫丹与洛丹伦的宏伟桥梁。当黑铁破坏者和爆破手炸毁了桥拱后，他们切断了联盟的交通线并迅速压制了这座据点。莫特雷·加玛森和少数幸存的守卫者勉强撤退到足够远的地方建立了一个侦察营地，但如果缺乏及时的反击，整个北门都有可能永久沦为黑铁部族的领地。"},{t="为预备役争取时间",b="由于矮人部队被部署到了遥远的联盟战场上，莫特雷的小分队大多只能靠自己来孤军奋战。他的斥候试图向铁炉堡发送求援信号，但通讯受阻，承诺的预备役部队也迟迟不见踪影。为了争取时间并瓦解敌人的防线，莫特雷下令直接对丹莫德的废墟进行外科手术式的打击，以此削减黑铁工程师、挖掘者和前线士兵的数量，防止他们进一步向南进军湿地。"}},faq={{q="莫特雷·加玛森是谁？",a="莫特雷·加玛森是一位铁炉堡山地巡逻队军官，指挥着丹莫德守军的残部。他驻扎在被占领的城镇外，协调着针对黑铁占领军的侦察和游击打击。",al={"莫特雷·加玛森","莫特雷是谁","丹莫德指挥官"}},{q="为什么丹莫德对铁炉堡如此重要？",a="丹莫德守卫着萨多尔大桥的南麓。作为连接卡兹莫丹与阿拉希高地及北洛丹伦的唯一陆路通道，控制了丹莫德就等同于控制了这些地区之间所有的地面交通和补给。",al={"为什么丹莫德很重要","丹莫德的重要性","丹莫德背景故事"}},{q="为什么黑铁矮人在湿地作战？",a="黑铁部族长期以来一直试图削弱他们的铜须表亲以及联盟。通过入侵湿地并摧毁萨多尔大桥，他们切断了铁炉堡通往北方的补给线，并在联盟边境后方开辟了敌对的第二战线。",al={"为什么黑铁矮人在这里","黑铁湿地","黑铁战争原因"}},{q="萨多尔大桥发生了什么？",a="黑铁挖掘者和爆破手在萨多尔大桥的基石拱门内埋设了集束炸药，严重损坏了桥梁，从而在攻陷丹莫德之前切断了铁炉堡来自洛丹伦的增援。",al={"萨多尔大桥被毁","谁炸了桥","萨多尔大桥爆炸"}},{q="铁炉堡的预备役部队在哪里？",a="铁炉堡的军事力量在海外的多次战役和本土防御中被严重拉紧。加玛森的斥候罗戈一直难以与最高指挥部建立可靠的联系，导致丹莫德哨所只能依靠他们能找到的任何当地盟友来坚守阵线。",al={"铁炉堡预备役","增援部队在哪","罗戈预备役"}},{q="在丹莫德击退黑铁矮人后会发生什么？",a="清理掉步兵和工兵能争取到宝贵的时间，但罗戈的情报显示，被关押在暴风城监狱的卡姆·深怒参与策划了针对萨多尔大桥的袭击，莫特雷请求你带回深怒的人头。",al={"黑铁战争后的下一个任务","深怒之源任务","黑铁战争之后"}}},fp="17,273,28.416.0,28.485.0,23.213.0,42.249.0,51.260.0,34.234.0,39.232.0,59.231.1"}
P.entries["quest:304"] = {n="艰巨的任务",s="在黑铁矮人对丹莫德和萨多尔大桥发动毁灭性突袭之后，布莱德·长须誓要为阵亡的亲族和失去的士兵复仇。他委托勇敢的旅者去追踪并杀掉神出鬼没的黑铁术士巴尔加拉斯，并割下他的耳朵作为完成任务的证明。",h="在黑铁矮人对丹莫德和萨多尔大桥发动毁灭性突袭之后，布莱德·长须誓要为阵亡的亲族和失去的士兵复仇。他委托勇敢的旅者去追踪并杀掉神出鬼没的黑铁术士巴尔加拉斯，并割下他的耳朵作为完成任务的证明。",kw={"严酷的任务","“脏鬼”巴尔加拉斯","黑铁矮人","丹莫德","布莱德·长须","罗戈","萨多尔大桥","湿地"},ang={["class:Warlock"]="“脏鬼”巴尔加拉斯利用邪恶的魔能来策划对丹莫德守军的大屠杀，这展示了黑铁矮人利用其技艺所达到的危险目的。",["faction:Alliance"]="萨多尔大桥是连接卡兹莫丹和洛丹伦的主要陆路通道，这使得清除黑铁矮人破坏者成为整个联盟的战略重中之重。",["race:Dwarf"]="对于铁炉堡的矮人来说，黑铁矮人在丹莫德的背叛和暴力行为是一种人身侮辱，也是氏族间长期内战中一道新伤口。"},sec={{t="丹莫德废墟",b="湿地的北部地区目睹了铁炉堡登山者与黑铁矮人潜入者之间激烈的战斗。在围攻期间，丹莫德镇被占领，萨多尔大桥的西侧桥梁被摧毁。布莱德·长须不仅在袭击中失去了许多忠诚的士兵，还失去了自己的兄弟，这让他决心要让敌人血债血偿。"},{t="懦弱的指挥官",b="诸如罗戈之类的斥候侦察表明，占领丹莫德的黑铁矮人部队是由一名被称为“脏鬼”巴尔加拉斯的术士指挥的。巴尔加拉斯并不与敌人正面交锋，而是躲藏起来，指使他的士兵执行他那邪恶的计划。布莱德希望干掉巴尔加拉斯能打垮黑铁矮人部队的脊梁，让铁炉堡的幸存者能够收复这条通往北方的关键通道。"}},faq={{q="“脏鬼”巴尔加拉斯是谁？",a="“脏鬼”巴尔加拉斯是一名黑铁术士，指挥着占领湿地北部丹莫德的部队。布莱德·长须形容他是个胆小鬼，他回避直接战斗，转而派遣成群的黑铁矮人军队来守住该地区。",al={"巴尔加拉斯","巴尔加拉斯是谁","丹莫德的黑铁领袖"}},{q="布莱德·长须是谁？",a="布莱德·长须是一位驻扎在丹莫德废墟外的矮人指挥官。当黑铁矮人部队夺取该定居点并摧毁萨多尔大桥的西侧通道时，他失去了他的兄弟和许多士兵。",al={"布莱德","布莱德·长须","丹莫德任务发布者"}},{q="为什么布莱德想要巴尔加拉斯的耳朵？",a="因为巴尔加拉斯是一个难以捉摸的目标，经常躲避公开战斗，布莱德需要这位术士死亡的实物证明，以确保这种威胁确实已被消除。",al={"为什么需要耳朵","巴尔加拉斯的耳朵"}},{q="萨多尔大桥发生了什么事？",a="萨多尔大桥的西侧桥梁在黑铁矮人对丹莫德的突袭中被摧毁，切断了连接湿地和阿拉希高地之间的一条重要道路。",al={"萨多尔大桥被毁","为什么萨多尔大桥断了"}},{q="巴尔加拉斯躲在哪里？",a="巴尔加拉斯潜伏在丹莫德周围被占领的防御工事和废墟中，他躲在士兵身后，而不是冒险进入开阔的沼泽地。",al={"巴尔加拉斯在哪里","寻找巴尔加拉斯"}},{q="巴尔加拉斯被杀后会发生什么？",a="随着巴尔加拉斯的死亡，布莱德相信，在另一位指挥官赶来增援之前，剩下的那些群龙无首的黑铁矮人部队将更容易被清除。",al={"严酷的任务之后","丹莫德下一步"}}},fp="11,245,21.323.0,20.300.0,25.220.0,26.210.0,39.117.0,34.179.0,25.130.0,37.145.0"}
P.entries["quest:305"] = {n="寻找挖掘队",s="“搜寻挖掘队”任务开始于在湿地的塔雷尔·石纹，他因妻子麦琳突然音讯全无而忧心忡忡。麦琳被指派前往东部著名的维尔加挖掘场，但她已经两周没有寄来例行的信件，这让塔雷尔担心探险队遭遇了不幸。旅者们需要冒险进入沼泽，找到挖掘现场并确认她的安全。",h="“搜寻挖掘队”任务开始于在湿地的塔雷尔·石纹，他因妻子麦琳突然音讯全无而忧心忡忡。麦琳被指派前往东部著名的维尔加挖掘场，但她已经两周没有寄来例行的信件，这让塔雷尔担心探险队遭遇了不幸。旅者们需要冒险进入沼泽，找到挖掘现场...",kw={"探险者协会","搜寻挖掘队","朗布雷德","麦琳·石纹","塔雷尔·石纹","湿地","维尔加挖掘场"},ang={["faction:Alliance"]="在沼泽地维持矮人的据点和研究考察对于保障湿地免受不断侵蚀的荒野威胁至关重要。",["race:Dwarf"]="探险者协会以发掘古代历史为荣，这使得维尔加挖掘场亲属的苦难对任何路过的矮人来说都是一件紧急事项。"},sec={{t="丈夫的恐惧",b="驻扎在潮湿泥泞的湿地时，塔雷尔·石纹一直期待着妻子麦琳的定期来信。麦琳在被称为维尔加挖掘场的矮人挖掘点工作，此前她每周都会发来描述他们工作的信件。当整整两周过去却杳无音讯时，塔雷尔确信营地遭遇了灾难。由于矮人官方力量不足，他只能寄望于路过的斥候勇敢地深入沼泽，看看挖掘队员是否还活着。"},{t="维尔加挖掘场",b="维尔加挖掘场是矮人发掘埋藏在湿地泥泞中的泰坦遗迹和泰坦铸造历史的典型努力。然而，在荒野地区挖掘史前地层经常会使队伍暴露在野兽和地下的敌对威胁之下。抵达该地点需要向东进入远离主路相对安全地带的区域，而导致挖掘队员信件中断的原因很可能依然滞留在那里。"}},faq={{q="塔雷尔·石纹是谁？",a="塔雷尔·石纹是一位驻扎在湿地的忧心忡忡的矮人。由于妻子麦琳在东部的挖掘场工作，而在收到她的来信突然中断后深感恐惧，他将路过的冒险者误认为是派来调查营地失联情况的官方斥候。",al={"塔雷尔·石纹","任务发布者","谁发布了搜寻挖掘队任务"}},{q="麦琳·石纹是谁？",a="麦琳·石纹是一位矮人考古学家，在湿地米奈希尔港东部的维尔加挖掘队工作。她经常给丈夫写信，直到一次意想不到的事件突然切断了她的通讯。",al={"麦琳·石纹","塔雷尔的妻子","麦琳是谁"}},{q="维尔加挖掘场在哪里？",a="维尔加挖掘场位于湿地，米奈希尔港以东、丹莫德以南，坐落在远离主路的岩石山脊中。",al={"挖掘场位置","在哪里找到麦琳","维尔加挖掘场在哪里"}},{q="为什么麦琳停止寄信了？",a="挖掘现场突然陷入沉寂是因为挖掘点出现了一种威胁，切断了矮人研究员与正常信使路线及常规营地生活的联系。",al={"为什么信件停止了","挖掘队发生了什么","为什么没有信件"}},{q="塔雷尔提到的“朗布雷德”是谁？",a="朗布雷德是一位矮人权威人士，他曾承诺如果通讯中断，会部署斥候去查看维尔加挖掘队的情况，这导致塔雷尔认为任何前来帮忙的能干冒险者都是奉朗布雷德之命而来。",al={"朗布雷德是谁","朗布雷德的斥候"}},{q="挖掘场可以安全进入吗？",a="不可以。该地点位于湿地危险的荒野之中，无论是什么导致了团队每周的信件中断，对任何抵达挖掘场的人来说都是一种活跃的危险。",al={"挖掘场安全吗","维尔加的危险"}}},fp="32,176,17.330.0,15.286.0,25.204.0,25.196.0,37.142.0,36.124.0,43.200.0,40.155.0"}
P.entries["quest:306"] = {n="寻找挖掘队",s="这项差事将维尔加挖掘场遭受灾难性恐龙袭击的消息传回了米奈希尔港。麦琳·石纹写了一封匆忙的信来安抚她焦虑的丈夫塔雷尔，并讲述了探险队是如何被淹没的。",h="这项差事将维尔加挖掘场遭受灾难性恐龙袭击的消息传回了米奈希尔港。麦琳·石纹写了一封匆忙的信来安抚她焦虑的丈夫塔雷尔，并讲述了探险队是如何被淹没的。",kw={"挖掘","米奈希尔港","麦琳·石纹","斑点迅猛龙","奥尔默","塔雷尔·石纹","湿地","维尔加"},ang={["faction:Alliance"]="湿地各处的补给道路和边境项目依然极其容易受到野兽的威胁，需要联盟旅行者保持时刻警惕。",["race:Dwarf"]="挖掘场的灾难沉重地打击了矮人的考古雄心，凸显了麦格尼国王的探险者们在远离铁炉堡安全地带时所面临的危险。"},sec={{t="来自废墟的信",b="在定位到挖掘场上方山脊处蜷缩着的挖掘队残部后，麦琳·石纹提供了一份匆忙的报告。在挖掘罕见文物和大型史前化石的同时，成群的当地斑点迅猛龙袭击了挖掘者，导致了致命的后果。突然爆发的凶猛攻势导致大部分船员丧生，幸存者则与文明世界隔绝。"},{t="苦涩的慰藉",b="回到米奈希尔港给塔雷尔·石纹带来了冷酷的宽慰。得知他的妻子和至少两名同伴因为一位名叫奥尔默的保卫者的勇气而幸存，这让他的心稍安，尽管如此多同事的惨死沉重地打击了城镇的边境精神。"}},faq={{q="湿地的挖掘队发生了什么事？",a="在发掘稀有文物和巨大的古代骨骼时，这支矮人探险队措手不及，被具有领地意识的斑点迅猛龙所淹没。大部分挖掘者被杀害，只剩下少数幸存者被困在挖掘场上方的悬崖上。",al={"挖掘场发生了什么","湿地挖掘灾难","挖掘为何失败"}},{q="谁救了麦琳·石纹？",a="麦琳认为是一位名叫奥尔默的勇敢保卫者击退了迅猛龙，并在下方挖掘场崩塌时护送她和勘探员到达了山脊上相对安全的地方。",al={"谁救了麦琳","奥尔默 石纹","奥尔默是谁"}},{q="塔雷尔·石纹是谁？",a="塔雷尔·石纹是麦琳的丈夫，驻扎在米奈希尔港。由于挖掘场久无音讯，他感到非常焦虑，并寻求旅行者调查她的下落。",al={"塔雷尔是谁","塔雷尔·石纹位置"}},{q="挖掘场在哪里？",a="挖掘场位于湿地内陆，米奈希尔港以东，丹莫德以西南。",al={"挖掘场在哪里","维尔加挖掘场位置"}},{q="探险队在挖掘什么？",a="在矮人勘探员的指导下，该团队正在挖掘埋藏在沼泽中的稀有地下文物和大型史前化石。",al={"他们在挖掘什么","挖掘文物"}},{q="除了麦琳还有其他幸存者吗？",a="是的，麦琳提到奥尔默和首席勘探员设法和她一起逃脱了迅猛龙的攻击，已知的幸存者总数共有三人。",al={"还有谁幸存","挖掘幸存者"}}},fp="32,194,24.315.0,15.237.0,53.201.0,28.122.0,25.163.0,30.99.0,36.148.0,40.95.0"}
P.entries["quest:3062"] = {n="黑暗之心",s="位于莫沙彻营地的塔罗·刺蹄想要埃达娜·恨爪的黑暗之心。她是居住在西边废墟中的北泉鹰身人女王。塔罗称她纯粹是邪恶的化身。",h="位于莫沙彻营地的塔罗·刺蹄想要埃达娜·恨爪的黑暗之心。她是居住在西边废墟中的北泉鹰身人女王。塔罗称她纯粹是邪恶的化身。",kw={"莫沙彻营地","黑暗之心","埃达娜·恨爪","菲拉斯","鹰身人","恨爪之石","北泉","塔罗·刺蹄"},sec={{t="鹰身人女王",b="埃达娜·恨爪是鹰身人的女王，统治着西边废墟中的北泉族群。塔罗称她纯粹是邪恶的化身，除了对他人的仇恨外，心中没有任何感情，并听说她的心脏是由水晶构成的。塔罗要你去面对她，并带回她的黑暗之心，因为她所散播的仇恨必须被终结。"},{t="召唤",b="塔罗听说鹰身人携带有一只号角。据传在废墟北部的恨爪之石附近吹响它，就能把女王引出来。塔罗很高兴想到，回应号角的将不会是她的族人，而是她的死亡。"},{t="当你归来时",b="塔罗现在确信埃达娜已经彻底消亡，并表示这颗心脏将被妥善保管，以纪念你的功绩。"}},faq={{q="埃达娜·恨爪是谁？",a="她统治着西部废墟中的北泉鹰身人。塔罗称她纯粹是邪恶的化身，说她只感受到仇恨，还听说她的心脏是水晶做的。",al={"埃达娜·恨爪","菲拉斯鹰身人女王","谁是鹰身人女王"}},{q="如何召唤埃达娜·恨爪？",a="塔罗听说鹰身人随身携带着一只号角，在废墟北端的恨爪之石附近吹响它，就能召唤出女王。",al={"如何召唤埃达娜","吹响号角 菲拉斯","恨爪之石"}},{q="是谁发布了狩猎埃达娜·恨爪的任务？",a="位于莫沙彻营地的塔罗·刺蹄。",al={"谁发布黑暗之心任务","塔罗·刺蹄","在哪里获得黑暗之心"}},{q="为什么塔罗·刺蹄想要埃达娜的心脏？",a="塔罗想要终结埃达娜在土地上散播的仇恨，因此索要她的黑暗之心。",al={"为什么需要黑暗之心","塔罗·刺蹄的动机"}}},fp="10,170,15.315.0,9.230.0,14.107.1,23.148.0,36.142.0,39.32.0,43.89.0"}
P.entries["quest:3063"] = {n="对鹰身人的复仇",s="塔罗·刺蹄曾经是一位经验丰富的猎人，无惧任何野兽，直到他被森林里的鸟妖伏击。从那以后，仇恨就在他心中沸腾，塔罗请求你去向西边的北泉鸟妖复仇。",h="塔罗·刺蹄曾经是一位经验丰富的猎人，无惧任何野兽，直到他被森林里的鸟妖伏击。从那以后，仇恨就在他心中沸腾，塔罗请求你去向西边的北泉鸟妖复仇。",kw={"菲拉斯","鸟妖","北泉","复仇","游羽","杀戮者","塔罗·刺蹄","唤风者"},sec={{t="老猎人的积怨",b="塔罗记得自己曾是一位经验丰富的猎人，无惧世间万物。直到在森林里的某一天，一场苦战过后，他正磨砺着武器，一群鸟妖包围了他。塔罗好不容易才逃出生天，但至今仍能听到她们的尖叫声在耳边回荡，从此他便不再是以前的自己了。事隔多年，那股仇恨依然在沸腾，塔罗渴望复仇。"},{t="北泉鸟妖",b="北泉鸟妖居住在西面。塔罗想要四只北泉鸟妖、四只北泉游羽、四只北泉唤风者和四只北泉杀戮者偿命。塔罗警告说，她们的翅膀如同黑夜一般，并且能潜入黑暗中消失不见。"},{t="狩猎之后",b="塔罗以老牛头人的口吻向你致谢，说你平复了他那颗备受煎熬的心。"}},faq={{q="塔罗·刺蹄是谁？",a="过去的一位老练猎人，无惧任何野兽，直到被森林里的鸟妖伏击。从此以后，塔罗就变了个人。",al={"塔罗·刺蹄的背景故事","谁发布了向北泉鸟妖复仇的任务","塔罗 菲拉斯"}},{q="北泉鸟妖在哪里？",a="在塔罗·刺蹄的西面。",al={"北泉鸟妖的位置","北泉鸟妖在哪里","菲拉斯鸟妖位置"}},{q="为什么塔罗想要向鸟妖复仇？",a="鸟妖在森林里伏击了塔罗，在他一场战斗后磨砺武器时包围了他，塔罗好不容易才逃脱。从此他便不再是以前的自己，而那股仇恨至今仍在心头翻涌。",al={"为什么要杀北泉鸟妖","塔罗·刺蹄的背景","塔罗为什么痛恨鸟妖"}},{q="塔罗想要杀掉哪些鸟妖？",a="四只北泉鸟妖、四只北泉游羽、四只北泉唤风者和四只北泉杀戮者。",al={"向北泉鸟妖复仇的目标","需要杀掉哪些鸟妖","北泉鸟妖的种类"}},{q="北泉鸟妖长什么样？",a="塔罗说她们的翅膀如同黑夜般漆黑，并警告说她们能遁入黑暗之中。",al={"鸟妖的外貌","北泉鸟妖的翅膀"}}},fp="28,228,22.338.0,23.229.0,14.91.1,22.132.0,42.30.0,47.174.0,36.113.0,42.91.0"}
P.entries["quest:3065"] = {n="普通石板",s="普通石板是初出茅庐的战士进入试炼谷的一种入门仪式。在证明了你对付当地野兽的勇气后，它会被交到你手中，指引你去找弗朗恩，这位当地的老兵负责将原始的蛮力转化为武技。",h="普通石板是初出茅庐的战士进入试炼谷的一种入门仪式。在证明了你对付当地野兽的勇气后，它会被交到你手中，指引你去找弗朗恩，这位当地的老兵负责将原始的蛮力转化为武技。",kw={"杜隆塔尔","弗朗恩","高内克","普通石板","大兽穴","试炼谷","战士"},ang={["class:Warrior"]="这份召唤标志着你踏上杜隆塔尔 The Warrior's Path 的第一步，直接指引你向弗朗恩学习基础姿态和打击技巧。",["faction:Horde"]="部落依靠源源不断的久经沙场的前线战士来保护杜隆塔尔那岌岌可危的边界，抵御半人马、野猪人和人类入侵者的威胁。",["race:Troll"]="在谷中训练的暗矛巨魔可能会听到弗朗恩对他（们）偏爱长矛胜过兽人斧头这一点的粗鲁评价，尽管他尊重任何能杀敌的手段。"},sec={{t="战斗的召唤",b="在证明了你能应付谷中的杂斑野猪后，高内克会把一张专门留给你的羊皮纸交给你。在杜隆塔尔恶劣的环境下，部落不会让他们的战士长时间缺乏指引。这块石板是一封邀请函，让你去找大兽穴外驻扎的战士训练师弗朗恩。"},{t="在大兽穴的阴凉处",b="弗朗恩在大兽穴外的阴凉处避暑，注视着从红色灌木丛中走来的新兵。他以老练的眼光评估着这些新兵，准备传授基础知识——无论是挥舞重斧还是使用长矛——以确保每一名新战士都能保卫年轻部落那脆弱的定居点。"}},faq={{q="什么是普通石板？",a="这是一份交给试炼谷年轻战士的入门指引。高内克将它传递下去，指引这些武技新兵去寻找驻地战士训练师弗朗恩。",al={"普通石板","这块石板是什么","战士笔记"}},{q="谁发送了这块石板？",a="这条信息来自大兽穴外休息的老兵、战士训练师弗朗恩，他一直在留意着新晋的战士。",al={"谁写的石板","谁发送了普通石板"}},{q="我在哪里可以找到弗朗恩？",a="弗朗恩驻扎在试炼谷内的大兽穴外，在岩石的遮蔽下躲避沙漠的烈日。",al={"弗朗恩位置","弗朗恩在哪里","寻找战士训练师"}},{q="弗朗恩为什么要提到长矛和斧头？",a="弗朗恩注意到了部落新兵中多样的战斗风格。虽然兽人偏爱双手斧这样沉重的砍刀，但巨魔和其他战士通常更喜欢长矛和轻便的长柄武器，这两者在战斗中都很有用。",al={"弗朗恩的长矛语录","为什么用长矛"}},{q="其他职业会接到这个任务吗？",a="不会。普通石板是专门给战士的。其他职业会收到属于他们自己的羊皮纸、符文或卷轴，指引他们去寻找各自的导师。",al={"普通石板是战士专属吗","试炼谷职业任务"}},{q="大兽穴的用途是什么？",a="大兽穴是试炼谷中一个有遮蔽的洞穴群，训练师、补给品和休息的新兵们会聚在这里，远离灼热的酷暑和游荡的野兽。",al={"什么是大兽穴","杜隆塔尔大兽穴"}}},fp="13,152,17.255.0,26.288.0,26.103.0,21.109.0,23.106.0,39.215.0,32.148.0,31.164.0"}
P.entries["quest:307"] = {n="肮脏的爪子",s="“肮脏的爪子”是巡山人卡尔·雷矛发布的一项任务，要求从被侵占的银泉矿洞中回收有价值的装备。尽管矿藏早已枯竭，但矿工联盟在狗头人侵入矿道之前，已将其改作仓库。矮人当局希望在巡山人对该地点发动毁灭性清洗之前，能够找回那些结实的工具。",h="“肮脏的爪子”是巡山人卡尔·雷矛发布的一项任务，要求从被侵占的银泉矿洞中回收有价值的装备。尽管矿藏早已枯竭，但矿工联盟在狗头人侵入矿道之前，已将其改作仓库。矮人当局希望在巡山人对该地点发动毁灭性清洗之前，能够找回那些结实...",kw={"肮脏的爪子","狗头人","洛克莫丹","矿工装备","矿工联盟","巡山人卡尔·雷矛","银泉矿洞","塞尔萨玛"},ang={["faction:Alliance"]="随着矮人的防御力量在卡兹莫丹各处分散，清理补给仓库可以确保重要的基础设施继续为联盟所用。",["profession:Mining"]="矿工们能够理解高品质矮人装备的价值，也明白让功能完好的工具在洞穴害虫的爪子里生锈是一件多么令人悲痛的事。",["race:Dwarf"]="对于矮人来说，看到粗鄙的狗头人玷污矿工联盟的手工艺品是一种侮辱，必须用迅捷的回收行动和锋利的钢铁来回应。"},sec={{t="枯竭的仓库",b="银泉矿洞坐落在奥加兹岗哨以东、洛克莫丹北部的山丘之中，很久以前就开采完了最后一点银矿脉。矮人矿工联盟并没有废弃这个地下建筑，而是将干燥的矿井重新改造为一个安全的仓库，用于存放备用的挖掘设备、十字镐和施工材料。在卡兹莫丹，只要有驻军守卫并抵御荒野的侵袭，坚固的地下隧道就是天然的仓库。"},{t="仓库里的爪子",b="矮人在洛克莫丹各地的警备力量有所削弱，狗头人趁机潜入了矿井。被黑暗的隧道和留下的闪亮铁制工具所吸引，这些害虫迅速将此地占为己有，当作巢穴。巡山人卡尔·雷矛急于带领一队战士进入隧道将它们消灭，但沉重的靴子和横扫的劈砍会震碎那些板条箱。冒险者必须潜入或一路杀进去，在全面进攻开始前把联盟的补给品取出来。"}},faq={{q="如果矿洞已经枯竭，为什么还要把装备留在里面？",a="在矿藏枯竭后，矿工联盟将银泉矿洞改建成了一个集中的存储仓库。矮人的地下隧道提供了坚固、干燥的庇护所，可以储存笨重的工具和物资，直到其他地方需要时再取出。",al={"为什么银泉矿洞里有装备","为什么矿洞里有工具","矿工联盟仓库"}},{q="为什么巡山人卡尔·雷矛不亲自清理矿洞？",a="卡尔·雷矛接到的命令是等待。此外，矿工联盟希望先将他们的装备取出来；如果卫兵冲进狭窄、黑暗的矿井，很可能会在激战中损坏那些装在板条箱里的精细工具。",al={"为什么雷矛不去","为什么巡山人要等待","雷矛任务原因"}},{q="银泉矿洞位于哪里？",a="矿洞位于洛克莫丹北部，奥加兹岗哨以东，巨石水坝以西南方向。",al={"银泉矿洞位置","银泉矿洞在哪里","“肮脏的爪子”发生地点"}},{q="为什么狗头人对矮人的工具如此感兴趣？",a="狗头人是强迫性的地下拾荒者。它们觊觎金属十字镐、铁铲、蜡烛和成品铁器，这些东西能让它们永无止境的挖掘工作变得更容易，因此满是矮人工具的仓库对它们来说是无法抗拒的战利品。",al={"为什么狗头人想要装备","狗头人偷窃工具","银泉矿洞的狗头人"}},{q="独自探索银泉矿洞危险吗？",a="矿洞内狭窄的通道和密集的狗头人使其变得十分危险。巡山人卡尔·雷矛明确警告说，独自前往的冒险者最好带上同伴。",al={"“肮脏的爪子”难吗","银泉矿洞难度","我能独自完成“肮脏的爪子”吗"}},{q="存放在矿洞里的物资属于谁？",a="这些物资属于铁炉堡矿工联盟，这是一个负责矮人王国境内的采石、采矿和管理地下资源的贸易协会。",al={"装备的主人是谁","矿工联盟的板条箱","谁经营矿工联盟"}}},fp="11,238,16.342.0,17.421.0,56.174.0,57.184.0,40.108.0,50.183.0,53.137.0,41.153.0"}
P.entries["quest:308"] = {n="加文的爱好",s="在雷酒酿制厂的地下室里，守卫加文·雷酒发现自己被成堆的酒桶包围，但他被禁止触碰它们。他渴望尝尝家族的佳酿，于是请求路过的冒险者为他拿一杯雷霆麦酒，以帮助他在值勤时保持清醒。",h="在雷酒酿制厂的地下室里，守卫加文·雷酒发现自己被成堆的酒桶包围，但他被禁止触碰它们。他渴望尝尝家族的佳酿，于是请求路过的冒险者为他拿一杯雷霆麦酒，以帮助他在值勤时保持清醒。",kw={"地下室","酿制厂","支开加文","丹莫罗","加文·雷酒","卡拉诺斯","雷霆麦酒"},ang={["class:Rogue"]="用烈酒分散守卫的注意力是行当里的古老伎俩，尽管加文很高兴自己要求这种分散注意力的行为。",["race:Dwarf"]="每个矮人都理解站在传说中的麦酒桶旁却不被允许喝上一口的痛苦。"},sec={{t="值勤时口渴的守卫",b="加文·雷酒的任务是看守卡拉诺斯雷酒酿制厂的地下仓库。尽管身处丹莫罗最好的黑啤酒之中，但根据家族的严令，他在值勤期间不得擅自取用库存。诱惑实在太大，以至于他不得不请求路过的旅人帮他从楼上的酒桶里打一品脱劲儿大的雷霆麦酒。"},{t="可疑的提神剂",b="加文坚称美酒只会磨砺他的感官，加强他的守备。纵容值勤的守卫是否明智尚存疑问，但在坚韧的丹莫罗矮人中，很少有人会因为雷酒家族的人想尝尝自己亲族酿造的举世闻名的佳酿而责怪他。"}},faq={{q="加文·雷酒是谁？",a="加文是著名的雷酒家族的一员，驻扎在卡拉诺斯雷酒酿制厂的地下室里，负责看守存放的酒桶。",al={"加文是谁","加文的背景故事","地下室守卫"}},{q="加文为什么需要别人给他带麦酒？",a="加文受家族严令，在值勤期间不得饮用地下室库存的酒。为了在不破坏密封酒桶的情况下绕过规则，他请外人从楼上给他带来一杯新鲜的麦酒。",al={"为什么加文不能喝酒","加文的麦酒任务","为什么要拿酒"}},{q="雷霆麦酒在哪里可以找到？",a="雷霆麦酒在卡拉诺斯的雷酒酿制厂楼上的主酒吧间供应，由旅店老板和酒保出售。",al={"获取雷霆麦酒","雷霆麦酒在哪里","购买雷霆麦酒"}},{q="雷酒酿制厂位于何处？",a="这家酿制厂是卡拉诺斯热闹的中心旅店，坐落在丹莫罗白雪皑皑的心脏地带，就在铁炉堡下方的山脚下。",al={"卡拉诺斯酿制厂","雷酒酿制厂地下室位置","加文在哪里"}},{q="雷酒酿制的麦酒为什么这么出名？",a="由雷酒氏族酿造，他们的黑啤酒和麦酒因其独特的冲击力、风味和矮人劲道而在卡兹莫丹乃至更远的地方享有盛名。",al={"雷酒家族声望","什么是雷霆麦酒"}},{q="把加文灌醉会惹麻烦吗？",a="加文声称麦酒只会让他更清醒，而不是让他迟钝，尽管这确实让他无法留意到有人在下层仓库乱逛。",al={"加文喝醉的后果","支开加文后会发生什么"}}},fp="18,241,23.266.0,19.230.0,26.143.0,46.179.0,27.114.0,44.135.0,33.147.0,44.134.0"}
P.entries["quest:3082"] = {n="风蚀石板",s="刻纹石板是猎人的一项入门任务，在完成最初的试炼后于试炼谷发放。它指引有抱负的巨魔猎人向猎人训练师基沙报到，以便开始他们在荒野中的正规训练。",h="刻纹石板是猎人的一项入门任务，在完成最初的试炼后于试炼谷发放。它指引有抱负的巨魔猎人向猎人训练师基沙报到，以便开始他们在荒野中的正规训练。",kw={"暗矛","杜隆塔尔","刻纹石板","高内克","猎人","基沙","试炼谷"},ang={["class:Hunter"]="这个任务标志着你正式加入了部落猎人的行列，建立了你与荒野以及当地训练师之间的纽带。",["faction:Horde"]="基沙与年轻新兵之间的交流展示了部落如何融合兽人和巨魔各自的文化优势，以确保他们共同的生存。",["race:Orc"]="对于年轻的兽人来说，收到这块石板代表着从他们的暗矛巨魔盟友那里学习精湛的荒野潜行和追踪术，以此补充传统的战士力量。",["race:Troll"]="基沙为暗矛巨魔的狩猎知识如何帮助部落在卡利姆多立足而感到自豪，重申了巨魔传统在其盟友生存中的重要作用。"},sec={{t="狩猎的召唤",b="在大兽穴中对付当地野猪证明了初步的勇气后，新手猎人会被高内克截住，并收到一条刻好的讯息。这块石板带有基沙的印记，她是驻扎在附近的一位技艺精湛的巨魔猎手。高内克将它递过来，以此作为年轻猎人已经展现出足够的胆量，足以引起经验丰富的生存专家注意的标志，标志着他们从基础的蛮力求生转向纪律严明的荒野训练。"},{t="生存的共享",b="当向基沙报到时，这位巨魔训练师讲述了部落中兽人和巨魔之间深厚的历史。虽然兽人拥有著名的战士和萨满传统，但暗矛巨魔带来了古老的潜行、追踪和生存技能，帮助兽人在艾泽拉斯生存下来。基沙将训练新猎人视为一种生存知识的持续交流，通过对狩猎的共同尊重，将这些盟友种族紧密地联系在一起。"}},faq={{q="谁发送了刻纹石板？",a="猎人训练师基沙发送了这块刻字的石板，一旦你在试炼谷证明了自己，它就会由高内克直接递交给你。",al={"谁写了刻纹石板","石板发送者","谁给了我这块石板"}},{q="基沙在哪里？",a="基沙位于杜隆塔尔的试炼谷北部区域，在大兽穴附近与其他职业导师待在一起。",al={"基沙位置","基沙在哪","寻找基沙"}},{q="为什么巨魔训练师在这里教导兽人猎人？",a="基沙说，部落在艾泽拉斯艰难求生时向巨魔求助以获取狩猎知识。兽人已经了解了战士和萨满之道，双方都在继续交流彼此的技能。",al={"为什么是巨魔猎人训练师","巨魔教导兽人","暗矛猎人"}},{q="上交这块石板后会发生什么？",a="基沙会收你为徒，并提出在你获得经验的过程中，指导你掌握部落猎人所需的基本技巧、射击和生存实践。",al={"石板之后做什么","刻纹石板奖励背景","基沙后续"}},{q="在获得这块石板前必须完成什么前置任务？",a="你必须首先通过击杀杂斑野猪完成高内克的初始任务“磨牙”，以证明你具备基本的耐力。",al={"石板前置任务","如何解锁刻纹石板","刻纹石板的前提条件"}},{q="任何职业都能完成这个任务吗？",a="不，这个任务专门针对在试炼谷开始旅程的新手猎人。其他职业会从高内克那里收到他们各自独特的训练召唤。",al={"谁能获得刻纹石板","刻纹石板职业要求","这是猎人专属吗"}}},fp="13,141,21.373.0,23.386.0,28.108.0,28.116.0,45.195.0,42.152.0,62.109.0,34.131.0"}
P.entries["quest:3083"] = {n="密文石板",s="密文石板是高内克交给在试炼谷受训的有志潜行者的一份征召令。这条信息由密码写成，指示新手扒手前往大兽穴寻找鲁瓦格，他是那里的秘密特工，负责监督潜行者的训练，并与破碎手氏族有着联系。",h="密文石板是高内克交给在试炼谷受训的有志潜行者的一份征召令。这条信息由密码写成，指示新手扒手前往大兽穴寻找鲁瓦格，他是那里的秘密特工，负责监督潜行者的训练，并与破碎手氏族有着联系。",kw={"杜隆塔尔","密文石板","高内克","潜行者训练师","鲁瓦格","破碎手氏族","大兽穴","试炼谷"},ang={["class:Rogue"]="这块石板标志着你正式加入了杜隆塔尔的秘密行动，让你与第一位导师鲁瓦格取得了直接联系，并让你接触到了破碎手氏族那无处不在的影响力。",["race:Orc"]="虽然传统的兽人文化崇尚公开的战场战斗，但兽人潜行者在现代部落中作为斥候和渗透者扮演着不可或缺的角色。",["race:Troll"]="暗矛潜行者将丛林的追踪本能与大兽穴导师所传授的刃术相结合，确立了他们对兽人盟友不可小觑的辅助作用。"},sec={{t="一份编码的征召令",b="一旦新兵证明了自己对抗当地野生动物的实力，高内克就会交出专门为他们递送的密文石板。这封信件并非使用直白的语言，而是用密码锁住的——这对于练习潜行、毒药和诡计艺术的人来说，既是一种考验，也是一种预防措施。它邀请新兵进入大兽穴，去见鲁瓦格，这位训练师负责为部落塑造潜行者、盗贼和扒手。"},{t="破碎手氏族之影",b="在破译指令并进入大兽穴后，新兵会找到鲁瓦格，他是效忠于破碎手氏族的特工。虽然他向新招募的潜行者保证，公会不会干涉他们的一举一动，但他警告说，如果学徒的表现不合格，氏族会追究他的责任。在一个被敌人环伺的新兴国家中，部落极其依赖沉默的斥候和敏捷的扒手来收集情报并从阴影中消除威胁。"}},faq={{q="密文石板的用途是什么？",a="它作为试炼谷中潜行者新手的入门征召令，指引他们前往大兽穴寻找职业训练师鲁瓦格。",al={"石板的作用","密文石板用途","为什么使用密文石板"}},{q="是谁将石板交给玩家的？",a="在你完成了猎杀杂斑野猪的初步战斗试炼后，试炼谷的试炼监督者高内克会把石板交给你。",al={"谁给予密文石板","石板任务发布者","高内克的石板"}},{q="在哪里可以找到鲁瓦格？",a="鲁瓦格位于大兽穴深处，那是坐落在试炼谷北侧悬崖边的一处黑暗洞穴建筑群。",al={"鲁瓦格的位置","鲁瓦格在哪里","寻找鲁瓦格"}},{q="鲁瓦格提到的“手”是指什么？",a="鲁瓦格指的是破碎手氏族，这是一个为萨尔大酋长的部落效力的暗杀者、间谍和潜行者的秘密网络与公会。",al={"什么是手氏族","破碎手氏族的鲁瓦格","谁是手氏族"}},{q="为什么石板要用加密的密码写成？",a="密码确保了潜行者敏感的事务及其联络人的身份不会被窥探，同时也能测试新兵处理机密信件的能力。",al={"为什么要加密","为什么使用密码","潜行者石板代码"}},{q="任何职业都能接受这个任务吗？",a="不能。密文石板专供在试炼谷开始旅程的巨魔潜行者使用。",al={"密文石板是潜行者专属吗","战士可以做密文石板任务吗","石板职业限制"}}},fp="16,157,15.335.0,22.376.0,44.113.0,38.132.0,24.101.0,37.124.0,49.160.0,35.99.0"}
P.entries["quest:3084"] = {n="符文石板",s="符文石板是一封发给在试炼谷受训的准萨满的召唤信。它由史克里克寄出，邀请有前途的新手开始接受正式教导，学习如何与灵魂沟通，并驾驭大地、火焰、水和空气的元素力量。",h="符文石板是一封发给在试炼谷受训的准萨满的召唤信。它由史克里克寄出，邀请有前途的新手开始接受正式教导，学习如何与灵魂沟通，并驾驭大地、火焰、水和空气的元素力量。",kw={"杜隆塔尔","元素","高内克","萨满","史克里克","石板","萨尔","试炼谷"},ang={["class:Shaman"]="这块石板标志着你正式踏上了萨满之路，要求你平衡元素力量，并成为先祖指引的灯塔。",["faction:Horde"]="萨满之道是新部落道德和精神的基石，为严酷的边境提供了一根荣誉与平衡的指南针。",["race:Orc"]="这块石板反映了萨尔所倡导的现代兽人对先祖萨满之道的回归，抛弃了过去恶魔术士留下的黑暗遗产。",["race:Troll"]="修习萨满之道的暗矛巨魔与史克里克这样的兽人导师找到了共同点，将他们与先祖的沟通和部落共享的元素传统融合在了一起。"},sec={{t="灵魂的召唤",b="在试炼谷尘土飞扬的训练场证明了最初的纪律后，刚入行的萨满会从高内克手中接过一块刻字的石板。石板上的符文是当地萨满训练师史克里克发出的邀请，标志着新手已经准备好将目光投向简单的肉搏战之外，去聆听自然世界更深处的流向。"},{t="新部落的精神领袖",b="萨满之道在复兴的部落中占据着神圣的地位。正如史克里克所教导的那样，萨满从四大元素中汲取力量，从先祖之灵中获得坚韧。萨满被期望效仿大酋长萨尔，成为社区的精神向导和智慧堡垒，为杜隆塔尔各处扎根的定居点提供保护。"}},faq={{q="什么是符文石板？",a="这是一块由高内克在试炼谷交给新手萨满的刻字石板。它传达了萨满训练师史克里克的召唤，督促年轻的冒险者将他们的精神和元素技艺学习正规化。",al={"符文石板","石板物品","萨满石板"}},{q="史克里克是谁？",a="史克里克是驻扎在试炼谷大兽穴入口附近的萨满训练师。她指导新的兽人和巨魔萨满掌握元素，并理解他们作为部落精神领袖的职责。",al={"史克里克","史克里克是谁","试炼谷萨满训练师"}},{q="为什么史克里克在对新萨满说话时会提到萨尔？",a="大酋长萨尔在旧部落受到恶魔腐蚀后，领导了先祖萨满之道的复兴。史克里克将萨尔视为萨满职责的典型榜样：在元素和谐与引导保护族人之间取得平衡。",al={"为什么提到萨尔","史克里克提到萨尔"}},{q="史克里克在哪里？",a="史克里克站在试炼谷东侧大兽穴入口外，准备向新手萨满传授他们早期的技巧。",al={"史克里克在哪里","找到史克里克"}},{q="谁分发这块石板？",a="高内克，他负责监督初到试炼谷的新人的初步试炼，一旦新手证明了自己的基本素质，他就会分发这块石板。",al={"谁给的石板","高内克石板"}},{q="史克里克教导的核心哲学是什么？",a="史克里克强调，萨满的原始力量来自于火、地、水和空气，而他们的耐力和决心则源于先祖之灵。萨满被期望为他们所加入的任何城镇或战团提供智慧和防御。",al={"史克里克哲学","萨满教导"}}},fp="21,178,21.346.0,37.317.0,34.191.0,15.206.0,60.225.0,25.141.0,25.149.0,40.210.0"}
P.entries["quest:3085"] = {n="神圣石板",s="这是一份交给试炼谷中初出茅庐的牧师的简单召唤令，发给那些刚刚完成了最初的力量试炼的学徒。这块刻有铭文的石板指引着年轻的通灵者去寻找暗矛巨魔牧师训练师肯杰，由他引导他们进行更深层次的灵魂交流。",h="这是一份交给试炼谷中初出茅庐的牧师的简单召唤令，发给那些刚刚完成了最初的力量试炼的学徒。这块刻有铭文的石板指引着年轻的通灵者去寻找暗矛巨魔牧师训练师肯杰，由他引导他们进行更深层次的灵魂交流。",kw={"暗矛","杜隆塔尔","高内克","神圣石板","肯杰","牧师","灵魂","大兽穴","试炼谷"},ang={["class:Priest"]="这个任务标志着从普通的山谷试炼过渡到大兽穴外肯杰主持的正规精神指导。",["faction:Horde"]="随着部落在杜隆塔尔定居，秘术修行者们确保了精神仪式和灵魂的意志依然是这个新国家发展的核心。",["race:Troll"]="石板强调了暗矛的精神传统，转向祖先之灵和洛阿神灵，而非外来牧师教派的教条哲学。"},sec={{t="来自肯杰的信息",b="在接受高内克的监督并证明了自己能够对付当地的野猪之后，在试炼谷训练的年轻牧师会收到一块刻有铭文的石头，被称为神圣石板。这则信息由高内克转交，上面印有肯杰的徽记。肯杰是一位驻扎在大兽穴外面的暗矛巨魔秘术师，负责照看那些追寻信仰与精神魔法之道的初来者。"},{t="与灵魂沟通",b="不同于跨越海洋的人类或矮人所信奉的圣光，部落暗矛巨魔的牧师之道核心在于与灵魂和洛阿神灵的沟通。肯杰通过提醒杜隆塔尔的新手学徒们，他们的力量源自精神修养，并承诺只在他们的灵魂纽带成熟时才会传授他们更高等的仪式，以此欢迎他们。"}},faq={{q="什么是神圣石板？",a="这是一块由巨魔牧师训练师肯杰发送给在试炼谷受训的年轻牧师的铭文信息。在高内克确认学徒在山谷中展示出基本能力之前，这块石板由他代为保管。",al={"什么是神圣石板","神圣石板物品","石板背景故事"}},{q="肯杰是谁？",a="肯杰是一位驻扎在试炼谷大兽穴外面的暗矛巨魔牧师训练师。他指导年轻的学徒如何与灵魂沟通，并引导他们学习掌握治疗和暗影精神艺术。",al={"肯杰","肯杰是谁","肯杰训练师"}},{q="为什么牧师起步时要先猎杀杂斑野猪？",a="试炼谷里的每一位学徒，无论其职业为何，在接受专业导师的训练之前，都必须先证明自己具备基本的自力更生和野外生存能力。",al={"为什么要杀野猪","初试锋芒的关联"}},{q="肯杰的牧师之道与圣光有何不同？",a="暗矛牧师祈求的是灵魂和洛阿神灵，而不是像人类和矮人教会那样祈祷圣光。肯杰强调的是与这些无形的存在保持恩惠和和谐。",al={"巨魔牧师背景","部落牧师","灵魂与圣光的对比"}},{q="大兽穴在哪里？",a="大兽穴是位于杜隆塔尔南部试炼谷中的一处洞穴聚落，是监督新入伍部落成员的训练师和试炼官们的聚集地。",al={"大兽穴杜隆塔尔","大兽穴在哪里","肯杰位置"}},{q="兽人可以通过这个任务成为牧师吗？",a="不能。在试炼谷，只有暗矛巨魔拥有在肯杰门下成为牧师所需的精神传统。兽人文化更多依赖于萨满教义和术士魔法。",al={"兽人牧师","兽人可以成为牧师吗","兽人神圣石板"}}},fp="15,172,22.270.0,26.318.0,28.188.0,15.181.0,51.186.0,57.197.0,17.149.0,43.174.0"}
P.entries["quest:3086"] = {n="雕文石板",s="雕文石板是试炼谷为新手部落法师提供的入门级职业任务。在证明了自己的实力后，高内克会派发该任务，指引年轻的施法者去找大兽穴外驻扎的暗矛巨魔法师训练师——迈安。",h="雕文石板是试炼谷为新手部落法师提供的入门级职业任务。在证明了自己的实力后，高内克会派发该任务，指引年轻的施法者去找大兽穴外驻扎的暗矛巨魔法师训练师——迈安。",kw={"奥术","杜隆塔尔","雕文石板","高内克","法师","迈安","大兽穴","试炼谷"},ang={["class:Mage"]="这个任务标志着你正式加入部落法师的行列，向你介绍了山谷里的训练师，并强调了控制原始魔法所需的严谨心态。",["race:Orc"]="在长期由萨满和战士主导的兽人文化中，法师并不常见，因此，在迈安的指导下学习奥术的兽人，走的是一条族人中少有人尝试的道路。",["race:Troll"]="对于踏上奥术之路的暗矛巨魔来说，接受迈安的指导反映了该部族在传统精神仪式之外，对正规施法方式的日益适应。"},sec={{t="铭文石上的讯息",b="在试炼谷通过与当地野生生物的战斗证明了自己的基本实力后，初出茅庐的法师们会收到高内克转交的一块铭文石板。这封信件来自该山谷的常驻法师训练师迈安，她要求新手在准备好进行正式的奥术学习时，前往大兽穴入口处寻找她。"},{t="无形之物的危险",b="见到迈安时，她没有客套，直截了当地指出了奥术力量的严酷现实。虽然她承认法师拥有塑造世界的力量，但她警告说，他们面临的最大威胁既不是敌对的战士，也不是敌对的种族，而是魔法本身那股无形且具有腐蚀性的诱惑。她建议大家保持谦逊和耐心，并告诫说，不受控制的魔法很容易让施法者高估自己的能力。"}},faq={{q="谁将雕文石板交给玩家？",a="在你完成了在试炼谷清理杂斑野猪的初步任务后，山谷的初始任务发布者高内克会将这块石板交给你。",al={"谁给予雕文石板","去哪里获取雕文石板","雕文石板入门"}},{q="迈安是谁？",a="迈安是一位暗矛巨魔法师训练师，驻扎在试炼谷大兽穴入口外。她负责指导部落法师新手的早期法术，并就奥术腐蚀的危险发出严厉警告。",al={"谁是迈安","迈安背景故事","巨魔法师训练师"}},{q="迈安在哪里？",a="迈安站在试炼谷北部，大兽穴入口外，隧道口的右侧。",al={"迈安在哪里","迈安位置","寻找迈安"}},{q="迈安对魔法提出了什么警告？",a="迈安警告说，魔法具有内在的腐蚀性影响，无法轻易阻止。她强调，法师应该警惕奥术带来的无形诱惑和权力幻觉，而不是像兽人、精灵或矮人这样的物理敌人。",al={"迈安的警告","魔法腐蚀背景","迈安说了什么"}},{q="其他职业会收到雕文石板吗？",a="不会。雕文石板仅指定给法师新手。其他职业会收到各自训练师量身定制的独特入门召唤物品，例如符文、卷轴或印记。",al={"其他职业能获得雕文石板吗","雕文石板是法师专属吗"}},{q="完成此石板任务需要什么前提条件？",a="你必须首先完成高内克的初始任务“露两手”，即在试炼谷的红土地上猎杀杂斑野猪。",al={"雕文石板需求","雕文石板前置任务"}}},fp="14,179,28.251.0,25.328.0,46.86.0,14.168.0,24.112.0,42.188.0,44.158.0,53.121.0"}
P.entries["quest:3087"] = {n="风蚀羊皮纸",s="风蚀羊皮纸是试炼谷的一项新手任务，引导年轻的兽人猎人找到当地的职业训练师基沙。在新手完成初次见血的试炼后，由高内克交付，这份笔记开启了在杜隆塔尔进行专业荒野训练和求生技能学习的大门。",h="风蚀羊皮纸是试炼谷的一项新手任务，引导年轻的兽人猎人找到当地的职业训练师基沙。在新手完成初次见血的试炼后，由高内克交付，这份笔记开启了在杜隆塔尔进行专业荒野训练和求生技能学习的大门。",kw={"暗矛","杜隆塔尔","风蚀羊皮纸","高内克","猎人训练师","基沙","试炼谷"},ang={["class:Hunter"]="这张字条代表了你作为部落猎人的首次正式认可，它指引你去找基沙，以提升你的准头并理解荒野。",["faction:Horde"]="猎人负责侦察边界并为营地提供食物；让新手尽早接触他们的技艺，能确保杜隆塔尔这个新兴国家获得充足的补给和保卫。",["race:Orc"]="兽人猎人依靠基沙这样的导师，将传统的氏族狩猎方法运用到杜隆塔尔干旱的岩壁和致命的野兽之中。",["race:Troll"]="对于暗矛新兵来说，在基沙的指导下学习，可以传承从回音群岛带来的古老丛林追踪传统。"},sec={{t="来自荒野的召唤",b="在证明了自己对抗当地斑点野猪的基本能力后，从试炼谷出发的猎人会从高内克那里收到一张风蚀羊皮纸。这封信件出自基沙之手，她是一位暗矛猎人，在营地边缘观察着新到来的人。这张字条是一份接受正式训练的正式邀请，承认了新手具备了征服野兽和适应杜隆塔尔严酷环境所需的本能。"},{t="猎人之道",b="向基沙报到标志着从普通新兵向专注追踪者的转变。基沙打消了新来者认为猎人技艺比奥术或先祖萨满之道更简单的念头。征服杜隆塔尔的掠食者、维护远程武器以及在严酷的土地上生存需要不懈的纪律。她指示学徒去帮助谷中的其他居民，在回到她身边学习更高级的求生技巧之前，先测试自己的能力。"}},faq={{q="什么是风蚀羊皮纸？",a="这是一份由高内克代表猎人训练师基沙递交的书面召唤。它号召有前途的新兵向她报到，在试炼谷接受专门的战斗和野外生存指导。",al={"这张羊皮纸是什么","风蚀羊皮纸笔记","猎人羊皮纸"}},{q="谁将这份召唤交给玩家？",a="在你在试炼谷完成击杀斑点野猪的初次试炼后，高内克会将这张羊皮纸交给你。",al={"谁发放风蚀羊皮纸","我在哪里接到任务"}},{q="基沙是谁？",a="基沙是一位驻扎在试炼谷的暗矛巨魔猎人。她负责评估新晋的兽人和巨魔猎人，教导他们远程作战、追踪和驯兽的基本技能。",al={"基沙背景故事","谁是基沙"}},{q="为什么基沙将猎人与法师和萨满相提并论？",a="基沙警告说，许多人认为与驾驭先祖之灵或奥术魔法相比，狩猎是一条轻松的道路。她强调，掌握致命的精准射击和驯服野兽同样需要专注和面对危险。",al={"为什么猎人并不轻松","基沙对话含义"}},{q="向基沙报到后会发生什么？",a="基沙会向你介绍进阶的猎人技巧，并指示你协助试炼谷的其他居民，以磨练你新获得的实用求生技能。",al={"风蚀羊皮纸之后做什么","猎人任务后续"}},{q="谁可以接到这个任务？",a="此任务仅提供给在试炼谷受训的新建兽人猎人。",al={"谁能获得风蚀羊皮纸","这是猎人专属任务吗"}}},fp="16,182,23.365.0,16.423.0,29.203.0,40.101.0,16.165.0,55.194.0,41.183.0,27.79.0"}
P.entries["quest:3088"] = {n="密文羊皮纸",s="密文羊皮纸是发给那些在试炼谷证明了基本生存技能的新手兽人潜行者的传唤函。它以密码书写，指引有前途的新兵前往大兽穴的阴影深处，去见鲁瓦格，他是为碎手氏族利益效力的特工。",h="密文羊皮纸是发给那些在试炼谷证明了基本生存技能的新手兽人潜行者的传唤函。它以密码书写，指引有前途的新兵前往大兽穴的阴影深处，去见鲁瓦格，他是为碎手氏族利益效力的特工。",kw={"杜隆塔尔","密文羊皮纸","高内克","兽人潜行者","鲁瓦格","碎手氏族","大兽穴","试炼谷"},ang={["class:Rogue"]="这张羊皮纸标志着你正式加入部落的秘密机构，为你引荐鲁瓦格并开始你最初的专业训练。",["faction:Horde"]="即使是像萨尔这样光荣的部落大酋长也认识到，为了保护杜隆塔尔这片新生土地免受隐蔽威胁，间谍和斥候是必不可少的。",["race:Orc"]="与那些寻求公开、嗜血荣耀的典型兽人战士不同，兽人潜行者将祖先的纪律与碎手氏族所要求的冷静狡黠结合在一起。"},sec={{t="一份加密的传唤函",b="在证明了自己面对当地野生动物时的勇气后，新手兽人会收到由高内克转交的密文羊皮纸。当其他训练师在空地上公开招募学员时，潜行者训练师鲁瓦格更喜欢密码和岩石带来的隐秘安全感。这张羊皮纸指引新手穿过阳光照耀的营地，深入被称为大兽穴的洞穴。"},{t="暗影中的眼睛",b="在破译了字条并冒险进入后，新手会发现鲁瓦格潜伏在岩石中。鲁瓦格对潜伏在洞穴深处的术士心存怀疑，他毫不耽搁地解释了自己的真实效忠对象：他代表碎手氏族监视新兵。虽然兽人社会崇尚战场上的公开荣誉和荣耀，但碎手氏族是部落隐秘的间谍、杀手和情报收集网络。"}},faq={{q="谁寄出了密文羊皮纸？",a="这张羊皮纸由试炼谷的潜行者训练师鲁瓦格撰写。在年轻兽人完成最初的试炼后，他会让高内克把这份编码信息传交给有前途的新兵。",al={"谁写了羊皮纸","谁给了我密文羊皮纸","谁寄出了字条"}},{q="这个任务的目的是什么？",a="这是兽人潜行者的职业入门任务，教导他们如何在大兽穴中找到鲁瓦格，以便开始他们关于潜行、开锁和战斗诡计的正式训练。",al={"为什么我需要密文羊皮纸","这个任务是做什么的"}},{q="鲁瓦格在哪里？",a="鲁瓦格躲在大兽穴里，这是一个位于试炼谷北侧的阴暗洞穴。他潜伏在入口附近的阴影中，与深处的术士们保持着谨慎的距离。",al={"鲁瓦格在哪里","寻找鲁瓦格","鲁瓦格位置"}},{q="为什么羊皮纸要加密？",a="潜行者依靠保密和谨慎行事。使用密码可以确保四处游荡的野兽或好奇的外来者无法阅读传唤函，同时也能测试新兵破译隐秘通讯的能力。",al={"为什么使用密码","为什么字条是编码的"}},{q="碎手氏族是谁？",a="碎手氏族最初是一个以自残而臭名昭著的兽人氏族，在萨尔的部落中，他们已经演变成一个由斥候、刺客和秘密特工组成的组织，在暗处工作以保护部落的利益。",al={"部落碎手氏族","什么是碎手氏族"}},{q="为什么鲁瓦格不信任Nartok？",a="Nartok是位于大兽穴深处的一名术士训练师。潜行者通过潜行来行动，但即使是鲁瓦格也觉得黑暗施法者在洞穴最深处公开进行邪能仪式令人深感不安。",al={"鲁瓦格与nartok","为什么鲁瓦格讨厌术士"}}},fp="19,153,15.300.0,19.322.0,34.174.0,34.144.0,22.150.0,31.145.0,27.212.0,30.145.0"}
P.entries["quest:3089"] = {n="符文羊皮纸",s="符文羊皮纸是寄给在试炼谷开启旅程的部落萨满祭司新手的信件。这张羊皮纸由训练师史克里克书写，召集有前途的新手开始他们与灵魂和元素沟通的正式教导。",h="符文羊皮纸是寄给在试炼谷开启旅程的部落萨满祭司新手的信件。这张羊皮纸由训练师史克里克书写，召集有前途的新手开始他们与灵魂和元素沟通的正式教导。",kw={"祖先","杜隆塔尔","元素","高内克","符文羊皮纸","萨满","史克里克","试炼谷"},ang={["class:Shaman"]="这张羊皮纸代表了你精神旅程的第一步，巩固了你与杜隆塔尔的灵魂和原始元素之间神圣的契约。",["race:Orc"]="对于兽人来说，回归萨满教义是在向德拉诺的祖先传统致敬，这些传统在旧部落受恶魔腐化期间几乎被灭绝。",["race:Troll"]="响应这一召唤的暗矛巨魔将他们与生俱来的精神共鸣和对祖先的崇敬融入了新部落共同的萨满传统中。"},sec={{t="来自灵魂的召唤",b="在证明了自己对抗当地野生动物的基本生存技能后，新的兽人萨满祭司会从试炼谷的监工高内克手中接过一张符文羊皮纸。这张羊皮纸上带有来自谷内萨满训练师史克里克的神秘文字，要求与新到来的新手会面。"},{t="萨满之道",b="向史克里克报到标志着萨满祭司对部落的神圣职责正式开始。史克里克提醒年轻的新手，他们的使命不仅仅是战斗；他们被选中作为祖先之魂的媒介和元素之怒的掌控者。通过史克里克，新的萨满祭司学习引导精神能量、治愈伤口并呼唤卡利姆多的自然力量。"}},faq={{q="符文羊皮纸是什么？",a="这是高内克在试炼谷交给新萨满祭司的书面召唤，要求他们寻找训练师史克里克以获取关于元素的正式指导。",al={"这是什么任务","羊皮纸任务","萨满新手笔记"}},{q="谁寄出的羊皮纸？",a="这封信是由史克里克执笔的，她是驻扎在试炼谷洞穴附近的萨满训练师，等待着那些被选中去指引族人灵魂的人。",al={"谁写了羊皮纸","史克里克的笔记","谁是史克里克"}},{q="我应该把羊皮纸带到哪里？",a="你只需在试炼谷内步行一小段路，史克里克就站在红色的岩石下，随时准备训练兽人和巨魔萨满祭司。",al={"我该去哪","史克里克在哪里","交付地点"}},{q="为什么我的角色被选中接收它？",a="根据史克里克的说法，那些被萨满之路吸引的人被选中作为祖先的媒介，并直接与世界的元素力量对话。",al={"为什么是萨满","为什么被选中","萨满使命背景"}},{q="提交羊皮纸后会发生什么？",a="史克里克会接受你作为她的学生，引导你走上元素魔法、祖先沟通以及治疗与战斗基础的道路。",al={"下一步","史克里克做什么","羊皮纸之后"}},{q="任何职业都能完成这个任务吗？",a="不能。符文羊皮纸是专门写给萨满祭司新手的。其他职业会收到各自职业训练师不同的召唤。",al={"这是萨满专属吗","谁会收到这张羊皮纸","战士的羊皮纸"}}},fp="24,182,26.272.0,22.280.0,37.122.0,24.143.0,30.143.0,42.132.0,44.137.0,34.114.0"}
P.entries["quest:309"] = {n="护送货物",s="“保护货物”是洛克莫丹南部的一项护送任务，冒险者需要保护信使米兰前往铁环挖掘场。米兰携带了一箱勘察员基恩萨·铁环急需的易爆火药。这段旅程揭示了威胁着矮人腹地的黑铁矮人潜伏破坏活动。",h="“保护货物”是洛克莫丹南部的一项护送任务，冒险者需要保护信使米兰前往铁环挖掘场。米兰携带了一箱勘察员基恩萨·铁环急需的易爆火药。这段旅程揭示了威胁着矮人腹地的黑铁矮人潜伏破坏活动。",kw={"火药","黑铁矮人伏击","铁环挖掘场","洛克莫丹护送任务","米兰","勘察员基恩萨·铁环"},ang={["faction:Alliance"]="联盟在洛克莫丹依赖通畅的后勤；保护信使免受地底袭击者的伤害，维持了铁炉堡与东部边境之间的联系。",["profession:Mining"]="矿工们深知在开凿卡兹莫丹坚硬基岩时，火药的价值与危险性。",["race:Dwarf"]="对于铁炉堡的矮人来说，保卫勘察员基恩萨·铁环的补给就是捍卫遗产，保护祖先的发现免遭他们那死对头——黑铁矮人的破坏。"},sec={{t="危在旦夕的运送任务",b="勘察员基恩萨·铁环在洛克莫丹南部山丘进行的考古挖掘工作需要稳定的火药供应，以开凿坚硬的岩石。当补给线中断、运送货车受到威胁时，信使米兰带着沉重的火药滞留在路上。安全地引导米兰走过崎岖的道路前往挖掘场，可以确保基恩萨·铁环的工作不会彻底停滞。"},{t="黑铁同情者",b="通往挖掘场的道路上不仅有野兽出没；黑铁渗透者们正伺机拦截这批爆炸性货物。他们在挖掘场附近的肆意伏击向勘察员基恩萨·铁环揭示了一个黑暗的事实：黑铁势力正在获取非法物资，并积极在洛克莫丹中心地带制造混乱。虽然这次运送确保了挖掘工作的继续，但也引发了人们对于敌人渗透联盟领地深度的担忧。"}},faq={{q="谁是米兰？",a="米兰是一名联盟信使，负责将重要物资（尤其是火药）沿着洛克莫丹危险的乡间小路运往铁环挖掘场。",al={"米兰是谁","米兰 洛克莫丹","信使米兰"}},{q="勘察员基恩萨·铁环为什么需要火药？",a="勘察员基恩萨·铁环在洛克莫丹南部领导着一项重要的考古挖掘工作。他的团队依靠大量的火药来清除岩石、挖掘埋藏的文物并维持挖掘作业。",al={"勘察员基恩萨·铁环为何需要火药","火药用途","勘察员基恩萨·铁环的火药"}},{q="护送途中谁会发动攻击？",a="黑铁矮人破坏者会在靠近挖掘场的地方伏击信使，试图夺取炸药并阻挠铁炉堡在该地区的行动。",al={"谁伏击了米兰","伏击者","护送途中的袭击者"}},{q="护送目的地在哪里？",a="护送任务始于洛克莫丹南部的道路，终点是位于湖泊东南方山丘上的铁环挖掘场。",al={"护送目的地","米兰去哪里","勘察员基恩萨·铁环在哪里"}},{q="为什么黑铁矮人会在洛克莫丹？",a="黑铁氏族在整个卡兹莫丹都设有秘密据点和间谍。他们积极袭击补给线，破坏探险者协会的挖掘工作，并试图破坏铁炉堡的防御外围。",al={"洛克莫丹的黑铁矮人","为什么这里有黑铁矮人","黑铁矮人的活动"}},{q="货物送达后会发生什么？",a="勘察员基恩萨·铁环如释重负地收下了火药，他感谢圣光保佑，尽管附近有黑铁同情者活动的令人不安的消息，但这批补给还是送到了。",al={"任务后续","“保护货物”之后发生什么","下一个任务"}}},fp="23,214,21.234.0,22.293.1,13.155.0,45.165.0,30.146.0,27.123.0,33.171.0,40.129.0"}
P.entries["quest:3090"] = {n="被污染的羊皮纸",s="你外出时，一名信使留下了一张有标记的羊皮纸，你的老师 Nartok 想与你谈谈。信中质疑萨尔的统治，并警告掌握术士之力的人正面临危险。",h="你外出时，一名信使留下了一张有标记的羊皮纸，你的老师 Nartok 想与你谈谈。信中质疑萨尔的统治，并警告掌握术士之力的人正面临危险。",kw={"污损的羊皮纸","大兽穴","nartok","奥格瑞玛","施法","萨尔","试炼谷","术士"},ang={["class:Warlock"]="作为一名术士，Nartok 的警告关乎你所掌握的力量，以及鲁莽行事的危险。"},sec={{t="一封信在等你",b="据说这张羊皮纸来自你的新老师 Nartok。信中请你读完后到试炼谷的大兽穴与他交谈。Nartok 称兽人是骄傲的民族，并认为萨尔拒绝了本可让这片土地归他们所有的力量。"},{t="在他们之中占有一席",b="Nartok 说你已加入他们的行列，但提醒你，掌握术士之力并不能让你受到欢迎。萨尔允许术士进入奥格瑞玛，因为他们仍是兽人；Nartok 警告你，鲁莽行事可能致命。若你需要学习施法，他随时可以教你。"}},faq={{q="是谁送来的羊皮纸？",a="据说这张羊皮纸来自你的新老师 Nartok。",al={"是谁送来的","羊皮纸来自谁"}},{q="我可以在哪里与 Nartok 交谈？",a="Nartok 在试炼谷的大兽穴。",al={"nartok 在哪里","nartok 的位置"}},{q="Nartok 如何看待萨尔？",a="Nartok 说，萨尔拒绝了本可让这片土地归他们所有的力量。",al={"萨尔的看法","为何批评萨尔"}},{q="萨尔为什么允许术士进入奥格瑞玛？",a="Nartok 说，萨尔允许术士进入奥格瑞玛，因为他们仍是兽人。",al={"奥格瑞玛的术士","萨尔为何允许术士"}},{q="Nartok 给出了什么警告？",a="Nartok 警告说，掌握术士之力并不能保证受到接纳，而且鲁莽行事可能致命。",al={"nartok 的警告","术士的危险"}},{q="Nartok 能教我法术吗？",a="Nartok 说，如果你需要学习施法，可以再来找他。",al={"法术课程","术士训练"}}},fp="17,175,15.240.0,18.262.1,23.64.0,30.45.0,33.73.0,46.78.0,30.90.0,27.65.0"}
P.entries["quest:3091"] = {n="简易便笺",s="“简易的便条”是一封由纳拉其营地的当地信使递交给新手牛头人战士的简短书面传召。这封信由训练师哈鲁特·雷角书写，号召年轻的战士报到，提醒他们战士与德鲁伊和萨满祭司在保卫部落边界、抵御半人马入侵方面所扮演的重要角色。",h="“简易的便条”是一封由纳拉其营地的当地信使递交给新手牛头人战士的简短书面传召。这封信由训练师哈鲁特·雷角书写，号召年轻的战士报到，提醒他们战士与德鲁伊和萨满祭司在保卫部落边界、抵御半人马入侵方面所扮演的重要角色。",kw={"纳拉其营地","半人马","哈鲁特·雷角","莫高雷","红云台地","简易的便条","牛头人","战士"},ang={["class:Warrior"]="哈鲁特·雷角指引着牛头人新手战士，教导他们克制好战的自负，并扛起保卫纳拉其营地免受半人马劫掠的重任。",["race:Tauren"]="对于在红云台地开始旅程的年轻牛头人来说，这封便条强化了一个观念：保卫部落的军事职责与萨满教义和德鲁伊教义等精神使命地位同等重要。"},sec={{t="战斗的号召",b="当年轻的战士到达纳拉其营地时，会收到由营地信使送达的简短传召。这封由资深训练师哈鲁特·雷角书写的“简易的便条”敦促新手战士立即报到，开始他们在保卫部落方面的实际训练。"},{t="守卫者的重担",b="虽然舒哈鲁人深切敬仰他们的精神领袖，但哈鲁特提醒他的学生，作为身体守卫者的他们肩负着同样的重担。战士们被征召去巡逻部落边界，猎杀掠夺成性的半人马群，并保护他们爱好和平的族人免受外来侵略。尽管战斗能带来荣耀，但每位战士都必须保持谦逊，并完成与任何萨满祭司或德鲁伊相同的传统仪式。"}},faq={{q="谁写了“简易的便条”？",a="这封便条是由纳拉其营地的战士训练师哈鲁特·雷角通过一名信使发出的，信使寻找着准备开始军事训练的年轻牛头人。",al={"谁发出的简易便条","谁写的便条","简易便条发送者"}},{q="谁是哈鲁特·雷角？",a="哈鲁特·雷角是一位驻扎在莫高雷纳拉其营地的牛头人战士训练师。他负责训练那些寻求战斗荣耀和渴望学习部落战争祖传之道的年轻战士。",al={"哈鲁特是谁","哈鲁特·雷角","哈鲁特在哪里"}},{q="“简易的便条”目的是什么？",a="这封便条号召刚觉醒的战士去见他们的训练师，并提醒他们，前线守卫者和猎人和德鲁伊及萨满祭司一样，对部落至关重要。",al={"为什么这封便条很重要","便条内容"}},{q="为什么战士被征召去猎杀半人马？",a="莫高雷的牛头人一直面临着边界处敌对半人马群的威胁。像哈鲁特这样的战士负责训练部落的守卫者去猎杀他们并保护营地。",al={"为什么对抗半人马","牛头人与半人马的冲突"}},{q="纳拉其营地位于哪里？",a="纳拉其营地是鹰风部落年轻牛头人的祖传训练营和起始定居点，位于莫高雷红云台地的边缘。",al={"纳拉其营地位置","纳拉其营地在哪里"}},{q="哈鲁特提到的部落仪式是什么？",a="部落的每一位成员，无论是战士、猎人、萨满祭司还是德鲁伊，都必须参加部落共享的祖传仪式，以证明他们的力量、谦逊和对族人的奉献。",al={"牛头人的成年仪式","牛头人要进行什么仪式"}}},fp="11,203,19.174.0,21.316.0,26.112.0,26.149.0,39.153.0,45.107.0,30.160.0,42.190.0"}
P.entries["quest:3092"] = {n="风化便笺",s="风化便笺是一份发给纳拉其营地中前途无量的年轻牛头人猎人的正式传唤。该信息代表训练师兰卡·远箭传达，呼吁新手前往，开始掌握荒野的实用与精神技艺。",h="风化便笺是一份发给纳拉其营地中前途无量的年轻牛头人猎人的正式传唤。该信息代表训练师兰卡·远箭传达，呼吁新手前往，开始掌握荒野的实用与精神技艺。",kw={"纳拉其营地","风化便笺","兰卡·远箭","莫高雷","红云台地","牛头人猎人"},ang={["class:Hunter"]="这份传唤标志着你正式加入了猎人传统，准备好让你掌握射击艺术、荒野生存和野兽伙伴关系。",["race:Tauren"]="对于舒哈鲁来说，狩猎是一项神圣的职责，通过尊重那些供养部落穿越莫高雷平原的野兽，来向大地母亲致敬。"},sec={{t="狩猎的召唤",b="当年轻的牛头人在红云台地的峭壁间训练时，若展现出在射击和追踪方面的天赋，他们就会收到一张风化便笺。这张便笺经由格鲁尔·鹰风之手传达，告知年轻猎人，兰卡·远箭已经注意到了他们的血统和潜力，并敦促他们在他的注视下正式开始学习。"},{t="平原的传统",b="对于舒哈鲁来说，猎人绝不仅仅是侦察兵或战士。猎人通过猎物供养部落，保护游牧营地，并与卡利姆多的野兽保持着密切的平衡。通过召集新手进行训练，兰卡为掌握武器、了解莫高雷的生物，以及最终承担驯服野生同伴的古老艺术奠定了基础。"}},faq={{q="风化便笺的目的是什么？",a="风化便笺作为一种正式介绍，将新手牛头人猎人与驻扎在纳拉其营地的本地职业训练师兰卡·远箭联系在一起。",al={"风化便笺的作用","风化便笺的用途","为什么我收到了风化便笺"}},{q="是谁递送了这张便笺？",a="格鲁尔·鹰风传递了这张便笺，并解释说刚才有一位来自猎人训练师的信使专门来寻找这位年轻的猎人。",al={"谁给予了风化便笺","风化便笺的任务发布者","风化便笺"}},{q="兰卡·远箭在哪里？",a="兰卡·远箭居住在红云台地的纳拉其营地，站在猎人训练场附近，准备指导新兵。",al={"兰卡·远箭在哪里","寻找兰卡·远箭","兰卡的位置"}},{q="为什么猎人在牛头人中如此受人尊敬？",a="猎人在牛头人社会中发挥着至关重要的作用，他们提供食物、解读未被驯服的荒野，并维护着与平原灵魂之间的和谐。",al={"牛头人猎人背景故事","为什么牛头人猎人很重要"}},{q="这项训练介绍了哪些技能？",a="兰卡教导新手基础的狩猎技巧，包括远程武器的使用、了解野兽，以及最终掌握驯服动物同伴所需的仪式。",al={"兰卡教什么","牛头人猎人基础"}},{q="读完便笺后的下一步是什么？",a="向兰卡·远箭报到即完成了传唤，他将成为你的训练师，并在你成长过程中教导你射击步枪、驯服宠物以及更多技巧。",al={"风化便笺之后的下一个任务","风化便笺后续"}}},fp="11,145,21.280.0,23.299.0,39.96.0,22.126.0,31.116.0,44.94.0,41.124.0,45.135.0"}
P.entries["quest:3094"] = {n="绿色便笺",s="“绿色便笺”是一份发给红云台地中前途无量的年轻牛头人的正式传唤函。这份便笺由加尔特·迷雾行者托付给格鲁尔·鹰风，号召自然的萌芽守护者们前往纳拉其营地寻找德鲁伊导师加尔特·迷雾行者。",h="“绿色便笺”是一份发给红云台地中前途无量的年轻牛头人的正式传唤函。这份便笺由加尔特·迷雾行者托付给格鲁尔·鹰风，号召自然的萌芽守护者们前往纳拉其营地寻找德鲁伊导师加尔特·迷雾行者。",kw={"纳拉其营地","德鲁伊","大地母亲","加尔特·迷雾行者","格鲁尔·鹰风","莫高雷","红云台地","绿色便笺"},ang={["class:Druid"]="这份传唤代表了德鲁伊在引导艾泽拉斯荒野能量与躁动灵魂方面的最初入门。",["faction:Horde"]="牛头人德鲁伊是现代部落与卡利姆多自然奥秘之间的主要桥梁，为该阵营原始的武力提供了精神上的平衡。",["race:Tauren"]="对于牛头人来说，德鲁伊教义不仅仅是一个魔法流派，更是源于他们对大地母亲的神圣奉献而继承下来的神圣盟约。"},sec={{t="通往修行之路的传唤",b="在红云台地履行职责的年轻牛头人因其天赋而被迅速选中。格鲁尔·鹰风代表加尔特·迷雾行者派出的信使转交了这封信。这份便笺是进入牛头人德鲁伊古老传承的邀请函，号召初学者从基础的村落杂务中脱身，去倾听那来自平原的低语平衡。"},{t="大地母亲的呼唤",b="在回应了传唤后，加尔特·迷雾行者警告这位初出茅庐的德鲁伊，祖先之灵与自然之灵在整个莫高雷变得躁动不安。牛头人德鲁伊的使命是成为自然的活体化身，无论远方的争端如何，都要维持与大地母亲意志的和谐。虽然暗夜精灵也修习德鲁伊之道，但加尔特告诫说，他们的傲慢蒙蔽了双眼，使其无法看清牛头人与自然界深厚的渊源。"}},faq={{q="什么是绿色便笺？",a="这是一份发送给纳拉其营地年轻牛头人德鲁伊的入门传唤函。它指示携带者寻找当地训练师加尔特·迷雾行者，以开始德鲁伊艺术的系统训练。",al={"绿色便笺","德鲁伊信件","莫高雷德鲁伊任务便笺"}},{q="谁将便笺交给玩家？",a="格鲁尔·鹰风将便笺交给了年轻的德鲁伊，并提到加尔特·迷雾行者派出的信使最近一直在找他们。",al={"谁给予绿色便笺","绿色便笺任务起始"}},{q="在哪里可以找到加尔特·迷雾行者？",a="加尔特·迷雾行者居住在纳拉其营地，驻扎在营地天然峭壁的庇护之下，他在那里监督牛头人德鲁伊新手的训练。",al={"加尔特·迷雾行者位置","加尔特在哪里"}},{q="为什么加尔特·迷雾行者要警告关于暗夜精灵的事？",a="尽管两个种族都崇敬自然，并通过塞纳里奥议会修习德鲁伊之道，但加尔特观察到，暗夜精灵的傲慢常常会影响他们对其他文化的看法。他鼓励他的学生无视这种态度，专注于大地母亲的智慧。",al={"牛头人和暗夜精灵德鲁伊","暗夜精灵傲慢德鲁伊"}},{q="为什么莫高雷的灵魂躁动不安？",a="加尔特·迷雾行者感觉到扰动正在整个莫高雷平原激荡着祖先之灵与自然之灵，这标志着平衡荒野将成为这位新德鲁伊终身职责的早期迹象。",al={"莫高雷灵魂躁动","为什么自然之灵愤怒"}},{q="完成此任务后，加尔特接下来会教什么技能？",a="在向加尔特·迷雾行者报到后，他将成为初学者的训练师，并承诺随着他们智慧的增长，教授大地母亲的恩赐。",al={"绿色便笺之后是什么","德鲁伊后续任务"}}},fp="12,134,21.325.0,25.337.0,25.124.0,36.117.0,35.126.0,54.146.0,40.157.0,62.144.0"}
P.entries["quest:3095"] = {n="简易卷轴",s="你对付天灾军团时，收到一卷盖有Dannal Stern印记的密封卷轴。卷轴召你前往丧钟镇，Dannal在那里谈起你的自由，并表示愿意教导你。",h="你对付天灾军团时，收到一卷盖有Dannal Stern印记的密封卷轴。卷轴召你前往丧钟镇，Dannal在那里谈起你的自由，并表示愿意教导你。",kw={"dannal stern","丧钟镇","简单的角色","被遗忘者","天灾军团","简单的卷轴","希尔瓦娜斯","训练"},sec={{t="密封的信件",b="你外出对付那些毫无理智的天灾军团时，有人送来一卷卷轴。封印看起来属于Dannal Stern，他是丧钟镇的战士训练师。信中请你读完后去找他谈谈，再次启程。"},{t="自由与训练",b="Dannal说，其他人逃过一死，逃到了镇上；他看到了他们坚韧不拔的潜质。他认为是希尔瓦娜斯解放了你的身躯与灵魂，尽管瘟疫依然折磨着你。他表示，随着你积累经验，愿意教导你；希尔瓦娜斯也需要你这样的职业人才，帮助拯救被遗忘者。"}},faq={{q="谁给我寄了卷轴？",a="卷轴上有Dannal Stern的封印，他是丧钟镇的战士训练师。",al={"卷轴寄件人","谁寄来的","dannal的卷轴"}},{q="为什么会收到这卷轴？",a="信中请你读完后去丧钟镇找Dannal Stern谈谈。",al={"为何寄卷轴","这卷轴有什么用","简单的卷轴"}},{q="Dannal怎么评价希尔瓦娜斯？",a="Dannal认为是希尔瓦娜斯解放了你的身躯与灵魂，尽管瘟疫依然影响着你。",al={"希尔瓦娜斯的解放","希尔瓦娜斯做了什么","希尔瓦娜斯与我"}},{q="Dannal愿意提供什么？",a="Dannal愿意在你积累经验时教导你，并请你去找他。",al={"dannal的教导","dannal能训练我吗","战士训练师"}},{q="希尔瓦娜斯需要我做什么？",a="Dannal说，希尔瓦娜斯需要你这样的职业人才，帮助拯救被遗忘者。",al={"希尔瓦娜斯的需求","我的职业职责","被遗忘者的未来"}}},fp="13,177,16.240.0,20.296.0,23.80.0,26.73.0,36.98.0,23.82.0,32.78.0"}
P.entries["quest:3096"] = {n="密文卷轴",s="密文卷轴是递交给丧钟镇刚苏醒的被遗忘者潜行者的一份谨慎召集令。由暗影牧师萨维斯转交，这道暗号指引新兵前往大卫·提亚斯处，他是一位在当地旅店中悄然行动的潜行者导师。",h="密文卷轴是递交给丧钟镇刚苏醒的被遗忘者潜行者的一份谨慎召集令。由暗影牧师萨维斯转交，这道暗号指引新兵前往大卫·提亚斯处，他是一位在当地旅店中悄然行动的潜行者导师。",kw={"大卫·提亚斯","丧钟镇","密文卷轴","被遗忘者潜行者","暗影牧师萨维斯","暗影行者","提瑞斯法林地"},ang={["class:Rogue"]="这份信件标志着你正式加入了被遗忘者的秘密网络，架起了从一具刚苏醒的尸体到一名渴望成为隐秘特工者之间的桥梁。",["race:Undead"]="随着新组建的被遗忘者在提瑞斯法林地抵御天灾军团和生者残余势力，侦察兵和隐秘特工对黑暗女王的生存战略至关重要。"},sec={{t="悄然的召集",b="当新复活的被遗忘者在墓地中与无脑僵尸作战时，定居点的领导层会留意那些在潜行和隐秘行动方面有特殊倾向的人。一旦初步准备就绪，暗影牧师萨维斯就会将这张封印的羊皮纸交给有前途的侦察兵。它盖有大卫·提亚斯的谨慎印章，作为对被遗忘者等级制度之下运作的阴影网络的初步引荐。"},{t="暗影之眼",b="大卫·提亚斯注视着丧钟镇的十字路口和旅店，为未来的秘密行动搜寻潜在的人选。被遗忘者需要的不是普通的小偷或鲁莽的扒手，而是为这个新生的王国效力的纪律严明的隐秘特工。提亚斯暗示，有能力的潜行者最终可能会引起暗影行者的注意，他们是被遗忘者内部一个专门的组织，崇尚狡诈、精准以及对黑暗女王的绝对忠诚。"}},faq={{q="密文卷轴的用途是什么？",a="这张卷轴是发给刚苏醒的被遗忘者潜行者的私人邀请函。一旦你证明了自己的能力，暗影牧师萨维斯就会将其交给你，指引你向大卫·提亚斯报到以接受专业训练。",al={"什么是密文卷轴","卷轴的作用","为什么要用密文卷轴"}},{q="大卫·提亚斯是谁？",a="大卫·提亚斯是驻扎在丧钟镇旅店的潜行者训练师。他负责评估新兵，并为更大的被遗忘者情报行动搜寻潜在的特工。",al={"大卫·提亚斯","大卫·提亚斯是谁","丧钟镇潜行者训练师"}},{q="提亚斯提到的暗影行者是谁？",a="暗影行者是被遗忘者的一个潜行特工和刺客组织。提亚斯告诫新潜行者，暗影行者只会招募有天赋、有纪律的特工，而不是笨拙的扒手。",al={"谁是暗影行者","被遗忘者暗影行者","暗影行者"}},{q="为什么信息是加密的？",a="被遗忘者潜行者非常看重保密性和行动安全。通过加密的通讯来指引潜在人选，可以确保敏感信息在像丧钟镇这样脆弱的定居点中免受粗心之人的窥探。",al={"为什么加密","为什么使用暗号"}},{q="在哪里可以找到暗影牧师萨维斯？",a="暗影牧师萨维斯在提瑞斯法林地的丧钟镇中央墓穴和教堂建筑群内，负责监督新被遗忘者的初步接收工作。",al={"萨维斯在哪里","萨维斯位置","寻找暗影牧师萨维斯"}},{q="大卫·提亚斯在哪里？",a="大卫·提亚斯站在丧钟镇中央教堂沿路而下的一座受损旅店建筑内。",al={"提亚斯在哪里","大卫·提亚斯位置","丧钟镇旅店训练师"}}},fp="16,154,15.339.0,19.365.0,44.173.0,19.145.0,46.129.0,29.171.0,39.137.0,29.91.0"}
P.entries["quest:3097"] = {n="神圣卷轴",s="《神圣卷轴》是针对丧钟镇新觉醒的被遗忘者牧师的入门召唤。这份公文由暗影牧师萨维斯移交，召集新手前往破败的村庄礼拜堂寻找黑暗牧师杜斯滕，以了解亡灵在死后如何运用信仰。",h="《神圣卷轴》是针对丧钟镇新觉醒的被遗忘者牧师的入门召唤。这份公文由暗影牧师萨维斯移交，召集新手前往破败的村庄礼拜堂寻找黑暗牧师杜斯滕，以了解亡灵在死后如何运用信仰。",kw={"黑暗牧师杜斯滕","丧钟镇","被遗忘者牧师","神圣卷轴","牧师任务","暗影牧师萨维斯","提瑞斯法林地"},ang={["class:Priest"]="这个任务标志着你在哲学上对被遗忘者神职的洗礼，拒绝传统的虔诚奉献，转而拥抱自立、苦难和暗影魔法。",["race:Undead"]="该卷轴体现了被遗忘者的世界观：脱离了旧有的人类信仰，他们纯粹依靠钢铁般的意志和相互间的需求而生存。"},sec={{t="丧钟镇的召唤",b="当新觉醒的亡灵从丧钟镇的坟墓中蹒跚走出时，他们的头脑往往因为瘟疫、死亡以及突然从巫妖王掌控中解脱而产生的创伤而感到眩晕。对于那些生前曾是圣光虔诚信徒的人来说，困惑尤为深刻。当新生的亡灵与徘徊在定居点外围的无脑天灾军团战斗时，暗影牧师萨维斯会拦截收到的信息。这封带有黑暗牧师杜斯滕印记的《神圣卷轴》要求新晋的牧师放弃游荡，前往受损的城镇礼拜堂报到。"},{t="信仰的重塑",b="在递交卷轴后，新手会接触到被遗忘者牧师严苛的神学。黑暗牧师杜斯滕毫不留情：圣光在死亡中抛弃了他们，祖先之灵只是空洞的传说，而虚空恶魔对他们的苦难毫无兴趣。相反，被遗忘者的神职人员教导说，纯粹的意志力和彻底的自立才是救赎的唯一真正源泉。在杜斯滕的教导下，新生的修行者学会了引导神圣戒律和暗影，运用力量不是出于对遥远神灵的虔诚，而是出于对自己生存的绝对信念。"}},faq={{q="什么是神圣卷轴？",a="这是一份由暗影牧师萨维斯交给丧钟镇新晋被遗忘者牧师的封印文件。它指示他们前往城镇礼拜堂寻找黑暗牧师杜斯滕，以开始正式的牧师训练。",al={"神圣卷轴","卷轴物品","牧师卷轴"}},{q="谁给玩家发送了卷轴？",a="该卷轴带有黑暗牧师杜斯滕的个人印记，他是居住在丧钟镇礼拜堂的被遗忘者牧师导师，尽管它是由暗影牧师萨维斯交给你的。",al={"谁发送了卷轴","杜斯滕卷轴","萨维斯信件"}},{q="被遗忘者还能运用圣光吗？",a="黑暗牧师杜斯滕告诉新牧师，圣光不再与他们有关。正如他所解释的，传统的圣光崇拜被放弃，取而代之的是对自己信仰以及对暗影的掌控。",al={"亡灵使用圣光","被遗忘者圣光","亡灵可以施放圣光吗"}},{q="黑暗牧师杜斯滕在哪里？",a="他位于提瑞斯法林地西部丧钟镇中心的废墟教堂内，站在其他被遗忘者训练师附近。",al={"寻找杜斯滕","杜斯滕位置","黑暗牧师杜斯滕在哪里"}},{q="为什么杜斯滕不理会祖先和恶魔？",a="杜斯滕试图剥离新复活的亡灵所持有的所有幻想。他告诉他们，圣光不再与他们有关，祖先的灵魂只是童话故事，而虚空生物也不需要他们，并以此宣扬被遗忘者仅凭意志生存了下来。",al={"杜斯滕的演讲","童话故事","虚空不想要你"}},{q="阅读卷轴后会发生什么？",a="你阅读了羊皮纸，并向丧钟镇礼拜堂的黑暗牧师杜斯滕报到，从而解锁你最初的牧师技能，并确立他为你在此新手区域的训练师。",al={"神圣卷轴任务目标","提交卷轴"}}},fp="15,218,23.456.0,15.447.0,28.167.0,35.107.0,40.195.0,37.133.0,46.241.0,38.163.0"}
P.entries["quest:3098"] = {n="雕文卷轴",s="雕文卷轴是发给丧钟镇新觉醒的被遗忘者法师的正式传唤。这张羊皮纸上盖着法师训练师伊莎贝拉的印章，指引着那些有前途的奥术修行者前往村庄里破败的教堂找到她，以磨练他们不稳定的力量。",h="雕文卷轴是发给丧钟镇新觉醒的被遗忘者法师的正式传唤。这张羊皮纸上盖着法师训练师伊莎贝拉的印章，指引着那些有前途的奥术修行者前往村庄里破败的教堂找到她，以磨练他们不稳定的力量。",kw={"奥术","丧钟镇","被遗忘者法师","雕文卷轴","伊莎贝拉","法师训练师","提瑞斯法林地"},ang={["class:Mage"]="这张卷轴标志着你正式加入被遗忘者法师的行列，将你的魔法技艺直接与你刚获得自由的族群的生存与复兴联系在了一起。",["race:Undead"]="被遗忘者法师带着黑暗的目的挥舞奥术，他们不把魔法视为达拉然那样的学术游戏，而是将其视为夺回他们被窃家园不可或缺的武器。"},sec={{t="奥术传唤",b="当一名刚被复活的被遗忘者在丧钟镇周围清理无脑的天灾军团时展现出对奥术魔法的亲和力，他们很快就会引起长辈们的注意。雕文卷轴由专人送达，上面印有当地法师导师伊莎贝拉的奥术印记。它要求这位新晋的修行者前往她在破败教堂内的岗位报到，因为如果不加管制，这种魔法天赋对被遗忘者造成的危险和对他们的敌人一样大。"},{t="亡灵的魔法运用",b="在丧钟镇破败的礼拜堂内，伊莎贝拉教导初学者们，死亡并没有使他们免受奥术危险的影响。虽然死亡剥夺了他们身体上的虚弱，但魔法那不稳定的拉扯和腐蚀本质依然如故。对于被遗忘者来说，追求奥术支配地位不仅仅是一项学术追求，更是一种生存和复仇的工具——这是夺回命运、消灭任何挑战他们对洛丹伦脆弱统治权的敌人的手段。"}},faq={{q="什么是雕文卷轴？",a="雕文卷轴是一份带有丧钟镇被遗忘者法师训练师伊莎贝拉个人印章的指导文书。它指示新觉醒的法师前往破败的教堂报告，以推进他们的奥术研究。",al={"雕文卷轴任务","这是什么卷轴","丧钟镇卷轴"}},{q="谁给你发送了雕文卷轴？",a="这张卷轴由丧钟镇的驻地法师训练师伊莎贝拉发出，在你证明了自己的价值、清理了附近无脑的天灾军团后递交给你。",al={"谁发送了卷轴","谁写了雕文卷轴","雕文卷轴发送者"}},{q="伊莎贝拉在哪里？",a="伊莎贝拉驻扎在丧钟镇中心那座破败的村庄教堂内，与其他为新复活的被遗忘者提供指导的职业导师待在一起。",al={"伊莎贝拉在哪里","找到伊莎贝拉","丧钟镇法师训练师位置"}},{q="为什么伊莎贝拉要警告你魔法腐蚀？",a="伊莎贝拉警告说，尽管被遗忘者是亡灵，但奥术力量不稳定的本质依然没有改变。魔法仍然带有持续的腐蚀和成瘾风险，需要纪律和意志来掌控，否则就会被其吞噬。",al={"亡灵魔法腐蚀","奥术腐蚀背景知识","为什么魔法对亡灵危险"}},{q="为什么奥术魔法对丧钟镇的被遗忘者很重要？",a="被遗忘者法师将奥术力量视为夺回洛丹伦、确保他们在无脑天灾军团、敌对活着的凡人以及血色十字军面前获得自治权的至关重要的工具。",al={"为什么被遗忘者使用魔法","亡灵法师背景知识"}},{q="任何被遗忘者职业都能收到这张卷轴吗？",a="不能。雕文卷轴专门发放给被遗忘者法师，作为前往丧钟镇主要职业训练师处的入门传唤。",al={"雕文卷轴是法师专属吗","术士能得到雕文卷轴吗","谁能获得雕文卷轴"}}},fp="14,157,23.347.0,25.403.0,27.173.0,36.114.0,26.130.0,52.134.0,60.153.0,43.102.0"}
P.entries["quest:3099"] = {n="被污染的卷轴",s="“被污染的卷轴”是丧钟镇的一项早期任务，指引刚苏醒的被遗忘者术士前往他们的训练师马克西米利安处。通过这封信件，马克西米利安邀请初学者拥抱力量与黑暗的奴役，以此作为确保获得真正自由的手段。",h="“被污染的卷轴”是丧钟镇的一项早期任务，指引刚苏醒的被遗忘者术士前往他们的训练师马克西米利安处。通过这封信件，马克西米利安邀请初学者拥抱力量与黑暗的奴役，以此作为确保获得真正自由的手段。",kw={"丧钟镇","被遗忘者","马克西米利安","天灾军团","希尔瓦娜斯","被污染的卷轴","提瑞斯法林地","术士"},ang={["class:Warlock"]="马克西米利安在丧钟镇引导刚苏醒的被遗忘者术士，将恶魔学识和奴役视为掌控与自由的终极主张。",["race:Undead"]="被遗忘者术士在打破天灾军团的枷锁与寻求可供驱使以求生存的恶魔仆从之间建立了一种黑暗的联系。"},sec={{t="黑暗召唤",b="在刚复生的被遗忘者开始清理丧钟镇周围漫无目的的天灾军团残党后不久，一封带有丧钟镇当地术士训练师马克西米利安印章的不祥信件随之送达。卷轴召唤收信人深思奴役与自主的本质，然后再回到这座废弃的定居点亲自与他交谈。"},{t="控制哲学",b="在回应召唤后，马克西米利安揭示了他关于力量与征服的哲学。他认为既然已经从巫妖王盲目的掌控中挣脱，那么只要没有夺取真正的权威，奴隶就永远是奴隶。在他眼中，驾驭恶魔仆从并非背叛希尔瓦娜斯，而是被遗忘者争取自我决定权与尊重的自然结果。"}},faq={{q="是谁寄出了“被污染的卷轴”？",a="这封卷轴上盖有马克西米利安的个人印章，他是驻扎在丧钟镇的术士训练师，负责寻找刚苏醒的黑暗艺术从业者。",al={"谁寄出了被污染的卷轴","谁给了我被污染的卷轴","被污染的卷轴寄件人"}},{q="马克西米利安是谁？",a="马克西米利安是丧钟镇的术士训练师，负责指导刚复生的被遗忘者学习召唤和控制恶魔实体的黑暗艺术。",al={"马克西米利安是谁","马克西米利安 丧钟镇","术士训练师 丧钟镇"}},{q="“被污染的卷轴”上写了什么？",a="这是一封寄给刚苏醒术士的信件，其中反思了自由、力量和奴役的本质，敦促读者拜访马克西米利安以获取更深入的指导。",al={"什么是被污染的卷轴","卷轴说了什么","卷轴信息"}},{q="马克西米利安是希尔瓦娜斯女士的叛徒吗？",a="马克西米利安明确表示他并非希尔瓦娜斯女士的叛徒。他声称女妖之王会欣赏他的观点，并指出她本人对自我决定权的追求正是打破他们天灾枷锁的关键。",al={"马克西米利安是叛徒吗","马克西米利安是否背叛希尔瓦娜斯","马克西米利安的忠诚"}},{q="我在哪里可以找到马克西米利安？",a="马克西米利安住在丧钟镇，那是提瑞斯法林地里的一座废弃定居点，刚复生的被遗忘者最初就是从那里的坟墓中苏醒的。",al={"在哪里找到马克西米利安","马克西米利安位置"}},{q="这个任务的目的是什么？",a="该任务是为刚复生的被遗忘者术士提供的引导性召唤，旨在让他们开始职业训练，并将他们引向丧钟镇的导师处。",al={"为什么术士任务是被污染的卷轴","被污染的卷轴目的"}}},fp="14,258,14.340.0,25.413.1,28.171.0,19.148.0,38.178.0,42.202.0,29.134.0,34.176.0"}
P.entries["quest:31"] = {n="水栖形态",s="这个任务标志着年轻的部落德鲁伊掌握水下能力的旅程迈出了最后一步。在证明了自己的价值并与月光林地的海狮之魂建立感应后，这位德鲁伊回到了雷霆崖的家中，接受正式的认可并掌握他们的水栖形态。",h="这个任务标志着年轻的部落德鲁伊掌握水下能力的旅程迈出了最后一步。在证明了自己的价值并与月光林地的海狮之魂建立感应后，这位德鲁伊回到了雷霆崖的家中，接受正式的认可并掌握他们的水栖形态。",kw={"水栖形态","德迪利特·星焰","德鲁伊","月光林地","海狮坠饰","海狮","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="掌握水栖形态架起了连接陆地与海洋的桥梁，让你能毫不费力地穿行于水域，并在深海中躲避捕食者。",["faction:Horde"]="牛头人德鲁伊代表了部落与塞纳里奥议会之间的精神纽带，行走于古老的中立圣地与他们自己的部落首都之间。",["race:Tauren"]="图拉克·符文图腾提醒你，掌握海洋中的野兽是告慰祖先的善举，也巩固了牛头人回归德鲁伊之道的神圣使命。"},sec={{t="海狮的回归",b="在月光林地这一圣地通过了考验后，一位充满抱负的牛头人德鲁伊受到德迪利特·星焰的指引，返回莫高雷。带着海狮坠饰，这位学徒展示了他们在这片横跨卡利姆多的水域中保持平衡与奉献的切实证明。这是他们遵循古老传统并获得水栖形态的实证。"},{t="与水域的交流",b="在登上雷霆崖的高地后，这位旅者将坠饰交给了导师图拉克·符文图腾。图拉克对于这位学徒尊崇祖先和自然平衡感到非常欣慰，并传授了水栖形态的秘诀。掌握了这门技艺后，德鲁伊获得了潜入河流与海洋的本能，能够自由呼吸，并化身为海洋生物畅游深海。"}},faq={{q="这个任务的目的是什么？",a="这个任务结束了年轻部落德鲁伊的成人礼，让他们能在雷霆崖上交来之不易的海狮坠饰，最终解锁他们的变形能力：水栖形态。",al={"为什么要做这个任务","水栖形态的目的","这个任务奖励什么"}},{q="我应该把海狮坠饰交给谁？",a="你必须将坠饰交给位于莫高雷雷霆崖上层的德鲁伊训练师图拉克·符文图腾。",al={"任务交给谁","水栖形态交任务地点","图拉克·符文图腾位置"}},{q="是谁让你返回雷霆崖的？",a="德迪利特·星焰，一位驻守在中立圣地月光林地的暗夜精灵德鲁伊看守者，在你完成水下考验后会指引你返回。",al={"谁提供水栖形态任务","德迪利特·星焰任务"}},{q="非德鲁伊职业可以完成这个任务吗？",a="不能。这个任务线仅限德鲁伊完成，作为他们修行并解锁动物形态的灵性与魔法成长之路的一部分。",al={"这是德鲁伊专属吗","其他职业能获得水栖形态吗"}},{q="为什么月光林地的暗夜精灵会帮助部落的德鲁伊？",a="月光林地是由塞纳里奥议会监管的中立圣地。在教授塞纳里奥之道的古老技艺时，暗夜精灵导师会抛开政治偏见指引牛头人德鲁伊，专注于维护自然的平衡。",al={"为什么德迪利特帮助部落","月光林地部落联盟关系","德鲁伊中立性"}},{q="完成这个任务会获得什么能力？",a="在向图拉克·符文图腾交付任务后，你将学会水栖形态，在变形后获得更高的游泳速度和水下呼吸能力。",al={"我能获得什么形态","水栖形态法术","水下形态"}}},fp="12,200,22.290.0,25.337.0,34.148.0,46.114.0,36.86.0,35.108.0,53.187.0,46.101.0"}
P.entries["quest:310"] = {n="针锋相对",s="“苦涩的竞争对手”是丹莫罗早期的一个联盟任务，源于两个自豪的矮人酿酒家族之间激烈的竞争。马莱斯·麦酒派遣一位冒险者潜入卡拉诺斯的雷酒酿制厂，并对竞争对手的库存动手脚。",h="“苦涩的竞争对手”是丹莫罗早期的一个联盟任务，源于两个自豪的矮人酿酒家族之间激烈的竞争。马莱斯·麦酒派遣一位冒险者潜入卡拉诺斯的雷酒酿制厂，并对竞争对手的库存动手脚。",kw={"麦酒烈焰","苦涩的竞争对手","丹莫罗","卡拉诺斯","马莱斯·麦酒","雷霆麦酒","雷酒酿制厂"},ang={["class:Rogue"]="潜入守卫森严的地窖，引开哨兵，并偷偷替换违禁品，这对任何潜行者来说都是熟悉的工作，即使奖励是啤酒而不是金币。",["faction:Alliance"]="卡拉诺斯是联盟旅行者在丹莫罗的文化和物流中心，这使得当地的酒馆纠纷成为过往新兵经常参与的消遣。",["race:Dwarf"]="对于矮人来说，酿酒是一项严肃的事业，其声望可与铁匠工艺相媲美。卷入一场因竞争对手的麦酒而引发的地窖争端，在丹莫罗的冰天雪地里再合适不过了。"},sec={{t="竞争的滋味",b="在卡兹莫丹，很少有东西能像一杯麦酒那样迅速激发人们的热情。长期以来，麦酒家族一直对卡拉诺斯著名的雷酒酿制厂的阴影感到不满。虽然马莱斯·麦酒勉强承认雷酒酿制厂的工艺值得尊敬，但她无法忍受它是丹莫罗唯一知名佳酿的说法。为了动摇当地人的口味，她设计了一个计划，用她自己调制的烈性酒——麦酒烈焰——来替换一桶雷霆麦酒。"},{t="地窖诡计",b="执行这个计划需要直接在卡拉诺斯的顾客眼皮子底下行动。酿制厂的厨房下方是地窖储藏室，陈年的酒桶正在那里等待开封。由于雷酒酿制厂在他们最珍贵的储备酒桶旁安排了守卫，想要破坏的人必须想办法在偷偷替换酒桶之前引开守卫。"}},faq={{q="谁发布了“苦涩的竞争对手”这个任务？",a="马莱斯·麦酒发布了这个任务。她决心证明她家族的酿酒工艺可以与雷酒酿制厂供应的著名饮品相媲美。",al={"谁发布了苦涩的竞争对手","马莱斯任务发布者"}},{q="雷酒地窖在哪里？",a="地窖位于卡拉诺斯镇的雷酒酿制厂下方。通往地下的楼梯隐藏在厨房的一张桌子后面。",al={"雷酒地下室在哪里","如何进入酿制厂地窖"}},{q="什么是麦酒烈焰？",a="麦酒烈焰是马莱斯·麦酒自酿的烈性麦酒。她相信，如果卡拉诺斯的顾客在以为它是雷霆麦酒的情况下品尝它，他们最终会承认她在酿酒方面的卓越水平。",al={"麦酒烈焰","我需要交换哪种酒"}},{q="如何绕过看守酒桶的卫兵？",a="在地下室值守的雷酒酿制厂卫兵会透露一些线索，暗示什么东西能吸引他的注意力，让你在趁他分心时有足够的时间调换酒桶。",al={"地窖卫兵干扰","无人看管的雷霆麦酒桶","卫兵酒桶"}},{q="为什么麦酒家族和雷酒家族会结怨？",a="这事关矮人的职业自尊。雷酒家族在卡拉诺斯的当地酒馆圈子里占据主导地位，而麦酒家族想要证明他们自己的配方同样出色，甚至更好。",al={"酿酒师世仇","为什么麦酒家族讨厌雷酒家族"}},{q="“苦涩的竞争对手”之后接什么任务？",a="一旦麦酒烈焰酒桶被安置好，任务就会直接导向“返回马莱斯”以报告你的成功。",al={"苦涩的竞争对手后续任务","苦涩的竞争对手之后是什么"}}},fp="13,126,22.247.0,17.190.0,34.129.0,40.109.0,27.156.0,49.134.0,49.172.0,33.94.0"}
P.entries["quest:3100"] = {n="简要的信件",s="“简单的信”是一份指引新手战士前往北郡修道院寻找训练师莱恩·贝舍尔的入门指令。它标志着他们正式军事训练的开始，并敦促他们帮助山谷中陷入困境的居民。",h="“简单的信”是一份指引新手战士前往北郡修道院寻找训练师莱恩·贝舍尔的入门指令。它标志着他们正式军事训练的开始，并敦促他们帮助山谷中陷入困境的居民。",kw={"艾尔文森林","白银之手骑士团","莱恩·贝舍尔","北郡修道院","北郡山谷","简单的信","战士训练师"},ang={["class:Warrior"]="莱恩·贝舍尔担任北郡修道院的驻地战士训练师，这封“简单的信”就是刚抵达的战士们开始军事训练的初始召集令。",["faction:Alliance"]="即使在白银之手保护的相对圣地之内，新兵们也会立即被要求去帮助陷入困境的联盟公民。",["race:Human"]="北郡修道院是人类冒险者踏入艾尔文森林的摇篮，当地的新兵会在这里得到最初的指引。"},sec={{t="战斗的召唤",b="“简单的信”是抵达北郡山谷的有志战士们的入门介绍。这封信指向北郡修道院的驻地战士训练师莱恩·贝舍尔，促使刚抵达的战士与他们的导师建立联系，熟悉周围的环境，并为军事生活的需求做好准备。"},{t="保卫山谷",b="尽管北郡修道院在白银之手骑士团的守卫下受到保护，但山谷平静的表象之下掩盖着更深层的麻烦。正如贝舍尔在收到信件后指出的那样，周围的居民面临着许多需要有能力的保卫者来解决的困境，这促使新兵们掌握武器，站出来保卫领土。"}},faq={{q="什么是简单的信？",a="“简单的信”是一封入门信函，战士在从狗头人营地返回后会得到它。它引导他们向当地的战士训练师莱恩·贝舍尔进行自我介绍，以开始正式的军事训练。",al={"什么是简单的信","简单的信任务","人类战士初始信件"}},{q="莱恩·贝舍尔是谁？",a="莱恩·贝舍尔是驻扎在北郡修道院的战士训练师。他指导新手战士掌握战斗技巧，欢迎带着命令或推荐信抵达山谷的新兵前来寻找他。",al={"莱恩·贝舍尔是谁","贝舍尔位置","北郡战士训练师在哪里"}},{q="我应该把简单的信交给谁？",a="这封信应直接交给莱恩·贝舍尔，他位于北郡山谷的北郡修道院内，周围是受神圣组织保护的隐蔽区域。",al={"简单的信交在哪里","简单的信上交","莱恩·贝舍尔位置"}},{q="白银之手骑士团在北郡扮演什么角色？",a="白银之手骑士团帮助守卫北郡山谷，保持修道院及其周边区域的相对安全，使新兵、农民和神职人员尽管面临日益增长的当地紧张局势，仍能履行职责。",al={"圣骑士在北郡做什么","北郡修道院白银之手","艾尔文森林圣骑士"}},{q="为什么当地居民需要帮助？",a="虽然修道院本身仍有相当的防御能力，但当地居民面临着不断的入侵和物资短缺。贝舍尔建议新来者探索周围的土地，并将他们的武力借给那些需要帮助的人。",al={"为什么贝舍尔要我帮助居民","北郡的问题","谁在北郡需要帮助"}},{q="我在递交信件后何时应该回到莱恩·贝舍尔身边？",a="莱恩·贝舍尔日夜都在修道院，随时准备在战士们获得战斗经验并需要进阶军事技能时为他们提供指导。",al={"我什么时候该去找莱恩·贝舍尔","北郡战士进阶训练","贝舍尔训练"}}},fp="13,241,14.355.0,19.380.0,26.249.0,21.213.0,37.176.0,63.220.0,49.217.0,66.154.0"}
P.entries["quest:3101"] = {n="圣洁信件",s="圣洁之信是针对抵达北郡山谷的圣光修行者所发布的引导信函。它指引持有者向位于北郡修道院的职业训练师报到，以开启他们的训练，并拥抱自己作为信仰象征的职责。",h="圣洁之信是针对抵达北郡山谷的圣光修行者所发布的引导信函。它指引持有者向位于北郡修道院的职业训练师报到，以开启他们的训练，并拥抱自己作为信仰象征的职责。",kw={"萨缪尔修士","圣洁之信","艾尔文森林","圣光","北郡","北郡修道院","圣骑士","训练师"},ang={["class:Paladin"]="作为圣光的使用者，圣骑士肩负着展示圣光美德的使命，并在北郡及更远的地方成为盟友希望的灯塔。",["faction:Alliance"]="圣光的代表们被期望以荣誉行事，维护联盟的道德立场和防御事业。",["race:Human"]="对于在北郡修道院开始服役的人类来说，这封信强调了他们在近期饱受试炼的王国中，作为荣誉象征行事的责任。"},sec={{t="神圣的召唤",b="圣洁之信标志着一位修行者在北郡山谷之旅的正式开始。这份文件旨在呼唤新抵达的圣光使用者，要求持有者前往北郡修道院寻找他们的训练师，以使他们的指导正规化，并承担起暴风城王国赋予他们的职责。"},{t="承载圣光",b="在呈交这封信时，修行者会被提醒其职业所承载的责任。圣光会在那些能够引导它的人身上显现，使他们成为盟友眼中希望的象征，同时也成为敌人显眼的目标。训练师强调，这种力量需要严明的纪律和对自身公共形象的自觉。"},{t="指导与纪律",b="除了精神上的义务，这封信还确立了师生之间持续的关系。当修行者在应对北郡面临的当地威胁时磨练自己的意志时，他们需要定期回到修道院，以解锁对战斗和神圣恩典的更深刻理解。"}},faq={{q="什么是圣洁之信？",a="圣洁之信是一封针对北郡山谷圣光修行者的引导信函。它指引持有者前往北郡修道院的职业训练师处，以确立他们的训练并提醒他们神圣的职责。",al={"什么是圣洁之信","圣洁之信任务"}},{q="圣洁之信从何而来？",a="当一位新晋圣骑士从狗头人营地返回后，北郡修道院的某人会递交这封信。信上盖有萨缪尔修士的印章，并指示圣骑士去见他。",al={"谁给予圣洁之信","谁寄出圣洁之信"}},{q="谁会收到圣洁之信？",a="这封信会被递交给萨缪尔修士，他是驻扎在艾尔文森林北郡修道院入口附近的圣骑士训练师。",al={"谁上交圣洁之信","谁阅读圣洁之信"}},{q="训练师在阅读信件后扮演什么角色？",a="训练师担任圣光之道的导师，在修行者于山谷中获得实际战斗经验的同时，指导他们掌握战斗技巧、防御性祝福和神圣法术。",al={"训练师教授什么","为什么要跟随训练师训练"}},{q="为什么信中提到要成为一个象征？",a="那些引导圣光的人被视为信仰和美德的鲜活典范。朋友和敌人都认可圣光的力量，这使得它的使用者成为显眼的人物，他们的行为会直接反映出信仰本身的形象。",al={"为什么我是象征","圣光象征"}},{q="这项训练在哪里进行？",a="北郡修道院坐落于艾尔文森林宁静的北部山谷中，它是信仰的避难所，也是暴风城王国保卫者的主要招募地。",al={"北郡修道院在哪里","我应该把信带到哪里"}}},fp="18,271,16.325.0,18.350.0,23.308.0,31.246.0,44.187.0,36.129.0,57.204.0,43.222.0,36.182.0"}
P.entries["quest:3102"] = {n="密文信件",s="加密的信件是一封发给北郡修道院中具有潜力的潜行者的秘密传唤，上面盖有Jorik Kerridan的徽记。它向新晋特工介绍了他们在僻静马厩中的训练师，并就如何在军情七处（SI:7）和迪菲亚潜行者这类组织的危险利益纠葛中生存下来提供了初步建议。",h="加密的信件是一封发给北郡修道院中具有潜力的潜行者的秘密传唤，上面盖有Jorik...",kw={"迪菲亚潜行者","加密的信件","jorik kerridan","北郡修道院","北郡山谷","潜行者训练师","军情七处"},ang={["class:Rogue"]="这份加密的传唤标志着年轻的潜行者对Jorik Kerridan及更广阔的地下世界的初步了解，并提供了关于如何在不失去独立性的前提下应对军情七处（SI:7）和迪菲亚潜行者等派系的初步建议。",["faction:Alliance"]="即使在北郡修道院虔诚的围墙之后，暴风城王国的影子特工们也在悄悄地为未来的冲突招募和训练有前途的新人。"},sec={{t="一份谨慎的传唤",b="在北郡修道院宁静虔诚的外表之下，秘密人才正被悄悄招募和磨练。在处理完日益严重的狗头人祸害后，具有潜力的潜行者新手会收到这封盖有Jorik Kerridan印章的加密的信件。为了避开牧师和圣骑士们好奇的目光，这封信被谨慎地寄出，指引收信人前往修道院后方僻静的马厩进行会面。"},{t="北郡的阴影",b="Jorik Kerridan之所以待在马厩里，正是因为那里安静且鲜有人注意。他欢迎那些不引人注目地到来的新人，并毫不拖延地向他们解释小偷和斥候在广阔世界中所面临的严酷现实。强大的组织——从暴风城的皇家情报机构军情七处（SI:7）到叛乱的迪菲亚潜行者——都在不断寻找潜行特工。Jorik建议新人将个人自主权置于首位，警告他们永远不要被强大的集团摆布，并提醒他们，聪明的潜行者始终掌握着主动权。"}},faq={{q="谁寄出了这封加密的信件？",a="这封信上盖有Jorik Kerridan的个人徽记，他是驻扎在北郡山谷的潜行者训练师。它被发送给那些从侦察附近狗头人营地归来的、具有潜力的新手。",al={"谁寄出了加密的信件","谁给了我加密的信件","谁写了这封加密的信件"}},{q="Jorik Kerridan在哪里？",a="Jorik Kerridan在北郡修道院后方僻静的马厩中保持着低调。他特意避开人们的视线，以免给自己的秘密工作带来不必要的关注。",al={"jorik在哪里","到哪里寻找jorik kerridan","jorik的位置"}},{q="加密的信件有什么目的？",a="这封信是为正在成长中的潜行者提供的谨慎邀请，让他们去见当地的训练师。由于潜行者依靠秘密行事，通信需要加密，以防止敏感的训练业务被修道院周围窥探的目光发现。",al={"为什么需要加密的信件","加密的信件是做什么的","为什么信件是加密的"}},{q="哪些组织在招募潜行者？",a="根据Jorik Kerridan的说法，艾泽拉斯各地的不同派系都觊觎着熟练潜行者的才能。这些派系包括冒险小队、暴风城的秘密情报部门军情七处（SI:7），甚至包括像迪菲亚潜行者这样在暴风城内寻找间谍的亡命之徒。",al={"谁需要潜行者","对潜行者感兴趣的派系","谁觊觎潜行者的技能"}},{q="Jorik Kerridan给了什么建议？",a="Jorik敦促你要保持自我，永远不要让强大的团体强迫你违背意愿行事。他提醒潜行者在游戏结束前掌握着主动权，强调了独立和谨慎的重要性。",al={"jorik的建议","jorik告诉你什么","潜行者建议jorik"}},{q="为什么Jorik Kerridan待在马厩里？",a="Jorik更喜欢北郡修道院后面僻静的马厩，因为那个地方环境很好，安静且几乎不会引起注意。秘密训练师和特工更喜欢在不被修道院的神职人员或卫兵发现的情况下会面。",al={"为什么躲在马厩里","为什么jorik在修道院后面","为什么马厩里很安静"}}},fp="16,163,18.319.0,21.362.0,30.131.0,32.121.0,44.149.0,50.163.0,37.142.0,43.191.0"}
P.entries["quest:3103"] = {n="神圣信件",s="神圣信件是由治安官玛克布莱德代表北郡修道院的常驻训练师女牧师安妮塔，发给极具潜力的年轻牧师的正式传唤。它标志着一位初出茅庐的牧师在动荡且脆弱的世界中，正式开始接受圣光的教义指导。",h="神圣信件是由治安官玛克布莱德代表北郡修道院的常驻训练师女牧师安妮塔，发给极具潜力的年轻牧师的正式传唤。它标志着一位初出茅庐的牧师在动荡且脆弱的世界中，正式开始接受圣光的教义指导。",kw={"艾尔文森林","神圣信件","圣光","治安官玛克布莱德","北郡修道院","牧师","女牧师安妮塔"},ang={["class:Priest"]="这个任务标志着你正式成为女牧师安妮塔门下的圣光信徒，并将你的神圣魔法视为治愈破碎世界的关键职责。",["race:Human"]="北郡修道院长期以来一直是暴风城王国的信仰与休养的圣地，尽管艾尔文森林周围困难重重，但它仍在传承着自己的传统。"},sec={{t="布道召唤",b="在证明了自己的勇气，扫荡了北郡周围的狗头人营地后，见习牧师会收到一封盖有女牧师安妮塔神圣印章的信件。这封信由治安官玛克布莱德转交，作为邀请他们进入修道院安静的大厅，开始深入学习圣光的凭证。"},{t="亟待拯救的世界",b="当把这封信呈交给女牧师安妮塔时，她会向这位新学徒强调这个王国的严峻形势。燃烧军团残留的威胁在艾泽拉斯投下了长长的阴影，而各个大陆也在新伤与动荡中苦苦挣扎。在她看来，披上牧师的斗篷不仅仅是一种学术上的追求，更是一种为受苦的世界带来治愈与慰藉的迫切道德责任。"}},faq={{q="什么是神圣信件？",a="这是一封盖有女牧师安妮塔徽章的密封信件，由治安官玛克布莱德在北郡山谷转交给刚抵达的人类牧师。它指引新手前往北郡修道院进行正式的训练。",al={"神圣信件","牧师北郡介绍任务","安妮塔的信"}},{q="是谁寄出了神圣信件？",a="女牧师安妮塔，这位驻扎在北郡修道院内的牧师训练师，亲自起草并封存了这封信，要求治安官玛克布莱德在见习牧师侦察完狗头人出没的区域归来后交给他们。",al={"谁写了神圣信件","谁寄出了信"}},{q="女牧师安妮塔为什么要召唤新牧师？",a="安妮塔认可了新手对圣光的感召，并寻求指导他们的训练。随着燃烧军团的残党等危险在世界各地徘徊，她强调迫切需要训练有素的治疗者和引导者。",al={"安妮塔为什么需要我","信件的目的"}},{q="在哪里可以找到女牧师安妮塔？",a="她居住在北郡修道院的主大厅内，随时准备训练人类牧师，帮助他们掌握最初的祈祷和仪式。",al={"安妮塔在哪里","女牧师安妮塔位置"}},{q="将信件交给女牧师安妮塔后会发生什么？",a="在阅读信件并问候安妮塔后，她会接受玩家作为她的学生，传授基础知识，并邀请他们在经验增长后回来接受更多的训练。",al={"神圣信件之后的任务","神圣信件后面是什么"}},{q="为什么在北郡会提到燃烧军团？",a="虽然第三次战争已经结束，但军团的恶魔残党仍然困扰着艾泽拉斯。女牧师安妮塔提到这种全球性的威胁，是为了强调任何离开山谷的冒险者所面临的更广泛的危险。",al={"北郡的燃烧军团","为什么安妮塔谈论恶魔"}}},fp="15,209,22.225.0,15.307.0,28.212.0,30.191.0,45.214.0,36.128.0,61.169.0,50.184.0"}
P.entries["quest:3104"] = {n="雕文信件",s="雕文信件是一份正式的传唤函，由治安官玛克布莱德在北郡山谷内送达给初出茅庐的人类法师。这封信件由凯尔登·布雷门加盖奥术印记，召唤有前途的施法者前往北郡修道院，开始他们正式的奥术技艺教导。",h="雕文信件是一份正式的传唤函，由治安官玛克布莱德在北郡山谷内送达给初出茅庐的人类法师。这封信件由凯尔登·布雷门加盖奥术印记，召唤有前途的施法者前往北郡修道院，开始他们正式的奥术技艺教导。",kw={"奥术","艾尔文森林","雕文信件","凯尔登·布雷门","法师","治安官玛克布莱德","北郡修道院"},ang={["class:Mage"]="这个任务标志着你正式从一个未经训练的璞玉，转变为凯尔登·布雷门门下暴风城奥术技艺的受认可学徒。",["race:Human"]="北郡的人类法师传承着一段历史，这段历史可以追溯到最初的达拉然人类奥术师和肯瑞托，并将奥术力量带入暴风城王国。"},sec={{t="奥术的召唤",b="一旦有抱负的学徒通过协助治安官玛克布莱德对抗当地的害兽证明了自己的能力，这位驻军指挥官就会递给他们一封带有奥术符文的信件。这封信直接来自北郡的常驻法师训练师凯尔登·布雷门，他负责监视来到修道院的新兵，寻找拥有魔法纪律和天赋的迹象。"},{t="巫术的重担",b="北郡修道院在历史上一直是圣光的庇护所，但暴风城目前面临的持续危险需要各个领域的修行者。响应信件的召唤会将学徒带到楼上，去见凯尔登·布雷门。导师并没有给予轻易的赞美，而是发出了严厉的警告：掌握奥术力量需要挑战自然的极限，这会招致普通民众的深切敬畏与根深蒂固的恐惧。"}},faq={{q="谁递送了雕文信件？",a="一旦新抵达的法师帮助清理了附近的狗头人害兽，治安官玛克布莱德就会在北郡修道院外将信交给他们。",al={"谁给予雕文信件","雕文信件任务发布者"}},{q="谁写了雕文信件？",a="这封信是由北郡修道院上层房间里的常驻法师训练师凯尔登·布雷门撰写并封印的。",al={"雕文信件作者","谁寄出了雕文信件"}},{q="我在哪里能找到凯尔登·布雷门？",a="进入治安官玛克布莱德身后的北郡修道院，走左边的走廊，上楼，朝后方的房间看去，就能找到等待教导的凯尔登。",al={"凯尔登·布雷门位置","凯尔登在哪里"}},{q="为什么法师训练师会待在修道院里？",a="虽然北郡修道院从本质上来说是一处圣洁的庇护所，但暴风城将山谷用作各领域防御者的初步训练基地，在牧师和治安官身边安排了奥术导师。",al={"为什么法师在北郡修道院","修道院里的法师训练师"}},{q="提交信件后会发生什么？",a="凯尔登·布雷门会收你为徒，欢迎你即便在面对危险时也决心掌控奥术的意志，并为你提供基础法术训练。",al={"雕文信件后续","雕文信件后续任务"}},{q="为什么凯尔登警告说法师会令人恐惧？",a="奥术魔法是一种不稳定且能扭曲现实的力量。凯尔登提醒学徒，追求至高无上的知识意味着要跨越普通民众感到极度不安的界限。",al={"为什么法师令人恐惧","凯尔登·布雷门对话"}}},fp="14,175,23.276.0,22.332.0,32.124.0,29.99.0,31.137.0,44.164.0,41.157.0,48.155.0"}
P.entries["quest:3105"] = {n="被污染的信件",s="“被污染的信件”是递交给在北郡山谷受训的人类术士新兵的一份隐秘召唤。这份书信由神秘的训练师杜希拉·拉萨雷托付给治安官玛克布莱德，旨在将新兵从修道院守卫窥探的目光中引开，开始他们关于邪能魔法的正式教导。",h="“被污染的信件”是递交给在北郡山谷受训的人类术士新兵的一份隐秘召唤。这份书信由神秘的训练师杜希拉·拉萨雷托付给治安官玛克布莱德，旨在将新兵从修道院守卫窥探的目光中引开，开始他们关于邪能魔法的正式教导。",kw={"堕落","杜希拉·拉萨雷","艾尔文森林","治安官玛克布莱德","北郡修道院","被污染的信件","扭曲虚空","术士"},ang={["class:Warlock"]="此任务代表了北郡人类术士的正式招募，确立了在躲避审视的守卫与掌握危险的虚空魔法之间微妙的平衡。",["race:Human"]="人类文化主要尊崇圣光和肯瑞托纪律严明的奥术，这迫使人类术士只能在北郡这样定居点的安静边缘练习他们的召唤术。"},sec={{t="一份隐秘的召唤",b="当牧师和圣骑士在北郡修道院的神圣大厅里公开研习时，黑暗魔法的践行者却必须谨小慎微。在证明了自己对抗当地狗头人威胁的能力后，术士新兵会收到一封由治安官玛克布莱德转交的信件。信件上盖着杜希拉·拉萨雷的徽章，指示这位年轻的施法者在从事其他任务之前，直接前往她在修道院主墙外的隐蔽哨位报到。"},{t="诱惑与野心",b="见到杜希拉后，你便会明白在暴风城守卫的监视下走上术士之路是多么如履薄冰，她将这些守卫斥为“可悲的凡人”。杜希拉对她的学生提出了一个直率的警告：从扭曲虚空汲取力量并与恶魔交流，时刻伴随着堕落的风险。虽然她建议学生要保持耐心、审慎和坚定不移的自控力，以避免沦为他们所操纵的黑暗能量的牺牲品，但她也明确表示，这种谨慎绝不应磨灭一个人内心熊熊燃烧的野心。"}},faq={{q="是谁寄出了“被污染的信件”？",a="这封信是由北郡修道院外居住的当地术士训练师杜希拉·拉萨雷亲笔书写并封缄的。她要求治安官玛克布莱德在你清除附近的狗头人营地回来后，立即将其交给你。",al={"谁写了被污染的信件","被污染的信件作者","谁发送了被污染的信件"}},{q="为什么治安官玛克布莱德会传递术士的信件？",a="治安官玛克布莱德在山谷中仅仅扮演着信使的角色，为有前途的新兵传递信息。虽然他知道这封信带有杜希拉的印记，并坚持认为其具有优先权，但他首要关注的仍然是北郡的防御和管理，而非监管其守卫的具体魔法实践。",al={"为什么玛克布莱德有这封信","玛克布莱德知道信的内容吗","玛克布莱德 术士信件"}},{q="我在哪里可以找到杜希拉·拉萨雷？",a="杜希拉·拉萨雷站在北郡修道院的正门外，靠近外墙和帐篷，远离里面的神职人员。",al={"杜希拉位置","杜希拉·拉萨雷在哪里","找到杜希拉"}},{q="为什么北郡修道院允许术士存在？",a="联盟领地内的术士处于极度的猜疑中，行事低调。在北郡，杜希拉将她的训练安排在圣所之外，流连于户外，这样她既能指导新兵，又能避免与北郡神职人员和圣骑士组成的圣教军发生直接冲突。",al={"北郡的术士","北郡允许邪能魔法吗","为什么允许术士"}},{q="收到信后，杜希拉教授了什么课程？",a="杜希拉警告说，缺乏纪律的修行者在汲取扭曲虚空的力量时会招致堕落。她建议修行者保持严格的自控和审慎，同时也强调对堕落的恐惧绝不能压垮术士个人的野心。",al={"杜希拉的建议","杜希拉说了什么","被污染的信件课程"}},{q="递交“被污染的信件”之后会发生什么？",a="与杜希拉交谈将结束这次召唤，并使她成为你的训练师；她会邀请你随着力量的增长回来学习更多术士之道。",al={"被污染的信件后续任务","被污染的信件后续"}}},fp="14,186,18.364.0,23.336.0,29.182.0,50.249.0,35.137.0,45.240.0,58.189.0,47.162.0"}
P.entries["quest:3106"] = {n="简易符文",s="“简易符文”是寒脊山谷中矮人战士新手的一项入门任务。该任务由斯登·粗臂代表战士训练师斯兰·库尔曼传达，引导刚入伍的新兵进入安威玛尔开始他们的军事训练。",h="“简易符文”是寒脊山谷中矮人战士新手的一项入门任务。该任务由斯登·粗臂代表战士训练师斯兰·库尔曼传达，引导刚入伍的新兵进入安威玛尔开始他们的军事训练。",kw={"安威玛尔","寒脊山谷","丹莫罗","铁炉堡","简易符文","斯登·粗臂","斯兰·库尔曼","穴居人","战士"},ang={["class:Warrior"]="这道符文标志着战士正式踏入军事纪律，指引着新的利刃和钝器直接前往安威玛尔寻找斯兰·库尔曼。",["faction:Alliance"]="寒脊山谷是保卫联盟南方卡兹莫丹前线的山地部队的最初训练场。",["race:Dwarf"]="斯兰·库尔曼对教导矮人新兵如何用传统的坚韧进行战斗感到无比自豪，在这个瞬息万变的世界里，他将他们的文化锚定在钢铁和铁器之中。",["race:Gnome"]="由于诺莫瑞根被穴居人和辐射摧毁，从寒脊山谷起步的侏儒战士必须与矮人导师并肩学习前线作战，才能在流亡中生存下来。"},sec={{t="铁砧的召唤",b="当年轻的新兵们在寒脊山谷周边清理害虫并证明自己的勇气时，老练的侦察兵们也在密切留意着有前途的战士。斯登·粗臂将一块刻有铭文的石头——即简易符文——交给了他们，这块石头正是斯兰·库尔曼托付给他的。这道符文召唤着怀揣战斗希望的新兵们走出雪谷小径，进入温暖的安威玛尔锻炉大厅，正式宣誓投身于战士之道。"},{t="变动中的丹莫罗",b="向斯兰报到，能让人立刻窥见现代丹莫罗所面临的严峻现实。这位老练的训练师坦率地谈到了王国不断变化的局势：诺莫瑞根在毁灭性的爆炸中化为废墟，流离失所的侏儒们正在寻求庇护；同胞矮人开始运用外来的奥术，或是信奉人类的圣光；而潜伏在地下的穴居人则不断抓挠着山脉边境，威胁始终存在。在斯兰眼中，坚实的军事纪律依然是抵御这一切所需的基石。"}},faq={{q="什么是简易符文？",a="简易符文是一块刻有铭文的小石板，由斯登·粗臂代表斯兰·库尔曼传达。它作为一份官方的邀请和指示，让新战士进入室内接受专业训练。",al={"简易符文物品","符文的作用","简易符文背景故事"}},{q="斯兰·库尔曼是谁？",a="斯兰·库尔曼是驻扎在寒脊山谷安威玛尔内的常驻战士训练师。他负责指导矮人和侏儒战士新手，教导他们近战、纪律和矮人坚韧精神的基础知识。",al={"谁是斯兰","斯兰·库尔曼背景故事","寒脊山谷战士训练师"}},{q="为什么侏儒会住在丹莫罗和铁炉堡？",a="侏儒们最近被迫撤离了他们的地下科技奇迹——诺莫瑞根，因为他们绝望地引爆了灾难性的辐射炸弹以击退地下穴居人的入侵。幸存者们翻过山岭，前往铁炉堡向他们的矮人盟友寻求庇护。",al={"为什么这里有侏儒","铁炉堡的侏儒","诺莫瑞根难民"}},{q="为什么斯兰会提到穴居人？",a="穴居人是原始而凶残的生物，它们最近被深埋地下的东西惊动，从而突破了寒脊山谷和丹莫罗的地表洞穴。它们对当地定居点和贸易路线构成了直接威胁，需要安威玛尔的守卫者们保持武装警惕。",al={"穴居人威胁","穴居人为什么会出现","寒脊山谷穴居人"}},{q="斯兰提到的矮人信奉圣光是什么意思？",a="传统上，矮人一直恪守祖辈的山地传统，但最近，由于与洛丹伦和暴风城等人类王国的紧密结盟，一些矮人开始信仰圣光，并训练出了自己的圣骑士和牧师。",al={"矮人与圣光","矮人圣骑士背景","矮人牧师"}},{q="我该把简易符文交给谁？",a="这块符文要直接交给斯兰·库尔曼，他就在寒脊山谷的小径尽头，位于安威玛尔大堡垒厅内的训练场边。",al={"简易符文交接地点","斯兰·库尔曼在哪","寻找斯兰"}}},fp="11,159,22.283.0,21.368.0,24.123.0,21.160.0,50.192.0,30.242.0,62.154.0,32.129.0"}
P.entries["quest:3107"] = {n="神圣符文",s="神圣符文是递交给寒脊山谷中新手矮人圣骑士的一份入门召唤书。它由斯登·粗臂代表布罗莫斯·格鲁诺尔转交，标志着一名新兵正式加入白银之手骑士团。",h="神圣符文是递交给寒脊山谷中新手矮人圣骑士的一份入门召唤书。它由斯登·粗臂代表布罗莫斯·格鲁诺尔转交，标志着一名新兵正式加入白银之手骑士团。",kw={"安威玛尔","布罗莫斯·格鲁诺尔","寒脊山谷","神圣符文","圣光","圣骑士训练师","白银之手","斯登·粗臂"},ang={["class:Paladin"]="这枚符文标志着你迈入白银之手骑士团的第一步，确立了你引导圣光以保卫铁炉堡的职责。",["race:Dwarf"]="矮人圣骑士将传统的矮人刚毅与人类传授的神学相结合，为圣光的教义带来了坚定的决心。"},sec={{t="安威玛尔的召唤",b="当新手冒险者在寒脊山谷清理穴居人和狼群时，当地的领袖们会密切关注那些展现出神圣武艺天赋的人。斯登·粗臂将这枚刻有符文的物品交给年轻的圣骑士，指示他们前往安威玛尔温暖的室内寻找布罗莫斯·格鲁诺尔。它既是一份邀请，也是一份正式通知，意味着未经雕琢的潜力现在必须通过纪律来磨砺。"},{t="矮人与圣光",b="虽然白银之手骑士团起源于洛丹伦的人类，但铁炉堡的矮人们却以狂热的虔诚拥抱了圣光的哲学。布罗莫斯·格鲁诺尔欢迎新兵加入兄弟会，提醒他们矮人圣骑士现在也肩负着保卫艾泽拉斯的神圣职责。基于牺牲、传统和武德，该组织要求新兵同样地拿起战锤与信仰。"}},faq={{q="什么是神圣符文？",a="这是一枚递交给寒脊山谷中新手矮人圣骑士的刻印信物，指示他们前往安威玛尔内部向布罗莫斯·格鲁诺尔报到，接受正式训练。",al={"神圣符文物品","符文有什么用","寒脊山谷圣骑士符文"}},{q="布罗莫斯·格鲁诺尔是谁？",a="布罗莫斯·格鲁诺尔是驻扎在安威玛尔的圣骑士训练师。他负责指导白银之手骑士团的新任矮人成员，并为他们应对威胁丹莫罗的危险做好准备。",al={"布罗莫斯是谁","安威玛尔圣骑士训练师","布罗莫斯·格鲁诺尔背景故事"}},{q="为什么矮人会成为白银之手骑士团的一员？",a="在第二次战争及其后的一段时间里，人类牧师和圣骑士将圣光的教义引入了铁炉堡的矮人之中。矮人们深切地尊重该组织严明的纪律以及为保卫艾泽拉斯而勇于牺牲的精神。",al={"矮人圣骑士背景故事","为什么矮人会有圣骑士","白银之手矮人"}},{q="谁会给你神圣符文？",a="在你协助斯登·粗臂完成当地任务后，他会在安威玛尔外将符文交给你，并提到是布罗莫斯·格鲁诺尔要求递送此物的。",al={"在哪里获得符文","谁把符文交给你"}},{q="布罗莫斯·格鲁诺尔在哪里？",a="你可以在寒脊山谷安威玛尔的大厅里找到布罗莫斯·格鲁诺尔，他就站在其他职业导师旁边。",al={"布罗莫斯位置","布罗莫斯在哪里","寻找布罗莫斯·格鲁诺尔"}},{q="将符文交给布罗莫斯后会发生什么？",a="布罗莫斯会确认你已被白银之手骑士团接纳，并为你提供最初的正式战斗与圣光训练，随后会将你重新派往丹莫罗。",al={"what comes next","神圣符文之后"}}},fp="16,135,21.242.0,26.390.0,29.178.0,23.176.0,55.228.0,35.135.0,33.103.0,49.179.0"}
P.entries["quest:3108"] = {n="风蚀符文",s="风蚀符文是一封书面传唤信，发送给在寒脊山谷协助卫兵的新手矮人猎人。这块刻文石碑由斯登·粗臂转交，指引刚起步的追踪者前往安威玛尔寻找索加斯·格瑞姆森，以正式开始他们的战斗和荒野生存训练。",h="风蚀符文是一封书面传唤信，发送给在寒脊山谷协助卫兵的新手矮人猎人。这块刻文石碑由斯登·粗臂转交，指引刚起步的追踪者前往安威玛尔寻找索加斯·格瑞姆森，以正式开始他们的战斗和荒野生存训练。",kw={"安威玛尔","寒脊山谷","丹莫罗","矮人","风蚀符文","猎人","斯登·粗臂","索加斯·格瑞姆森"},ang={["class:Hunter"]="这枚符文开启了你在丹莫罗的猎人旅程，并将你引荐给索加斯·格瑞姆森，同时让你了解矮人追踪、武器保养和荒野生存的基础传统。",["race:Dwarf"]="将信息刻在坚硬的石头上反映了矮人长期以来对经久耐用工艺的崇敬，即便是对于日常的传唤和实地指令也是如此。"},sec={{t="石刻传唤",b="当有前途的矮人猎人在寒脊山谷协助斯登·粗臂应对周边的威胁时，他们会被交给一块被称为“风蚀符文”的刻文石板。矮人导师倾向于使用雕刻的符文来传达正式信件，而不是发送口头命令或简单的羊皮纸。符文指示接收者总结早期的工作，并前往安威玛尔室内接受关于狩猎之道的更深层指导。"},{t="丹莫罗猎人的传统",b="将符文呈交给索加斯·格瑞姆森标志着猎人正式步入正轨。索加斯强调，在卡兹莫丹进行登山和生存需要对严酷的环境保持深深的敬畏：在刺骨的积雪中辨识踪迹、维护武器和弹药，以及了解那些在山脊间游荡的野生野兽。这块风蚀的石头是猎人从一个带着枪的孤独流浪者成长为安威玛尔资深探路者学徒的第一步。"}},faq={{q="什么是风蚀符文？",a="这是一块交给寒脊山谷新手猎人的刻文石板，作为一种书面邀请，指引他们前往安威玛尔寻找索加斯·格瑞姆森进行正式训练。",al={"什么是风蚀符文","风蚀符文物品","符文含义"}},{q="谁发送了风蚀符文？",a="猎人训练师索加斯·格瑞姆森发送了它，但一旦你在安威玛尔外证明了你的基本能力，山地探险家斯登·粗臂会将其亲手交给你。",al={"谁给了我风蚀符文","风蚀符文发送者"}},{q="我应该把风蚀符文带到哪里？",a="你应该把它带给索加斯·格瑞姆森，他就在寒脊山谷的安威玛尔大厅内。",al={"我要去哪里","我该交给谁","索加斯位置"}},{q="为什么矮人使用符文而不是信件？",a="矮人文化非常重视石匠工艺、传统和经久耐用的手艺。将信件和神圣的指令刻在石质符文上，能确保它们比脆弱的羊皮纸更能抵御丹莫罗凛冽的寒风和恶劣的天气。",al={"为什么要用风蚀符文","矮人符文知识"}},{q="将符文交给索加斯·格瑞姆森后会发生什么？",a="索加斯会欢迎你加入矮人追踪者的行列，向你解释在冰封山脊生存、维护装备以及尊重野兽的核心原则，随后为你提供基础猎人技巧的训练。",al={"索加斯教什么","上交风蚀符文"}},{q="任何职业都可以获得风蚀符文吗？",a="不可以。风蚀符文是专门发给在寒脊山谷开始冒险的矮人猎人的。其他职业会收到各自独特的征募信物，指引他们前往安威玛尔寻找各自的导师。",al={"风蚀符文是猎人专有的吗","战士能拿到风蚀符文吗"}}},fp="11,154,18.308.0,35.434.0,24.154.0,26.140.0,32.96.0,44.197.0,58.201.0,38.174.0"}
P.entries["quest:3109"] = {n="密文符文",s="密文符文是一封发给在寒脊山谷迈出第一步的潜行者新人的加密信件。通过斯登·粗臂之手传递，这则刻写的信息指引那些有潜力的“暗影”前往安威玛尔，向潜行者训练师索姆·哈格林报到。",h="密文符文是一封发给在寒脊山谷迈出第一步的潜行者新人的加密信件。通过斯登·粗臂之手传递，这则刻写的信息指引那些有潜力的“暗影”前往安威玛尔，向潜行者训练师索姆·哈格林报到。",kw={"安威玛尔","寒脊山谷","丹莫罗","密文符文","诺莫瑞根","潜行者训练师","索姆·哈格林","斯登·粗臂"},ang={["class:Rogue"]="这枚符文标志着你与丹莫罗潜行者网络的第一次正式接触，它将引导你找到索姆·哈格林，开始磨练你的潜行、格斗技巧和生存之道。",["race:Dwarf"]="索姆欢迎铁炉堡氏族的矮人同胞进入暗影，并指出在丹莫罗，没有什么比一把冰冷的利刃和黑暗更能让特工活下去了。",["race:Gnome"]="索姆敦促他的学生们在诺莫瑞根痛失家园后，向栖身于寒脊山谷的侏儒们展现同胞情谊。"},sec={{t="加密信息",b="当潜行者们在寒脊山谷的雪径上协助斯登·粗臂时，敏锐的他们会收到一块奇异的刻文石。斯登承认这块石头是有人交给他代转的，并怀疑它直接来自索姆·哈格林。索姆没有在庭院里大声呼喊招募潜在的侦察兵和恶棍，而是利用密文符文来考验新手的谨慎程度，并借此将他们召入室内。"},{t="安威玛尔的屋檐下",b="在安威玛尔内部，索姆·哈格林欢迎新来的特工加入这行。他提出教授能让特工保住性命并赚得盆满钵满的战术、打击技和精妙技巧。除了磨砺匕首外，索姆还提醒矮人潜行者要关照他们流离失所的侏儒盟友，这些侏儒仍在从诺莫瑞根的灾难性陷落中恢复。"}},faq={{q="谁寄出了密文符文？",a="这枚符文由安威玛尔大厅内的潜行者训练师索姆·哈格林所写。他让斯登·粗臂将其悄悄传递给雪地里有潜力的新兵。",al={"谁写了密文符文","密文符文发送者","谁给了斯登符文"}},{q="我去哪里找索姆·哈格林？",a="索姆·哈格林位于安威玛尔的主厅内，那是坐落在丹莫罗寒脊山谷中心的一座石制堡垒。",al={"索姆在哪里","索姆·哈格林位置","找到索姆"}},{q="这枚符文有什么用？",a="它作为给潜行者新手的介绍性传唤，鼓励他们解读信息、向职业训练师报到，并开始学习高级战斗技巧和生存战术。",al={"密文符文的作用","密文符文的目的","为什么要用密文符文"}},{q="为什么索姆会提到侏儒？",a="由于诺莫瑞根最近遭遇灾难而陷落，侏儒难民与矮人们一同分享着寒脊山谷和安威玛尔。索姆提醒他的学生们，侏儒们经历了一段艰难的时光，需要支持以安顿在这个临时住所中。",al={"为什么要帮助侏儒","索姆对诺莫瑞根的评价"}},{q="谁把符文交给玩家？",a="在潜行者冒险者们帮完寒脊山谷当地的初步任务后，斯登·粗臂会将这块石头交给他们。",al={"谁开启密文符文任务","密文符文任务给予者"}},{q="其他职业能收到这枚符文吗？",a="不能。密文符文仅供在寒脊山谷开启旅程的潜行者新手使用。",al={"此任务是否仅限潜行者","战士能获得密文符文吗"}}},fp="14,117,17.248.0,24.298.0,29.149.0,29.111.0,33.147.0,33.202.0,33.117.0,36.81.0"}
P.entries["quest:311"] = {n="向马莱斯回报",s="“回到马莱斯身边”是丹莫罗一场激烈的酿酒纷争的恶作剧式终章。在潜入卡拉诺斯的地窖并换上一桶马莱斯的烈性“烫喉酒”后，冒险者带着一大桶雷霆麦酒回到烈酒村，作为无可辩驳的证据。",h="“回到马莱斯身边”是丹莫罗一场激烈的酿酒纷争的恶作剧式终章。在潜入卡拉诺斯的地窖并换上一桶马莱斯的烈性“烫喉酒”后，冒险者带着一大桶雷霆麦酒回到烈酒村，作为无可辩驳的证据。",kw={"烈酒村","丹莫罗","卡拉诺斯","马莱斯·麦酒","烫喉酒","雷霆麦酒","雷酒酿制厂"},ang={["class:Rogue"]="潜入守卫森严的地窖来调换违禁酒桶，这在冰雪覆盖的山丘上是一场关于潜行和手法的小小考验。",["race:Dwarf"]="矮人文化将酿酒视为一种艺术形式和荣誉竞赛，这使得地窖里的小摩擦也成为了当地极具重要性的自尊心之战。"},sec={{t="破坏的战利品",b="当涉及到麦酒时，矮人之间的竞争很少会通过外交手段解决。居住在烈酒村的马莱斯·麦酒对卡拉诺斯的酿酒师们怀有强烈的竞争怨恨，而后者正是著名的雷霆麦酒的创造者。在将她那劲头十足的“烫喉酒”悄悄混入雷酒酿制厂的地窖后，马莱斯要求得到行动成功的证据。从他们眼皮底下偷走一桶真正的雷霆麦酒，既是战利品，也是一种筹码。"},{t="平息苦涩的酿造之争",b="将沉重的酒桶运回白雪皑皑的山脊，回到烈酒村，这起恶作剧便宣告完成。马莱斯对计划的成功感到非常激动，她兴高采烈地陶醉于自己耍弄了卡拉诺斯的守卫和地窖管理员的成就感中。虽然表面上这只是个无伤大雅的玩笑，但这起事件巩固了丹莫罗各地不同的矮人家族对自己招牌配方所倾注的那份激烈且不妥协的自豪感。"}},faq={{q="这个任务的目的是什么？",a="你必须将偷来的雷霆麦酒桶送回烈酒村交给马莱斯·麦酒，以证明你成功地将她的“烫喉酒”放入了卡拉诺斯的地窖中。",al={"我该做什么","回到马莱斯身边任务目标","上交酒桶"}},{q="马莱斯·麦酒是谁？",a="马莱斯是一位居住在烈酒村的矮人酿酒师。她对家族的烈性酒配方引以为傲，并与卡拉诺斯的雷酒酿制厂酿酒师们有着小小的竞争关系。",al={"马莱斯是谁","马莱斯背景故事","麦酒家族"}},{q="酒桶是从哪里拿来的？",a="在将马莱斯的“烫喉酒”混入他们的库存后，酒桶直接取自卡拉诺斯雷酒酿制厂内的地窖仓库。",al={"酒桶从哪儿来","卡拉诺斯地窖","雷霆麦酒位置"}},{q="烈酒村在哪里？",a="烈酒村坐落在丹莫罗西部涌冰湖的冰冻湖畔，位于卡拉诺斯的西北方向。",al={"烈酒村位置","烈酒村在哪","如何找到马莱斯"}},{q="为什么马莱斯与卡拉诺斯不和？",a="矮人酿酒大师们在配方上竞争极其激烈。马莱斯想要证明她自己的配方——“烫喉酒”，能够胜过或羞辱雷酒酿制厂生产的著名雷霆麦酒。",al={"为何竞争","马莱斯对雷酒酿制厂","酿酒纷争"}},{q="马莱斯如何处理这桶酒？",a="这桶酒主要是作为证明在卡拉诺斯守卫的眼皮底下成功掉包的证据，尽管马莱斯毫无疑问会很高兴能留住她对手的存货。",al={"为什么要偷雷霆麦酒","麦酒会怎样"}}},fp="17,144,22.153.0,21.211.0,34.143.0,26.145.0,33.122.0,26.103.0,37.166.0,37.125.0"}
P.entries["quest:3110"] = {n="神圣符文",s="神圣符文是寒脊山谷中矮人牧师新手的入门任务。斯登·粗臂会递交一枚来自牧师训练师布兰斯托克·卡德尔的刻文符文，召唤安威玛尔内的新手去加深他们与圣光的联系。",h="神圣符文是寒脊山谷中矮人牧师新手的入门任务。斯登·粗臂会递交一枚来自牧师训练师布兰斯托克·卡德尔的刻文符文，召唤安威玛尔内的新手去加深他们与圣光的联系。",kw={"安威玛尔","布兰斯托克·卡德尔","寒脊山谷","丹莫罗","矮人牧师","神圣符文","斯登·粗臂"},ang={["class:Priest"]="这枚符文标志着你作为丹莫罗圣光仆从的正式身份，指引你去寻找布兰斯托克·卡德尔学习你最初的法术。",["race:Dwarf"]="矮人牧师将对圣光的虔诚信仰与矮人特有的坚毅融合在一起，对于在抵御穴居人入侵时守住寒脊山谷至关重要。"},sec={{t="布道的召唤",b="在协助斯登·粗臂清理安威玛尔外围迫在眉睫的威胁时，一位新来的牧师引起了该定居点精神导师的注意。布兰斯托克·卡德尔将一枚刻有祷言和指引的神圣符文托付给斯登，指引这位年轻的冒险者走进安威玛尔坚固的大厅，正式开始他们的神圣修行。"},{t="寒脊山的守卫者",b="虽然矮人文化通常强调武勇和重甲，但圣光依然是铁炉堡社会的基石。在寒脊山谷，神圣施法者与战士和猎人并肩作战，在保护聚居地免受极具侵略性的穴居人入侵和在雪堆中潜行的危险野生动物威胁方面起着至关重要的作用。"}},faq={{q="什么是神圣符文？",a="这是一枚由斯登·粗臂代表布兰斯托克·卡德尔提供的神职符文。阅读它既是基础祷言的入门，也鼓励年轻的牧师去寻求正式的训练。",al={"什么是神圣符文","符文用途"}},{q="布兰斯托克·卡德尔是谁？",a="布兰斯托克·卡德尔是驻扎在安威玛尔内的矮人牧师训练师。他以冷幽默和坚定的信仰而闻名，负责指导初出茅庐的侍僧，并教授他们基础的神圣法术以协助寒脊山谷的防御。",al={"布兰斯托克","寒脊山谷牧师训练师"}},{q="我在哪里能找到布兰斯托克·卡德尔？",a="他位于丹莫罗寒脊山谷中心空地的安威玛尔主石屋之内。",al={"布兰斯托克位置","布兰斯托克在哪"}},{q="为什么矮人在寒脊山谷需要牧师？",a="穴居人已经占领了山谷的部分地区，当地守卫依靠圣光信徒的治疗能力和神圣打击来维持防线并治疗伤员。",al={"为什么需要矮人牧师","安威玛尔的牧师"}},{q="任何职业都能接受这个任务吗？",a="不能。神圣符文是专门提供给在寒脊山谷开始旅程的年轻矮人牧师的。",al={"谁能获得神圣符文","这个任务是牧师专属吗"}},{q="谁将符文交给玩家？",a="斯登·粗臂，一位在旅店外监督试炼的安威玛尔山地巡逻队员，在你协助他进行初步的山谷防御后会将符文交给你。",al={"谁发布神圣符文任务","斯登·粗臂的角色"}}},fp="13,225,22.306.0,22.269.0,26.168.0,25.186.0,34.117.0,48.148.0,30.99.0,36.160.0"}
P.entries["quest:3112"] = {n="简易备忘录",s="《简易备忘录》是一封递交给在寒脊山谷起步的侏儒战士新手们的信函。它由外面的斯登·粗臂转交，指引新受训的战士前往安威玛尔拜访斯兰·库尔曼，后者承诺将帮助他们为收复诺莫瑞根做好准备。",h="《简易备忘录》是一封递交给在寒脊山谷起步的侏儒战士新手们的信函。它由外面的斯登·粗臂转交，指引新受训的战士前往安威玛尔拜访斯兰·库尔曼，后者承诺将帮助他们为收复诺莫瑞根做好准备。",kw={"安威玛尔","寒脊山谷","丹莫罗","诺莫瑞根","简易备忘录","斯登·粗臂","斯兰·库尔曼","战士训练师"},ang={["class:Warrior"]="这封信正式开启了侏儒战士的战斗教育，让他们与铁炉堡的资深武器大师建立了联系。",["race:Dwarf"]="像斯兰·库尔曼这样的矮人导师将侏儒的苦难视为与他们自己古老的纷争同等重要，展现了与这些流离失所的盟友深厚的团结友谊。",["race:Gnome"]="这份备忘录凸显了侏儒从诺莫瑞根流亡的现状，以及他们培养能够收复那座充满辐射的城市的士兵的坚定决心。"},sec={{t="前往安威玛尔的召集令",b="在为登山队员斯登·粗臂清除寒脊山谷内扰乱治安的穴居人和野猪时，一位年轻的侏儒战士收到了塞进这名矮人手中的简短口信。经验丰富的训练师斯兰·库尔曼看中了这名难民新兵的潜力，利用这份备忘录召集这名新来者前往安威玛尔的中央大厅，开始正式的武技训练。"},{t="团结的誓言",b="虽然矮人训练师偶尔会拿侏儒战士矮小的身材开玩笑，但斯兰·库尔曼非常严肃地对待他们的抗争。出于对诺莫瑞根陷落的同情，斯兰将侏儒的苦难比作铁炉堡落入黑铁氏族之手时矮人们的感受。为了信守诺言，他发誓要指导这些流亡战士学习战术，直到他们准备好收复家园。"}},faq={{q="什么是《简易备忘录》？",a="这是一张由斯登·粗臂在寒脊山谷递交给侏儒战士新手的介绍信。信中指示战士前往安威玛尔的大厅寻找战士训练师斯兰·库尔曼。",al={"简易备忘录","什么是这份便条","备忘录任务"}},{q="谁寄出的备忘录？",a="它来自驻扎在安威玛尔的当地矮人战士训练师斯兰·库尔曼。他让斯登·粗臂将其转交给那些正在协助登山队员的有前途的战士。",al={"谁写的备忘录","谁寄出的简易备忘录"}},{q="斯兰·库尔曼为什么要训练侏儒战士？",a="斯兰承诺会帮助流亡的侏儒。他尊重他们的决心，并对他们的悲剧深表同情，将诺莫瑞根的陷落比作铁炉堡被黑铁氏族征服后的情景。",al={"为什么斯兰要训练侏儒","侏儒战士背景故事"}},{q="我在哪里可以找到斯兰·库尔曼？",a="斯兰·库尔曼站在位于丹莫罗寒脊山谷的核心定居点——安威玛尔的主大厅内。",al={"斯兰·库尔曼在哪里","斯兰·库尔曼位置"}},{q="斯登·粗臂是谁？",a="斯登·粗臂是一名驻扎在寒脊山谷安威玛尔外围的矮人登山队员，负责协调当地针对好斗的野猪和入侵的穴居人的防御工作。",al={"斯登·粗臂","斯登是谁"}},{q="为什么侏儒会在寒脊山谷开始冒险？",a="在诺莫瑞根悲剧性陷落并遭受辐射后，幸存的侏儒作为难民逃往了矮人领地。安威玛尔和铁炉堡敞开大门收留了他们，让他们在此重整旗鼓。",al={"为什么侏儒在这里","寒脊山谷的侏儒"}}},fp="17,208,21.219.0,22.310.0,30.143.0,25.104.0,44.182.0,30.90.0,21.149.0,44.191.0"}
P.entries["quest:3113"] = {n="密文备忘录",s="《密文备忘录》是一份发给抵达寒脊山谷的侏儒潜行者新手们的入门召唤令。这份伪装过的便条经由斯登·粗臂之手传递，悄悄指引新入行的特工们去安威玛尔内部寻找索姆·哈格林。",h="《密文备忘录》是一份发给抵达寒脊山谷的侏儒潜行者新手们的入门召唤令。这份伪装过的便条经由斯登·粗臂之手传递，悄悄指引新入行的特工们去安威玛尔内部寻找索姆·哈格林。",kw={"安威玛尔","寒脊山谷","丹莫罗","密文备忘录","诺莫瑞根","潜行者训练师","索姆·哈格林","斯登·粗臂"},ang={["class:Rogue"]="这项任务是侏儒潜行者的首次召集，向他们介绍了索姆·哈格林，以及在矮人领地内从事这种隐秘行当所必需的相互保护的信条。",["race:Dwarf"]="像斯登·粗臂这样的矮人山地巡逻队员促进了这些交流，展示了铁炉堡与寒脊山谷的流离失所的侏儒之间切实的合作。",["race:Gnome"]="这份备忘录突显了诺莫瑞根灾难后侏儒难民的困境，展示了幸存者们如何在作为矮人客人的同时团结一致。"},sec={{t="谨慎的引见",b="当侏儒新手们在寒脊山谷协助山地巡逻队员对抗当地的穴居人威胁时，斯登·粗臂会递给他们一张被秘密转交过来的折叠羊皮纸。这份便条表面上伪装成一份官方备忘录，实则是一封邀请函，邀请他们去见驻扎在安威玛尔内的潜行者训练师索姆·哈格林。"},{t="雪中的艰难处境",b="这条信息反映了诺莫瑞根突然陷落后，侏儒们所面临的不安现实。侏儒幸存者们被迫背井离乡，只能与身为东道主的矮人们在丹莫罗拥挤地共享住所。索姆·哈格林深知，一旦有物品失窃，潜行者就会引发怀疑，因此他提倡这一行当的从业者之间保持某种默契的团结，以确保共同生存。"}},faq={{q="《密文备忘录》是谁写的？",a="驻扎在安威玛尔内的潜行者训练师索姆·哈格林写下了这份便条。他将其伪装成来自上级的官方指令，以便斯登·粗臂能在不引起怀疑的情况下将其转交。",al={"谁发送了备忘录","谁写了便条","索姆的便条"}},{q="为什么备忘录要进行伪装？",a="潜行者更喜欢谨慎行事，特别是在安威玛尔这样繁忙的矮人据点中。索姆·哈格林保持低调，以免每当装备失踪时引发谣言或指控，他利用加密的问候语来专门联系同道的潜行者。",al={"为何伪装","为何加密"}},{q="这张便条揭示了丹莫罗的什么情况？",a="这段对话突显了诺莫瑞根失陷后，侏儒与矮人之间既有摩擦又保持团结的关系。尽管将两个种族的人口都塞进铁炉堡和丹莫罗会造成资源紧张，但索姆强调，从事暗影行当的人必须互相照应。",al={"侏儒与矮人的关系","丹莫罗的诺莫瑞根难民"}},{q="是谁将备忘录递交给玩家的？",a="在你协助斯登·粗臂完成寒脊山谷的任务后，他会把这份文件交给你，并认为这是索姆·哈格林发来供你训练使用的。",al={"斯登·粗臂的递送","谁递交便条"}},{q="索姆·哈格林担任什么角色？",a="索姆·哈格林是位于安威玛尔山中大厅内的潜行者训练师，负责指导新入行的潜行者进行战斗技巧和暗影天赋的训练。",al={"索姆·哈格林的角色","索姆做什么"}},{q="这个任务与诺莫瑞根的陷落有关吗？",a="是的。索姆直接提到了诺莫瑞根被占领一事，并强调尽管失去了机械家园，但流离失所的侏儒潜行者们可以依靠彼此的兄弟情谊来坚持下去。",al={"诺莫瑞根陷落传说","侏儒难民身份"}}},fp="20,105,23.219.0,28.268.0,35.174.0,32.218.0,61.226.0,42.129.0,34.120.0,44.165.0"}
P.entries["quest:3114"] = {n="雕文备忘录",s="《雕文备忘录》是一项引导寒脊山谷新手法师前往安威玛尔寻找当地训练师的入门任务。这份信件被托付给登山者斯登·粗臂，召唤初出茅庐的奥术修行者去寻找古怪的侏儒玛瑞克·斯托纳尔，以开启他们正式的法术研究。",h="《雕文备忘录》是一项引导寒脊山谷新手法师前往安威玛尔寻找当地训练师的入门任务。这份信件被托付给登山者斯登·粗臂，召唤初出茅庐的奥术修行者去寻找古怪的侏儒玛瑞克·斯托纳尔，以开启他们正式的法术研究。",kw={"安威玛尔","寒脊山谷","丹莫罗","雕文备忘录","法师训练师","玛瑞克·斯托纳尔","斯登·粗臂"},ang={["class:Mage"]="这份信件标志着你正式开启了在丹莫罗的奥术学徒生涯，直接与你的初始训练师建立了联系。",["faction:Alliance"]="斯登·粗臂与玛瑞克·斯托纳尔之间无缝的配合，体现了共享寒脊山谷的矮人和侏儒之间紧密的伙伴关系。",["race:Gnome"]="玛瑞克·斯托纳尔是诺莫瑞根陷落后避难于矮人领地并传授其传统技艺的几位侏儒专家之一。"},sec={{t="给新手法师的信",b="在协助登山者斯登·粗臂完成寒脊山谷的早期职责时，新抵达的法师会收到当地奥术权威的召唤。斯登收到了一份写给年轻施法者的备忘录，并将其转交给他们，建议他们花点时间阅读其中的内容，然后进入温暖的安威玛尔去见作者本人。"},{t="与玛瑞克·斯托纳尔一起训练",b="备忘录的作者是玛瑞克·斯托纳尔，一位驻扎在安威玛尔的侏儒法师训练师。玛瑞克没有让他的学生沉浸在枯燥的理论讲座中，而是提供了直接且切合实际的建议：远离严重的麻烦，攒钱用于训练和购买酒馆的饮料，并严格避免前往沦陷的诺莫瑞根，那里简直是一场放射性灾难。在设定了基本期望后，玛瑞克已准备好指导新人学习奥术。"}},faq={{q="谁负责递送这份备忘录？",a="斯登·粗臂，一名驻扎在寒脊山谷的联盟登山者，在你协助他完成初步任务后会将备忘录交给你。",al={"谁给出了雕文备忘录","斯登·粗臂任务"}},{q="玛瑞克·斯托纳尔是谁？",a="玛瑞克·斯托纳尔是一位居住在寒脊山谷安威玛尔的侏儒法师训练师。他指导年轻法师学习早期法术和一般的奥术安全知识。",al={"玛瑞克是谁","安威玛尔法师训练师"}},{q="我在哪里可以找到玛瑞克·斯托纳尔？",a="玛瑞克位于安威玛尔的主大厅内，这是位于丹莫罗寒脊山谷顶部的矮人中心哨站。",al={"玛瑞克·斯托纳尔位置","寒脊山谷的法师训练师在哪里"}},{q="为什么玛瑞克警告不要前往诺莫瑞根？",a="诺莫瑞根最近被穴居人占领，并因放射性气体的灾难性泄漏而受到污染，这对任何在丹莫罗游荡的冒险新手来说都极其危险。",al={"玛瑞克关于诺莫瑞根的警告","为什么远离诺莫瑞根"}},{q="哪些职业会接到这个任务？",a="此任务仅提供给在寒脊山谷开启旅程的年轻法师，旨在向他们介绍自己的职业训练师。",al={"谁会收到雕文备忘录","这是法师专属任务吗"}},{q="玛瑞克对他的学生有什么期望？",a="玛瑞克的要求很简单：他告诫学生要远离麻烦，存够银币来支付法术学习费用并请他喝麦芽酒，并且离诺莫瑞根远一点。",al={"玛瑞克的期望","训练师想要什么"}}},fp="18,125,26.173.0,29.272.0,29.112.0,23.160.0,33.103.0,49.145.0,31.105.0,42.133.0"}
P.entries["quest:3115"] = {n="被污染的备忘录",s="“被污染的备忘录”是为刚刚在寒脊山谷起步的侏儒术士新手提供的入门任务。这份信件通过斯登·粗臂悄悄传递，召唤初学者前往安威玛尔的阴影中会见阿拉玛尔·格里姆，后者宣扬通过黑暗力量实现自立，而不是依赖他们的矮人东道主。",h="“被污染的备忘录”是为刚刚在寒脊山谷起步的侏儒术士新手提供的入门任务。这份信件通过斯登·粗臂悄悄传递，召唤初学者前往安威玛尔的阴影中会见阿拉玛尔·格里姆，后者宣扬通过黑暗力量实现自立，而不是依赖他们的矮人东道主。",kw={"阿拉玛尔·格里姆","安威玛尔","寒脊山谷","丹莫罗","侏儒术士","诺莫瑞根流亡","斯登·粗臂","被污染的备忘录"},ang={["class:Warlock"]="这份公文标志着你正式踏入了术士这一职业，并将恶魔契约视为一种源于生存的实用主义，而非疯狂。",["race:Dwarf"]="矮人东道主明显带着厌恶和强烈的警惕，容忍这些黑暗修行者留在他们的屋檐下。",["race:Gnome"]="这份备忘录反映了某些流亡侏儒对于自己流离失所的状态以及对铁炉堡依赖的深层怨恨。"},sec={{t="谨慎的召唤",b="即使在寒脊山谷这样冰天雪地的哨站，修行黑暗艺术也遭到了深深的怀疑。在帮助斯登·粗臂处理当地威胁时，年轻的侏儒术士会收到一张被偷偷塞过来的纸条。斯登很不情愿地递出它，并说出了联盟领地对术士那脆弱的停战协定：“小心点……你们这类人在这些地方可不怎么受信任。”"},{t="流亡的侏儒怨恨",b="在回应了纸条后，术士会在安威玛尔的大厅内见到潜伏在那里的阿拉玛尔·格里姆。对于侏儒的困境，格里姆毫不避讳。在他看来，传统的工程学和普通魔法彻底辜负了诺莫瑞根，将他们的人民推向了灭绝的边缘，并使他们沦为二等难民，不得不依赖矮人的善意。格里姆没有去祈求圣光或寄希望于矮人的政治，而是敦促他的学生召唤并驾驭那些能够提供绝对服从的恶魔。"}},faq={{q="什么是“被污染的备忘录”？",a="这是一份由斯登·粗臂在寒脊山谷交给侏儒术士新手的书面信息。它指引新手去寻找安威玛尔的当地术士训练师——阿拉玛尔·格里姆。",al={"被污染的备忘录","术士字条丹莫罗","什么是备忘录"}},{q="为什么术士在寒脊山谷不受信任？",a="矮人及其联盟盟友非常推崇武艺荣耀和圣光等传统美德，他们认为恶魔学和暗影魔法本质上是腐化且危险的。侏儒术士在极大的社会怀疑阴影下行事。",al={"为什么矮人不信任术士","术士偏见安威玛尔"}},{q="阿拉玛尔·格里姆是谁？",a="阿拉玛尔·格里姆是一位居住在安威玛尔的侏儒术士训练师。他对诺莫瑞根的陷落以及不得不依赖矮人施舍而感到的屈辱感到愤恨，他教导年轻侏儒绑定恶魔仆从以确保自己的力量。",al={"阿拉玛尔·格里姆背景","谁是阿拉玛尔"}},{q="为什么格里姆批评常规魔法和技术？",a="格里姆认为，在诺莫瑞根的灾难中，传统的工程学和被主流接受的魔法流派辜负了侏儒，使他们依赖于那些优先考虑与人类关系而非夺回侏儒家园的矮人赞助者。",al={"格里姆对诺莫瑞根的看法","为什么选择黑暗魔法而非工程学"}},{q="矮人术士可以接到这个任务吗？",a="不能。在丹莫罗，只有侏儒才能修行术士之道，因此这个召唤仅限刚刚到达的侏儒修行者。",al={"矮人术士被污染的备忘录","矮人可以成为术士吗"}},{q="这个任务发生在哪里？",a="任务始于寒脊山谷的斯登·粗臂附近，终结于安威玛尔内部，这是位于丹莫罗西南部的、俯瞰山谷的中央堡垒。",al={"阿拉玛尔·格里姆在哪里","被污染的备忘录交付"}}},fp="18,142,18.270.0,27.373.0,31.177.0,48.178.0,20.213.0,53.233.0,38.118.0,33.147.0"}
P.entries["quest:3116"] = {n="简易符记",s="简易符记是发给幽影谷中有抱负的暗夜精灵战士的入门征召令。它由管理员伊尔萨莱恩代表训练师奥莉希亚传达，正式标志着新兵开始接受战斗训练，以保护尚显稚嫩的泰达希尔枝叶。",h="简易符记是发给幽影谷中有抱负的暗夜精灵战士的入门征召令。它由管理员伊尔萨莱恩代表训练师奥莉希亚传达，正式标志着新兵开始接受战斗训练，以保护尚显稚嫩的泰达希尔枝叶。",kw={"奥达希尔","奥莉希亚","菲拉斯","ilthalaine","幽影谷","简易符记","泰达希尔","战士"},ang={["class:Warrior"]="这个任务标志着你作为卡多雷战士的正式开始，将你作为你的第一位武器导师介绍给奥莉希亚。",["faction:Alliance"]="奥莉希亚的建议反映了暗夜精灵尽管历经数世纪的孤立，却依然努力欢迎其他联盟种族来到他们枝叶下的早期举措。",["race:NightElf"]="这枚符记直接反映了卡多雷周围发生的快速变化——从种植泰达希尔，到向外国盟友开放他们与世隔绝的家园。"},sec={{t="幽影谷的战斗号角",b="在证明了自己能够应对幽影谷中躁动的野生动物并掌握基本生存技能后，年轻的暗夜精灵战士会收到一枚经由管理员伊尔萨莱恩转交的刻印符记。这枚代币是奥莉希亚发出的正式请求，她是驻扎在奥达希尔的当地战士训练师，旨在邀请新兵站出来，为保卫族人贡献他们的武力。"},{t="动荡的新纪元",b="当向奥莉希亚报到时，她会将战士的训练置于快速且令人不安的变革背景下。在短短几年内，暗夜精灵种下了世界之树泰达希尔，目睹了一种阴险的腐蚀在远近的森林野兽中蔓延，并重新与曾经被认为已经失落的古老祖先领地（如菲拉斯）取得了联系。面对这些威胁，急需能干的守卫者。"},{t="开启枝叶",b="除了武艺训练外，奥莉希亚还为年轻的卡多雷准备好面对他们这片庇护谷地之外的世界。她建议新兵不要对那些来到泰达希尔的其他种族外来者抱有偏见。虽然她告诫说并非每一位旅者都是出于纯粹的利他主义，但她强调盟友对保卫卡多雷至关重要，并敦促她的学生在担任守护者角色时，给予适度的信任。"}},faq={{q="什么是简易符记？",a="这是一枚由幽影谷的战士训练师奥莉希亚发出的刻印代币，发给初出茅庐的暗夜精灵战士，以召唤他们进行正式的战斗指导。",al={"简易符记物品","这个符记是什么","战士符记"}},{q="谁派你去找奥莉希亚的？",a="在你完成在幽影谷维持平衡的初步任务后，管理员伊尔萨莱恩会将符记交给你，并指引你去找奥莉希亚。",al={"谁发放简易符记","简易符记任务发布者"}},{q="奥莉希亚在哪里？",a="奥莉希亚位于幽影谷的安全避风港内，站在奥达希尔的巨树干旁，在那里训练有抱负的暗夜精灵战士。",al={"奥莉希亚位置","奥莉希亚在哪里","幽影谷战士训练师"}},{q="为什么奥莉希亚说现在需要战士？",a="近年来带来了巨大的挑战：泰达希尔的建立、感染当地野生动物的广泛腐蚀，以及对菲拉斯等久已失落之地的重新发现。需要熟练的战斗人员来保护卡多雷免受这些迫在眉睫的威胁。",al={"为什么暗夜精灵需要战士","幽影谷战士背景"}},{q="奥莉希亚对访问泰达希尔的其他种族有什么评价？",a="她劝诫不要抱有偏见，解释说其他种族的外来者很快就会造访泰达希尔的枝叶。虽然她承认并非所有到访者都是纯粹出于利他主义，但她建议给予一定程度的信任，以便他们能协助保卫这棵大树。",al={"奥莉希亚关于其他种族的看法","暗夜精灵与外来者","泰达希尔的联盟"}},{q="提到菲拉斯有什么意义？",a="菲拉斯代表了暗夜精灵古老的土地，这些土地在天崩地裂后长期与世隔绝或被认为已经失落。它的被重新发现凸显了卡多雷在经历了数千年的孤立后，正以多快的速度与广阔的世界重新建立联系。",al={"为什么要提到菲拉斯","菲拉斯的联系"}}},fp="12,180,28.325.0,20.333.0,18.324.0,25.159.0,31.143.0,28.110.0,52.222.0,61.192.0,47.200.0"}
P.entries["quest:3117"] = {n="风化符记",s="风化符记是一份通过管理员伊尔萨莱恩送达幽影谷年轻暗夜精灵猎人的书面召集令。它召唤他们登上奥达希尔的巨大枝干，去见他们的导师阿亚娜·远途，并正式开始他们的射箭与驯兽之路。",h="风化符记是一份通过管理员伊尔萨莱恩送达幽影谷年轻暗夜精灵猎人的书面召集令。它召唤他们登上奥达希尔的巨大枝干，去见他们的导师阿亚娜·远途，并正式开始他们的射箭与驯兽之路。",kw={"奥达希尔","阿亚娜·远途","风化符记","猎人","ilthalaine","幽影谷","泰达希尔"},ang={["class:Hunter"]="这个任务标志着你在泰达希尔猎人导师指导下的正式入门，开启了学习弓箭制作、追踪和野兽掌握的大门。",["race:NightElf"]="对于卡多雷来说，狩猎是一门与自然和谐相处并敬畏艾露恩的神圣学科，而不仅仅是一项运动。"},sec={{t="枝干上的召唤",b="在证明了他们保卫幽影谷的初步警觉后，年轻的卡多雷猎人会从管理员伊尔萨莱恩手中接过一枚刻印的信物。风化符记最初由猎人导师阿亚娜·远途的信使携带，它指引新手爬上奥达希尔的高处，导师们就在那里注视着树冠。"},{t="猎人之道",b="见到阿亚娜标志着猎人在泰达希尔训练的正式开始。她指导新手学习射击和理解卡利姆多野生生物的双重艺术。阿亚娜强调，真正的猎人必须尊重他们的野兽同伴，在一个充满未见危险的世界里保持警惕和谦逊。"}},faq={{q="风化符记是什么？",a="这是一封由猎人导师阿亚娜·远途发出的刻印信件，旨在指引有前途的暗夜精灵新手前往她在奥达希尔顶部的岗位。",al={"风化符记","这个符记是什么","符记物品"}},{q="阿亚娜·远途在哪里？",a="她位于奥达希尔的上层平台，那是幽影谷中心巨大的世界之树空洞。",al={"阿亚娜在哪里","寻找阿亚娜·远途","阿亚娜·远途位置"}},{q="谁发放风化符记？",a="管理员伊尔萨莱恩会在暗夜精灵猎人开始通过保卫当地林地证明自己后，将它交给他们。",al={"谁提供任务","任务提供者","我在哪里获得风化符记"}},{q="阿亚娜·远途教什么？",a="她训练猎人掌握射击、野兽管理和荒野生存的传统，同时告诫他们永远不要低估外面的危险。",al={"猎人训练","阿亚娜教什么","为什么要与阿亚娜交谈"}},{q="为什么阿亚娜告诫猎人关于他们的宠物？",a="她提醒学生，荒野中潜藏着比新手猎人所能意识到的更为强大的威胁，这意味着猎人必须尊重他们的同伴动物，而不是草率地对待它们的能力。",al={"野兽危险","为什么尊重野兽","宠物警示"}},{q="这个任务其他职业可以接吗？",a="不能，风化符记是专门为暗夜精灵猎人准备的职业入门召唤。",al={"德鲁伊能做这个吗","这是猎人专属吗","其他职业"}}},fp="12,203,23.274.0,22.254.0,25.126.0,35.113.0,31.132.0,34.129.0,49.189.0,41.76.0"}
P.entries["quest:3118"] = {n="密文符记",s="密文符记是发给初到幽影谷的暗夜精灵潜行者新手的引导性召唤。由管理员伊尔萨莱恩代表弗拉胡恩·影语者携带，它引导这些秘密特工开始受训，并警惕威胁着卡利姆多的脆弱和平。",h="密文符记是发给初到幽影谷的暗夜精灵潜行者新手的引导性召唤。由管理员伊尔萨莱恩代表弗拉胡恩·影语者携带，它引导这些秘密特工开始受训，并警惕威胁着卡利姆多的脆弱和平。",kw={"奥达希尔","管理员伊尔萨莱恩","密文符记","弗拉胡恩·影语者","潜行者训练师","幽影谷","泰达希尔"},ang={["class:Rogue"]="这项任务标志着你正式加入卡多雷的侦察兵、刺客和情报收集者网络，他们的职责是保护泰达希尔免受隐形敌人的侵害。",["faction:Alliance"]="幽影谷的训练师提醒新兵，跨阵营条约十分脆弱，情报工作对于防止部落入侵至关重要。",["race:NightElf"]="即使在奥达希尔这片与世隔绝的避风港中，卡多雷人依然密切注视着卡利姆多不断变化的边界，以保卫他们新种植的枝桠。"},sec={{t="阴影中的讯息",b="当年轻的暗夜精灵在管理员伊尔萨莱恩的指导下学习自然的平衡时，那些倾向于潜行和隐秘行动的人会收到一份更安静的召唤。密文符记由幽影谷的潜行者导师弗拉胡恩·影语者派人送达。上面刻着的密码只有行内的新手才能看懂，它指示持信人解读其中的内容，并前往奥达希尔的树根附近寻找弗拉胡恩，以正式开始受训。"},{t="守望地平线",b="弗拉胡恩的讯息不仅仅是一个简单的受训预约；它更是对卡利姆多地缘政治现实的一个严肃警告。随着第三次战争的结束，联盟与新兴的部落之间的和平依然薄如蝉翼。在幽影谷，潜行者侦察兵和情报人员被敦促尽早磨炼他们的耳目，监视那些可能在边境引发新一轮战争的潜在威胁和秘密挑衅。"}},faq={{q="什么是密文符记？",a="它是潜行者导师弗拉胡恩·影语者发给幽影谷新晋潜行者的加密信物，指示他们向奥达希尔树下向他报到，以接受正式训练。",al={"什么是密文符记","密文符记任务","符记物品"}},{q="谁将符记交给年轻的暗夜精灵？",a="一旦新手证明了自己具备处理幽影谷枝桠周围当地野生生物的基本能力，管理员伊尔萨莱恩便会代表弗拉胡恩交付符记。",al={"谁提供任务","任务发布者","管理员伊尔萨莱恩"}},{q="在哪里可以找到弗拉胡恩·影语者？",a="弗拉胡恩·影语者驻守在幽影谷的大树奥达希尔的庇护下，随时准备指导新来的暗夜精灵潜行者。",al={"弗拉胡恩在哪里","寻找弗拉胡恩·影语者","弗拉胡恩的位置"}},{q="为什么在和平的泰达希尔需要潜行者？",a="正如弗拉胡恩所指出的，目前与外部势力的停战状态非常脆弱。潜行侦察兵和情报收集者对于揭露隐秘阴谋至关重要，特别是在涉及部落动向和对枝桠的内部威胁方面。",al={"为什么暗夜精灵需要潜行者","幽影谷的潜行者","潜行者的目的"}},{q="将符记交给弗拉胡恩后会发生什么？",a="弗拉胡恩会收下密码信物，认可你的准备情况，并邀请你在获得经验后回来找他，以便他能教授你战斗技巧、武器掌握和潜行艺术。",al={"what comes next","密文符记之后","符记奖励背景故事"}},{q="部落会直接对幽影谷构成威胁吗？",a="虽然泰达希尔偏远的树冠在很大程度上免受了部落的公开袭击，但有关部落特工在卡利姆多各地播下不信任种子的传言，使卡多雷哨兵和特工们保持高度警惕。",al={"部落是否在泰达希尔","部落对幽影谷的威胁","部落播下不信任的种子"}}},fp="15,194,24.369.0,20.335.0,28.154.0,41.158.0,39.144.0,45.169.0,50.201.0,53.166.0"}
P.entries["quest:3119"] = {n="神圣符记",s="神圣符记是给在幽影谷开始训练的年轻暗夜精灵牧师的入门召唤信物。管理员伊尔萨莱恩传达了来自牧师训练师珊达的消息，指导新手修行者前往奥达希尔寻求指引，学习如何运用艾露恩的恩典。",h="神圣符记是给在幽影谷开始训练的年轻暗夜精灵牧师的入门召唤信物。管理员伊尔萨莱恩传达了来自牧师训练师珊达的消息，指导新手修行者前往奥达希尔寻求指引，学习如何运用艾露恩的恩典。",kw={"奥达希尔","管理员伊尔萨莱恩","艾露恩","神圣符记","牧师","幽影谷","珊达","泰达希尔"},ang={["class:Priest"]="这一通过仪式将年轻的卡多雷牧师与珊达联系起来，开启了他们在艾露恩的光辉与智慧中的正式训练。",["faction:Alliance"]="珊达的言论突显了新建立的联盟关系是如何将不熟悉的种族和旅者直接带到泰达希尔的枝干上的。",["race:NightElf"]="牧师体系是卡多雷文化的核心，由指引其族人几千年的古老月神信仰传统所管理。"},sec={{t="侍奉的召唤",b="在暗夜精灵文化中，牧师作为月神艾露恩的侍女和仆人，占据着神圣的地位。当幽影谷的一位年轻卡多雷表现出对圣光和信仰的亲和力时，管理员伊尔萨莱恩便会将一枚神圣符记交托给他们。这枚由牧师训练师珊达派信使送来的信物，是一份正式的邀请，请他们前往奥达希尔之树，开始专业的灵性教导。"},{t="变革的世界",b="在见到珊达后，年轻的侍僧发现受庇护的泰达希尔圣地正在经历不同寻常的动荡。珊达指出，世界之树的枝干上开始出现旅者，其中包括获准与卡多雷会面的联盟成员。虽然广阔的世界在呼唤，但珊达建议新手在涉足更遥远的纷争之前，先立足于幽影谷目前面临的问题。"}},faq={{q="什么是神圣符记？",a="这是一枚由牧师训练师珊达通过信使发送给管理员伊尔萨莱恩的刻印信物，旨在召唤新手牧师前往奥达希尔接受指导。",al={"神圣符记物品","这个符记是什么","珊达的符记"}},{q="珊达是谁？",a="珊达是驻扎在幽影谷奥达希尔的牧师训练师。她指导初出茅庐的暗夜精灵牧师进行The Sisterhood of Elune的基本仪式、纪律和祈祷。",al={"奥达希尔牧师训练师","珊达是谁"}},{q="珊达在哪里？",a="珊达居住在幽影谷中心地带的巨大树木——奥达希尔的空心树根内部，这里位于泰达希尔。",al={"找到珊达","神圣符记交任务地点","珊达位置"}},{q="为什么联盟成员会访问泰达希尔？",a="在第三次战争后，暗夜精灵与联盟建立了联系。外族人开始抵达泰达希尔的枝干上，与卡多雷进行协调和商议，因为双方都在为艾泽拉斯面临的挑战做准备。",al={"泰达希尔的联盟","为什么外来者在世界之树"}},{q="牧师完成这个任务后应该做什么？",a="珊达建议牧师协助幽影谷各地的当地守卫者和看守者，并在需要学习新的祈祷和技巧时随时回到她身边。",al={"拿到符记后做什么","神圣符记之后"}},{q="为什么伊尔萨莱恩要发布这个任务？",a="管理员伊尔萨莱恩负责监督幽影谷中新手的最初试炼。当珊达的信使带着符记到达时，伊尔萨莱恩将其保管，直到这位有抱负的牧师证明自己有能力迈出下一步。",al={"管理员伊尔萨莱恩牧师","为什么和伊尔萨莱恩对话"}}},fp="14,181,20.343.0,16.355.0,27.147.0,14.134.0,24.111.0,45.280.0,51.144.0,36.204.0"}
P.entries["quest:312"] = {n="马克格拉恩的干肉",s="图德拉·马克格拉恩，一位居住在丹莫罗寒冷山脊上的受伤矮人猎人，他的冬季补给被当地一只臭名昭著的野兽偷走了。一只被称为“老冰须”的巨大雪人将马克格拉恩的钍制强化肉柜搬回了自己的巢穴。由于腿部受伤无法跑赢这只野兽，猎人只能指望路过的冒险者潜入其中找回他的补给。",h="图德拉·马克格拉恩，一位居住在丹莫罗寒冷山脊上的受伤矮人猎人，他的冬季补给被当地一只臭名昭著的野兽偷走了。一只被称为“老冰须”的巨大雪人将马克格拉恩的钍制强化肉柜搬回了自己的巢穴。由于腿部受伤无法跑赢这只野兽，猎人只能指...",kw={"肉干","丹莫罗","肉柜","老冰须","被盗的补给","钍","图德拉·马克格拉恩","雪人"},ang={["class:Hunter"]="同行们一定会同情马克格拉恩的不幸遭遇，他辛辛苦苦腌制和保存的数月成果，却在追踪猎物时被一只投机取巧的野兽毁于一旦。",["class:Rogue"]="马克格拉恩特别寻找那些潜行能力强的旅行者，这使得失窃案成为侦察兵们的教科书式任务，他们可以在老冰须背后悄悄潜入，而不必拔出武器。",["race:Dwarf"]="丹莫罗的每一个矮人都知道山地冬季那冷酷无情的残酷，如果没有肉食储备或避难所，即便是久经沙场的登山者也无法抵御严寒。"},sec={{t="冬季储备与被盗的储物柜",b="在丹莫罗严酷的冬天生存下来需要充足的准备，对于生活在卡拉诺斯和铁炉堡温暖区域之外的登山者来说更是如此。图德拉·马克格拉恩为了熬过即将到来的寒冬，辛勤地腌制了一个月份量的肉干。为了防范饥饿的野熊，他将口粮锁进了一个强化的钍制肉柜中。不幸的是，他没有预料到山地雪人的蛮力，它们直接把整个柜子搬走了，而不是当场强行撬开。"},{t="老冰须的巢穴",b="盗窃的元凶是老冰须，一只潜伏在崎岖山丘中的可怕而凶残的雪人。当马克格拉恩外出猎鹿时，老冰须抢走了柜子并将其拖回了自己的山洞。虽然马克格拉恩确信即使是雪人也无法摧毁坚固的钍制外壳，但他自己受伤的腿让这项回收任务变成了自杀行为。任何进入山洞的勇敢灵魂，要么必须直接与这头野兽较量，要么必须在怪物外出巡视雪堆时谨慎地潜入。"}},faq={{q="图德拉·马克格拉恩是谁？",a="图德拉·马克格拉恩是一位居住在丹莫罗雪原上的矮人陷阱工和猎人。他因为腿部受伤，依靠储备的食物来度过恶劣的冬季环境。",al={"图德拉·马克格拉恩","马克格拉恩","马克格拉恩是谁"}},{q="是谁偷走了马克格拉恩的肉柜？",a="一只具有威胁性的当地雪人，被称为老冰须。它在马克格拉恩外出打猎时偷走了柜子，并将沉重的钍制储物箱拖回了它的山中巢穴。",al={"谁偷了补给","谁拿走了肉","被盗补给的窃贼"}},{q="为什么马克格拉恩不能自己拿回肉类？",a="马克格拉恩的腿部受伤，严重限制了他的行动能力。他知道自己无法足够迅速或安静地进入老冰须的洞穴并逃脱，否则就会被抓住并遭到重创。",al={"为什么马克格拉恩拿不回来","马克格拉恩的腿","受伤的腿"}},{q="雪人把食物吃了吗？",a="没有。肉干被锁在一个用坚固钍锭打造的箱子里。虽然雪人成功搬走了沉重的容器，但它无法破坏金属。",al={"食物被吃了吗","老冰须能打开柜子吗"}},{q="为了找回肉柜，我必须与老冰须战斗吗？",a="不，你不一定非要与它战斗。老冰须经常在巢穴外游荡，这为机敏的冒险者提供了潜入洞穴并不被察觉地拿走储物柜的机会。",al={"能潜行避开老冰须吗","我必须杀了老冰须吗"}},{q="被盗的储藏物在哪里？",a="被盗的肉柜位于老冰须山洞的深处，就在丹莫罗马克格拉恩营地附近的山丘中。",al={"山洞在哪里","老冰须洞穴位置"}}},fp="30,181,32.217.0,18.290.0,23.153.0,33.141.0,46.118.0,26.128.0,57.107.0,34.116.0"}
P.entries["quest:3120"] = {n="绿色符记",s="绿色符记是一份送达幽影谷新觉醒的暗夜精灵德鲁伊手中的书面传唤。管理员伊尔萨莱恩会将其转交给他们，指引这些初出茅庐的变形者前往奥达希尔的树枝间寻找玛丹特·硬木。它标志着德鲁伊正式开始学习自然与翡翠梦境的奥秘。",h="绿色符记是一份送达幽影谷新觉醒的暗夜精灵德鲁伊手中的书面传唤。管理员伊尔萨莱恩会将其转交给他们，指引这些初出茅庐的变形者前往奥达希尔的树枝间寻找玛丹特·硬木。它标志着德鲁伊正式开始学习自然与翡翠梦境的奥秘。",kw={"奥达希尔","德鲁伊训练师","翡翠梦境","ilthalaine","玛丹特·硬木","幽影谷","绿色符记"},ang={["class:Druid"]="这个任务代表了你正式加入塞纳里奥议会，在玛丹特·硬木的教导下，开启了通往理解翡翠梦境的漫长道路。",["race:NightElf"]="德鲁伊教义深深植根于暗夜精灵文化之中；在奥达希尔出示这枚符记，标志着新手踏入这一古老传统的第一步。"},sec={{t="树枝的召唤",b="一旦一位年轻的暗夜精灵在维持幽影谷的当地平衡方面展现出潜力，就需要接受正式的入会仪式。管理员伊尔萨莱恩通过一名信使收到绿色符记，并将其委托给这位新手。这枚小小的信物象征着奥达希尔的塞纳里奥议会已经注意到了他们，并邀请这位年轻的德鲁伊正式开始他们的训练。"},{t="共融与梦境",b="在奥达希尔内向玛丹特·硬木出示符记后，新手便会被接纳进入组织。尽管与翡翠梦境进行更深层次的共融以及掌握动物形态尚需时日，但玛丹特确立了他作为他们第一位导师的地位，负责教导他们如何解读自然的灵魂并引导原始的林地之力。"}},faq={{q="什么是绿色符记？",a="这是一份由管理员伊尔萨莱恩代玛丹特·硬木传递的铭文传唤，召集德鲁伊新手前往奥达希尔开始他们的正式训练。",al={"绿色符记物品","这是什么符记","德鲁伊符记"}},{q="我该把绿色符记带给谁？",a="把它交给玛丹特·硬木，他是驻扎在幽影谷中心、奥达希尔巨型瘤树内的德鲁伊训练师。",al={"玛丹特在哪里","上交绿色符记","我该去哪里"}},{q="为什么玛丹特会提到翡翠梦境？",a="德鲁伊通过漫长的沉睡恍惚，从翡翠梦境中汲取了他们大部分的力量与智慧。虽然新手还未准备好自由漫游翡翠梦境，但玛丹特将其作为他们最终将要学习的基础奥秘引入。",al={"为什么是翡翠梦境","玛丹特的梦境对话","德鲁伊恍惚"}},{q="是谁把符记送给伊尔萨莱恩的？",a="玛丹特·硬木派出的信使将符记送达给了管理员伊尔萨莱恩，以便直接交到这位有前途的年轻德鲁伊手中。",al={"谁发送了符记","符记信使"}},{q="出示符记后会发生什么？",a="玛丹特·硬木将成为你在幽影谷的主要导师，让你能在力量增长的同时学习最早期的德鲁伊法术和魔法技巧。",al={"接下来我学什么","绿色符记之后"}},{q="非德鲁伊玩家可以接到这个任务吗？",a="不能。绿色符记专供在幽影谷开启旅程的暗夜精灵德鲁伊使用。其他职业会收到各自职业训练师发出的独特传唤。",al={"这是德鲁伊专属吗","谁会获得绿色符记"}}},fp="13,278,20.322.0,23.295.0,26.160.0,34.116.0,43.191.0,34.142.0,40.150.0,34.154.0"}
P.entries["quest:3121"] = {n="奇怪的要求",s="巫医尤克里需要一份奥格瑞玛的尼鲁·火刃调制好的药剂。尤克里交给你一颗干缩的头颅，作为换取草药报酬许诺给尼鲁的，并让你前往奥格瑞玛的大断崖把它交给尼鲁。",h="巫医尤克里需要一份奥格瑞玛的尼鲁·火刃调制好的药剂。尤克里交给你一颗干缩的头颅，作为换取草药报酬许诺给尼鲁的，并让你前往奥格瑞玛的大断崖把它交给尼鲁。",kw={"一个奇怪的要求","cleft of shadow","菲拉斯","尼鲁·火刃","奥格瑞玛","干缩的头颅","巫医尤克里"},sec={{t="许诺的报酬",b="巫医尤克里说，奥格瑞玛的尼鲁·火刃手头上有他在菲拉斯开始行动所需的东西：一种他还不愿解释其用途的药剂。尤克里给了你一颗干缩的头颅，以此作为换取草药报酬许诺给尼鲁的物品。这原本是尤克里在森林里偶遇的某个可怜矮人的头颅。你可以在大断崖找到尼鲁。"},{t="尼鲁的草药",b="尼鲁·火刃一直在等尤克里派人送来这件东西，他将为尤克里的实验准备的草药混合物交给了你。"}},faq={{q="谁给予了“奇怪的要求”任务？",a="巫医尤克里，他让你带一颗干缩的头颅去奥格瑞玛。",al={"谁给予了奇怪的要求","谁开启了这个任务","奇怪的要求任务给予者"}},{q="尼鲁·火刃在哪里？",a="在奥格瑞玛的大断崖。",al={"尼鲁·火刃在哪里","我该去哪里","干缩的头颅交付地点"}},{q="那颗干缩的头颅是谁的？",a="尤克里称那是他在森林里偶遇的某个可怜矮人的头颅。",al={"这颗头颅是谁的","干缩的头颅身份","那个矮人是谁"}},{q="为什么尤克里要给尼鲁一颗干缩的头颅？",a="尤克里承诺过用它换取草药，并且他需要尼鲁调制好的药剂。",al={"为什么尼鲁想要这颗头颅","尼鲁·火刃交易"}},{q="“奇怪的要求”之后是什么？",a="这个任务线接下来是“回到巫医尤克里身边”。",al={"接下来是什么","奇怪的要求之后的下一个任务"}}},fp="17,230,18.343.0,13.133.1,28.67.0,25.37.0,32.71.0,46.99.0,31.53.0"}
P.entries["quest:3122"] = {n="向巫医尤克里回复",s="随着在“一个奇怪的请求”中交付了缩小的头颅，尼鲁·火刃将草药交给你，并要求你将其带给位于菲拉斯的巫医尤克里，同时转告他，尼鲁对这个头颅很满意。",h="随着在“一个奇怪的请求”中交付了缩小的头颅，尼鲁·火刃将草药交给你，并要求你将其带给位于菲拉斯的巫医尤克里，同时转告他，尼鲁对这个头颅很满意。",kw={"菲拉斯","草药袋","穆塞克容器","缩小的头颅","巫医尤克里"},sec={{t="草药的去向",b="在“一个奇怪的请求”之后，尼鲁·火刃给了你一袋给巫医尤克里的草药。他还要求你告诉尤克里，尼鲁对那个缩小的头颅很满意。这袋草药是要带给菲拉斯的尤克里的。"},{t="仪式开始",b="尤克里说这些草药正是准备穆塞克容器所需要的，并希望他最新的咒语能像他预期的那样强大。他让你等一会儿，他要进行仪式并使用这些草药。"}},faq={{q="谁把草药给了巫医尤克里？",a="尼鲁·火刃，就是你把缩小头颅带给他的那个人。",al={"任务起始点","谁给了草药"}},{q="这些草药要送到哪里？",a="送到位于菲拉斯的巫医尤克里那里。",al={"这是什么草药","我应该把草药袋带到哪里"}},{q="尼鲁对那个缩小的头颅满意吗？",a="是的。尼鲁对这个头颅很满意，并让你转告尤克里。",al={"尼鲁喜欢那个头颅吗","尼鲁缩小头颅交易"}}},fp="29,207,17.216.0,17.225.1,43.58.0,22.34.0,41.71.0"}
P.entries["quest:3123"] = {n="测试容器",s="在回到巫医尤克里处后，巫医尤克里称这是对刚刚进行的仪式以及你自身能力的考验。你被给予了一个可以缩小并捕获生物的容器，并被派往辛特兰用它捕获十只枭兽，然后将它们带回菲拉斯交给尤克里。",h="在回到巫医尤克里处后，巫医尤克里称这是对刚刚进行的仪式以及你自身能力的考验。你被给予了一个可以缩小并捕获生物的容器，并被派往辛特兰用它捕获十只枭兽，然后将它们带回菲拉斯交给尤克里。",kw={"艾露恩","菲拉斯","辛特兰","穆塞克","枭兽","尤克里","容器"},sec={{t="辛特兰的容器",b="巫医尤克里称这是一场考验，既是对刚刚完成的仪式的考验，也是对你自身能力的考验。你收到的容器可以将生物缩小并将其困在其中。你前往辛特兰寻找枭兽，这种生物曾是暗夜精灵女神艾露恩的宠物。尤克里指明这些凶猛、原始且野蛮的枭兽就是你的猎物。你必须击败十只，并在它们的灵魂消散前将其缩小放入容器中。十只枭兽连同容器，一起带回菲拉斯交给尤克里。"},{t="后续",b="尤克里解释说，当一个生物暴力死去时，它的穆塞克可能会逃脱并寻求复仇。像你刚才那样将倒下的生物缩小，可以防止穆塞克逃走，尤克里现在说它可以随意使用了。"}},faq={{q="谁发布了“测试容器”任务？",a="巫医尤克里，他将容器交给你。",al={"测试容器任务发布者","谁发布测试容器"}},{q="枭兽在哪里？",a="尤克里派你去辛特兰寻找它们。",al={"哪里找到枭兽","枭兽位置"}},{q="目标生物是什么？",a="被称为枭兽的凶猛、原始或野蛮的鸟兽。需要十只。",al={"要杀哪种枭兽","测试容器目标"}},{q="枭兽和艾露恩之间有什么联系？",a="尤克里说，枭兽曾经是暗夜精灵女神艾露恩的宠物。",al={"枭兽与艾露恩传说","为什么是枭兽"}},{q="这个容器有什么作用？",a="它能让你将倒下的生物缩小并困住，这样它的灵魂就无法逃脱。",al={"穆塞克容器如何工作","容器力量"}},{q="“测试容器”之后是什么？",a="任务线接下来是“角鹰兽穆塞克”。",al={"测试容器后续任务","测试容器之后做什么"}}},fp="18,296,28.485.0,9.208.1,29.46.0,22.53.0,32.76.0,47.68.0,23.88.0,32.41.0"}
P.entries["quest:3124"] = {n="角鹰兽灵魂精华",s="在你通过了缪塞克容器的试炼后，巫医尤克里要你去处理另一种生物。你需要立刻杀掉高原荒野的碎羽角鹰兽，并将它们缩小装入容器中，以便保存它们的缪塞克。",h="在你通过了缪塞克容器的试炼后，巫医尤克里要你去处理另一种生物。你需要立刻杀掉高原荒野的碎羽角鹰兽，并将它们缩小装入容器中，以便保存它们的缪塞克。",kw={"菲拉斯","碎羽","高原荒野","角鹰兽缪塞克","缪塞克容器","巫医尤克里"},sec={{t="忠诚的伙伴",b="巫医尤克里认为你值得信赖，并将容器交给了你，现在他想要另一种生物的灵魂。角鹰兽是暗夜精灵的老伙伴，它们的灵魂忠诚而坚定。你需要杀掉十只任意种类的碎羽角鹰兽，并用容器迅速将它们缩小捕获，以保存它们的缪塞克。尤克里说它们就在营地南边的高原荒野中。"},{t="尤克里的警告",b="尤克里说，如果被杀死的动物的缪塞克逃逸了，它可能会化身为更强大的生物，到那时它的复仇将让你永无宁日。尤克里称这项工作很危险，并称赞你完成得很好。"}},faq={{q="是谁派你去捕获角鹰兽的？",a="巫医尤克里。在完成“测试容器”后，你才会接到这个任务。",al={"角鹰兽缪塞克任务发布者","谁提供角鹰兽缪塞克任务","哪里接角鹰兽缪塞克任务"}},{q="碎羽角鹰兽在哪里？",a="它们位于高原荒野，尤克里说就在营地的南边。",al={"碎羽角鹰兽在哪里","菲拉斯角鹰兽位置","在菲拉斯哪里找角鹰兽"}},{q="为什么巫医尤克里想要角鹰兽的灵魂？",a="尤克里提到角鹰兽是暗夜精灵的老伙伴，它们的灵魂忠诚且坚定。他的目的是为了保存它们的缪塞克。",al={"为什么要找角鹰兽","为什么要捕获角鹰兽缪塞克","尤克里对于角鹰兽的理由"}},{q="如何捕获缪塞克？",a="杀掉一只碎羽角鹰兽，然后迅速用缪塞克容器将它缩小并捕获。任务需要十只，任意类型皆可。",al={"如何使用缪塞克容器","如何获得角鹰兽缪塞克","捕获碎羽缪塞克"}},{q="这个任务链的前一步是什么？",a="测试容器，在那里你证明了自己值得信赖，并掌握了使用缪塞克容器的方法。",al={"角鹰兽缪塞克前置条件","角鹰兽缪塞克的前一个任务","角鹰兽缪塞克的前置任务"}}},fp="17,234,16.426.0,16.241.1,37.68.0,44.78.0,53.145.0,27.118.0,41.92.0"}
P.entries["quest:3125"] = {n="精灵龙灵魂精华",s="在收集了角鹰兽之灵后，巫医尤克里又盯上了小精龙的灵魂。你被派往西方去猎杀小精龙和精灵龙，并夺取它们力量的源泉。",h="在收集了角鹰兽之灵后，巫医尤克里又盯上了小精龙的灵魂。你被派往西方去猎杀小精龙和精灵龙，并夺取它们力量的源泉。",kw={"小精龙穆希克","菲拉斯","角鹰兽穆希克","部落","穆希克容器","小精龙","精灵龙","树人穆希克","巫医尤克里"},sec={{t="脆弱的外表，强大的灵魂",b="尤克里指出，小精龙看起来很脆弱，但它们的灵魂才是真正的珍宝。它们一直是暗夜精灵的盟友，尤克里希望部落也能分享那份力量。尤克里给了你一个穆希克容器，并派你向西走，去击杀八只小精龙或精灵龙，然后用容器缩小并捕获每一只倒下的小精龙。"},{t="回到尤克里身边",b="当你带着捕获的灵魂回来时，尤克里向你表示感谢，并说现在部落可以汲取小精龙的精神力量了。尤克里还希望你能再帮他完成一项工作。"}},faq={{q="为什么巫医尤克里想要小精龙的灵魂？",a="尤克里说，小精龙虽然看起来脆弱，但却拥有强大的灵魂，而且它们一直是暗夜精灵的盟友。尤克里希望部落也能从这种力量中受益。",al={"为什么需要小精龙","小精龙穆希克的作用","为什么要杀小精龙"}},{q="在哪里可以找到小精龙？",a="尤克里说它们就在他所处位置的西方。",al={"小精龙在哪里","小精龙的位置","菲拉斯小精龙位置"}},{q="什么生物能提供这种穆希克？",a="小精龙和精灵龙。需要击杀并捕获其中的八只。",al={"哪些怪物会掉落穆希克","小精龙穆希克杀什么怪物","小精龙穆希克目标"}},{q="必须对倒下的生物做什么？",a="在每一只倒下的小精龙身上使用穆希克容器，将其缩小并捕获其中的穆希克。",al={"如何获得小精龙穆希克","穆希克容器如何使用","捕获穆希克"}},{q="这一步在尤克里的任务中排在什么位置？",a="它在角鹰兽穆希克之后，后面紧跟着树人穆希克任务。",al={"这个任务前置是什么","穆希克任务链顺序","小精龙穆希克之后是什么"}}},fp="20,187,28.343.0,21.194.1,56.180.0,38.49.0,35.80.0,42.91.0,49.80.0"}
P.entries["quest:3126"] = {n="树人灵魂精华",s="巫医尤克里下一个目标是游荡的森林行者，即在森林中缓慢漫步的树人。继精灵龙之后，你被派去寻找其中的三个。",h="巫医尤克里下一个目标是游荡的森林行者，即在森林中缓慢漫步的树人。继精灵龙之后，你被派去寻找其中的三个。",kw={"菲拉斯","穆塞克容器","树人穆塞克","树人","尤克里","游荡的森林行者"},sec={{t="缓慢的保护者",b="尤克里说，暗夜精灵招募了树人作为盟友，以对抗部落。它们行动缓慢，但尤克里认为它们作为保护者的角色毋庸置疑，并计划将这种力量转为部落所用。"},{t="三个森林行者",b="尤克里希望找到并杀死三个游荡的森林行者，然后用穆塞克容器将每个倒下的树人缩小并捕获。"},{t="尤克里的裁决",b="当你返回时，尤克里感谢了你，并提到穆塞克的收集工作即将完成。"}},faq={{q="是谁派遣冒险者去对付树人的？",a="巫医尤克里，他在让你对付精灵龙之后紧接着提出了这个要求。",al={"谁发布树人穆塞克任务","树人穆塞克任务发布者","尤克里树人任务"}},{q="为什么巫医尤克里想要树人穆塞克？",a="尤克里说，暗夜精灵招募了树人作为盟友，以对抗部落，他想利用它们作为保护者的力量来为部落谋取利益。",al={"为什么要杀死森林行者","为什么需要树人穆塞克","尤克里树人任务动机"}},{q="为树人穆塞克任务需要找到什么生物？",a="游荡的森林行者，它们在森林中漫步。需要找到三个。",al={"要杀死哪些树人","游荡的森林行者","树人穆塞克任务目标"}},{q="树人是如何被捕获的？",a="在游荡的森林行者倒下后，使用穆塞克容器将其缩小并捕获。",al={"如何使用穆塞克容器","捕获森林行者","缩小树人"}},{q="树人穆塞克在尤克里的任务序列中处于什么位置？",a="它位于精灵龙穆塞克之后，山岭巨人穆塞克之前。",al={"树人穆塞克任务链","精灵龙穆塞克之后的任务","树人穆塞克之后的下一个任务"}}},fp="13,165,15.223.0,20.129.0,16.94.1,40.70.0,48.163.0,47.74.0,29.93.0,53.74.0"}
P.entries["quest:3127"] = {n="山岭巨人灵魂精华",s="巫医尤克里称这是最后一项任务，并派你前往西北方寻找最后的敌人：山岭巨人。尤克里渴望利用它们巨大的体型和力量。",h="巫医尤克里称这是最后一项任务，并派你前往西北方寻找最后的敌人：山岭巨人。尤克里渴望利用它们巨大的体型和力量。",kw={"燃烧军团","峭壁巨人","菲拉斯","踏地者","山岭巨人穆瑟克","穆瑟克容器","树妖的穆瑟克","巫医尤克里"},sec={{t="岩石地面的巨人",b="据巫医尤克里所说，当燃烧军团降临艾泽拉斯时，山岭巨人从群山中走下来协助暗夜精灵。它们那庞大的身躯和踏在岩石地面上引起的震颤非常容易辨认。尤克里渴望利用那种规模的力量。尤克里要你击倒七个踏地者或峭壁巨人，并用穆瑟克容器将它们缩小并捕获。"},{t="尤克里的吹嘘",b="当你返回时，尤克里谈到了现在所收集之物的可能性。尤克里声称，利用你一路上收集的材料，它能够将这些生物的灵魂永久地禁锢在它想要的任何东西中。"}},faq={{q="谁要求获得山岭巨人的穆瑟克？",a="巫医尤克里，它称这是对你的最后要求。",al={"任务发布者","谁发布山岭巨人穆瑟克任务","尤克里任务"}},{q="山岭巨人在哪里？",a="尤克里派你向西北方向行进，在岩石地形中寻找它们。",al={"山岭巨人位置","踏地者在哪里","峭壁巨人位置"}},{q="为什么山岭巨人会在这里？",a="根据尤克里的说法，当燃烧军团降临到这个世界上时，它们从群山中走下来协助暗夜精灵。",al={"巨人为什么在这里","菲拉斯山岭巨人背景"}},{q="哪些生物提供所需的穆瑟克？",a="踏地者和峭壁巨人。需要七个，穆瑟克容器会将每一个倒下的巨人缩小并捕获。",al={"为了穆瑟克我需要杀什么","哪些巨人算数"}},{q="这个任务在序列中排在什么前面？",a="它紧随“树妖的穆瑟克”之后，而“灵魂武器”列在它之后。",al={"前置任务","穆瑟克任务链顺序"}}},fp="21,161,26.395.0,14.235.1,41.58.0,38.67.0,29.124.0,44.108.0,39.67.0"}
P.entries["quest:3128"] = {n="天然材料",s="位于莫沙彻营地的巫医尤克里需要收集材料来完成一项尝试，这些材料需要与其他试炼一起收集：破碎的圆木、结痂的矿石、坚韧的筋腱和金属碎片，它们分别来自树人、山岭巨人、精龙、枭兽和角鹰兽。",h="位于莫沙彻营地的巫医尤克里需要收集材料来完成一项尝试，这些材料需要与其他试炼一起收集：破碎的圆木、结痂的矿石、坚韧的筋腱和金属碎片，它们分别来自树人、山岭巨人、精龙、枭兽和角鹰兽。",kw={"莫沙彻营地","结痂的矿石","菲拉斯","金属碎片","穆伊斯克","自然材料","坚韧的筋腱","破碎的圆木","辛特兰","巫医尤克里"},sec={{t="为巫医收集材料",b="在你回到巫医尤克里身边后，还有一份后续的材料清单等着你，需要与其他试炼一起收集。需要从菲拉斯的树人身上获取两根破碎的圆木。六块结痂的矿石可以在西部的山岭巨人与精龙身上找到。二十块坚韧的筋腱来自于辛特兰的枭兽或菲拉斯的角鹰兽。大量的金属碎片（总共四十个）可以从上述任意生物身上获得。"},{t="尤克里的裁决",b="当带回材料后，尤克里感到很高兴。将它们与穆伊斯克结合，应该能得到预期的结果。"}},faq={{q="谁在请求这些自然材料？",a="莫沙彻营地的巫医尤克里。",al={"自然材料任务发布者","自然材料任务起始地点"}},{q="哪些生物拥有破碎的圆木？",a="菲拉斯的树人；需要两根破碎的圆木。",al={"破碎的圆木获取地点","谁掉落破碎的圆木","破碎的圆木来源"}},{q="哪里可以收集到结痂的矿石？",a="西部的山岭巨人和精龙携带着它们；需要六块。",al={"如何获得结痂的矿石","结痂的矿石来源","谁掉落结痂的矿石"}},{q="哪些野兽提供坚韧的筋腱？",a="辛特兰的枭兽或菲拉斯的角鹰兽；需要二十块。",al={"坚韧的筋腱掉落","在哪里寻找坚韧的筋腱","谁拥有坚韧的筋腱"}},{q="金属碎片来自哪里？",a="四十个碎片来自上述列出的任何生物：树人、山岭巨人、精龙、枭兽和角鹰兽。",al={"金属碎片来源","如何获得金属碎片","谁掉落金属碎片"}},{q="在此任务之前有什么要求？",a="该任务紧接“回到巫医尤克里”之后。",al={"自然材料前置任务","自然材料前续任务","什么任务指引向自然材料"}}},fp="17,206,30.401.0,16.134.1,37.50.0,40.59.0,41.86.0,41.109.0,38.110.0,30.51.0"}
P.entries["quest:3129"] = {n="灵魂武器",s="巫医尤克里现在拥有了一切所需的材料，以及你捕捉到的灵魂。将它们注入武器是一项艰苦的工作，因此尤克里请你稍等片刻，他需要做些准备。",h="巫医尤克里现在拥有了一切所需的材料，以及你捕捉到的灵魂。将它们注入武器是一项艰苦的工作，因此尤克里请你稍等片刻，他需要做些准备。",kw={"菲拉斯","姆伊塞克","灵魂武器","灵魂之武器","巫医尤克里"},sec={{t="片刻的耐心",b="尤克里承认，将姆伊塞克注入武器的过程相当艰难。现在他手头已经有了所需的全部材料，以及你捕捉到的灵魂，尤克里可以开始了，并请你在他准备武器时稍作等待。"},{t="等待结束之时",b="尤克里回来并让你从武器中进行选择，告诉你要捕捉的生物的灵魂已经被永久地封印在其中了。它们的力量现在可以为你所用。"}},faq={{q="谁是“灵魂之武器”的幕后主使？",a="巫医尤克里，就是派你去收集姆伊塞克的同一个人，这个任务紧接在“山岭巨人的姆伊塞克”之后。",al={"谁发布灵魂之武器任务","灵魂之武器任务发布者","尤克里任务"}},{q="巫医尤克里在这一步做了什么？",a="尤克里正在努力将捕捉到的姆伊塞克注入武器，这个过程被他称为是一项艰巨的工作，并请你在他进行准备时稍作等待。",al={"灵魂之武器任务流程","尤克里在做什么"}},{q="在尤克里开始工作之前需要什么？",a="尤克里说所需的材料已经收集完毕，你捕捉的灵魂也已到手，所以工作可以开始了。",al={"灵魂之武器需求","灵魂之武器前置条件"}}},fp="17,184,19.207.0,18.178.1,32.106.0,50.139.0,39.110.0"}
P.entries["quest:313"] = {n="灰色洞穴",s="卡拉诺斯的驾驶员迪恩·石轮正在寻找真正具有矮人毅力的人来修缮他心爱的攻城战车“Trollplow”。为了考验有志向的冒险者的勇气，他会将他们派往西面危险的洞穴——即所谓的灰色洞穴，去猎杀野蛮的温迪戈以获取它们厚实的毛皮。",h="卡拉诺斯的驾驶员迪恩·石轮正在寻找真正具有矮人毅力的人来修缮他心爱的攻城战车“Trollplow”。为了考验有志向的冒险者的勇气，他会将他们派往西面危险的洞穴——即所谓的灰色洞穴，去猎杀野蛮的温迪戈以获取它们厚实的毛皮。",kw={"丹莫罗","灰色洞穴","卡拉诺斯","驾驶员迪恩·石轮","trollplow","温迪戈","雪怪的鬃毛"},ang={["profession:Engineering"]="任何欣赏矮人攻城车辆工艺的人都知道，在零下天气里维护重型机械需要对驾驶室保暖采取创造性的解决方案。",["race:Dwarf"]="对于年轻的山地探险队员和铁炉堡的冒险者来说，挑战灰色洞穴的温迪戈是一项典型的当地成人礼。",["race:Gnome"]="与卡拉诺斯周围的矮人们比邻而居，意味着要尽一份力来帮助装备铁炉堡的重型装甲引擎。"},sec={{t="毅力的考验",b="操作一辆巨大的矮人攻城坦克需要钢铁般的神经，以及在冰冷的山口空气中应对震耳欲聋的机械的体质。驻扎在卡拉诺斯附近钢架补给站的驾驶员迪恩·石轮声称自己两者兼备。与其轻易放弃工作或自尊，他挑战新来者前往冰冻的山丘面对当地野兽，以证明他们拥有同样坚韧的性格。"},{t="Trollplow里的舒适享受",b="驾驶员迪恩·石轮的攻城战车有一个引以为傲且直白的名字：Trollplow，但在严寒的丹莫罗气候中，它那狭窄的铁皮驾驶室里冷得刺骨。驾驶员迪恩·石轮想出了一个既实用又大胆的解决方案：温迪戈毛皮。从潜伏在灰色洞穴的凶猛温迪戈身上获取厚重的鬃毛，可以为制作Trollplow甲板上耐用且温暖的地毯提供所需材料，同时还能控制当地野兽的数量。"}},faq={{q="谁是驾驶员迪恩·石轮？",a="驾驶员迪恩·石轮是一名驻扎在丹莫罗卡拉诺斯城外的矮人攻城战车驾驶员。他驾驶着一辆被亲切地命名为Trollplow的装甲战争机器，并对自己的钢铁意志和机械手艺感到无比自豪。",al={"驾驶员迪恩·石轮","任务发布者","驾驶员迪恩·石轮是谁"}},{q="灰色洞穴位于何处？",a="灰色洞穴是一处坐落在卡拉诺斯正西面群山中的积雪洞穴系统。它是丹莫罗凶残的温迪戈臭名昭著的巢穴。",al={"灰色洞穴位置","温迪戈洞穴在哪里","如何找到灰色洞穴"}},{q="为什么驾驶员迪恩·石轮想要温迪戈的鬃毛？",a="驾驶员迪恩·石轮想要温迪戈浓密而隔热的毛皮，为他的攻城战车Trollplow的内部甲板制作一张舒适的地毯，同时借此考验冒险者的勇气。",al={"为什么需要温迪戈鬃毛","鬃毛的用途","鬃毛有什么用"}},{q="什么是Trollplow？",a="Trollplow是驾驶员迪恩·石轮的个人矮人攻城战车。它那富有侵略性的名字反映了铁炉堡矮人与居住在周围峭壁上的敌对霜鬃巨魔之间持续不断的冲突。",al={"trollplow","驾驶员迪恩·石轮的坦克","什么是trollplow"}},{q="灰色洞穴里栖息着什么样的生物？",a="这个洞穴里栖息着野蛮的温迪戈——一种原产于丹莫罗雪山顶的类猿野兽，它们会积极地保护领地，抵御任何闯入者。",al={"灰色洞穴里的怪物","灰色洞穴里住着什么"}},{q="温迪戈对卡拉诺斯有危险吗？",a="虽然温迪戈很少像霜鬃巨魔那样组织协同攻击，但它们暴力的凶猛性和与主干道的近距离接触，使它们成为旅行者和当地商贩共同的时刻存在的威胁。",al={"温迪戈有威胁吗","温迪戈的危险性"}}},fp="16,162,14.246.0,30.212.0,23.192.0,34.127.0,38.128.0,18.177.0,48.148.0,39.161.0"}
P.entries["quest:3130"] = {n="憎世纳迦之战",s="在你报告情况后，珊蒂斯·羽月将军将你指派给羽月要塞的副官拉托尼库斯·月矛。珊蒂斯希望能调动全部兵力对抗纳迦，但她不能让要塞在面对部落或其他更可怕的威胁时门户大开。",h="在你报告情况后，珊蒂斯·羽月将军将你指派给羽月要塞的副官拉托尼库斯·月矛。珊蒂斯希望能调动全部兵力对抗纳迦，但她不能让要塞在面对部落或其他更可怕的威胁时门户大开。",kw={"对抗恨潮","羽月要塞","菲拉斯","恨潮","部落","拉托尼库斯·月矛","纳迦","珊蒂斯·羽月"},sec={{t="珊蒂斯的权衡",b="珊蒂斯·羽月将军将你派去寻找拉托尼库斯·月矛，他是将军的副官，一直密切监视着纳迦军队。珊蒂斯将在此评估针对纳迦的整体局势。虽然她很想集结全部力量对付它们，但如果因此导致要塞在面对部落或更可怕的敌人时毫无防备，那就得不偿失了。拉托尼库斯正在羽月要塞等你。"},{t="拉托尼库斯的计划",b="拉托尼库斯·月矛说将军已经委派他直接处理纳迦的问题。计划分为两部分：从数量和指挥层面上削弱他们，并查明他们在废墟中究竟在密谋什么。有了你的协助，我们既能对抗他们的势力，又能确保要塞的安全。"}},faq={{q="为什么珊蒂斯·羽月要派你去找拉托尼库斯？",a="如果调动全部兵力对抗纳迦会导致羽月要塞暴露在部落或更可怕的敌人面前，珊蒂斯是不会这么做的。因此，将军指派你去找一直监视着纳迦的副官拉托尼库斯。",al={"为什么找拉托尼库斯","拉托尼库斯·月矛的作用","羽月要塞指派"}},{q="拉托尼库斯·月矛在哪里？",a="在羽月要塞，珊蒂斯会派你去那里向他报告。",al={"拉托尼库斯的位置","拉托尼库斯在哪","寻找拉托尼库斯·月矛"}},{q="这项任务的前置是什么？",a="返回羽月要塞，之后珊蒂斯会派你去寻找拉托尼库斯。",al={"对抗恨潮的前置条件","上一个任务","恨潮任务线起始"}}},fp="21,266,24.411.0,23.288.1,53.232.0,38.69.0,33.82.0"}
P.entries["quest:314"] = {n="保护牲畜",s="“保护羊群”是由冻石农场（Amberstill Ranch）的鲁德拉·冻石（Rudra Amberstill）在丹莫罗（Dun Morogh）发布的一项任务。一只名为瓦格什（Vagash）的凶猛掠食野兽在夜间不断袭击农场珍贵的山羊，而铁炉堡（Ironforge）的军队此时正分散在王国内各地，因此当地的饲养员们只能依靠过往的冒险者来提供保护。",h="“保护羊群”是由冻石农场（Amberstill Ranch）的鲁德拉·冻石（Rudra Amberstill）在丹莫罗（Dun...",kw={"冻石农场","丹莫罗","铁炉堡","山羊","保护羊群","鲁德拉·冻石","瓦格什","维隆·冻石"},ang={["class:Hunter"]="在丹莫罗的雪堆中追踪像瓦格什这样的臭名昭著的顶级掠食者，对于任何磨练自己技能的追踪者来说，都是一个经典的试炼场。",["faction:Alliance"]="随着High Seat的军团被抽调去支持东部王国各地的联盟行动，援助处于困境中的农村宅地有助于稳定后方。",["race:Dwarf"]="对于矮人游侠来说，保卫冻石农场就是保护那些载着你的族人奔赴卡兹莫丹战场的山羊。"},sec={{t="农场的威胁",b="冻石农场提供的山羊是铜须矮人们标志性的坐骑和役用兽。维持这些羊群对丹莫罗的乡村经济至关重要。当夜幕降临，兽栏中回荡起惊恐的叫声时，冻石家族发现他们有两只珍贵的山羊失踪了。罪魁祸首就是瓦格什，这是一只潜伏在农场上方附近岩架上的臭名昭著的凶残野兽，它以暴力捕食当地家畜而闻名。"},{t="防守吃紧",b="通常情况下，这种程度的本地威胁会由矮人山地巡逻队或国王麦格尼·铜须（King Magni Bronzebeard）的皇家部队来处理。然而，铁炉堡的常备军目前正分散在遥远的边境，支援更广阔的联盟。在没有官方军事分队巡逻山脊线的情况下，鲁德拉·冻石被迫请求独立的战士们去猎杀瓦格什，并带回这只野兽的一颗致命尖牙作为凭证。"}},faq={{q="瓦格什是谁？",a="瓦格什是一只危险的掠食怪物，它潜伏在冻石农场正上方的雪山脊上。它因其强大的力量和贪婪的食欲而令人恐惧，对丹莫罗东部的家养山羊群和毫无防备的旅行者都构成了致命威胁。",al={"什么是瓦格什","瓦格什怪物","瓦格什背景"}},{q="在哪里可以找到瓦格什？",a="瓦格什在俯瞰冻石农场的岩架高处，一个被积雪覆盖的洞穴中筑巢。沿着宅地后方松树林旁的小雪坡向上走，可以直接到达它巢穴的洞口。",al={"瓦格什位置","瓦格什在哪里","寻找瓦格什"}},{q="为什么铁炉堡卫兵不来处理？",a="国王麦格尼·铜须的军队目前正忙于防守战略要塞并支援远方的联盟战役。因此，像冻石农场这样的农村宅地必须自力更生，或者招募有能力的冒险者。",al={"为什么没有卫兵","铁炉堡军队在哪","为什么要帮助冻石农场"}},{q="鲁德拉提到的维隆是谁？",a="维隆·冻石（Veron Amberstill）是农场的一位山羊饲养大师，负责训练和照料铜须矮人著名的骑乘山羊。鲁德拉提到，一旦潜伏在他们珍贵动物身边的掠食威胁被消除，维隆将如释重负。",al={"维隆是谁","维隆·冻石","维隆"}},{q="为什么需要击杀证明？",a="鲁德拉要求得到瓦格什的尖牙，是为了确保被击杀的确实是那个恐吓他们羊群的真正怪物，而不是山坡上普通的游荡野兽。",al={"为什么要瓦格什的尖牙","瓦加什的牙齿","什么是证明"}},{q="山羊对丹莫罗有什么重要性？",a="山羊是耐寒、脚步稳健的生物，非常适合在卡兹莫丹冰冷崎岖的地形中穿行。它们是矮人王国必不可少的役用动物、羊毛来源和骑兵坐骑。",al={"为什么山羊很重要","冻石山羊的用途","矮人山羊传说"}}},fp="19,175,21.251.0,17.255.0,14.189.0,26.169.0,47.199.0,32.179.0,34.133.0,47.154.0"}
P.entries["quest:315"] = {n="完美烈酒",s="烈酒村的雷杰德·麦酒决心酿造出终极的矮人烈酒，他将家族的酿酒传统与异域风味的当地原料相结合。为了完善他的实验性配方，他正在寻找闪光草，这是一种极其辛辣的植物，只由敌对的霜鬃巨魔在闪光岭的顶部种植。胆大的旅行者被派遣进入巨魔营地，直接从他们的部落篮筐中偷取这种草药。",h="烈酒村的雷杰德·麦酒决心酿造出终极的矮人烈酒，他将家族的酿酒传统与异域风味的当地原料相结合。为了完善他的实验性配方，他正在寻找闪光草，这是一种极其辛辣的植物，只由敌对的霜鬃巨魔在闪光岭的顶部种植。胆大的旅行者被派遣进入巨...",kw={"烈酒村","丹莫罗","矮人酿酒","霜鬃巨魔","完美烈酒","雷杰德·麦酒","闪光岭","闪光草"},ang={["profession:Herbalism"]="虽然不是标准的制作草药，但这种抗寒的闪光草因其独特的植物学特性，成为了丹莫罗冰冷岩壁上一种引人入胜的新奇事物。",["race:Dwarf"]="对于铜须氏族来说，酿酒几乎是神圣的，而寻找一种异域野生草药来超越竞争对手的酒馆被认为是一项高尚的追求。"},sec={{t="酿酒师的野心",b="在烈酒村，酿酒不仅仅是一门手艺，更是一种生活方式，对麦酒家族来说尤其如此。雷杰德·麦酒坚信酿造出伟大的酒是他的天职，但要酿造出传说中的“完美烈酒”需要非传统的创新。雷杰德没有仅仅依靠标准的啤酒花、麦芽和山泉水，而是将目光投向了丹莫罗未受驯化的植物，试图赋予他的麦酒一种独特的刺激感。"},{t="闪光岭的巨魔草药",b="雷杰德觊觎的秘密配方是闪光草，这是一种耐寒植物，由东边闪光岭上的霜鬃巨魔种植。虽然霜鬃巨魔采集它主要是为了部落和神秘仪式，但矮人们除了知道它辛辣、独特的味道外，几乎没什么实际用途。这种草药直接从巨魔村庄的储存篮中抢来，成为了雷杰德最新、最大胆的发酵实验的核心原料。"}},faq={{q="什么是闪光草？",a="闪光草是一种独特的植物，由闪光岭上的霜鬃巨魔种植和收获。虽然巨魔主要在部落仪式中使用它，但雷杰德·麦酒试图测试其辛辣、独特的味道，将其作为矮人酿酒过程中一种非传统的调味剂。",al={"闪光草背景知识","闪光草有什么用","霜鬃巨魔植物"}},{q="闪光岭在哪里？",a="闪光岭位于丹莫罗北部积雪覆盖的高地上，烈酒村的东侧。它是当地霜鬃巨魔的加固营地，因此去那里进行任何草药采集活动都是进入敌方领地的危险之举。",al={"闪光岭位置","闪光岭在哪里","如何找到闪光岭"}},{q="雷杰德为什么要从霜鬃巨魔那里偷东西？",a="霜鬃巨魔垄断了丹莫罗的闪光草种植，矮人和巨魔之间的紧张关系使得和平贸易成为不可能。由于这些植物已经被收获并捆扎在他们营地的部落篮筐中，溜进去或杀进去抢夺是雷杰德唯一的选择。",al={"为什么要偷巨魔的东西","为什么要偷巨魔的篮子","雷杰德的巨魔计划"}},{q="雷杰德·麦酒是谁？",a="雷杰德·麦酒是一位居住在烈酒村的雄心勃勃的矮人酿酒师。正如他的家族姓氏所示，他致力于发现完美烈酒的配方，不断尝试新的口味和强效的野生原料。",al={"雷杰德是谁","雷杰德·麦酒","麦酒家族"}},{q="闪光草算是炼金药草吗？",a="不算。闪光草不是从野外采集点获得的炼金试剂。它是一种任务物品，储存在闪光岭上霜鬃巨魔营地的柳条篮和储物箱里。",al={"草药师可以采摘闪光草吗","闪光草是草药学吗","闪光草采集"}},{q="闪光草上交后会有什么用？",a="雷杰德将新采集来的闪光草直接投入烈酒村正在发酵的一批酒中，希望它独特的属性最终能让他酿造出他梦寐以求的完美配方。",al={"这种烈酒有效吗","雷杰德的酿造结果","闪光草啤酒"}}},fx={["3780a202"]={q="霜鬃巨魔是什么人？",a="霜鬃是冰霜巨魔的一个土著部族，世代居住在丹莫罗的雪山峭壁间。随着铁炉堡矮人不断扩张，他们被赶出了祖辈的猎场，因此对邻近的矮人怀有深深的敌意。他们在闪光岭等聚居地种植闪光草，用于部族仪式，并会竭力抵御任何闯入营地的人。",al={"霜鬃巨魔","闪光岭上的巨魔是谁","霜鬃部族"}}},fp="17,335,19.319.0,31.300.0,20.238.0,31.188.0,56.267.0,25.170.0,42.191.0,47.182.0"}
P.entries["quest:3161"] = {n="加兹瑞迪安",s="玛尔冯·瑞文斯克是一位科学家，骨子里也是位寻宝者。他需要三十件曾经生活在塔纳利斯的巨魔留下的饰品。玛尔冯给了你一个他自己发明的探测器来帮助你寻找它们。",h="玛尔冯·瑞文斯克是一位科学家，骨子里也是位寻宝者。他需要三十件曾经生活在塔纳利斯的巨魔留下的饰品。玛尔冯给了你一个他自己发明的探测器来帮助你寻找它们。",kw={"破碎石柱","探测器","东月废墟","加兹瑞迪安","加兹瑞拉","玛尔冯·瑞文斯克","南月废墟","塔纳利斯","巨魔"},sec={{t="多头蛇神的遗物",b="很久以前，巨魔占据了这片土地，他们制作了大量以加兹瑞拉——他们当作神来崇拜的多头蛇——为原型的饰品。玛尔冯·瑞文斯克将雕刻这些饰品的元素称为“加兹瑞迪安”，这个名字取自那位多头蛇神。玛尔冯已经找到了一些，他希望能有更多的来进行研究。"},{t="探测器",b="玛尔冯发明了一种能让寻找加兹瑞迪安变得简单的探测器，并将它交给了你。佩戴它即可开始搜寻。饰品在塔纳利斯的几乎任何地方都能找到，不过在破碎石柱、东月废墟和南月废墟附近最为密集。"}},faq={{q="玛尔冯·瑞文斯克是谁？",a="玛尔冯·瑞文斯克是塔纳利斯的一位科学家，骨子里也是位寻宝者。他研究古代巨魔制作的饰品。",al={"玛尔冯·瑞文斯克","谁给予加兹瑞迪安","任务发布者"}},{q="什么是加兹瑞迪安？",a="这是玛尔冯·瑞文斯克对巨魔的多头蛇饰品所用雕刻元素的命名，取自那位多头蛇神的名字。",al={"什么是加兹瑞迪安","加兹瑞迪安矿石","加兹瑞迪安材料"}},{q="加兹瑞拉是谁？",a="加兹瑞拉是古代巨魔当作神来崇拜的一头多头蛇。他们制作饰品时便是以它为原型的。",al={"加兹瑞拉神灵","多头蛇崇拜","谁是加兹瑞拉"}},{q="在哪里可以找到加兹瑞迪安饰品？",a="在塔纳利斯几乎任何地方，不过最集中的地方是在破碎石柱以及东月废墟和南月废墟周围。",al={"在哪里寻找加兹瑞迪安","加兹瑞迪安的最佳地点","加兹瑞迪安位置"}},{q="如何找到这些饰品？",a="玛尔冯专门发明了一种探测器。佩戴它即可开始搜寻。",al={"如何发现饰品","加兹瑞迪安探测器","寻找加兹瑞迪安"}}},fp="11,207,23.285.0,12.263.0,26.130.0,20.119.0,18.102.0,38.125.0,30.77.0"}
P.entries["quest:317"] = {n="贝尔丁的补给",s="“为‘喷气蒸汽号’储备物资”是联盟的一项任务，由丹莫罗钢架补给站的驾驶员贝隆·风箱提供。为了让他的攻城坦克能随铁炉堡攻城旅长期部署，这位驾驶员招募当地猎人收集野猪肉和熊皮，以此补给他的机组成员。",h="“为‘喷气蒸汽号’储备物资”是联盟的一项任务，由丹莫罗钢架补给站的驾驶员贝隆·风箱提供。为了让他的攻城坦克能随铁炉堡攻城旅长期部署，这位驾驶员招募当地猎人收集野猪肉和熊皮，以此补给他的机组成员。",kw={"熊皮","野猪肉","丹莫罗","灰色洞穴","喷气蒸汽号","驾驶员贝隆·风箱","攻城旅","钢架补给站"},ang={["faction:Alliance"]="矮人修理厂与攻城旅装甲机组之间的合作，使联盟的前线攻城技术保持运作。",["profession:Cooking"]="在丹莫罗的雪堆中收获大块的野猪肉，凸显了维持当地山地驻军的主食来源。",["race:Dwarf"]="提供来自丹莫罗悬崖的猎物，可以让攻城旅的矮人机组在Khaz Modan的机械工厂工作时吃饱并得到休息。",["race:Gnome"]="协助风箱可以确保铁炉堡流亡侏儒的机械盟友——矮人攻城旅，为即将到来的长期战役获得充足的补给。"},sec={{t="储备引擎补给",b="驾驶员贝隆·风箱驻扎在卡拉诺斯外面的钢架补给站，负责监管即将到来的长期行动准备工作。他的攻城坦克被称为“喷气蒸汽号”，需要机械工程师贝尔丁·钢架进行调试，还需要一个月的野外补给，才能让机组成员在丹莫罗严寒的零下气温中继续工作。"},{t="雪原狩猎",b="由于贝尔丁·钢架正忙着钻在“喷气蒸汽号”的引擎盖下，贝隆·风箱无法离开他的车辆去收集口粮和保暖材料。他指引旅行者前往灰色洞穴南边的雪原狩猎，那里的本土野猪能提供耐吃的肉类，而本地熊则能提供适合用作坦克保暖寝具的厚熊皮。"}},faq={{q="什么是“喷气蒸汽号”？",a="“喷气蒸汽号”是矮人驾驶员贝隆·风箱操作的攻城坦克。它目前驻扎在钢架补给站，正在接受调试和补给，为代表铁炉堡攻城旅进行的长期军事部署做准备。",al={"喷气蒸汽号","喷气蒸汽号是什么","风箱的坦克"}},{q="驾驶员贝隆·风箱是谁？",a="驾驶员贝隆·风箱，绰号“菲泽”，是铁炉堡攻城旅的一名矮人攻城坦克驾驶员。当他的车辆在钢架补给站进行机械调整时，他正在为即将到来的任务协调野外补给。",al={"驾驶员贝隆·风箱","贝隆·风箱","驾驶员贝隆·风箱是谁"}},{q="在哪里可以收集到所需的补给？",a="驾驶员贝隆·风箱指引猎人前往灰色洞穴南面的雪原，那里栖息着当地的野猪和熊，它们的肉和皮可以提供充足的补给和寝具。",al={"野猪在哪里","熊在哪里","狩猎地点","丹莫罗野猪肉"}},{q="什么是攻城旅？",a="攻城旅是铁炉堡的攻城坦克驾驶员部队，操作着像“喷气蒸汽号”和“巨魔犁”这样重装甲战争机器，支援矮人的防御和联盟的战役。",al={"攻城旅"}},{q="这个任务接下来通向哪里？",a="在为“喷气蒸汽号”重新补给肉类和毛皮后，驾驶员贝隆·风箱会派旅行者向西前往烈酒村，执行任务“Evershine”，去寻找一种他用来保暖以及作为坦克火炉紧急燃料的烈性酒。",al={"下一个任务","为喷气蒸汽号储备物资后续","为喷气蒸汽号储备物资后续任务"}},{q="攻城坦克为什么需要动物皮毛？",a="在山区的雪地里进行长期行动时，矮人或侏儒蒸汽坦克的内部既寒冷又有穿堂风。厚熊皮能为机组成员在远离营地的长期驻留期间提供至关重要的温暖和寝具隔热。",al={"为什么需要皮毛","厚熊皮的用途","寝具"}}},fp="17,169,23.257.0,23.248.0,17.177.0,23.202.0,44.114.0,26.174.0,34.201.1,44.185.0"}
P.entries["quest:318"] = {n="艾沃沙酒",s="“永光烈酒”是一项联盟的运送任务，始于卡拉诺斯附近的驾驶员贝隆·风箱。这位矮人攻城坦克驾驶员会派遣旅行者前往西方的烈酒村，去取雷杰德·麦酒酿造的一种强效矮人烈酒。这种烈酒既可以作为暖身饮料，也可以作为风箱的攻城坦克在紧急情况下的高辛烷值燃料。",h="“永光烈酒”是一项联盟的运送任务，始于卡拉诺斯附近的驾驶员贝隆·风箱。这位矮人攻城坦克驾驶员会派遣旅行者前往西方的烈酒村，去取雷杰德·麦酒酿造的一种强效矮人烈酒。这种烈酒既可以作为暖身饮料，也可以作为风箱的攻城坦克在紧急...",kw={"烈酒村","丹莫罗","永光烈酒","喷气蒸气号","卡拉诺斯","驾驶员贝隆·风箱","雷杰德·麦酒"},ang={["profession:Engineering"]="使用易挥发的蒸馏烈酒作为辅助燃料助推器，展现了像风箱这样的驾驶员是如何在恶劣环境中维持他们的攻城坦克运转的。",["race:Dwarf"]="雷杰德·麦酒的强效烈酒展现了寒冷丹莫罗山峰上矮人酿酒传统的火爆极端一面。",["race:Gnome"]="驾驶员贝隆·风箱将平凡的物品——甚至是矮人烈酒——改造成应急燃料的习惯，会让任何侏儒技师印象深刻。"},sec={{t="强效配方",b="矮人的酿酒技术在整个卡兹莫丹都享有盛誉，但雷杰德·麦酒在烈酒村的配方挑战了传统酿造工艺的极限。他酿造的实验性饮品“永光烈酒”非常出名，除了最强壮的矮人外，几乎没人能经得住它的一击。尽管它非常烈，但因其强大的供暖效果，在寒冷的丹莫罗广受推崇。"},{t="驾驶员贝隆·风箱的燃料",b="攻城坦克驾驶员经常会想出一些日常用品的非传统用法，驾驶员贝隆·风箱也不例外。风箱在卡拉诺斯外的钢架补给站工作，他不仅用“永光烈酒”来抵御严寒，还将其作为辅助燃料。将这种易挥发的酒精直接倒入他的攻城坦克“喷气蒸气号”的炉膛中，就能产生一种爆发性的紧急动力，这让他不止一次脱离险境。"}},faq={{q="什么是“永光烈酒”？",a="“永光烈酒”是由烈酒村的矮人酿酒大师雷杰德·麦酒酿造的一种极其浓烈的实验性酒精饮料。它以劲头火爆而闻名，连强壮的矮人饮酒者都能放倒。",al={"什么是永光烈酒","永光烈酒","永光烈酒是什么样的饮料"}},{q="为什么驾驶员贝隆·风箱想要“永光烈酒”？",a="驾驶员贝隆·风箱使用“永光烈酒”既是为了抵御丹莫罗的严寒，也将其作为紧急可燃燃料。当这种易挥发的烈酒倒入他的攻城坦克“喷气蒸气号”的炉膛时，能立即产生一阵推进动力。",al={"为什么风箱想要烈酒","驾驶员贝隆·风箱永光烈酒","为什么风箱需要它"}},{q="烈酒村在哪里？",a="烈酒村位于丹莫罗西部，就在卡拉诺斯以西的道路上。它坐落在雪山附近，是雷杰德·麦酒等当地酿酒师的家园。",al={"烈酒村在哪里","烈酒村位置","寻找烈酒村"}},{q="谁是雷杰德·麦酒？",a="雷杰德·麦酒是一位驻扎在烈酒村的矮人实验酿酒师。他酿造各种各样的饮品，从普通的艾尔啤酒到足以点燃机器炉膛的强效烈酒，应有尽有。",al={"雷杰德是谁","雷杰德·麦酒信息","麦酒酿酒师"}},{q="到达雷杰德·麦酒处后接下来做什么？",a="如果没有帮助，雷杰德是不会交出他珍贵的烈酒的。到达烈酒村后，玩家将接到任务“永光烈酒的谢礼”，必须先帮助这位酿酒师，他才会为驾驶员贝隆·风箱交出一桶酒。",al={"永光烈酒后的下一个任务","永光烈酒之后做什么","雷杰德任务后续"}},{q="“永光烈酒”真的可以安全饮用吗？",a="据驾驶员贝隆·风箱所说，“永光烈酒”足以放倒几乎任何尝试饮用的矮人。虽然从技术上讲，铁胃的深山居民可以饮用，但其极强的易燃性使它同样适合用作坦克炉膛的燃料。",al={"可以喝永光烈酒吗","永光烈酒有毒吗","永光烈酒危险吗"}}},fp="9,179,19.179.0,24.268.0,18.177.0,40.201.0,26.144.0,25.171.0,49.181.1,33.188.0"}
P.entries["quest:3181"] = {n="玛尔戈的巨角",s="这只巨大的号角来自灼热峡谷的怒火玛戈尔，表面满是划痕和裂纹，还嵌着一个断裂的斧头。斧头上刻着这是巡山人贝波蒂所有的标记，当你试图将其取出时，它瞬间碎成了无数碎片。这只号角需要交给贝波蒂。",h="这只巨大的号角来自灼热峡谷的怒火玛戈尔，表面满是划痕和裂纹，还嵌着一个断裂的斧头。斧头上刻着这是巡山人贝波蒂所有的标记，当你试图将其取出时，它瞬间碎成了无数碎片。这只号角需要交给贝波蒂。",kw={"巨大的号角","洛克莫丹","怒火玛戈尔","贝波蒂","灼热峡谷","石坝小径"},sec={{t="破碎的线索",b="来自怒火玛戈尔的号角上布满了划痕和裂纹。上面嵌着一个不同寻常的金属物体，那是一个断裂的斧头，上面刻着的标记表明它属于巡山人贝波蒂。当你试图将它弄出来时，它却碎成了无数碎片。"},{t="大门",b="这只号角开启了通往石坝小径的任务线，这条小径连接着洛克莫丹和灼热峡谷。它需要交给巡山人贝波蒂，但她并不愿意打开那扇大门。"},{t="在大门口",b="贝波蒂说这只号角显然是伪造的。她曾与玛戈尔正面交锋，贝波蒂说她的号角要大得多，至少是你这只的八倍大，而你这只很可能是从贫瘠之地的风鼻兽身上弄下来的。"}},faq={{q="这只号角从何而来？",a="它来自灼热峡谷的怒火玛戈尔。",al={"哪里可以找到号角","怒火玛戈尔的位置","谁掉落号角"}},{q="谁是巡山人贝波蒂？",a="贝波蒂就是那个需要接收号角的巡山人，她也不愿意打开那扇大门。",al={"贝波蒂","谁是贝波蒂","巡山人贝波蒂"}},{q="号角里的斧头怎么了？",a="上面刻着它是巡山人贝波蒂的财产，当你试图将其取出时，它碎成了无数碎片。",al={"为什么贝波蒂的斧头会在号角里","斧头上的铭文"}},{q="这只号角会引出什么？",a="它开启了打通石坝小径的任务线，连接了洛克莫丹和灼热峡谷。",al={"石坝小径","什么是通往灼热峡谷的大门钥匙"}}},fp="21,316,16.250.0,8.188.0,11.233.1,31.48.0,31.112.0,41.123.0,27.103.1"}
P.entries["quest:319"] = {n="艾沃沙酒",s="为了帮钢架补给站的驾驶员贝隆·风箱弄到一桶永光酒，冒险者必须先帮帮烈酒村。酿酒师雷杰德·麦酒拒绝交出他的酒，除非先清理掉在附近雪堆中游荡的危险掠食者。",h="为了帮钢架补给站的驾驶员贝隆·风箱弄到一桶永光酒，冒险者必须先帮帮烈酒村。酿酒师雷杰德·麦酒拒绝交出他的酒，除非先清理掉在附近雪堆中游荡的危险掠食者。",kw={"贝隆·风箱","烈酒村","丹莫罗","成年峭壁野猪","永光酒","冰爪熊","雷杰德·麦酒","雪豹"},ang={["class:Hunter"]="清理丹莫罗西部的凶猛掠食者是对射击技术的考验，对手是峭壁上最强壮的冬季野兽。",["race:Dwarf"]="每一个矮人都明白让野生掠食者远离酿酒坊的重要性，这样才能确保烈酒村传奇的酒桶不被干扰。",["race:Gnome"]="钢架补给站的攻城机器驾驶员和技工们急切地等待着这桶酒，他们指望着冒险者能安抚那位固执的酿酒师，好让“喷气蒸汽号”的准备工作能够继续。"},sec={{t="酿酒师的交易",b="雷杰德·麦酒确实有驾驶员贝隆·风箱需要的永光酒，但他并不急着免费交出这珍贵的佳酿。雷杰德想要的不是钱，而是保护。丹莫罗西部的野生猛兽——贪婪的冰爪熊、皮糙肉厚的成年峭壁野猪，还有徘徊的雪豹——在烈酒村附近游荡，令当地居民感到不安，也造成了持续不断的干扰和危险。"},{t="工匠的安宁",b="虽然雷杰德坚持说没有一个自尊的矮人会畏惧野兽，但全天候应付这些掠食者会浪费宝贵的生产时间。清理掉当地的野生动物能让村民们获得安宁，从而专注于酿造和锻造工作，不必总是提心吊胆地盯着树林边缘。"}},faq={{q="雷杰德为什么要杀掉这些动物？",a="徘徊的熊、野猪和雪豹在烈酒村附近游荡。虽然矮人们并不怕它们，但驱赶它们会浪费本可以用于酿造和锻造的宝贵工作时间。",al={"为什么要杀熊","为什么要清理烈酒村的动物","雷杰德的任务原因"}},{q="永光酒是什么？",a="永光酒是一种烈性、著名的酒，由雷杰德·麦酒在烈酒村独家酿造。像驾驶员贝隆·风箱这样的攻城机器驾驶员觉得它非常有价值，既可以作为饮品，也可以作为一种易燃的燃料添加剂。",al={"什么是永光酒","永光酒酿造","雷杰德的酒"}},{q="谁最初想要永光酒？",a="钢架补给站的驾驶员贝隆·风箱派你去获取它，好让他在这路上保持温暖，并将其投入他自己的攻城机器“喷气蒸汽号”的熔炉中，以获得爆发性的动力。",al={"谁派我去取永光酒","谁想要永光酒","任务链开始"}},{q="去哪里可以找到这些动物？",a="它们在丹莫罗西部的烈酒村和涌冰湖周围的冰冻原野和峭壁上游荡。",al={"冰爪熊在哪里","雪豹位置","成年峭壁野猪位置"}},{q="完成这个委托后会发生什么？",a="一旦清理完野兽，雷杰德就会交出那桶永光酒，让你直接把它带回钢架补给站交给驾驶员贝隆·风箱。",al={"后续任务","完成永光酒的委托后"}},{q="村民们真的受到掠食者的威胁吗？",a="雷杰德坚持认为没有一个自尊的矮人会怕雪地里的野兽，但在家门口就有危险的掠食者咆哮着，会对日常工作造成持续的干扰和危险。",al={"烈酒村有危险吗","矮人害怕吗"}}},fp="21,187,18.238.0,23.265.0,42.176.0,18.185.0,39.168.0,31.108.0,40.120.0,54.133.0"}
P.entries["quest:32"] = {n="异种蝎的威胁",s="高级勘探员菲兹杜瑟将关于虫群威胁的报告交给你，并催促你把它送到奥格瑞玛，交给一位名叫基尔兹宾·鼓眼的巨魔学者。",h="高级勘探员菲兹杜瑟将关于虫群威胁的报告交给你，并催促你把它送到奥格瑞玛，交给一位名叫基尔兹宾·鼓眼的巨魔学者。",kw={"暗影裂口","鼓眼","菲兹杜瑟","昆虫","奥格瑞玛","其拉虫人","塔纳利斯","基尔兹宾"},sec={{t="知情者",b="菲兹杜瑟希望这份报告能交到一位对此类事务有深入了解的人手中。基尔兹宾·鼓眼是一位巨魔学者，他花了很多时间研究艾泽拉斯生态中独特的生命形式，此外他还是一位历史学家。菲兹杜瑟希望基尔兹宾能弄清楚真正的危险究竟是什么，以及该如何阻止它，并表示需要一切能够提供的帮助。基尔兹宾住在奥格瑞玛暗影裂口的第二层。"},{t="基尔兹宾的回答",b="基尔兹宾以前处理过这些生物，并认为菲兹杜瑟把报告交给你是一个明智的选择。它们会迅速吞噬塔纳利斯沙漠，是任何人所面临的最大威胁之一。它们就是其拉虫人，是部落和联盟所面临的最严峻威胁之一的工具。基尔兹宾感叹没有人有足够的远见能早点发现这一点。"}},faq={{q="基尔兹宾·鼓眼是谁？",a="一位巨魔学者和历史学家，他花费了大量时间研究艾泽拉斯生态系统中独特的生命形式。",al={"谁是鼓眼","基尔兹宾·鼓眼背景故事","奥格瑞玛的巨魔学者"}},{q="是谁派你去找基尔兹宾的？",a="高级勘探员菲兹杜瑟，他给了你这份报告，并让你把它带到奥格瑞玛。",al={"其拉虫人的崛起起始","谁给予其拉虫人的崛起任务"}},{q="基尔兹宾·鼓眼在奥格瑞玛的什么位置？",a="在奥格瑞玛暗影裂口，第二层的一间屋子里。",al={"基尔兹宾在哪里","鼓眼的房子在哪里"}},{q="这一步之前是什么？",a="它紧接在“昆虫分析”之后。",al={"其拉虫人的崛起前置任务","什么导致了其拉虫人的崛起"}}},fp="20,153,17.452.0,17.367.1,25.115.0,26.93.0,48.60.0,37.32.0"}
P.entries["quest:320"] = {n="艾沃沙酒",s="“回到驾驶员贝隆·风箱处”是丹莫罗的一个短途配送任务，冒险者需要将一桶当地酿造的永恒之光送给位于钢架补给站的驾驶员贝隆·风箱。这个任务结束了一次当地的委托，为口渴的驾驶员送去了一杯令人愉悦的佳酿。",h="“回到驾驶员贝隆·风箱处”是丹莫罗的一个短途配送任务，冒险者需要将一桶当地酿造的永恒之光送给位于钢架补给站的驾驶员贝隆·风箱。这个任务结束了一次当地的委托，为口渴的驾驶员送去了一杯令人愉悦的佳酿。",kw={"永恒之光酒桶","丹莫罗","永恒之光","卡拉诺斯","驾驶员贝隆·风箱","回到贝隆·风箱处","钢架补给站"},ang={["faction:Alliance"]="在矮人猎人和矮人驾驶员之间奔走传信有助于维持驻扎在丹莫罗的联盟部队的士气和同志情谊。",["race:Dwarf"]="像永恒之光这样醇厚的矮人佳酿在整个丹莫罗总是供不应求，将其安全送到口渴的战友手中简直是理所当然的事。",["race:Gnome"]="驾驶员贝隆·风箱是一位驻扎在钢架补给站的矮人攻城机驾驶员，让辛勤工作的工程师们保持精力充沛有助于维持机械的平稳运转。"},sec={{t="给补给站的一桶酒",b="“回到驾驶员贝隆·风箱处”是丹莫罗雪原上的一个差事。在协助当地的狩猎活动后，冒险者会收到一桶刚酿好的永恒之光，并被指派将其直接送到钢架补给站的驾驶员贝隆·风箱手中。这是一件简单的顺手之劳，彰显了在这片寒冷的边境地区，人们之间那种非正式的同志情谊和相互支持的精神。"},{t="口渴的驾驶员",b="钢架补给站是卡拉诺斯外的一个繁忙中心，主要负责机械测试、车辆维护和侏儒工艺。对于驻扎在寒风中的飞行员来说，没有什么比喝上一口烈性的当地佳酿更让人满足的了。驾驶员贝隆·风箱在收到酒后毫不耽搁，急切地当场启瓶，享受着当地酿酒师的劳动成果。"}},faq={{q="任务“回到驾驶员贝隆·风箱处”是什么？",a="“回到驾驶员贝隆·风箱处”是丹莫罗的一个运送任务，冒险者需要将一桶刚得到的永恒之光直接送给位于钢架补给站的驾驶员贝隆·风箱。",al={"回到贝隆·风箱处任务","贝隆·风箱任务"}},{q="驾驶员贝隆·风箱是谁？",a="驾驶员贝隆·风箱是一位矮人攻城机驾驶员，驻扎在丹莫罗卡拉诺斯外的钢架补给站。他正热切地等待着新鲜的永恒之光送来品尝。",al={"谁想要永恒之光","贝隆·风箱是谁"}},{q="永恒之光是什么？",a="永恒之光是一种在丹莫罗酿造的强劲当地佳酿，装在结实的木桶里，深受口渴的飞行员和当地人的喜爱。",al={"什么是永恒之光","永恒之光酒桶"}},{q="应该把酒桶送到哪里？",a="驾驶员贝隆·风箱位于钢架补给站，那是一个位于丹莫罗卡拉诺斯以东的工程中心和工作坊。",al={"贝隆·风箱在哪里","贝隆·风箱位置"}},{q="为什么要给贝隆·风箱送去永恒之光？",a="在协助该地区的狩猎任务后，冒险者受托将一桶永恒之光送给一直热切期盼着能尝上一口的驾驶员贝隆·风箱。",al={"为什么要运送永恒之光","运送永恒之光的原因"}},{q="当贝隆·风箱收到永恒之光时会发生什么？",a="在收到木桶后，驾驶员贝隆·风箱感到非常满意，他说这酒很不错，并立即动手启瓶品尝。",al={"贝隆·风箱怎么处理酒","贝隆·风箱的反应"}}},fp="19,233,20.367.0,16.361.0,38.167.0,23.182.0,30.127.0,30.127.0,40.177.0,51.160.0"}
P.entries["quest:321"] = {n="光铸铁",s="“圣铸铁”是戈罗林·钢眉在米奈希尔港发布的一项联盟打捞任务。冒险者被派往搜索“飞鱼号”的残骸，这是一艘精灵驱逐舰，在第二次战争期间，它随库尔提拉斯第三舰队一同失踪，船上载有珍贵的圣洁金属。",h="“圣铸铁”是戈罗林·钢眉在米奈希尔港发布的一项联盟打捞任务。冒险者被派往搜索“飞鱼号”的残骸，这是一艘精灵驱逐舰，在第二次战争期间，它随库尔提拉斯第三舰队一同失踪，船上载有珍贵的圣洁金属。",kw={"飞鱼号","戈罗林·钢眉","金属锭","库尔提拉斯","圣铸铁","米奈希尔港","鱼人","第三舰队","浸水的箱子","湿地"},ang={["class:Paladin"]="用圣铸铁锻造的武器与圣光有着深刻的共鸣，即使找回一枚丢失的金属锭也具有重要的精神意义。",["faction:Alliance"]="米奈希尔港外的沉船是第二次战争中令人悲痛的纪念碑，库尔提拉斯和洛丹伦的勇敢水手们在那里倒在了龙火之下。",["profession:Blacksmithing"]="各门派的铁匠都将圣铸铁视为材料界的圣杯，它以蕴含强大的祝福和无与伦比的结构稳定性而闻名。"},sec={{t="圣洁货物",b="虽然散落在湿地海岸线上的大多数沉船残骸都属于著名的库尔提拉斯第三舰队，但有一艘船与众不同：一艘名为“飞鱼号”的精灵驱逐舰。该船从洛丹伦出发，试图跟随海军舰队以寻求庇护，船上运载着珍贵的圣铸铁货物。不幸的是，当龙喉氏族的兽人驾驭着被奴役的红龙从天而降时，与战舰同行的保护作用微乎其微。他们焚毁了舰队，将士兵和圣洁的金属一同沉入了海底。"},{t="潮汐掠夺者",b="到达米奈希尔港以南“飞鱼号”的破碎残骸处，会发现时间与大海并不是唯一的破坏者。装载着货物的被水浸透的箱子已被撬开并遭到翻找。海岸鱼人作为沉船的常客，早已洗劫了船舱并将金属锭四处散落，几乎没给戈罗林·钢眉留下任何珍贵矿石的踪迹。"}},faq={{q="什么是“飞鱼号”？",a="“飞鱼号”是一艘在第二次战争期间从洛丹伦驶出的精灵驱逐舰。它运载着一批稀有的圣铸铁，并随库尔提拉斯第三舰队同行以寻求保护，但最终与舰队其余船只一起被受兽人奴役的红龙焚毁并沉没。",al={"飞鱼号背景故事","湿地精灵驱逐舰","哪艘船载有圣铸铁"}},{q="戈罗林·钢眉是谁？",a="戈罗林·钢眉是一位驻扎在湿地米奈希尔港的矮人。他致力于从海岸线的沉船中回收历史遗物和贵重材料，尤其是像圣铸铁这样的传奇金属。",al={"戈罗林·钢眉","米奈希尔港的矮人","谁发布圣铸铁任务"}},{q="什么是圣铸铁？",a="圣铸铁是一种极其罕见的圣洁金属，用于锻造神圣的武器和盔甲。因其纯净和强大的精神属性，它受到圣光追随者和铁匠们的高度珍视。",al={"圣铸铁金属","什么是圣铸铁","圣铸铁锭"}},{q="为什么这些船只在湿地沉没？",a="在第二次战争期间，部落的龙喉氏族利用恶魔之魂奴役了红龙军团。巨龙骑士在湿地海岸外袭击了库尔提拉斯第三舰队，烧毁了船只并将它们送入海底。",al={"谁击沉了第三舰队","为什么湿地有沉船","湿地红龙舰队"}},{q="为什么箱子几乎是空的？",a="“飞鱼号”上那个被水浸透的箱子上有明显的鱼人利爪抓痕。这些生物撬开了箱子并掠走了货物，带走了大部分金属锭，并将它们散落在泥泞的岸边。",al={"金属锭在哪里","为什么箱子有抓痕","谁偷了圣铸铁"}},{q="“飞鱼号”的残骸位于何处？",a="残骸位于米奈希尔港以南的海岸浅滩，沿着湿地的西岸散布在当地鱼人聚居地附近的浅水区。",al={"飞鱼号位置","箱子在哪里","湿地沉船位置"}}},fp="15,197,14.334.0,22.251.1,26.235.0,24.213.0,24.167.0,40.227.0,30.162.0,51.192.0"}
P.entries["quest:322"] = {n="格瑞曼德·艾尔默",s="在湿地的“飞翔的鱼鹰号”残骸中打捞出光铸铁锭后，冒险者受命将这批珍贵的金属运往暴风城。在那里，矮人铁匠大师格里曼德·艾尔莫正等待着将这些原始金属打造为能够对抗死灵法师摩本特·菲尔的利器。",h="在湿地的“飞翔的鱼鹰号”残骸中打捞出光铸铁锭后，冒险者受命将这批珍贵的金属运往暴风城。在那里，矮人铁匠大师格里曼德·艾尔莫正等待着将这些原始金属打造为能够对抗死灵法师摩本特·菲尔的利器。",kw={"祝福武器","dwarven district","戈罗林·钢眉","格里曼德·艾尔莫","光铸铁","洛克莫丹","摩本特·菲尔","暴风城"},ang={["class:Paladin"]="携带神圣的铁料来打造对抗暮色森林死灵法师的武器，这呼应了白银之手骑士团的核心使命：以神圣的警觉净化黑暗巫术。",["faction:Alliance"]="这次运输展示了各王国间的紧密合作，将米奈希尔港的矮人牧师与暴风城矮人区的熔炉连接起来，以援助暮色森林陷入困境的人们。",["profession:Blacksmithing"]="光铸铁是一种稀有且难以驾驭的金属；观察像格里曼德·艾尔莫这样经验丰富的矮人铁匠承担这项任务，凸显了锻造圣物所需的高超工艺。"},sec={{t="失而复得的稀有金属",b="光铸铁并非普通市场摊位上随处可见的交易金属。它因对邪恶与不洁之物具有特殊的感应力而闻名，需要一位了解其特质与脾性的铁匠来锻造。在从湿地海岸外的“飞翔的鱼鹰号”残骸中找回这批货物后，戈罗林·钢眉将回收的铁锭装入一个坚固的板条箱中。他知道南部王国中只有一位工匠有能力加工这种非凡的材料：铁匠大师格里曼德·艾尔莫。"},{t="矮人区的熔炉",b="格里曼德·艾尔莫在暴风城矮人区那烟尘弥漫、叮当作响的环境中经营着城中最出色的铁砧之一。当收到找回的这批货物时，艾尔莫提到他已经多年没有锻造过光铸铁了。这位资深工匠对这项英勇的任务深感兴趣，也渴望给死灵法师摩本特·菲尔以沉重打击，因此欣然同意出手相助。"}},faq={{q="这次运输的目的是什么？",a="板条箱里装的是从湿地的“飞翔的鱼鹰号”残骸中打捞出来的光铸铁。戈罗林·钢眉将其送往格里曼德·艾尔莫处，以便这位技艺精湛的铁匠能将这种神圣的金属塑造成足以对抗死灵法师摩本特·菲尔的武器。",al={"为什么要将铁锭送到暴风城","祝福武器的目的","一箱光铸铁锭有什么用"}},{q="格里曼德·艾尔莫是谁？",a="格里曼德·艾尔莫是一位受人尊敬的矮人武器匠，在暴风城的矮人区经营生意。他是少数几位具备锻造光铸铁这类特殊金属所需培训与技能的工匠之一。",al={"格里曼德·艾尔莫的背景","矮人区的铁匠是谁"}},{q="为什么光铸铁在对抗摩本特·菲尔时如此重要？",a="摩本特·菲尔是一位难以捉摸且强大的死灵法师，受到黑暗魔法的庇护。普通的武器难以刺穿他不洁的防御，因此必须使用由神圣的光铸铁锻造的武器来剥离他的保护，使他变得脆弱。",al={"为什么选择光铸铁","光铸铁如何伤害摩本特·菲尔"}},{q="戈罗林·钢眉让你去哪里？",a="戈罗林·钢眉让你从湿地的米奈希尔港前往暴风城的矮人区，格里曼德·艾尔莫的熔炉就在那里。",al={"我该去哪里完成祝福武器任务","格里曼德·艾尔莫的位置"}},{q="格里曼德·艾尔莫以前锻造过光铸铁吗？",a="是的。在检查金属后，格里曼德提到他已经多年没有处理过光铸铁了，并对能再次用这种传奇材料施展技艺感到高兴。",al={"格里曼德以前锻造过光铸铁吗","艾尔莫的锻造经验"}},{q="武器完成前必须发生什么？",a="格里曼德同意将找回的光铸铁锻造成摩本特的克星。武器完成后，必须将其送往暮色森林的斯温·约根手中。",al={"祝福武器之后是什么","武器是立刻锻造好的吗"}}},fp="11,236,20.355.0,28.315.0,37.202.0,22.167.0,56.155.0,37.127.0,54.135.0,51.143.0"}
P.entries["quest:3221"] = {n="与伦弗利尔会面",s="“与伦弗利尔谈话”是银松森林中瑟伯切尔内的一个简短任务。高级执行官哈德瑞克指引你回到皇家药剂师学会的当地研究员那里，讨论关于受污染狼心的发现。",h="“与伦弗利尔谈话”是银松森林中瑟伯切尔内的一个简短任务。高级执行官哈德瑞克指引你回到皇家药剂师学会的当地研究员那里，讨论关于受污染狼心的发现。",kw={"哈德瑞克","伦弗利尔","皇家药剂师学会","瑟伯切尔","银松森林","狼心"},ang={["faction:Horde"]="随着部落在洛丹伦建立据点，了解影响当地野兽的腐化对于确保荒野的安全至关重要。",["race:Undead"]="皇家药剂师学会与瑟伯切尔的军事指挥部密切合作，确保对银松森林中的每一种生物异常现象进行研究，从而服务于黑暗女王的目标。"},sec={{t="学会的传唤",b="在协助银松森林各处的死亡猎手之后，高级执行官哈德瑞克会转交一份来自药剂师伦弗利尔的紧急信件。伦弗利尔一直在分析从当地野生动物身上收集到的变色狼心，并要求你立即前往。"},{t="炼金奇事",b="药剂师伦弗利尔在瑟伯切尔墓穴内的实验室为皇家药剂师学会效力。他正在进行的研究旨在探索黑暗魔法和疾病是如何改变银松森林野兽的，以此将前线军事侦察与化学研究联系起来。"}},faq={{q="药剂师伦弗利尔在哪里？",a="药剂师伦弗利尔位于银松森林中部瑟伯切尔的墓穴内，他站在炼金设备旁，距离高级执行官哈德瑞克仅几步之遥。",al={"伦弗利尔位置","伦弗利尔在哪里","寻找伦弗利尔"}},{q="药剂师伦弗利尔为什么要找我谈话？",a="伦弗利尔一直在分析从当地银松狼身上收集到的变色狼心，并发现了它们腐化过程中的特殊之处，这需要进一步调查并与幽暗城进行沟通。",al={"伦弗利尔为什么找我","伦弗利尔狼心"}},{q="是谁派你去见伦弗利尔的？",a="高级执行官哈德瑞克，即瑟伯切尔的被遗忘者军事指挥官，会在你从协助他的死亡猎手归来后，将伦弗利尔的传唤转交给你。",al={"谁发布与伦弗利尔谈话任务","任务发布者"}},{q="这次谈话之后会发生什么？",a="与伦弗利尔交谈将直接引出相关任务，这些任务有助于将瑟伯切尔的区域炼金研究与幽暗城的药剂师金格等高级成员联系起来。",al={"与伦弗利尔谈话后续任务","伦弗利尔后续"}}},fp="20,179,24.235.0,22.251.0,38.149.0,52.168.0,27.141.0,31.164.0"}
P.entries["quest:323"] = {n="证明你的实力",s="“证明你的价值”是斯温·约根在暮色森林西部复仇行动中的关键一步。在允许冒险者直接对抗死灵法师摩尔本·菲尔之前，这位悲痛的隐士要求证明他们有能力击败盘踞在乌鸦岭墓地的亡灵军团。",h="“证明你的价值”是斯温·约根在暮色森林西部复仇行动中的关键一步。在允许冒险者直接对抗死灵法师摩尔本·菲尔之前，这位悲痛的隐士要求证明他们有能力击败盘踞在乌鸦岭墓地的亡灵军团。",kw={"黑暗骑士","暮色森林","荒弃鬼屋","摩尔本·菲尔","证明你的价值","乌鸦岭墓地","骷髅治疗者","骷髅掠夺者","骷髅守卫","斯温·约根"},ang={["class:Paladin"]="净化乌鸦岭墓地中摩尔本·菲尔的躁动死者是神圣的工作，用圣光的正义回应暮色森林逝者未被掩埋的哀嚎。",["class:Priest"]="黑暗仪式对乌鸦岭墓地的亵渎呼唤着精神上的净化，终结那些扭曲生死、祸害世间的守卫和治疗者。",["faction:Alliance"]="由于缺乏常规的暴风城巡逻队，暮色森林西部已经陷入无政府状态，这使得像斯温这样饱受摧残的边境居民只能完全依赖流浪的勇士来击退亡灵天灾。"},sec={{t="苦涩隐士的考验",b="斯温·约根躲藏在喧嚣森林以北的一处偏僻营地中，因家人的惨死而饱受悲痛与愤怒的折磨。他已经拼凑出线索，摧毁他家园的暗影黑暗骑士与一名名叫摩尔本·菲尔的邪恶死灵法师结盟。尽管斯温渴望复仇，但他并非鲁莽之徒，不会将未经考验的新兵直接推向菲尔的魔爪。他要求冒险者展示出高超的战斗技巧，以击败占据乌鸦岭墓地的骷髅大军。"},{t="乌鸦岭墓穴",b="为了满足斯温的要求，冒险者必须深入位于荒弃鬼屋以南的乌鸦岭墓地。在菲尔邪恶魔法的束缚下，陵墓及其周边地区到处都是躁动的尸体：挥舞长剑的骷髅掠夺者在墓碑间游荡，而骷髅守卫和治疗者则照看著地下深处的黑暗密室。清理这支先锋部队是一场血腥的苦差事，尤其是当复仇幻影摩拉迪姆这样的恐怖存在在墓地小径上游荡时。"},{t="通往死灵法师之路",b="在布满白骨的地下墓穴中幸存下来，这让斯温确信他的盟友不仅仅只有匹夫之勇。然而，击败菲尔的爪牙只是序幕。摩尔本·菲尔掌握着黑暗的保护附魔，使他在普通武器面前几乎毫发无伤，这迫使斯温必须在最终决战开始前寻求更伟大的智慧和上古遗物。"}},faq={{q="为什么在面对摩尔本·菲尔之前，斯温要让我去对付骷髅？",a="斯温知道摩尔本·菲尔是一位与神秘黑暗骑士结盟的致命死灵法师。在他们证明自己拥有切开整支亡灵先锋部队所需的耐力和战术技巧之前，他拒绝让盟友去送死。",al={"为什么要证明你的价值","为什么斯温要我杀骷髅","斯温的考验"}},{q="哪里可以找到骷髅守卫和治疗者？",a="虽然骷髅掠夺者在荒弃鬼屋以南的开阔墓地游荡，但骷髅治疗者和守卫主要集中在墓地中心以西的大型陵墓和地下墓穴隧道内及其周围。",al={"守卫在哪里","骷髅治疗者在哪里","寻找骷髅守卫"}},{q="摩拉迪姆是谁，我为什么要在这里提防他？",a="摩拉迪姆是一位强大而悲惨的亡灵骑士，他会在乌鸦岭墓地的小径上游荡。他比墓穴周围的普通骷髅强大得多，会迅速斩杀粗心大意的冒险者。",al={"摩拉迪姆的危险","摩拉迪姆是谁","乌鸦岭游荡的精英"}},{q="摩尔本·菲尔与黑暗骑士有什么关联？",a="斯温发现摩尔本·菲尔与屠杀他妻儿的披风黑暗骑士结盟。虽然骑士们消失在阴影中，但菲尔仍驻扎在暮色森林，继续他的邪恶死灵法术。",al={"摩尔本·菲尔与黑暗骑士的联系","为什么黑暗骑士和菲尔结盟","斯温家人的凶手"}},{q="完成这个任务后会发生什么？",a="一旦证明了你的战斗实力，斯温会认可你的力量，但也会解释说摩尔本·菲尔不能仅靠蛮力杀死。他会指引你去暴风城的Cathedral of Light寻求主教法席恩的建议，以找到剥除死灵法师邪恶保护的方法。",al={"证明你的价值后的下一个任务","消灭骷髅后做什么"}},{q="斯温·约根的营地在哪里？",a="斯温在暮色森林最西北边缘的山丘上维持着一处隐蔽的营地，安全地隐藏在乌鸦岭以北、通往西部荒野的道路以西。",al={"斯温在哪里","斯温的营地位置"}}},fp="18,189,22.415.0,21.380.0,27.277.1,64.178.0,49.187.0,57.152.0,48.200.0,41.216.1,36.136.0"}
P.entries["quest:324"] = {n="丢失的铁锭",s="“丢失的铸块”是联盟在湿地执行的一项任务，旨在从沉船中回收圣化金属。在沉没的宝箱中只找到一根铸块后，旅行者们必须去搜寻掠夺了剩余货物的当地蓝腮鱼人。",h="“丢失的铸块”是联盟在湿地执行的一项任务，旨在从沉船中回收圣化金属。在沉没的宝箱中只找到一根铸块后，旅行者们必须去搜寻掠夺了剩余货物的当地蓝腮鱼人。",kw={"蓝腮","飞鱼号","戈罗林·钢眉","铸块","光铸铁","鱼人","浸水的宝箱","湿地"},ang={["class:Paladin"]="从原始鱼人手中回收光铸铁，能确保圣洁的材料被保存下来，用于制造适合作为圣光勇士使用的圣化武器。",["profession:Blacksmithing"]="每一位金属工匠都知道，看到像光铸铁这样优质的原材料最终变成沿海鱼人巢穴里的珍品，而不是出现在铁砧上，是一件多么令人痛心的事情。",["race:Dwarf"]="回收丢失的杰作级矿石，并将其交到像戈罗林·钢眉这样的矮人牧师手中，是对矮人锻造传统和回收者传统的致敬。"},sec={{t="被劫掠的沉船",b="在湿地多雾的海岸外，躺着飞鱼号的残骸。为了给矮人牧师戈罗林·钢眉取回珍贵的光铸铁，寻宝者们发现货舱里的浸水宝箱几乎是空的。贪婪的当地蓝腮鱼人已经抢掠了船只的其余部分，将闪闪发光的铸块据为己有。"},{t="收回圣洁金属",b="光铸铁并非普通的矿石；它是一种稀有、特殊的金属，能够用于圣洁的锻造工艺。对于一位圣光矮人来说，任由这些金属在鱼人营地中腐烂是无法想象的。通过狩猎那些在破碎船体附近的浅滩上蜂拥而至的蓝腮劫掠者，冒险者们夺回了散落的铸块，以便戈罗林·钢眉能将这些铁锭锻造成武器。"}},faq={{q="哪艘船运载了光铸铁？",a="货物是搭乘飞鱼号抵达的，这艘不幸的船只在湿地海岸外遭遇了劫难。它破碎的木材残骸现在部分淹没在浅滩中。",al={"哪艘船","飞鱼号","沉船名称"}},{q="为什么宝箱里没有铸块？",a="浸水的宝箱里只剩下一根铸块。沿海的蓝腮鱼人已经撬开了沉没的残骸，掠走了剩余的货物，并将其散布在它们的沿海劫掠者之间。",al={"铸块在哪里","为什么鱼人持有铁锭","宝箱是空的"}},{q="戈罗林·钢眉是谁？",a="戈罗林·钢眉是一位圣光教会的矮人牧师，位于米奈希尔港的深水旅店中。他是主教法席恩的同事，他寻找光铸铁是为了打造一把对抗死灵法师摩本特·费尔的武器。",al={"戈罗林","戈罗林·钢眉是谁","任务发布者"}},{q="光铸铁有什么特别之处？",a="光铸铁是一种稀有的圣洁金属，对神圣附魔和锻造有着独特的感应。它受到那些制作与圣光相符的武器装备的工匠们的推崇。",al={"光铸铁背景","什么是光铸铁","为什么铁锭很重要"}},{q="是哪些鱼人拿走了铁锭？",a="蓝腮部落，特别是那些在飞鱼号残骸周围的浅滩和海滩上徘徊的鱼人劫掠者，夺走了丢失的铸块。",al={"谁偷了铸块","哪个部落","蓝腮劫掠者"}},{q="交还铸块后接下来要做什么？",a="一旦戈罗林·钢眉收齐了所有的铸块，他会将这些圣洁的金属装进一个板条箱，并派你去暴风城找武器匠格里曼德·艾尔莫尔进行锻造，任务将继续进入“受福武器”。",al={"下一个任务","戈罗林做什么","受福武器任务"}}},fp="15,151,21.270.0,27.250.0,38.141.0,37.121.0,24.226.0,38.140.0,28.114.0,43.189.1"}
P.entries["quest:325"] = {n="整装待发",s="“武装待命”标志着铸造一把专为剥离死灵法师摩本特·费尔的邪恶防御而设计的武器的圆满完成。在获得了格里曼德·埃尔默的精湛手艺后，这位冒险者带着“摩本特的克星”渡河回到暮色森林，交给了复仇心切的斯温·约根。",h="“武装待命”标志着铸造一把专为剥离死灵法师摩本特·费尔的邪恶防御而设计的武器的圆满完成。在获得了格里曼德·埃尔默的精湛手艺后，这位冒险者带着“摩本特的克星”渡河回到暮色森林，交给了复仇心切的斯温·约根。",kw={"武装待命","暮色森林","格里曼德·埃尔默","摩本特·费尔","摩本特的克星","乌鸦岭","暴风城","斯温·约根"},ang={["class:Paladin"]="优质矮人钢铁与神圣祝圣的结合，呼应了圣骑士将神圣光芒注入武术装备以粉碎亡灵结界的传统。",["faction:Alliance"]="暴风城的工匠与暮色森林的前线幸存者之间的协作，突显了联盟必须利用其首都的专业知识来清除蔓延的枯萎病。",["profession:Blacksmithing"]="格里曼德·埃尔默的手艺展示了精湛的锻造技术如何与神圣仪式相结合，从而打造出对抗超自然威胁的特制武器。"},sec={{t="锻造武器",b="摩本特·费尔对乌鸦岭墓地的掌控似乎坚不可摧。常规的钢铁在笼罩着这位死灵法师的黑暗结界面前要么粉碎，要么被毫无伤痕地弹开。要克服这种邪恶的魔法，需要一件专门的圣物：“摩本特的克星”。随着金属在暴风城的Dwarven District由格里曼德·埃尔默塑形，并经由神圣力量的祝圣，这件破除结界的圣物终于完成了，随时准备切断费尔与亡灵的联系。"},{t="回到隐士身边",b="将“摩本特的克星”带回暮色森林为斯温·约根带来了希望，他目睹了自己的家人和农场成为不断蔓延的黑暗的牺牲品。驻扎在森林西部边界附近那个孤寂营地的斯温，一眼就看出了这位旅者眼中的火光，以及这把武器所蕴含的神圣工艺。随着这件破除结界的圣物交付，向乌鸦岭的主人发起直接攻击的舞台已经搭好。"}},faq={{q="什么是“摩本特的克星”？",a="“摩本特的克星”是一把经过专门锻造和祝圣的武器，旨在刺穿乌鸦岭死灵法师摩本特·费尔周围那不可摧毁的魔法结界。",al={"摩本特的克星","什么是该武器","摩本特的克星之剑"}},{q="是谁打造了这把武器？",a="居住在暴风城的Dwarven District的熟练铁匠格里曼德·埃尔默，用祝圣过的圣光锻铁打造了这把破除结界的武器。",al={"谁制作了摩本特的克星","格里曼德·埃尔默的角色"}},{q="我该把“摩本特的克星”交给谁？",a="你必须将武器交给斯温·约根，他正躲在暮色森林西部的一个营地里，距离西部荒野的边界不远。",al={"斯温在哪里","斯温·约根的位置","交付地点"}},{q="为什么斯温·约根不能亲自对付摩本特·费尔？",a="斯温·约根被迫离开了家园，他的家人和同伴都在森林肆虐的黑暗势力中丧生。在孤立无援且遭到追猎的情况下，他只能依靠联盟中能力出众的勇士来为逝者复仇。",al={"为什么斯温不战斗","斯温·约根的背景故事"}},{q="完成“武装待命”后会发生什么？",a="在收到这把被祝福的武器后，斯温·约根会指派你直接深入乌鸦岭墓地，去面对并击败摩本特·费尔。",al={"what comes next","武装待命后的下一个任务"}},{q="回到斯温营地的最快路线是什么？",a="从西部荒野的哨兵岭向东穿过河流，通常比向西穿越充满恐怖的夜色镇要短得多，也安全得多。",al={"去斯温那里的最快方式","如何快速到达斯温处"}}},fp="15,99,15.277.0,20.301.1,23.110.0,23.121.0,34.100.0,48.170.0,46.116.1,47.153.0"}
P.entries["quest:3261"] = {n="乔恩·星眼",s="乔恩·天视（Jorn Skyseer）是一个部落旅行任务，旨在引导经验丰富的猎人从十字路口向南穿过贫瘠之地，前往陶拉祖营地。在为塞格拉·黑棘（Sergra Darkthorn）证明了他们追踪当地猛禽的技能后，猎人会被派去寻找资深牛头人追踪者乔恩·天视，以获得更深层次的精神和体能指导。",h="乔恩·天视（Jorn Skyseer）是一个部落旅行任务，旨在引导经验丰富的猎人从十字路口向南穿过贫瘠之地，前往陶拉祖营地。在为塞格拉·黑棘（Sergra...",kw={"陶拉祖营地","猎人之道","乔恩·天视","镰爪猛禽","塞格拉·黑棘","贫瘠之地","十字路口"},ang={["class:Hunter"]="这个任务直接将你引向乔恩·天视，他会考验你是否有能力智取并征服中部和南部平原的传奇顶级掠食者。",["faction:Horde"]="这段行程连接了十字路口和陶拉祖营地，引导部落军队更深入地进入贫瘠之地南部充满纷争的领土。",["race:Tauren"]="对于返回南方陶拉祖营地的牛头人来说，这趟旅程将部落的狩猎传统与贫瘠之地荒野的精神守护重新连接了起来。"},sec={{t="传承衣钵",b="在猎杀了潜伏在北部大草原上狡猾的日鳞和镰爪猛禽后，冒险者赢得了十字路口塞格拉·黑棘的尊重。塞格拉深知，纯粹的武技最终必须与对这片土地上伟大野兽的深刻理解相结合，因此她宣布对猎人的指导告一段落，并将其派往南方。"},{t="通往陶拉祖之路",b="沿着漫长的黄金之路向南行进，穿过日益崎岖的平原，便可抵达陶拉祖营地，这是一座坐落在南方荒野附近的重要牛头人定居点。乔恩·天视就在那里等候，这位技艺高超的资深追踪者随时准备教授猎人们如何在贫瘠之地追踪那些难以捉摸的传奇猎物。"}},faq={{q="是谁派我去找乔恩·天视的？",a="驻扎在十字路口的猛禽猎人塞格拉·黑棘，会在你证明了自己对抗当地镰爪猛禽的追踪和狩猎能力后，将你派往那里。",al={"谁给予乔恩·天视任务","谁开启乔恩·天视任务","塞格拉·黑棘任务"}},{q="乔恩·天视在哪里？",a="乔恩·天视驻扎在陶拉祖营地，该营地位于贫瘠之地主干道以南的远方。",al={"乔恩·天视在哪里","乔恩·天视位置","寻找乔恩·天视"}},{q="找到乔恩·天视后会发生什么？",a="当你向他报到后，乔恩会欢迎你踏上猎人之道，并开始引导你追踪和狩猎贫瘠之地南部的各种难以捉摸的野兽，首先就是传奇猛禽伊沙穆哈雷（Ishamuhale）。",al={"乔恩教导什么","乔恩·天视后续","乔恩·天视之后的任务"}},{q="做这个任务需要猎人职业吗？",a="不需要。虽然故事主线围绕着学习平原追踪者的道路和踏上猎人之道展开，但任何完成了塞格拉·黑棘猛禽任务的部落冒险者都可以进行这项任务。",al={"这是猎人专属吗","乔恩·天视职业要求"}},{q="为什么塞格拉不再亲自教导你了？",a="塞格拉·黑棘的工作重点是十字路口附近的北部猛禽巢穴。一旦冒险者掌握了这些狩猎技巧，她就会将他们引荐给南方的乔恩·天视，由他负责监督进入南部区域的更深入的探险。",al={"为什么塞格拉将你送走","塞格拉指导结束"}},{q="什么是陶拉祖营地？",a="陶拉祖营地是位于南贫瘠之地的一个牛头人营地。它是往返于北部平原与莫高雷或千针石林之间的旅客们的狩猎哨所、贸易枢纽和文化中转站。",al={"关于陶拉祖营地","什么是陶拉祖"}}},fp="12,214,18.282.0,19.255.0,29.161.0,30.83.0,41.195.0,48.150.0,42.193.0,21.205.0"}
P.entries["quest:328"] = {n="隐藏的钥匙",s="在博彩商赫洛德的账本装订处藏着一把小铜钥匙，旁边还有关于一个保险箱的笔记。在库尔森的营地后方的洞穴群深处找到这个容器，也许能揭开列兵索尔森是如何被出卖的真相。",h="在博彩商赫洛德的账本装订处藏着一把小铜钥匙，旁边还有关于一个保险箱的笔记。在库尔森的营地后方的洞穴群深处找到这个容器，也许能揭开列兵索尔森是如何被出卖的真相。",kw={"博彩商赫洛德","铜钥匙","库尔森的营地","列兵索尔森","储藏区","荆棘谷","保险箱"},sec={{t="装订里的秘密",b="搜查博彩商赫洛德的账本并没有直接提到列兵索尔森，但却有了其他发现：一本装订好的书里藏着一把小铜钥匙。文书中的碎片提到在库尔森的营地后方的洞穴群——也就是储藏区——里藏着一个保险箱。打开那个容器或许能揭开索尔森的身份是如何暴露的。"},{t="深入储藏区",b="想要找到这个保险箱，必须深入营地后的洞穴系统。这口箱子又重又厚，上面包着铜边，结构坚固，就放在洞穴里堆叠的板条箱中间。"}},faq={{q="这把铜钥匙是从哪里来的？",a="这把小铜钥匙藏在博彩商赫洛德的一本账簿的装订处，是在检查他的文书时发现的。",al={"钥匙在哪里","我怎么拿到的钥匙","小铜钥匙来源"}},{q="博彩商赫洛德的保险箱在哪里？",a="这个保险箱位于储藏区内，也就是库尔森的营地最深处的那个洞穴群。",al={"保险箱位置","保险箱在哪里","箱子在哪里"}},{q="为什么要寻找赫洛德的保险箱？",a="赫洛德的散乱文件没能解释列兵索尔森的行踪是如何泄露的，但它们提到了一个可能藏有答案的保险箱。",al={"为什么要找保险箱","盒子里有什么","保险箱的目的"}},{q="这一步之前发生了什么？",a="这发生在对博彩商赫洛德的调查之后，当时正在搜寻并查阅他的账簿记录。",al={"上一个任务","哪个任务在前"}}},fp="14,246,24.393.0,23.177.0,35.129.0,42.111.0,33.148.0,27.110.0"}
P.entries["quest:3281"] = {n="被偷走的银币",s="“被偷走的银币”是部落在十字路口从加兹罗格处接到的一个任务，旨在取回被迅猛龙偷走的一箱工资银币。在听闻了关于它们诡异狡猾的传言后，旅行者们追踪这些失窃的钱币一直深入到棘齿城南部的迅猛龙巢穴。找回这个保险箱能确保十字路口的守卫们拿到应得的报酬。",h="“被偷走的银币”是部落在十字路口从加兹罗格处接到的一个任务，旨在取回被迅猛龙偷走的一箱工资银币。在听闻了关于它们诡异狡猾的传言后，旅行者们追踪这些失窃的钱币一直深入到棘齿城南部的迅猛龙巢穴。找回这个保险箱能确保十字路口的...",kw={"贫瘠之地","十字路口","加兹罗格","工资","迅猛龙巢穴","迅猛龙窃贼","棘齿城","被偷走的银币"},ang={["class:Hunter"]="贫瘠之地迅猛龙的行为打破了典型的野兽特征，表现出复杂的社会性筑巢行为，以及对人造闪亮货物的不同寻常的吸引力。",["faction:Horde"]="十字路口是部落在卡利姆多的后勤脊梁；保证守卫有薪水和食物对于维持对边境的控制至关重要。"},sec={{t="兽行劫案",b="十字路口是贫瘠之地的交通枢纽，连接着奥格瑞玛、莫高雷和棘齿城。在这片广袤的草原上维持秩序需要保持警惕的守卫，而守卫需要稳定的薪水。当迅猛龙伏击了运送薪水的车队时，加兹罗格最初是想对这些野兽进行报复。但仅仅杀掉兽群并不能平衡定居点的账目，迫使部落不得不调查这些普通的动物究竟是如何以及为何要把沉重的钱箱拖走。"},{t="迅猛龙巢穴",b="侦察兵在棘齿城以南、北方城堡西北方向两座嶙峋的山峰之间发现了一个密集的迅猛龙巢穴。这些生物将完好无损的保险箱直接拖进了它们的筑巢领地，并在巢穴中守卫着它，旁边还有它们的蛋和新鲜的猎物。加兹罗格不得不承认，关于迅猛龙拥有智慧和囤积行为的传言是惊人的准确，因为普通的野兽很少会藏匿金属贵重物品。"}},faq={{q="迅猛龙起初为什么要偷银币？",a="贫瘠之地的迅猛龙以惊人的狡猾和奇特的拾荒习性而闻名。无论是因为受到闪亮的金属吸引、胸箱上经过处理的皮革气味，还是仅仅因为强烈的囤积本能，它们都把完好的保险箱拖回了它们在迅猛龙巢穴的公共巢穴中。",al={"迅猛龙为何要银币","为什么是银币迅猛龙","迅猛龙窃取钱币的动机"}},{q="加兹罗格是谁？",a="加兹罗格是一名驻扎在十字路口主地堡的兽人军官。他负责该哨所的安全和后勤工作，处理来自当地野生动物、半人马入侵和工资发放中断等威胁。",al={"加兹罗格","谁给予被偷走的银币任务","十字路口任务发布者加兹罗格"}},{q="迅猛龙巢穴位于何处？",a="迅猛龙巢穴位于贫瘠之地东部，棘齿城地精港口以南，联盟北方城堡要塞以西北。这些巢穴分布在两座山峰之间的一条崎岖通道内。",al={"迅猛龙巢穴位置","在哪里寻找被偷走的银币","被偷走的银币宝箱位置"}},{q="如果银币无法找回会发生什么？",a="被偷走的银币是十字路口守卫的月薪。如果丢失，哨所的防守者将面临无薪工作，这会动摇在这个不断遭受野猪人、半人马和联盟突袭的堡垒中的士气。",al={"为什么被偷走的银币很重要","十字路口守卫薪水"}},{q="这是长任务链的一部分吗？",a="是的。在搜寻这笔钱之前，冒险者必须先为加兹罗格完成“迅猛龙窃贼”任务，清除掉袭击了最初运输队的贫瘠之地迅猛龙，然后再追踪钱财的具体位置。",al={"被偷走的银币前置任务","迅猛龙窃贼后续"}},{q="联盟参与了这次偷窃吗？",a="没有。虽然北方城堡位于迅猛龙巢穴的东南方，但这次盗窃完全是本地的迅猛龙所为，即使是经验丰富的部落指挥官也对它们这种盗窃和囤积本能感到惊讶。",al={"北方城堡偷了银币吗","联盟 迅猛龙 贫瘠之地"}}},fp="13,185,15.381.0,18.329.0,48.236.0,14.185.0,37.150.0,44.214.0,37.176.0,38.168.0"}
P.entries["quest:329"] = {n="找出内鬼！",s="在赫洛德的保险箱里放着一张潮湿的羊皮纸，上面详细记录了列兵索尔森的日常生活。这封信只留下了一个字母“M”作为署名，暗示着在荆棘谷北部的反抗军营地中混入了一个内奸。这张沾满泥土的字条是写给多伦上尉的。",h="在赫洛德的保险箱里放着一张潮湿的羊皮纸，上面详细记录了列兵索尔森的日常生活。这封信只留下了一个字母“M”作为署名，暗示着在荆棘谷北部的反抗军营地中混入了一个内奸。这张沾满泥土的字条是写给多伦上尉的。",kw={"doren","赫洛德","沾满泥土的字条","反抗军营地","间谍","荆棘谷","保险箱","索尔森","叛徒"},ang={["faction:Alliance"]="揪出荆棘谷的告密者，可以保护联盟反抗军在当地威胁下维持的岌岌可危的据点。"},sec={{t="队伍中的叛徒",b="打开保险箱，不仅发现了值钱的东西，还有一张追踪列兵索尔森行踪的日程表。上面那难以辨认的字迹记录了他的巡逻路线、同伴，以及他在反抗军营地周围的日常活动，最后只签了一个“-M”。如此详尽的观察记录只能来自与索尔森朝夕相处的人，这表明反抗军营地内部出现了叛徒。"},{t="向多伦报告",b="带着这张潮湿的羊皮纸回到反抗军营地，真相就会大白于多伦上尉面前。凭借这张带有签名的字条，指挥官便掌握了搜查潜伏在营地内部的告密者所需的证据。"}},faq={{q="那张沾满泥土的字条上写了什么？",a="字条上包含了一份列兵索尔森的日常作息表。它勾勒出了他的巡逻地点、他交谈的对象，以及他在营地里如何打发时间，最后以字母“-M”结尾。",al={"沾满泥土的字条内容","字条上写了什么","间谍字条细节"}},{q="这张字条是从哪里来的？",a="这张字条是在解锁赫洛德的保险箱后，在箱子里发现的。",al={"去哪里找沾满泥土的字条","揭露间谍任务起始","如何开启揭露间谍任务"}},{q="谁会收到这张字条？",a="这张字条必须交给荆棘谷北部反抗军营地的多伦上尉。",al={"把沾满泥土的字条交给谁","去哪里上交字条","多伦上尉交任务"}},{q="上报字条后接下来该做什么？",a="在报告此事之后，多伦上尉的调查将继续进行，接下来的任务是“巡逻时刻表”。",al={"下一个任务是什么","揭露间谍之后的下一步","揭露间谍之后"}}},fp="17,300,22.373.0,18.227.1,34.205.0,30.116.0,22.96.0,41.88.0"}
P.entries["quest:33"] = {n="林中的群狼",s="“边境的狼群”是Eagan Peltskinner在北郡修道院外发布的一个早期任务。他招募新的冒险者去山谷中猎杀游荡的狼，并收集它们的肉供他自己烹饪。",h="“边境的狼群”是Eagan Peltskinner在北郡修道院外发布的一个早期任务。他招募新的冒险者去山谷中猎杀游荡的狼，并收集它们的肉供他自己烹饪。",kw={"修道院","eagan","艾尔文","肉","北郡","peltskinner","森林狼","狼"},ang={["profession:Cooking"]="Eagan Peltskinner对狼排的渴望向新的冒险者介绍了Azeroth的边境现实：你猎杀的任何东西通常都可以烹饪并食用。",["race:Human"]="在北郡开始旅程的人类新兵会发现，这是他们保卫暴风城直接边境的首批实际任务之一。"},sec={{t="务实的请求",b="当治安官玛克布莱德和暴风城卫兵将有限的人力集中在保卫北郡修道院，抵御Defias强盗时，普通的商人仍有日常需求。Eagan Peltskinner站在修道院围墙边，对当地的森林狼怀有深深的怨恨。与其只是抱怨那些在边境树林里徘徊的野兽，他选择招募路过的新兵来减少它们的数量，并为他的煎锅获取硬狼肉。"},{t="北郡荒野",b="北郡山谷曾经是一片宁静的避难所，被起伏的丘陵和茂密的树林环绕。由于暴风王国因缺乏领导和兵力短缺而感到吃力，幼狼和森林狼等野生捕食者变得更加大胆，在靠近修道院的小径和果园附近徘徊。清除它们不仅能填满Eagan Peltskinner的食品储藏室，还能让修道院附近的道路对新手、工人和新到的保卫者来说更加安全。"}},faq={{q="Eagan Peltskinner是谁？",a="Eagan Peltskinner是北郡修道院入口附近的一位当地猎人和商人。他对该地区的野生森林狼非常厌恶，但却非常乐意烹饪并食用它们的肉。",al={"eagan是谁","peltskinner","eagan peltskinner"}},{q="Eagan Peltskinner为什么要狼肉？",a="Eagan Peltskinner真心喜欢吃狼排。他用实用的初始装备和钱币奖励那些愿意出去为他收集新鲜狼肉的新兵。",al={"为什么需要狼肉","eagan饿了","eagan怎么处理肉"}},{q="狼在哪里？",a="森林狼和幼狼在整个北郡山谷的田野、丘陵和河岸边游荡，特别是在修道院的南部和东部。",al={"狼在哪里","狼群位置","寻找狼群"}},{q="为什么狼在北郡是个问题？",a="由于巡逻减少，加上Defias强盗等威胁对山谷造成的压力，野生动物已经侵入了道路和农场，使得神职人员和工人在没有护送的情况下出行变得危险。",al={"为什么狼在袭击","北郡狼群问题"}},{q="在接这个任务前我需要和谁交谈吗？",a="不需要。虽然维里副队长可能会通过引导任务将新人指引给Eagan Peltskinner，但Eagan Peltskinner会直接向任何在修道院外接近他的人提供这个狩猎任务。",al={"任务前置条件","前置条件","谁发布任务"}},{q="硬狼肉可以用于烹饪配方吗？",a="Eagan Peltskinner打算自己烹饪这些肉，但新手厨师通常会学到，在艾尔文森林采集的狼肉是户外烹饪的基本食材。",al={"硬狼肉烹饪","玩家可以烹饪狼肉吗"}}},fp="24,189,19.323.0,19.318.0,25.158.0,30.109.0,29.128.0,39.151.0,53.160.0,44.149.0"}
P.entries["quest:330"] = {n="巡逻时间表",s="在发现了一封只留有首字母缩写的罪证信息后，多伦上尉试图找出反抗军营地内的叛徒。通过对比值勤名册，值勤记录可以揭示上周是谁与列兵索尔森一起执行巡逻任务。",h="在发现了一封只留有首字母缩写的罪证信息后，多伦上尉试图找出反抗军营地内的叛徒。通过对比值勤名册，值勤记录可以揭示上周是谁与列兵索尔森一起执行巡逻任务。",kw={"塞斯曼下士","库尔森","多伦上尉","巡逻时间表","列兵索尔森","反抗军营地","荆棘谷"},sec={{t="名册中的线索",b="找回的字条上只写着字母M，仅凭这一点很难揭露那个协助库尔森部队的同谋。然而，作者提到在上周一直与列兵索尔森一起执行定期的巡逻任务。多伦上尉让你穿过反抗军营地去和负责维护值勤记录的士兵塞斯曼下士谈谈，以查明是谁和索尔森一起执行任务。"},{t="记录显示的内容",b="查看官方记录证实，在过去的一整周里，列兵默尔被分配了与索尔森完全相同的值勤时间和路线。这一发现揭露了默尔就是向库尔森的人提供情报的告密者。身份一旦暴露，叛徒便逃离营地，向着暮色森林的北部边界逃去。"}},faq={{q="为什么多伦上尉要派你去找塞斯曼下士？",a="塞斯曼下士负责反抗军营地的值勤记录和时间表。因为那封找回的字条提到曾与列兵索尔森一起走过固定的路线，所以塞斯曼的记录可以查明是谁被指派与他一同值勤。",al={"为什么要找塞斯曼谈话","塞斯曼下士的职责","塞斯曼的巡逻时间表"}},{q="在找回的字条中发现了什么线索？",a="信息上只签了字母M，并明确提到其作者在上周与列兵索尔森走过相同的巡逻路线。",al={"字条线索","信件线索","谁在字条上签名"}},{q="这项调查在哪里进行？",a="这项调查完全在荆棘谷北部的反抗军营地内进行，需要在多伦上尉和塞斯曼下士之间往返。",al={"巡逻时间表在哪里","巡逻时间表位置"}},{q="是什么事件引发了这次调查？",a="在“间谍现形！”任务中，你给多伦上尉带去了从赫洛德的贵重物品中发现的泥泞字条，上面只签了一个首字母。",al={"前置任务","巡逻时间表任务的起因"}}},fp="16,279,21.417.0,21.337.1,55.225.0,41.158.0,35.148.0,33.131.0"}
P.entries["quest:3301"] = {n="茉拉·符文图腾",s="这个任务委托一名旅行者将一份来自贫瘠之地的变异的钳嘴龟壳送到银松森林的穆拉·符文图腾手中。它架起了牛头人跨越大陆进行治疗努力的桥梁，将卡利姆多平原那奇异的生命力与被遗忘者凋零的土地联系在了一起。",h="这个任务委托一名旅行者将一份来自贫瘠之地的变异的钳嘴龟壳送到银松森林的穆拉·符文图腾手中。它架起了牛头人跨越大陆进行治疗努力的桥梁，将卡利姆多平原那奇异的生命力与被遗忘者凋零的土地联系在了一起。",kw={"贫瘠之地","穆拉·符文图腾","绿洲","瑟伯切尔","银松森林","钳嘴龟壳","图加·符文图腾"},ang={["class:Druid"]="研究非同寻常的自然复苏——即使是那些源于奇怪变异的复苏——是德鲁伊努力使破碎的大地恢复平衡的核心所在。",["faction:Horde"]="这项任务反映了年轻部落内部日益增长的合作纽带，将卡利姆多的保卫者与洛丹伦被遗忘者的斗争直接联系在了一起。",["race:Tauren"]="这项使命展示了符文图腾氏族对培育自然世界所怀有的深厚奉献精神，他们甚至将治疗之手跨过海洋，伸向了银松森林阴暗枯萎的树林中。",["race:Undead"]="虽然许多人认为被遗忘者的土地早已因腐烂和枯萎而无可救药，但像穆拉·符文图腾这样的牛头人德鲁伊却真诚地寻求让瑟伯切尔周边的森林重焕生机。"},sec={{t="跨海之桥",b="在调查贫瘠之地繁茂绿洲周围那些奇异的、受魔法影响而变异的野生动物时，图加·符文图腾注意到了这些变异的钳嘴龟身上的一些特别之处。尽管它们遭到了腐蚀，但它们的龟壳却散发着充满活力且坚韧的能量。图加认为这种奇异的生命力可以发挥更大的作用，于是请求一名冒险者将龟壳带过无尽之海，交给驻扎在东部王国的族人穆拉·符文图腾。"},{t="援助被遗忘者",b="穆拉·符文图腾居住在瑟伯切尔，这是一个位于银松森林阴森腐烂树林中的被遗忘者哨站。意识到银松森林是一片正在遭受病痛和枯萎的林地，穆拉踏上了艰苦的旅程，来到这里协助部落的新盟友净化并重振他们的家园。她希望龟壳内层的微光以及那顽强、持久的生命火花，能解开复苏这片北方大陆生命力的秘密。"}},faq={{q="穆拉·符文图腾是谁？",a="穆拉·符文图腾是一位牛头人德鲁伊，也是图加·符文图腾的族人。她跨海来到了银松森林，并在瑟伯切尔定居，通过研究如何治愈这片垂死的森林来协助被遗忘者。",al={"穆拉","谁是穆拉","符文图腾 银松森林"}},{q="穆拉·符文图腾在哪里？",a="穆拉·符文图腾驻扎在瑟伯切尔，这是一个位于东部王国大陆银松森林中部路边的被遗忘者城镇。",al={"穆拉位置","穆拉在哪里","寻找穆拉·符文图腾"}},{q="为什么图加想把钳嘴龟壳送到银松森林？",a="在贫瘠之地的绿洲附近收集到的钳嘴龟壳展现出了一种不自然的生命力和内在光芒。图加认为研究这种坚韧的生命力可能会给穆拉提供关于治愈银松森林那片枯萎、垂死的生态环境的见解。",al={"为什么寄送龟壳","钳嘴龟壳的作用","为什么穆拉需要龟壳"}},{q="为什么牛头人要试图治愈被遗忘者的土地？",a="牛头人肩负着培育和修复自然世界的神圣职责。穆拉意识到银松森林正在腐朽枯萎，她希望将大地的治疗传统延伸开来，以协助他们新的部落盟友，并恢复土壤的平衡。",al={"牛头人帮助亡灵","为何治愈银松森林","银松森林的德鲁伊"}},{q="这个任务是如何将贫瘠之地和银松森林联系起来的？",a="它在早期部落领地之间建立起了一条主题和地理上的纽带，派遣冒险者从卡利姆多阳光炙烤的平原前往东部王国的黑暗森林，以运送研究材料。",al={"贫瘠之地到银松森林的任务","跨大陆任务"}},{q="把龟壳交给穆拉之后会发生什么？",a="穆拉对龟壳残留的内在光芒着了迷，并决定对其进行深入研究，以此继续她寻找治愈银松森林枯萎林地方法的长期事业。",al={"穆拉后续","what comes next"}}},fp="14,163,20.330.0,19.321.0,22.198.0,32.121.0,55.219.0,49.234.0,54.129.0,41.146.0"}
P.entries["quest:331"] = {n="向多伦报告",s="在获得巡逻信息后，塞斯曼下士指引你返回多伦上尉处。将这些发现直接带给反抗军在北荆棘谷的指挥官，可以提供至关重要的军事情报。",h="在获得巡逻信息后，塞斯曼下士指引你返回多伦上尉处。将这些发现直接带给反抗军在北荆棘谷的指挥官，可以提供至关重要的军事情报。",kw={"doren","库尔森","巡逻时间表","塞斯曼","荆棘谷"},sec={{t="传递情报",b="塞斯曼下士提醒你，多伦上尉需要直接听取关于巡逻信息的报告。你必须把你所了解的情况带回给多伦。"},{t="叛徒现身",b="出示巡逻信息后，真相大白，原来是梅尔背叛了营地。多伦上尉为失去了一名曾经勇敢忠诚的士兵而感到悲伤，但同时也为能在库尔森上校利用这一点之前就揪出叛徒而感到无比释然。"}},faq={{q="谁指派你去见多伦上尉？",a="在和你一起查看过巡逻时间表后，塞斯曼下士会派你去向多伦上尉汇报。",al={"谁开启了向多伦报告","谁派我去找多伦","向多伦报告任务给予者"}},{q="这份报告之前发生了什么？",a="此任务紧接“巡逻时间表”，在该任务中，塞斯曼下士会为你梳理巡逻时间表。",al={"前置任务","向多伦报告的前置任务是什么","巡逻时间表"}},{q="这份报告是送往哪里的？",a="你要直接将报告送往位于北荆棘谷反抗军营地的多伦上尉处。",al={"多伦上尉在哪里","多伦位置","我该去哪里"}}},fp="15,223,27.146.0,18.265.1,34.111.0,29.96.0,31.101.0"}
